window.KANJI_ETYM = {
"一":{"t":"zeichen","x":"Ein einzelner waagerechter Strich steht für die Zahl eins.","s":2,"i":"obs"},
"二":{"t":"zeichen","x":"Zwei waagerechte Striche übereinander stehen für die Zahl zwei – wie bei 一 und 三 zählt man einfach die Striche.","s":2,"i":"obs"},
"三":{"t":"zeichen","x":"Drei waagerechte Striche stehen für die Zahl drei – man zählt einfach die Striche, wie bei 一 und 二.","s":2,"i":"obs"},
"九":{"t":"leih","x":"Das Zeichen zeigte ursprünglich einen Arm mit deutlich hervorgehobenem Ellbogen und bedeutete „Ellbogen“ (heute 肘). Weil das Wort ähnlich klang, lieh man es für „neun“ aus.","s":2,"n":"Ältere Erklärungen deuten 九 als Drache oder als „die Zahlen bis zum Ende zusammenfassen“. Diese Deutungen gelten heute als unbegründet.","i":"obs"},
"七":{"t":"leih","x":"Ursprünglich ein Kreuz: ein Strich, der in der Mitte durchgeschnitten wird. Es stand für „schneiden“ (heute 切). Weil das Wort ähnlich klang, lieh man das Zeichen für „sieben“ aus.","s":2,"i":"obs"},
"八":{"t":"leih","x":"Zwei Linien, die sich voneinander wegbiegen, standen für „teilen, trennen“ (heute 分 bzw. 別). Wegen des ähnlichen Klangs wurde das Zeichen für „acht“ ausgeliehen; die alte Bedeutung ging verloren.","s":2,"n":"In Zeichen wie 共, 具 oder 兵 hat der untere Teil, der wie 八 aussieht, nichts damit zu tun: dort sind es zwei Hände.","i":"obs"},
"十":{"t":"zeichen","x":"Auf Orakelknochen war zehn meist nur ein senkrechter Strich – gleichsam eine aufgestellte 一 als nächste Zählstufe. Später kam in der Mitte ein Punkt dazu, der zu einem Querstrich wurde; so entstand das Kreuz.","s":1,"n":"Manchmal liest man, 十 sei ursprünglich das Bild einer Nadel. Diese Deutung gilt heute als wenig überzeugend.","i":"obs"},
"上":{"t":"zeichen","x":"Eine kurze Markierung über einer längeren Grundlinie zeigt „oben“. Das Gegenstück ist 下 mit der Markierung darunter. Später nutzte man das Zeichen auch für „hinaufgehen, heben“.","s":2,"p":[["一","Grundlinie","b"],["⺊","Markierung","f"]],"i":"obs"},
"下":{"t":"zeichen","x":"Eine kurze Markierung unter einer längeren Grundlinie zeigt „unten“. Das Gegenstück ist 上 mit der Markierung darüber. Später nutzte man das Zeichen auch für „hinuntergehen“.","s":2,"p":[["一","Grundlinie","b"],["卜","Markierung","f"]],"n":"Der untere Teil sieht heute wie 卜 (wahrsagen) aus, ist aber nur die umgeformte Markierung.","i":"obs"},
"人":{"t":"bild","x":"Ein stehender Mensch von der Seite gesehen: ein Arm und ein Bein sind zu erkennen. Links in Zeichen erscheint 人 oft als schmale Form 亻.","s":2,"i":"obs"},
"入":{"t":"unklar","x":"Die Form ist eine Spitze wie ⋀ oder eine Pfeilspitze. Ob sie einen Eingang zeigt oder ein Zeichen für „hineingehen“ ist, ist nicht geklärt. Wahrscheinlich stand es zuerst für „innen“ (内) und wurde dann für „eintreten“ verwendet.","s":0,"n":"入 sieht 人 ähnlich, hat aber keine Verbindung zu ihm.","i":"obs"},
"大":{"t":"bild","x":"Ein erwachsener Mensch, der von vorn gesehen aufrecht steht. Daraus wurde „groß“. Zum Vergleich: 人 zeigt den Menschen von der Seite.","s":2,"n":"Oft liest man, 大 sei ein Mensch mit weit ausgebreiteten Armen. Die alten Schriftformen zeigen aber keine ausgestreckten Arme, nur die Vorderansicht.","i":"obs"},
"女":{"t":"bild","x":"Eine kniende Frau mit vor dem Körper verschränkten Armen. Die heutige Form ist stark vereinfacht und gegenüber der ältesten Form gespiegelt.","s":2,"n":"Die Schlaufe im heutigen Zeichen ist der Rest eines Arms; der zweite Arm ist bei der Vereinfachung verschwunden.","i":"obs"},
"山":{"t":"bild","x":"Drei Berggipfel nebeneinander. Auf Orakelknochen waren die Gipfel noch Dreiecke, später wurden daraus senkrechte Striche.","s":2,"i":"obs"},
"川":{"t":"bild","x":"Fließendes Wasser zwischen zwei Ufern: Die äußeren Striche sind die Ufer, der mittlere ist die Strömung.","s":2,"i":"obs"},
"土":{"t":"bild","x":"Ein Erdklumpen auf dem Boden. Später wurde der Klumpen oben und unten spitz und in der Mitte zu einem Querstrich – so entstand das Kreuz über der Bodenlinie. Auf Orakelknochen konnte das Zeichen auch den Erdgott meinen (vgl. 社).","s":2,"i":"obs"},
"千":{"t":"laut","x":"一 gibt die Zahl an, 人 (Mensch) liefert den Klang: Im Altchinesischen klangen „Mensch“ und „tausend“ ähnlich. Im Japanischen (ジン/セン) ist die Ähnlichkeit nicht mehr zu hören.","s":2,"p":[["一","eins","b"],["人","Mensch","l"]],"n":"Oft liest man, der Strich über 人 bedeute eine „Verlängerung“ des Zählens bis tausend. Die heutige Forschung sieht 千 als Zahl + Klangteil.","i":"obs"},
"子":{"t":"bild","x":"Ein Säugling mit großem Kopf und ausgebreiteten Armen; die Beine sind in ein Tuch gewickelt, daher nur ein Strich nach unten.","s":2,"i":"obs"},
"小":{"t":"bild","x":"Drei kleine Punkte oder Sandkörner stehen für etwas Winziges, daraus „klein“. Lange wurde dasselbe Zeichen auch für „wenig“ (少) und „Sand“ (沙) verwendet; erst später trennte man die Schreibungen.","s":1,"n":"Eine alte Erklärung (Shuowen) zerlegt 小 in 八 „teilen“ + einen Strich. Sie stützt sich auf die späte Siegelschrift; die ältesten Formen zeigen einfach drei Punkte.","i":"obs"},
"中":{"t":"zeichen","x":"Ein senkrechter Strich, in der Mitte mit einem Kreis markiert: Das zeigt die Mitte. Der Kreis ist heute zum Kästchen 口 geworden.","s":0,"p":[["口","Kreis","f"],["丨","senkrechter Strich","b"]],"n":"Oft liest man, 中 sei ein Fahnenmast mit Trommel in der Mitte eines Platzes. Diese Deutung beruht auf einer verwandten Form mit Fahnen (𠁩), die nach anderer Ansicht ein eigenes Zeichen war.","i":"obs"},
"五":{"t":"leih","x":"Die alte Form ist ein Kreuz ㄨ zwischen zwei waagerechten Strichen. Was sie ursprünglich zeigte, ist umstritten – vielleicht ein Gerät zum Aufwickeln von Seil. Wegen des Klangs wurde das Zeichen für „fünf“ ausgeliehen.","s":0,"n":"Eine zweite Deutung: Die Urform war nur ㄨ, zwei gekreuzte Linien für „sich kreuzen“ (互); die beiden Querstriche kamen später dazu.","i":"obs"},
"六":{"t":"leih","x":"Was das Zeichen ursprünglich zeigte, ist unklar – vielleicht eine einfache Behausung wie eine Hütte oder Höhlenwohnung, vielleicht auch ein altes Zählzeichen. Sicher ist nur: Wegen des ähnlichen Klangs wurde es für „sechs“ ausgeliehen.","s":0,"i":"obs"},
"円":{"t":"laut","x":"Alte Form 圓: Die Umrandung 囗 gibt den Sinn „rund“, 員 den Klang. 員 selbst bedeutete zuerst „Kreis“, bekam aber 囗 dazu. Im heutigen 円 wurde 員 zu einem Strich verkürzt und die Unterkante von 囗 rutschte nach oben.","s":2,"p":[["囗","Umrandung","b"],["員","Mitglied","l"]],"a":"圓","i":"s"},
"天":{"t":"bild","x":"Ein Mensch von vorn (大) mit besonders betontem Kopf. Ursprünglich hieß das Zeichen „Kopf, Scheitel“; daraus wurde „das, was oben ist“ und schließlich „Himmel“.","s":1,"p":[["一","Kopf","f"],["大","Mensch","b"]],"n":"Oft liest man, 天 sei 一 + 大, „das Eine über dem Großen“. Die Orakelknochenformen zeigen aber, dass der obere Teil der Kopf des Menschen ist.","i":"obs"},
"日":{"t":"bild","x":"Die Sonne als Kreis. Der Punkt bzw. Strich in der Mitte wurde eingefügt, damit man das Zeichen nicht mit ähnlichen Formen wie 口 verwechselt.","s":2,"i":"obs"},
"月":{"t":"bild","x":"Bild einer Mondsichel. Anfangs wurden 月 und 夕 gleich geschrieben; erst ab der Westlichen Zhou-Zeit stand 月 für „Mond“ und 夕 für „Abend“.","s":2,"n":"Als Bauteil in anderen Kanji ist 月 oft gar nicht der Mond: in 有 oder 祭 steht es für Fleisch, in 前 für ein Boot, in 青 ist es ein verformter Klangteil.","i":"obs"},
"木":{"t":"bild","x":"Bild eines Baumes: oben die Äste, unten die Wurzeln, in der Mitte der Stamm. In den alten Formen sind Äste und Wurzeln noch deutlich zu sehen.","s":2,"n":"Mit einem Zusatzstrich entstehen daraus 本 (Markierung unten an der Wurzel) und 末 (Markierung oben an der Spitze).","i":"obs"},
"水":{"t":"bild","x":"Bild von fließendem Wasser: in der Mitte der Strom, an den Seiten Tropfen oder Nebenströme. Links in einem Kanji wird es zu 氵 zusammengedrückt.","s":2,"n":"氵 (drei Tropfen, Wasser) nicht mit 冫 (zwei Striche, Eis/Kälte) verwechseln – die beiden haben nichts miteinander zu tun.","i":"obs"},
"火":{"t":"bild","x":"Bild von lodernden Flammen. Unten in einem Kanji wird es oft zu den vier Punkten 灬 (z. B. in 熱 oder 照); in 灸 steht es noch in voller Form unten.","s":2,"n":"Nicht jedes 灬 ist Feuer: In 黒 oder 魚 sind die Punkte aus ganz anderen Bildteilen entstanden.","i":"obs"},
"出":{"t":"kombi","x":"Ursprünglich ein Fuß (止), der aus einer Grube oder Höhle (凵) heraustritt – also „hinausgehen“. Die heutige Form ist so stark verändert, dass man den Fuß nicht mehr erkennt.","s":2,"p":[["止","Fuß","b"],["凵","Grube, Höhle","b"]],"n":"Oft liest man „zwei Berge übereinander“ oder (so schon das alte Wörterbuch Shuowen) „eine Pflanze, die aus dem Boden sprießt“. Das beruht auf der schon verformten späteren Schreibweise.","i":"obs"},
"右":{"t":"bild","x":"Ursprünglich nur eine rechte Hand (又), die auch „rechts“ bedeutete. In Bronzeinschriften kam 口 dazu – nicht als „Mund“, sondern nur als Unterscheidungszeichen. Der obere Teil ist die umgeformte Hand.","s":1,"p":[["𠂇","rechte Hand","b"],["口","Zusatz ohne Bedeutung","f"]],"n":"Oft liest man „die Hand, die Essen zum Mund führt“. 口 hat hier aber keine Bedeutung; es diente nur dazu, das Zeichen von 又 abzuheben.","i":"obs"},
"四":{"t":"leih","x":"Ursprünglich ein Bild für Atem, der aus der Nase strömt (später 呬 geschrieben). Wegen des gleichen Klangs wurde es für das Wort „vier“ ausgeliehen.","s":2,"n":"Vorher schrieb man „vier“ einfach mit vier waagerechten Strichen (亖). Das ließ sich leicht mit 二 und 三 verwechseln, darum setzte sich 四 durch, endgültig in der Qin-Zeit.","i":"obs"},
"左":{"t":"bild","x":"Ursprünglich nur eine linke Hand (𠂇), das Gegenstück zur rechten Hand 又. Später kam 工 dazu; der obere Teil ist die umgeformte Hand.","s":1,"p":[["𠂇","linke Hand","b"],["工","Zusatz","f"]],"n":"Ob 工 eine Bedeutung trägt, ist umstritten: Japanische Forschung sieht darin nur ein Zierzeichen, andere deuten es als „Arbeit, helfen“ – dann wäre 左 die alte Form von 佐 (helfen).","i":"obs"},
"本":{"t":"zeichen","x":"Ein Baum (木), bei dem unten an der Wurzel ein Strich als Markierung steht. Das Zeichen bedeutete „Wurzel“, daraus „Ursprung, Grundlage“; „Buch“ ist eine spätere Bedeutung.","s":2,"p":[["木","Baum","b"],["一","Markierung","f"]],"n":"Gegenstück: 末 hat die Markierung oben an der Spitze und bedeutet „Ende, Spitze“.","i":"bs"},
"白":{"t":"unklar","x":"Ein altes Bildzeichen, dessen Vorlage nicht sicher bekannt ist. Vorgeschlagen werden u. a. eine Eichel oder ein Kopf. Für das Wort „weiß“ wurde es wohl nur ausgeliehen.","s":0,"n":"Oft liest man „ein Daumennagel“ oder „Sonne mit Lichtstrahl“. Die Daumen-Deutung gilt als widerlegt, und auch die Zerlegung des alten Wörterbuchs Shuowen in 入 und 二 passt nicht zu den ältesten Formen.","i":"obs"},
"万":{"t":"leih","x":"Die alte Form 萬 zeigte einen Skorpion. Wegen des ähnlichen Klangs wurde es für „zehntausend“ ausgeliehen. 万 ist eine Kurzform, beeinflusst von der Schreibschrift von 萬 und dem Zeichen 丏.","s":1,"n":"Früher hieß es, 万 komme vom Hakenkreuz-Symbol 卍 – das gilt als falsch. Ein Zeichen 万 gab es schon auf Orakelknochen, dort als Stammesname; was es zeigte, ist unklar.","a":"萬","i":"obs"},
"今":{"t":"leih","x":"Ein auf den Kopf gestelltes 曰 (sprechender Mund) – also ein geschlossener Mund, „schweigen“ (später 噤). Wegen des Klangs wurde es für „jetzt“ ausgeliehen.","s":1,"p":[["亼","umgedrehter Mund","b"]],"n":"Oft liest man „ein Deckel über etwas“. Nach den Orakelknochen-Formen ist das falsch. Eine andere Deutung: etwas im Mund halten (vgl. 含).","i":"obs"},
"午":{"t":"leih","x":"Bild eines Stößels (später 杵 geschrieben). Ausgeliehen für das 7. Zeichen der zwölf Tierkreiszeichen, das Pferd; die Stunde des Pferdes (11–13 Uhr) ergab „Mittag“.","s":2,"n":"Hat nichts mit 干 zu tun, auch wenn es ähnlich aussieht.","i":"obs"},
"友":{"t":"laut","x":"Zwei rechte Hände (又) nebeneinander; die obere ist heute zu 𠂇 umgeformt. Nach heutiger Forschung ist 又 hier vor allem der Klangteil: 又 ユウ → 友 ユウ. Das Wort bedeutete „einander helfen, nahestehen“.","s":1,"p":[["𠂇","Hand (又)","l"],["又","Hand","l"]],"n":"Oft liest man „zwei Hände, die sich gegenseitig helfen = Freunde“ (so schon das alte Wörterbuch Shuowen). Das passt zur Bedeutung, die heutige Forschung sieht die Hände aber vor allem als Klangträger.","i":"obs"},
"父":{"t":"bild","x":"Eine Hand, die etwas hält – nach verbreiteter Deutung ein Steinbeil. Gemeint ist der Mann, der mit dem Werkzeug arbeitet; daraus „Vater“.","s":1,"n":"Japanische Forschung sieht es anders: Das Zeichen bedeutete „greifen, halten“ (später 把) und wurde für das gleich klingende Wort „Vater“ nur ausgeliehen.","i":"obs"},
"北":{"t":"leih","x":"Zwei Menschen, die sich den Rücken zukehren. Das Zeichen bedeutete „Rücken, sich abwenden“ (heute 背). Für das ähnlich klingende Wort „Norden“ wurde es ausgeliehen.","s":2,"p":[["匕","Mensch (abgewandt)","b"]],"n":"Für „Rücken“ bekam das Zeichen später 月 (Körper) dazu: 背. Beide Hälften von 北 waren ursprünglich je ein Mensch.","i":"obs"},
"半":{"t":"kombi","x":"Oben 八 (teilen, auseinander), darunter 牛 (Rind): ein Rind wird in zwei Hälften geteilt. In der heutigen Form sind beide Teile zusammengewachsen.","s":2,"p":[["丷","teilen (八)","b"],["牛","Rind","b"]],"i":"b"},
"外":{"t":"laut","x":"Der rechte Teil war ursprünglich ein Hinweiszeichen: ein senkrechter Strich mit einer Markierung außen, also „außen“. Dazu kam 夕 (damals = 月) als Klangteil: 月 ガツ → 外 ガイ.","s":1,"p":[["夕","Mond, Abend","l"],["卜","Strich mit Marke außen","b"]],"n":"Oft liest man „Wahrsagen (卜) am Abend (夕)“. Der rechte Teil hat aber nichts mit 卜 (Wahrsagen) zu tun, er sieht nur so aus.","i":"obs"},
"母":{"t":"bild","x":"Ursprünglich dasselbe Zeichen wie 女 (kniende Frau). Um „Mutter“ von „Frau“ zu unterscheiden, kamen zwei Punkte dazu.","s":2,"p":[["女","Frau","b"],["丶","Unterscheidungspunkte","f"]],"n":"Oft liest man, die beiden Punkte seien Brüste. Die Forschung sieht darin nur Unterscheidungszeichen – genauso wurden z. B. 月 und 夕 getrennt.","i":"obs"},
"休":{"t":"kombi","x":"Ein Mensch (亻) unter einem Baum (木). Das Zeichen stand zuerst für den Schatten, den ein Baum spendet, und für „schützen“; die Bedeutung „sich ausruhen“ kam erst später dazu.","s":1,"p":[["亻","Mensch","b"],["木","Baum","b"]],"n":"Oft liest man „ein Mensch ruht sich am Baum aus“. In den ältesten Texten bedeutet das Zeichen aber noch nicht „ausruhen“, sondern „Schatten spenden, beschützen“.","i":"obs"},
"先":{"t":"kombi","x":"Ein Fuß (止, oben verformt) über einem Menschen (儿): der Fuß geht dem Menschen voraus. Daraus „voraus, vorher“.","s":2,"p":[["𠂒","Fuß (止)","b"],["儿","Mensch","b"]],"i":"obs"},
"名":{"t":"unklar","x":"Aus 夕 (Mondsichel, Abend) und 口. Die alte Erklärung: Im Dunkeln sieht man niemanden, also nennt man seinen Namen. Wie das Zeichen wirklich entstand, ist umstritten.","s":0,"p":[["夕","Mond, Abend","b"],["口","Mund","b"]],"n":"Neuere Vorschläge: 口 schrieb früher auch „Name“, und 夕 kam als Klangteil dazu; oder 口 ist nur Zierzeichen und das Zeichen bedeutete „dunkel“ (冥), bevor es für „Name“ ausgeliehen wurde.","i":"obs"},
"年":{"t":"laut","x":"Ursprünglich 禾 (Getreide) über 人 als Klangteil: 人 ニン → 年 ネン. Es bedeutete „Ernte“, daraus „Jahr“. 人 wurde später zu 千, und beim Umschreiben in die Kanzleischrift verschmolz alles zur heutigen Form.","s":2,"p":[["禾","Getreide","b"],["人","Mensch","l"]],"n":"Oft liest man „ein Mensch trägt Getreide auf dem Rücken“. Die Forschung sieht 人 hier als Klangteil, nicht als Bildteil.","i":"obs"},
"気":{"t":"laut","x":"Die alte Form 氣: 米 (Reis) als Sinnteil, 气 als Klangteil (气 キ → 氣 キ). Es bedeutete „Essen schenken“ und wurde dann für „Dampf, Luft“ ausgeliehen. In 気 ist 米 zu 㐅 verkürzt.","s":2,"p":[["气","Dampf, Luft","l"],["米","Reis","b"],["㐅","Kürzel für 米","f"]],"a":"氣","i":"s"},
"百":{"t":"laut","x":"一 (eins, Zahl) als Sinnteil, 白 als Klangteil: 白 ハク → 百 ヒャク. Gemeint ist „(ein) Hundert“.","s":2,"p":[["一","eins","b"],["白","weiß","l"]],"i":"obs"},
"男":{"t":"kombi","x":"Ein Feld 田 und darunter 力, das ursprünglich ein Gerät zum Umgraben zeigt. Zusammen: das Feld bestellen – die schwere Feldarbeit galt als Sache der Männer, daher „Mann“.","s":1,"p":[["田","Feld","b"],["力","Pflug, Kraft","b"]],"i":"obs"},
"見":{"t":"kombi","x":"Ein kniender Mensch, dessen Kopf als großes Auge 目 gezeichnet ist: jemand, der schaut. Unten ist vom Menschen nur noch 儿 (die Beine) übrig.","s":2,"p":[["目","Auge","b"],["儿","Mensch (Beine)","b"]],"i":"obs"},
"車":{"t":"bild","x":"Ein Wagen von oben gesehen: auf den Orakelknochen zwei große Räder an einer Achse und eine Deichsel nach vorn. Heute ist davon nur noch ein Rad (日-artig) auf der Achse übrig.","s":2,"i":"obs"},
"毎":{"t":"leih","x":"Die alte Form 每 ist 母 (Frau) mit einem Schmuckzeichen oben, vielleicht einer Haarnadel. Das Zeichen wurde für das ähnlich klingende Wort „jeder“ ausgeliehen. Im heutigen 毎 sind die zwei Punkte von 母 zu einem Strich verbunden.","s":1,"p":[["𠂉","Haarschmuck","f"],["母","Mutter, Frau","b"]],"n":"Der Shuowen sah oben einen Spross 屮 und in 母 einen Klangteil. Die Forschung hält das für falsch: Es ist 母 mit zusätzlichem Strich.","a":"每","i":"obs"},
"行":{"t":"leih","x":"Bild einer Straßenkreuzung, ursprünglich für „Weg“. Später wurde es für „gehen“ und „handeln, tun“ ausgeliehen.","s":2,"n":"Heute sieht es aus wie 彳 + 亍, war aber ursprünglich ein einziges, symmetrisches Bild der Kreuzung.","i":"obs"},
"西":{"t":"leih","x":"Die ältesten Formen werden als Vogelnest gedeutet (verwandt mit 栖 „nisten“). Das Zeichen wurde für das gleich klingende Wort „Westen“ ausgeliehen.","s":1,"n":"Spätere geschlossene Formen könnten mit 囟 zusammenhängen; das Nest gilt nur für die frühesten offenen Formen als gut belegt.","i":"obs"},
"何":{"t":"leih","x":"Auf Orakelknochen ein Mensch, der etwas auf der Schulter trägt – Urform von 荷 „tragen“. Später schrieb man es als 亻 + Klangteil 可 (可 カ → 何 カ). Ausgeliehen wurde es für das Fragewort „was“.","s":2,"p":[["亻","Mensch","b"],["可","können, erlaubt","l"]],"i":"obs"},
"来":{"t":"leih","x":"Die alte Form 來 ist ein Bild einer Weizenpflanze mit Ähre, Blättern und Wurzeln. Schon auf Orakelknochen wurde es für „kommen“ ausgeliehen; für „Weizen“ nahm man dann 麦/麥. Im heutigen 来 sind die zwei kleinen 人 zu kurzen Strichen geworden.","s":2,"a":"來","i":"obs"},
"学":{"t":"laut","x":"Die alte Form 學: oben 𦥯 aus zwei Händen, gekreuzten Zählstäbchen 爻 und einem Gebäude – ein Haus, in dem geübt und gelernt wird. Dieser Teil schrieb das Wort schon allein und gibt den Klang. Später kam 子 „Kind“ dazu. In 学 ist der obere Teil zu ⺍ + 冖 verkürzt.","s":1,"p":[["𦥯","lernen (alte Schreibung)","l"],["子","Kind","b"]],"a":"學","i":"obs"},
"金":{"t":"laut","x":"Oben gibt 今 den Klang (今 キン → 金 キン). Die zwei Punkte stehen für Metallstücke; der untere Teil war ursprünglich 火 „Feuer“ und ist zu einer 王-artigen Form verschliffen. Das Wort meinte zuerst Kupfer, dann Metall allgemein, später Gold.","s":1,"p":[["今","jetzt","l"],["丷","Metallstücke","b"],["王","aus 火 Feuer","f"]],"n":"Oft liest man nach dem Shuowen: Metallkörner in der Erde 土. Die ältesten Formen zeigen aber keine Erde.","i":"bs"},
"雨":{"t":"bild","x":"Eine Wolke bzw. der Himmel, aus dem Regentropfen fallen. Der waagrechte Strich oben kam erst später dazu.","s":2,"i":"obs"},
"国":{"t":"laut","x":"Die alte Form 國: die Umgrenzung 囗 zeigt den Sinnbereich „Gebiet, Land“, 或 im Inneren gibt den Klang. In der heutigen Kurzform 国 wurde 或 durch 玉 „Jade“ ersetzt.","s":2,"p":[["囗","Umgrenzung","b"],["或","Klangteil (alte Form)","l"],["玉","Jade (Kurzform)","f"]],"a":"國","i":"bs"},
"東":{"t":"leih","x":"Bild eines vollen Sacks, der an beiden Enden zugebunden ist. Das Zeichen wurde für das ähnlich klingende Wort „Osten“ ausgeliehen.","s":2,"n":"Oft liest man: die Sonne 日 geht hinter einem Baum 木 auf. Das stammt aus dem Shuowen und passt nicht zu den ältesten Formen – heute gilt es als Volksetymologie.","i":"obs"},
"長":{"t":"leih","x":"Bild eines alten Menschen mit langen Augenbrauen; das Wort meinte zuerst „der Ältere“ (daher auch „Leiter, Oberhaupt“). Für „lang“ wurde das Zeichen ausgeliehen.","s":1,"n":"Oft liest man: ein Greis mit langen Haaren. Der Vergleich mit 老 und 髟 spricht aber eher für lange Augenbrauen.","i":"obs"},
"前":{"t":"laut","x":"歬 zeigt einen Fuß 止 auf einem Boot 舟 – vorwärtskommen. Mit dem Messer 刂 entstand ein Zeichen für „schneiden“ (heute 剪), das dann für „vorne, vorher“ benutzt wurde. Fuß und Boot wurden zu 䒑 und 月 verkürzt.","s":1,"p":[["歬","vorwärts (heute 䒑 + 月)","l"],["刂","Messer","b"]],"i":"bs"},
"南":{"t":"leih","x":"Auf Orakelknochen ein zylindrisches Gefäß mit Deckel, manchmal mit Inhalt; es stand wohl für eine Fleischsoße oder einen Eintopf. Ausgeliehen wurde es für das ähnlich klingende Wort „Süden“.","s":1,"n":"Oft liest man, es zeige eine Glocke oder ein Musikinstrument. Das passt nicht zu den ältesten Formen.","i":"obs"},
"後":{"t":"kombi","x":"Aufgebaut aus 幺 „Faden“ und 夊 „Fuß“; 彳 „gehen“ kam später dazu. Eine verbreitete Deutung: ein mit einer Schnur gefesselter Fuß kommt nicht voran und bleibt zurück – daher „hinten, später“.","s":0,"p":[["彳","gehen, Weg","b"],["幺","Faden","b"],["夊","Fuß","b"]],"n":"Die Bauteile sind sicher, ihr ursprünglicher Sinn aber nicht: Es gibt mehrere Vorschläge und keine allgemein anerkannte Deutung.","i":"obs"},
"食":{"t":"kombi","x":"Oben ein nach unten gerichteter Mund 亼, unten eine Schale mit Essen auf einem Fuß 皀. Zusammen: essen. Die Schale sieht heute ähnlich wie 良 aus, hat damit aber nichts zu tun.","s":2,"p":[["亼","Mund (umgedreht)","b"],["良","aus 皀 Speiseschale","f"]],"n":"Manchmal wird 亼 als Deckel des Gefäßes gedeutet. Auf Orakelknochen werden Deckel aber anders gezeichnet; 亼 ist ein umgedrehtes 口.","i":"obs"},
"校":{"t":"laut","x":"木 „Holz“ gibt den Sinnbereich, 交 den Klang (交 コウ → 校 コウ). Gemeint war zuerst ein hölzernes Gerät (eine Art Fessel); für „Schule“ wurde das Zeichen ausgeliehen.","s":1,"p":[["木","Baum, Holz","b"],["交","kreuzen","l"]],"i":"s"},
"時":{"t":"laut","x":"日 „Sonne, Tag“ gibt den Sinnbereich Zeit, 寺 den Klang (寺 ジ → 時 ジ). Früher schrieb man 旹 mit 之 als Klangteil; erst später trat 寺 an dessen Stelle.","s":2,"p":[["日","Sonne, Tag","b"],["寺","Tempel","l"]],"n":"Manche deuten 寺 zusätzlich als Sinnteil. Die Forschung sieht es hier nur als Klangteil.","i":"os"},
"高":{"t":"bild","x":"Ein hohes Gebäude, etwa ein Wachturm. Ursprünglich glich es 京; zur Unterscheidung kam in der Mitte ein 口 dazu.","s":2,"i":"obs"},
"間":{"t":"kombi","x":"Nebenform von 閒: ein Tor 門, durch dessen Spalt der Mond 月 scheint – „Lücke, Zwischenraum“. In 間 wurde der Mond durch die Sonne 日 ersetzt. Von der räumlichen Lücke kam die Bedeutung „Zeitraum“.","s":2,"p":[["門","Tor","b"],["日","Sonne (früher 月 Mond)","b"]],"i":"bs"},
"話":{"t":"laut","x":"訁 „Wort, sprechen“ gibt den Sinnbereich. Rechts steht eigentlich 𠯑, das nur den Klang beisteuert und heute genau wie 舌 aussieht.","s":2,"p":[["訁","Wort, sprechen","b"],["舌","Klangteil 𠯑","l"]],"n":"Oft liest man: Worte 言 + Zunge 舌 = sprechen. Der rechte Teil ist aber nicht „Zunge“, sondern ein anderes Zeichen (𠯑), das nur gleich aussieht.","i":"s"},
"電":{"t":"laut","x":"申 war ursprünglich selbst das Zeichen für „Blitz“; später kam 雨 „Regen, Wetter“ dazu, und 申 blieb als Klangteil. Aus „Blitz“ wurde in der Neuzeit „Elektrizität“.","s":2,"p":[["⻗","Regen","b"],["申","Blitz","l"]],"n":"Im heutigen 電 endet der senkrechte Strich von 申 unten mit einem Haken (乚).","i":"b"},
"聞":{"t":"laut","x":"耳 „Ohr“ gibt den Sinnbereich, 門 den Klang (門 モン → 聞 モン). Auf Orakelknochen war es noch ein kniender Mensch mit betontem Ohr; später ersetzte man das durch Ohr + Klangteil 門.","s":2,"p":[["門","Tor","l"],["耳","Ohr","b"]]},
"語":{"t":"laut","x":"訁 (Sprache, Reden) gibt den Sinnbereich an, 吾 liefert den Klang: 吾 ゴ → 語 ゴ. Gemeint war ursprünglich das Reden, das sich an ein Gegenüber richtet – also „sich unterhalten, erzählen“; daraus wurde „Wort, Sprache“.","s":2,"p":[["訁","sprechen","b"],["吾","ich","l"]],"n":"Schon alte chinesische Wörterbücher unterscheiden: 言 ist das Sprechen an sich, 語 das Gespräch oder Streitgespräch mit jemandem.","i":"s"},
"読":{"t":"laut","x":"Alte Form 讀: 言 (sprechen) gibt den Sinnbereich „vorlesen, laut lesen“ an, der rechte Teil liefert den Klang. Japan hat 讀 aus der Schreibschrift zu 読 verkürzt – nach demselben Muster, mit dem 賣 zu 売 wurde.","s":1,"p":[["訁","sprechen","b"],["売","Klangteil (Form)","l"]],"n":"Der rechte Teil von 讀 sah aus wie 賣 („verkaufen“), war aber ursprünglich ein anderes, ähnlich geschriebenes Zeichen (𧶠). Mit „verkaufen“ hat 読 also nichts zu tun.","a":"讀","i":"s"},
"生":{"t":"bild","x":"Eine junge Pflanze, die aus dem Boden sprießt: oben der Spross, unten ein Strich für die Erde. Daraus entstanden „wachsen, entstehen, geboren werden, leben“.","s":2,"n":"Der untere Teil sieht heute wie 土 (Erde) aus, ist aber nur der Bodenstrich unter dem Spross, nicht das Zeichen 土.","i":"obs"},
"書":{"t":"laut","x":"Oben 聿: eine Hand, die einen Schreibpinsel hält – der Sinnteil „schreiben“. Unten stand ursprünglich 者 als Klangteil (者 シャ → 書 ショ); er ist in der heutigen Form zu 曰 zusammengeschrumpft.","s":2,"p":[["聿","Schreibpinsel","b"],["者","Person","l"]],"i":"bs"},
"力":{"t":"leih","x":"Die Orakelknochenformen zeigen ein Grabgerät zum Umbrechen der Erde, eine Art Pflug oder Spaten. Das Zeichen wurde dann für das ähnlich klingende Wort „Kraft“ ausgeliehen.","s":1,"n":"Oft liest man, 力 zeige einen angespannten Arm. Diese Deutung stützt sich auf spätere Bronzeformen, die der Hand 又 ähneln; die ältesten Formen zeigen aber das Ackergerät.","i":"obs"},
"口":{"t":"bild","x":"Ein geöffneter Mund. Daraus „Mund“ und allgemein „Öffnung, Eingang“.","s":2,"n":"In vielen anderen Zeichen steht 口 gar nicht für den Mund, sondern nur als Markierung, die ein Zeichen von einem ähnlichen unterscheidet (z. B. 右 aus 又 „rechte Hand“).","i":"obs"},
"工":{"t":"bild","x":"Ein Werkzeug – entweder ein Gerät mit Klinge zum Bearbeiten des Bodens oder ein Winkelmaß der Zimmerleute. Daraus „Handwerk, Fertigkeit, Arbeit“.","s":0,"n":"Welches Werkzeug gemeint ist, ist nicht geklärt; es gibt keine allgemein anerkannte Deutung.","i":"obs"},
"夕":{"t":"bild","x":"Eine Mondsichel. Anfangs waren 月 (Mond) und 夕 dasselbe Zeichen; erst ab der Westlichen Zhou-Zeit stand 月 für „Mond“ und 夕 für „Abend, Nacht“.","s":2,"i":"obs"},
"手":{"t":"bild","x":"Eine Hand mit fünf Fingern: der oberste Strich ist ein umgebogener Finger, die Querstriche stehen für die übrigen. Anders als viele andere Hand-Zeichen hatte 手 immer fünf Finger.","s":2,"i":"bs"},
"文":{"t":"leih","x":"Ein Mensch von vorn mit einem Muster auf der Brust – eine Tätowierung oder Bemalung. Ursprünglich hieß es „Muster, Zeichnung“ (heute 紋); dann wurde es für „Schriftzeichen, Text“ verwendet.","s":2,"n":"In der heutigen Form ist das Brustmuster verschwunden; übrig ist nur der Umriss des Menschen mit ausgebreiteten Armen und Beinen.","i":"obs"},
"犬":{"t":"bild","x":"Ein Hund von der Seite gesehen, mit langem Schwanz. Das Bild wurde später so stark umgeformt, dass es heute wie 大 mit einem Punkt aussieht.","s":2,"i":"obs"},
"正":{"t":"laut","x":"止 (Fuß) steht für das Losziehen. Oben stand ursprünglich 丁 (Nagel) als Klangteil (丁 チョウ → 正 ショウ), später zum Strich verkürzt. Gemeint war zuerst „auf Feldzug ziehen“ (heute 征); dann wurde das Zeichen für „richtig, gerade“ ausgeliehen.","s":2,"p":[["一","verkürztes 丁","l"],["止","Fuß","b"]],"n":"Oft liest man „一 + 止: an der Linie anhalten“ oder „gegen eine Stadtmauer marschieren“. Die ältesten Formen zeigen oben aber einen Kreis bzw. ein Rechteck, also 丁.","i":"obs"},
"田":{"t":"bild","x":"Ein Feld, durch sich kreuzende Feldwege in Abschnitte geteilt. Ursprünglich allgemein „Acker, Feld“; im Japanischen meint 田 das Reisfeld.","s":2,"n":"Im alten China wurde vor allem Hirse angebaut – das Bild zeigt also keinen Nassreis-Acker, sondern ein gewöhnliches Feld.","i":"obs"},
"目":{"t":"bild","x":"Ein menschliches Auge, das im Lauf der Zeit um 90 Grad gedreht wurde und deshalb heute senkrecht steht.","s":2,"n":"In manchen Zeichen ist die liegende Form 罒 kein Auge, sondern ein Netz (z. B. in 買 und 罪).","i":"obs"},
"立":{"t":"bild","x":"Ein Mensch von vorn mit ausgebreiteten Armen (wie 大), der auf einem Strich – dem Boden – steht. Daraus „stehen, aufstellen“.","s":2,"i":"obs"},
"元":{"t":"bild","x":"Ein Mensch, dessen Kopf besonders hervorgehoben ist: oben zwei Striche für den Kopf, unten die Beine (儿). Ursprünglich hieß es „Kopf“; daraus wurde „das Oberste, Anfang, Ursprung“.","s":2,"i":"obs"},
"公":{"t":"leih","x":"Die frühen Formen zeigen ein rundes Gefäß, einen bauchigen Krug (heute 瓮). Das Zeichen wurde für das ähnlich klingende Wort „öffentlich; Fürst“ ausgeliehen.","s":1,"n":"Oft liest man 八 (sich abwenden) + 厶 (privat) = „Gegenteil von privat“. Das stammt aus alten Texten, passt aber nicht zu den Orakelknochen- und Bronzeformen.","i":"obs"},
"切":{"t":"laut","x":"刀 (Messer) gibt den Sinnbereich „schneiden“ an, 七 liefert den Klang (七 シツ → 切 セツ).","s":2,"p":[["七","sieben","l"],["刀","Messer","b"]],"n":"Nach einer Deutung war 七 – in alter Form ein Kreuz – selbst schon das Urzeichen für „schneiden“ und wurde erst später für „sieben“ benutzt.","i":"s"},
"少":{"t":"bild","x":"Kleine Punkte, vielleicht Sandkörner, für „kleine Dinge, wenig“. Bis zur Qin-Zeit wurden 小 und 少 gleichermaßen für „klein“ und „wenig“ benutzt; erst dann teilte man sie auf.","s":1,"n":"Das Zeichen stand früher auch für „Sand“; dafür schrieb man später 沙 mit Wasser 氵.","i":"o"},
"心":{"t":"bild","x":"Ein Herz als Organ, heute stark vereinfacht. Daraus „Herz, Gemüt, Seele“.","s":2,"i":"obs"},
"方":{"t":"unklar","x":"Was das Zeichen ursprünglich zeigte, ist ungeklärt; vermutet werden u. a. ein Boot, ein Spaten oder ein Zeichen für „Seite“. Sicher ist nur: es wurde für das Wort „Richtung, Seite, Art und Weise“ verwendet.","s":0,"i":"obs"},
"牛":{"t":"bild","x":"Der Kopf eines Rindes von vorn: zwei Hörner, zwei Ohren und der senkrechte Strich für den Kopf.","s":2,"n":"Ein altes chinesisches Wörterbuch las darin Hörner, Kopf, Schultern und Schwanz; die frühen Formen zeigen aber nur den Kopf.","i":"obs"},
"止":{"t":"leih","x":"Ein Fußabdruck mit drei Zehen, der nach oben zeigt – ursprünglich „Fuß“ (heute 趾). Dann wurde das Zeichen für das ähnlich klingende Wort „anhalten, aufhören“ ausgeliehen.","s":2,"n":"In vielen Zeichen steht 止 noch für den Fuß bzw. das Gehen, z. B. in 歩 und 正.","i":"obs"},
"兄":{"t":"kombi","x":"Ein Mensch (儿) mit großem Mund (口): der, der Anweisungen gibt – der Ältere, der in der Familie das Sagen hat. Daraus „älterer Bruder“.","s":2,"p":[["口","Mund","b"],["儿","Mensch","b"]],"n":"Das ähnlich aussehende Bauteil in 祝 und 呪 ist ein kniender Mensch und ein anderes Zeichen, nicht 兄.","i":"obs"},
"冬":{"t":"unklar","x":"Anfangs gab es nur den oberen Teil; was er zeigt, ist ungeklärt. Später kam unten das Eis-Zeichen (仌, heute zwei Punkte) dazu, um „Winter“ deutlich zu machen.","s":0,"p":[["夂","Urform (unklar)","f"],["⺀","Eis","b"]],"n":"Oft liest man, oben seien zusammengeknotete Fadenenden („Ende des Jahres“). Das ist nur eine von mehreren Vermutungen, wie Fruchtstände oder die Fühler einer Heuschrecke.","i":"os"},
"古":{"t":"leih","x":"Oben stand ursprünglich ein Schild (十 ist hier die alte Form von 盾), darunter 口 nur als Unterscheidungszeichen. Gemeint war „fest, hart“ (heute 固). Wegen des gleichen Klangs wurde das Zeichen dann für das Wort „alt“ ausgeliehen; 固 (コ) bekam für die alte Bedeutung den Rahmen 囗 dazu.","s":2,"p":[["十","Schild (alte Form von 盾)","b"],["口","Unterscheidungszeichen","f"]],"n":"Oft liest man „zehn (十) Münder (口) haben es weitererzählt – also ist es alt“. Diese Deutung stammt aus dem alten Wörterbuch Shuowen; die Orakelknochen zeigen aber einen Schild, nicht die Zahl Zehn.","i":"obs"},
"台":{"t":"laut","x":"Die alte Form 臺 bedeutet „Terrasse, erhöhte Plattform“. Sinnteile sind 高 „hoch“ und (später dazugekommen) 室 „Gebäude“, der Klang kam von 止 bzw. 之. Im Zeichen 臺 sind diese Teile heute stark verschliffen. In Japan ersetzt man 臺 durch das einfachere, ähnlich klingende Zeichen 台.","s":1,"p":[["高","hoch","b"],["室","Raum, Gebäude","b"],["之","gehen (Klangteil)","l"]],"n":"台 selbst ist ein eigenes altes Zeichen: 㠯 (heute 以) mit einem 口 als Unterscheidungszeichen, ursprünglich eine Variante von 以 „benutzen“. Später wurde es wegen des ähnlichen Klangs für 臺 verwendet.","a":"臺","i":"obs"},
"広":{"t":"laut","x":"Die alte Form 廣 verbindet 广 (ein Gebäude mit nur einer Wand, eine offene Halle) als Sinnteil mit 黃 „gelb“ als Klangteil: 黃 コウ → 廣 コウ. Gemeint war eine weite, offene Halle, daraus „weit, geräumig“. In Japan wurde 黃 Ende des 19. Jh. durch das einfache 厶 ersetzt.","s":2,"p":[["广","offene Halle","b"],["黃","gelb","l"]],"n":"Die Kurzform 広 ist eine japanische Schöpfung (zuerst 1891 belegt), wohl angelehnt an 鑛 → 鉱 und an gleich klingende Zeichen wie 弘 oder 宏. Das 厶 hat hier keine eigene Bedeutung.","a":"廣","i":"obs"},
"用":{"t":"leih","x":"Ursprünglich eine Abwandlung von 同 (einer Röhre), ergänzt um einen Griff: ein Eimer oder Bottich mit Henkel. Für das ähnlich klingende Wort „benutzen“ wurde das Zeichen dann ausgeliehen.","s":1,"n":"Ältere Deutungen sahen darin eine Glocke, einen Holzrahmen oder einen Zaun. Nach heutigem Stand ist das falsch.","i":"obs"},
"世":{"t":"leih","x":"世 ist eine verkürzte Form von 枼, dem Bild eines Baumes mit Blättern (Urform von 葉 „Blatt“) – nur der obere Teil mit den Zweigen und Blättern blieb übrig. Für das ähnlich klingende Wort „Generation, Zeitalter“ wurde es ausgeliehen; daraus kam auch „Welt“.","s":2,"n":"Oft liest man „dreimal 十 = 30 Jahre = eine Generation“. Das stammt aus dem Shuowen; die Orakelknochen- und Bronzeformen haben aber nichts mit 十 zu tun. 葉 enthält das 世 bis heute.","i":"bs"},
"主":{"t":"bild","x":"In der alten Schrift fielen mehrere Bildzeichen zu 主 zusammen: eine Ahnentafel (die Holztafel, auf der der Geist eines Vorfahren verehrt wird), eine Lampe oder Fackel mit Flamme oben (der Punkt) und brennendes Holz. Die japanische Forschungsübersicht deutet 主 als Ahnentafel.","s":1,"n":"Das rechte Teil von 往 sieht ähnlich aus, hat mit 主 aber nichts zu tun.","i":"obs"},
"代":{"t":"laut","x":"亻 „Mensch“ gibt den Sinnbereich, 弋 (ein Pflock) liefert den Klang, der im Altchinesischen sehr ähnlich war. Gemeint ist „ersetzen, ablösen“ – wie ein Mensch den anderen ablöst. Daraus wurden „Generation, Zeitalter“ und „Gebühr“ (Ersatz für eine Leistung).","s":2,"p":[["亻","Mensch","b"],["弋","Pflock","l"]],"i":"s"},
"写":{"t":"laut","x":"Die alte Form 寫 hat 宀 „Dach, Haus“ als Sinnteil und 舄 (セキ/シャク) als Klangteil. Bedeutung ist „übertragen, abschreiben“. Die heutige Form 写 entstand aus einer schnell geschriebenen Schreibschrift-Form von 寫: 宀 wurde zu 冖, 舄 zu 与.","s":1,"p":[["宀","Dach, Haus","b"],["舄","Elster; Schuh","l"]],"n":"Das 与 in 写 ist nur eine verschliffene Form von 舄 und hat mit dem Zeichen 与 „geben“ nichts zu tun.","a":"寫"},
"去":{"t":"leih","x":"Ursprünglich ein Mensch (大) mit einem Mund (口): „den Mund öffnen“ (heute 呿). Das Zeichen wurde für das gleich klingende Wort „weggehen“ ausgeliehen. Mit der Zeit wurde aus 大 oben 土 und aus 口 unten 厶.","s":1,"p":[["土","Mensch (aus 大)","b"],["厶","Mund (aus 口)","b"]],"n":"Ein zweites altes Zeichen, ein Gefäß mit Deckel (Urform von 盍/蓋), fiel in der Form mit 去 zusammen. Das 土 oben hat nichts mit „Erde“ zu tun – dieselbe Verkürzung von 大 steckt in 赤 und 走.","i":"os"},
"字":{"t":"laut","x":"宀 „Haus“ ist der Sinnteil, 子 „Kind“ der Klangteil: 子 シ → 字 ジ. Zuerst bedeutete das Wort „(ein Kind) aufziehen, ernähren“. Für das gleich klingende Wort „Schriftzeichen“ wurde das Zeichen dann mitbenutzt.","s":2,"p":[["宀","Dach, Haus","b"],["子","Kind","l"]],"i":"bs"},
"早":{"t":"laut","x":"日 „Sonne“ gibt den Sinnbereich (Tageszeit). Unten stand ursprünglich 棗 „Jujube“ (eine Dattelfrucht) als Klangteil: 棗 ソウ → 早 ソウ. Davon ist heute nur noch das 十 übrig.","s":1,"p":[["日","Sonne","b"],["十","Rest von 棗 (Jujube)","l"]],"n":"Oft liest man „die Sonne über 甲 ‚Erster‘ – wenn die Sonne zuerst aufgeht“. Diese Deutung stammt aus dem Shuowen und passt nicht zu den alten Formen. Noch früher wurde für „früh“ das Zeichen 屮 (Gras) ausgeliehen.","i":"s"},
"町":{"t":"laut","x":"田 „Feld“ ist der Sinnteil, 丁 der Klangteil: 丁 チョウ → 町 チョウ. Ursprünglich bezeichnete das Wort den schmalen Weg oder Damm zwischen Reisfeldern. In Japan wurde daraus „Stadtviertel, Kleinstadt“.","s":2,"p":[["田","Feld","b"],["丁","Nagel","l"]],"i":"s"},
"花":{"t":"laut","x":"艹 „Pflanze“ ist der Sinnteil, 化 der Klangteil: 化 カ → 花 カ. 花 ist eine jüngere Schreibung: Vor der Han-Zeit schrieb man „Blume“ mit 華; dessen komplizierter unterer Teil wurde durch das einfache, gleich klingende 化 ersetzt.","s":2,"p":[["艹","Pflanze","b"],["化","sich verwandeln","l"]],"n":"Oft liest man „Pflanze, die sich verwandelt (化) = Blüte“. Nach heutigem Stand steht 化 hier nur für den Klang.","i":"bs"},
"赤":{"t":"kombi","x":"Oben stand 大 (ein großer Mensch, auch „groß“), unten 火 „Feuer“: ein großes Feuer bzw. ein Mensch am Feuer – also die Farbe des Feuers, „rot“. Aus 大 wurde später 土, und das Feuer wurde so umgeformt, dass man es heute kaum erkennt.","s":2,"p":[["土","groß / Mensch (aus 大)","b"],["火","Feuer","b"]],"n":"Das 土 oben ist dieselbe Verkürzung von 大 wie in 去 und 走 und hat nichts mit „Erde“ zu tun.","i":"obs"},
"足":{"t":"unklar","x":"Der untere Teil geht auf 止 „Fuß“ zurück. Nach neuerer Forschung schrieb man „Fuß“ zuerst mit einem Zeichen, das einen Menschen (欠) mit betontem Fuß zeigte; der Fuß-Teil wurde selbstständig, und als der Mensch wegfiel, blieb 足 übrig.","s":0,"p":[["口","(Teil der alten Form)","f"],["龰","Fuß (aus 止)","b"]],"n":"Lange galt 足 als einfaches Bild eines Beins (wie 疋), mit dem Knie als 口 oben. Das stützt sich auf die späte Siegelschrift; die japanische Forschungsübersicht hält es für widerlegt.","i":"obs"},
"不":{"t":"leih","x":"Ursprünglich ein Bildzeichen; was es zeigt, ist umstritten: entweder den Kelch einer Blüte oder einen Haarschmuck. Sicher ist, dass es wegen des ähnlichen Klangs für die Verneinung „nicht“ ausgeliehen wurde.","s":1,"n":"Oft liest man „ein Vogel fliegt zum Himmel (一) und kommt nicht weiter – also ‚nicht‘“. Das stammt aus dem Shuowen und ist durch die alten Formen nicht gedeckt.","i":"obs"},
"仕":{"t":"laut","x":"亻 „Mensch“ ist der Sinnteil, 士 der Klangteil: 士 シ → 仕 シ. 士 bezeichnete einen Mann im Amt und passt damit auch zur Bedeutung „dienen“ (einem Herrn dienen, ein Amt ausüben).","s":2,"p":[["亻","Mensch","b"],["士","Mann, Beamter","l"]]},
"会":{"t":"laut","x":"Die alte Form 會 verbindet 合 „zusammenkommen“ als Sinnteil mit 𡆧, dem Bild eines Essgefäßes, als Klangteil. Gemeint war „sich treffen, sich versammeln“. Die heutige Form 会 entstand aus einer Schreibschrift-Form von 會.","s":2,"p":[["合","zusammenkommen","b"],["𡆧","Gefäß","l"]],"n":"Das Shuowen deutete 會 als 亼 + 曾; die Bronzeformen zeigen aber keinen Bezug zu 曾. Auch 合 als Klangteil ist widerlegt, es trägt nur den Sinn.","a":"會","i":"obs"},
"同":{"t":"leih","x":"Ursprünglich das Bild einer Röhre oder eines Rohrs (Urform von 筒 „Röhre“); das 口 darin kam später nur als Zierteil dazu. Für das gleich klingende Wort „gleich, derselbe“ wurde das Zeichen ausgeliehen: 筒 トウ – 同 ドウ.","s":2,"n":"Eine Deutung, die 同 mit 凡 „alle“ verbindet, gilt als falsch.","i":"obs"},
"多":{"t":"kombi","x":"Zwei Stücke Fleisch übereinander: doppelt so viel, also „viel“. Schon in der Bronzeschrift wurde das Fleisch-Zeichen dem ähnlich aussehenden 夕 angeglichen, deshalb sieht man heute zweimal 夕.","s":2,"p":[["夕","Fleischstück (aus 肉)","b"],["夕","Fleischstück (aus 肉)","b"]],"n":"Oft liest man „zwei Abende (夕) = viele Tage“. Diese Deutung stammt aus dem Shuowen; die alten Formen zeigen aber Fleisch, nicht 夕 „Abend“.","i":"obs"},
"考":{"t":"leih","x":"考 ist eine Nebenform von 老 „alt“: ein alter Mensch mit langem Haar, der sich gebeugt auf einen Stock (丂, früher 匕) stützt. Für das ähnlich klingende Wort „nachdenken, überlegen“ wurde diese Form dann ausgeliehen.","s":2,"p":[["耂","alter Mensch","b"],["丂","Stock","b"]],"n":"Das Shuowen sah in 丂 nur einen Klangteil; die Orakelknochen zeigen aber, dass das ganze Zeichen aus 老 abgezweigt ist.","i":"obs"},
"肉":{"t":"bild","x":"Das Bild eines Stücks Fleisch – ein Fleischbrocken oder die Rippen eines Tierrumpfs. Weil es dem Zeichen 月 sehr ähnlich wurde, bekam es zur Unterscheidung zusätzliche Striche.","s":2,"n":"Als Bauteil links oder unten sieht 肉 meist wie 月 aus (z. B. in 腕, 肩, 育). Dieses „Fleisch-月“ hat mit dem Mond nichts zu tun.","i":"obs"},
"自":{"t":"leih","x":"Das Bild einer Nase – die Urform von 鼻 „Nase“, das 自 bis heute enthält. Für das Wort „selbst; von … aus“ wurde das Zeichen ausgeliehen; die Nase bekam dann das neue Zeichen 鼻.","s":2,"n":"Oft liest man „man zeigt auf die eigene Nase, wenn man ‚ich‘ meint“. Das ist eine Volksetymologie ohne Beleg; es handelt sich um eine Entlehnung über den Klang.","i":"obs"},
"色":{"t":"leih","x":"Oben eine Hand (爪), unten ein kniender Mensch (卩): eine Hand drückt jemanden nieder. Vermutlich eine alte Form von 印 bzw. 抑 „niederdrücken“. Das Zeichen wurde dann für ein anderes Wort ausgeliehen – zuerst „Gesichtsausdruck“, später „Farbe“.","s":1,"p":[["⺈","Hand (aus 爪)","b"],["巴","kniender Mensch (aus 卩)","b"]],"n":"Oft liest man „zwei Menschen übereinander“ und deutet das als Liebe oder Begierde. Das beruht auf dem Shuowen; die Bronzeformen zeigen eine Hand über einem knienden Menschen. Das untere 巴 hat mit dem Zeichen 巴 nichts zu tun.","i":"s"},
"体":{"t":"laut","x":"Die alte Form 體 verbindet 骨 „Knochen“ als Sinnteil mit 豊 (einem Ritualgefäß) als Klangteil, der im Altchinesischen ähnlich klang. Die Kurzform 体 ist seit der Song-Zeit belegt und neu gebildet: 亻 „Mensch“ + 本 „Grundlage“ – der Körper als Grundlage des Menschen.","s":2,"p":[["骨","Knochen","b"],["豊","Opfergefäß","l"]],"n":"Das 豊 in 體 ist ein altes eigenes Zeichen und nicht 豐 „reich“ (dessen japanische Kurzform ebenfalls 豊 ist). Außerdem gibt es ein gleich aussehendes, aber anderes Zeichen 体 (ホン, Nebenform von 笨 „plump“).","a":"體","i":"bs"},
"作":{"t":"laut","x":"亻 (Mensch) zeigt, dass es um menschliches Tun geht; 乍 steuert den Klang bei (乍 サク → 作 サク). Zusammen schreibt das Zeichen das Wort für „machen, herstellen“.","s":2,"p":[["亻","Mensch","b"],["乍","plötzlich","l"]],"i":"obs"},
"図":{"t":"kombi","x":"Die alte Form 圖 verbindet 囗 (Umgrenzung) mit 啚, der frühen Form von 鄙 „Randgebiet, entlegenes Land“: ein Gebiet samt seinen Außenbereichen, eingefasst in einen Rahmen – also eine Landkarte. Daraus wurde „Plan, Zeichnung“. Im heutigen 図 ist das Innere zu wenigen Strichen verkürzt.","s":2,"p":[["囗","Umgrenzung","b"],["啚","entlegenes Land","b"]],"a":"圖","i":"bs"},
"売":{"t":"laut","x":"Zuerst schrieb man „kaufen“ und „verkaufen“ beide mit 買 (バイ). Für „verkaufen“ setzte man 出 (hinaus) darüber – die Ware geht nach außen. So entstand 賣; das 出 sieht in der Druckschrift wie 士 aus. Das heutige 売 ist eine Verkürzung von 賣.","s":2,"p":[["士","aus 出: hinausgehen","b"],["買","kaufen","l"]],"n":"Das obere 士 hat nichts mit „Krieger“ zu tun – es ist ein verformtes 出.","a":"賣","i":"s"},
"弟":{"t":"bild","x":"Das Bildzeichen zeigt einen Speer- bzw. Hellebardenschaft (戈), um den ein Band in regelmäßigen Windungen gewickelt ist. Die geordnete Abfolge der Windungen stand für „Reihenfolge“; daraus wurde der Nachgeborene, der „jüngere Bruder“.","s":2,"i":"bs"},
"社":{"t":"kombi","x":"礻 (von 示, Altar für Gottheiten) und 土 (Erde): der Gott des Bodens bzw. sein Erdaltar. Daraus wurde der Schrein, um den sich die Leute eines Ortes sammelten, und später „Gemeinschaft, Gesellschaft, Firma“.","s":1,"p":[["礻","Gottheit, Altar","b"],["土","Erde","b"]],"n":"土 liefert vermutlich auch den Klang: Im Altchinesischen klangen 土 und 社 ähnlich. Nach dieser Deutung ist es eine Verbindung aus Laut und Sinn.","i":"s"},
"言":{"t":"zeichen","x":"Auf Orakelknochen schrieb man „sagen“ zunächst mit 舌 (Zunge aus dem Mund). Um die beiden Wörter zu trennen, bekam das Zeichen einen zusätzlichen Querstrich oben. Heute ist daraus die Form mit 亠, zwei Strichen und 口 geworden.","s":1,"p":[["舌","Zunge","b"],["一","Unterscheidungsstrich","f"]],"n":"Oft liest man 言 als „Nadel/Messer (辛) + Mund“. Diese Deutung aus dem alten Wörterbuch 説文 passt nicht zu den Formen auf Orakelknochen.","i":"obs"},
"走":{"t":"bild","x":"Ursprünglich ein Bild eines rennenden Menschen mit schwingenden Armen. Später kam unten 止 (Fuß) für die Bewegung dazu. Der Mensch oben ist heute zu 土 verformt, der Fuß unten zu 龰.","s":2,"p":[["土","laufender Mensch","b"],["龰","Fuß (止)","b"]],"n":"Das 土 oben hat nichts mit „Erde“ zu tun. Das alte Wörterbuch 説文 deutete den oberen Teil als 夭 (sich krümmen) – laut Forschung ein anderes Zeichen.","i":"obs"},
"近":{"t":"laut","x":"辶 (gehen, unterwegs sein) gibt den Sinnbereich: Wege und Entfernungen. 斤 (Axt) steuert nur den Klang bei (斤 キン → 近 キン). Zusammen: „nah“.","s":2,"p":[["辶","gehen","b"],["斤","Axt","l"]],"i":"s"},
"空":{"t":"laut","x":"穴 (Höhle, Loch) gibt den Sinn, 工 den Klang (工 コウ → 空 クウ/コウ). Ursprünglich hieß das Zeichen „Loch, Hohlraum“; daraus wurden „leer“ und der weite, leere „Himmel“.","s":2,"p":[["穴","Loch, Höhle","b"],["工","Arbeit","l"]],"i":"s"},
"青":{"t":"laut","x":"Ein seltenes Zeichen mit zwei Klangteilen: oben 生 (セイ), unten ursprünglich 井 (セイ), beide klangen wie das Wort für „blau/grün“. Heute ist 生 zu 龶 verkürzt und 井 zu 月 verformt.","s":2,"p":[["龶","aus 生: wachsen","l"],["月","aus 井: Brunnen","l"]],"n":"Oft liest man „junge Pflanze (生) + rote Farbe (丹)“ = Farbe frischer Pflanzen. Nach heutiger Forschung war der untere Teil aber 井 und gab nur den Klang.","i":"bs"},
"音":{"t":"zeichen","x":"音 war anfangs dasselbe Zeichen wie 言 (sprechen). Zur Unterscheidung bekam der Mund (口) einen Strich hinein – wohl als „verschlossener Mund“: Laut, Klang statt deutlicher Rede. Heute sieht das Zeichen wie 立 über 日 aus.","s":2,"p":[["言","sagen, Wort","b"],["一","Strich im Mund","f"]],"n":"立 und 日 im heutigen Zeichen sind keine echten Bauteile, sondern Umformungen von 言 mit dem Zusatzstrich.","i":"bs"},
"地":{"t":"laut","x":"土 (Erde) gibt den Sinn: der weite Erdboden. Der rechte Teil steuerte im Altchinesischen den Klang bei; heute klingen 也 (ヤ) und 地 (チ) nicht mehr ähnlich.","s":2,"p":[["土","Erde","b"],["也","auch (eigentlich 它)","l"]],"n":"Manche Forscher sehen als Klangteil ursprünglich 它 (Schlange), dessen Form in diesem Zeichen mit 也 zusammenfiel. Eine frühe Nebenform (墬) zeigt Hügel, Schwein und Erdhaufen.","i":"bs"},
"安":{"t":"kombi","x":"Auf Orakelknochen ist eine kniende Gestalt zu sehen, mit einem Strich am Gesäß: sie sitzt fest (oder auf einem Kissen). Später kam 宀 (Haus) darüber. Das Zeichen hieß zuerst „ruhig sitzen“, daraus wurden „ruhig, sicher“ und später „billig“.","s":1,"p":[["宀","Dach, Haus","b"],["女","sitzender Mensch","b"]],"n":"Oft liest man „Frau im Haus = Ruhe“. Das ist laut Forschung falsch: Der untere Teil war keine Frau, sondern eine kniende Figur mit Markierung; erst in der Han-Zeit wurde er wie 女 geschrieben.","i":"obs"},
"有":{"t":"leih","x":"Das Zeichen besteht aus 又 (Hand, hier Klangteil) und ⺼ (Fleisch). Es schrieb wohl zuerst ein Wort für „(Speisen) anbieten, zum Essen nötigen“. Dann wurde es für das gleich klingende Wort „haben, vorhanden sein“ ausgeliehen.","s":2,"p":[["𠂇","Hand (又)","l"],["月","Fleisch (⺼)","b"]],"n":"Oft liest man „Hand hält Fleisch → besitzen“. Laut Forschung ist die Hand aber Klangteil, und „haben“ eine Entlehnung. Der untere Teil ist Fleisch, nicht der Mond (月) – so deutete es das alte Wörterbuch 説文.","i":"obs"},
"死":{"t":"kombi","x":"Rechts steht ein Mensch (heute 匕), links 歹, das nach neuerer Deutung eine Schaufel zeigt. Eine Lesart: Ein Mensch wird mit der Schaufel bestattet – „sterben, Tod“. Ganz geklärt ist der Aufbau nicht.","s":0,"p":[["歹","Schaufel","b"],["匕","Mensch","b"]],"n":"Oft liest man „Mensch kniet vor Knochenresten (歹)“. Dass 歹 Knochen sind, stammt aus dem alten Wörterbuch 説文 und gilt heute als falsch. Manche sehen 歹 auch als Klangteil.","i":"obs"},
"京":{"t":"leih","x":"Ein Bildzeichen: ein hohes Gebäude, etwa ein Wachturm auf einem Unterbau. Zuerst stand es für „hoch“; dann wurde es für das gleich klingende Wort „Hauptstadt“ ausgeliehen.","s":2,"n":"Als oberer Teil anderer Zeichen fällt unten das 小 weg, z. B. in 亮 und 亭.","i":"obs"},
"夜":{"t":"laut","x":"Zuerst schrieb man „Nacht“ einfach mit 夕 (Mond/Abend). Dann kam 亦 als Klangteil dazu (亦 ヤク → 夜 ヤ). Im heutigen Zeichen ist 亦 zerlegt: 亠 und 亻 stammen von ihm, sein letzter Strich verschmilzt mit 夕.","s":2,"p":[["亦","auch (verformt)","l"],["夕","Abend, Mond","b"]],"i":"bs"},
"妹":{"t":"laut","x":"女 (Frau) gibt den Sinnbereich: weibliche Verwandte. 未 steuert den Klang bei (未 ミ → 妹 マイ, beide mit m-). Zusammen: „jüngere Schwester“.","s":2,"p":[["女","Frau","b"],["未","noch nicht","l"]],"i":"obs"},
"姉":{"t":"laut","x":"女 (Frau) gibt den Sinn, der rechte Teil den Klang (シ → 姉 シ). Ursprünglich war das ein anderes Element (𠂔, im Chinesischen 姊); in Japan wird es heute wie 市 (Markt, シ) geschrieben.","s":1,"p":[["女","Frau","b"],["市","eigentlich 𠂔","l"]],"i":"bs"},
"店":{"t":"laut","x":"广 (ein an einen Hang gebautes Haus, allgemein Gebäude) gibt den Sinnbereich. 占 steuert den Klang bei (占 セン → 店 テン, im Altchinesischen sehr ähnlich). Zusammen: „Laden, Geschäft“.","s":2,"p":[["广","Gebäude","b"],["占","wahrsagen","l"]]},
"明":{"t":"kombi","x":"Schon auf Orakelknochen gibt es 日 + 月: Die Sonne geht auf, der Mond steht noch am Himmel – Morgendämmerung, „hell“. Daneben gab es 朙 aus 囧 (rundes Muster) + 月. Das heutige 明 geht auf 朙 zurück: 囧 wurde über 目 zu 日.","s":1,"p":[["日","Sonne","b"],["月","Mond","b"]],"n":"Das 囧 in 朙 deutet man oft als Fenster, durch das Mondlicht fällt. Eine andere Deutung sieht darin ein Wirbelmuster, wie es auf Bronzegefäßen vorkommt.","i":"obs"},
"歩":{"t":"bild","x":"Zwei Fußabdrücke hintereinander, einer davon gespiegelt: ein Schritt nach dem anderen, also „gehen“. Die alte Form 步 hat unten einen gespiegelten Fuß; im heutigen 歩 wurde er an 少 angeglichen.","s":2,"p":[["止","Fuß","b"],["少","umgedrehter Fuß","f"]],"n":"Der untere Teil hat nichts mit 少 (wenig) zu tun – er ist ein umgedrehtes 止.","a":"步","i":"b"},
"画":{"t":"kombi","x":"Am Anfang stand ein Bild eines alten Zirkels. Dazu kam 聿 (Hand mit Pinsel), später noch 周: So entstand 畫, „zeichnen, Linien ziehen“. Im heutigen 画 ist der Pinsel oben weggefallen.","s":1,"p":[["聿","Pinsel","b"],["田","eigentlich Zirkel","b"]],"n":"Oft liest man „Pinsel zieht die Grenzen eines Feldes (田)“. Die alten Inschriften zeigen aber kein Feld, sondern den Zirkel.","a":"畫","i":"obs"},
"知":{"t":"kombi","x":"知 und 智 waren ursprünglich dasselbe Zeichen. Auf Orakelknochen: Erwachsener (大) + Mund (口) + Kind (子) – ein Erwachsener gibt einem Kind Wissen weiter. Später wurde 大 zu 矢 umgeformt, und 子 fiel weg: So entstand 知.","s":1,"p":[["矢","Pfeil (aus 大)","f"],["口","Mund","b"]],"n":"Oft liest man „Worte treffen schnell wie ein Pfeil (矢)“, oder 矢 gilt als Klangteil. Beides passt nicht: Der Pfeil ist nur eine spätere Umformung von 大, und 矢 klang im Altchinesischen anders als 知.","i":"s"},
"室":{"t":"laut","x":"宀 (Dach) gibt den Sinnbereich: Haus, Wohnung. 至 steuert den Klang bei (至 シ → 室 シツ). Ursprünglich hieß das Zeichen „Haus, Wohnsitz“, heute „Zimmer, Raum“.","s":2,"p":[["宀","Dach, Haus","b"],["至","ankommen","l"]],"n":"Das alte Wörterbuch 説文 deutet 至 auch inhaltlich: der Ort, an dem man ankommt und bleibt.","i":"obs"},
"思":{"t":"laut","x":"Die alte Form war 恖: unten 心 „Herz“ als Sinnteil für Denken und Fühlen, oben 囟 „Fontanelle, Schädeldecke“ als Klangteil (altchinesisch ähnlich wie 思). Schon in Seidenschriften wurde 囟 zu dem nicht verwandten 田 „Reisfeld“ verschrieben.","s":1,"p":[["田","Schädeldecke (囟)","l"],["心","Herz","b"]],"n":"Oft liest man „Gedanken in Kopf (田) und Herz“. Das obere Teil hat mit 田 nichts zu tun. Ob 囟 neben dem Klang auch Sinn beiträgt, ist offen; die japanische Forschung sieht es als reinen Klangteil.","i":"s"},
"海":{"t":"laut","x":"氵 „Wasser“ zeigt den Sinnbereich, 毎 (alte Form 每) ist der Klangteil. Im Altchinesischen klangen 每 und 海 noch verwandt; heute haben sich die Lesungen auseinanderentwickelt (毎 マイ, 海 カイ).","s":2,"p":[["氵","Wasser","b"],["毎","jedes","l"]],"n":"In der alten Schreibweise steht rechts 每 statt 毎; das ist nur eine kleine Glyphenabweichung.","i":"bs"},
"茶":{"t":"laut","x":"茶 ist eine Abwandlung des älteren Zeichens 荼 „Bitterkraut“, das in alten Texten auch für Tee stand. 荼 besteht aus 艹 „Pflanze“ als Sinnteil und 余 als Klangteil. Für die Bedeutung „Tee“ ließ man einen Strich weg, so entstand 茶.","s":2,"p":[["艹","Pflanze","b"],["余","ich (verkürzt)","l"]],"n":"Oft liest man „ein Mensch (人) zwischen Gras (艹) und Baum (木)“. Das untere Teil ist aber das verkürzte 余 aus 荼, kein Mensch und kein Baum."},
"以":{"t":"bild","x":"Das Zeichen zeigt einen Menschen, der etwas trägt oder bei sich führt; rechts ist der Mensch (人) noch zu erkennen. Die ursprüngliche Bedeutung war „mitnehmen, anführen“. Daraus wurde das Funktionswort „mit, mittels“ und in Wörtern wie 以上・以下 „von … an“.","s":2,"n":"Die verkürzte Form 㠯 wurde manchmal als Bild eines Pflug-Geräts gedeutet; das gilt heute als falsch – es ist der Körper des tragenden Menschen.","i":"obs"},
"夏":{"t":"kombi","x":"Vermutlich zeigte das früheste Zeichen einen Menschen mit großem Kopf (頁) unter der Sonne (日): „Sommer“. Später kamen ein Fuß und zwei Hände dazu, die Sonne fiel weg. Die heutige Form bewahrt davon nur den Kopf oben und den Fuß 夂 unten.","s":1,"p":[["𦣻","Kopf (aus 頁)","b"],["夂","Fuß","b"]],"n":"Oft liest man „ein Tänzer mit großer Maske“. Diese Deutung stützt sich nur auf Bronzeinschriften; die Orakelknochenformen sprechen dagegen.","i":"obs"},
"家":{"t":"laut","x":"宀 „Dach“ gibt den Sinnbereich Haus an. Darunter stand ursprünglich 𢑓 „Eber“ als Klangteil (altchinesisch ähnlich wie 家, heute カ). Später wurde er zu 豕 „Schwein“ vereinfacht.","s":2,"p":[["宀","Dach","b"],["豕","Schwein (urspr. Eber 𢑓)","l"]],"n":"Oft liest man „ein Schwein unter dem Dach – Haustiere gehören zum Haus“. Das ist Volksetymologie: Das Tier steht nur für den Klang, nicht für die Bedeutung.","i":"obs"},
"紙":{"t":"laut","x":"糸 „Faden, Seide“ zeigt den Sinnbereich: Papier wurde aus Fasern hergestellt. 氏 ist der Klangteil: 氏 シ → 紙 シ.","s":2,"p":[["糸","Faden, Seide","b"],["氏","Sippe","l"]],"i":"s"},
"通":{"t":"laut","x":"辶 „gehen, Weg“ zeigt den Sinnbereich: hindurchgehen, durchkommen. 甬 ist der Klangteil; im Altchinesischen klangen 甬 und 通 ähnlich, heute nicht mehr (甬 ヨウ, 通 ツウ).","s":2,"p":[["辶","gehen","b"],["甬","Glocke","l"]]},
"強":{"t":"laut","x":"虫 „Insekt“ ist der Sinnteil, oben steht der Klangteil 𪪺 (弓 + kleines 口 als Unterscheidungszeichen). So schrieb man den Namen des Kornkäfers. Dann wurde das Zeichen für das gleich klingende Wort „stark“ ausgeliehen; vorher schrieb man „stark“ mit 𪪺 allein.","s":1,"p":[["弓","Bogen","l"],["ム","Markierung (aus 口)","f"],["虫","Insekt","b"]],"n":"Das obere Teil sieht aus wie 弘, ist aber ein anderes Zeichen. Aus dem kleinen 口 wurde später ム. 弓 als „starkes Ding“ passt zur Bedeutung, doch im heutigen 強 trägt es nur den Klang.","i":"s"},
"教":{"t":"laut","x":"攵 (eine Hand mit Stock) steht für eine Handlung, hier das Anleiten; 爻 ist der Klangteil (altchinesisch ähnlich wie 教). Später kam 子 „Kind“ dazu: einem Kind etwas beibringen. In der alten Form 敎 sieht man 爻 über 子 noch deutlich; heute ist die linke Hälfte zu 孝 verkürzt.","s":2,"p":[["爻","Kreuzzeichen","l"],["子","Kind","b"],["攵","Hand mit Stock","b"]],"n":"Die linke Hälfte sieht heute aus wie 孝 „Pietät“, hat damit aber nichts zu tun – sie ist aus 爻 + 子 entstanden. Vergleiche 學 (学), das ebenfalls 爻 und 子 enthält.","a":"敎"},
"理":{"t":"laut","x":"王 ist hier die Form von 玉 „Jade“ und gibt den Sinnbereich an; 里 ist der Klangteil: 里 リ → 理 リ. Ursprünglich hieß das Zeichen „Jade bearbeiten“. Daraus entwickelten sich „ordnen“ und schließlich „Ordnung, Vernunft, Grund“.","s":2,"p":[["王","Jade (玉)","b"],["里","Dorf","l"]]},
"週":{"t":"laut","x":"Ein relativ junges Zeichen: Zu 周 „rundherum, Umlauf“ kam 辶 „gehen“ hinzu, um die Bedeutung „herumgehen“ abzugrenzen. 周 gibt zugleich den Klang: 周 シュウ → 週 シュウ. Die Bedeutung „Woche“ (ein Umlauf von sieben Tagen) kam erst sehr viel später.","s":2,"p":[["辶","gehen","b"],["周","Umkreis","l"]],"n":"Im ältesten Zeichenlexikon (説文解字, um 100 n. Chr.) fehlt 週 noch; es taucht erst Jahrhunderte später auf."},
"魚":{"t":"bild","x":"Ein Bild eines Fisches: oben der Kopf, in der Mitte der Körper mit Schuppen, unten die Schwanzflosse.","s":2,"n":"Die vier Punkte unten (灬) sehen aus wie „Feuer“, sind aber aus der Schwanzflosse entstanden.","i":"obs"},
"鳥":{"t":"bild","x":"Ein Bild eines Vogels mit herabhängendem Schwanz: oben Kopf und Auge, in der Mitte der Körper, unten Schwanzfedern und Krallen.","s":2,"n":"Die vier Punkte unten sind Teil des Vogels, nicht „Feuer“ 灬. Ähnlich entstanden 烏 „Krähe“ und 隹 (ein weiteres, heute abstrakteres Vogel-Zeichen).","i":"obs"},
"黒":{"t":"leih","x":"Die alte Form 黑 zeigte wohl einen Menschen mit auf den Rücken gebundenen Händen; Punkte am Kopf werden als Tätowierung als Strafe gedeutet. Daher stand es für „Tusche, Tinte“ (墨) und wurde für das ähnlich klingende Wort „schwarz“ ausgeliehen. In 黒 wurden die zwei Punkte in der Mitte zu einem Strich.","s":1,"n":"Oft liest man „Ruß im Rauchabzug über dem Feuer (灬)“. Das stammt aus alten Wörterbüchern; die frühen Formen zeigen aber einen Menschen, kein Feuer.","a":"黑","i":"obs"},
"住":{"t":"laut","x":"亻 „Mensch“ gibt den Sinnbereich an, 主 ist der Klangteil: 主 シュ → 住 ジュウ. Gemeint ist, dass sich ein Mensch an einem Ort aufhält, also „wohnen“.","s":2,"p":[["亻","Mensch","b"],["主","Herr","l"]],"n":"Vergleiche 駐 „anhalten, stationiert sein“ mit demselben Klangteil."},
"医":{"t":"laut","x":"Die alte Form 醫 hat unten 酉 „Weinkrug“ als Sinnteil und oben 殹 als Klangteil; gemeint war ursprünglich ein süßes Reisgetränk. Für das ähnlich klingende Wort „Arzt“ wurde es ausgeliehen. Die heutige Form 医 ist nur der obere linke Teil von 醫.","s":1,"p":[["殹","(Klangteil)","l"],["酉","Weinkrug","b"]],"n":"Oft liest man, 酉 stehe für Heilwein. Da „Arzt“ eine Entlehnung ist, gilt das als Volksdeutung. Es gab außerdem ein eigenes Zeichen 医 „Köcher“ (Pfeil 矢 in einem Behälter), das mit Medizin nichts zu tun hat und nur zufällig gleich aussieht.","a":"醫","i":"s"},
"究":{"t":"laut","x":"穴 „Loch, Höhle“ gibt den Sinnbereich an, 九 ist der Klangteil: 九 キュウ → 究 キュウ. Heute bedeutet es „bis zum Ende gehen, ergründen“.","s":2,"p":[["穴","Loch, Höhle","b"],["九","neun","l"]],"i":"s"},
"者":{"t":"leih","x":"Der obere Teil war ein Bildzeichen, das einer Pflanze ähnelt; was es genau zeigte, ist umstritten (vielleicht Zuckerrohr). Unten kam 口 als Zusatzzeichen dazu, heute als 日 geschrieben. Das Zeichen wurde für ein grammatisches Wort ausgeliehen, daraus „derjenige, der …“, also „Person“.","s":0,"p":[["耂","Pflanzenbild (unklar)","f"],["日","Zusatzzeichen (aus 口)","f"]],"n":"耂 hat nichts mit 老 „alt“ zu tun. Die alte Schreibweise mit einem Punkt über 日 beruht auf einer falschen Deutung des Unterteils als 白.","i":"bs"},
"研":{"t":"laut","x":"石 „Stein“ gibt den Sinnbereich an: mit Stein schleifen, polieren. Der rechte Teil ist eine Verkürzung von 幵, dem Klangteil: 幵 ケン → 研 ケン. Aus „schleifen“ wurde übertragen „gründlich untersuchen, forschen“.","s":2,"p":[["石","Stein","b"],["开","Klangteil (aus 幵)","l"]],"n":"Die alte Schreibweise 硏 zeigt rechts noch 幵; der Unterschied ist nur eine Glyphenvariante.","i":"s"},
"場":{"t":"laut","x":"土 „Erde“ gibt den Sinnbereich an, 昜 ist der Klangteil (vgl. 陽 ヨウ, 湯 トウ). Ursprünglich war ein ebener Platz gemeint; daraus „Ort, Stelle“.","s":2,"p":[["土","Erde","b"],["昜","Sonnenschein","l"]]},
"朝":{"t":"laut","x":"Das heutige 朝 geht auf ein Bronzezeichen aus Fluss (川/水) + Klangteil 𠦝 zurück, das wohl „Flut, Gezeiten“ (潮) bedeutete. Es wurde für das gleich klingende Wort „Morgen“ ausgeliehen. Rechts trat später 舟 „Boot“ an die Stelle des Flusses; seit der Han-Zeit schreibt man dort 月.","s":1,"p":[["𠦝","Sonne im Gras","l"],["月","urspr. Fluss (umgeformt)","f"]],"n":"Oft liest man „die Sonne geht im Gras auf, der Mond steht noch am Himmel“. So sah ein Orakelknochenzeichen für „Morgen“ aus, das in der Westlichen Zhou-Zeit außer Gebrauch kam. Ob 月 im heutigen Zeichen davon übrig ist oder aus 舟 entstand, ist unklar.","i":"ob"},
"答":{"t":"laut","x":"答 ist eine Variante von 荅 (艹 „Pflanze“ + Klangteil 合), einem Wort für eine Bohnenart. Es wurde für das gleich klingende Wort „antworten“ ausgeliehen. Später ersetzte man 艹 irrtümlich durch ⺮ „Bambus“, das daher keine Bedeutung trägt.","s":1,"p":[["⺮","Bambus (urspr. 艹)","f"],["合","zusammenpassen","l"]]},
"買":{"t":"laut","x":"貝 „Muschel“ stand für Geld und Wertgegenstände und gibt den Sinnbereich an. Darüber steht 罒, die Form von 网 „Netz“, wohl als Klangteil. Das Zeichen schrieb anfangs sowohl „kaufen“ als auch „verkaufen“ (später 賣/売).","s":1,"p":[["罒","Netz (网)","l"],["貝","Muschel, Geld","b"]],"n":"Eine zweite Deutung sieht darin eine Sinnverbindung: mit dem Netz (网) Muscheln, also Geld, einfangen. Neuere Lautrekonstruktionen sprechen eher dafür, dass 网 den Klang angibt.","i":"bs"},
"道":{"t":"laut","x":"辶 „gehen, Weg“ gibt den Sinnbereich an, 首 ist der Klangteil (altchinesisch ähnlich wie 道). Früh schrieb man 行 „Kreuzung“ + 首; Fuß und Weg-Teile verschmolzen später zu 辶.","s":2,"p":[["辶","gehen","b"],["首","Kopf","l"]],"n":"Oft liest man „ein Kopf geht voran“ oder „man trug abgeschlagene Köpfe, um den Weg zu reinigen“. Beides gilt als widerlegt: Es gibt Varianten, in denen 首 durch ein anderes gleich klingendes Teil ersetzt ist, also trägt 首 nur den Klang.","i":"bs"},
"楽":{"t":"leih","x":"Die alte Form 樂 zeigt ein Saiteninstrument: Saiten (幺) auf einem Holzkörper (木); 白 kam später als Klangteil dazu. Gemeint war „Musik“ (音楽). Für das ähnlich klingende Wort „Freude, angenehm“ wurde das Zeichen ausgeliehen. 楽 ist eine aus der Schreibschrift verkürzte Form von 樂.","s":1,"p":[["木","Holz","b"],["幺","Faden, Saite","b"],["白","weiß","l"]],"n":"Oft liest man, 白 sei ein Daumen, der die Saiten zupft, oder das Zeichen zeige Glöckchen an einem Holzgestell. Nach den ältesten Schriftfunden stimmt beides nicht: 白 ist kein Daumen, sondern wohl ein Klangteil.","a":"樂","i":"obs"},
"事":{"t":"kombi","x":"Eine Hand hält eine Stange, wohl mit Fahne oder Trommel daran – das Zeichen eines Amtsträgers. Daraus wurde „ein Amt ausüben, Dienst“ und schließlich „Angelegenheit, Sache“. 事 war anfangs nur eine Schreibvariante von 吏 (Beamter); erst um die Qin-Zeit trennten sich die beiden.","s":1,"p":[["⺕","Hand","b"],["中","Stange mit Fahne","b"]],"n":"Hand und Stange sind in der heutigen Form verschmolzen: Oben steht etwas wie 一 + 口, darunter die Hand ⺕ mit dem senkrechten Strich. Eng verwandt sind 吏 und 史.","i":"obs"},
"使":{"t":"laut","x":"亻 (Mensch) gibt den Sinnbereich an, 吏 (eine Form von 史 シ) den Klang: 史 シ → 使 シ. Gemeint war zuerst der Bote oder Gesandte, den man schickt; daraus wurde „jemanden einsetzen, beauftragen“ und schließlich „benutzen“.","s":2,"p":[["亻","Mensch","b"],["吏","Beamter","l"]],"n":"吏 zeigt eine Hand, die eine Stange hält (Zeichen eines Amtsträgers). Deshalb passt es nicht nur vom Klang, sondern auch vom Sinn her zu „Gesandter“."},
"始":{"t":"laut","x":"女 (Frau) gibt den Sinnbereich an, 台 den Klang. Ursprünglich stand das Zeichen wohl für „schwanger sein“ (verwandt mit 胎 „Mutterleib“). Für das ähnlich klingende Wort „anfangen“ wurde es dann ausgeliehen.","s":2,"p":[["女","Frau","b"],["台","Sockel","l"]],"n":"Oft liest man „das Leben einer Frau beginnt“ o. Ä. Das ist eine Eselsbrücke; 台 ist hier einfach der Klangteil."},
"服":{"t":"laut","x":"Der Kern rechts zeigt eine Hand (又), die einen knienden Menschen (卩) niederdrückt: „unterwerfen, sich fügen, dienen“. Links kam später ein Teil dazu, das sich über 舟 (Boot) zu 月 wandelte. „Kleidung“ ist eine spätere, ausgeliehene Bedeutung.","s":1,"p":[["月","später ergänzt","f"],["卩","kniender Mensch","b"],["又","Hand","b"]],"n":"Das linke 月 hat nichts mit Mond oder Fleisch zu tun. Ob es als Klangteil oder als „Tablett“ (凡) hinzukam, ist nicht einig; ein Boot (舟), wie die alte Erklärung im 説文 meint, ist es jedenfalls nicht.","i":"obs"},
"物":{"t":"laut","x":"牜 (Rind) gibt den Sinnbereich an, 勿 den Klang: 勿 ブツ → 物 ブツ. Ursprünglich bezeichnete das Wort ein buntscheckiges Rind; später wurde das Zeichen für das gleich klingende Wort „Ding, Sache“ ausgeliehen.","s":2,"p":[["牜","Rind","b"],["勿","nicht","l"]],"i":"os"},
"屋":{"t":"laut","x":"Der untere Teil stammt von 室 (Zimmer, Raum) und gibt den Sinnbereich an. Oben stand ursprünglich ein Klangteil, der sich mit der Zeit zu 尸 verformt hat. Gemeint war zuerst „Dach“, dann „Haus“ und im Japanischen auch „Laden“.","s":2,"p":[["尸","Klangteil (entstellt)","l"],["至","Zimmer (aus 室)","b"]],"n":"Oft liest man 尸 als „Leichnam/Körper“ und 至 als „ankommen“ („wo man ankommt und sich hinlegt“). Die Forschung sieht das anders: 尸 ist ein entstellter Klangteil, 至 ein Rest von 室.","i":"s"},
"度":{"t":"laut","x":"又 (Hand) gibt den Sinnbereich an: „messen“ – wohl weil man früher mit der Hand Maß nahm. Oben stand ursprünglich 石 (Stein) als Klangteil; er hat sich zur heutigen Form mit 广 und 廿 verformt. Aus „messen“ wurden „Maß, Grad“ und „Mal“.","s":2,"p":[["广","Stein (entstellt)","l"],["又","Hand","b"]],"n":"Das 广 oben hat hier nichts mit „Gebäude“ zu tun. Die alte Erklärung im 説文 nimmt 庶 als Klangteil an; heute gilt 石 als Klangteil.","i":"s"},
"待":{"t":"laut","x":"彳 (gehen, Weg) gibt den Sinnbereich an, 寺 den Klang. Gemeint ist „warten“ – etwa am Weg auf jemanden warten. Der Klang hat sich verschoben: 寺 wird heute ジ gelesen, 待 タイ.","s":2,"p":[["彳","gehen, Weg","b"],["寺","Tempel","l"]]},
"持":{"t":"laut","x":"扌 (Hand) gibt den Sinnbereich an, 寺 den Klang: 寺 ジ → 持 ジ. Ursprünglich schrieb man „halten, festhalten“ einfach mit 寺; erst später setzte man die Hand davor, um die Bedeutung klarzustellen.","s":2,"p":[["扌","Hand","b"],["寺","Tempel","l"]]},
"界":{"t":"laut","x":"田 (Feld) gibt den Sinnbereich an, 介 den Klang: 介 カイ → 界 カイ. Gemeint war die Grenze zwischen Feldern; daraus wurden „Grenze, Bereich“ und „Welt“ (z. B. 世界).","s":2,"p":[["田","Feld","b"],["介","dazwischen","l"]],"i":"s"},
"発":{"t":"laut","x":"Die alte Form 發 geht auf ein Bild zurück: ein Bogen, der gerade einen Pfeil abschießt und noch nachschwingt. Später kam eine Hand dazu, die dann durch den Klangteil 癹 ersetzt wurde: 癹 ハツ → 發 ハツ. Bedeutung: „abschießen, aussenden“. 発 ist eine aus der Schreibschrift verkürzte Form; 弓 ist dabei weggefallen.","s":2,"p":[["癶","Füße","f"],["弓","Bogen","b"],["癹","niedertreten","l"]],"n":"Im heutigen 発 ist vom Bogen nichts mehr zu sehen; oben steht noch 癶 aus dem Klangteil 癹.","a":"發","i":"os"},
"送":{"t":"laut","x":"辶 (gehen, unterwegs sein) gibt den Sinnbereich an, das Teil darüber (alte Form 灷) den Klang. Gemeint ist „jemanden begleiten, fortschicken“, daher heute auch „senden“.","s":2,"p":[["辶","gehen","b"],["关","Klangteil 灷","l"]],"n":"Oft liest man das obere Teil als „zwei Hände mit Fackel“ und deutet: jemanden mit Fackeln hinausbegleiten. Die Forschung sieht 灷 heute als Klangteil; in Orakelknochen-Texten steht es für ein ähnlich klingendes Wort."},
"重":{"t":"laut","x":"Ursprünglich ein Bild: ein Mensch mit einem schweren Sack (東) auf dem Rücken; 東 gibt zugleich den Klang. Später kam 土 (Boden) dazu – der Träger steht auf der Erde. Bedeutung: „schwer“; „aufeinanderschichten“ (重ねる) ist eine ausgeliehene Bedeutung.","s":1,"p":[["人","Mensch","b"],["東","Sack, Bündel","l"],["土","Erde, Boden","b"]],"n":"Oft zerlegt man 重 in 千 + 里. Das ist nur eine Merkhilfe; mit 千 hat das obere Teil nichts zu tun – dort steckt der Mensch.","i":"obs"},
"起":{"t":"laut","x":"走 (laufen, sich bewegen) gibt den Sinnbereich an, 己 den Klang: 己 キ → 起 キ. Bedeutung: „sich erheben, aufstehen“.","s":2,"p":[["走","laufen","b"],["己","selbst","l"]],"n":"Im Chinesischen wird das rechte Teil teils als 巳 geschrieben; in Japan steht 己.","i":"s"},
"院":{"t":"laut","x":"阝 (Erdwall) gibt den Sinnbereich an, 完 den Klang. Gemeint war die Umfriedung, die Mauer um einen Hof; daraus wurde „ummauertes Gebäude“ und schließlich „Institution“ (病院, 大学院).","s":2,"p":[["阝","Erdwall, Hügel","b"],["完","vollständig","l"]],"n":"Heute passen 完 カン und 院 イン im Klang kaum zusammen. Vermutlich hat sich die Aussprache verändert oder das Zeichen wurde mit einem gleichbedeutenden Wort anderen Klangs gelesen.","i":"s"},
"終":{"t":"laut","x":"冬 zeigte ursprünglich die Knoten am Ende einer Schnur und bedeutete selbst „Ende“. Als 冬 für „Winter“ gebraucht wurde, setzte man 糸 (Faden) als Sinnteil davor; 冬 wirkt seitdem als Klangteil. Bedeutung: „enden, Ende“.","s":2,"p":[["糸","Faden","b"],["冬","Winter","l"]],"i":"obs"},
"習":{"t":"laut","x":"In den ältesten Formen steht unten 日 (Sonne) und oben 彗 (Besen) als Klangteil. Gemeint war wohl „in der Sonne trocknen“; für das ähnlich klingende Wort „lernen, üben“ wurde das Zeichen ausgeliehen. Später wurde aus 日 ein 白 und aus 彗 etwas, das wie 羽 aussieht.","s":1,"p":[["羽","Besen (彗)","l"],["白","Sonne (urspr. 日)","b"]],"n":"Oft liest man „ein junger Vogel übt mit den Flügeln (羽) das Fliegen“. Diese alte Deutung nach dem 説文 gilt heute als unsicher bis falsch; in den ältesten Formen steht kein 羽.","i":"os"},
"転":{"t":"laut","x":"Die alte Form 轉: 車 (Wagen, Rad) gibt den Sinnbereich an, 專 den Klang. Gemeint ist „sich drehen, rollen“ wie ein Rad. In der heutigen Form wurde 專 durch das einfachere 云 ersetzt – genauso wie bei 伝 (alt 傳).","s":2,"p":[["車","Wagen","b"],["云","sagen (statt 專)","f"]],"a":"轉","i":"s"},
"運":{"t":"laut","x":"辶 (gehen, unterwegs sein) gibt den Sinnbereich an, 軍 den Klang: 軍 グン → 運 ウン. Bedeutung: „sich im Kreis bewegen, befördern“; daraus wurde auch „Lauf der Dinge, Schicksal, Glück“.","s":2,"p":[["辶","gehen","b"],["軍","Heer","l"]],"n":"Oft liest man „ein Heer (軍) marschiert und transportiert etwas“. 軍 ist hier aber der Klangteil, nicht der Sinn.","i":"s"},
"開":{"t":"laut","x":"門 (Tor) gibt den Sinnbereich an, das Teil darin (alte Form 幵) den Klang. Bedeutung: „öffnen, aufgehen“.","s":0,"p":[["門","Tor","b"],["开","Klangteil 幵","l"]],"n":"Oft liest man: zwei Hände (廾) schieben den Riegel (一) eines Tores auf. Manche Forscher sehen das noch so; andere halten das Teil im Tor für einen Klangteil, weil ein verriegeltes Tor in den ältesten Schriftformen nicht belegt ist.","i":"s"},
"集":{"t":"kombi","x":"Ein Vogel (隹) sitzt auf einem Baum (木). Die ältere Form 雧 zeigt sogar drei Vögel: Vögel, die sich in einem Baum sammeln – daher „sich versammeln, sammeln“.","s":2,"p":[["隹","Vogel","b"],["木","Baum","b"]],"i":"os"},
"飲":{"t":"bild","x":"Auf Orakelknochen ein Bild: ein Mensch beugt sich mit offenem Mund, oft mit herausgestreckter Zunge, über einen Krug mit Wein und trinkt. Später löste sich der Mund als 今 ab, der Körper wurde zu 欠, und der Krug wurde zu 食 umgeformt.","s":1,"p":[["飠","essen (statt Krug)","f"],["欠","Mensch mit offenem Mund","b"]],"n":"Der Teil 食 links hat also ursprünglich mit „essen“ nichts zu tun – er stand für ein Weingefäß (酉).","i":"ob"},
"業":{"t":"leih","x":"Ein Bildzeichen: ein Gestell mit zackigem Querbalken, an dem man Glocken und Klangsteine aufhängte. Für das gleich klingende Wort „Tätigkeit, Arbeit, Werk“ wurde das Zeichen ausgeliehen.","s":1,"n":"Es gibt noch andere Deutungen, etwa ein Mensch, der diesen Balken hochhebt. Das Gestell für Musikinstrumente ist aber die verbreitetste.","i":"bs"},
"漢":{"t":"laut","x":"氵 (Wasser) gibt den Sinnbereich an, 𦰩 den Klang (dasselbe Teil steckt in 難 ナン und 嘆 タン). Gemeint war der Fluss Han. Nach ihm wurde die Han-Dynastie benannt, und daraus wurde der Name für Chinesisches überhaupt (漢字).","s":2,"p":[["氵","Wasser","b"],["𦰩","gefesselter Mensch","l"]],"i":"bs"},
"歌":{"t":"laut","x":"欠 zeigt einen Menschen mit weit geöffnetem Mund und gibt den Sinnbereich „Atem, Mund“. 哥 liefert den Klang: 哥 カ → 歌 カ. 哥 bedeutete früher selbst „singen“; 歌 ist eine verdeutlichte Schreibung dieses Wortes.","s":2,"p":[["哥","singen (alt)","l"],["欠","offener Mund","b"]],"i":"s"},
"親":{"t":"laut","x":"見 (sehen) gibt den Sinnbereich, der linke Teil den Klang: zuerst 辛 シン, später ersetzt durch 亲 (wie in 新 シン) → 親 シン. Gemeint war von Anfang an das Wort für „vertraut, nahestehend“; daraus „Verwandte, Eltern“.","s":2,"p":[["亲","Variante von 辛 (Meißel)","l"],["見","sehen","b"]],"n":"Oft liest man „auf einem Baum (木) stehen (立) und nach dem Kind sehen (見)“. Das ist eine Eselsbrücke: der linke Teil ist ein Klangteil und hat mit Baum und Stehen nichts zu tun.","i":"bs"},
"病":{"t":"laut","x":"疒 zeigt ein Bett, auf dem ein Kranker liegt, und gibt den Sinnbereich „Krankheit“. 丙 liefert den Klang: 丙 ヘイ → 病 ヘイ/ビョウ.","s":2,"p":[["疒","Krankenbett","b"],["丙","dritter (Zählzeichen)","l"]],"n":"Manchmal liest man, 丙 bedeute hier „Feuer“, also Fieber im Bett. Nach heutigem Stand steht 丙 nur für den Klang."},
"別":{"t":"kombi","x":"Links ein Knochen (冎), rechts ein Messer (刂 = 刀). Mit dem Messer Fleisch vom Knochen lösen, also zerlegen und trennen; daraus „getrennt, anders“.","s":2,"p":[["冎","Knochen","b"],["刂","Messer","b"]],"n":"Der linke Teil sieht heute aus wie 口 über 力; das ist eine verformte Schreibung des Knochens 冎.","i":"os"},
"注":{"t":"laut","x":"氵 (Wasser) gibt den Sinnbereich „Flüssigkeit“, 主 den Klang; altchinesisch klangen beide ähnlich (heute 主 シュ, 注 チュウ). Grundbedeutung „gießen“; übertragen „die Aufmerksamkeit auf etwas richten“ (注意).","s":2,"p":[["氵","Wasser","b"],["主","Herr, Haupt-","l"]]},
"洋":{"t":"laut","x":"氵 (Wasser) gibt den Sinnbereich, 羊 (Schaf) nur den Klang: 羊 ヨウ → 洋 ヨウ. Gemeint war das weite Meer. „Westlich“ (西洋, 洋服) bedeutet eigentlich „von jenseits des Ozeans“.","s":2,"p":[["氵","Wasser","b"],["羊","Schaf","l"]],"i":"s"},
"特":{"t":"laut","x":"牛 (Rind) gibt den Sinnbereich, 寺 (Tempel) den Klang (altchinesisch ähnlich; vgl. 等 トウ). Ursprünglich bezeichnete 特 einen Stier; die heutige Bedeutung „besonders“ hat sich daraus entwickelt.","s":2,"p":[["牛","Rind","b"],["寺","Tempel","l"]],"n":"Noch früher schrieb man das Wort mit 牛 + 戠; später wurde dieser Klangteil durch 寺 ersetzt."},
"意":{"t":"zeichen","x":"Ursprung ist 言 (sprechen) mit einer Markierung in der Mitte: ein Hinweiszeichen für „Gedanke, Meinung“. Später kam 心 (Herz) hinzu. Der obere Teil wird heute wie 音 geschrieben, hat mit „Klang“ aber nichts zu tun.","s":1,"p":[["音","eigentlich 言 mit Markierung","b"],["心","Herz","b"]],"n":"Oft liest man „der Klang (音) des Herzens (心)“. Das geht auf das alte Wörterbuch 説文解字 zurück; nach heutigem Befund ist der obere Teil ein abgewandeltes 言.","i":"bs"},
"味":{"t":"laut","x":"口 (Mund) gibt den Sinnbereich, 未 den Klang: 未 ミ → 味 ミ. Gemeint ist das, was man im Mund schmeckt: der Geschmack.","s":2,"p":[["口","Mund","b"],["未","noch nicht","l"]]},
"勉":{"t":"laut","x":"力 (Kraft) gibt den Sinnbereich „sich anstrengen“, 免 den Klang: 免 メン → 勉 ベン. Die Bedeutung war von Anfang an „sich bemühen, sich anstrengen“.","s":2,"p":[["免","befreien","l"],["力","Kraft","b"]],"i":"s"},
"旅":{"t":"kombi","x":"Unter einer Fahne (㫃, heute 方 mit dem Haken darüber) stehen Menschen (从) in einer Reihe: eine Truppe unter ihrem Feldzeichen. Ursprünglich hieß 旅 „Truppenverband“; daraus „unterwegs sein, reisen“.","s":2,"p":[["㫃","Fahne","b"],["从","zwei Menschen","b"]],"n":"Der Teil unter dem Haken rechts sieht heute nicht mehr wie zwei Menschen aus; er ist aus 从 verformt.","i":"obs"},
"員":{"t":"leih","x":"Oben ein Kreis (〇), unten ein runder Bronzekessel (鼎, später zu 貝 verformt): ein Zeichen für „rund“ (heute 圓, vgl. 円). Es wurde für ein ähnlich klingendes Wort „Anzahl Leute“ ausgeliehen; daraus „Mitglied, Angestellter“.","s":2,"p":[["口","Kreis (〇)","l"],["貝","eigentlich 鼎 Kessel","b"]],"n":"Das alte Wörterbuch 説文解字 deutete es als 口 + 貝 (Muschel, Geld). Die ältesten Schriftformen zeigen aber, dass weder Mund noch Muschel gemeint sind.","i":"obs"},
"動":{"t":"laut","x":"力 (Kraft) gibt den Sinnbereich, 重 den Klang; altchinesisch klangen beide ähnlich (heute 重 ジュウ/チョウ, 動 ドウ). Bedeutung: sich bewegen, etwas bewegen.","s":2,"p":[["重","schwer","l"],["力","Kraft","b"]],"n":"Oft liest man „mit Kraft (力) etwas Schweres (重) bewegen“. Das ist eine Eselsbrücke; 重 steht hier für den Klang.","i":"obs"},
"悪":{"t":"laut","x":"Alte Form 惡: 心 (Herz, Gefühl) gibt den Sinnbereich, 亞 den Klang: 亞 ア → 惡 アク/オ. Grundbedeutung „hassen, verabscheuen“ (Lesung オ, vgl. 嫌悪) und „schlecht“ (アク). Heute steht statt 亞 die Kurzform 亜.","s":2,"p":[["亜","Kurzform von 亞","l"],["心","Herz","b"]],"n":"Manchmal wird 亞 als Grabkammer gedeutet und das Zeichen als „bedrücktes Herz“ erklärt. Nach heutigem Stand ist 亞 hier nur Klangteil.","a":"惡","i":"s"},
"族":{"t":"kombi","x":"Unter einer Fahne (㫃, heute 方 mit dem Haken darüber) ein Pfeil (矢): Krieger, die sich unter demselben Feldzeichen sammeln. Daraus „Gruppe, Sippe, Familie“.","s":2,"p":[["㫃","Fahne","b"],["矢","Pfeil","b"]],"i":"obs"},
"着":{"t":"leih","x":"着 ist eine abgewandelte Schreibung von 著 (oben 艹 → 䒑, unten 日 → 目). 著 selbst ist eine Nebenform von 箸 (Essstäbchen: 竹 + Klangteil 者), bei der 竹 zu 艹 verkürzt wurde; das Zeichen wurde für andere, ähnlich klingende Wörter ausgeliehen. In Japan dient 着 für „anziehen, ankommen“, 著 für „verfassen, auffallend“.","s":1,"p":[["𦍌","verformtes Oberteil von 著","f"],["目","verformtes 日","f"]],"n":"Oft liest man 著 als Gras (艹) + 者. Schreibungen aus der Han-Zeit zeigen aber, dass oben ursprünglich 竹 stand. Der obere Teil von 着 erinnert an 羊 (Schaf), hat damit aber nichts zu tun."},
"野":{"t":"laut","x":"Zuerst ein Bild aus Wald (林) und Erde (土): offenes Land draußen. Dann kam 予 als Klangteil dazu (予 ヨ → 野 ヤ), und 林 wurde durch 田 (Feld) ersetzt. 田 über 土 sieht heute wie 里 aus.","s":2,"p":[["里","eigentlich 田 Feld + 土 Erde","b"],["予","im Voraus","l"]],"n":"Oft liest man „Dorf (里) + 予“. Tatsächlich wurden 土 und 田 zu verschiedenen Zeiten hinzugefügt; das Dorf-Zeichen 里 steckt ursprünglich nicht darin."},
"風":{"t":"leih","x":"Das Wort „Wind“ schrieb man zuerst mit dem Bild des Phönix (鳳), dessen Name ähnlich klang. Später kam 凡 als Klangteil dazu (heute oben als 几 sichtbar), und eine Schmuckfeder des Phönix wurde zu 虫 verformt.","s":1,"p":[["凡","alle, gewöhnlich","l"],["虫","verformte Phönixfeder","f"]],"n":"Mit Insekten (虫) hat der Wind nichts zu tun; so deutete es aber schon 説文解字. Eine zweite ernsthafte Deutung sieht im Zeichen ursprünglich ein Insektennest, „Wind“ wäre dann eine Ausleihe.","i":"obs"},
"新":{"t":"leih","x":"斤 (Axt) gibt den Sinn „hacken“, 辛 den Klang (辛 シン → 新 シン); später kam 木 (Holz) dazu und verschmolz mit 辛 zu 亲. Gemeint war „Brennholz schlagen“ (heute 薪). Für das gleich klingende Wort „neu“ wurde das Zeichen ausgeliehen.","s":2,"p":[["亲","辛 (Meißel) + 木 (Holz)","l"],["斤","Axt","b"]],"n":"Oft liest man „frisch mit der Axt geschlagenes Holz ist neu“. Nach heutigem Stand ist „neu“ aber eine reine Lautausleihe.","i":"obs"},
"問":{"t":"laut","x":"口 (Mund) gibt den Sinnbereich „sprechen“, 門 (Tor) nur den Klang: 門 モン → 問 モン. Bedeutung: fragen.","s":2,"p":[["門","Tor","l"],["口","Mund","b"]],"n":"Oft liest man „am Tor (門) mit dem Mund (口) nachfragen“. Das ist eine Eselsbrücke; 門 steht hier für den Klang.","i":"s"},
"銀":{"t":"laut","x":"釒 (Metall, = 金) gibt den Sinnbereich, 艮 den Klang (altchinesisch ähnlich; vgl. 根 コン, 限 ゲン). Gemeint ist das weiße Metall: Silber.","s":2,"p":[["釒","Metall","b"],["艮","stillstehen","l"]],"i":"s"},
"題":{"t":"laut","x":"頁 (Kopf) gibt den Sinnbereich, 是 den Klang (altchinesisch ähnlich; vgl. 提 テイ). Ursprünglich hieß 題 „Stirn“; die Bedeutung „Titel, Thema“ kam erst später durch Ausleihe hinzu.","s":2,"p":[["是","dies, richtig","l"],["頁","Kopf","b"]],"i":"s"},
"館":{"t":"laut","x":"飠 (Essen) gibt den Sinnbereich, 官 den Klang: 官 カン → 館 カン. Gemeint war eine Unterkunft für Gäste, in der man auch verpflegt wurde; daraus „Gebäude, Halle“.","s":2,"p":[["飠","Essen","b"],["官","Amt, Beamter","l"]],"n":"Zuerst schrieb man das Wort mit 宛; dann kam 食 dazu, und wegen eines Lautwandels wurde 宛 später durch 官 ersetzt.","i":"s"},
"駅":{"t":"laut","x":"Alte Form 驛: 馬 (Pferd) gibt den Sinnbereich, 睪 den Klang (vgl. 譯 → 訳 ヤク). Gemeint war die Poststation, an der Boten die Pferde wechselten; heute der Bahnhof. In Japan ersetzte man 睪 wie bei 釋 → 釈 durch das einfachere 尺.","s":2,"p":[["馬","Pferd","b"],["尺","Längenmaß (statt 睪)","l"]],"a":"驛","i":"s"},
"料":{"t":"kombi","x":"Reis (米) und eine Schöpfkelle (斗) als Hohlmaß: Getreide abmessen. Ursprünglich hieß 料 „messen, abschätzen“; die heutigen Bedeutungen „Material“ und „Gebühr“ haben sich daraus entwickelt.","s":2,"p":[["米","Reis","b"],["斗","Schöpfkelle","b"]],"i":"bs"},
"映":{"t":"laut","x":"日 (Sonne) gibt den Sinnbereich Licht an: „scheinen, sich spiegeln“. 央 steuert nur den Klang bei. Dieselbe Klanggruppe steckt in 英 エイ.","s":2,"p":[["日","Sonne","b"],["央","Mitte","l"]]},
"私":{"t":"laut","x":"禾 (Getreidepflanze) ist der Sinnteil, 厶 gibt den Klang (厶 シ → 私 シ). Ursprünglich schrieb man das Wort „privat, eigen“ nur mit 厶; 禾 kam erst später dazu.","s":1,"p":[["禾","Getreide","b"],["厶","privat","l"]],"n":"Nach einer anderen Deutung bezeichnete 私 zuerst eine Getreidesorte und wurde dann für „ich, privat“ ausgeliehen. Woher die Form 厶 selbst kommt, ist unklar."},
"帰":{"t":"kombi","x":"Die alte Form 歸 verbindet 𠂤 (Truppe, Heer) mit 帚 (Besen); auf Bronzen kam 止 (Fuß, gehen) dazu. Eine Deutung: Das Heer fegt den Feind weg und kehrt heim. 帰 ist eine aus der Schreibschrift verkürzte Form, in der 𠂤 und 止 zu zwei Strichen links wurden.","s":1,"p":[["𠂤","Truppe","b"],["帚","Besen","b"],["止","Fuß","b"]],"n":"Manche sehen 𠂤 oder 帚 auch als Klangteil; wie genau die Teile „heimkehren“ ergeben, ist nicht sicher geklärt.","a":"歸","i":"obs"},
"春":{"t":"laut","x":"Alte Formen zeigen 艹 (Gras) und 日 (Sonne) als Sinnteile und 屯 (keimender Spross) als Klangteil. Zuerst wurde 屯 allein für „Frühling“ ausgeliehen; Gras und Sonne kamen zur Unterscheidung dazu.","s":2,"p":[["艹","Gras","b"],["屯","Spross","l"],["日","Sonne","b"]],"n":"Im heutigen Zeichen sind 艹 und 屯 zu dem oberen Teil 𡗗 verschmolzen, deshalb erkennt man sie nicht mehr. Die ältere Anordnung bewahrt die Nebenform 萅.","i":"os"},
"昼":{"t":"kombi","x":"Die alte Form 晝 besteht aus 聿 (Hand, die einen Stab/Pinsel hält) und 日 (Sonne); schon alte Texte verwenden sie für „Tag, Tageszeit“. 昼 ist eine Kurzform aus der Schreibschrift, in der 聿 zu 尺 wurde.","s":1,"p":[["聿","Hand mit Pinsel","b"],["日","Sonne","b"]],"n":"Was 聿 hier bedeutet, ist unklar: Eine Deutung sieht darin das Einteilen der Zeit, eine andere hält 聿 für einen Klangteil.","a":"晝"},
"秋":{"t":"bild","x":"Orakelknochen zeigen ein Insekt (Grille oder Heuschrecke), das im Herbst auftritt. Später kamen 火 (Feuer) und 禾 (Getreide) dazu, und das Insekt fiel schließlich weg – übrig blieb 禾 + 火.","s":2,"p":[["禾","Getreide","b"],["火","Feuer","f"]],"n":"Oft liest man „Getreide + Feuer: nach der Ernte werden die Felder abgebrannt“. Die alten Formen zeigen aber, dass das Zeichen von einem Insektenbild ausgeht; 火 ist ein Überrest. Das 龜 in der Nebenform 龝 ist dieses Insekt, keine Schildkröte.","i":"os"},
"計":{"t":"laut","x":"訁 (Wort, sprechen) gibt den Sinnbereich an, 十 den Klang. Das Wort bedeutete „berechnen, planen“.","s":1,"p":[["訁","Wort","b"],["十","zehn","l"]],"n":"Oft liest man „Wort + zehn = zählen“ (so schon das alte Wörterbuch Shuowen). Neuere Forschung sieht darin eine Fehldeutung: 十 dient als Klangteil.","i":"s"},
"建":{"t":"bild","x":"Die alten Formen zeigen eine Hand, die einen Pfahl oder Pfosten in einen Untergrund setzt: „aufstellen, errichten“. Der linke Teil war ursprünglich ein Winkel und wurde später zu 廴.","s":2,"p":[["廴","Sockel (Form)","f"],["聿","Hand mit Pfahl","f"]],"n":"Das Shuowen zerlegt 建 in 聿 (Pinsel) und 廴 (gehen). Die Orakelknochen- und Bronzeformen zeigen aber, dass das Zeichen mit beiden nichts zu tun hat; nur die Hand ist in 聿 noch erkennbar.","i":"obs"},
"英":{"t":"laut","x":"艹 (Pflanze) ist der Sinnteil, 央 gibt den Klang. Das Wort bedeutete „Blüte“, daraus „hervorragend“. Für „England“ wird es nur wegen des Klangs (英吉利) verwendet. Gleiche Klanggruppe wie 映 エイ.","s":2,"p":[["艹","Gras","b"],["央","Mitte","l"]],"n":"Früher deutete man 央 („Mitte“) zugleich als Sinnteil. Das gilt heute als Fehlanalyse: 央 gibt nur den Klang."},
"飯":{"t":"laut","x":"飠 (Essen) gibt den Sinnbereich an, 反 den Klang (反 ハン → 飯 ハン). Das Wort bedeutete „essen“ und „gekochtes Getreide“.","s":2,"p":[["飠","Essen","b"],["反","umkehren","l"]],"n":"Früher schrieb man 飰 mit 卞 als Klangteil; nach einem Lautwandel wurde der Klangteil durch das besser passende 反 ersetzt.","i":"bs"},
"曜":{"t":"laut","x":"日 (Sonne, Licht) ist der Sinnteil, 翟 gibt den Klang. 曜 ist eine Nebenform von 燿/耀 „leuchten“, bei der nur der Sinnteil getauscht wurde. Heute steht es vor allem in den Wochentagen (月曜日 usw.), die nach den leuchtenden Himmelskörpern benannt sind.","s":2,"p":[["日","Sonne","b"],["翟","Fasanenfedern","l"]]},
"品":{"t":"kombi","x":"Dreimal 口: Die drei Kästchen stehen für viele verschiedene Dinge. Daraus „viel, Ware, Art“.","s":1,"p":[["口","Ding (Zeichen)","b"]],"n":"Oft liest man, die drei 口 seien Münder oder Gefäße. Für die Gefäß-Deutung gibt es keinen Beleg; vielleicht ist 口 hier nur ein Füllzeichen ohne eigene Bedeutung.","i":"obs"},
"急":{"t":"laut","x":"心 (Herz, Gefühl) ist der Sinnteil, der obere Teil ist eine veränderte Form von 及 und gibt den Klang (及 キュウ → 急 キュウ). Bedeutung: „drängen, sich beeilen“.","s":2,"p":[["刍","aus 及: erreichen","l"],["心","Herz","b"]],"n":"Der obere Teil sieht heute aus wie 刍, stammt aber von 及 ab.","i":"s"},
"真":{"t":"laut","x":"Auf Bronzen: 貝 (Muschelgeld, Wertsache) als Sinnteil und 𠂈 (Urform von 顛 „kopfüber“) als Klangteil. Wohl zuerst „kostbar, selten“ (heute 珍); später für das gleich klingende Wort „wahr, echt“ ausgeliehen. Der untere Teil hat sich stark verändert.","s":1,"p":[["貝","Muschel, Wert","b"],["𠂈","kopfüber","l"]],"n":"Das Shuowen deutet 真 als Unsterblichen, der zum Himmel aufsteigt; andere sehen einen Toten. Beides passt nicht zu den Bronzeformen. Ein Orakelknochenzeichen aus 匕 (Löffel) + 鼎 (Dreifuß) ist wohl ein anderes Zeichen (eher 煮); erst später trat in 真 manchmal 鼎 an die Stelle von 貝.","a":"眞"},
"堂":{"t":"laut","x":"土 (Erde, Lehm) gibt den Sinnbereich an, 尚 den Klang. Gemeint war ein großer, erhöhter Saal oder Hauptbau, wie man ihn auf einem Erdsockel errichtete.","s":2,"p":[["尚","hoch, schätzen","l"],["土","Erde","b"]],"i":"bs"},
"試":{"t":"bild","x":"Orakelknochen zeigen einen Menschen, der einen Stab oder eine Hellebarde hält und dabei spricht (Zunge/Mund). Das Wort bedeutete wohl „beaufsichtigen“; die Form wurde später entstellt und sieht heute wie 言 + 式 aus.","s":0,"p":[["訁","sprechen","f"],["式","Form","f"]],"n":"Üblich ist die Erklärung 言 (Wort) + Klangteil 式 (式 シキ → 試 シ), so schon im alten Wörterbuch Shuowen. Zu den ältesten Formen passt das aber nicht."},
"借":{"t":"laut","x":"亻 (Mensch) gibt den Sinnbereich an, 昔 den Klang (昔 シャク → 借 シャク). Bedeutung: „leihen, borgen“.","s":2,"p":[["亻","Mensch","b"],["昔","früher","l"]],"i":"s"},
"験":{"t":"laut","x":"In der alten Form 驗 ist 馬 (Pferd) der Sinnteil und 僉 der Klangteil. Zuerst war es der Name einer Pferdeart; später wurde es für „prüfen, nachweisen“ ausgeliehen. Im heutigen 験 ist 僉 zu 㑒 verkürzt – wie in 検 ケン, 険 ケン, 剣 ケン.","s":1,"p":[["馬","Pferd","b"],["㑒","alle","l"]],"a":"驗","i":"s"},
"質":{"t":"laut","x":"貝 (Muschelgeld, Wertsache) gibt den Sinnbereich an, 斦 den Klang. Zuerst bedeutete es „Pfand“ (vgl. 質屋 Pfandhaus); später wurde es für „Inhalt, Beschaffenheit“ ausgeliehen.","s":1,"p":[["斦","zwei Äxte","l"],["貝","Muschel, Wert","b"]],"n":"Das Shuowen sieht 斦 + 貝 als Sinnverbindung; schon der Gelehrte Zhu Junsheng hielt 斦 aber für einen Klangteil.","i":"s"},
"貸":{"t":"laut","x":"貝 (Muschelgeld, Wertsache) ist der Sinnteil, 代 gibt den Klang (代 タイ → 貸 タイ). Zuerst hieß es „geben, schenken“, später „verleihen“.","s":2,"p":[["代","ersetzen","l"],["貝","Muschel, Wert","b"]],"i":"s"},
"市":{"t":"laut","x":"Orakelknochen und Bronzen zeigen oben 之/止 als Klangteil (止 シ → 市 シ) und darunter einen Sinnteil, der heute wie 巾 aussieht. Später wurde das Zeichen für „Markt“ verwendet, daraus „Stadt“.","s":1,"p":[["止","Fuß","l"],["巾","Tuch (Form)","f"]],"n":"Der untere Teil wird verschieden gelesen: als 兮 („lebhaft, geschäftig“) oder als 平. Was das Zeichen ursprünglich bedeutete, ist unklar.","i":"bs"},
"次":{"t":"leih","x":"Bild eines Menschen, der Luft ausstößt (欠 Mensch mit offenem Mund, daneben Striche für Atem). Vielleicht stand es zuerst für „seufzen“ (heute 咨). Später wurde es für das gleich klingende Wort „nächster, folgen“ ausgeliehen.","s":2,"p":[["冫","Atem","b"],["欠","Mensch mit offenem Mund","b"]],"n":"Das Shuowen erklärt 次 als 欠 + Klangteil 二; die alten Formen widerlegen das. Je nach Schrift wird der Atem als 冫 oder 二 geschrieben.","i":"obs"},
"雪":{"t":"laut","x":"Ursprünglich 雨 (Regen, Wetter) als Sinnteil und 彗 als Klangteil. Später wurde 彗 zu seinem unteren Teil ⺕ verkürzt, so entstand 雪.","s":2,"p":[["雨","Regen","b"],["⺕","aus 彗: Besen","l"]],"n":"Oft liest man „Schnee, den man mit dem Besen (彗) zusammenfegt“, oder man verbindet 雪 mit 羽 (Feder). Beides gilt als Fehldeutung: 彗 gibt nur den Klang.","i":"os"},
"所":{"t":"unklar","x":"Rechts steht sicher 斤 (Axt). Der linke Teil ist umstritten: Das alte Wörterbuch Shuowen sieht 戸 als Klangteil und deutet das Zeichen als Geräusch beim Holzfällen; eine neuere Deutung hält ihn für die Urform von 肩 (Schulter). Wie es zu „Ort“ kam, ist offen.","s":0,"p":[["戸","unklar","f"],["斤","Axt","b"]],"n":"Die Bedeutung „Tür“ von 戸 spielt hier in keiner Deutung eine Rolle – auch wenn der linke Teil heute wie 戸 aussieht.","i":"bs"},
"好":{"t":"kombi","x":"Das Zeichen besteht aus 女 (Frau) und 子 (Kind). Meist wird es als Mutter mit Kind gedeutet – daraus „gut“ und „mögen“. Warum diese Teile genau „gut“ ergeben, ist aber nicht gesichert.","s":0,"p":[["女","Frau","b"],["子","Kind","b"]],"n":"Manche halten die Herkunft für unklar; eine Theorie sieht 子 als Sinnteil und einen verkürzten Klangteil. Das Bild einer Frau, die ein Kind hochhebt, beruht auf einer Orakelknochenform, die vielleicht gar nicht 好 ist.","i":"obs"},
"昔":{"t":"laut","x":"日 „Tag“ gibt den Sinnbereich: vergangene Tage. Der obere Teil war früher ein eigenes Zeichen, das eine runzlige, raue oder verflochtene Oberfläche zeigte; hier liefert er nur den Klang (alt-chinesisch etwa *sak, heute セキ).","s":2,"p":[["日","Sonne, Tag","b"],["龷","runzlig, rau","l"]],"n":"Oft liest man „Fleischstreifen, die in der Sonne trocknen“ (so das alte Wörterbuch Shuowen). Die heutige Forschung sieht im oberen Teil aber einen Klangteil.","i":"obs"},
"神":{"t":"laut","x":"In den ältesten Inschriften schrieb man „Gott“ einfach mit 申, dem Bild eines Blitzes: Den unberechenbaren Blitz hielt man für göttlich. Später kam 礻 (Altar) als Sinnteil dazu. 申 gibt auch den Klang: 申 シン → 神 シン.","s":2,"p":[["礻","Altar, Gottheit","b"],["申","Blitz","l"]],"i":"bs"},
"働":{"t":"laut","x":"Ein in Japan geschaffenes Zeichen (国字). Zuerst schrieb man „arbeiten“ (はたらく) einfach mit 動; um es von うごく „sich bewegen“ zu unterscheiden, setzte man 亻 davor. 動 gibt den Klang: 動 ドウ → 働 ドウ. Die Lesung はたらき ist seit 1503 belegt.","s":2,"p":[["亻","Mensch","b"],["動","bewegen","l"]],"n":"Oft liest man „ein Mensch, der sich bewegt, arbeitet“. Alte japanische Schriften zeigen aber, dass 亻 nur zur Unterscheidung von 動 hinzukam."},
"連":{"t":"kombi","x":"Ein Wagen 車 und 辶 „gehen“: ein von Menschen gezogener Handwagen. Das Wort für „aneinanderreihen, verbinden“ klang ähnlich und wurde mit demselben Zeichen geschrieben; so kam es zu „Reihe, verbinden, mitnehmen“.","s":2,"p":[["辶","gehen","b"],["車","Wagen","b"]]},
"分":{"t":"kombi","x":"八 zeigt zwei Teile, die auseinandergehen, 刀 das Messer als Werkzeug: mit dem Messer zerteilen. Daraus „teilen, Teil“ und später auch „Minute“ als Teil der Stunde.","s":2,"p":[["八","auseinander","b"],["刀","Messer","b"]],"i":"obs"},
"々":{"t":"kurz","x":"Kein eigentliches Kanji, sondern ein Wiederholungszeichen: Es wiederholt das Kanji davor (人々, 時々). Nach einer Deutung entstand es aus der schnell geschriebenen Form von 仝, einer Nebenform von 同 „gleich“.","s":1},
"才":{"t":"leih","x":"Bildzeichen eines hölzernen Gegenstands, wohl eines Pflocks oder Riegels. Wegen des ähnlichen Klangs lieh man es früh für das Wort „Begabung“ aus. In Japan dient es außerdem als einfache Schreibung für 歳 „… Jahre alt“.","s":1,"n":"Oft liest man „ein Spross, der aus der Erde bricht“ (Shuowen). Die ältesten Schriftformen widerlegen das.","i":"obs"},
"王":{"t":"bild","x":"Bild einer großen Zeremonialaxt mit breiter Klinge, die nach unten zeigt. Die Axt war ein Zeichen königlicher Macht; daraus „König“.","s":2,"n":"Oft liest man: drei Striche für Himmel, Mensch und Erde, verbunden durch den König. Die ältesten Schriftformen zeigen aber eine Axt; die Deutung ist nachträglich erfunden.","i":"obs"},
"石":{"t":"bild","x":"Der obere Teil zeigt eine Steinplatte, wie man sie für den Klangstein (磬, ein altes Schlaginstrument) benutzte. 口 kam später nur als Schmuckelement dazu und bedeutet hier nicht „Mund“.","s":2,"p":[["丆","Klangstein","b"],["口","Zierteil","f"]],"n":"Oft liest man „ein Stein (口) unter einer Klippe (厂)“, so schon das Shuowen. Die Orakelknochen zeigen, dass das nicht stimmt.","i":"obs"},
"内":{"t":"kombi","x":"入 „hineingehen“ unter einem Dach 冂: ins Haus hineingehen bzw. hineinbringen. Daraus wurde „innen, innerhalb“. In der heutigen Form ist aus 入 ein 人 geworden; die alte Form 內 zeigt noch 入.","s":1,"p":[["冂","Haus, Umhüllung","b"],["入","hineingehen","b"]],"n":"Nach einer anderen Deutung ist 入 der Klangteil (ニュウ ~ ナイ); das Zeichen hätte zuerst „hineingehen“ bedeutet und sei dann für das ähnlich klingende Wort „innen“ ausgeliehen worden.","a":"內"},
"太":{"t":"zeichen","x":"Abgeleitet von 大 „groß“: In alten Inschriften stand 大 auch für „sehr groß, dick“. Um die beiden Wörter zu unterscheiden, setzte man später einen Punkt bzw. kleinen Strich dazu – so entstand 太.","s":2,"p":[["大","groß","b"],["丶","Unterscheidungspunkt","f"]]},
"引":{"t":"kombi","x":"Ein Bogen 弓 mit einem kurzen Strich daneben, der das Spannen der Sehne andeutet: „den Bogen ziehen“. Daraus allgemein „ziehen“.","s":2,"p":[["弓","Bogen","b"],["丨","Markierungsstrich","f"]],"n":"Eine neuere, weniger sichere Deutung: Der Strich markiert die Krümmung des Bogens; die Bedeutung „ziehen“ wäre erst durch Ausleihen entstanden.","i":"bs"},
"他":{"t":"laut","x":"Abgewandelte Form des älteren 佗: 亻 „Mensch“ als Sinnteil und 它 als Klangteil (它 タ → 他 タ). In der Schrift wurde 它 später zu 也 verändert.","s":2,"p":[["亻","Mensch","b"],["也","(aus 它 Schlange)","l"]]},
"号":{"t":"kombi","x":"Ein Mund 口 und 丂, das den ausgestoßenen Atem andeutet: „laut rufen, schreien“. Daraus „Ruf, Name, Zeichen“ und im Japanischen „Nummer“. Die alte Form 號 setzt noch 虎 „Tiger“ dazu.","s":0,"p":[["口","Mund","b"],["丂","ausströmender Atem","b"]],"n":"Nach anderer Deutung zeigte das älteste Zeichen ein schreiendes Kind; der untere Teil wurde später zu 丂 umgeformt und dient seitdem auch als Klangteil.","a":"號","i":"s"},
"平":{"t":"unklar","x":"Die Herkunft ist ungeklärt. Das älteste Zeichen besteht aus 丂 und zwei oder drei Punkten. Eine Deutung: ein Schlagstock mit Spritzern (Wirkung des Schlags), später für das Wort „flach, eben“ ausgeliehen. Andere sehen darin flach treibende Wasserpflanzen oder eine Waage.","s":0,"n":"Das Shuowen erklärt 八 + 亏 (ausgestoßener Atem) als „ruhig fließende Rede“; auch das ist nicht gesichert.","i":"bs"},
"打":{"t":"laut","x":"扌 „Hand“ gibt den Sinnbereich, 丁 den Klang (alt-chinesisch ähnlich wie 丁 テイ): mit der Hand schlagen. Die japanische Lesung ダ geht auf eine spätere chinesische Dialektaussprache zurück.","s":2,"p":[["扌","Hand","b"],["丁","Nagel","l"]],"i":"s"},
"申":{"t":"leih","x":"Bild eines zuckenden Blitzes. Es war das ursprüngliche Zeichen für 電 „Blitz“ und 神 „Gott“. Für das gleich klingende Wort „sagen, melden“ (heute 申す) wurde es ausgeliehen.","s":2,"i":"obs"},
"礼":{"t":"laut","x":"Alte Form 禮: 礻 „Altar“ als Sinnteil und 豊 (ein Gefäß für Opfergaben) als Klangteil (レイ). Ursprünglich schrieb man das Wort nur mit 豊. 礼 geht auf eine sehr alte Nebenform zurück (schon im Shuowen); darin ist 豊 durch 乚 ersetzt, das man als ausgetauschten Klangteil 乙 deutet.","s":2,"p":[["礻","Altar","b"],["豊","Ritualgefäß","l"]],"n":"Das 豊 in 禮 ist nicht das heutige 豊 „reich“ (alte Form 豐), sondern ein anderes, ähnlich aussehendes Zeichen.","a":"禮","i":"obs"},
"耳":{"t":"bild","x":"Bild eines menschlichen Ohrs.","s":2,"i":"obs"},
"交":{"t":"bild","x":"Nach neuerer Forschung ist 交 eine Nebenform von 爻: Das Zeichen zeigt sich kreuzende Linien und stand für das Wort „sich kreuzen, sich mischen“. Daraus auch „Umgang, Austausch“.","s":0,"n":"Oft liest man „ein Mensch mit gekreuzten Beinen“ (Shuowen). Die alten Schriftzeichen, die man dafür hielt, liest man heute aber als 黃.","i":"bs"},
"光":{"t":"kombi","x":"Feuer 火 über dem Kopf eines knienden Menschen: das Feuer leuchtet. Daraus „Licht, leuchten“. Heute sind beide Teile verkürzt: Das Feuer ist zu ⺌ geworden, der Mensch zu 兀.","s":2,"p":[["⺌","Feuer","b"],["兀","kniender Mensch","b"]],"i":"obs"},
"回":{"t":"bild","x":"Ein Kästchen in einem Kästchen, ursprünglich wohl eine Spirale oder ein Wirbel: „sich drehen, kreisen“. Daraus auch „Runde, …mal“.","s":1,"n":"Nach anderer Deutung zeigt das Bild ein Umschließen (wie 囲); für „sich drehen“ wäre es erst ausgeliehen worden.","i":"bs"},
"当":{"t":"laut","x":"Alte Form 當: 田 „Feld“ als Sinnteil und 尚 als Klangteil. Gemeint waren einander gegenüberliegende Felder; das Zeichen schrieb das Wort „treffen, zutreffen, entsprechen“ (あたる). 当 ist eine Kurzform aus der Schreibschrift: Vom oberen 尚 bleibt ⺌, 田 wird zu ヨ.","s":2,"p":[["田","Feld","b"],["尚","noch, schätzen","l"]],"a":"當","i":"s"},
"米":{"t":"bild","x":"Bild von enthülsten Reiskörnern; der waagrechte Strich in der Mitte wird als Sieb gedeutet, mit dem die Körner gesiebt wurden. Mit 木 „Baum“ hat das Zeichen nichts zu tun.","s":2,"n":"Die Bedeutung „Amerika“ kommt vom japanischen Kürzel 米国; „Meter“ ist eine japanische Lehnschreibung.","i":"obs"},
"声":{"t":"laut","x":"Alte Form 聲: 耳 „Ohr“ als Sinnteil und 殸 (ein Klangstein, der angeschlagen wird) als Klangteil – ein Ohr hört den Ton. 声 behält davon nur den oberen linken Teil von 殸.","s":2,"p":[["殸","Klangstein anschlagen","l"],["耳","Ohr","b"]],"a":"聲","i":"os"},
"形":{"t":"laut","x":"彡 (Striche, Muster) gibt den Sinnbereich „Gestalt, Aussehen“ an. Links stand ursprünglich 井 in der Bedeutung „Gussform“ (Vorläufer von 型 ケイ) als Klangteil; dieses Bauteil hat sich später zu 开 verformt.","s":2,"p":[["开","Gussform (aus 井)","l"],["彡","Striche, Muster","b"]],"n":"Dieses 井 ist nicht das Brunnen-Zeichen, sondern ein eigenes Zeichen für die Gussform. Das alte Wörterbuch Shuowen hielt das verformte 幵 fälschlich für den Klangteil.","i":"s"},
"草":{"t":"laut","x":"艹 (Gras) gibt den Sinnbereich an, 早 liefert den Klang (早 ソウ → 草 ソウ). Ursprünglich schrieb man „Gras“ nur mit 艸; der Klangteil 早 kam später dazu.","s":2,"p":[["艹","Gras, Pflanze","b"],["早","früh","l"]],"i":"s"},
"化":{"t":"kombi","x":"Zwei Menschen: einer aufrecht (亻), einer kopfüber (匕). Das Umdrehen steht für Umkehrung und Veränderung – daher „sich verwandeln“.","s":2,"p":[["亻","Mensch","b"],["匕","umgedrehter Mensch","b"]],"n":"Das alte Wörterbuch Shuowen sah im rechten Teil zusätzlich einen Klangteil.","i":"obs"},
"両":{"t":"laut","x":"Die alte Form 兩 besteht aus zwei miteinander verbundenen 丙. 丙 liefert den Klang, die Verdopplung passt zur Bedeutung „zwei, beide“. 両 ist eine vereinfachte Form von 兩.","s":1,"p":[["丙","3. Himmelsstamm","l"]],"n":"Das alte Wörterbuch Shuowen erklärte 兩 anders (一 + 㒳). Manche bringen das Zeichen auch mit der alten Form von 更 in Verbindung, die zwei Wagen zeigt.","a":"兩"},
"全":{"t":"unklar","x":"Woher das Zeichen kommt, ist nicht geklärt. Die bekannten Deutungen passen nicht zu den alten Bronzeinschriften.","s":0,"n":"Oft liest man, das Zeichen zeige ein ganzes, makelloses Stück Jade (入 + 玉). Die Forschung hält diese und ähnliche Deutungen heute für unbelegt.","i":"s"},
"向":{"t":"leih","x":"Ein Haus 宀 und ein Mund 口: Stimmen hallen im Inneren wider. Das Zeichen war ursprünglich die Form für 響 „widerhallen“ und wurde später für das ähnlich klingende Wort „sich zuwenden“ ausgeliehen.","s":2,"p":[["宀","Haus","b"],["口","Mund","b"]],"n":"Oft liest man, das Zeichen zeige ein Fenster nach Norden und davon komme „Richtung“. Diese alte Deutung gilt heute als nicht verlässlich. Das Dach 宀 ist im heutigen Zeichen zu 丿 + 冂 verformt.","i":"obs"},
"曲":{"t":"bild","x":"Bild eines gebogenen, gekrümmten Gegenstands – daher „biegen, krumm“.","s":2,"n":"Im Chinesischen dient 曲 außerdem als Kurzform für das Zeichen 麴; das ist ein anderes Wort.","i":"obs"},
"直":{"t":"kombi","x":"Auf Orakelknochen ein Auge 目 mit einem senkrechten Strich darüber: ein gerader Blick – daher „gerade, direkt“. In Bronzeinschriften kam unten links der Teil 𠃊 hinzu.","s":1,"p":[["十","gerade Linie (aus 丨)","b"],["目","Auge","b"],["𠃊","späterer Zusatz","f"]],"n":"Die Bedeutung des Strichs ist nicht ganz sicher. In den Orakeltexten steht das Zeichen auch für ein Opfer und für „umhergehen, folgen“.","i":"obs"},
"活":{"t":"laut","x":"氵 (Wasser) gibt den Sinnbereich an, rechts stand ursprünglich der Klangteil 𠯑. Zuerst bezeichnete das Zeichen das Rauschen fließenden Wassers; „leben“ wurde erst später über den Klang ausgeliehen.","s":2,"p":[["氵","Wasser","b"],["舌","verformtes 𠯑","l"]],"n":"Der rechte Teil sieht heute aus wie 舌 „Zunge“, hat damit aber nichts zu tun: 𠯑 hat sich nur zu dieser Form verändert.","i":"s"},
"点":{"t":"laut","x":"Die alte Form 點 verbindet 黑 „schwarz“ als Sinnteil mit 占 als Klangteil; gemeint war ein schwarzer Fleck. In 点 ist von 黑 nur 灬 übrig geblieben, und 占 steht nun oben statt rechts.","s":2,"p":[["占","wahrsagen","l"],["灬","Rest von 黑","b"]],"n":"Die vier Punkte 灬 sehen aus wie das Feuer-Zeichen, stammen hier aber vom unteren Teil von 黑 „schwarz“.","a":"點","i":"s"},
"科":{"t":"laut","x":"斗 (Messgefäß) gibt den Sinnbereich an, 禾 liefert den Klang (禾 カ → 科 カ). Gemeint war „Sorte, Klasse“ – daraus wurde „Fach, Abteilung“.","s":2,"p":[["禾","Getreide","l"],["斗","Messgefäß","b"]],"n":"Oft liest man „Getreide mit dem Messbecher abmessen und einteilen“. Diese alte Deutung als reine Sinnverbindung gilt heute als falsch.","i":"s"},
"首":{"t":"bild","x":"Bild eines Kopfes. Auf Orakelknochen erscheint er mit oder ohne Haarschopf; die beiden Striche oben (丷) sind ein Rest der Haare. Ursprünglich „Kopf“, im Japanischen heute vor allem „Hals“.","s":1,"i":"obs"},
"欠":{"t":"laut","x":"Die Bedeutung „fehlen“ stammt von 缺: 缶 (Tontopf) gibt den Sinnbereich an, 夬 den Klang (夬 ケツ → 缺 ケツ); gemeint war ein Sprung im Gefäß. In Japan wird dafür heute das einfachere, eigentlich fremde Zeichen 欠 geschrieben.","s":1,"p":[["缶","Tontopf","b"],["夬","Klangteil ケツ","l"]],"n":"欠 selbst bedeutete „gähnen“ (Lesung ケン) und zeigt einen knienden Menschen mit offenem Mund. Als Bauteil steht es in 次, 吹, 歌, 飲 für Tätigkeiten mit dem Mund.","a":"缺","i":"s"},
"由":{"t":"unklar","x":"Was das Zeichen ursprünglich zeigt, ist ungeklärt; vorgeschlagen werden u. a. ein Gefäß, ein Helm oder junge Triebe an einem Baum. Für „Grund, Ursache“ wurde es wegen des Klangs ausgeliehen.","s":0,"i":"b"},
"民":{"t":"unklar","x":"Die alten Formen zeigen ein Auge mit einem kreuzförmigen Strich darüber oder hindurch. Was gemeint war, ist ungeklärt (vielleicht getrübte Sicht). Für „Volk“ wurde das Zeichen wegen des Klangs ausgeliehen.","s":0,"n":"Oft liest man, es zeige einen Sklaven, dem ein Auge ausgestochen wurde. Dafür gibt es keine Belege: Weder eine solche Strafe noch geblendete Sklaven sind für diese Zeit nachgewiesen.","i":"obs"},
"付":{"t":"kombi","x":"Ein Mensch 亻 und eine Hand 寸: jemandem etwas reichen. Ursprünglich bedeutete das Zeichen „geben, übergeben“; im Japanischen heute vor allem „anbringen, anhaften“.","s":2,"p":[["亻","Mensch","b"],["寸","Hand","b"]],"n":"Eine andere Deutung sieht darin eine Hand, die einen Menschen von hinten nach vorn stößt; das Zeichen wäre dann erst später für „geben“ ausgeliehen worden.","i":"bs"},
"失":{"t":"leih","x":"Auf Orakelknochen ein Fuß 止 mit Blutstropfen ringsum – wohl ein verletzter, gestürzter Mensch; gemeint war „stolpern“. Für das ähnlich klingende Wort „verlieren“ wurde das Zeichen ausgeliehen.","s":1,"n":"Früher deutete man es als „etwas fällt aus der Hand“ (手 + 乙), doch die alten Formen zeigen keine Hand. Auch die Deutung „eine tanzende Schamanin verliert sich“ ist unbelegt.","i":"os"},
"必":{"t":"leih","x":"Ursprünglich der Griff einer Waffe: aus Waffenzeichen wie 戈 wurde nur der Stiel übernommen, dazu kamen zwei Zierpunkte. Für das Wort „unbedingt“ wurde es wegen des Klangs ausgeliehen.","s":2,"n":"Mit 心 „Herz“ hat das Zeichen nichts zu tun, auch wenn es heute ähnlich aussieht. Die alte Erklärung 弋 + 八 gilt als falsch.","i":"bs"},
"未":{"t":"leih","x":"Ein Baum 木 mit zusätzlichen, dicht wachsenden Zweigen oben. Was genau gemeint war, ist umstritten (vielleicht „Ast, Stamm“). Für „noch nicht“ und als achtes der zwölf Erdzweige (十二支) wurde es ausgeliehen.","s":1,"n":"Nicht mit 末 verwechseln: Bei 未 ist der obere Querstrich kürzer, bei 末 länger.","i":"obs"},
"末":{"t":"zeichen","x":"Ein Baum 木, dessen Spitze mit einem zusätzlichen Querstrich hervorgehoben ist: die Baumspitze, das äußerste Ende. Das Gegenstück ist 本, bei dem der Strich unten die Wurzel markiert.","s":2,"p":[["木","Baum","b"],["一","Markierung","f"]],"n":"Nicht mit 未 verwechseln: Bei 末 ist der obere Querstrich länger.","i":"bs"},
"記":{"t":"laut","x":"訁 (Wort, Sprache) gibt den Sinnbereich an, 己 liefert den Klang (己 キ → 記 キ). Daraus: „aufschreiben, festhalten“.","s":2,"p":[["訁","Wort, Sprache","b"],["己","selbst","l"]],"i":"s"},
"組":{"t":"laut","x":"糹 (Faden, Seide) gibt den Sinnbereich an, 且 liefert den Klang (且 ソ → 組 ソ). Ursprünglich bedeutete das Zeichen „geflochtene Schnur“; heute steht es für „zusammensetzen“ und „Gruppe“.","s":2,"p":[["糹","Faden","b"],["且","ferner","l"]],"i":"bs"},
"船":{"t":"laut","x":"舟 (Boot) gibt den Sinnbereich an, der rechte Teil 㕣 liefert den Klang.","s":1,"p":[["舟","Boot","b"],["㕣","Klangteil","l"]],"i":"bs"},
"支":{"t":"unklar","x":"Häufige Deutung: eine Hand 又 hält einen Zweig (die Hälfte von 竹 „Bambus“) – also „Zweig“ (vgl. 枝). Gesichert ist das nicht. „Stützen“ ist eine spätere, über den Klang entlehnte Bedeutung.","s":0,"p":[["十","Zweig (halbes 竹)","b"],["又","Hand","b"]],"n":"Eine andere Deutung sieht eine Hand mit einem Lineal oder Zirkel (vgl. 規 „Maßstab“).","i":"s"},
"助":{"t":"laut","x":"力 (Kraft, starker Arm) gibt den Sinnbereich an, 且 liefert den Klang (且 ショ → 助 ジョ). Gemeint ist: mit seiner Kraft helfen.","s":2,"p":[["且","ferner","l"],["力","Kraft","b"]],"i":"s"},
"君":{"t":"laut","x":"Oben steht 尹 (Verwalter, Amtsträger) als Klangteil, darunter 口. In den ältesten Inschriften wurden 君 und 尹 oft füreinander verwendet. Das Zeichen schrieb das Wort für „Herrscher, Herr“, woraus auch die Anrede „du“ (きみ) wurde.","s":2,"p":[["尹","Verwalter","l"],["口","Mund","b"]],"n":"Das alte Wörterbuch Shuowen deutet 口 als „Befehle geben“. Ob 口 wirklich etwas bedeutet oder nur zur Zierde dasteht, ist unsicher.","i":"obs"},
"対":{"t":"leih","x":"Die alte Form 對 zeigte ein Grabwerkzeug (丵), Erde (土) und eine Hand (又, später 寸). Was das Bild ursprünglich meinte, ist unklar – vielleicht „Erde feststampfen“ oder „Land urbar machen“. Das Zeichen wurde dann für das Wort „antworten, entgegnen“ ausgeliehen. In 対 ist die linke Hälfte zu 文 verkürzt.","s":1,"p":[["文","verkürzte Form","f"],["寸","Hand","b"]],"n":"Das Shuowen erzählt, ein Han-Kaiser habe 口 (Mund) durch 士 ersetzt, weil viele Antworten unehrlich waren. Wahrscheinlicher ist 士 nur eine Verschreibung von 土 (Erde).","a":"對","i":"obs"},
"局":{"t":"laut","x":"尸 gibt den Sinnbereich, 句 den Klang (句 ク/コウ → 局 キョク; im Altchinesischen klangen beide ähnlich). Im heutigen Zeichen ist 句 unter dem 尸 zusammengedrückt und kaum noch zu erkennen.","s":2,"p":[["尸","Körper","b"],["句","Satz","l"]],"n":"Manche Wörterbücher deuten das Zeichen als Leiche mit angewinkelten Gliedern, die begraben wird. Das ist eine Volksetymologie.","i":"s"},
"役":{"t":"unklar","x":"Die Herkunft ist nicht geklärt. Heute sieht das Zeichen aus wie 彳 (gehen) + 殳 (Stabwaffe), aber die ältesten Formen vor der Qin-Zeit haben mit 殳 offenbar nichts zu tun.","s":0,"p":[["彳","gehen","f"],["殳","Stabwaffe","f"]],"n":"Oft liest man: jemand bewacht mit einer Waffe in der Hand die Grenze, daraus „Dienst, Aufgabe“. Diese Deutung geht auf das Shuowen zurück; die Forschung hält die Zerlegung in 彳 + 殳 heute für falsch.","i":"s"},
"投":{"t":"laut","x":"扌 (Hand) zeigt den Sinnbereich: etwas mit der Hand tun. 殳 gibt nur den Klang. Zusammen schreiben sie das Wort „werfen“.","s":2,"p":[["扌","Hand","b"],["殳","Stabwaffe","l"]],"n":"Eine Deutung als Sinnverbindung („mit der Hand eine Waffe schleudern“) gilt als falsch: 殳 ist hier nur Klangteil.","i":"s"},
"決":{"t":"laut","x":"氵 (Wasser) gibt den Sinnbereich, 夬 den Klang (夬 ケツ → 決 ケツ). Ursprünglich ging es um Hochwasser, das einen Damm durchbricht. Später wurde das Zeichen für das gleich klingende Wort „entscheiden, festlegen“ verwendet.","s":2,"p":[["氵","Wasser","b"],["夬","Klangteil","l"]],"n":"Manche erklären 夬 zusätzlich als Sinnteil; diese Zerlegung gilt als falsch – 夬 gibt nur den Klang.","i":"s"},
"馬":{"t":"bild","x":"Ein Pferd, hochkant gezeichnet, mit dem Kopf nach links und wehender Mähne. In Bronze-Inschriften wurde der Kopf oft zu einem Auge vereinfacht. Unten entstanden später vier Punkte (灬), die nichts mit Feuer (火) zu tun haben.","s":2,"n":"Oft heißt es, die vier Punkte seien die vier Beine. Das stimmt so nicht: Die ältesten Formen zeigen das Pferd auf nur zwei Beinen, erst beim späteren Umformen des Zeichens wurden daraus die vier Punkte.","i":"obs"},
"番":{"t":"laut","x":"田 (Feld) gibt den Sinnbereich, 釆 den Klang (釆 ハン → 番 バン). Das Zeichen schrieb wohl ursprünglich das Wort „Saat ausstreuen“ (heute 播). Später wurde es für „sich abwechseln“ ausgeliehen – daher „Reihenfolge, Nummer, Wache“.","s":1,"p":[["釆","unterscheiden","l"],["田","Feld","b"]],"n":"Das Shuowen sah darin einen Tierfußabdruck, ein anderer Gelehrter Samen auf einer offenen Hand. Beide deuten den unteren Teil nicht als Feld.","i":"bs"},
"絵":{"t":"laut","x":"Alte Form 繪: 糸 (Faden) gibt den Sinnbereich, 會 den Klang (會 カイ → 繪 カイ). Gemeint war eine farbenprächtige Stickerei; daraus wurde „Bild“. 絵 ist verkürzt, genau wie 會 zu 会.","s":2,"p":[["糹","Faden","b"],["会","treffen","l"]],"a":"繪","i":"s"},
"数":{"t":"laut","x":"Alte Form 數: 攴 (heute 攵, eine Hand mit Stock, steht für Tätigkeiten) gibt den Sinnbereich, 婁 den Klang. Das Wort bedeutete „zählen“. Die heutige Form 数 ist aus der Schreibschrift-Form von 數 verkürzt.","s":2,"p":[["娄","Kurzform von 婁","l"],["攵","schlagen, Hand","b"]],"a":"數"},
"具":{"t":"kombi","x":"Zwei Hände (廾) halten einen Dreifußkessel (鼎): Man bereitet ein Essen vor. Daraus die Bedeutung „bereitstellen, vorbereiten“. Der Kessel ist heute zu 目 verkürzt, die Hände sind zu dem Strich und den zwei Beinchen unten geworden.","s":2,"p":[["目","Kessel (鼎)","b"],["廾","beide Hände","b"]],"n":"Das Shuowen hielt den mittleren Teil für 貝 (Muschel, Geld) und bezog das Zeichen auf Geld. Das gilt als Irrtum.","i":"obs"},
"受":{"t":"laut","x":"Oben eine Hand (爫), unten eine Hand (又): Etwas wird von Hand zu Hand gereicht. Dazwischen stand ursprünglich 舟 (Boot) als Klangteil (舟 シュウ → 受 ジュ); heute ist es zu 冖 geschrumpft.","s":1,"p":[["爫","Hand","b"],["冖","Boot 舟 (verkürzt)","l"],["又","Hand","b"]],"n":"Eine andere Deutung zählt auch das Boot zum Sinn: alle drei Teile zusammen bedeuten „etwas übergeben“.","i":"obs"},
"和":{"t":"laut","x":"口 gibt den Sinnbereich, 禾 (Getreide) den Klang (禾 カ → 和 カ/ワ). Das Wort bedeutete „in Einklang bringen“. 和 ist eine Nebenform des älteren 龢, dessen Sinnteil die Flöte 龠 war – Harmonie wohl zunächst als Zusammenklang in der Musik.","s":2,"p":[["禾","Getreide","l"],["口","Mund","b"]],"n":"Deutungen als reine Sinnverbindung (etwa „Getreide im Mund“) gelten als falsch: 禾 gibt nur den Klang.","i":"bs"},
"定":{"t":"laut","x":"宀 (Dach, Haus) gibt den Sinnbereich, 正 den Klang (正 ショウ → 定 ジョウ). Das Wort bedeutete „zur Ruhe kommen, feststehen“. Unten ist 正 im heutigen Zeichen leicht abgewandelt.","s":2,"p":[["宀","Dach, Haus","b"],["正","richtig","l"]],"i":"s"},
"実":{"t":"kombi","x":"Alte Form 實: Unter einem Dach (宀) liegen Jadeschmuck und Muscheln (貝, früher Geld) – ein Haus voller Schätze. Die Grundbedeutung war „voll sein, gefüllt“. 実 ist eine stark verkürzte Form davon.","s":2,"p":[["宀","Dach, Haus","b"],["周","Jadeschmuck","b"],["貝","Muschel, Geld","b"]],"n":"Das Shuowen zerlegt 實 in 宀 + 貫 (Schnur mit Muscheln). Das beruht auf der späteren Siegelschrift, in der Jade und Muschel zu 貫 verschmolzen waren, und gilt als falsch.","a":"實","i":"bs"},
"泳":{"t":"laut","x":"氵 (Wasser) gibt den Sinnbereich, 永 den Klang (永 エイ → 泳 エイ). Zusammen schreiben sie das Wort „schwimmen“.","s":2,"p":[["氵","Wasser","b"],["永","ewig","l"]],"i":"obs"},
"苦":{"t":"laut","x":"艹 (Pflanze) gibt den Sinnbereich, 古 den Klang (古 コ → 苦 ク). Das Zeichen schrieb das Wort für ein bitteres Kraut und das Wort „bitter“. Heute steht es auch für „Leiden, Mühe“.","s":2,"p":[["艹","Pflanze","b"],["古","alt","l"]],"i":"s"},
"表":{"t":"laut","x":"Das Kleid 衣 ist in zwei Hälften geteilt, dazwischen steckt 毛 (heute oben als 龶 kaum zu erkennen). 衣 gibt den Sinnbereich, 毛 den Klang. Gemeint war die Außenseite der Kleidung, daher „Oberfläche, äußere Seite“.","s":1,"p":[["衣","Kleidung","b"],["毛","Haar, Fell","l"]],"n":"Eine andere Deutung sieht 毛 als Sinnteil: ein Gewand mit Fell oder Federn nach außen = Oberkleid. Wegen der alten Aussprache gilt die Klangteil-Deutung als besser begründet."},
"部":{"t":"laut","x":"阝 auf der rechten Seite (aus 邑, Siedlung) gibt den Sinnbereich, 咅 den Klang. Ursprünglich war es der Name eines Ortes im heutigen Gansu. Später wurde das Zeichen für das gleich klingende Wort „Gruppe, Abteilung“ ausgeliehen.","s":2,"p":[["咅","Klangteil","l"],["阝","Ort, Stadt","b"]]},
"乗":{"t":"kombi","x":"Ein Mensch (大) steht oben auf einem Baum (木), die Füße sind zu sehen: „hinaufsteigen, auf etwas steigen“. Deutlicher ist das in der Nebenform 椉. In 乘 wurde das Bild zu 禾 + 北 umgeformt; 乗 geht auf eine verkürzte Schreibweise der Han-Zeit zurück.","s":1,"p":[["大","Mensch","b"],["木","Baum","b"]],"a":"乘","i":"obs"},
"客":{"t":"laut","x":"宀 (Dach, Haus) gibt den Sinnbereich, 各 den Klang (各 カク → 客 カク). Zusammen schreiben sie das Wort „Gast“.","s":2,"p":[["宀","Dach, Haus","b"],["各","jeder","l"]],"n":"Früher wurde 各 auch als Sinnteil gedeutet; diese Zerlegung gilt heute als falsch.","i":"bs"},
"相":{"t":"kombi","x":"Ein Auge (目) schaut auf einen Baum (木): „betrachten, prüfen“. Später wurde das Zeichen für das gleich klingende Wort „gegenseitig“ ausgeliehen.","s":2,"p":[["木","Baum","b"],["目","Auge","b"]]},
"美":{"t":"bild","x":"Ein Mensch (大) mit einem Kopfschmuck aus Federn oder Widderhörnern. Der Schmuck wird heute wie 羊 (Schaf) geschrieben. Das Zeichen schrieb das Wort „schön“.","s":2,"p":[["𦍌","Kopfschmuck","f"],["大","Mensch","b"]],"n":"Oft liest man „großes Schaf = schön“. Dafür gibt es keine Belege; dass oben ein Schaf steht, ist nur eine spätere Formangleichung.","i":"ob"},
"負":{"t":"kombi","x":"Oben ein Mensch (heute zu ⺈ verkürzt), unten 貝 (Muschel, früher Geld). Das Zeichen schreibt das Wort „auf dem Rücken tragen“ (負う). Wie die Teile genau zusammenwirken, ist nicht geklärt.","s":0,"p":[["⺈","Mensch","b"],["貝","Muschel, Geld","b"]],"n":"Eine andere Deutung: 貝 als Sinnteil plus 伓 als Klangteil; das 不 darin fiel später weg."},
"談":{"t":"laut","x":"訁 (Sprache) gibt den Sinnbereich, 炎 den Klang. Zusammen schreiben sie das Wort „sprechen, sich unterhalten“.","s":2,"p":[["訁","Sprache","b"],["炎","Flamme","l"]],"n":"Oft liest man „lodernde Worte, lebhaftes Gespräch“. Das ist eine Zurechtdeutung: 炎 trägt hier nur den Klang, nicht die Bedeutung „Flamme“."},
"要":{"t":"leih","x":"Ursprünglich ein Bild: ein Mensch mit betontem Auge, der beide Hände an die Hüfte legt. Gemeint war „Hüfte, Taille“ (heute 腰). Das gleich klingende Wort für „Angelpunkt, wesentlich“ lieh sich das Zeichen später aus.","s":2,"p":[["覀","Kopf/Auge (stilisiert)","f"],["女","Frau (aus Mensch)","f"]],"n":"Die Teile 覀 und 女 sind nur spätere Stilisierungen der Figur. Ältere Deutungen als „覀 + 女“ oder als Laut-Bedeutungs-Zeichen gelten heute als falsch.","i":"bs"},
"勝":{"t":"laut","x":"力 (Kraft) gibt den Sinnbereich an, 朕 den Klang. Das Wort bedeutete „einer Sache gewachsen sein, ertragen“ und „überlegen sein, siegen“.","s":2,"p":[["力","Kraft","b"],["朕","ich (Kaiser)","l"]],"n":"Heute sieht das Zeichen aus wie 月 + 劵. Das ist nur eine Verformung von 朕 + 力 – mit dem Mond hat 月 hier nichts zu tun.","i":"s"},
"速":{"t":"laut","x":"辶 (gehen, sich bewegen) gibt den Sinnbereich an, der rechte Teil den Klang: „schnell“. Die On-Lesung klingt bis heute gleich: 束 ソク → 速 ソク.","s":2,"p":[["辶","gehen","b"],["束","Bündel","l"]],"n":"Der Klangteil war ursprünglich ein anderes, ähnlich aussehendes Zeichen als 束 „Bündel“; beide sind in der heutigen Schrift zusammengefallen.","i":"obs"},
"配":{"t":"kombi","x":"Links ein Weingefäß (酉), rechts ursprünglich ein kniender Mensch, der heute wie 己 aussieht. Heute bedeutet das Zeichen „zuteilen, verteilen“.","s":0,"p":[["酉","Weingefäß","b"],["己","kniender Mensch","b"]],"n":"Eine andere Deutung sieht im rechten Teil eine Verkürzung von 妃 als Klangteil – dann wäre es ein Laut-Bedeutungs-Zeichen.","i":"b"},
"酒":{"t":"laut","x":"酉 ist das Bild eines Gefäßes und stand ursprünglich allein für „Wein, Reiswein“. Später kam 氵 (Wasser, Flüssigkeit) zur Verdeutlichung dazu; 酉 blieb als Klangteil im Zeichen.","s":2,"p":[["氵","Wasser","b"],["酉","Weingefäß","l"]],"i":"s"},
"進":{"t":"kombi","x":"Ein Vogel (隹) und 辶 (gehen). Ein Vogel läuft nur vorwärts, nie rückwärts – so entsteht der Sinn „vorwärtsgehen, voranschreiten“.","s":2,"p":[["辶","gehen","b"],["隹","Vogel","b"]],"n":"Manche sehen 隹 als Klangteil; die alten Lautformen passen dazu aber nicht.","i":"obs"},
"落":{"t":"laut","x":"艹 (Pflanze) gibt den Sinnbereich an – man denkt an fallende Blätter –, 洛 den Klang. So entsteht „fallen, fallen lassen“. 洛 ラク → 落 ラク.","s":2,"p":[["艹","Pflanze","b"],["洛","Fluss Luo","l"]]},
"葉":{"t":"laut","x":"枼 war das Bild eines Baums mit Blättern und stand zuerst selbst für „Blatt“. Später kam 艹 (Pflanze) dazu, um es zu verdeutlichen. 枼 ヨウ → 葉 ヨウ.","s":2,"p":[["艹","Pflanze","b"],["枼","belaubter Baum","l"]],"n":"Eine alte Deutung zerlegt 枼 in 世 + 木; das gilt als falsch – 世 ist nur eine Verkürzung von 枼."},
"路":{"t":"laut","x":"Der Fuß links gibt den Sinnbereich „gehen“ an, 各 den Klang. Zusammen: „Weg, Straße“.","s":2,"p":[["𧾷","Fuß","b"],["各","jeder","l"]],"n":"Ursprünglich stand links 疋 (ebenfalls ein Fuß); weil 疋 und 足 verwechselt wurden, sieht das Zeichen heute so aus.","i":"bs"},
"鳴":{"t":"kombi","x":"Ein Mund und ein Vogel: der Ruf eines Vogels. Daraus wurde allgemein „Laute geben, rufen, klingen“.","s":2,"p":[["口","Mund","b"],["鳥","Vogel","b"]],"n":"Der rechte Teil zeigte ursprünglich einen Hahn und glich sich erst später an 鳥 an."},
"横":{"t":"laut","x":"木 (Holz) gibt den Sinnbereich an, 黄 den Klang. Gemeint war ursprünglich ein Querbalken bzw. Riegel; daraus wurde „quer, waagerecht, Seite“. 黄 オウ → 横 オウ.","s":2,"p":[["木","Baum, Holz","b"],["黄","gelb","l"]],"n":"Die alte Schreibung ist 橫 mit 黃; der Unterschied ist nur eine Kleinigkeit im Strich."},
"調":{"t":"laut","x":"訁 (Wort, Sprache) gibt den Sinnbereich an, 周 den Klang. Heute bedeutet das Zeichen „abstimmen, untersuchen“ und „Ton, Tonart“.","s":2,"p":[["訁","Wort, sprechen","b"],["周","rundum","l"]]},
"頭":{"t":"laut","x":"頁 (Kopf) gibt den Sinnbereich an, 豆 den Klang. Die On-Lesung klingt gleich: 豆 トウ → 頭 トウ.","s":2,"p":[["頁","Kopf","b"],["豆","Opfergefäß","l"]],"i":"s"},
"顔":{"t":"laut","x":"頁 (Kopf) gibt den Sinnbereich an, 彦 den Klang: „Gesicht“. 彦 ゲン → 顔 ガン klingt noch ähnlich.","s":2,"p":[["頁","Kopf","b"],["彦","tüchtiger Mann","l"]],"n":"Alte Schreibung 顏 mit 彥 – nur eine leicht andere Form. Frühe Bronzeinschriften schreiben das Wort mit 面 (Gesicht) und einem anderen Klangteil.","i":"bs"},
"最":{"t":"laut","x":"Ursprünglich 宀 (Dach) + 取 als Klangteil: „sammeln, zusammenkommen“. Das Dach wurde später zu 曰 verformt. Die Bedeutung „am meisten“ kam erst später hinzu.","s":2,"p":[["曰","Dach (aus 宀)","f"],["取","nehmen","l"]],"n":"Mit 曰 „sagen“ oder 日 hat der obere Teil nichts zu tun. Die seltene On-Lesung シュ erinnert noch an 取 シュ.","i":"os"},
"争":{"t":"bild","x":"Das Bild zweier Hände, die von oben und unten an einem U-förmigen Gegenstand ziehen: „streiten, sich um etwas reißen“. Die heutige Form 争 ist aus der alten Form 爭 vereinfacht.","s":1,"p":[["⺈","Hand (aus 爪)","b"],["⺕","Hand","b"]],"n":"Manche deuten den Gegenstand als Pflugschar; nach den alten Lautformen ist das aber wenig wahrscheinlich.","a":"爭","i":"os"},
"伝":{"t":"laut","x":"Alte Form 傳: 亻 (Mensch) gibt den Sinnbereich an, 專 den Klang – „weitergeben, übermitteln“. In Japan wurde 專 zu 云 verkürzt, genauso wie 轉 zu 転.","s":2,"p":[["亻","Mensch","b"],["專","ausschließlich","l"],["云","Kurzform von 專","f"]],"n":"Im Chinesischen gibt es zufällig auch ein seltenes, eigenständiges Zeichen 伝 (亻+云), das mit 傳 nichts zu tun hat.","a":"傳","i":"obs"},
"共":{"t":"leih","x":"Zwei Hände, die einen Gegenstand hochhalten und darbringen. Das Zeichen stand wohl zuerst für „darbringen, anbieten“ (heute 供) und wurde dann für das Wort „zusammen, gemeinsam“ ausgeliehen.","s":1,"p":[["廾","zwei Hände","b"],["廿","Gegenstand (aus 口)","f"]],"n":"Der Gegenstand war ursprünglich ein 口 (nicht „Mund“), wurde zu 廿 (nicht „zwanzig“) und verschmolz mit den Händen zur heutigen Form.","i":"obs"},
"成":{"t":"unklar","x":"Sicher ist nur, dass das Zeichen eine Waffe (Streitaxt) enthält. Eine Deutung sieht im Rest den Klangteil 丁 und als Urbedeutung „Stadtmauer“ (heute 城); andere halten den Ursprung für ungeklärt.","s":0,"p":[["戊","Streitaxt","b"],["丁","Nagel","f"]],"n":"Der kleine Teil innen ist kein 口 „Mund“, wie man manchmal liest.","i":"obs"},
"老":{"t":"bild","x":"Das Bild eines Menschen mit langem Haar, der sich auf einen Stock stützt: ein alter Mensch.","s":2,"p":[["耂","Mensch mit langem Haar","b"],["匕","Stock","b"]],"n":"匕 ist hier kein Löffel, sondern der Stock. 老 ist eng verwandt mit 考 und hat denselben oberen Teil wie 孝.","i":"obs"},
"位":{"t":"laut","x":"亻 (Mensch) gibt den Sinnbereich an, 立 den Klang: der Platz, an dem jemand steht – „Stelle, Rang“. In alten Inschriften schrieb man dafür oft einfach 立.","s":2,"p":[["亻","Mensch","b"],["立","stehen","l"]],"i":"obs"},
"初":{"t":"kombi","x":"Kleidung (衤) und Messer (刀): Wer ein Kleid machen will, schneidet zuerst den Stoff zu. Daraus wurde „Anfang, das erste Mal“.","s":2,"p":[["衤","Kleidung","b"],["刀","Messer","b"]],"i":"obs"},
"利":{"t":"kombi","x":"Getreide (禾) und ein Messer (刂): Korn wird mit einer scharfen Klinge geerntet. Daraus kommen „scharf“ und „Gewinn, Nutzen“.","s":2,"p":[["禾","Getreide","b"],["刂","Messer","b"]],"i":"obs"},
"努":{"t":"laut","x":"力 (Kraft) gibt den Sinnbereich an – seine Kraft einsetzen –, 奴 den Klang: „sich bemühen“. 奴 ド → 努 ド.","s":2,"p":[["力","Kraft","b"],["奴","Knecht","l"]]},
"労":{"t":"laut","x":"Alte Form 勞: 力 (Kraft) gibt den Sinnbereich „Mühe, Arbeit“ an, der obere Teil (das seltene Zeichen 𬡤) den Klang. Japan verkürzte den oberen Teil zu ⺍ + 冖, wie bei 栄 und 営.","s":2,"p":[["力","Kraft","b"],["𬡤","seltenes Zeichen","l"]],"n":"Oft wird der obere Teil als „Feuer“ (𤇾, wie in 栄 und 営) gedeutet. Die Forschung sieht das heute anders: Er war ursprünglich ein eigener Klangteil und hat mit diesem Feuer-Teil nichts zu tun.","a":"勞","i":"s"},
"命":{"t":"laut","x":"In den Orakelknochen schrieb man „Befehl“ noch einfach mit 令. Später kam 口 Mund dazu, und so wurde 命 ein eigenes Zeichen. 口 gibt den Sinnbereich (Sprechen, Anordnen), 令 レイ zugleich Klang und Grundsinn: 令 レイ → 命 メイ.","s":2,"p":[["口","Mund","b"],["令","Befehl","l"]],"i":"obs"},
"放":{"t":"laut","x":"攵 (eine Hand, die etwas tut) gibt den Sinnbereich „Handlung“, 方 ホウ den Klang: 方 ホウ → 放 ホウ. Gemeint war „loslassen, freilassen“.","s":2,"p":[["方","Richtung","l"],["攵","Hand mit Stock","b"]],"i":"s"},
"育":{"t":"leih","x":"Das Zeichen ist eine verkürzte Form von 冑/胄, bei der der obere Teil weggefallen ist. Diese Form wurde in der Han-Zeit für das gleich klingende Wort „aufziehen“ ausgeliehen. Vorher schrieb man dieses Wort mit 毓.","s":1,"n":"Oft liest man: oben ein kopfüber geborenes Kind (𠫓), unten 月 Körper – also Geburt und Großziehen. Diese früher verbreitete Deutung gilt heute als überholt.","i":"obs"},
"指":{"t":"laut","x":"扌 Hand gibt den Sinnbereich, 旨 シ den Klang: 旨 シ → 指 シ. Gemeint war zuerst der Finger, daraus wurde auch „zeigen“.","s":2,"p":[["扌","Hand","b"],["旨","Geschmack, Sinn","l"]],"i":"bs"},
"追":{"t":"kombi","x":"辶 steht für Bewegung, 𠂤 ist das alte Zeichen für eine Truppe (Urform von 師). Zusammen: einer Truppe hinterherziehen – „verfolgen, nachjagen“.","s":1,"p":[["辶","gehen","b"],["𠂤","Truppe","b"]],"n":"Das alte Wörterbuch 説文 und manche heutige Darstellungen halten 𠂤 für den Klangteil. Dagegen spricht, dass 𠂤 lautlich weit von 追 entfernt ist; deshalb wird es hier als Sinnverbindung erklärt.","i":"bs"},
"戦":{"t":"laut","x":"Alte Form 戰: 戈 (Hellebarde, eine Stangenwaffe) gibt den Sinnbereich „kämpfen, Krieg“, 單 (heute 単 タン) den Klang. In 戦 wurde 單 genauso zu 単 verkürzt wie im Zeichen 単 selbst.","s":2,"p":[["単","einzeln","l"],["戈","Hellebarde","b"]],"n":"Später lieh man das Zeichen auch für ein gleich klingendes Wort „zittern“ aus – daher 戦く（おののく）.","a":"戰","i":"s"},
"良":{"t":"unklar","x":"Die Herkunft ist ungeklärt. Es ist ein altes Bildzeichen, doch was es zeigt, ist umstritten: vorgeschlagen werden u. a. ein Raum mit Gängen nach beiden Seiten (dann Urform von 廊 Korridor), ein Messgefäß oder ein Essgefäß.","s":0,"n":"Trotz ähnlicher Form hat es mit 艮, 食 und 亡 nichts zu tun – die Erklärung im alten Wörterbuch 説文 mit 亡 widerspricht den Orakelknochen.","i":"obs"},
"便":{"t":"laut","x":"亻 Mensch gibt den Sinnbereich. Rechts stand ursprünglich 𠓥 (in der Bronzeschrift eine Peitsche), das heute wie 更 aussieht; es gibt den Klang (→ 便 ベン). Gemeint war „gut passend, angenehm“.","s":1,"p":[["亻","Mensch","b"],["更","aus 𠓥 Peitsche","l"]],"n":"Oft liest man nach 説文: Mensch + 更 „ändern“ – man ändert seine Haltung, um es bequem zu haben. Der Bronzebefund mit 𠓥 spricht dagegen; manche sehen darin sogar die Urform von 鞭 Peitsche.","i":"bs"},
"庭":{"t":"laut","x":"广 (ein Gebäude mit Dach) gibt den Sinnbereich, 廷 テイ den Klang: 廷 テイ → 庭 テイ. Gemeint ist der Hof bzw. Garten am Haus.","s":2,"p":[["广","Gebäude","b"],["廷","Hof","l"]],"i":"bs"},
"息":{"t":"kombi","x":"自 war ursprünglich das Bild einer Nase. Die ältesten Formen zeigen die Nase mit Strichen darunter für den ein- und ausströmenden Atem. Später verschmolz diese Form mit einem zweiten Zeichen aus 心 und 自, das eigentlich „hassen“ bedeutete; so kam das Herz 心 ins heutige Zeichen.","s":1,"p":[["自","Nase","b"],["心","Herz","b"]]},
"流":{"t":"laut","x":"氵 Wasser gibt den Sinnbereich, 㐬 den Klang: 㐬 リュウ → 流 リュウ. 㐬 ist eine verkürzte Form von 毓 (aufziehen).","s":2,"p":[["氵","Wasser","b"],["㐬","Kurzform von 毓","l"]]},
"消":{"t":"laut","x":"氵 Wasser gibt den Sinnbereich, 肖 ショウ den Klang: 肖 ショウ → 消 ショウ. Gemeint ist „erlöschen, verschwinden“ – etwa ein Feuer, das mit Wasser gelöscht wird.","s":2,"p":[["氵","Wasser","b"],["肖","ähneln","l"]],"i":"s"},
"都":{"t":"laut","x":"Das rechte 阝 ist eine Form von 邑 „Stadt, Siedlung“ und gibt den Sinnbereich; 者 gibt den Klang. Im Altchinesischen klangen beide noch ähnlich (*ta / *taa); heute 者 シャ, 都 ト. Gemeint ist die Hauptstadt.","s":2,"p":[["者","Person","l"],["阝","Stadt (邑)","b"]],"n":"Rechts stehendes 阝 = 邑 (Stadt), links stehendes 阝 = 阜 (Hügel), wie in 陽.","i":"bs"},
"商":{"t":"unklar","x":"Wie das Zeichen entstand, ist ungeklärt. In den Orakelknochen steht unten immer 丙, darüber ein wechselndes Oberteil, z. B. ein auf der Spitze stehendes Dreieck mit Querstrich. 口 kam erst in späteren Formen unten dazu.","s":0,"p":[["丙","Unterteil","f"],["口","Mund","f"]],"n":"Das Oberteil wird oft als 辛 (Meißel) gedeutet; nach den Orakelknochen ist das aber zweifelhaft. Auch die Erklärung im alten Wörterbuch 説文 (mit 章 als Klangteil) gilt als falsch.","i":"obs"},
"深":{"t":"laut","x":"氵 Wasser gibt den Sinnbereich, 罙 den Klang: 罙 シン → 深 シン. Gemeint ist „tief“.","s":2,"p":[["氵","Wasser","b"],["罙","Klangzeichen","l"]]},
"球":{"t":"laut","x":"Links steht 玉 Jade, ein Edelstein; es gibt den Sinnbereich. 求 gibt den Klang: 求 キュウ → 球 キュウ. Gemeint war eine runde Kugel, ein „Juwel“.","s":2,"p":[["王","Jade (玉)","b"],["求","suchen","l"]],"n":"Das linke Teil sieht aus wie 王 König, ist aber 玉 Jade – in Zusammensetzungen fällt der Punkt weg.","i":"s"},
"陽":{"t":"laut","x":"Ursprünglich stand 昜 allein für „Sonnenschein, die sonnige Seite“. Später kam 阝 (Hügel) dazu. 昜 gibt nun Klang und Grundsinn: 昜 ヨウ → 陽 ヨウ.","s":2,"p":[["阝","Hügel (阜)","b"],["昜","Sonnenschein","l"]],"i":"b"},
"寒":{"t":"kombi","x":"Unter einem Dach 宀 liegt ein Mensch 人 zwischen viel Gras 茻: Er deckt sich mit Gras zu, um sich vor der Kälte zu schützen. Mensch und Gras sind heute zum Mittelteil verschmolzen.","s":2,"p":[["宀","Haus","b"],["人","Mensch","b"],["茻","viel Gras","b"],["⺀","Zierstriche","f"]],"n":"Die zwei Punkte unten werden oft als Eis 冫 erklärt. In Bronzeinschriften sind es aber zusätzliche Striche ohne eigene Bedeutung; erst die Siegelschrift deutete sie als Eis um.","i":"bs"},
"悲":{"t":"laut","x":"心 Herz gibt den Sinnbereich Gefühl, 非 den Klang: 非 ヒ → 悲 ヒ. Gemeint ist „traurig sein“.","s":2,"p":[["非","nicht","l"],["心","Herz","b"]],"i":"s"},
"期":{"t":"laut","x":"月 Mond (für Zeit und Kalender) gibt den Sinnbereich, 其 den Klang: 其 キ → 期 キ. Gemeint war eine vereinbarte Zeit, eine Frist. In älteren Varianten stand statt 月 noch 日 Sonne.","s":2,"p":[["其","jener","l"],["月","Mond","b"]],"i":"bs"},
"歯":{"t":"laut","x":"Alte Form 齒: Ursprünglich ein Bild eines offenen Mundes mit Zähnen (𠚕). Später kam oben 止 als Klangteil dazu: 止 シ → 齒 シ. In 歯 sind die einzelnen Zähne im Mund zu 米 vereinfacht.","s":2,"p":[["止","anhalten","l"],["𠚕","Mund mit Zähnen","b"]],"a":"齒","i":"obs"},
"港":{"t":"laut","x":"氵 Wasser gibt den Sinnbereich, 巷 den Klang: 巷 コウ → 港 コウ.","s":2,"p":[["氵","Wasser","b"],["巷","Gasse","l"]]},
"登":{"t":"laut","x":"癶 zeigt zwei Füße, die nach oben steigen, und gibt den Sinn „hinaufsteigen“. Darunter 豆, ein Gefäß mit Essen, das ursprünglich zwei Hände emporhielten (Urform von 烝 „darbringen“); dieser Teil gibt den Klang. Die Hände sind später weggefallen.","s":1,"p":[["癶","Füße","b"],["豆","Speisegefäß","l"]],"n":"Eine andere Deutung liest das Zeichen als reine Sinnverbindung: Füße steigen auf einen erhöhten Gegenstand. Die Hände sind noch in der Nebenform 𤼷 erhalten.","i":"obs"},
"亡":{"t":"leih","x":"Ursprünglich ein Messer 刀, an dessen Schneide eine Markierung die Spitze anzeigt – gemeint war 芒 „Klingenspitze“. Das Zeichen wurde dann für das ähnlich klingende Wort „nicht haben, verloren gehen“ ausgeliehen; heute auch „sterben, verstorben“.","s":1,"n":"Die Form in den Orakelknochen weicht etwas von der Messer-Form der Bronzen ab; die Verbindung ist noch nicht ganz geklärt.","i":"obs"},
"合":{"t":"kombi","x":"Zwei Münder, die einander zugewandt sind – der obere steht auf dem Kopf. Daraus „zusammenkommen, zusammenpassen“. Das Zeichen stand anfangs auch für „antworten“, das man heute 答 schreibt.","s":2,"p":[["亼","Mund (umgedreht)","b"],["口","Mund","b"]],"i":"obs"},
"予":{"t":"leih","x":"Ursprünglich dasselbe Zeichen wie 呂. Es wurde für das gleich klingende Wort „ich“ (auch „geben“) ausgeliehen und bekam später unten einen Haken, um es von 呂 zu unterscheiden. „Im Voraus“ bedeutet es im Japanischen, weil 予 dort auch als Kurzform für 豫 steht.","s":1,"n":"豫 besteht aus 象 (Elefant) und dem Klangteil 予 (ヨ); seine Grundbedeutung ist unbekannt, es wurde für „im Voraus“ ausgeliehen. Oft liest man, 予 zeige ein Weberschiffchen – die Forschung hält das für falsch.","i":"s"},
"反":{"t":"kombi","x":"厂 (Felshang) + 又 (Hand): Eine Hand greift an einen Felsen, um hinaufzuklettern. Gemeint war zuerst „hochklettern“; später lieh man das Zeichen für das ähnlich klingende Wort „umdrehen, zurückkehren“ aus – daher „gegen, Gegenteil“.","s":1,"p":[["厂","Felshang","b"],["又","Hand","b"]],"n":"Eine andere Deutung: 又 (Hand) trägt den Sinn, 厂 nur den Klang; das Zeichen habe ursprünglich das Umdrehen der Handfläche gezeigt.","i":"obs"},
"返":{"t":"laut","x":"辶 (gehen, Weg) gibt den Sinnbereich, 反 (umkehren) den Klang und passt auch vom Sinn: 反 ハン → 返 ヘン. Gemeint war „den Weg zurückgehen“, daraus „zurückkehren, zurückgeben“.","s":2,"p":[["辶","gehen, Weg","b"],["反","umkehren","l"]],"i":"s"},
"宿":{"t":"kombi","x":"In den ältesten Formen liegt ein Mensch auf einer Schlafmatte; später kam 宀 (Dach, Haus) dazu: unter einem Dach schlafen, übernachten. Die Matte wurde mit der Zeit zu 百 umgeformt.","s":2,"p":[["宀","Dach, Haus","b"],["亻","Mensch","b"],["百","(früher: Matte)","b"]],"n":"Das 百 rechts hat nichts mit „hundert“ zu tun – es ist die umgeformte Matte.","i":"obs"},
"想":{"t":"laut","x":"心 (Herz, Sinn) gibt den Sinnbereich „denken“, 相 den Klang: 相 ソウ → 想 ソウ. Gemeint ist „denken, sich vorstellen“.","s":2,"p":[["心","Herz, Sinn","b"],["相","einander; ansehen","l"]]},
"感":{"t":"laut","x":"心 (Herz) gibt den Sinnbereich, 咸 den Klang: 咸 カン → 感 カン. Gemeint ist, dass das Herz von etwas bewegt wird – „empfinden, Gefühl“.","s":2,"p":[["咸","alle","l"],["心","Herz","b"]],"i":"s"},
"暗":{"t":"laut","x":"日 (Sonne, Licht) gibt den Sinnbereich, 音 den Klang (音 オン, 暗 アン). Das Wort bedeutet „dunkel“ – also ohne Sonnenlicht.","s":2,"p":[["日","Sonne","b"],["音","Laut, Ton","l"]],"n":"Manche Erklärungen deuten 音 zusätzlich als Sinnteil; dafür gibt es keinen Beleg, es ist nur der Klangteil.","i":"s"},
"様":{"t":"laut","x":"Die alte Form 樣 besteht aus 木 (Baum) und dem Klangteil 羕 (ヨウ). Sie bezeichnete zuerst eine Eichenart und wurde dann für das ähnlich klingende Wort „Form, Aussehen“ ausgeliehen. Die heutige Form vereinfacht die rechte Hälfte.","s":2,"p":[["木","Baum","b"],["羕","(Klangteil)","l"]],"n":"Die rechte Seite von 様 ist eine verkürzte Form von 羕 (etwa 𦍌 über 氺).","a":"樣"},
"福":{"t":"laut","x":"礻 (Altar, Götter) zeigt den Bereich Religion und Segen, 畐 gibt den Klang: 畐 フク → 福 フク. Gemeint ist das Glück, das von den Göttern kommt.","s":2,"p":[["礻","Altar, Götter","b"],["畐","Gefäß","l"]],"i":"obs"},
"殺":{"t":"kombi","x":"Links stand ursprünglich ein getötetes Tier, rechts kam 殳 (Waffe bzw. Hand, die zuschlägt) dazu: ein Tier wird erschlagen – „töten“. Die linke Hälfte wurde später zu der Form umgebildet, die heute wie 㐅 über 木 aussieht.","s":1,"p":[["㐅木","(früher: Tier)","b"],["殳","Waffe, schlagen","b"]],"n":"Welches Tier gemeint ist, ist umstritten: ein Wildschwein mit durchbohrtem Kopf oder eine umgedrehte Schlange. Die Zerlegung in 杀 + 殳 (Shuowen) ist falsch – 杀 ist eine Kurzform von 殺.","i":"os"},
"然":{"t":"laut","x":"灬 (Feuer) gibt den Sinnbereich, 肰 (ゼン) den Klang. Ursprünglich hieß das Zeichen „brennen“; dann wurde es für ein gleich klingendes Wort wie „so, in dieser Weise“ ausgeliehen. Für „brennen“ schrieb man darum 燃 mit zusätzlichem 火.","s":2,"p":[["肰","Hundefleisch","l"],["灬","Feuer","b"]],"n":"Oft liest man „Fleisch über dem Feuer rösten“. Dass 肰 als eigenes Zeichen existiert, zeigt aber: Es ist ein Klangteil. Der Teil links oben ist ein gekipptes 肉 (Fleisch) und sieht heute wie 夕 aus.","i":"s"},
"熱":{"t":"laut","x":"灬 (Feuer) gibt den Sinnbereich „heiß“, 埶 den Klang. Im Altchinesischen klangen beide sehr ähnlich; im Japanischen ist die Ähnlichkeit kaum noch zu hören (埶 ゲイ, 熱 ネツ).","s":2,"p":[["埶","pflanzen","l"],["灬","Feuer","b"]],"i":"s"},
"選":{"t":"laut","x":"辶 (gehen) gibt den Sinnbereich, 巽 den Klang: 巽 ソン → 選 セン.","s":1,"p":[["辶","gehen","b"],["巽","Südosten","l"]],"n":"Das alte Wörterbuch Shuowen sieht als Grundbedeutung „jemanden höflich wegschicken“: Wer auswählt, schickt die anderen weg. Das ist eine traditionelle Deutung, nicht durch alte Schriftfunde belegt.","i":"s"},
"願":{"t":"laut","x":"頁 (Kopf) gibt den Sinnbereich, die linke Hälfte den Klang. Das Zeichen schrieb zuerst ein Wort für „Kopf“ und wurde dann für das ähnlich klingende Wort „wünschen, bitten“ ausgeliehen.","s":1,"p":[["原","(früher: anderer Klangteil)","l"],["頁","Kopf","b"]],"n":"Oft wird 原 als Klangteil genannt (so schon das Shuowen). Die linke Hälfte stammt aber von einem anderen Klangteil (𡚇), der erst um die Han-Zeit wie 原 geschrieben wurde; danach glich sich die Aussprache an (原 ゲン, 願 ガン).","i":"s"},
"情":{"t":"laut","x":"忄 (Herz) gibt den Sinnbereich Gefühl, 青 den Klang: 青 セイ → 情 セイ/ジョウ.","s":2,"p":[["忄","Herz","b"],["青","blau, grün","l"]]},
"疑":{"t":"bild","x":"Ursprünglich ein Bild: ein Mensch mit Stock, der sich mit offenem Mund umschaut und nicht weiß, wohin er gehen soll – „ratlos sein, zweifeln“. Später kamen 止 (Fuß) und 牛 als Klangteil dazu; 牛 wurde zu 子, und aus 子 + 止 entstand die heutige rechte Seite.","s":2,"p":[["𠤕","ratloser Mensch","b"],["龴疋","aus 子 + 止","f"]],"n":"Das Shuowen zerlegt das Zeichen in 子, 止, 匕 und 矢 („ein Kind am versperrten Weg“). Die alten Schriftformen zeigen, dass das nicht stimmt.","i":"obs"},
"皆":{"t":"leih","x":"Die heutige Form 比 + 白 ist das Ergebnis vieler Umformungen; die ältesten Formen enthielten u. a. 虍 (Tiger). Das Zeichen stand wohl zuerst für „zusammenwirken, harmonieren“ und wurde dann für das ähnlich klingende Wort „alle“ ausgeliehen.","s":1,"p":[["比","nebeneinander","f"],["白","weiß","f"]],"n":"Die Deutung „比 + 白“ stammt aus dem Shuowen und beruht auf späten Formen: Das untere 白 war ursprünglich 口 bzw. 甘.","i":"obs"},
"例":{"t":"laut","x":"亻 (Mensch) gibt den Sinnbereich, 列 den Klang: 列 レツ → 例 レイ.","s":2,"p":[["亻","Mensch","b"],["列","Reihe","l"]],"n":"Manche Erklärungen sehen in 列 (Reihe) zusätzlich einen Sinnteil; dafür gibt es keinen Beleg.","i":"s"},
"参":{"t":"bild","x":"Die alte Form 參 zeigt drei Sterne über einem Menschen – gemeint war das Sternbild der „Drei Sterne“ (im Orion). Die heutige Form 参 ist eine verkürzte Schreibung von 參.","s":1,"p":[["厶","Stern","b"],["大","Mensch","b"],["彡","Lichtstrahlen","b"]],"n":"Das Shuowen zerlegt 參 in 晶 (Sterne) + Klangteil 㐱; nach den alten Formen hat es mit 㐱 nichts zu tun. Eine andere Deutung sieht darin eine Haarnadel mit drei Sternen.","a":"參","i":"bs"},
"完":{"t":"laut","x":"宀 (Dach, Haus) gibt den Sinnbereich, 元 den Klang (元 ガン/ゲン → 完 カン). Gemeint ist „ganz, unversehrt“, daraus „vollenden“.","s":2,"p":[["宀","Dach, Haus","b"],["元","Ursprung","l"]]},
"念":{"t":"kombi","x":"Oben stand ursprünglich ein umgedrehter Mund (亼), unten 心 (Herz): man spricht nach innen, zum eigenen Herzen – „bedenken, im Sinn haben“. Erst in späten Bronzeinschriften wurde der obere Teil zu 今.","s":2,"p":[["今","(früher: umgedrehter Mund)","b"],["心","Herz","b"]],"n":"Oft wird 今 als Klangteil erklärt (so schon das Shuowen); die alten Lautformen von 今 und 念 passen aber nicht zusammen.","i":"obs"},
"折":{"t":"kombi","x":"Links stand ursprünglich ein in zwei Hälften zerteilter Baum, rechts 斤 (Axt): Eine Axt spaltet einen Baum – „brechen“. Die linke Hälfte wurde später zu 扌 (Hand) umgeformt.","s":2,"p":[["扌","(früher: zerteilter Baum)","b"],["斤","Axt","b"]],"n":"Das 扌 sieht heute wie „Hand“ aus, war aber ursprünglich der zerbrochene Baum.","i":"obs"},
"望":{"t":"laut","x":"Ursprünglich ein Bild: ein Mensch steht auf dem Boden und blickt mit großem Auge (臣) in die Ferne. Später kam 月 (Mond) dazu, und das Auge wurde durch den Klangteil 亡 ersetzt: 亡 ボウ → 望 ボウ.","s":2,"p":[["亡","zugrunde gehen","l"],["月","Mond","b"],["王","(früher: stehender Mensch)","b"]],"n":"Das 王 unten ist kein „König“, sondern ein Mensch, der auf dem Boden steht. Das Zeichen bezeichnete auch den Vollmond.","i":"obs"},
"束":{"t":"bild","x":"Bild eines Sacks, der an beiden Enden zugebunden ist – daher „binden, bündeln, Bündel“. Ursprünglich war es dasselbe Zeichen wie 東.","s":2,"n":"Heute sieht das Zeichen aus wie 木 mit 口; das ist nur Zufall der Form, nicht seine Herkunft.","i":"obs"},
"残":{"t":"laut","x":"Die alte Form 殘 besteht aus 歹 (Knochen, verkürzt aus 死 „sterben“) und dem Klangteil 戔 (セン/サン → ザン). Ursprünglich hieß es „beschädigen, zerstören“; heute vor allem „übrig bleiben“. In 残 ist 戔 zu einer kürzeren Form vereinfacht.","s":2,"p":[["歹","Knochen, Tod","b"],["戔","zwei Waffen","l"]],"n":"Zuerst schrieb man das Wort nur mit 戔; 歹 kam später dazu.","a":"殘","i":"s"},
"求":{"t":"leih","x":"Das Zeichen zeigte ursprünglich ein Tier mit vielen Beinen, einen Tausendfüßler (später 蛷 geschrieben). Weil das Wort ähnlich klang, lieh man es für das Wort „suchen, verlangen“ aus.","s":2,"n":"Das alte Wörterbuch Shuowen hielt 求 für die Urform von 裘 „Pelzmantel“. Die Orakelknochen zeigen aber für 裘 ein eigenes Zeichen, daher gilt das heute als falsch.","i":"obs"},
"約":{"t":"laut","x":"Der Faden 糸 gibt den Sinnbereich an: zusammenbinden, bündeln. 勺 steuert nur den Klang bei. Aus „zusammenbinden“ wurden „vereinbaren, Versprechen“ und „zusammengefasst, ungefähr“.","s":2,"p":[["糸","Faden","b"],["勺","Schöpfkelle","l"]],"i":"s"},
"性":{"t":"laut","x":"Das Herz 忄 gibt den Sinnbereich an: das Innere, das Wesen eines Menschen. 生 liefert den Klang (生 セイ/ショウ → 性 セイ/ショウ). Gemeint war das, was einem angeboren ist – die Natur; daraus auch „Eigenschaft“ und „Geschlecht“.","s":2,"p":[["忄","Herz","b"],["生","geboren werden","l"]]},
"格":{"t":"laut","x":"木 gibt den Sinnbereich an, 各 den Klang (各 カク → 格 カク). Das Wort bedeutete „Form, Muster, Maßstab“; daraus wurden „Norm“ und „Rang“.","s":2,"p":[["木","Baum, Holz","b"],["各","jeder","l"]],"n":"Manche erklären 各 zugleich als Sinnteil. Die Forschung hält diese Deutung für falsch: 各 steht hier nur für den Klang.","i":"obs"},
"能":{"t":"leih","x":"Ursprünglich das Bild eines Bären (vgl. 熊): Die beiden 匕 rechts sind die Pranken, 月 ist der Kopf mit offenem Maul. Später wurde das Zeichen für das ähnlich klingende Wort „können“ ausgeliehen.","s":2,"n":"Das alte Wörterbuch Shuowen zerlegte das Zeichen in „Fleisch“ 肉 und weitere Teile. Die ältesten Schriftformen zeigen aber, dass es ein einziges Tierbild ist.","i":"obs"},
"術":{"t":"laut","x":"行 (die Straßenkreuzung, hier links und rechts aufgeteilt) gibt den Sinnbereich „Weg“ an, 朮 in der Mitte den Klang (朮 ジュツ → 術 ジュツ). Zuerst hieß das Wort „Weg“; später wurde es für das gleich klingende Wort „Kunst, Technik“ verwendet.","s":2,"p":[["行","Weg, gehen","b"],["朮","Pflanzenname","l"]]},
"晴":{"t":"laut","x":"Die Sonne 日 gibt den Sinnbereich „Wetter, Himmel“ an, 青 den Klang (青 セイ → 晴 セイ). Gemeint ist: Der Himmel klart auf, das Wetter ist schön.","s":2,"p":[["日","Sonne","b"],["青","blau","l"]],"n":"In alten Texten wurde dasselbe Wort auch anders geschrieben, z. B. mit 星 im Buch der Lieder."},
"列":{"t":"laut","x":"Das Messer 刂 gibt den Sinnbereich „zerteilen, auseinanderschneiden“ an. Die linke Hälfte war ursprünglich ein anderes Zeichen (𡿪), das den Klang beisteuerte; sie sieht heute nur zufällig aus wie 歹. Aus „aufteilen“ wurde „in Reihen aufstellen, Reihe“.","s":1,"p":[["歹","Klangteil (eigentlich 𡿪)","l"],["刂","Messer","b"]],"n":"Oft liest man „Knochenreste 歹 + Messer = zerlegen“, und manche Fachleute vertreten das bis heute. In der Siegelschrift steht links aber 𡿪, das mit 歹 (wie in 死) nichts zu tun hat.","i":"s"},
"式":{"t":"laut","x":"工 gibt den Sinnbereich an, 弋 den Klang. Das Wort bedeutete „Vorbild, Muster“; daraus wurden „Form, Formel“ und „festgelegter Ablauf, Zeremonie“.","s":2,"p":[["弋","Schnurpfeil","l"],["工","Arbeit, Werkzeug","b"]]},
"信":{"t":"laut","x":"言 „Wort“ gibt den Sinnbereich an, 人 (hier 亻) liefert den Klang – im Altchinesischen klangen beide ähnlich. Das Wort bedeutete „Aufrichtigkeit, Wahrhaftigkeit“; daraus wurden „vertrauen, glauben“ und „Nachricht“.","s":2,"p":[["亻","Mensch","l"],["言","Wort, sprechen","b"]],"n":"Oft liest man „ein Mensch steht zu seinem Wort“. Das stammt aus dem alten Wörterbuch Shuowen; heute sieht man 人 hier als Klangteil."},
"単":{"t":"leih","x":"Die alte Form 單 zeigt ein Jagd- oder Kampfgerät: einen gegabelten Stab mit zwei Steinen oben. Später wurde das Zeichen für das Wort „einzeln, einfach“ ausgeliehen. 単 ist eine Kurzform aus der Halbkursive: die zwei 口 oben wurden zu drei Strichen.","s":1,"n":"Andere Deutungen sehen darin ein Fangnetz mit zwei Gewichten oder eine Zikade (Urform von 蟬). Einig ist man sich, dass „einzeln“ eine spätere, entlehnte Bedeutung ist.","a":"單","i":"obs"},
"変":{"t":"laut","x":"Die alte Form 變: 攵 (eine Hand, die etwas tut) gibt den Sinnbereich „verändern, umformen“ an, 䜌 oben steuert den Klang bei. 変 ist eine Kurzform aus der Schreibschrift: 䜌 wurde zu 亦, 攵 zu 夂.","s":2,"p":[["䜌","Klangteil (heute 亦)","l"],["攵","Hand mit Stock","b"]],"a":"變","i":"bs"},
"夫":{"t":"bild","x":"Ursprünglich dasselbe Bild wie 大: ein erwachsener Mensch mit ausgebreiteten Armen. Ein zusätzlicher Querstrich ohne eigene Bedeutung unterschied es später von 大. Auf den Orakelknochen wurden beide noch vermischt; 夫 blieb dann für „erwachsener Mann“, daraus „Ehemann“.","s":2,"p":[["大","erwachsener Mensch","b"],["一","Zierstrich","f"]],"n":"Oft liest man, der obere Strich sei eine Haarnadel, die junge Männer mit 20 trugen. Das stammt aus dem Shuowen und gilt als falsch: Haarnadeln sehen in der alten Schrift anders aus.","i":"obs"},
"昨":{"t":"laut","x":"日 „Tag“ gibt den Sinnbereich an, 乍 den Klang (乍 サク → 昨 サク). Gemeint war „gestern“, daraus „vorig, letztes“ (昨年).","s":2,"p":[["日","Sonne, Tag","b"],["乍","plötzlich","l"]],"n":"乍 wurde früher auch im Sinn von „zuerst, eben erst“ gebraucht und könnte deshalb zusätzlich etwas zur Bedeutung beitragen.","i":"s"},
"法":{"t":"laut","x":"法 ist eine Kurzform von 灋: Wasser 氵, das Tier 廌 und ein Klangteil. Der Klangteil sieht aus wie 去; manche Fachleute sehen darin ein verkürztes 盍. Später fiel 廌 weg. Warum 廌 im Zeichen stand, ist ungeklärt.","s":1,"p":[["氵","Wasser","b"],["去","weggehen","l"]],"n":"Oft liest man, 廌 sei ein Fabeltier, das bei Gericht Recht und Unrecht unterscheidet. Das geht auf das Shuowen zurück und gilt als unzuverlässig. In Bronzeinschriften stand das Zeichen meist für „verschwenden“.","i":"bs"},
"晩":{"t":"laut","x":"Die Sonne 日 gibt den Sinnbereich „Tageszeit“ an, 免 den Klang – im Altchinesischen klangen beide fast gleich. Gemeint war „Abend“, daraus „spät“.","s":2,"p":[["日","Sonne","b"],["免","befreien","l"]],"n":"Die traditionelle Form 晚 unterscheidet sich nur durch einen kleinen Strich in 免."},
"猫":{"t":"laut","x":"犭 gibt den Sinnbereich „Tier“ an, 苗 den Klang (苗 ビョウ → 猫 ビョウ). Ältere Form ist 貓 mit 豸 links; in 猫 wurde nur die linke Seite ausgetauscht.","s":2,"p":[["犭","Tier, Hund","b"],["苗","Setzling","l"]],"n":"Oft liest man, 苗 (gelesen ミョウ) ahme das Miauen nach. Die Forschung nennt das eine Volksdeutung: 苗 gibt die Aussprache des Wortes „Katze“ wieder, nicht den Katzenlaut."},
"園":{"t":"laut","x":"Die Umzäunung 囗 gibt den Sinnbereich an: ein eingefriedetes Stück Land. 袁 steuert den Klang bei (袁 エン → 園 エン). So bedeutet das Zeichen „Garten, Park“.","s":2,"p":[["囗","Umzäunung","b"],["袁","langes Gewand","l"]],"i":"s"},
"遠":{"t":"laut","x":"辶 „gehen“ gibt den Sinnbereich „Weg, Strecke“ an, 袁 den Klang (袁 エン → 遠 エン). Gemeint ist ein langer Weg: „fern, weit“.","s":2,"p":[["辶","gehen","b"],["袁","langes Gewand","l"]],"i":"obs"},
"係":{"t":"bild","x":"Auf den Orakelknochen zeigt das Zeichen einen Menschen, dessen Oberkörper gefesselt ist. Später wurden Mensch und Schnur getrennt geschrieben, daraus wurde 係. Aus „anbinden“ entstanden „verbunden sein, zusammenhängen“ und „zuständig sein“.","s":1,"p":[["亻","Mensch","b"],["系","Faden, Schnur","b"]],"n":"Oft liest man „Mensch 亻 + Klangteil 系“. Das geht auf das Shuowen zurück; die Orakelknochen zeigen aber einen gefesselten Menschen, und 系 ist eher eine Kurzform von 係.","i":"obs"},
"取":{"t":"kombi","x":"Eine Hand 又 hält ein Ohr 耳. Jäger schnitten erlegten Tieren das Ohr ab, um ihre Beute nachzuweisen. Daraus wurde „fangen, ergreifen“ und allgemein „nehmen“.","s":2,"p":[["耳","Ohr","b"],["又","Hand","b"]],"n":"Oft liest man, Krieger hätten Feinden die Ohren abgeschnitten. Dafür gibt es keinen Beleg; der Brauch ist nur für Jagdtiere bezeugt.","i":"obs"},
"守":{"t":"laut","x":"Das Dach 宀 gibt den Sinnbereich an: ein Gebäude, das man bewacht. 寸 war ursprünglich das Zeichen für den Ellbogen (später 肘) und steuert den Klang bei. So entstand „schützen, bewahren“.","s":1,"p":[["宀","Dach, Haus","b"],["寸","Ellbogen (Urform von 肘)","l"]],"n":"Oft liest man „eine Hand 寸 unter dem Dach = bewachen“. Die Bronzeinschriften sprechen eher dafür, dass 寸 (alte Form von 肘) den Klang liefert; ganz einig ist sich die Forschung darin aber nicht.","i":"obs"},
"幸":{"t":"unklar","x":"Der Aufbau ist nicht sicher geklärt. Alte Formen verbinden einen Hund 犬 mit einem zweiten Teil: je nach Gegend ein Schaf 羊 oder ein umgedrehter Pfeil 矢. Die heutige Form geht auf die Variante mit 犬 oben und 羊 unten zurück. Warum diese Teile „Glück“ ergeben, weiß man nicht.","s":0,"p":[["土","aus 犬 entstanden","f"],["𢆉","aus 羊 oder 矢","f"]],"n":"Oft liest man, 幸 zeige Handfesseln (man ist „glücklich“ davongekommen). Das beruht auf einer Verwechslung mit dem ähnlichen Zeichen 㚔 und gilt als falsch.","i":"s"},
"箱":{"t":"laut","x":"Bambus ⺮ gibt den Sinnbereich an: ein Behälter aus Bambus. 相 steuert den Klang bei (相 ソウ → 箱 ソウ). Bedeutung: „Kasten, Schachtel“.","s":2,"p":[["⺮","Bambus","b"],["相","gegenseitig","l"]],"i":"s"},
"面":{"t":"zeichen","x":"Ausgangspunkt ist das Bild eines Kopfes (wie in 首). Der Gesichtsteil – vor allem das Auge – wurde hervorgehoben, um „Gesicht“ zu bezeichnen. Der obere Querstrich kam später dazu. Aus „Gesicht“ wurden „Vorderseite, Fläche, Seite“.","s":1,"n":"Der innere Teil sieht aus wie 目, ist aber nur das hervorgehobene Auge. Mit 自 „Nase, selbst“ hat das Zeichen nichts zu tun. Im Chinesischen steht 面 heute auch als Kurzform für 麵 „Nudeln“.","i":"os"},
"喜":{"t":"kombi","x":"Oben steht 壴, die Urform von 鼓 „Trommel“, darunter 口. Das Zeichen schreibt das Wort für „sich freuen“.","s":1,"p":[["壴","Trommel","b"],["口","Mund","b"]],"n":"Ob 口 hier „Mund“ bedeutet oder nur ein Zusatzzeichen ohne eigene Bedeutung ist, ist umstritten.","i":"obs"},
"治":{"t":"laut","x":"Wasser 氵 als Sinnteil, 台 als Klangteil. Ursprünglich war 治 der Name eines Flusses. Später lieh man das Zeichen für das gleich klingende Wort „ordnen, regieren“ aus; daraus auch „heilen“.","s":2,"p":[["氵","Wasser","b"],["台","Sockel","l"]]},
"笑":{"t":"laut","x":"In den ältesten Formen stand oben Gras 艸 und unten ein Hund 犬; 艸 gab dabei wohl den Klang, 犬 den Sinn. Erst später wurde die Schreibung zu Bambus ⺮ und 夭 umgedeutet.","s":1,"p":[["⺮","urspr. Gras 艸","l"],["夭","urspr. Hund 犬","b"]],"n":"Das Shuowen erklärt 笑 als 竹 + 夭, und so findet man es oft. Die Formen vor der Qin-Zeit zeigen aber weder 竹 noch 夭; diese Deutung gilt als falsch.","i":"s"},
"辞":{"t":"laut","x":"Alte Form 辭: links 𤔔, zwei Hände, die Seidenfäden ordnen; rechts kam der Klangteil 𬔖 hinzu, der später zu 辛 verformt wurde. Die Bedeutung entwickelte sich wohl von „Fäden ordnen“ über „Streitfall klären, Aussage“ zu „Worte“ und „sich verabschieden, ablehnen“. 辞 ist eine Kurzform von 辭.","s":2,"p":[["舌","Kurzform, urspr. 𤔔","f"],["辛","verformt aus 𬔖","l"]],"n":"Mit 舌 „Zunge“ hat das Zeichen nichts zu tun: die linke Hälfte ist eine verkürzte Schreibung, die nur so aussieht. Auch 辛 ist nur eine verformte Gestalt des Klangteils.","a":"辭","i":"bs"},
"関":{"t":"laut","x":"Alte Form 關: Tor 門 als Sinnteil, darin 𢇇 als Klangteil. In Bronze-Inschriften sieht man ein Tor, das mit zwei Holzstäben verriegelt ist – „Riegel, Schranke“. Die heutige Form 関 entstand aus einer flüssigen Schreibschrift-Form von 關.","s":2,"p":[["門","Tor","b"],["关","Kurzform von 𢇇","l"]],"a":"關"},
"政":{"t":"laut","x":"攵 (Hand mit Stock) steht für eine Handlung, 正 gibt den Klang: 正 セイ → 政 セイ. Das Zeichen schreibt das Wort „ordnen, regieren“.","s":2,"p":[["正","richtig","l"],["攵","schlagen, Handlung","b"]]},
"留":{"t":"laut","x":"Feld 田 als Sinnteil, 卯 (oben, heute leicht abgewandelt) als Klangteil. Das Zeichen schreibt das Wort „bleiben, anhalten“.","s":2,"p":[["卯","Tierkreiszeichen Hase","l"],["田","Feld","b"]],"i":"s"},
"険":{"t":"laut","x":"Alte Form 險: Hügel 阝 (aus 阜) als Sinnteil, 僉 als Klangteil – wie in 検 ケン und 験 ケン. Das Zeichen schreibt das Wort „steil, schwer zugänglich“; daraus „gefährlich“. In 険 ist 僉 verkürzt.","s":2,"p":[["阝","Hügel","b"],["㑒","Kurzform von 僉","l"]],"a":"險","i":"s"},
"危":{"t":"laut","x":"Oben 厃, ein Mensch auf einer Klippe, unten 㔾 (卩), ein kniender Mensch. Nach einer Deutung gibt 厃 den Klang: Das Zeichen schrieb zuerst „knien“ (heute 跪) und wurde dann für das ähnlich klingende Wort „gefährlich“ ausgeliehen.","s":0,"p":[["厃","Mensch auf Klippe","l"],["㔾","kniender Mensch","b"]],"n":"Nach einer anderen Deutung ist es eine Sinnverbindung: ein Mensch oben auf der Klippe und ein kniender Mensch – also jemand in gefährlicher Lage.","i":"os"},
"存":{"t":"laut","x":"Das Zeichen besteht aus einem abgewandelten 才 (oben links) und 子. 才 gibt den Klang. Ursprünglich war 存 eine Nebenform von 在 „sich befinden, da sein“.","s":1,"p":[["才","Begabung","l"],["子","Kind","b"]],"n":"Nach einer anderen Deutung ist auch 子 ein Klangteil (im Altchinesischen ähnlich wie 才), nicht ein Sinnteil."},
"原":{"t":"laut","x":"Klippe 厂 als Sinnteil, Quelle 泉 als Klangteil; 泉 ist unten zu 白 und 小 verformt. Das Zeichen schrieb zuerst das Wort „Quelle, Ursprung“ (heute 源). Später lieh man es für das gleich klingende Wort „Ebene, Feld“ aus.","s":1,"p":[["厂","Klippe","b"],["泉","Quelle (heute 白+小)","l"]],"n":"Oft liest man „eine Quelle sprudelt aus der Felswand → Ursprung“, also eine reine Sinnverbindung. Diese Einordnung gilt heute als falsch: 泉 gibt hier den Klang.","i":"bs"},
"薬":{"t":"laut","x":"Alte Form 藥: Pflanze 艹 als Sinnteil – Arzneien waren meist Kräuter –, 樂 als Klangteil. In 薬 ist 樂 wie in 楽 verkürzt.","s":2,"p":[["艹","Gras, Pflanze","b"],["楽","Musik, Freude","l"]],"a":"藥","i":"bs"},
"側":{"t":"laut","x":"Mensch 亻 als Sinnteil, 則 als Klangteil: 則 ソク → 側 ソク.","s":2,"p":[["亻","Mensch","b"],["則","Regel","l"]]},
"席":{"t":"laut","x":"Ursprünglich ein Bild einer geflochtenen Matte. Später kam Stein 石 als Klangteil dazu: 石 セキ → 席 セキ. Die Matte wurde zu 巾 „Tuch“, 石 zum oberen Teil 广 + 廿 verformt. Grundbedeutung: Sitzmatte, daher „Sitzplatz“.","s":2,"p":[["广","verformt aus 石","l"],["巾","Tuch, urspr. Matte","b"]],"n":"Der obere Teil sieht aus wie in 度 und 庶; das Shuowen erklärte 席 deshalb mit 庶. Er ist aber ein verformtes 石."},
"敗":{"t":"laut","x":"攵 (Hand mit Stock, schlagen) als Sinnteil, 貝 als Klangteil: 貝 バイ → 敗 ハイ. Das Zeichen schreibt „zerstören, beschädigen“ und „zerstört werden, verlieren“.","s":2,"p":[["貝","Muschel","l"],["攵","schlagen","b"]],"i":"s"},
"果":{"t":"bild","x":"Bild eines Baumes 木, an dem Früchte hängen. Grundbedeutung „Frucht“; daraus „Ergebnis“.","s":2,"n":"Der obere Teil sieht heute wie 日 aus, zeigte aber die Früchte in der Baumkrone.","i":"obs"},
"因":{"t":"leih","x":"Ein Mensch 大 liegt auf einer Matte oder Decke 囗. Das Zeichen schrieb zuerst „Unterlage, Matte“ (heute 茵). Später wurde es für das gleich klingende Wort „beruhen auf, sich stützen auf“ ausgeliehen; daraus „Ursache“.","s":2,"p":[["囗","Matte","b"],["大","Mensch","b"]],"n":"Eine zweite mögliche Deutung sieht darin einen Menschen, der Kleidung trägt.","i":"obs"},
"常":{"t":"laut","x":"Tuch 巾 als Sinnteil, 尚 als Klangteil: 尚 ショウ → 常 ジョウ. Ursprünglich ein Gewand für den Unterkörper, ähnlich einem Rock (heute 裳). Dann für das gleich klingende Wort „dauernd, immer“ ausgeliehen.","s":2,"p":[["尚","verehren","l"],["巾","Tuch","b"]],"i":"bs"},
"識":{"t":"laut","x":"Sprechen 言 als Sinnteil, 戠 als Klangteil – derselbe wie in 職 und 織. Das Zeichen schreibt „wissen, verstehen“.","s":2,"p":[["訁","sprechen","b"],["戠","戠 (Klangteil)","l"]],"i":"bs"},
"非":{"t":"bild","x":"Bild zweier Menschen, die einander den Rücken zukehren – ähnlich wie 北. Zur Unterscheidung von 北 kamen oben kurze Querstriche hinzu. Das Zeichen steht für das Wort „nicht sein, nicht“.","s":1,"n":"Oft liest man nach dem Shuowen, 非 zeige zwei voneinander abgewandte Flügel. Die Orakelknochen-Formen sprechen aber dagegen.","i":"obs"},
"官":{"t":"kombi","x":"Unter einem Dach 宀 steht 𠂤 (heute wie 㠯 geschrieben). Zusammen bezeichnen sie ein Amtsgebäude, eine Behörde.","s":1,"p":[["宀","Dach","b"],["㠯","urspr. 𠂤","b"]],"n":"Was 𠂤 hier zeigt, ist unsicher: Eine Deutung sieht darin eine Truppe (Heerhaufen), eine andere mehrere Räume unter einem Dach."},
"察":{"t":"laut","x":"Dach 宀 als Sinnteil, 祭 als Klangteil. Das Zeichen schreibt „untersuchen, klar erkennen“.","s":2,"p":[["宀","Dach","b"],["祭","Fest, Opfer","l"]],"i":"bs"},
"愛":{"t":"laut","x":"Ursprünglich 㤅: Herz 心 als Sinnteil, 旡 als Klangteil. Schon zur Qin-Zeit kam unten ein Fuß 夂 ohne eigene Bedeutung dazu, und 旡 wurde oben zu 爫 + 冖 verformt. Das Zeichen schreibt „mögen, lieben“.","s":2,"p":[["爫","verformt aus 旡","l"],["冖","verformt aus 旡","f"],["心","Herz","b"],["夂","Fuß","f"]],"n":"爫 und 冖 haben in 愛 keine eigene Bedeutung, sie sind nur Reste des Klangteils 旡.","i":"s"},
"警":{"t":"laut","x":"Sprechen 言 als Sinnteil, 敬 als Klangteil: 敬 ケイ → 警 ケイ. Das Zeichen schreibt „warnen, ermahnen“.","s":2,"p":[["敬","achten","l"],["言","sprechen","b"]],"i":"s"},
"覚":{"t":"laut","x":"Alte Form 覺: Sehen 見 als Sinnteil, oben 𦥯 als Klangteil – derselbe wie in 學 (学): 学 ガク → 覚 カク. In 覚 ist der obere Teil genauso verkürzt wie in 学.","s":2,"p":[["⺍","Kurzform von 𦥯","l"],["見","sehen","b"]],"a":"覺","i":"s"},
"説":{"t":"laut","x":"言 (Wort, sprechen) ist der Sinnteil, 兑 (alte Schreibung 兌) der Klangteil. Das Zeichen steht für das Wort „darlegen, erklären“ – also etwas mit Worten auseinandersetzen.","s":2,"p":[["言","Wort, sprechen","b"],["兑","tauschen","l"]],"n":"Neben 説 gibt es die ältere Schreibung 說 mit 兌 rechts. Der Unterschied liegt nur in den zwei kleinen Strichen oben (丷 statt ハ); Aufbau und Herkunft sind gleich."},
"告":{"t":"unklar","x":"Die Herkunft ist ungeklärt. Eine Deutung sieht darin ein Bildzeichen: einen Mund, aus dem die Zunge herausragt. Eine andere sieht eine verkürzte Trommel (壴) über einem offenen Mund (口).","s":0,"n":"Oft liest man, oben stecke 牛 (Rind) – so zerlegt es schon das alte Wörterbuch 説文解字. Auf Orakelknochen und Bronzen sieht der obere Teil aber anders aus als 牛 und hat nichts damit zu tun.","i":"obs"},
"種":{"t":"laut","x":"禾 (Getreidepflanze) ist der Sinnteil: Es geht um Saatgut, „Samen“. 重 gibt den Klang (vgl. 重 ジュウ → 種 シュ). Aus „Samen“ wurde auch „Art, Sorte“.","s":2,"p":[["禾","Getreide","b"],["重","schwer","l"]],"i":"s"},
"達":{"t":"unklar","x":"辶 (gehen, unterwegs sein) zeigt den Sinnbereich „hingelangen, erreichen“. Der rechte Teil ist umstritten: Nach einer Deutung ist er der Klangteil 羍; nach einer anderen zeigte das Urzeichen einen Pfeil, der an einem Ziel ankommt, und 辶 kam erst später dazu.","s":0,"p":[["辶","gehen","b"]],"n":"Der rechte Teil ist nicht 幸 (Glück): Er hat unten drei waagrechte Striche statt zwei."},
"類":{"t":"laut","x":"犬 (Hund) ist der Sinnteil, 頪 (米 + 頁) der Klangteil; 犬 steht heute unter 米. 頪 zeigte auf Orakelknochen einen knienden Menschen, der Tränen vergießt – das Urzeichen für 涙 (Träne). 涙 ルイ und 類 ルイ klingen bis heute gleich.","s":2,"p":[["頪","weinender Mensch","l"],["犬","Hund","b"]],"i":"s"},
"報":{"t":"kombi","x":"Links eine Handfessel (㚔), rechts 𠬝 „unterwerfen“ (Urform von 服): ein gefesselter Verurteilter. Daher „bestrafen, (Strafe) vergelten“ und allgemein „erwidern, vergelten“. „Bericht“ kam erst später dazu.","s":2,"p":[["幸","Handfessel","b"],["𠬝","unterwerfen","b"]],"n":"Der linke Teil sieht heute aus wie 幸 (Glück), hat damit aber nichts zu tun: Ursprünglich war es das Bild einer Handfessel.","i":"bs"},
"等":{"t":"laut","x":"⺮ (Bambus) ist der Sinnteil: Gemeint sind die Bambusstreifen, auf die man früher schrieb und die gleichmäßig nebeneinanderlagen – daher „gleich“, auch „Rang, Klasse“. 寺 war der Klangteil; im Altchinesischen klangen beide ähnlich, heute (ジ / トウ) nicht mehr.","s":2,"p":[["⺮","Bambus","b"],["寺","Tempel","l"]]},
"座":{"t":"laut","x":"坐 (sitzen, ザ) gibt Klang und Bedeutung. Früher schrieb man mit 坐 sowohl „sitzen“ als auch „Sitzplatz“; für das Hauptwort fügte man 广 (Dach, Gebäude) hinzu: 坐 ザ → 座 ザ „Sitz, Platz“.","s":2,"p":[["广","Gebäude","b"],["坐","sitzen","l"]]},
"忘":{"t":"laut","x":"心 (Herz, Sinn) ist der Sinnteil, 亡 der Klangteil: 亡 ボウ → 忘 ボウ „vergessen“.","s":2,"p":[["亡","verlieren","l"],["心","Herz","b"]],"n":"Dieselben Bauteile wie 忙 (beschäftigt), nur anders angeordnet. Die beiden Wörter gehen im Chinesischen auf dasselbe Wort zurück.","i":"s"},
"洗":{"t":"laut","x":"氵 (Wasser) ist der Sinnteil, 先 der Klangteil: 先 セン → 洗 セン „waschen“.","s":2,"p":[["氵","Wasser","b"],["先","vorher","l"]]},
"許":{"t":"laut","x":"言 (Wort, sprechen) ist der Sinnteil, 午 der Klangteil. Im Altchinesischen klangen 午 und 許 ähnlich; heute (ゴ / キョ) hört man das nicht mehr. Bedeutung: „erlauben“.","s":2,"p":[["言","Wort, sprechen","b"],["午","Mittag","l"]]},
"静":{"t":"laut","x":"Ein seltener Fall mit zwei Klangteilen: 青 (セイ) und 爭 geben beide nur den Klang für „still, ruhig“. In alten Inschriften werden 青, 争 und 静 sogar füreinander verwendet. Die heutige Form verkürzt 爭 zu 争.","s":2,"p":[["青","blau","l"],["争","streiten","l"]],"n":"Das alte Wörterbuch 説文解字 sieht 青 (blau) als Sinnteil. Die Inschriften zeigen aber, dass 青 und 争 hier keine Bedeutung beisteuern, sondern nur den Klang.","a":"靜"},
"煙":{"t":"laut","x":"火 (Feuer) ist der Sinnteil, 垔 der Klangteil (垔 イン → 煙 エン): „Rauch“.","s":2,"p":[["火","Feuer","b"],["垔","verstopfen","l"]],"i":"s"},
"加":{"t":"kombi","x":"力 (Kraft, ursprünglich ein Pflug) und 口 (Mund). Nach einer Deutung steht 口 für das Rufen oder Keuchen bei der Arbeit: noch mehr Kraft hineinlegen → „hinzufügen, verstärken“.","s":1,"p":[["力","Kraft","b"],["口","Mund","b"]],"n":"Das alte Wörterbuch 説文解字 erklärt es anders: Kraft + Mund = „mit Worten übertreiben, verleumden“.","i":"bs"},
"容":{"t":"laut","x":"宀 (Dach, Haus) ist der Sinnteil für „aufnehmen, fassen“. Der Klangteil war 公 (im Altchinesischen ähnlich wie 容); in Bronzeinschriften ist das noch zu sehen, heute sieht der untere Teil wie 谷 aus.","s":2,"p":[["宀","Dach","b"],["公","öffentlich","l"]],"n":"Das alte Wörterbuch 説文解字 zerlegt 容 in 宀 + 谷 (Tal); das gilt heute als falsch. Die Bedeutung „Aussehen“ hat 容 von einem anderen Zeichen (頌) übernommen.","i":"bs"},
"易":{"t":"leih","x":"Ein Bildzeichen: ein Gefäß, aus dem Flüssigkeit gegossen wird. Es stand zuerst für „schenken, verleihen“ (heute 賜). Später wurde es für gleich klingende Wörter ausgeliehen: „tauschen“ (エキ) und „leicht“ (イ).","s":2,"n":"Oft liest man, 易 zeige eine Eidechse oder ein Chamäleon (so schon 説文解字), oder Sonne 日 + 勿. Die alten Schriftfunde zeigen aber ein Gefäß; mit der Sonne hat es nichts zu tun.","i":"obs"},
"財":{"t":"laut","x":"貝 (Muschel, früher Zahlungsmittel) ist der Sinnteil für „Wertsachen, Vermögen“. 才 gibt den Klang: 才 サイ → 財 ザイ.","s":2,"p":[["貝","Muschel","b"],["才","Begabung","l"]]},
"若":{"t":"leih","x":"Ursprünglich ein kniender Mensch, der mit den Händen ins Haar greift (叒). Später kam unten ein 口 als reines Unterscheidungszeichen dazu. Das Zeichen stand für „gehorchen“ und wurde für das Bindewort „falls, wenn“ ausgeliehen.","s":1,"p":[["艹","Hände, Haar","f"],["口","Zierzeichen","f"]],"n":"Der heutige Aufbau aus 艹 und 右 ist nur eine spätere Schreibform, kein Hinweis auf die Herkunft. Die Deutung als betende Schamanin mit erhobenen Händen ist nicht belegt. Nach einer Nebendeutung zeigte das Zeichen eine Hand, die Gras auswählt.","i":"obs"},
"忙":{"t":"laut","x":"忄 (Herz, Gemüt) ist der Sinnteil, 亡 der Klangteil: 亡 ボウ → 忙 ボウ „beschäftigt“.","s":2,"p":[["忄","Herz","b"],["亡","verlieren","l"]],"n":"Dieselben Bauteile wie 忘 (vergessen), nur anders angeordnet. Die beiden Wörter gehen im Chinesischen auf dasselbe Wort zurück."},
"徒":{"t":"laut","x":"Ursprünglich 辵 (gehen, unterwegs sein) als Sinnteil und 土 als Klangteil: „zu Fuß gehen“ (土 ト → 徒 ト). Später verschob sich die Schreibung, sodass das Zeichen heute aus 彳 und 走 (laufen) zu bestehen scheint.","s":2,"p":[["彳","Weg","b"],["土","Erde","l"],["止","Fuß","b"]],"n":"In der heutigen Form steckt 辵 geteilt: 彳 links, der Fuß (止) unten rechts; 土 sitzt dazwischen.","i":"s"},
"得":{"t":"kombi","x":"Eine Hand (又) greift nach einer Muschel (貝), dem alten Zahlungsmittel: Wertvolles in die Hand bekommen → „erlangen“. Später kam 彳 (Weg) dazu – die Muschel wurde unterwegs aufgehoben.","s":2,"p":[["彳","Weg","b"],["旦","Muschel (貝)","b"],["寸","Hand (又)","b"]],"n":"Heute ist die Muschel kaum zu erkennen: 貝 wurde in der Kanzleischrift zu 目 verkürzt und dann zu 旦 verformt; die Hand 又 wurde zu 寸.","i":"obs"},
"続":{"t":"laut","x":"糸 (Faden) ist der Sinnteil für „fortsetzen, anknüpfen“, der rechte Teil 𧶠 war der Klangteil. Die heutige Form ersetzt ihn durch das kürzere 売.","s":2,"p":[["糸","Faden","b"],["売","verkaufen","l"]],"n":"Der rechte Teil war eigentlich 𧶠, das fast wie 賣 (verkaufen) aussieht; bei der Schriftreform wurde er wie 賣 zu 売 verkürzt.","a":"續","i":"os"},
"困":{"t":"leih","x":"Holz (木) in einer Umrandung (囗): zusammengeschnürtes Holz, „bündeln, schnüren“ (heute 梱). Für das ähnlich klingende Wort „in die Enge geraten, in Not sein“ wurde das Zeichen ausgeliehen.","s":1,"p":[["囗","Umrandung","b"],["木","Holz","b"]],"n":"Manche deuten 困 als Querholz einer Tür (Türschwelle). Dagegen spricht, dass Türen in der Schrift als 門 erscheinen, nie als 囗.","i":"os"},
"機":{"t":"laut","x":"木 (Holz) ist der Sinnteil, 幾 der Klangteil: 幾 キ → 機 キ. Gemeint war zuerst ein Webstuhl bzw. eine Vorrichtung aus Holz; daraus wurde „Maschine“.","s":2,"p":[["木","Holz","b"],["幾","wie viele","l"]],"i":"s"},
"飛":{"t":"bild","x":"Ein Vogel, der mit ausgebreiteten Flügeln auffliegt: „fliegen“.","s":2,"i":"os"},
"害":{"t":"unklar","x":"Woher die Form von 害 kommt, ist nicht geklärt; es gibt viele Theorien, aber keine hat sich durchgesetzt. Sicher ist nur: Das Zeichen wurde für ein gleich klingendes Wort „schädigen, Schaden“ ausgeliehen.","s":0,"n":"Das alte Wörterbuch Shuowen zerlegt es in 宀 (Dach), 口 (Mund) und einen Klangteil. Die Bronze-Inschriften, auf die sich viele dieser Erklärungen stützten, zeigen laut neuerer Forschung gar nicht dieses Zeichen.","i":"bs"},
"余":{"t":"laut","x":"Die Bedeutung „Rest, übrig“ stammt vom alten Zeichen 餘: Sinnteil 食 (Essen) plus Klangteil 余 (余 ヨ → 餘 ヨ), ursprünglich „Essensreste“. In Japan schreibt man dafür heute einfach 余, das Essen-Bauteil fiel weg.","s":2,"p":[["食","Essen","b"],["余","Hütte; ich","l"]],"n":"余 selbst war ein Bildzeichen, wohl für eine strohgedeckte Hütte (vielleicht Urform von 舎); was es genau zeigt, ist unsicher. Es wurde früh für das Wort „ich“ ausgeliehen.","a":"餘","i":"s"},
"難":{"t":"laut","x":"Sinnteil 隹 (Vogel) plus Klangteil links (𦰩, ナン). Ursprünglich bezeichnete das Zeichen eine Vogelart. Es wurde dann für gleich klingende Wörter ausgeliehen: „Unglück, Not“ und „schwierig“.","s":2,"p":[["𦰩","Teil von 暵","l"],["隹","Vogel","b"]],"n":"Manchmal wird das Zeichen als Sinnverbindung gedeutet; das gilt in der Forschung als falsche Zerlegung."},
"確":{"t":"laut","x":"Sinnteil 石 (Stein) plus Klangteil 隺 (カク → 確 カク). Gemeint war „hart, fest“ – fest wie ein Stein. Daraus wurde „sicher, gewiss, bestätigen“.","s":2,"p":[["石","Stein","b"],["隺","hochfliegen","l"]]},
"在":{"t":"laut","x":"Zuerst lieh man sich einfach 才 (サイ) für das Wort „sich befinden, da sein“ (在 ザイ). Später kam 士 als zweiter Klangteil dazu. Beide Teile geben also den Klang an, keiner die Bedeutung.","s":2,"p":[["才","Begabung","l"],["士","Mann (heute 土)","l"]],"n":"Der untere Teil sieht heute wie 土 (Erde) aus, war aber ursprünglich 士; vom 才 sind oben links nur noch Striche übrig. „Etwas ist auf der Erde“ ist deshalb keine echte Herleitung.","i":"obs"},
"夢":{"t":"bild","x":"Auf Orakelknochen ein Bild: ein Mensch liegt auf einem Bett, manchmal mit betontem Auge. Später fiel das Bett weg und 夕 (Nacht) kam hinzu. Im heutigen Zeichen sind oben die Brauen, darunter das Auge (罒), dann der Körper (冖) und 夕.","s":2,"p":[["艹","Augenbrauen","f"],["罒","Auge","b"],["冖","Körper","f"],["夕","Abend, Nacht","b"]],"n":"Das alte Wörterbuch Shuowen sah es als 瞢 (Klangteil) plus 夕; die Orakelknochen zeigen aber das Bild des Schlafenden.","i":"obs"},
"産":{"t":"laut","x":"Sinnteil 生 (geboren werden, wachsen) plus Klangteil 产, eine Verkürzung von 彦. Gemeint war „gebären, hervorbringen“; daraus „erzeugen, Erzeugnis“.","s":2,"p":[["产","aus 彦","l"],["生","geboren werden","b"]],"n":"Früher deutete man das Zeichen als Sinnverbindung; die Forschung hält das für unbegründet. In der traditionellen Form 產 steht oben 文 statt 立."},
"倒":{"t":"laut","x":"Sinnteil 亻 (Mensch) plus Klangteil 到 (到 トウ → 倒 トウ). Gemeint ist ein Mensch, der umfällt: „umfallen, umstürzen“.","s":2,"p":[["亻","Mensch","b"],["到","ankommen","l"]],"i":"s"},
"妻":{"t":"kombi","x":"Die alten Formen zeigen eine Frau (女), an deren Haar eine Hand greift. Das Zeichen stand für „Ehefrau“. Wie genau das Bild gemeint war, ist nicht gesichert.","s":1,"p":[["肀","Hand","b"],["女","Frau","b"]],"n":"Oft liest man „Frau mit Haarschmuck“; das passt nicht zu den Orakelknochen- und Bronzeformen. Eine Deutung sieht im Griff ins Haar einen Hinweis auf Brautraub – das ist aber nur eine Vermutung.","i":"bs"},
"議":{"t":"laut","x":"Sinnteil 訁 (sprechen) plus Klangteil 義 (義 ギ → 議 ギ). Gemeint ist „miteinander reden, beraten“.","s":2,"p":[["訁","sprechen","b"],["義","Gerechtigkeit","l"]],"i":"s"},
"犯":{"t":"laut","x":"Sinnteil 犭 (Hund) plus ein Klangteil, der heute wie 㔾 aussieht. Das Zeichen stand für das Wort „verletzen, übertreten“; daraus „ein Verbrechen begehen“.","s":2,"p":[["犭","Hund","b"],["㔾","Klangteil","l"]],"i":"s"},
"罪":{"t":"kombi","x":"Für „Schuld, Verbrechen“ schrieb man früher 辠. Weil es 皇 (Kaiser) ähnelte, soll der erste Kaiser von Qin es durch 罪 ersetzt haben: oben 罒 (wohl verkürzt aus 罰 „Strafe“), unten 非 (Unrecht).","s":1,"p":[["罒","Strafe (罰) / Netz","b"],["非","Unrecht","b"]],"n":"Oft liest man „mit dem Netz (网) fängt man alle, die Unrecht (非) tun“. Ob 罒 hier für „Netz“ steht, ist zweifelhaft. Eine andere Deutung sieht in 罪 ein altes Zeichen für ein Fischnetz."},
"論":{"t":"laut","x":"Sinnteil 訁 (sprechen) plus Klangteil 侖 (侖 ロン → 論 ロン). Zuerst stand 侖 allein für das Wort „darlegen, erörtern“; später kam 訁 dazu.","s":2,"p":[["訁","sprechen","b"],["侖","ordnen","l"]],"i":"bs"},
"経":{"t":"laut","x":"Alte Form 經: Sinnteil 糹 (Faden) plus Klangteil 巠 (ケイ → 經 ケイ). Gemeint waren die Längsfäden am Webstuhl; zuerst schrieb man dafür nur 巠. Im heutigen 経 wurde 巠 zu 圣 vereinfacht.","s":2,"p":[["糹","Faden","b"],["圣","aus 巠","l"]],"n":"Das 圣 in 経 ist nur eine Kurzform und hat mit dem chinesischen Zeichen 圣 nichts zu tun.","a":"經"},
"済":{"t":"laut","x":"Alte Form 濟: Sinnteil 氵 (Wasser) plus Klangteil 齊 (セイ → 濟 セイ/サイ). Im heutigen 済 ist 齊 wie im Zeichen 斉 vereinfacht.","s":2,"p":[["氵","Wasser","b"],["斉","aus 齊","l"]],"n":"Oft liest man, 齊 bedeute hier „gleichmäßig“, also „Wassermenge regeln“. Das gilt als konstruiert: Der Teil gibt nur den Klang an.","a":"濟"},
"判":{"t":"laut","x":"Sinnteil 刂 (Messer) plus Klangteil 半 (半 ハン → 判 ハン). Gemeint war „teilen, trennen“; daraus „unterscheiden, urteilen“.","s":2,"p":[["半","Hälfte","l"],["刂","Messer","b"]]},
"制":{"t":"kombi","x":"Das Zeichen zeigt einen Baum und ein Messer: Mit dem Messer wird in den Baum geschnitten. Die Grundbedeutung war „abschneiden“; später kamen „regeln, beherrschen“ hinzu.","s":2,"p":[["木","Baum (verändert)","b"],["刂","Messer","b"]],"n":"Der linke Teil sieht heute nicht mehr wie 木 aus. Das alte Wörterbuch Shuowen las ihn als 未; die Bronzeformen zeigen, dass das falsch ist. 制 ist eng verwandt mit 折 (brechen).","i":"bs"},
"務":{"t":"laut","x":"Sinnteil 力 (Kraft) plus Klangteil 敄 (aus 矛 + 攵; 矛 ム → 務 ム). Gemeint ist „sich anstrengen, sich bemühen“; daraus „Pflicht, Aufgabe“.","s":2,"p":[["矛","Lanze","l"],["攵","schlagen","l"],["力","Kraft","b"]],"i":"bs"},
"資":{"t":"laut","x":"Sinnteil 貝 (Muschel; Muscheln dienten früher als Geld) plus Klangteil 次 (次 シ → 資 シ). Gemeint waren „Vorräte, Vermögen“; daraus „Mittel, Kapital“.","s":2,"p":[["次","nächster","l"],["貝","Muschel, Geld","b"]],"n":"Früher deutete man 次 auch als Bedeutungsträger; die Forschung hält das für falsch – es gibt nur den Klang an.","i":"s"},
"権":{"t":"laut","x":"Alte Form 權: Sinnteil 木 (Baum) plus Klangteil 雚 (カン → 權 ケン). Zuerst war es der Name einer Baumart; dann wurde es für „Gewicht der Waage“ ausgeliehen, später „Macht, Recht“. Im heutigen 権 ist 雚 nach der Schreibschrift verkürzt.","s":2,"p":[["木","Baum","b"],["𮥶","aus 雚","l"]],"a":"權","i":"s"},
"件":{"t":"kombi","x":"Sinnverbindung aus 亻 (Mensch) und 牛 (Rind). Das Wort bedeutete ursprünglich „teilen, aufteilen“; heute steht es für „einzelne Sache, Angelegenheit“. Wie die beiden Teile diesen Sinn ergeben, ist nicht geklärt.","s":1,"p":[["亻","Mensch","b"],["牛","Rind","b"]],"i":"s"},
"断":{"t":"laut","x":"Alte Form 斷: Sinnteil 斤 (Axt) plus 㡭, ein Bild durchtrennter Fäden, das zugleich den Klang gibt. Zuerst stand 㡭 allein für „abtrennen, abschneiden“, dann kam die Axt dazu. Im heutigen 断 ist die linke Seite stark verkürzt.","s":1,"p":[["㡭","abschneiden","l"],["斤","Axt","b"]],"a":"斷","i":"bs"},
"任":{"t":"laut","x":"Sinnteil 亻 (Mensch) plus Klangteil 壬 (壬 ニン → 任 ニン). Gemeint war „eine Last an der Tragestange auf der Schulter tragen“; daraus „übernehmen, Verantwortung, anvertrauen“.","s":2,"p":[["亻","Mensch","b"],["壬","Tragestange","l"]],"n":"Möglicherweise zeigt 壬 selbst eine um 90 Grad gedrehte Tragestange.","i":"obs"},
"責":{"t":"laut","x":"Sinnteil 貝 (Muschel, Geld) plus Klangteil 朿 (Dorn). Gemeint waren Abgaben und Schulden, die man einfordert; daraus „fordern, vorwerfen“ und „Verantwortung“.","s":2,"p":[["龶","aus 朿 (Dorn)","l"],["貝","Muschel, Geld","b"]],"n":"Der obere Teil sieht heute wie 生 ohne den schrägen Strich aus, war aber 朿 – ähnlich wie in 青 und 素.","i":"s"},
"増":{"t":"laut","x":"Alte Form 增: Sinnteil 土 (Erde) plus Klangteil 曾 (ソウ/ゾウ → 增 ゾウ). Gemeint ist „mehr werden, vermehren“. Im heutigen 増 ist 曾 zu 曽 vereinfacht.","s":2,"p":[["土","Erde","b"],["曽","aus 曾","l"]],"a":"增","i":"obs"},
"解":{"t":"kombi","x":"Horn 角, Messer 刀 und Rind 牛: Einem Rind wird das Horn abgetrennt, das Tier wird zerlegt. Daraus die Grundbedeutung „auseinandernehmen, lösen“.","s":1,"p":[["角","Horn","b"],["刀","Messer","b"],["牛","Rind","b"]],"n":"In den ältesten Formen halten zwei Hände das Horn; eine der beiden Hände wurde später in der Form zum Messer 刀.","i":"obs"},
"際":{"t":"laut","x":"阝 (links, Form von 阜 „Erdwall, Hügel“) ist der Sinnteil, 祭 der Klangteil (祭 サイ → 際 サイ). Gemeint war die Stelle, an der zwei Dinge aneinanderstoßen – Rand, Zwischenraum.","s":2,"p":[["阝","Erdwall, Hügel","b"],["祭","Fest, Opfer","l"]]},
"認":{"t":"laut","x":"言 „sagen, Wort“ ist der Sinnteil, 忍 der Klangteil (忍 ニン → 認 ニン). Das Wort bedeutete „genau erkennen, feststellen“; daraus „anerkennen“.","s":2,"p":[["言","Wort, sagen","b"],["忍","ertragen","l"]]},
"過":{"t":"laut","x":"辶 (gehen, unterwegs sein) ist der Sinnteil, 咼 der Klangteil (咼 カ → 過 カ). Bedeutung: an etwas vorbeigehen, darüber hinausgehen – daher „vergehen, überschreiten, zu viel“.","s":2,"p":[["辶","gehen","b"],["咼","Lautzeichen","l"]],"i":"bs"},
"寝":{"t":"laut","x":"Alte Form 寢: 宀 „Dach, Haus“ und 爿 „Bett“ geben den Sinnbereich, 𠬶 ist der Klangteil (wie in 侵 シン → 寝 シン). Bedeutung: schlafen, sich hinlegen. Heute ist 爿 zu 丬 verkürzt.","s":1,"p":[["宀","Dach, Haus","b"],["丬","Bett","b"],["𠬶","Hand mit Besen","l"]],"n":"In den ältesten Inschriften wurde „schlafen“ mit einem einfacheren Zeichen ohne Klangteil geschrieben; 𠬶 kam erst später dazu.","a":"寢"},
"置":{"t":"laut","x":"罒 (Form von 网 „Netz“) ist der Sinnteil, 直 der Klangteil (直 チョク ~ 置 チ; im Altchinesischen klangen beide noch fast gleich). Das Wort bedeutete „hinstellen, hinsetzen, legen“.","s":2,"p":[["罒","Netz","b"],["直","gerade","l"]]},
"費":{"t":"laut","x":"貝, die Kaurimuschel, die früher als Zahlungsmittel diente, zeigt den Sinnbereich Geld und Wert. 弗 ist der Klangteil (弗 フツ ~ 費 ヒ). Bedeutung: „aufwenden, verbrauchen, ausgeben“.","s":2,"p":[["弗","nicht","l"],["貝","Muschel, Geld","b"]]},
"示":{"t":"bild","x":"Das Bild eines Altars bzw. einer Ahnentafel, an der den Vorfahren und Göttern geopfert wurde. Deshalb steht 示 (links oft als 礻) in vielen Zeichen rund um Götter und Rituale, etwa 神, 社, 祭.","s":1,"n":"Die Bedeutung „zeigen“ hat eine eigene Herkunft: Bis zur Qin-Zeit schrieb man dieses Wort mit 視. Erst in der Han-Zeit erscheint dafür eine verkürzte Form, die genauso aussah wie das Altar-Zeichen – zwei Zeichen fielen zusammen.","i":"os"},
"観":{"t":"laut","x":"Alte Form 觀: 見 „sehen“ ist der Sinnteil, 雚 der Klangteil (雚 カン → 観 カン). Bedeutung: genau hinsehen, betrachten. Die heutige Form kürzt 雚 nach seiner Schreibschrift-Form ab.","s":2,"p":[["雚","Reiher","l"],["見","sehen","b"]],"a":"觀","i":"s"},
"値":{"t":"laut","x":"亻 (Mensch) ist der Sinnteil, 直 der Klangteil (直 チョク ~ 値 チ). Zuerst bedeutete das Wort „treffen, auf etwas stoßen“; „Preis, Wert“ ist eine später für ein gleich klingendes Wort ausgeliehene Bedeutung.","s":1,"p":[["亻","Mensch","b"],["直","gerade","l"]]},
"吸":{"t":"laut","x":"口 „Mund“ ist der Sinnteil, 及 der Klangteil (及 キュウ → 吸 キュウ). Bedeutung: mit dem Mund einziehen, einatmen, saugen.","s":2,"p":[["口","Mund","b"],["及","erreichen","l"]]},
"状":{"t":"laut","x":"Alte Form 狀: 犬 „Hund“ ist der Sinnteil, 爿 der Klangteil (爿 ショウ ~ 状 ジョウ). Das Wort bedeutete „Gestalt, Aussehen, Zustand“. In der heutigen Form ist 爿 zu 丬 verkürzt.","s":2,"p":[["丬","Bett","l"],["犬","Hund","b"]],"a":"狀"},
"収":{"t":"laut","x":"Alte Form 收: 攵 (Hand mit Stock, „einwirken, schlagen“) ist der Sinnteil, 丩 der Klangteil (丩 キュウ ~ 収 シュウ). Ursprünglich „festnehmen“, daraus „einziehen, einsammeln“. Heute ist 攵 zu 又 vereinfacht.","s":1,"p":[["丩","verschlungen","l"],["又","Hand","b"]],"a":"收","i":"s"},
"職":{"t":"laut","x":"耳 „Ohr“ ist der Sinnteil, 戠 der Klangteil (戠 ショク → 職 ショク). Zuerst schrieb das Zeichen das Wort „wissen, erkennen“ (heute 識); später wurde es für das gleich klingende Wort „Amt, Aufgabe“ ausgeliehen.","s":1,"p":[["耳","Ohr","b"],["戠","Lautzeichen","l"]],"i":"s"},
"規":{"t":"laut","x":"Das Wort bedeutete „Zirkel“ zum Kreiseziehen, daraus „Maßstab, Regel“. Die älteste Form zeigte wohl einen kreuzförmigen Zirkel. In der heutigen Form gilt 夫 als verkürztes 矩 „Winkelmaß“ und 見 als Klangteil.","s":0,"p":[["夫","Winkelmaß (aus 矩)","b"],["見","sehen","l"]],"n":"Oft liest man „ein erwachsener Mann 夫, den man sich als Vorbild ansieht 見“. Diese Deutung gilt heute als falsch.","i":"s"},
"割":{"t":"laut","x":"刂 (Messer) ist der Sinnteil, 害 der Klangteil – im Altchinesischen klangen beide gleich (etwa „kat“), heute 害 ガイ, 割 カツ. Bedeutung: mit dem Messer zerteilen, spalten.","s":2,"p":[["害","Schaden","l"],["刂","Messer","b"]],"i":"s"},
"演":{"t":"laut","x":"氵 (Wasser) ist der Sinnteil, 寅 der Klangteil (寅 イン ~ 演 エン). Ursprünglich hieß das Wort „Wasser fließt weiter, breitet sich aus“; die Bedeutungen „vortragen, aufführen“ kamen später hinzu.","s":2,"p":[["氵","Wasser","b"],["寅","Tierkreis: Tiger","l"]]},
"師":{"t":"kombi","x":"Auf Orakelknochen schrieb man das Wort „Meister, Anführer“ mit 帀 und das gleich klingende Wort „Heer, Truppe“ mit 𠂤. In der Westlichen Zhou-Zeit wurden beide zu 師 verbunden. Was die zwei Teile ursprünglich abbildeten, ist unbekannt.","s":1,"p":[["𠂤","Heer","b"],["帀","Meister","b"]],"i":"bs"},
"備":{"t":"laut","x":"亻 (Mensch) ist der Sinnteil, 𤰈 der Klangteil (heute rechts als 卄 + 厂 + 用 geschrieben). 𤰈 stellte einen Köcher dar. Bedeutung: „bereithalten, vorbereiten, ausrüsten“.","s":1,"p":[["亻","Mensch","b"],["𤰈","Köcher","l"]],"n":"Oft liest man „ein Mensch mit Köcher auf dem Rücken ist gerüstet“. Neuere Analysen sehen 𤰈 hier aber nur als Klangteil.","i":"obs"},
"優":{"t":"laut","x":"亻 (Mensch) ist der Sinnteil, 憂 der Klangteil (憂 ユウ → 優 ユウ). Das Wort bedeutete „sanft, freundlich“; „überlegen“ und „Schauspieler“ sind spätere Bedeutungen.","s":2,"p":[["亻","Mensch","b"],["憂","Sorge","l"]],"n":"Erklärungen wie „ein Mensch, der sich sorgt (憂), ist sanft“ gelten als falsch – 憂 gibt hier nur den Klang."},
"宅":{"t":"laut","x":"宀 (Dach, Haus) ist der Sinnteil, 乇 der Klangteil (乇 タク → 宅 タク). Bedeutung: Wohnhaus, Wohnsitz.","s":2,"p":[["宀","Dach, Haus","b"],["乇","Lautzeichen","l"]]},
"現":{"t":"laut","x":"王 (hier für 玉 „Jade“) ist der Sinnteil, 見 der Klangteil (見 ケン → 現 ゲン). Zuerst stand das Zeichen für den „Glanz von Jade“; später wurde es für das gleich klingende Wort „erscheinen“ ausgeliehen.","s":1,"p":[["王","Jade (玉)","b"],["見","sehen","l"]],"n":"Oft liest man „man sieht den Glanz der Jade – so erscheint etwas“. Beide Wörter gab es aber schon getrennt; „erscheinen“ ist eine Ausleihe, keine Ableitung."},
"呼":{"t":"laut","x":"口 „Mund“ ist der Sinnteil, 乎 der Klangteil (乎 コ → 呼 コ). Bedeutung: ausatmen, laut rufen.","s":2,"p":[["口","Mund","b"],["乎","Fragepartikel","l"]]},
"違":{"t":"laut","x":"辶 (gehen) ist der Sinnteil, 韋 der Klangteil (韋 イ → 違 イ). Ursprünglich „auseinandergehen, abweichen, sich widersetzen“; daraus „sich unterscheiden, falsch sein“.","s":2,"p":[["辶","gehen","b"],["韋","Leder","l"]],"i":"s"},
"差":{"t":"laut","x":"Unten steht 左 – ursprünglich nur eine Hand, später zu 左 erweitert; es gibt auch den Klang (左 サ → 差 サ). Was oben steht, ist umstritten: Weizen, den man zwischen den Händen reibt, oder ein Bündel Holzkohle. „Unterschied“ ist eine spätere, ausgeliehene Bedeutung.","s":0,"p":[["𦍌","Ähren/Bündel","b"],["左","links, Hand","l"]],"n":"Der obere Teil sieht heute aus wie 羊 „Schaf“, hat damit aber nichts zu tun.","i":"bs"},
"供":{"t":"laut","x":"亻 (Mensch) ist der Sinnteil, 共 gibt den Klang (共 キョウ → 供 キョウ). Ursprünglich schrieb man das Wort „darbieten, bereitstellen“ einfach mit 共; erst später kam der Menschen-Teil dazu.","s":2,"p":[["亻","Mensch","b"],["共","gemeinsam","l"]],"i":"s"},
"限":{"t":"laut","x":"阝 (links, eine Form von 阜 „Hügel, Erdwall“) gibt den Sinnbereich an, 艮 den Klang. Gemeint ist „Grenze, Schranke“ – passend zu einem Erdwall, der etwas abgrenzt.","s":2,"p":[["阝","Hügel, Erdwall","b"],["艮","Klangteil","l"]]},
"与":{"t":"laut","x":"Die alte Form 與 verbindet 舁 (mehrere Hände, die etwas gemeinsam anheben) mit 牙 als Klangteil; gemeint ist „geben“. Die heutige Form 与 ist nur der mittlere Teil, der auf eine Nebenform von 牙 zurückgeht.","s":1,"p":[["舁","gemeinsam heben","b"],["牙","Eckzahn","l"]],"n":"Dass der Strich heute unten herausragt, wurde bei der japanischen Schriftreform nach dem Krieg ohne besonderen Grund so festgelegt.","a":"與","i":"s"},
"渡":{"t":"laut","x":"氵 (Wasser) zeigt den Sinnbereich – ein Gewässer überqueren –, 度 gibt den Klang (度 ト → 渡 ト).","s":2,"p":[["氵","Wasser","b"],["度","Maß, Mal","l"]]},
"景":{"t":"laut","x":"日 (Sonne) ist der Sinnteil, 京 der Klangteil (京 ケイ → 景 ケイ). Ursprünglich bedeutete das Zeichen „Sonnenlicht“; heute steht es für „Anblick, Landschaft“.","s":2,"p":[["日","Sonne","b"],["京","Hauptstadt","l"]],"i":"s"},
"抜":{"t":"laut","x":"Die alte Form 拔 verbindet 扌 (Hand) als Sinnteil – mit der Hand herausziehen – mit 犮 als Klangteil (犮 バツ → 拔 バツ). In der heutigen Form wurde 犮 durch das ähnlich aussehende 友 ersetzt.","s":2,"p":[["扌","Hand","b"],["犮","Klangteil (heute wie 友)","l"]],"n":"友 (Freund) hat mit der Bedeutung nichts zu tun; es ist nur eine Vereinfachung der Form.","a":"拔","i":"s"},
"候":{"t":"laut","x":"亻 (Mensch) ist der Sinnteil, 侯 gibt den Klang (侯 コウ → 候 コウ). Das Wort bedeutete zuerst „warten, Ausschau halten“; die heutigen Bedeutungen wie „Wetter, Jahreszeit“ kamen erst später hinzu.","s":2,"p":[["亻","Mensch","b"],["侯","Fürst","l"]],"n":"Der kleine senkrechte Strich in der Mitte gehört zum Klangteil: Eine alte Form von 侯 wurde beim Einbau leicht abgewandelt, deshalb sieht 候 wie 侯 mit einem Extrastrich aus."},
"構":{"t":"laut","x":"木 (Holz) gibt den Sinnbereich an – etwas aus Holz zusammenbauen –, 冓 den Klang (冓 コウ → 構 コウ).","s":2,"p":[["木","Holz, Baum","b"],["冓","Klangteil","l"]]},
"捕":{"t":"laut","x":"扌 (Hand) zeigt den Sinnbereich – mit der Hand fangen –, 甫 gibt den Klang (甫 ホ → 捕 ホ).","s":2,"p":[["扌","Hand","b"],["甫","Klangteil","l"]]},
"慣":{"t":"laut","x":"忄 (Herz, Gemüt) ist der Sinnteil, 貫 gibt den Klang (貫 カン → 慣 カン). Gemeint ist „sich an etwas gewöhnen“.","s":2,"p":[["忄","Herz","b"],["貫","durchziehen","l"]]},
"満":{"t":"laut","x":"Die alte Form 滿 verbindet 氵 (Wasser) als Sinnteil – Wasser bis zum Rand – mit 㒼 als Klangteil; gemeint ist „voll sein“. Im heutigen 満 ist der rechte Teil zu 艹 über 両 verkürzt.","s":2,"p":[["氵","Wasser","b"],["㒼","Klangteil","l"]],"n":"Manche Bücher deuten 㒼 auch als Bedeutungsträger. Das gilt heute als unbegründete Vermutung; 㒼 liefert nur den Klang.","a":"滿"},
"掛":{"t":"laut","x":"扌 (Hand) gibt den Sinnbereich an – etwas mit der Hand einhaken, aufhängen –, 卦 den Klang. Ursprünglich war 掛 eine volkstümliche Nebenform von 挂.","s":2,"p":[["扌","Hand","b"],["卦","Orakelzeichen","l"]]},
"居":{"t":"laut","x":"尸 (ein Körper, eine sitzende Gestalt) ist der Sinnteil, 古 gibt den Klang (古 コ → 居 コ). Gemeint ist „sitzen, sich aufhalten, wohnen“.","s":2,"p":[["尸","Körper","b"],["古","alt","l"]],"i":"s"},
"突":{"t":"kombi","x":"Zusammengesetzt aus 穴 (Loch) und 犬 (Hund). Das Zeichen stand für gleich klingende Wörter für „Loch“ und „plötzlich“; auch andere Zeichen mit 犬 tragen die Bedeutung „plötzlich“. In der japanischen Form ist 犬 zu 大 verkürzt.","s":1,"p":[["穴","Loch","b"],["犬","Hund (heute 大)","b"]],"n":"Oft liest man „ein Hund schießt plötzlich aus seinem Bau“. Diese alte Deutung wurde nur aus der Form erraten und gilt heute als nicht belegt.","i":"os"},
"招":{"t":"laut","x":"扌 (Hand) ist der Sinnteil – mit der Hand herbeiwinken –, 召 gibt den Klang (召 ショウ → 招 ショウ).","s":2,"p":[["扌","Hand","b"],["召","herbeirufen","l"]]},
"段":{"t":"leih","x":"Die Bronzeform zeigt eine Hand mit Hammer (殳), die von einem Stein (links) Stücke abschlägt; das Wort bezeichnete zunächst einen Schleifstein. Später wurde das Zeichen für ein ähnlich klingendes Wort „Abschnitt, Stufe“ ausgeliehen.","s":1,"p":[["厂","Felsen, Stein","b"],["殳","Hammer in der Hand","b"]],"n":"殳 war ursprünglich das Bild eines Hammers; später stand es für eine Stangenwaffe aus Bambus.","i":"bs"},
"腹":{"t":"laut","x":"月 steht hier für 肉 (Fleisch) und zeigt: ein Körperteil. 复 gibt den Klang (复 フク → 腹 フク).","s":2,"p":[["月","Fleisch","b"],["复","zurückkehren","l"]],"n":"月 ist hier nicht der Mond, sondern die verkürzte Form von 肉 – typisch für Zeichen, die Körperteile bezeichnen.","i":"s"},
"痛":{"t":"laut","x":"疒 (Krankheit, Krankenlager) gibt den Sinnbereich an, 甬 den Klang. Denselben Klangteil hat auch 通 ツウ, das heute genauso gelesen wird wie 痛 ツウ.","s":2,"p":[["疒","Krankheit","b"],["甬","Klangteil","l"]]},
"退":{"t":"kombi","x":"Auf Orakelknochen: ein Speisegefäß (皀) und ein Fuß, der sich davon abwendet – man geht vom Gefäß weg, „sich zurückziehen“. Später kam der Geh-Teil 辶 hinzu, und das Gefäß verkürzte sich zu dem eigentlich unverwandten 艮.","s":1,"p":[["辶","gehen","b"],["艮","Speisegefäß (aus 皀)","b"]],"n":"Die Einzelheiten sind offen: Gedeutet wird es als Aufstehen vom Tisch nach dem Essen oder als Abräumen der Opfergefäße.","i":"bs"},
"迷":{"t":"laut","x":"辶 (gehen) gibt den Sinnbereich an – sich unterwegs verirren –, 米 den Klang (米 ベイ → 迷 メイ).","s":2,"p":[["辶","gehen","b"],["米","Reis","l"]],"i":"s"},
"訪":{"t":"laut","x":"言 (Wort, sprechen) ist der Sinnteil – nachfragen, aufsuchen –, 方 gibt den Klang (方 ホウ → 訪 ホウ).","s":2,"p":[["言","Wort, sprechen","b"],["方","Richtung","l"]]},
"怒":{"t":"laut","x":"心 (Herz, Gefühl) ist der Sinnteil, 奴 gibt den Klang (奴 ド → 怒 ド). Gemeint ist „zornig werden“.","s":2,"p":[["奴","Knecht","l"],["心","Herz","b"]]},
"眠":{"t":"laut","x":"目 (Auge) gibt den Sinnbereich an – die Augen schließen, schlafen –, 民 den Klang (民 ミン → 眠 ミン).","s":2,"p":[["目","Auge","b"],["民","Volk","l"]]},
"靴":{"t":"laut","x":"革 (Leder) zeigt den Sinnbereich – Schuhe aus Leder –, 化 gibt den Klang (化 カ → 靴 カ).","s":2,"p":[["革","Leder","b"],["化","sich verwandeln","l"]]},
"途":{"t":"laut","x":"辶 (gehen) gibt den Sinnbereich „Weg“ an, 余 den Klang. Im Altchinesischen klangen beide ähnlich; heute erkennt man das noch an 塗 ト, das ebenfalls 余 enthält.","s":2,"p":[["辶","gehen","b"],["余","übrig","l"]]},
"給":{"t":"laut","x":"糹 (Faden, Seide) gibt den Sinnbereich an, 合 liefert den Klang. Nach der alten Erklärung bedeutete das Zeichen zuerst „reichlich, genügend“; daraus wurde „geben, versorgen“ und heute auch „Gehalt“.","s":1,"p":[["糹","Faden, Seide","b"],["合","zusammenfügen","l"]],"n":"Die Bedeutung von 合 („zusammenfügen“) hat mit dem Sinn des Zeichens wahrscheinlich nichts zu tun – es steht nur wegen seines Klangs da.","i":"s"},
"冷":{"t":"laut","x":"冫 (Eis) gibt den Sinnbereich an: kalt wie Eis. 令 liefert den Klang: 令 レイ → 冷 レイ.","s":2,"p":[["冫","Eis","b"],["令","Befehl","l"]],"n":"Manchmal wird 令 hier zusätzlich als Sinnträger gedeutet. Dafür gibt es keinen Beleg; es ist nur Klangteil.","i":"s"},
"処":{"t":"laut","x":"Die alte Form 處 verbindet 夂 (Fuß) und 几 (Tischchen, Sitz) als Sinnteil mit 虍 (Tigerkopf) als Klangteil: sich an einem Ort niederlassen. Die heutige Form 処 behält nur den unteren Teil von 處.","s":1,"p":[["虍","Tiger","l"],["夂","Fuß","b"],["几","Tischchen, Sitz","b"]],"a":"處","i":"b"},
"婦":{"t":"laut","x":"Das Wort für „verheiratete Frau“ wurde zuerst einfach mit 帚 (Besen) geschrieben. Später kam 女 (Frau) als Sinnteil dazu, und 帚 blieb als Klangteil.","s":1,"p":[["女","Frau","b"],["帚","Besen","l"]],"n":"Oft liest man „eine Frau mit Besen“ – das geht auf eine alte Erklärung zurück. Heute sieht man 帚 vor allem als Klangteil bzw. als frühere Schreibung desselben Wortes.","i":"obs"},
"程":{"t":"laut","x":"禾 (Getreide) gibt den Sinnbereich an, 呈 den Klang: 呈 テイ → 程 テイ. Ursprünglich ging es ums Messen (von Getreide); daraus wurden „Maß, Ausmaß, Grad“.","s":2,"p":[["禾","Getreide","b"],["呈","darbieten","l"]]},
"精":{"t":"laut","x":"米 (Reis) gibt den Sinnbereich an, 青 den Klang: 青 セイ → 精 セイ. Gemeint war zuerst geschälter, besonders guter Reis; daraus wurden „verfeinert, rein“ und später „Geist, Lebenskraft“.","s":2,"p":[["米","Reis","b"],["青","blau, grün","l"]],"i":"s"},
"絶":{"t":"kombi","x":"Die ältesten Formen zeigen Fäden (糸) und ein Messer (刀): Fäden werden durchgeschnitten. Später kam 卩 als Klangteil dazu (alte Form 絕). Daraus wurden „abschneiden, abbrechen“ und „äußerst“.","s":2,"p":[["糹","Faden","b"],["刀","Messer","b"],["卩","kniender Mensch","l"]],"n":"Oft wird 絶 als 糸 + 色 (Farbe) erklärt. Das stimmt nicht: Der rechte Teil entstand aus 刀 und 卩, die heute nur zufällig wie 色 aussehen.","a":"絕","i":"obs"},
"杯":{"t":"laut","x":"木 (Baum, Holz) gibt den Sinnbereich an, 不 liefert den Klang. Das Zeichen bedeutet „Becher, Schale“ und dient heute auch als Zählwort für gefüllte Tassen und Gläser.","s":2,"p":[["木","Baum, Holz","b"],["不","nicht","l"]]},
"積":{"t":"laut","x":"禾 (Getreide) gibt den Sinnbereich an, 責 den Klang: 責 セキ → 積 セキ. Gemeint war das Aufhäufen und Speichern (von Getreide); daraus wurden „stapeln, anhäufen“.","s":2,"p":[["禾","Getreide","b"],["責","fordern, Schuld","l"]]},
"寄":{"t":"laut","x":"宀 (Dach, Haus) gibt den Sinnbereich an, 奇 den Klang: 奇 キ → 寄 キ. Ursprünglich hieß es, fern von zu Hause bei jemandem unterzukommen. Heute bedeutet es vor allem „sich nähern, vorbeischauen“ und „überlassen, spenden“.","s":2,"p":[["宀","Dach, Haus","b"],["奇","seltsam","l"]]},
"娘":{"t":"laut","x":"女 (Frau) gibt den Sinnbereich an, 良 liefert den Klang: 良 リョウ klingt ähnlich wie 娘 ジョウ.","s":2,"p":[["女","Frau","b"],["良","gut","l"]],"n":"Oft liest man „eine gute (良) Frau (女) = Tochter“. Das ist eine Merkhilfe; 良 steht hier wegen seines Klangs."},
"怖":{"t":"laut","x":"忄 (Herz, Gefühl) gibt den Sinnbereich an, 布 den Klang: 布 フ → 怖 フ. Bedeutung: „sich fürchten“ und „einschüchtern“.","s":2,"p":[["忄","Herz, Gefühl","b"],["布","Tuch","l"]]},
"恐":{"t":"laut","x":"心 (Herz, Gefühl) gibt den Sinnbereich an, der obere Teil 巩 den Klang: 巩 キョウ → 恐 キョウ. Bedeutung: „sich fürchten“.","s":2,"p":[["巩","festhalten","l"],["心","Herz, Gefühl","b"]]},
"婚":{"t":"laut","x":"女 (Frau) gibt den Sinnbereich an, 昏 den Klang: 昏 コン → 婚 コン. Bedeutung: „Mann und Frau werden“, also heiraten.","s":2,"p":[["女","Frau","b"],["昏","Abenddämmerung","l"]]},
"遊":{"t":"laut","x":"辶 (gehen) gibt den Sinnbereich an, 斿 den Klang: 斿 ユウ → 遊 ユウ. Das Zeichen ist eine Nebenform von 游, bei der 氵 (Wasser) durch 辶 ersetzt wurde: umherziehen, sich vergnügen.","s":2,"p":[["辶","gehen","b"],["斿","Fahnenband","l"]],"i":"b"},
"貧":{"t":"laut","x":"貝 (Muschel, früher Zahlungsmittel) gibt den Sinnbereich Geld und Besitz an, 分 den Klang: 分 ブン klingt ähnlich wie 貧 ヒン/ビン. Bedeutung: „arm“.","s":2,"p":[["分","teilen","l"],["貝","Muschel, Geld","b"]],"n":"Oft liest man „das Geld (貝) wird aufgeteilt (分), bis man arm ist“. Das ist nur eine Merkhilfe; 分 steht wegen seines Klangs da.","i":"s"},
"適":{"t":"laut","x":"辶 (gehen) gibt den Sinnbereich an, 啇 den Klang: 啇 テキ → 適 テキ. Zuerst bedeutete das Zeichen „hingehen“; später wurde es für ein gleich klingendes Wort „passen, geeignet sein“ ausgeliehen.","s":2,"p":[["辶","gehen","b"],["啇","aus 啻 „nur“","l"]],"n":"Der Klangteil war ursprünglich 啻 und wurde später zu 啇 umgeformt.","i":"s"},
"押":{"t":"laut","x":"扌 (Hand) gibt den Sinnbereich an, 甲 liefert den Klang. Bedeutung: „drücken, schieben“.","s":2,"p":[["扌","Hand","b"],["甲","Panzer","l"]],"n":"Manchmal wird 甲 hier zusätzlich als Sinnträger gedeutet. Das gilt heute als falsche Analyse; 甲 ist nur Klangteil."},
"更":{"t":"laut","x":"Zuerst schrieb man das Wort mit zwei übereinandergestellten 丙 (nach einer Deutung zwei Wagen). Später kam 攴 (Hand mit Stock: etwas tun) als Sinnteil dazu, ein 丙 fiel weg, der Rest diente als Klangteil. Bedeutung: „ändern, erneuern“ und „noch mehr“.","s":1,"p":[["丙","(zwei) Wagen","l"],["攴","Hand mit Stock","b"]],"n":"Im heutigen 更 sind 丙 und 攴 kaum noch zu erkennen: Beim Übergang zur Kanzleischrift wurden sie verschliffen. Manche Übersichten zeigen als ältestes 更 ein Zeichen für „Peitsche“ – das gehört zu 便, nicht zu 更.","i":"obs"},
"浮":{"t":"laut","x":"氵 (Wasser) gibt den Sinnbereich an, 孚 den Klang: 孚 フ → 浮 フ. Bedeutung: auf dem Wasser treiben, schweben, auftauchen.","s":2,"p":[["氵","Wasser","b"],["孚","ergreifen","l"]]},
"越":{"t":"laut","x":"走 (laufen) gibt den Sinnbereich an, 戉 den Klang: 戉 エツ → 越 エツ. Bedeutung: über etwas hinübergehen, überqueren, übertreffen.","s":2,"p":[["走","laufen","b"],["戉","Streitaxt","l"]]},
"背":{"t":"laut","x":"Das Wort „Rücken“ schrieb man zuerst mit 北. Als 北 für „Norden“ gebraucht wurde, setzte man ⺼ (Fleisch, Körperteil; sieht aus wie 月) darunter, und 北 wurde zum Klangteil. Später auch „sich abwenden“.","s":2,"p":[["北","Norden","l"],["月","Fleisch, Körper","b"]],"i":"s"},
"盗":{"t":"unklar","x":"Die Herkunft ist umstritten. Nach einer neueren Deutung zeigten die alten Formen, wie geschmolzenes Metall in eine Gussform fließt; das Zeichen wurde dann für das ähnlich klingende Wort „stehlen“ ausgeliehen. Die alte Form ist 盜, verkürzt zu 盗.","s":0,"p":[["次","aus 㳄 „Speichel“","f"],["皿","Schale","f"]],"n":"Oft liest man: Jemand sabbert (㳄) beim Anblick einer fremden Schale (皿), begehrt sie und stiehlt. Diese Erklärung ist umstritten: Ein Teil der Forschung meint, die frühen Formen hätten mit 㳄 gar nichts zu tun.","a":"盜","i":"obs"},
"除":{"t":"laut","x":"阝 (Hügel, Erdstufen) gibt den Sinnbereich an, 余 den Klang. Ursprünglich bedeutete das Zeichen „Stufen, Treppe“; später wurde es für ein gleich klingendes Wort „entfernen“ ausgeliehen.","s":2,"p":[["阝","Hügel, Stufen","b"],["余","übrig","l"]],"i":"s"},
"幾":{"t":"leih","x":"Die ältesten Formen zeigen eine Hellebarde (戈), mit der ein Gefangener mit Zopf getötet wird – ein Wort für „töten“. Später wurde das Zeichen für ein ähnlich klingendes Wort „wie viele, einige“ ausgeliehen. Aus dem Zopf wurden die zwei kleinen 幺 oben.","s":0,"p":[["𢆶","aus dem Zopf","f"],["戈","Hellebarde","b"],["人","Mensch","b"]],"n":"Eine andere Erklärung liest 𢆶 (feine Fäden) und 戍 (bewachen): „auf Kleinigkeiten achtgeben“. Sie stützt sich auf spätere Zeichenformen, nicht auf die ältesten Funde.","i":"bs"},
"散":{"t":"laut","x":"Die älteste Form 㪔 zeigt Bäume (林) und eine Hand, die mit einem Stock schlägt: Pflanzen abschlagen, einen Platz roden. Später kam 月 (Fleisch) dazu, und 㪔 gab den Klang an. „Zerstreuen, verstreut“ ist eine spätere Bedeutung.","s":1,"p":[["龷","Bäume (verkürzt)","l"],["攵","schlagen","l"],["月","Fleisch","b"]],"n":"Wie es zu „zerstreuen“ kam, ist nicht geklärt: Eine Deutung denkt an Bambus, der leicht in Stücke zerfällt; eine andere hält das Zeichen für ausgeliehen – zuerst habe es „Rest, Übriggebliebenes“ bedeutet.","i":"obs"},
"似":{"t":"laut","x":"亻 (Mensch) gibt den Sinnbereich an, 以 den Klang. Im Altchinesischen klangen beide Wörter ähnlich; heute passen 以 イ und 似 ジ nicht mehr zusammen.","s":2,"p":[["亻","Mensch","b"],["以","mittels","l"]]},
"富":{"t":"laut","x":"宀 (Dach, Haus) gibt den Sinnbereich an: was man im Haus besitzt, Vermögen. 畐 liefert den Klang – derselbe Klangteil steckt in 福 フク „Glück“.","s":2,"p":[["宀","Dach, Haus","b"],["畐","Gefäß","l"]],"i":"bs"},
"探":{"t":"laut","x":"扌 (Hand) gibt den Sinnbereich an: mit der Hand tasten, suchen. 罙 liefert den Klang; es steckt auch in 深 シン „tief“.","s":2,"p":[["扌","Hand","b"],["罙","tief","l"]]},
"迎":{"t":"laut","x":"辶 (gehen, unterwegs sein) gibt den Sinnbereich an: jemandem entgegengehen, ihn empfangen. 卬 liefert den Klang; es steckt auch in 仰 ギョウ „aufblicken“.","s":2,"p":[["辶","gehen","b"],["卬","aufblicken","l"]],"i":"s"},
"祖":{"t":"laut","x":"Das Wort „Vorfahr“ wurde zuerst einfach mit 且 geschrieben. Zur Verdeutlichung kam 礻 (Altar, Verehrung) dazu: die Ahnen, denen man opfert. 且 gibt den Klang an, wie auch in 組 ソ.","s":2,"p":[["礻","Altar, Gottheit","b"],["且","außerdem","l"]],"i":"obs"},
"雑":{"t":"laut","x":"Alte Form 雜: 衣 (Kleidung) gibt den Sinnbereich an, 集 (sammeln) den Klang. Gemeint ist das Vermischen – vielleicht ursprünglich verschiedene Farben bei gefärbten Stoffen. In 雑 ist 衣 links zu 九 verkürzt, das 木 von 集 steht darunter.","s":2,"p":[["衣","Kleidung","b"],["集","sammeln","l"]],"a":"雜","i":"s"},
"賛":{"t":"laut","x":"貝 (Muschel, früher Zahlungsmittel) gibt den Sinnbereich Geld und Wert an, der obere Teil den Klang. Ältere Bedeutung ist „unterstützen, helfen“ – etwa mit Geld; heute „zustimmen, loben“.","s":1,"p":[["㚘","zwei Männer","l"],["貝","Muschel, Geld","b"]],"n":"In der alten Form 贊 steht oben zweimal 先. Die heutige Form 賛 hat wieder zweimal 夫 – so wie die frühe Schreibung des Zeichens.","a":"贊","i":"s"},
"込":{"t":"kombi","x":"Ein in Japan geschaffenes Zeichen: 辶 (gehen, sich bewegen) und 入 (hinein) ergeben „sich hineinbewegen, hineinstopfen“. Darum hat es keine chinesische On-Lesung.","s":2,"p":[["辶","gehen","b"],["入","hinein","b"]]},
"欲":{"t":"laut","x":"欠 (Mensch mit weit offenem Mund) gibt den Sinnbereich an: Verlangen, haben wollen. 谷 liefert den Klang – wie in 浴 ヨク „baden“.","s":2,"p":[["谷","Tal","l"],["欠","offener Mund","b"]],"n":"Früher deutete man 谷 zusätzlich als Sinnteil (die Bedeutung des Tals trage zum Sinn bei). Das gilt heute als falsche Analyse: 谷 gibt nur den Klang.","i":"s"},
"閉":{"t":"kombi","x":"Ein Tor 門 mit einem Stück Holz darin: 才 ist hier eine Verkürzung von 材 „Bauholz“. Ein Balken, der das Tor versperrt – daraus „schließen, zumachen“.","s":1,"p":[["門","Tor","b"],["才","Holz (aus 材)","b"]],"n":"Eine andere Deutung sieht im inneren Teil nur einen Klangteil und keinen Balken."},
"窓":{"t":"laut","x":"Kurzform von 窻: 穴 (Loch, Öffnung) gibt den Sinnbereich an, 悤 den Klang – 悤 ソウ → 窓 ソウ. Im heutigen 窓 ist 悤 zu 厶 und 心 verkürzt.","s":2,"p":[["穴","Loch, Öffnung","b"],["悤","eilig","l"]],"n":"Oft liest man, im Zeichen stecke ein Bild eines Fensters (囪). Dass es dieses Zeichen wirklich gab, ist zweifelhaft; seine Form passt nicht zu den alten Bronzeinschriften von 悤."},
"否":{"t":"laut","x":"不 („nicht“) gibt den Klang an; im Altchinesischen klangen 不 und 否 fast gleich. 口 wurde dazugesetzt, um das Wort „verneinen, nein“ von 不 zu unterscheiden.","s":1,"p":[["不","nicht","l"],["口","Mund","b"]],"i":"s"},
"暮":{"t":"laut","x":"莫 zeigte ursprünglich die Sonne, die zwischen Gräsern versinkt: Abend. Weil 莫 später anders gebraucht wurde, setzte man zur Unterscheidung unten noch ein 日 dazu. 莫 gibt auch den Klang: 莫 ボ → 暮 ボ.","s":2,"p":[["莫","Sonnenuntergang (urspr.)","l"],["日","Sonne","b"]]},
"誤":{"t":"laut","x":"言 (Wort, sprechen) gibt den Sinnbereich an: sich beim Reden irren, Fehler. 呉 liefert den Klang – 呉 ゴ → 誤 ゴ.","s":2,"p":[["言","Wort, sprechen","b"],["呉","Name (Wu)","l"]]},
"降":{"t":"kombi","x":"Links 阝 (Hügel, Erdhang), rechts 夅 – zwei Füße, die nach unten zeigen. Füße steigen einen Hang hinab: „hinabsteigen“, später auch „aussteigen“ und „fallen“ (Regen, Schnee).","s":1,"p":[["阝","Hügel","b"],["夅","Füße abwärts","b"]],"i":"ob"},
"勤":{"t":"laut","x":"力 (Kraft) gibt den Sinnbereich an: sich anstrengen, fleißig arbeiten. 堇 liefert den Klang – 堇 キン → 勤 キン, ebenso in 謹 キン.","s":2,"p":[["堇","Lehm","l"],["力","Kraft","b"]]},
"刻":{"t":"laut","x":"刂 (Messer) gibt den Sinnbereich an: mit der Klinge ritzen, einschneiden. 亥 liefert den Klang, wie in 核 カク. Die Bedeutung „Zeitpunkt“ kam später dazu.","s":2,"p":[["亥","Schwein (Tierkreis)","l"],["刂","Messer","b"]]},
"遅":{"t":"laut","x":"Alte Form 遲: 辶 (gehen) gibt den Sinnbereich an – langsam gehen, spät dran sein. Der rechte Teil liefert den Klang. In 遅 ist er zu 尸 und 羊 vereinfacht.","s":1,"p":[["辶","gehen","b"],["屖","alter Klangteil","l"]],"n":"Oft liest man, der Klangteil sei 犀 „Nashorn“. Die alten Bronzeinschriften zeigen aber eine andere Form (屖), die mit dem Nashorn nichts zu tun hat.","a":"遲","i":"s"},
"破":{"t":"laut","x":"石 (Stein) gibt den Sinnbereich an: Stein zerspringt, bricht. 皮 liefert den Klang, wie auch in 波 ハ.","s":2,"p":[["石","Stein","b"],["皮","Haut","l"]]},
"互":{"t":"leih","x":"Das Zeichen hat sich als Nebenform aus einem älteren Zeichen abgespalten, wohl aus 巨. Für das Wort „gegenseitig, einander“ wurde es nur wegen des Klangs ausgeliehen.","s":1,"n":"Oft liest man, 互 zeige eine Haspel zum Aufwickeln von Seil. Die heutige Forschung leitet die Form dagegen von 巨 (vielleicht auch 牙) ab."},
"彼":{"t":"laut","x":"彳 (Weg, gehen) gibt den Sinnbereich an, 皮 den Klang: 皮 ヒ → 彼 ヒ. Gebraucht wird es für das Hinweiswort „jener, dort drüben“, im Japanischen auch für „er“.","s":2,"p":[["彳","gehen, Weg","b"],["皮","Haut","l"]]},
"恥":{"t":"laut","x":"心 (Herz, Gefühl) gibt den Sinnbereich an: ein Gefühl, die Scham. 耳 (Ohr) liefert den Klang; heute klingen 耳 ジ und 恥 チ nicht mehr ähnlich.","s":2,"p":[["耳","Ohr","l"],["心","Herz","b"]],"n":"Oft liest man, man werde vor Scham rot bis an die Ohren. Das Ohr steht hier aber nur für den Klang.","i":"s"},
"払":{"t":"laut","x":"Alte Form 拂: 扌 (Hand) gibt den Sinnbereich an – mit der Hand wegwischen, wegfegen. 弗 liefert den Klang: 弗 フツ → 拂 フツ. In 払 ist 弗 zu 厶 verkürzt, genauso wie in 仏 aus 佛.","s":2,"p":[["扌","Hand","b"],["弗","nicht","l"]],"a":"拂"},
"舞":{"t":"laut","x":"Oben steckt 無: Es zeigte ursprünglich einen Menschen, der mit Schmuck in den Händen tanzt. Als 無 für „nicht haben“ gebraucht wurde, setzte man unten 舛 (zwei Füße) dazu, um „tanzen“ zu schreiben. 無 ブ → 舞 ブ.","s":1,"p":[["無","urspr. Tänzer","l"],["舛","zwei Füße","b"]],"i":"obs"},
"頼":{"t":"laut","x":"Alte Form 賴: 貝 „Muschel, Geld“ gibt den Sinnbereich an, 剌 (aus 束 und 刀) den Klang. Gemeint war zuerst „Gewinn, Ertrag“; später lieh man das gleich klingende Zeichen für „sich verlassen auf, bitten“ aus. In der heutigen Form wurden 刀 und 貝 zu 頁 zusammengezogen.","s":2,"p":[["束","Bündel (Teil von 剌)","l"],["頁","aus 刀 + 貝 verkürzt","f"]],"n":"Das 頁 rechts hat nichts mit „Kopf“ zu tun – es ist nur die verkürzte Schreibung von 刀 über 貝.","a":"賴","i":"s"},
"戻":{"t":"laut","x":"Alte Form 戾. Das Wort für „sich widersetzen, verdreht sein“ wurde zuerst mit einem Klangzeichen (𡆥) geschrieben, später kam 犬 „Hund“ dazu. In Japan ließ man beim Hund den Punkt weg, so wurde daraus 大. Die Bedeutung „zurückkehren, zurückgeben“ (もどる) gibt es nur im Japanischen.","s":0,"p":[["戸","Tür (heutige Form)","f"],["大","aus 犬 Hund verkürzt","f"]],"n":"Oft liest man: ein Hund zwängt sich gebückt unter einer Tür (戸) hindurch. Diese und ähnliche Erklärungen gelten heute als unbelegt.","a":"戾","i":"os"},
"抱":{"t":"laut","x":"扌 „Hand“ gibt den Sinnbereich an, 包 den Klang (包 ホウ → 抱 ホウ). Zuerst schrieb man „umarmen“ einfach mit 包; später kam die Hand dazu. Passend dazu bedeutet 包 selbst „einwickeln“ – mit den Händen umschließen.","s":2,"p":[["扌","Hand","b"],["包","einwickeln","l"]],"i":"s"},
"緒":{"t":"laut","x":"糸 „Faden“ gibt den Sinnbereich an, 者 den Klang (者 シャ → 緒 ショ/チョ). Zum Fadenteil passt die Bedeutung „Schnur“.","s":2,"p":[["糸","Faden","b"],["者","Person","l"]]},
"逃":{"t":"laut","x":"辶 „gehen, sich bewegen“ gibt den Sinnbereich an, 兆 den Klang (兆 チョウ → 逃 トウ, früher klangen beide gleich). Ursprünglich schrieb man „fliehen“ nur mit 兆; die Bewegung 辶 kam später dazu.","s":2,"p":[["辶","gehen","b"],["兆","Vorzeichen","l"]],"i":"bs"},
"御":{"t":"laut","x":"In den ältesten Inschriften steht 午 als Klangteil (午 ゴ → 御 ゴ/ギョ) neben 卩, einem knienden Menschen; später kamen 彳 „gehen“ und 止 „Fuß“ dazu. Das Wort bedeutete „lenken, beherrschen“. In Japan wurde 御 zur Höflichkeitsvorsilbe (お・ご).","s":1,"p":[["彳","gehen","b"],["午","Mittag","l"],["卩","kniender Mensch","b"]],"n":"Nach einer anderen Deutung schrieb das Zeichen zuerst ein Wort für „empfangen, entgegengehen“ und wurde erst später für das gleich klingende „lenken, regieren“ ausgeliehen."},
"吹":{"t":"kombi","x":"Das heutige 吹 entstand erst in der Han-Zeit aus 炊 „kochen“: Man ersetzte 火 „Feuer“ durch 口 „Mund“ und schuf so ein eigenes Zeichen für „blasen“. Ältere Zeichen derselben Gestalt standen für ganz andere Wörter.","s":0,"p":[["口","Mund","b"],["欠","offener Mund (aus 炊)","f"]],"n":"Oft liest man: Mund + Mensch mit offenem Mund (欠) = blasen, schon auf Orakelknochen belegt. Neuere Forschung liest diese frühen Zeichen aber als andere Wörter (u. a. Vorform von 足).","i":"obs"},
"到":{"t":"laut","x":"至 „ankommen“ gibt den Sinn an, 刂 (= 刀 „Messer“) den Klang (刀 トウ → 到 トウ). Das Messer hat also nur mit dem Klang zu tun, nicht mit der Bedeutung „erreichen, ankommen“.","s":2,"p":[["至","ankommen","b"],["刂","Messer","l"]],"n":"Manche lesen aus Bronzeinschriften 至 + 人 „Mensch“ heraus; andere halten diese Bronzezeichen für eine Vorform von 致.","i":"bs"},
"髪":{"t":"laut","x":"Alte Form 髮: 髟 „langes, herabhängendes Haar“ gibt den Sinnbereich an, 犮 den Klang (犮 バツ/ハツ → 髪 ハツ). In der heutigen japanischen Form wurde 犮 zu dem ähnlich aussehenden 友 „Freund“ vereinfacht.","s":2,"p":[["髟","langes Haar","b"],["友","aus 犮 verkürzt","l"]],"n":"Das 友 unten hat nichts mit „Freund“ zu tun – es ist nur eine vereinfachte Schreibung von 犮.","a":"髮"},
"疲":{"t":"laut","x":"疒 „Krankheit, Krankenlager“ gibt den Sinnbereich an: sich krank und erschöpft fühlen. 皮 liefert den Klang (皮 ヒ → 疲 ヒ).","s":2,"p":[["疒","Krankheit","b"],["皮","Haut","l"]]},
"歳":{"t":"laut","x":"Alte Form 歲: Zwei Füße (zusammen 步 „Schritt“) stehen für das Voranschreiten der Zeit, dazwischen gibt 戉 „Streitaxt“ den Klang. So entstand das Zeichen für „Jahr“, später auch „Lebensjahr“. Heute ist der untere Fuß zu 小 verkürzt und die Axt sieht aus wie 戌.","s":2,"p":[["止","Fuß (oben)","b"],["戌","aus 戉 Streitaxt","l"],["小","Fuß (unten, verformt)","f"]],"a":"歲","i":"obs"},
"偶":{"t":"laut","x":"亻 „Mensch“ gibt den Sinnbereich an, 禺 den Klang (禺 グウ → 偶 グウ). Gemeint war wohl eine Figur in Menschengestalt, etwa ein Götzenbild.","s":1,"p":[["亻","Mensch","b"],["禺","Affe","l"]]},
"偉":{"t":"laut","x":"亻 „Mensch“ gibt den Sinnbereich an, 韋 den Klang (韋 イ → 偉 イ). Gemeint war ein großer, herausragender Mensch – daher „großartig, bedeutend“.","s":2,"p":[["亻","Mensch","b"],["韋","Leder","l"]],"i":"s"},
"頂":{"t":"laut","x":"頁 „Kopf“ gibt den Sinnbereich an, 丁 den Klang (丁 チョウ → 頂 チョウ). Ursprünglich bedeutete das Zeichen „Kopf, Scheitel“; daraus wurde „Gipfel, oberste Spitze“.","s":2,"p":[["丁","Nagel","l"],["頁","Kopf","b"]],"i":"s"},
"了":{"t":"unklar","x":"Wie dieses Zeichen aufgebaut ist, weiß man nicht sicher. Eine Vermutung sieht darin eine verkürzte Form von 子 (Kind). Für „beenden, fertig“ wurde es vermutlich nur wegen des gleichen Klangs verwendet.","s":0,"n":"Eine alte Erklärung sieht ein Baby ohne Arme oder verschlungene Beine; sie ist nicht belegt.","i":"s"},
"丸":{"t":"leih","x":"Ursprünglich zeigte das Zeichen einen sich duckenden, zusammengerollten Menschen und stand für das Wort „sich bücken“. Später wurde es für ein gleich klingendes Wort ausgeliehen: „rund, Kugel“.","s":2,"n":"Oft liest man, es sei ein umgedrehtes 仄. Die Orakelknochen-Formen zeigen aber keinen Zusammenhang damit.","i":"s"},
"玉":{"t":"bild","x":"Mehrere Jadestücke, die an einer Schnur aufgereiht sind. Der Punkt kam später dazu, damit man das Zeichen von 王 unterscheiden kann.","s":2,"n":"Manche sehen darin ein rituelles Jadeobjekt (Cong).","i":"obs"},
"久":{"t":"leih","x":"Das Zeichen geht auf 又 (rechte Hand) zurück: Eine Form mit zwei Fingern spaltete sich ab. Sie wurde für das gleich klingende Wort „lange Zeit“ ausgeliehen.","s":1,"n":"Eine alte Deutung sieht Menschenbeine, die von hinten festgehalten werden. Sie gilt als nicht verlässlich.","i":"s"},
"戸":{"t":"bild","x":"Ein einzelner Türflügel. Die ältere Form 戶 zeigt ihn deutlicher; die heutige Schreibung 戸 ist eine verkürzte Form davon. Zwei Türflügel ergeben 門.","s":2,"a":"戶","i":"obs"},
"毛":{"t":"bild","x":"Ein Bildzeichen: Haar oder Feder. Nach neuerer Forschung stand es zuerst für ein Gras und wurde dann für das gleich klingende Wort „Haar, Fell“ ausgeliehen.","s":1,"i":"bs"},
"央":{"t":"leih","x":"Wahrscheinlich ein Mensch mit einem Joch um den Hals. Das Zeichen stand zuerst für „Unglück“ und wurde später für das gleich klingende Wort „Mitte“ ausgeliehen.","s":1,"n":"Eine alte Deutung sieht einen Menschen in einem Haus. Sicher ist die Erklärung nicht.","i":"obs"},
"氷":{"t":"kurz","x":"Eine abgewandelte Schreibung von 冰 („Eis“), in dem 冫 (Eis) und 水 (Wasser) stecken. Der Punkt in 氷 ersetzt den Eisstrich.","s":1},
"皮":{"t":"bild","x":"Eine Hand zieht einem Tier das Fell ab. Daraus wurde „Haut, Fell, Leder“. Das Fell ist heute oben links abstrakt geworden.","s":2,"p":[["又","Hand","b"]],"i":"bs"},
"皿":{"t":"bild","x":"Ein breites, offenes Gefäß auf einem runden Fuß. Es ist als Bild einer Schale oder eines Tellers entstanden.","s":2,"i":"obs"},
"竹":{"t":"bild","x":"Zwei Bambusstängel mit herabhängenden Blättern. Die heutige Form ist stark vereinfacht.","s":2,"i":"obs"},
"糸":{"t":"bild","x":"Ein Bündel Seidenfaden. Die ältere Form 絲 zeigt das Bild doppelt; beide Formen bedeuteten von Anfang an dasselbe.","s":2,"a":"絲","i":"obs"},
"虫":{"t":"bild","x":"Ein Tier in einfacher Form, ursprünglich für Tiere allgemein. Die ältere Form 蟲 setzt das Zeichen dreifach; erst später trennte man die Bedeutungen und verwendete 虫 für Insekten und Gewürm.","s":1,"n":"Oft liest man, 虫 sei eine Giftschlange. Die neuere Forschung hält das für eine Fehldeutung.","a":"蟲"},
"村":{"t":"laut","x":"木 gibt den Sinnbereich an, 寸 den Klang (ソン bleibt bis heute). Das Zeichen ist jung und fehlt in sehr alten Wörterbüchern.","s":1,"p":[["木","Baum","b"],["寸","Daumenbreite","l"]],"n":"Der Ursprung ist nicht ganz klar: Eine Theorie führt es auf ein älteres Zeichen für „Dorf“ zurück.","i":"s"},
"貝":{"t":"bild","x":"Eine Kaurischnecke. Sie diente im alten China als Geld, deshalb stecken in vielen Zeichen mit 貝 Wörter für Geld, Wert und Handel.","s":2,"i":"obs"},
"池":{"t":"laut","x":"氵 (Wasser) gibt den Sinnbereich an, 也 den Klang. Gemeint ist ein Teich.","s":2,"p":[["氵","Wasser","b"],["也","auch","l"]]},
"羽":{"t":"bild","x":"Zwei Flügel oder Federn nebeneinander. Daraus „Feder, Flügel“; heute auch Zählwort für Vögel.","s":2,"i":"obs"},
"角":{"t":"bild","x":"Ein Horn eines Tieres. Daraus entstanden auch die Bedeutungen „Ecke, Winkel“.","s":2,"i":"obs"},
"谷":{"t":"bild","x":"Die ältere Form zeigt zwei Berghänge mit einem Tal dazwischen. Der Mund 口 wurde später als Zusatz ohne eigene Bedeutung angefügt.","s":1,"p":[["口","Zusatz","f"]],"i":"obs"},
"麦":{"t":"leih","x":"Die ältere Form 麥 besteht aus 來 (Klangteil) und einem Fuß 夊. Sie stand ursprünglich wohl für „kommen“ und wurde später für „Weizen, Gerste“ ausgeliehen. 麦 ist eine verkürzte Handschriftform.","s":1,"p":[["來","kommen","l"],["夊","Fuß","b"]],"n":"Das heutige 来 („kommen“) war dagegen ursprünglich das Bild einer Weizenpflanze.","a":"麥","i":"obs"},
"林":{"t":"kombi","x":"Zwei Bäume nebeneinander ergeben einen Hain oder Wald. Bei 森 stehen drei Bäume.","s":2,"p":[["木","Baum","b"],["木","Baum","b"]],"i":"obs"},
"州":{"t":"bild","x":"Eine Sandbank oder Insel in einem Fluss: drei Strichgruppen im fließenden Wasser. Daraus wurde „Land, Provinz“.","s":2,"i":"obs"},
"血":{"t":"kombi","x":"Eine Schale 皿 mit einem Zeichen für Blut. In den ältesten Texten geht es um rituell vergossenes Opferblut.","s":1,"p":[["皿","Schale","b"],["丿","Tropfen","f"]],"n":"Die Forschung ist sich nicht einig: Manche sehen in 皿 eher den Klangteil und im Strich nur eine Markierung.","i":"os"},
"星":{"t":"laut","x":"Ursprünglich stand 晶 (mehrere funkelnde Sterne) allein für „Stern“. Später kam 生 als Klangteil dazu (セイ). Das alte 晶 wurde zu 日 verkürzt.","s":2,"p":[["日","Sterne","b"],["生","Leben","l"]],"i":"o"},
"札":{"t":"laut","x":"木 gibt den Sinnbereich an: ein dünnes Holztäfelchen. Daraus wurde ein Zettel oder Schild, auf das man schreibt; später auch „Geldschein“.","s":2,"p":[["木","Holz","b"],["乚","Lautteil","l"]],"i":"s"},
"辺":{"t":"laut","x":"Die ältere Form 邊 hat 辶 (Bewegung) als Sinnteil und 臱 als Klangteil. Gemeint ist „Rand, Seite“. Die heutige Form 辺 ist eine stark verkürzte Schreibung.","s":2,"p":[["辶","gehen","b"],["臱","Lautteil","l"]],"a":"邊","i":"obs"},
"弱":{"t":"laut","x":"弓 (Bogen) steht für den Sinn, im Gegensatz zu 強 („stark“). Der zweite Teil gibt den Klang an (ジャク).","s":1,"p":[["弓","Bogen","b"],["㳮","Lautteil","l"]],"n":"Oft liest man „ein verzierter, schwacher Bogen“. Die neuere Forschung hält das für eine Fehldeutung.","i":"s"},
"黄":{"t":"leih","x":"Die ältere Form 黃 zeigte ursprünglich einen Menschen mit aufgeschwollenem Oberkörper. Sie stand für ein Wort wie „Gebrechlichkeit“ und wurde für das gleich klingende Wort „gelb“ ausgeliehen.","s":1,"n":"Für die Orakelknochen sind zwei Grundformen belegt; die genaue Herkunft ist nicht ganz geklärt.","a":"黃","i":"obs"},
"森":{"t":"kombi","x":"Drei Bäume zeigen: sehr viele Bäume. Daraus wurde „Wald, dicht bewachsen“.","s":2,"p":[["木","Baum","b"],["木","Baum","b"],["木","Baum","b"]],"i":"os"},
"雲":{"t":"laut","x":"Zuerst schrieb man „Wolke“ nur mit 云 (ウン). Später kam 雨 als Sinnteil dazu, weil 云 auch für „sagen“ ausgeliehen wurde.","s":2,"p":[["雨","Regen","b"],["云","Wolke","l"]],"i":"s"},
"県":{"t":"leih","x":"Die ältere Form 縣 zeigte einen Kopf, der mit einem Seil an einem Baum hängt: „aufhängen“. Das Zeichen wurde später für „Verwaltungsbezirk“ ausgeliehen. 県 ist die verkürzte Form.","s":2,"p":[["目","Kopf","b"],["木","Baum","b"],["糸","Seil","b"]],"a":"縣","i":"bs"},
"軽":{"t":"laut","x":"In der älteren Form 輕 steht 車 (Wagen) für den Sinn, denn das Wort bezeichnete ursprünglich einen leichten Wagen. 巠 gibt den Klang an (ケイ). In 軽 wurde dieser Teil verkürzt.","s":2,"p":[["車","Wagen","b"],["巠","Lautteil","l"]],"a":"輕","i":"s"},
"農":{"t":"kombi","x":"In der Frühzeit zeigte das Zeichen Pflanzen und ein Werkzeug zum Jäten, dazu später ein Feld 田. Es stand für Unkraut jäten und Ackerbau. Die Teile wurden im Lauf der Zeit zu 曲 verformt.","s":2,"p":[["林","Pflanzen","b"],["辰","Steinhacke","b"]],"i":"obs"},
"鉄":{"t":"laut","x":"Die ältere Form 鐵 hat 金 (Metall) als Sinnteil und einen komplizierten Klangteil. In 鉄 wurde dieser Teil durch das einfachere 失 ersetzt (テツ).","s":2,"p":[["釒","Metall","b"],["失","verlieren","l"]],"a":"鐵"},
"算":{"t":"laut","x":"竹 (Bambus) gibt den Sinn an: Rechenstäbchen aus Bambus. 具 gibt den Klang an. Gemeint ist „zählen, rechnen“.","s":1,"p":[["竹","Bambus","b"],["具","Gerät","l"]],"n":"Eine andere Deutung liest den mittleren Teil 目 als Rechenstäbchen.","i":"s"},
"線":{"t":"laut","x":"糸 (Faden) steht für den Sinn, 泉 gibt den Klang an (セン). Gemeint ist ein Faden oder eine Linie.","s":2,"p":[["糸","Faden","b"],["泉","Quelle","l"]],"i":"s"},
"仲":{"t":"laut","x":"亻 (Mensch) steht für den Sinn, 中 gibt den Klang an (チュウ). Daraus wurde das Verhältnis zwischen Menschen, auch „vermitteln“.","s":2,"p":[["亻","Mensch","b"],["中","Mitte","l"]],"i":"obs"},
"低":{"t":"laut","x":"亻 (Mensch) steht für den Sinn, 氐 gibt den Klang an (テイ). Gemeint ist „niedrig“, also etwa ein Mensch, der sich klein macht.","s":2,"p":[["亻","Mensch","b"],["氐","Lautteil","l"]]},
"岸":{"t":"laut","x":"屵 (Felsklippe) gibt den Sinn an: der Rand des Landes. 干 steht für den Klang. Oben sieht man heute ein 山.","s":1,"p":[["屵","Felsklippe","b"],["干","trocknen","l"]],"i":"s"},
"波":{"t":"laut","x":"氵 (Wasser) steht für den Sinn, 皮 gibt den Klang an (ヒ → ハ). Gemeint ist die Welle.","s":2,"p":[["氵","Wasser","b"],["皮","Haut","l"]],"i":"s"},
"拾":{"t":"laut","x":"扌 (Hand) steht für den Sinn: mit der Hand aufheben. 合 gibt den Klang an. Gemeint ist „aufheben, auflesen“.","s":2,"p":[["扌","Hand","b"],["合","passen","l"]],"i":"s"},
"秒":{"t":"laut","x":"Ursprünglich bezeichnete das Zeichen die Granne (Spitze) einer Getreideähre: 禾 für den Sinn, 少 für den Klang. Von etwas ganz Feinem kam später die Bedeutung „Sekunde“.","s":2,"p":[["禾","Getreide","b"],["少","wenig","l"]],"n":"Manchmal wird es als Sinnverbindung gedeutet; das ist nicht richtig."},
"競":{"t":"laut","x":"Das Zeichen besteht aus 竟 (Klangteil) doppelt. Zwei Menschen, die gegeneinander antreten: „wetteifern“.","s":1,"p":[["竟","beenden","l"],["竟","beenden","l"]],"n":"Ein älteres Wörterbuch deutet es als zwei Menschen, die streiten.","i":"obs"},
"令":{"t":"kombi","x":"Oben ein umgedrehter Mund, unten ein kniender Mensch: Jemand gibt einen Befehl, ein anderer empfängt ihn. Daraus „Befehl, Anordnung“.","s":2,"p":[["亼","Mund","b"],["卩","Kniender","b"]],"i":"obs"},
"根":{"t":"laut","x":"木 (Baum) steht für den Sinn, 艮 für den Klang (コン). Gemeint ist die Wurzel.","s":2,"p":[["木","Baum","b"],["艮","Lautteil","l"]],"i":"s"},
"倍":{"t":"laut","x":"亻 (Mensch) steht für den Sinn, 咅 für den Klang. Ursprünglich bedeutete das Wort „sich abwenden“; erst später wurde es zu „doppelt, -fach“.","s":2,"p":[["亻","Mensch","b"],["咅","Lautteil","l"]]},
"島":{"t":"laut","x":"山 (Berg) gibt den Sinn an: Land, das aus dem Wasser ragt. 鳥 gibt den Klang an.","s":2,"p":[["山","Berg","b"],["鳥","Vogel","l"]],"n":"Oft liest man „ein Berg, auf dem Vögel rasten“. Die Forschung hält das für eine unbelegte Vermutung.","i":"s"},
"祭":{"t":"kombi","x":"Eine Hand legt ein Stück Fleisch auf einen Altar 示. Ursprünglich genügten Fleisch und Hand; der Altar kam in der Zhou-Zeit dazu. Daraus wurde „Opfer, Fest“.","s":2,"p":[["肉","Fleisch","b"],["又","Hand","b"],["示","Altar","b"]],"i":"obs"},
"章":{"t":"leih","x":"Der Aufbau ist nicht sicher geklärt. Eine Deutung sieht darin die Bearbeitung eines Jadestücks mit einem Meißel. Das Zeichen wurde später für das gleich klingende Wort „Schriftstück, Kapitel“ ausgeliehen.","s":0,"i":"bs"},
"童":{"t":"unklar","x":"Die Bedeutung der oberen Teile ist umstritten. Sicher ist: In der Bronzezeit kam 東 als Klangteil dazu. Das Zeichen wurde für das gleich klingende Wort „Kind“ ausgeliehen.","s":0,"p":[["東","Osten","l"]],"n":"Oft liest man, ein Sklave sei geblendet worden. Neuere Forschung sieht im oberen Teil eher einen Kopfschmuck.","i":"obs"},
"階":{"t":"laut","x":"阝 (Hügel, Erhebung) steht für den Sinn, 皆 für den Klang (カイ). Gemeint sind Stufen, daraus „Stockwerk“.","s":2,"p":[["阝","Hügel","b"],["皆","alle","l"]],"i":"s"},
"植":{"t":"laut","x":"木 (Baum) steht für den Sinn, 直 für den Klang (チョク → ショク). Gemeint ist „pflanzen“.","s":2,"p":[["木","Baum","b"],["直","gerade","l"]]},
"温":{"t":"laut","x":"氵 (Wasser) steht für den Sinn, 昷 für den Klang (オン). Gemeint ist „warm“. Die ältere Form 溫 hat einen etwas anderen Klangteil; 昷 zeigt einen Menschen im Gefäß.","s":2,"p":[["氵","Wasser","b"],["昷","Lautteil","l"]],"a":"溫","i":"os"},
"湯":{"t":"laut","x":"氵 (Wasser) steht für den Sinn, 昜 für den Klang. Gemeint ist heißes Wasser.","s":2,"p":[["氵","Wasser","b"],["昜","Lautteil","l"]]},
"短":{"t":"laut","x":"Der linke Teil ist eine verformte Kurzform von 矩 (Winkelmaß), also ein Maßgerät. 豆 steht für den Klang. Gemeint ist „kurz“.","s":1,"p":[["矢","Pfeil","f"],["豆","Bohne","l"]],"n":"Oft liest man, 矢 (Pfeil) sei der Maßstab. Die frühen Formen zeigen aber, dass 矢 hier nichts mit einem Pfeil zu tun hat."},
"泉":{"t":"bild","x":"Wasser, das aus einer Quelle hervorsprudelt. Daraus „Quelle“.","s":2,"i":"obs"},
"橋":{"t":"laut","x":"木 (Holz) steht für den Sinn: Brücken waren aus Holz. 喬 steht für den Klang (キョウ).","s":2,"p":[["木","Baum","b"],["喬","hoch","l"]],"i":"s"},
"緑":{"t":"laut","x":"糸 (Faden, Seide) steht für den Sinn, 彔 für den Klang (ロク → リョク). Die ältere Form 綠 ist fast gleich; 緑 ist die japanische Schreibung.","s":2,"p":[["糸","Faden","b"],["彔","Lautteil","l"]],"a":"綠","i":"s"},
"練":{"t":"laut","x":"糸 (Seide) steht für den Sinn, 柬 für den Klang. Gemeint ist ursprünglich die Bearbeitung von Seide, später „üben, trainieren“.","s":1,"p":[["糸","Seide","b"],["柬","Lautteil","l"]],"i":"s"},
"億":{"t":"laut","x":"亻 (Mensch) steht für den Sinn, 意 für den Klang. Ursprünglich bedeutete das Wort „sich beruhigen“. Dann wurde es für die Zahl „hundert Millionen“ ausgeliehen.","s":2,"p":[["亻","Mensch","b"],["意","Sinn","l"]],"i":"s"},
"課":{"t":"laut","x":"言 (Sprache) steht für den Sinn, 果 für den Klang (カ). Gemeint ist „abschätzen, bewerten“, daraus „Aufgabe, Lektion“.","s":2,"p":[["言","Sprache","b"],["果","Frucht","l"]]},
"賞":{"t":"laut","x":"貝 (Muschel, früher Geld) steht für den Sinn: eine Belohnung. 尚 steht für den Klang (ショウ). Gemeint ist „Preis, Lohn“.","s":2,"p":[["貝","Muschel/Geld","b"],["尚","noch","l"]],"i":"bs"},
"輪":{"t":"laut","x":"車 (Wagen) steht für den Sinn, 侖 für den Klang (リン). Gemeint ist das Rad.","s":2,"p":[["車","Wagen","b"],["侖","Lautteil","l"]]},
"像":{"t":"laut","x":"亻 (Mensch) steht für den Sinn, 象 für den Klang (ゾウ). Gemeint ist ein Abbild, eine Figur.","s":2,"p":[["亻","Mensch","b"],["象","Elefant","l"]]},
"卒":{"t":"leih","x":"Ursprünglich ein fertig genähtes Kleidungsstück. Das Zeichen wurde zuerst für „beenden“ und dann für das gleich klingende Wort „Soldat“ ausgeliehen.","s":2,"n":"Oft liest man, es sei 衣 mit 十 (einfacher Soldat). Die Forschung findet dafür keine Belege.","i":"obs"},
"協":{"t":"laut","x":"劦 (drei Arme/Kräfte, die zusammen arbeiten) steht für den Sinn, 十 wurde als Klangteil ergänzt. Gemeint ist „zusammenarbeiten“.","s":1,"p":[["劦","zusammenarbeiten","b"],["十","zehn","l"]],"i":"s"},
"周":{"t":"leih","x":"In der Frühzeit ein Gegenstand aus Jade mit eingeritzten Mustern. Später für das gleich klingende Wort „ringsum, herum“ ausgeliehen. Der Mund 口 wurde später als Zusatz hinzugefügt.","s":2,"n":"Oft liest man „Mund + gebrauchen: sorgfältig reden“. Das ist eine spätere Deutung.","i":"obs"},
"囲":{"t":"laut","x":"In der älteren Form 圍 steht 囗 (Umrandung) für den Sinn, 韋 für den Klang (イ) und Bedeutung. Das heutige 囲 ist eine verkürzte Schreibung mit 井 im Inneren.","s":2,"p":[["囗","Umschließung","b"],["韋","umgeben","l"]],"a":"圍","i":"bs"},
"固":{"t":"laut","x":"Zuerst stand 古 (コ) allein für „fest“; später kam 囗 als Umrandung dazu. Gemeint ist „hart, fest“.","s":2,"p":[["囗","Umschließung","b"],["古","alt","l"]],"i":"bs"},
"季":{"t":"unklar","x":"Das Zeichen besteht aus 禾 (Getreide) und 子 (Kind). Wie daraus „Jahreszeit“ wird, ist nicht sicher geklärt.","s":0,"p":[["禾","Getreide","b"],["子","Kind","b"]],"n":"Eine Vermutung: ein Wort für Ähre mit 子 als Klangteil.","i":"obs"},
"希":{"t":"kombi","x":"Ursprünglich zeigte das Zeichen Fäden, die sich nur locker kreuzen – also etwas Dünnes, Spärliches. Später kam 巾 (Tuch) dazu. Die Bedeutung „spärlich, selten“ wurde dann für das gleich klingende Wort „hoffen“ ausgeliehen.","s":2,"p":[["爻","Gekreuztes","b"],["巾","Tuch","b"]]},
"材":{"t":"laut","x":"木 (Baum, Holz) zeigt den Sinnbereich, 才 (サイ) gibt den Klang an: ザイ. Gemeint ist ursprünglich Rundholz und Rohmaterial, daraus „Material, Stoff“.","s":2,"p":[["木","Baum","b"],["才","Begabung","l"]]},
"芸":{"t":"laut","x":"Die alte Form 藝 bestand aus einer Pflanze (艸) und dem Klangteil 埶; das Wort bedeutete ursprünglich „pflanzen“ und wurde später für „Kunst, Fertigkeit“ ausgeliehen. 芸 ist eine Kurzform, bei der der mittlere Teil weggelassen wurde.","s":2,"p":[["艹","Pflanze","b"],["埶","pflanzen","l"]],"n":"Ein anderes, gleich geschriebenes Zeichen (ウン) bezeichnet eine Pflanze aus der Familie der Rautengewächse; es hat mit „Kunst“ nichts zu tun.","a":"藝"},
"技":{"t":"laut","x":"扌 (Hand) steht für das, was man mit den Händen tut; 支 liefert den Klang. Gemeint ist handwerkliches Können, die Kunstfertigkeit eines Handwerkers.","s":2,"p":[["扌","Hand","b"],["支","Zweig, Stütze","l"]],"i":"s"},
"骨":{"t":"laut","x":"Das Bildzeichen 冎 stand ursprünglich selbst für „Knochen“ und gibt auch den Klang an (コツ). Später wurde 肉 (als 月 geschrieben) hinzugefügt, damit man das Zeichen besser vom Ausgangszeichen unterscheiden konnte.","s":2,"p":[["冎","Knochen","l"],["月","Fleisch","b"]],"i":"os"},
"寺":{"t":"laut","x":"Ursprünglich schrieb man damit das Wort „halten, festhalten“: eine Hand (又, später 寸) als Sinnteil und 之 als Klangteil. Später wurde das Zeichen für „Amtsgebäude“ ausgeliehen; für „halten“ entstand 持. Das 土 oben ist aus 之 verformt.","s":2,"p":[["之","gehen","l"],["寸","Hand","b"]],"i":"bs"},
"岩":{"t":"kombi","x":"Berg über Stein: ein Felsen. Ursprünglich schrieb man das Wort mit 巖 (Berg + Klangteil); 岩 entstand in der Han-Zeit als vereinfachte Variante, die Berg und Stein einfach kombiniert.","s":2,"p":[["山","Berg","b"],["石","Stein","b"]],"i":"s"},
"区":{"t":"kombi","x":"Die alte Form 區 zeigt einen abgegrenzten Raum (匸), in dem mehrere Dinge (品) liegen: ein abgetrennter Bereich, ein Bezirk. In der Kurzform 区 ist 品 durch 乂 ersetzt.","s":2,"p":[["匸","Umgrenzung","b"],["品","Dinge","b"]],"n":"Ältere Wörterbücher erklären 匸 als Versteck und 品 als „viele Münder“ oder Ähnliches; diese Deutungen gelten heute als nicht haltbar.","a":"區","i":"os"},
"坂":{"t":"laut","x":"Erde (土) als Sinnteil, 反 (ハン) als Klangteil: ein Hang, eine Böschung. Das Zeichen wurde aus 阪 abgewandelt, indem man den Hügel-Teil 阝 durch 土 ersetzte.","s":2,"p":[["土","Erde","b"],["反","zurück","l"]],"i":"b"},
"勇":{"t":"laut","x":"力 (Kraft) trägt den Sinn, 甬 (ヨウ) den Klang: ユウ. Gemeint ist Tapferkeit, die sich in Kraft zeigt.","s":2,"p":[["力","Kraft","b"],["甬","Klang","l"]],"i":"s"},
"毒":{"t":"leih","x":"Nach einer neueren Deutung zeigt das Zeichen eine Frau mit Federschmuck auf dem Kopf; es schrieb ursprünglich das Wort für „Federzier“. Später wurde es für „Gift“ ausgeliehen, außerdem für „aufrichtig“ (篤).","s":1,"p":[["龶","Federschmuck","f"],["毋","Frau","f"]],"n":"Eine zweite Deutung sieht darin Pflanze (屮) + Klangteil 毐 – also eine „giftige Pflanze“.","i":"s"},
"浅":{"t":"laut","x":"Die alte Form 淺 besteht aus Wasser (氵) und dem Klangteil 戔 (セン): flaches Wasser, dann allgemein „flach, seicht“. In 浅 ist 戔 zu 㦮 verkürzt.","s":2,"p":[["氵","Wasser","b"],["戔","Klang","l"]],"a":"淺"},
"軍":{"t":"laut","x":"Oben steht ein Teil, der den Klang liefert (グン), darunter ein Wagen (車). Gemeint ist ursprünglich „umkreisen, umringen“; daraus wurde das Heer, das sich mit Wagen umgibt.","s":1,"p":[["車","Wagen","b"],["勹","Klang","l"]],"n":"Die klassische Deutung liest 勹 als „umhüllen“ und das Ganze als Sinnverbindung. Das ist möglich, aber nicht sicher.","i":"bs"},
"仏":{"t":"laut","x":"Die alte Form 佛 hat Mensch (亻) und den Klangteil 弗 (フツ). Sie schrieb zunächst ein Wort für „undeutlich, schemenhaft“ und wurde dann für „Buddha“ ausgeliehen, als Nachbildung des Klangs. In 仏 ist 弗 zu 厶 verkürzt.","s":2,"p":[["亻","Mensch","b"],["厶","Kurzform von 弗","f"]],"a":"佛","i":"s"},
"築":{"t":"laut","x":"Holz (木) zeigt das Baumaterial; 筑 (チク) gibt den Klang an. Ursprünglich schrieb 筑 selbst das Wort „bauen“; 木 wurde später hinzugefügt.","s":2,"p":[["木","Holz","b"],["筑","Klang","l"]]},
"門":{"t":"bild","x":"Ein Bild eines Tors mit zwei Flügeln, links und rechts je eine Tür. Die halbe Form (戸) zeigt eine einzelne Tür.","s":2,"i":"obs"},
"荷":{"t":"laut","x":"Pflanze (艹) und der Klangteil 何 (カ): ursprünglich der Lotus. Später wurde das Zeichen für „auf der Schulter tragen“ ausgeliehen, das früher mit 何 geschrieben wurde; daher heute „Last, Gepäck“.","s":2,"p":[["艹","Pflanze","b"],["何","was","l"]],"i":"s"},
"府":{"t":"laut","x":"广 (Gebäude) zeigt den Sinnbereich, 付 (フ) den Klang. Das Wort meinte ursprünglich ein Lagerhaus, ein Gebäude; heute steht es für Amt und Regierungssitz.","s":2,"p":[["广","Gebäude","b"],["付","geben","l"]],"i":"s"},
"浴":{"t":"laut","x":"氵 (Wasser) zeigt, worum es geht: sich mit Wasser übergießen, baden. 谷 liefert den Klang.","s":2,"p":[["氵","Wasser","b"],["谷","Tal","l"]],"n":"Früher las man 谷 auch als Sinnteil („Tal“) mit; diese Analyse als „Sinn + Klang zugleich“ gilt als Fehldeutung.","i":"s"},
"専":{"t":"kombi","x":"Die alte Form 專 zeigt eine Hand, die eine Spindel dreht; das Wort bedeutete ursprünglich „Spindel“. Die heutige Bedeutung hat sich daraus entwickelt. In 専 sind die oberen Striche verkürzt.","s":1,"p":[["叀","Spindel","b"],["寸","Hand","b"]],"n":"Nicht verwandt ist das ähnlich aussehende 尃 (in 博 und 縛).","a":"專","i":"os"},
"細":{"t":"laut","x":"糸 (Faden) zeigt den Sinnbereich, 囟 liefert den Klang (サイ). Gemeint ist „dünn, fein“, wie bei einem Faden.","s":2,"p":[["糹","Faden","b"],["囟","Schädel","l"]],"n":"Das 田 rechts hat nichts mit „Feld“ zu tun: Es ist aus 囟 entstellt. Eine frühere Deutung als „Sinn + Klang“ gilt als falsch.","i":"s"},
"鼻":{"t":"laut","x":"自 war ursprünglich ein Bild der Nase. Weil es später für „selbst“ gebraucht wurde, kam 畀 als Klangteil (ビ) dazu, um das Wort „Nase“ eindeutig zu schreiben.","s":2,"p":[["自","Nase","b"],["畀","geben","l"]],"n":"Manche lesen 畀 als zwei Lungen unter der Nase; auf Orakelknochen zeigt 畀 aber einen Pfeil.","i":"s"},
"兵":{"t":"kombi","x":"Zwei Hände halten ein Beil, also eine Waffe. Gemeint ist zuerst die Waffe, daraus der Soldat.","s":2,"p":[["斤","Beil","b"],["廾","zwei Hände","b"]],"n":"Heute sieht der obere Teil aus wie 丘 (Hügel), ist damit aber nicht verwandt.","i":"obs"},
"塩":{"t":"laut","x":"Die alte Form 鹽 hat 鹵 (Salz) als Sinnteil und 監 (カン) als Klangteil. In 塩 ist das alles stark verkürzt: 臣 wurde zu 土, 鹵 zu 口. Die Kurzform gibt es schon seit dem 6. Jahrhundert.","s":2,"p":[["鹵","Salz","b"],["監","beaufsichtigen","l"]],"a":"鹽","i":"s"},
"栄":{"t":"laut","x":"Die alte Form 榮 hat 木 (Baum) und den Klangteil 熒 (エイ). Sie meinte zuerst eine Baumart (jap. kiri) und wurde dann für „blühen, gedeihen“ ausgeliehen. In 栄 ist der obere Klangteil verkürzt.","s":2,"p":[["木","Baum","b"],["熒","Klang","l"]],"a":"榮","i":"s"},
"干":{"t":"leih","x":"Ein Bild eines Schildes mit gegabelter Spitze oder Federschmuck. Später wurde das Zeichen für das gleich klingende Wort „trocken“ (乾) ausgeliehen.","s":2,"n":"Möglich ist auch, dass 干 eine gegabelte Jagdwaffe zeigt und mit 單 verwandt ist.","i":"obs"},
"底":{"t":"laut","x":"广 (Gebäude) und der Klangteil 氐 (テイ): der Boden, das Fundament eines Gebäudes.","s":2,"p":[["广","Gebäude","b"],["氐","Wurzel","l"]],"n":"Nach einer Deutung zeigt 氐 etwas „Unteres“ (einen Menschen, der sich beugt, oder eine Wurzel) und trägt damit auch Bedeutung bei."},
"署":{"t":"laut","x":"Oben ein Netz (网, hier als 罒) als Sinnteil, unten 者 (シャ) als Klangteil: ショ.","s":1,"p":[["罒","Netz","b"],["者","Person","l"]]},
"恋":{"t":"laut","x":"Die alte Form 戀 hat 心 (Herz) als Sinnteil und 䜌 (レン) als Klangteil: jemanden im Herzen lieben und sich nach ihm sehnen. In 恋 ist der obere Teil stark verkürzt.","s":2,"p":[["心","Herz","b"],["䜌","Klang","l"]],"a":"戀"},
"訓":{"t":"laut","x":"言 (Sprechen) zeigt den Sinnbereich, 川 den Klang: Gemeint ist „belehren“, also mit Worten unterweisen.","s":2,"p":[["訁","Sprechen","b"],["川","Fluss","l"]]},
"祈":{"t":"laut","x":"礻 (Altar) steht für das Religiöse, 斤 (キン) liefert den Klang: キ. Gemeint ist „beten“.","s":2,"p":[["礻","Altar","b"],["斤","Beil","l"]]},
"焼":{"t":"laut","x":"Die alte Form 燒 hat 火 (Feuer) und einen Klangteil 堯, der früher ähnlich klang wie das Wort für „brennen, backen“. In 焼 ist der Klangteil zu 尭 verkürzt; die heutige Lesung ショウ klingt anders.","s":2,"p":[["火","Feuer","b"],["尭","Klang","l"]],"a":"燒","i":"s"},
"胸":{"t":"laut","x":"匈 (キョウ) war ursprünglich schon das Zeichen für „Brust“; später wurde 月 (Fleisch, Körper) dazugesetzt. Es ist der Sinnbereich „Körper“ plus der Klang.","s":2,"p":[["月","Fleisch","b"],["匈","Brust","l"]],"n":"Eine frühere Deutung als „Sinn + Klang zugleich“ gilt als Fehlschluss, weil Wortgeschichte und Zeichengeschichte nicht dasselbe sind.","i":"s"},
"脳":{"t":"kombi","x":"Die alte Form 腦 zeigt Fleisch (月) und dazu den Kopf (囟) mit Haar (巛) darüber: das, was im Kopf liegt. 脳 ist eine verkürzte Schreibweise dieses Aufbaus.","s":0,"p":[["月","Fleisch","b"],["巛","Haar","b"],["囟","Kopf","b"]],"n":"Eine andere Analyse liest den rechten Teil als Klangteil 𡿺, der aus 夒 verkürzt wurde. Die Forschung ist sich hier nicht einig.","a":"腦"},
"枚":{"t":"unklar","x":"Das Zeichen besteht aus 木 (Baum, Holz) und 攵 (Hand mit Stock). Was es ursprünglich bedeutete, ist unbekannt. Später wurde es als Zählwort für flache Dinge ausgeliehen.","s":0,"p":[["木","Baum","b"],["攴","Hand mit Stock","f"]],"n":"Eine Forschungsmeinung hält den rechten Teil für verformtes 文 (Klangteil); andere lesen 木 + Hand mit Stock als Sinnverbindung."},
"禁":{"t":"laut","x":"示 (Altar, Religiöses) ist der Sinnteil, 林 (リン) der Klangteil: キン. Gemeint ist „verbieten, untersagen“.","s":2,"p":[["示","Altar","b"],["林","Wald","l"]]},
"喫":{"t":"laut","x":"口 (Mund) zeigt, dass es um Essen und Trinken geht; 契 (ケイ) gibt den Klang an. Gemeint ist „zu sich nehmen“.","s":1,"p":[["口","Mund","b"],["契","Vertrag","l"]],"i":"s"},
"減":{"t":"laut","x":"氵 (Wasser) als Sinnteil und 咸 (カン) als Klangteil: Das Wasser nimmt ab, wird weniger.","s":2,"p":[["氵","Wasser","b"],["咸","alle","l"]],"n":"Nach einer Deutung trägt 咸 auch Bedeutung: Ein Wasserlauf wird „abgedichtet“, also fließt weniger."},
"順":{"t":"laut","x":"頁 (Kopf, Gesicht) als Sinnteil, 川 (セン) als Klangteil: ジュン. Gemeint ist „sich fügen, gehorchen“, dann „der Reihe nach, Ordnung“.","s":2,"p":[["頁","Kopf","b"],["川","Fluss","l"]],"n":"Oft liest man „dem Fluss folgen“ (川 + Kopf als Sinnverbindung). Die traditionelle Lehre sagt das, die moderne Forschung sieht 川 nur als Klangteil.","i":"obs"},
"布":{"t":"laut","x":"巾 (Tuch) steht für den Stoff, 父 (フ) liefert den Klang. Gemeint ist der Stoff, das Tuch.","s":2,"p":[["父","Vater","l"],["巾","Tuch","b"]],"n":"Der obere Teil sieht heute anders aus als 父; er ist daraus verformt. Ein Bildzeichen ist 布 nicht.","i":"bs"},
"詞":{"t":"laut","x":"言 (Sprechen) zeigt den Sinnbereich, 司 den Klang (シ). Gemeint sind Worte, die Sprache.","s":2,"p":[["訁","Sprechen","b"],["司","leiten","l"]]},
"歴":{"t":"laut","x":"Die alte Form 歷 hat 止 (Fuß, gehen) als Sinnteil und 厤 als Klangteil (レキ): „vorübergehen, durchlaufen“. In 歴 ist der Klangteil verkürzt (Japan).","s":2,"p":[["止","Fuß","b"],["厤","Klang","l"]],"a":"歷","i":"s"},
"冊":{"t":"bild","x":"Ein Bild aneinandergebundener Bambusstreifen, auf denen früher geschrieben wurde: ein Buch, eine Schriftrolle.","s":2,"i":"obs"},
"宇":{"t":"laut","x":"宀 (Dach, Haus) ist der Sinnteil, 于 (ウ) der Klangteil: Gemeint ist die Dachtraufe, der Dachvorsprung.","s":2,"p":[["宀","Dach","b"],["于","Klang","l"]]},
"団":{"t":"laut","x":"Die alte Form 團 hat 囗 (Umrandung) als Sinnteil und 專 als Klangteil (セン→ダン): Gemeint ist etwas Rundes. In 団 ist 專 bis auf 寸 verkürzt; das ist eine japanische Neuschöpfung.","s":2,"p":[["囗","Umrandung","b"],["寸","Hand","f"]],"a":"團"},
"暴":{"t":"leih","x":"Das Zeichen zeigt zwei Hände, die etwas in die Sonne halten, es zum Trocknen auslegen. Ursprünglich schrieb es das Wort „der Sonne aussetzen“ (曝) und wurde später für „wild, gewaltsam“ ausgeliehen.","s":1,"p":[["日","Sonne","b"],["廾","zwei Hände","b"],["米","Getreide","b"]],"n":"Die Erklärung der klassischen Wörterbuch-Tradition (日 + 出 + 廾 + 米) gilt als falsch.","i":"os"},
"混":{"t":"laut","x":"氵 (Wasser) als Sinnteil und 昆 (コン) als Klangteil. Gemeint ist „mischen“, wie wenn Wasser durcheinanderfließt.","s":2,"p":[["氵","Wasser","b"],["昆","viele","l"]],"i":"s"},
"乱":{"t":"leih","x":"Die alte Form 亂 zeigt eine Hand, die einen verwickelten Strang Fäden auseinanderzieht. Das Wort bedeutete ursprünglich „verbinden“ und wurde für „Unordnung“ ausgeliehen. In 乱 ist die linke Seite stark verkürzt.","s":1,"p":[["𤔔","Fäden ordnen","b"],["乚","Zusatzstrich","f"]],"n":"Der Strich 乚 (früher als 乙 gedeutet) ist nur ein späterer Zierstrich ohne eigene Bedeutung.","a":"亂"},
"改":{"t":"laut","x":"Schon auf Orakelknochen steht links ein Klangteil, rechts eine Hand mit Stock (攵). Der Klangteil war ursprünglich 巳, wurde später als 己 geschrieben.","s":2,"p":[["己","Klang","l"],["攵","Hand mit Stock","b"]],"n":"Oft liest man „ein Kind wird mit dem Stock zurechtgewiesen“. Das ist wohl eine nachträgliche Deutung, kein Befund.","i":"s"},
"絡":{"t":"laut","x":"糸 (Faden) als Sinnteil, 各 als Klangteil: Gemeint ist „umwickeln, verflechten“, wie bei einem Gespinst aus Fäden.","s":2,"p":[["糹","Faden","b"],["各","jeder","l"]],"i":"s"},
"比":{"t":"laut","x":"Zwei nebeneinander gestellte 匕, die auch den Klang geben (ヒ). Das Wort meinte ursprünglich „nebeneinander stehen“ und wurde dann für „vergleichen“ ausgeliehen.","s":1,"p":[["匕","Löffel","l"],["匕","Löffel","l"]],"n":"Oft liest man „zwei Menschen nebeneinander“; auf Orakelknochen sind 人 und 匕 aber immer klar verschieden.","i":"obs"},
"被":{"t":"laut","x":"衤 (Kleidung) zeigt den Sinnbereich, 皮 (ヒ) den Klang. Gemeint ist „etwas überziehen, sich bedecken“.","s":2,"p":[["衤","Kleidung","b"],["皮","Haut","l"]]},
"震":{"t":"laut","x":"雨 (Regen, Wetter) als Sinnteil, 辰 (シン) als Klangteil. Das Wort meinte zuerst den Donner; später wurde es auch für „beben, zittern“ verwendet.","s":2,"p":[["雨","Regen","b"],["辰","Klang","l"]],"i":"s"},
"械":{"t":"laut","x":"木 (Holz) zeigt das Material, 戒 (カイ) den Klang. Ursprünglich waren damit Handschellen aus Holz gemeint, später allgemein Geräte und Maschinen.","s":2,"p":[["木","Holz","b"],["戒","warnen","l"]]},
"個":{"t":"laut","x":"亻 (Mensch) als Sinnteil, 固 (コ) als Klangteil. Heute dient das Zeichen als Zählwort für einzelne Dinge.","s":1,"p":[["亻","Mensch","b"],["固","fest","l"]]},
"圧":{"t":"laut","x":"Die alte Form 壓 hat 土 (Erde) und den Klangteil 厭 (エン). Das Wort „drücken“ wurde zuerst mit 厭 allein geschrieben; 土 kam später dazu. In 圧 bleibt nur der Rahmen 厂 von 厭.","s":2,"p":[["土","Erde","b"],["厭","Klang","l"]],"a":"壓"},
"厚":{"t":"laut","x":"Eine Felswand (厂) als Sinnbereich und 𣆪 als Klangteil (コウ): „dick, dicht“.","s":1,"p":[["厂","Felswand","b"],["𣆪","Krug","l"]],"n":"Nach einer anderen Deutung zeigt das Zeichen ein Gefäß für Wein, das an einer Felswand reift.","i":"obs"},
"防":{"t":"laut","x":"阝 (Hügel, Erdwall) als Sinnteil, 方 (ホウ) als Klangteil: ein Deich oder Damm. Daraus „abwehren, schützen“.","s":2,"p":[["阝","Hügel","b"],["方","Richtung","l"]]},
"史":{"t":"kombi","x":"Eine Hand hält ein Gerät, das einen Schreiber oder Beamten kennzeichnet. Das Wort bedeutete „Schreiber“; das Zeichen war ursprünglich dasselbe wie 吏 und 事.","s":1,"p":[["又","Hand","b"]],"n":"Die klassische Deutung „Hand hält die Mitte (中)“ ist falsch. Welches Gerät genau gezeigt wird, ist unklar.","i":"obs"},
"委":{"t":"laut","x":"女 (Frau) als Sinnteil, 禾 als Klangteil: Gemeint ist „sich fügen, nachgeben“. Daraus entwickelten sich Bedeutungen wie „anvertrauen“.","s":2,"p":[["禾","Getreide","l"],["女","Frau","b"]],"n":"Gern liest man „eine Frau, die sich beugt wie eine Ähre“ als Sinnverbindung. Das gilt als falsch.","i":"s"},
"査":{"t":"laut","x":"木 (Holz) und der Klangteil 且 (ショ): Das Zeichen schrieb zuerst das Wort „Floß“. Später wurde es für „untersuchen, prüfen“ ausgeliehen.","s":2,"p":[["木","Holz","b"],["且","Klang","l"]]},
"総":{"t":"laut","x":"Die alte Form 總 hat 糸 (Faden, Seil) und den Klangteil 悤 (ソウ): Gemeint ist „zusammenbinden, bündeln“, daraus „insgesamt“. In 総 ist 悤 durch eine Variante ersetzt.","s":2,"p":[["糹","Faden","b"],["悤","Klang","l"]],"a":"總","i":"s"},
"設":{"t":"laut","x":"言 (Sprechen) als Sinnteil; der rechte Teil geht auf einen alten Klangteil zurück, eine verkürzte Form von 埶, und wird heute als 殳 geschrieben.","s":2,"p":[["言","Sprechen","b"],["殳","Klang","l"]],"n":"Die klassische Erklärung „言 + 殳“ als Sinnverbindung gilt als falsch.","i":"s"},
"省":{"t":"laut","x":"Ursprünglich 眚: ein Auge (目) mit 生 (セイ) als Klangteil. Gemeint ist „prüfend ansehen, inspizieren“. Das 生 oben wurde im Lauf der Zeit zu 少 verformt.","s":2,"p":[["目","Auge","b"],["生","Leben","l"]],"i":"obs"},
"税":{"t":"laut","x":"Die alte Form 稅 hat 禾 (Getreide) als Sinnteil und 兌 als Klangteil. Das Wort bedeutete ursprünglich Abgabe an die Obrigkeit; 税 verwendet die Variante 兑.","s":2,"p":[["禾","Getreide","b"],["兑","Klang","l"]],"n":"Oft liest man „ein Teil der Ernte wird abgezogen“ (兌 als „lösen“). Das gilt als konstruiert; 兌 trägt nur den Klang.","a":"稅"},
"各":{"t":"leih","x":"Ein nach unten gerichteter Fuß (夂) kommt an eine Öffnung (口): „kommen, ankommen“. Später wurde das Zeichen für das gleich klingende Wort „jeder“ ausgeliehen; für „ankommen“ entstand 格.","s":2,"p":[["夂","Fuß","b"],["口","Öffnung","b"]],"n":"Das 口 ist hier kein Mund, sondern eine Öffnung oder Höhle.","i":"obs"},
"勢":{"t":"laut","x":"力 (Kraft) als Sinnteil, 埶 als Klangteil: „Schwung, Kraft, Einfluss“.","s":2,"p":[["埶","pflanzen","l"],["力","Kraft","b"]],"n":"Früher las man 埶 auch als Sinnteil („pflanzen“); das gilt als unbegründete Annahme.","i":"s"},
"営":{"t":"laut","x":"Die alte Form 營 hat 宮 (Haus, Palast) als Sinnteil und 熒 (エイ) als Klangteil. Beide Teile sind stark verkürzt: oben bleibt nur ein Rest von 熒, unten wurde 宮 zu 呂.","s":2,"p":[["宮","Palast","b"],["熒","Klang","l"]],"a":"營"},
"領":{"t":"laut","x":"頁 (Kopf) zeigt den Sinnbereich, 令 (レイ) den Klang: ursprünglich „Nacken, Hals“. Später erweiterte sich die Bedeutung zu „Gebiet, besitzen, anführen“.","s":2,"p":[["頁","Kopf","b"],["令","befehlen","l"]],"i":"s"},
"副":{"t":"laut","x":"刂 (Messer) zeigt „teilen, spalten“, 畐 (フク) gibt den Klang. Das Zeichen bedeutete „aufteilen“ und wurde dann für „zweiter, Hilfs-“ ausgeliehen.","s":2,"p":[["畐","Klang","l"],["刂","Messer","b"]],"i":"s"},
"域":{"t":"laut","x":"土 (Erde) zeigt den Sinnbereich: abgegrenztes Land. 或 liefert den Klang (ワク → イキ). Das Zeichen schreibt das Wort für ein umgrenztes Stück Land, ein „Gebiet“.","s":2,"p":[["土","Erde","b"],["或","Gebiet (alte Form)","l"]],"i":"s"},
"停":{"t":"laut","x":"亻 (Mensch) ist der Sinnteil, 亭 gibt den Klang (テイ → テイ). Das Zeichen schreibt das Wort „anhalten, stehen bleiben“.","s":2,"p":[["亻","Mensch","b"],["亭","Pavillon","l"]],"i":"s"},
"革":{"t":"leih","x":"Ursprünglich das Bild eines ausgebreiteten Tierfells: oben der Kopf, unten Schwanz und Beine. Gemeint war gegerbtes Leder. Später wurde das Zeichen für das gleich klingende Wort „ändern, erneuern“ ausgeliehen (改革).","s":2,"n":"Kurzzeitig wurden in älteren Formen noch zwei Hände (臼) um das Fell gesetzt; sie sind später wieder verschwunden.","i":"obs"},
"律":{"t":"laut","x":"彳 (gehen, Weg) gibt den Sinnbereich, 聿 den Klang. Das Zeichen schreibt das Wort für „Regel, Gesetz, Ordnung“, also das, wonach man sich richtet.","s":2,"p":[["彳","gehen","b"],["聿","Pinsel","l"]]},
"準":{"t":"laut","x":"氵 (Wasser) und ein Klangteil (ジュン): Gemeint war das Wasserlot, also das Prüfen einer Fläche mit Wasser, daraus „Maßstab, Norm, sich richten nach“.","s":1,"p":[["氵","Wasser","b"],["隼","Falke (Form)","l"]],"n":"Der Klangteil ist eigentlich 隹, nicht der Falke 隼. Nur bei diesem Zeichen wurde er in der Kanzleischrift zu 隼 verändert; in verwandten Zeichen blieb er 隹."},
"則":{"t":"kombi","x":"Ursprünglich ein Dreifußkessel (鼎) und ein Messer (刀): Man ritzt etwas in ein Bronzegefäß. Daraus wurde „Vorbild, Regel, Gesetz“. Der Kessel 鼎 wurde später zum unverwandten 貝 verändert.","s":1,"p":[["貝","Kessel (früher 鼎)","b"],["刂","Messer","b"]],"n":"Eine Alternative: Das Bild könne auch auf das Herstellen einer Gussform zurückgehen. Eindeutig gesichert ist nur: Kessel plus Messer.","i":"bs"},
"導":{"t":"laut","x":"道 (Weg, ドウ) gibt den Klang, 寸 (Hand) den Sinn: jemanden an der Hand auf dem Weg führen. Das Zeichen bedeutet „führen, leiten“.","s":1,"p":[["道","Weg","l"],["寸","Hand","b"]],"n":"Nach japanischer Forschung war das Zeichen zuerst nur eine Variante von 道; dort wurde das 止 zu 寸 und später ein 止 wieder eingefügt.","i":"s"},
"乳":{"t":"bild","x":"Das Bild einer knienden Frau, die ein Kind im Arm hält und stillt. Die Frau ähnelt dem Zeichen 母. Daraus „Muttermilch, Brust“.","s":2,"i":"os"},
"城":{"t":"laut","x":"土 (Erde) ist der Sinnteil, denn Stadtmauern wurden früher aus gestampfter Erde gebaut. 成 gibt den Klang (セイ). Das Zeichen schreibt das Wort „Burg, Stadtmauer“.","s":2,"p":[["土","Erde","b"],["成","werden","l"]],"i":"bs"},
"担":{"t":"laut","x":"Die alte Form 擔 hatte 扌 (Hand) für den Sinn „tragen“ und 詹 für den Klang (タン). In der heutigen Kurzform steht dafür das einfachere 旦, das ebenfalls タン klingt.","s":2,"p":[["扌","Hand","b"],["旦","Morgenröte","l"]],"a":"擔"},
"額":{"t":"laut","x":"頁 (Kopf, Gesicht) zeigt, dass es um einen Körperteil am Kopf geht, 客 gibt den Klang (カク → ガク). Das Zeichen schreibt das Wort „Stirn“; später auch „Rahmen, Betrag“.","s":2,"p":[["客","Gast","l"],["頁","Kopf","b"]],"i":"s"},
"輸":{"t":"laut","x":"車 (Wagen) zeigt den Sinnbereich, 俞 gibt den Klang (ユ). Das Zeichen schreibt das Wort „befördern, schicken“, also Transport mit dem Wagen.","s":2,"p":[["車","Wagen","b"],["俞","(Klang)","l"]],"i":"s"},
"燃":{"t":"laut","x":"Ursprünglich schrieb 然 selbst das Wort „brennen“ (Klang ネン). Weil 然 später für abstrakte Bedeutungen ausgeliehen wurde, setzte man 火 (Feuer) dazu, um „brennen“ wieder eindeutig zu machen.","s":2,"p":[["火","Feuer","b"],["然","so, wie es ist","l"]]},
"祝":{"t":"kombi","x":"Ein Altar (示) und ein knieender Mensch mit weit geöffnetem Mund: Er spricht Gebete und Segenswünsche beim Opfer. Daraus „beglückwünschen, feiern“.","s":2,"p":[["礻","Altar","b"],["兄","Mensch mit offenem Mund","b"]],"n":"Das 兄 in diesem Zeichen ist laut japanischer Quelle ein anderer Ursprung als der „ältere Bruder“ 兄: ein Sitzender mit betontem Mund.","i":"obs"},
"届":{"t":"unklar","x":"Das Zeichen gilt als vereinfachte Variante von 屆. Eine gesicherte Erklärung für den Aufbau liegt nicht vor.","s":0},
"肩":{"t":"bild","x":"Der obere Teil, den man heute wie 戸 schreibt, bildet ein Schulterblatt nach, genauer das eines Rindes. Später kam 月 (Fleisch, Körperteil) dazu. So entstand „Schulter“.","s":1,"p":[["戸","Schulterblatt (Form)","b"],["月","Fleisch","b"]],"n":"Mit der „Tür“ 戸 hat das Zeichen nichts zu tun, auch wenn es heute gleich aussieht.","i":"s"},
"腕":{"t":"laut","x":"月 (Fleisch, Körperteil) zeigt den Sinnbereich, 宛 gibt den Klang. Das Zeichen schreibt das Wort „Arm“; übertragen „Können, Fähigkeit“.","s":2,"p":[["月","Fleisch","b"],["宛","(Klang)","l"]]},
"腰":{"t":"laut","x":"月 (Fleisch, Körperteil) zeigt den Sinnbereich, 要 gibt den Klang (ヨウ → ヨウ). Das Zeichen schreibt das Wort „Hüfte, Taille“.","s":2,"p":[["月","Fleisch","b"],["要","wichtig","l"]],"n":"Es ist ein reines Lautzeichen. Der Teil 要 trägt hier keine zusätzliche Bedeutung."},
"触":{"t":"laut","x":"Die alte Form 觸 hatte 角 (Horn) für den Sinn „mit dem Horn stoßen, berühren“ und 蜀 für den Klang (ショク). Bei der Kurzform wurde 蜀 zu 虫 verkürzt.","s":2,"p":[["角","Horn","b"],["虫","Insekt (steht für 蜀)","l"]],"a":"觸","i":"s"},
"層":{"t":"laut","x":"尸 steht für den Sinnbereich „Gebäude“, 曾 gibt den Klang (ソウ). Das Zeichen schrieb das Wort für ein hohes, mehrstöckiges Gebäude; daraus „Stockwerk, Schicht“.","s":1,"p":[["尸","Haus (Form)","b"],["曾","(Klang)","l"]],"i":"s"},
"型":{"t":"laut","x":"土 (Erde) zeigt den Sinn: eine Form aus Erde, in die man etwas gießt. 刑 gibt den Klang (ケイ). Daraus „Gussform, Muster, Typ“.","s":2,"p":[["刑","Strafe","l"],["土","Erde","b"]]},
"庁":{"t":"laut","x":"Die alte Form 廳 hatte 广 (Gebäude) für den Sinn „Amtsgebäude, Behörde“ und 聽 für den Klang (チョウ). Die Kurzform ersetzt den aufwendigen Klangteil durch das einfache 丁.","s":2,"p":[["广","Gebäude","b"],["丁","(Klang)","l"]],"a":"廳","i":"o"},
"管":{"t":"laut","x":"竹 (Bambus) zeigt das Material: ein Rohr, wie eine Bambusflöte oder ein Röhrchen. 官 gibt den Klang (カン). Später wurde das Zeichen auch für „verwalten“ benutzt.","s":2,"p":[["竹","Bambus","b"],["官","Beamter","l"]]},
"象":{"t":"bild","x":"Das Bild eines Elefanten mit langem Rüssel. Oben stehen Kopf und Rüssel, darunter der Körper. Später auch „Gestalt, Erscheinung“.","s":2,"i":"obs"},
"量":{"t":"unklar","x":"Die Herkunft ist ungeklärt. In den ältesten Formen steht ein Viereck mit einem Sack (東) darüber oder darunter; später kam 土 dazu. Zu den Deutungen gibt es mehrere Vorschläge, aber keinen gesicherten.","s":0,"n":"Die alte Erklärung aus 曏 und 重 gilt heute als falsch, denn die frühen Formen haben damit nichts zu tun.","i":"obs"},
"境":{"t":"laut","x":"土 (Erde) zeigt den Sinnbereich Land, 竟 gibt den Klang (キョウ). Das Zeichen schreibt das Wort „Grenze, Grenzgebiet“.","s":2,"p":[["土","Erde","b"],["竟","enden","l"]],"i":"s"},
"武":{"t":"kombi","x":"Eine Waffe (戈) und ein Fuß (止): Menschen ziehen bewaffnet los. Daraus „Krieger, Militär, Kriegskunst“.","s":2,"p":[["戈","Waffe","b"],["止","Fuß","b"]],"n":"Oft liest man „戈 anhalten“ (Gewalt beenden). Das ist eine alte Deutung, die aus einer Anekdote stammt; 止 ist in dem Zeichen der Fuß, nicht „anhalten“.","i":"obs"},
"述":{"t":"laut","x":"辶 (gehen) ist der Sinnteil, 术 (alt: 朮) gibt den Klang (ジュツ). Das Zeichen bedeutet „darlegen, berichten“.","s":2,"p":[["辶","gehen","b"],["术","(Klang)","l"]],"i":"bs"},
"販":{"t":"laut","x":"貝 (Kaurimuschel, früher Geld) zeigt den Sinnbereich Handel, 反 gibt den Klang (ハン). Das Zeichen bedeutet „verkaufen, handeln“.","s":2,"p":[["貝","Muschel/Geld","b"],["反","Gegenteil","l"]],"i":"s"},
"含":{"t":"laut","x":"口 (Mund) zeigt den Sinn „im Mund halten“, 今 gibt den Klang. Heute liest man 含 ガン und 今 コン; die alte Aussprache war ähnlicher. Daraus „enthalten“.","s":2,"p":[["今","jetzt","l"],["口","Mund","b"]],"i":"bs"},
"況":{"t":"laut","x":"氵 (Wasser) und 兄 (Klang: キョウ). Die ursprüngliche Bedeutung ist unbekannt. Das Zeichen wurde für die Wörter „vergleichen, Lage, Zustand“ ausgeliehen.","s":1,"p":[["氵","Wasser","b"],["兄","älterer Bruder","l"]],"i":"os"},
"補":{"t":"laut","x":"衤 (Kleidung) zeigt den Sinn: Stoff ausbessern, flicken. 甫 gibt den Klang (ホ). Daraus „ergänzen, ausgleichen“.","s":2,"p":[["衤","Kleidung","b"],["甫","(Klang)","l"]]},
"効":{"t":"laut","x":"Die alte Form 效 hatte 交 (Klang コウ) und 攵 (schlagen, Handlung), Bedeutung: nachahmen, befolgen. In der heutigen Form steht 力 (Kraft) statt 攵: „Wirkung, Wirksamkeit“.","s":2,"p":[["交","kreuzen","l"],["力","Kraft","b"]],"a":"效"},
"豊":{"t":"laut","x":"Die alte Form 豐 bestand aus einer Trommel (壴) und dem doppelten Klangteil 丰 (ホウ). Das Zeichen gab erst den Trommelklang wieder und wurde dann für „üppig, reich“ ausgeliehen. 豊 ist die Kurzform.","s":0,"p":[["曲","(Form)","f"],["豆","Trommel/Gefäß","b"]],"n":"Oft liest man „eine Schale mit hoch aufgehäuften Speisen“. Das stammt aus älterer Lehre und passt nicht zu den frühen Formen. Ein anderes 豊 las man auch „レイ“ (Ritual).","a":"豐","i":"obs"},
"巻":{"t":"laut","x":"Die alte Form 卷 hatte eine kniende, gebeugte Person (卩) als Sinnteil und einen Klangteil (カン/ケン). Gemeint ist „biegen, aufrollen“. Daraus „Rolle, Schriftrolle, Band“.","s":2,"p":[["龹","(Klang)","l"],["己","kniende Person","b"]],"a":"卷"},
"捜":{"t":"laut","x":"Die alte Form 搜 hatte 扌 (Hand) und 叟 (Klang ソウ). 叟 selbst bedeutete schon „suchen“: eine Hand mit einer Fackel in einem Haus. Die Kurzform verändert die Mitte von 叟.","s":2,"p":[["扌","Hand","b"],["叟","(Klang)","l"]],"a":"搜"},
"替":{"t":"kombi","x":"Zwei Menschen (ursprünglich 立 und 立), die versetzt stehen und die Plätze tauschen. Daraus „wechseln, ersetzen“. Das 曰 unten war zunächst ein bloßer Zusatz 口.","s":1,"p":[["夫夫","zwei Menschen (aus 立立)","b"],["曰","Mund (aus 口)","f"]],"n":"Die alten Erklärungen von Xu Shen, mit 竝 und 白 oder 曰, gelten als falsch.","i":"s"},
"造":{"t":"laut","x":"辶 (gehen) und ein Klangteil, der wie 告 aussieht. Ursprünglich schrieb das Zeichen das Wort „ankommen“; später wurde es für das gleich klingende „herstellen“ ausgeliehen.","s":1,"p":[["辶","gehen","b"],["告","(Klangteil, ähnlich 告)","l"]],"n":"Der Klangteil sieht aus wie 告 (verkünden), ist aber ein anderes Zeichen: 屮 mit 口 als Zusatz. Die alte Erklärung mit 告 gilt als falsch.","i":"s"},
"印":{"t":"leih","x":"Ursprünglich eine Hand, die eine kniende Person herunterdrückt: das Wort „niederdrücken“ (抑). Später wurde das Zeichen für das gleich klingende „Siegel, Stempel“ ausgeliehen.","s":2,"p":[["爪","Hand","b"],["卩","kniende Person","b"]],"i":"obs"},
"復":{"t":"laut","x":"彳 (gehen, Weg) und 复 (Klang フク, auch „wiederholen“). Das Zeichen schreibt das Wort „zurückkehren“, hin und her gehen.","s":2,"p":[["彳","gehen","b"],["复","wiederholen","l"]],"i":"obs"},
"筆":{"t":"laut","x":"Ursprünglich schrieb 聿 selbst das Wort „Pinsel“ (die Hand mit dem Pinsel). Später kam 竹 (Bambus, der Schaft) dazu, um es klarer zu machen. Daraus „Schreibpinsel, Schreiben“.","s":2,"p":[["竹","Bambus","b"],["聿","Pinsel","l"]]},
"貯":{"t":"laut","x":"貝 (Kaurimuschel, früher Geld) zeigt den Sinnbereich Wertsachen, 宁 gibt den Klang (チョ). Das Zeichen schreibt das Wort „aufbewahren, ansparen“.","s":2,"p":[["貝","Muschel/Geld","b"],["宁","(Klang)","l"]]},
"刺":{"t":"laut","x":"Ursprünglich schrieb 朿 (Dorn) selbst das Wort „Dorn, stechen“ (Klang シ). Später kam 刂 (Messer) dazu. Daraus „stechen, Stachel“.","s":2,"p":[["朿","Dorn","l"],["刂","Messer","b"]],"i":"s"},
"郵":{"t":"laut","x":"阝 (Siedlung) zeigt den Ort, der Rest ist ein Klangteil. Das Zeichen schrieb das Wort für eine Relaisstation, an der Boten Botschaften weitergaben. Daraus „Post“.","s":0,"p":[["垂","hängen (aus 𠌶)","l"],["阝","Ort/Stadt","b"]],"n":"Eine andere Lesart sieht 垂 („fern“) und 邑 („Stadt“) als Sinnverbindung. Nach der japanischen Forschung war der Klangteil ursprünglich 𠌶 und wurde erst später zu 垂 verändert.","i":"s"},
"針":{"t":"laut","x":"金 (Metall) zeigt das Material, 十 den Klang. Heute klingen 針 (シン) und 十 (ジュウ) verschieden, früher waren sie ähnlich. Das Zeichen schreibt das Wort „Nadel“.","s":2,"p":[["金","Metall","b"],["十","zehn","l"]]},
"菓":{"t":"laut","x":"艹 (Pflanze) und 果 (Frucht, Klang カ). Das Zeichen bezeichnet Früchte, Baumfrüchte; daraus „Süßigkeit, Gebäck“.","s":2,"p":[["艹","Pflanze","b"],["果","Frucht","l"]]},
"河":{"t":"laut","x":"氵 (Wasser) und 可 (Klang カ). Das Zeichen schrieb das Wort für einen großen Fluss, besonders den Gelben Fluss. Heute allgemein „Fluss“.","s":2,"p":[["氵","Wasser","b"],["可","können","l"]],"i":"obs"},
"汗":{"t":"laut","x":"氵 (Wasser) und 干 (Klang カン). Das Zeichen schreibt das Wort „Schweiß“, die Flüssigkeit auf der Haut.","s":2,"p":[["氵","Wasser","b"],["干","trocken","l"]]},
"再":{"t":"unklar","x":"Die Herkunft ist ungeklärt. Es gibt mehrere Vorschläge: ein Fisch, ein Korb oder ein Gerät zum Flechten von Seilen. Gesichert ist keiner. Das Zeichen bedeutet „wieder, nochmals“.","s":0,"i":"obs"},
"接":{"t":"laut","x":"扌 (Hand) zeigt den Sinn: mit der Hand etwas annehmen oder berühren. 妾 gibt den Klang. Daraus „berühren, anschließen, empfangen“.","s":2,"p":[["扌","Hand","b"],["妾","Nebenfrau","l"]]},
"占":{"t":"kombi","x":"卜 (Orakelriss) und 口 (Mund): Man deutet das Orakel und sagt es voraus. Daraus „wahrsagen, vorhersagen“; später auch „einnehmen, besetzen“.","s":2,"p":[["卜","Orakel","b"],["口","Mund","b"]],"i":"os"},
"胃":{"t":"bild","x":"Ursprünglich ein Magen mit Nahrung darin. Später kam 月 (Fleisch, Körperteil) dazu. Das obere Stück sieht heute aus wie 田, ist aber ein Zeichenrest des Mageninhalts.","s":2,"p":[["田","Magen mit Inhalt","b"],["月","Fleisch","b"]],"n":"Mit dem „Feld“ 田 hat das Zeichen nichts zu tun.","i":"bs"},
"悩":{"t":"laut","x":"Die alte Form 惱 hatte 心 (Herz) für den Sinn „sich quälen“ und 𡿺 als Klangteil. Die Kurzform kürzt diesen Teil. Daraus „sich Sorgen machen, leiden“.","s":2,"p":[["忄","Herz","b"],["㐫","(Klang)","l"]],"n":"Früher las man darin eine Sinnverbindung (mit 凶, „Unglück“). Die Forschung sieht das als Fehler: Der rechte Teil ist nur Klang.","a":"惱"},
"昇":{"t":"laut","x":"日 (Sonne) zeigt den Sinn: Die Sonne steigt auf. 升 gibt den Klang (ショウ). Das Zeichen schreibt das Wort „aufsteigen“.","s":2,"p":[["日","Sonne","b"],["升","Hohlmaß","l"]],"i":"s"},
"濃":{"t":"laut","x":"氵 (Wasser) zeigt den Sinn Flüssigkeit, 農 gibt den Klang (ノウ). Das Zeichen schreibt das Wort „dicht, dick, stark“, bei Flüssigkeiten „dick, konzentriert“.","s":2,"p":[["氵","Wasser","b"],["農","Landwirtschaft","l"]]},
"極":{"t":"laut","x":"木 (Holz) zeigt das Material: Ursprünglich war es der Firstbalken eines Daches. 亟 gibt den Klang (キョク). Später ausgeliehen für „äußerstes Ende, Gipfel, Pol“.","s":2,"p":[["木","Holz","b"],["亟","(Klang)","l"]],"i":"s"},
"逆":{"t":"laut","x":"辶 (gehen) und 屰 (Klang ギャク; zugleich „sich entgegenstellen“). Ursprünglich „entgegengehen, empfangen“, dann „in die Gegenrichtung, verkehrt“.","s":2,"p":[["辶","gehen","b"],["屰","entgegen","l"]],"i":"s"},
"巨":{"t":"leih","x":"Eine Kurzform von 矩 (Winkelmaß): ursprünglich ein Mensch mit einem Zimmermannswinkel in der Hand. Das Zeichen wurde später für das gleich klingende „groß“ ausgeliehen.","s":2,"p":[["工","Winkelmaß","b"]],"n":"Oft liest man, 巨 sei das Bild eines Lineals mit Griff. Das gilt heute als falsch.","i":"bs"},
"庫":{"t":"laut","x":"广 (Gebäude) zeigt den Sinn: ein Lagerhaus. 車 gibt den Klang (früher ähnlich wie コ/ク). Das Zeichen schreibt das Wort „Lager, Speicher“.","s":2,"p":[["广","Gebäude","b"],["車","Wagen","l"]],"n":"Oft liest man „Wagenschuppen“ (Sinnverbindung). Das gilt als falsch, denn das Wort bedeutet nicht „Wagenhalle“.","i":"s"},
"児":{"t":"bild","x":"Die alte Form 兒 zeigt ein Kind. Unten sind die Beine, oben der Kopf. Warum der obere Teil so aussieht, ist unbekannt. Das Zeichen bedeutet „Kind“.","s":1,"p":[["儿","Mensch","b"]],"n":"Oft liest man, oben sei die noch nicht geschlossene Schädelstelle eines Babys. Das passt nicht zu den frühen Formen. Auch „Haarknoten“ ist nicht gesichert.","a":"兒","i":"obs"},
"凍":{"t":"laut","x":"冫 (Eis) zeigt den Sinn, 東 gibt den Klang (トウ). Das Zeichen schreibt das Wort „frieren, gefrieren“.","s":2,"p":[["冫","Eis","b"],["東","Osten","l"]]},
"幼":{"t":"laut","x":"幺 (klein, Klang ヨウ) und 力 (Kraft): ein Kind mit noch wenig Kraft. Das Zeichen schreibt das Wort „klein, jung“.","s":1,"p":[["幺","klein","l"],["力","Kraft","b"]],"n":"Je nach Quelle ist 幺 Klangteil oder Sinnteil. Gesichert ist nur: 幺 ist zumindest Klangteil.","i":"obs"},
"清":{"t":"laut","x":"氵 (Wasser) zeigt den Sinn: klares Wasser. 青 gibt den Klang (セイ). Das Zeichen schreibt das Wort „rein, sauber, klar“.","s":2,"p":[["氵","Wasser","b"],["青","blau/grün","l"]]},
"録":{"t":"laut","x":"Die alte Form 錄 hatte 金 (Metall) für den Sinn und 彔 als Klangteil (ロク). Die Kurzform nimmt statt 彔 das ähnliche 录. Das Zeichen schreibt das Wort „aufschreiben, festhalten“.","s":2,"p":[["釒","Metall","b"],["录","(Klang)","l"]],"a":"錄"},
"券":{"t":"laut","x":"刀 (Messer) zeigt den Sinn: Verträge wurden früher in zwei Hälften geschnitten. 龹 (alt 𢍏) gibt den Klang (ケン). Daraus „Urkunde, Ticket, Gutschein“.","s":1,"p":[["龹","(Klang)","l"],["刀","Messer","b"]],"i":"s"},
"移":{"t":"laut","x":"禾 (Getreide) zeigt den Sinn: Reispflanzen, die sich im Wind biegen. 多 gibt den Klang, der früher ähnlicher war. Später ausgeliehen für „wechseln, verschieben“.","s":2,"p":[["禾","Getreide","b"],["多","viel","l"]],"i":"s"},
"並":{"t":"bild","x":"Die alte Form 竝 zeigt zwei Menschen, die nebeneinander auf dem Boden stehen. Daraus „nebeneinander, Reihe“. Die heutige Form ist eine verkürzte Schreibung aus der Kanzleischrift.","s":2,"a":"竝"},
"乾":{"t":"laut","x":"Aufgebaut aus dem Klangteil 倝 (カン) und weiteren Strichen. Das Zeichen wurde für das gleich klingende Wort „trocken“ ausgeliehen.","s":0,"p":[["龺","(Klangteil 倝)","l"],["乞","(Zusatzstriche)","f"]],"n":"Nach japanischer Forschung sind die Zusatzstriche nur Verzierung. Eine andere Lesart sieht darin 乙 als Sinnteil.","i":"s"},
"欧":{"t":"laut","x":"Die alte Form 歐 hatte 欠 (gähnen, den Mund aufreißen) und 區 als Klangteil. Das Zeichen bedeutete „erbrechen“. Für „Europa“ wurde es nur wegen des Klangs ausgeliehen (欧羅巴).","s":2,"p":[["区","Bezirk","l"],["欠","Mund aufreißen","b"]],"a":"歐","i":"s"},
"臣":{"t":"leih","x":"Ursprünglich das Bild eines Auges, das nach unten blickt. Dann wurde es für das gleich klingende Wort „Diener, Untertan“ ausgeliehen. Die Augenbedeutung steckt noch in 臨 und 監.","s":2,"i":"obs"},
"略":{"t":"laut","x":"Das Feld 田 gibt den Sinnbereich, 各 den Klang. Ursprünglich meinte das Zeichen die Grenze eines Landstücks (um ein Feld herumgehen und es abstecken). Später wurde es für „weglassen, kürzen“ ausgeliehen; daher „Abkürzung, Umriss“.","s":2,"p":[["田","Feld","b"],["各","(Klang)","l"]],"i":"s"},
"航":{"t":"laut","x":"Das Boot 舟 zeigt den Sinnbereich „Schiff, Schifffahrt“, 亢 gibt den Klang: 亢 コウ → 航 コウ.","s":2,"p":[["舟","Boot","b"],["亢","(Klang)","l"]]},
"板":{"t":"laut","x":"Holz 木 steht für das Material, 反 gibt den Klang: 反 ハン → 板 ハン. Gemeint ist ein flaches Holzstück, ein Brett.","s":2,"p":[["木","Baum, Holz","b"],["反","zurückbiegen","l"]]},
"詰":{"t":"laut","x":"言 (Sprache) zeigt den Sinnbereich, 吉 gibt den Klang: 吉 キツ → 詰 キツ. Das Zeichen steht für das genaue Befragen, also jemanden „in die Enge treiben“; daher „gedrängt, voll“.","s":2,"p":[["言","Sprache","b"],["吉","Glück","l"]]},
"照":{"t":"laut","x":"Das Feuer (灬, unten) gibt den Sinnbereich „Licht, Glanz“, 昭 den Klang: 昭 ショウ → 照 ショウ. Gemeint ist „beleuchten, scheinen“.","s":2,"p":[["灬","Feuer","b"],["昭","hell","l"]],"i":"bs"},
"快":{"t":"laut","x":"Das Herz 忄 (Gefühl) zeigt den Sinnbereich, 夬 den Klang: 夬 カイ → 快 カイ. Gemeint ist ein angenehmes Gefühl. Später wurde das Zeichen auch für „schnell“ ausgeliehen.","s":2,"p":[["忄","Herz","b"],["夬","(Klang)","l"]],"n":"Manchmal wird das Zeichen als Sinnverbindung gedeutet; die Forschung hält das für eine falsche Analyse."},
"版":{"t":"laut","x":"片 (ein flaches Holzstück) zeigt den Sinnbereich, 反 den Klang: 反 ハン → 版 ハン. Ursprünglich „Brett“; später besonders das Holz zum Drucken, daher „Druck, Ausgabe“.","s":2,"p":[["片","Holzstück","b"],["反","(Klang)","l"]],"i":"s"},
"預":{"t":"laut","x":"予 gibt den Klang: 予 ヨ → 預 ヨ; 頁 (Kopf) ist der Sinnteil. Das Zeichen schrieb ursprünglich das Wort „im Voraus“. Heute bedeutet es „anvertrauen, in Verwahrung nehmen“.","s":1,"p":[["予","im Voraus","l"],["頁","Kopf","b"]]},
"延":{"t":"kombi","x":"Älteste Form ist 㢟: Weg 彳 und Fuß 止, also eine weite Strecke gehen. Später kam oben ein Strich als Unterscheidungszeichen dazu. Daraus entstand „sich in die Länge ziehen, verlängern“.","s":2,"p":[["彳","Weg","b"],["止","Fuß","b"]],"n":"Im heutigen Zeichen sieht der Wegteil wie 廴 aus; das ist nur eine veränderte Schreibung von 彳 und 止.","i":"bs"},
"翌":{"t":"unklar","x":"Das Zeichen bedeutet „folgend, nächst“ (z. B. 翌日 „der nächste Tag“). Es gilt als Laut-Sinn-Zeichen mit 羽 „Feder“, doch der zweite Teil (立 oder 昱) wird unterschiedlich gedeutet. Eine sichere Erklärung gibt es nicht.","s":0},
"符":{"t":"laut","x":"Bambus (𥫗) zeigt den Sinnbereich, 付 den Klang: 付 フ → 符 フ. Das Zeichen steht für eine Marke oder Anweisung, ein „Zeichen“.","s":2,"p":[["𥫗","Bambus","b"],["付","geben","l"]]},
"編":{"t":"laut","x":"Faden 糸 zeigt den Sinnbereich, 扁 den Klang: 扁 ヘン → 編 ヘン. Gemeint ist „flechten, stricken“; auch das Zusammenbinden von Schriftstücken mit Fäden zu einem Buch, daher „zusammenstellen, herausgeben“.","s":2,"p":[["糸","Faden","b"],["扁","flach","l"]],"i":"os"},
"普":{"t":"laut","x":"Klangteil ist 並. Das 日 ist kein Sinnteil, sondern ein unterscheidender Zusatz (ursprünglich ein 口, in der heutigen Schrift zu 日 geworden). Das Zeichen bedeutet „weit, allgemein“.","s":1,"p":[["並","nebeneinander","l"],["日","(Zusatz)","f"]],"n":"Oft liest man „Sonne + nebeneinander = viele Tage in einer Reihe“; die Forschung hält diese Sinnverbindung für eine falsche Analyse.","i":"s"},
"掃":{"t":"kombi","x":"Eine Hand 扌 mit einem Besen 帚: Das Bild zeigt das Kehren. Daher „fegen, kehren“.","s":2,"p":[["扌","Hand","b"],["帚","Besen","b"]]},
"泥":{"t":"laut","x":"Wasser 氵 zeigt den Sinnbereich, 尼 den Klang: 尼 ニ → 泥 デイ/ニ. Gemeint ist „Schlamm“. Später wurde es auch für „steckenbleiben, haften“ ausgeliehen.","s":2,"p":[["氵","Wasser","b"],["尼","(Klang)","l"]],"i":"s"},
"棒":{"t":"laut","x":"Holz 木 zeigt den Sinnbereich, 奉 den Klang: 奉 ホウ → 棒 ボウ. Gemeint ist ein hölzerner Stock oder Knüppel.","s":2,"p":[["木","Baum, Holz","b"],["奉","darbringen","l"]]},
"孫":{"t":"kombi","x":"Kind 子 plus 系 (Fortsetzung, Faden): Das Kind, das die Reihe der Familie weiterführt, ist das Enkelkind.","s":2,"p":[["子","Kind","b"],["系","Abfolge","b"]],"i":"s"},
"帯":{"t":"bild","x":"Ursprünglich 帶: ein Bild eines geknüpften Gürtels (Webband). Das heutige Zeichen 帯 ist eine verkürzte Schreibung davon. Bedeutung: „Gürtel, Obi“.","s":2,"a":"帶","i":"os"},
"粉":{"t":"laut","x":"Reis 米 zeigt den Sinnbereich, 分 den Klang: 分 フン → 粉 フン. Gemeint ist Mehl oder Pulver, ursprünglich aus Reis gemahlen.","s":2,"p":[["米","Reis","b"],["分","teilen","l"]],"i":"s"},
"菜":{"t":"laut","x":"Pflanze 艹 zeigt den Sinnbereich, 采 den Klang: 采 サイ → 菜 サイ. Gemeint ist essbares Grünzeug, „Gemüse“.","s":2,"p":[["艹","Pflanze","b"],["采","pflücken","l"]],"i":"s"},
"貨":{"t":"laut","x":"Die Kaurimuschel 貝 steht für Wertvolles, Geld; 化 gibt den Klang: 化 カ → 貨 カ. Gemeint sind Güter und Waren.","s":2,"p":[["化","verwandeln","l"],["貝","Muschel, Geld","b"]],"n":"Früher wurde das Zeichen teils als Sinnverbindung gedeutet (Geld, das sich „verwandelt“); das gilt heute als falsch.","i":"s"},
"陸":{"t":"laut","x":"阝 (Hügel) zeigt den Sinnbereich, 坴 den Klang: 坴 リク → 陸 リク. Gemeint ist erhöhtes festes Land, daher „Festland“.","s":2,"p":[["阝","Hügel","b"],["坴","(Klang)","l"]],"i":"obs"},
"均":{"t":"laut","x":"Erde 土 zeigt den Sinnbereich, 匀 den Klang. Gemeint ist „einebnen, ausgleichen“; daraus „gleichmäßig, Durchschnitt“.","s":2,"p":[["土","Erde","b"],["匀","gleichmäßig","l"]]},
"採":{"t":"laut","x":"Hand 扌 plus Klangteil 采: 采 サイ → 採 サイ. Das Wort „pflücken, nehmen“ wurde zunächst mit 采 geschrieben; später setzte man zur Verdeutlichung die Hand dazu.","s":2,"p":[["扌","Hand","b"],["采","pflücken","l"]]},
"永":{"t":"bild","x":"Bild eines langen Flusses mit Nebenarmen. Dasselbe Bild schrieb zunächst auch „Nebenarm“ (派); später trennten sich die Zeichen. Bedeutung heute: „lang, ewig“.","s":1,"n":"Eine andere Deutung sieht darin einen Menschen, der im Wasser schwimmt; 永 wäre dann die Urform von 泳.","i":"obs"},
"液":{"t":"laut","x":"Wasser 氵 zeigt den Sinnbereich, 夜 den Klang. Gemeint ist alles Flüssige wie Wasser: Saft, Flüssigkeit.","s":2,"p":[["氵","Wasser","b"],["夜","Nacht","l"]],"i":"s"},
"績":{"t":"laut","x":"Faden 糸 zeigt den Sinnbereich, 責 den Klang: 責 セキ → 績 セキ. Ursprünglich „Fäden spinnen“. Heute steht es für das Ergebnis solcher Arbeit: Leistung, Verdienst.","s":2,"p":[["糸","Faden","b"],["責","(Klang)","l"]]},
"複":{"t":"laut","x":"Kleidung 衤 zeigt den Sinnbereich, 复 den Klang. Gemeint ist ein gefüttertes Kleidungsstück, also Stoff in mehreren Lagen. Daher „doppelt, mehrfach“.","s":2,"p":[["衤","Kleidung","b"],["复","(Klang)","l"]],"i":"s"},
"党":{"t":"laut","x":"Ältere Form 黨: 黑 „schwarz, dunkel“ als Sinnteil, 尚 als Klangteil; später für „Gruppe, Partei“ ausgeliehen. Die heutige Form 党 war zuvor ein eigenes Zeichen (尚 + 人, für das Volk der Tanguten) und wurde als Kurzform übernommen.","s":2,"p":[["尚","(Klang)","l"],["黑","schwarz","b"]],"a":"黨","i":"s"},
"卵":{"t":"bild","x":"Bildzeichen für das Ei bzw. den Laich (Fischeier).","s":1,"n":"Eine andere Deutung hält das Bild ursprünglich für etwas anderes; „Ei“ wäre dann erst später ausgeliehen worden. Das ist nicht gesichert.","i":"bs"},
"捨":{"t":"laut","x":"Hand 扌 zeigt den Sinnbereich, 舍 den Klang: 舍 シャ → 捨 シャ. Gemeint ist etwas mit der Hand wegwerfen oder aufgeben.","s":2,"p":[["扌","Hand","b"],["舍","Haus","l"]]},
"汚":{"t":"unklar","x":"Eine Nebenform von 汙. Das Zeichen enthält links 氵 (Wasser); der rechte Teil 亐 ist eine Form von 于. Eine genauere Erklärung des Aufbaus liegt nicht vor. Bedeutung: „schmutzig“.","s":0,"p":[["氵","Wasser","b"]]},
"机":{"t":"laut","x":"Holz 木 zeigt das Material, 几 den Klang: 几 キ → 机 キ. Ursprünglich schrieb 几 selbst schon das Wort „Tisch“; Holz wurde später ergänzt.","s":2,"p":[["木","Baum, Holz","b"],["几","Tischchen","l"]]},
"簡":{"t":"laut","x":"Bambus 𥫗 zeigt den Sinnbereich: Beschriftete Bambustäfelchen dienten früher als Schreibmaterial. 間 gibt den Klang: 間 カン → 簡 カン. Daher „Täfelchen“, später „einfach, kurz“.","s":2,"p":[["𥫗","Bambus","b"],["間","(Klang)","l"]],"n":"Oft liest man, 間 meine den Abstand zwischen aufgereihten Täfelchen; das gilt als Notlösung, 間 trägt hier nur den Klang.","i":"s"},
"誌":{"t":"laut","x":"Sprache 言 zeigt den Sinnbereich, 志 den Klang: 志 シ → 誌 シ. Gemeint ist das Aufschreiben, Festhalten; heute z. B. in 雑誌 „Zeitschrift“.","s":2,"p":[["言","Sprache","b"],["志","Wille","l"]]},
"宝":{"t":"laut","x":"Ältere Form 寶: ein Haus 宀, in dem Jade 玉 und Kaurimuscheln 貝 als Schätze liegen; später kam 缶 als Klangteil hinzu. Die Kurzform 宝 lässt 缶 und 貝 weg.","s":2,"p":[["宀","Dach, Haus","b"],["玉","Juwel","b"]],"n":"Oft wird 缶 als weiterer Schatz gedeutet. Dafür gibt es keinen Beleg; die alten Formen sprechen dagegen.","a":"寶","i":"obs"},
"尊":{"t":"kombi","x":"Eine Hand 寸 hält ein Weingefäß 酋 hin: darbringen, aufstellen. Später wurde das Zeichen für „ehren, verehren“ ausgeliehen.","s":1,"p":[["酋","Weingefäß","b"],["寸","Hand","b"]],"n":"Nach der Siegelschrift könnte der untere Teil auch zwei Hände zeigen, statt 寸.","i":"obs"},
"敬":{"t":"unklar","x":"Das Zeichen besteht aus 茍 und 攵 (Hand mit Stock, Handlung). 茍 ist nicht dasselbe wie 苟, seine Herkunft ist ungeklärt. Bedeutung: „ehren, achten“.","s":0,"p":[["茍","(unklar)","l"],["攵","Hand mit Stock","b"]],"n":"Manche deuten den Aufbau als Sinnverbindung; die Forschung hält das für eine falsche Analyse.","i":"bs"},
"灰":{"t":"laut","x":"Feuer 火 zeigt den Sinnbereich, der obere Teil (𠂇, eine Form von 又) gibt den Klang. Bedeutung: „Asche“, also der Rest vom Feuer.","s":1,"p":[["𠂇","Hand","l"],["火","Feuer","b"]],"n":"Oft liest man „Hand über dem Feuer: Glut, die man anfassen kann“; die Forschung sieht 又 heute als Klangteil.","i":"s"},
"砂":{"t":"laut","x":"Stein 石 zeigt den Sinnbereich, 少 den Klang. 砂 ist eine Variante von 沙, das Sand am Flussufer meint; hier wurde 氵 durch 石 ersetzt.","s":2,"p":[["石","Stein","b"],["少","wenig","l"]]},
"著":{"t":"laut","x":"Eigentlich eine Variante von 箸 (Essstäbchen): Bambus 竹 plus Klangteil 者, wobei 竹 zu 艹 verkürzt wurde. Später wurde 著 für „offenbaren, verfassen“ ausgeliehen.","s":1,"p":[["艹","(Bambus)","f"],["者","Person","l"]],"n":"Oft erklärt man 著 als „Pflanze 艹 + 者“. Ältere Schreibungen zeigen, dass 艹 nichts mit Pflanzen zu tun hat."},
"蒸":{"t":"laut","x":"Pflanze 艹 zeigt den Sinnbereich, 烝 den Klang: 烝 ジョウ → 蒸 ジョウ. Bedeutung: „dämpfen, dünsten“.","s":2,"p":[["艹","Pflanze","b"],["烝","(Klang)","l"]],"i":"s"},
"蔵":{"t":"laut","x":"Ältere Form 藏: Pflanze 艹 als Sinnteil, 臧 als Klangteil: 臧 ゾウ → 蔵 ゾウ. Gemeint ist „verbergen, aufbewahren“. Die Kurzform 蔵 verkürzt den Klangteil stark.","s":2,"p":[["艹","Pflanze","b"],["臧","(Klang)","l"]],"a":"藏","i":"s"},
"装":{"t":"laut","x":"Kleidung 衣 zeigt den Sinnbereich, 壯 (heute 壮) den Klang: 壮 ソウ → 装 ソウ. Gemeint ist sich ankleiden, herrichten. In der alten Form 裝 steht noch 壯; in 装 ist es zu 壮 verkürzt.","s":2,"p":[["壮","kräftig","l"],["衣","Kleidung","b"]],"a":"裝"},
"裏":{"t":"laut","x":"Kleidung 衣 zeigt den Sinnbereich, 里 den Klang: 里 リ → 裏 リ. Gemeint ist die Innenseite oder das Futter eines Kleidungsstücks, daher „Rückseite, Innen“.","s":2,"p":[["衣","Kleidung","b"],["里","Dorf","l"]],"n":"Das 衣 ist in zwei Teile geteilt; der Klangteil 里 steckt mitten darin."},
"諸":{"t":"laut","x":"Sprache 言 zeigt den Sinnbereich, 者 den Klang: 者 ショ → 諸 ショ. Bedeutung heute: „die verschiedenen, allerlei“.","s":2,"p":[["言","Sprache","b"],["者","Person","l"]]},
"臓":{"t":"laut","x":"Körperteil ⺼ zeigt den Sinnbereich, 蔵 (alt 藏) den Klang: ゾウ → 臓 ゾウ. Gemeint sind die inneren Organe, die „Eingeweide“. Die Kurzform folgt der Verkürzung von 藏 zu 蔵.","s":2,"p":[["⺼","Fleisch, Körper","b"],["蔵","(Klang)","l"]],"a":"臟"},
"純":{"t":"laut","x":"Faden 糸 zeigt den Sinnbereich, 屯 den Klang. Ursprünglich war es rohe Seide. Später wurde es für „rein, ohne Beimischung“ ausgeliehen.","s":2,"p":[["糸","Faden","b"],["屯","(Klang)","l"]],"i":"bs"},
"紅":{"t":"laut","x":"Faden 糸 zeigt den Sinnbereich, 工 den Klang: 工 コウ → 紅 コウ. Gemeint ist ein gefärbtes Seidengewebe in Rot, daher die Farbe „tiefrot, karmin“.","s":2,"p":[["糸","Faden, Seide","b"],["工","Arbeit","l"]],"i":"s"},
"拝":{"t":"laut","x":"Ältere Form 拜: Hand (手, später 扌) plus Klangteil 𠦪. Gemeint ist die Verbeugung, die Ehrerbietung. In 拝 ist die Hand zu 扌 geworden und der Rest vereinfacht.","s":1,"p":[["扌","Hand","b"],["𠦪","(Klang)","l"]],"n":"Eine zweite Deutung sieht darin eine Hand, die Kräuter als Gabe hält. Bronzeinschriften sprechen aber für ein Laut-Zeichen.","a":"拜","i":"bs"},
"劇":{"t":"laut","x":"豦 gibt den Klang, 刂 (Messer) den Sinnbereich. Die Grundbedeutung ist „heftig, stark“. Heute steht das Zeichen für das Schauspiel, das Theaterstück.","s":2,"p":[["豦","(Klang)","l"],["刂","Messer","b"]],"n":"Oft liest man, 豦 zeige einen Tiger und ein Wildschwein im Kampf; die Forschung hält das für falsch."},
"承":{"t":"kombi","x":"Älteste Form: eine kniende Person 卩 mit beiden Händen 廾, die etwas trägt oder stützt. Später wurde noch 手 (Hand) ergänzt. Bedeutung: „annehmen, empfangen, übernehmen“.","s":1,"p":[["卩","kniende Person","b"],["廾","zwei Hände","b"],["手","Hand","b"]],"n":"Eine andere Auffassung sieht das Zeichen als Laut-Sinn-Zeichen aus 手 und dem Klangteil 氶.","i":"obs"},
"損":{"t":"laut","x":"Hand 扌 zeigt den Sinnbereich, 員 den Klang. Gemeint ist „beschädigen, verlieren“, daher „Verlust, Nachteil“.","s":2,"p":[["扌","Hand","b"],["員","Mitglied","l"]],"n":"Manchmal als Sinnverbindung gedeutet; die Forschung hält das für falsch."},
"枝":{"t":"laut","x":"Holz 木 zeigt den Sinnbereich, 支 den Klang: 支 シ → 枝 シ. Bedeutung: „Ast, Zweig“.","s":2,"p":[["木","Baum, Holz","b"],["支","Zweig","l"]],"n":"Das Wort „Zweig“ wurde früher mit 枳 geschrieben; 枝 kam erst später als Laut-Sinn-Zeichen hinzu.","i":"s"},
"測":{"t":"laut","x":"Wasser 氵 zeigt den Sinnbereich, 則 den Klang: 則 ソク → 測 ソク. Gemeint ist ursprünglich das Ausmessen der Wassertiefe; daraus „messen, ermessen“.","s":2,"p":[["氵","Wasser","b"],["則","Regel","l"]]},
"講":{"t":"laut","x":"Sprache 言 zeigt den Sinnbereich, 冓 den Klang: 冓 コウ → 講 コウ. Gemeint ist das Besprechen, Erörtern; daraus „Vortrag, Vorlesung“.","s":2,"p":[["言","Sprache","b"],["冓","(Klang)","l"]]},
"紹":{"t":"laut","x":"Faden 糸 zeigt den Sinnbereich, 召 den Klang: 召 ショウ → 紹 ショウ. Gemeint ist „verbinden, fortführen“; daraus „vermitteln, vorstellen“.","s":2,"p":[["糸","Faden","b"],["召","rufen","l"]]},
"介":{"t":"unklar","x":"Eine Person 人 mit Strichen links und rechts. In den ältesten Formen sind es je zwei oder vier Punkte. Was sie darstellen, ist nicht geklärt.","s":0,"p":[["人","Mensch","b"]],"n":"Oft deutet man das als Mensch in einer Rüstung. Das gilt als Volksetymologie. Eine andere Lesart sieht die Striche als „dazwischen“.","i":"obs"},
"湖":{"t":"laut","x":"Wasser 氵 zeigt den Sinnbereich, 胡 den Klang: 胡 コ → 湖 コ. Bedeutung: „See“.","s":2,"p":[["氵","Wasser","b"],["胡","(Klang)","l"]],"n":"Früher teils als Sinnverbindung gedeutet; das gilt als falsch.","i":"s"},
"銅":{"t":"laut","x":"Metall 釒 zeigt den Sinnbereich, 同 den Klang: 同 ドウ → 銅 ドウ. Bedeutung: „Kupfer“.","s":2,"p":[["釒","Metall","b"],["同","gleich","l"]],"i":"s"},
"油":{"t":"laut","x":"Wasser 氵 zeigt den Sinnbereich, 由 den Klang: 由 ユ → 油 ユ. Das Zeichen stand zunächst für einen Flussnamen; heute bedeutet es „Öl, Fett“.","s":2,"p":[["氵","Wasser","b"],["由","(Klang)","l"]],"i":"s"},
"旧":{"t":"laut","x":"Ältere Form 舊: 雈 (eine Eulenart) als Sinnteil, 臼 als Klangteil. Das Zeichen stand zuerst für einen Vogel und wurde dann für „alt“ ausgeliehen. 旧 ist stark verkürzt, entweder aus 臼 oder aus einer Kurzschrift von 舊.","s":1,"p":[["雈","Eule","b"],["臼","Mörser","l"]],"a":"舊","i":"obs"},
"姓":{"t":"laut","x":"女 (Frau) zeigt den Sinnbereich, 生 den Klang: 生 セイ → 姓 セイ. Bedeutung: der Name einer Familie oder Sippe.","s":2,"p":[["女","Frau","b"],["生","Leben","l"]]},
"貿":{"t":"laut","x":"Die Kaurimuschel 貝 (Geld, Ware) zeigt den Sinnbereich, 卯 den Klang: 卯 ボウ → 貿 ボウ. Gemeint ist „tauschen, Handel treiben“.","s":2,"p":[["卯","(Klang)","l"],["貝","Muschel, Geld","b"]]},
"将":{"t":"laut","x":"Ältere Form 將: Fleisch 肉 in einer Hand 寸, also etwas darbieten; 爿 gibt den Klang. Daher „darbringen, voranbringen“. Die Kurzform 将 geht auf eine Schreibschrift-Abkürzung zurück.","s":2,"p":[["爿","Tischchen","l"],["肉","Fleisch","b"],["寸","Hand","b"]],"n":"Das ältere Wörterbuch erklärt den Aufbau anders; das gilt als falsche Analyse.","a":"將","i":"s"},
"伸":{"t":"laut","x":"Mensch 亻 zeigt den Sinnbereich, 申 den Klang: 申 シン → 伸 シン. Bedeutung: „sich recken, ausstrecken“.","s":2,"p":[["亻","Mensch","b"],["申","(Klang)","l"]]},
"幅":{"t":"laut","x":"Tuch 巾 zeigt den Sinnbereich, 畐 den Klang: 畐 フク → 幅 フク. Gemeint ist ursprünglich die Breite von Stoff; daraus „Breite, Spanne“.","s":2,"p":[["巾","Tuch","b"],["畐","(Klang)","l"]],"i":"s"},
"甘":{"t":"leih","x":"Ein Mund mit einem Strich darin: etwas im Mund halten (heute 含). Später wurde das Zeichen für „süß“ ausgeliehen.","s":1,"p":[["口","Mund","b"]],"i":"obs"},
"換":{"t":"laut","x":"Hand 扌 zeigt den Sinnbereich, 奐 den Klang: 奐 カン → 換 カン. Bedeutung: „austauschen, wechseln“.","s":2,"p":[["扌","Hand","b"],["奐","(Klang)","l"]],"n":"Früher teils als Sinnverbindung gedeutet; das gilt als falsch."},
"療":{"t":"laut","x":"Das Krankheitszeichen 疒 zeigt den Sinnbereich, 尞 den Klang: 尞 リョウ → 療 リョウ. Bedeutung: „heilen, behandeln“.","s":2,"p":[["疒","Krankheit","b"],["尞","(Klang)","l"]]},
"般":{"t":"leih","x":"Das Zeichen schrieb ursprünglich das Wort für „Becken, Schale“. Die beiden heutigen Teile 舟 und 殳 sind aus einer älteren Form dieses Beckens verformt worden und tragen keinen eigenen Sinn mehr. Später wurde es für ein gleich klingendes Wort „Art, Sorte“ ausgeliehen.","s":1,"p":[["舟","Boot","f"],["殳","Hand mit Stab","f"]],"i":"obs"},
"依":{"t":"laut","x":"Links steht 亻, der Mensch, als Sinnteil: Es geht um das Verhalten eines Menschen, der sich auf etwas stützt. Rechts gibt 衣 den Klang an (イ → 依 イ).","s":2,"p":[["亻","Mensch","b"],["衣","Kleidung","l"]],"n":"Manchmal wird das Zeichen als „ein Mensch in Kleidung“ gedeutet. Das ist eine falsche Analyse: 衣 liefert nur den Klang.","i":"obs"},
"漁":{"t":"laut","x":"氵 (Wasser) zeigt den Sinnbereich: Arbeit am Wasser. 魚 (ギョ) gibt den Klang, passt aber auch inhaltlich, denn gefischt wird ja der Fisch. Daher ギョ → 漁 ギョ.","s":2,"p":[["氵","Wasser","b"],["魚","Fisch","l"]],"n":"Die Lesung リョウ ist keine alte Lesung dieses Zeichens, sondern in Japan von 猟 übernommen worden.","i":"s"},
"募":{"t":"laut","x":"力 (Kraft, Mühe) liefert den Sinn: Man bemüht sich darum, Leute oder Mittel zusammenzubekommen. 莫 gibt den Klang (莫 ボ → 募 ボ).","s":2,"p":[["莫","nicht / Abend","l"],["力","Kraft","b"]],"i":"s"},
"患":{"t":"laut","x":"心 (Herz) zeigt, dass es um ein Leiden oder Sorgen im Inneren geht. 串 gibt den Klang (串 カン → 患 カン).","s":2,"p":[["串","durchbohren","l"],["心","Herz","b"]],"n":"Ein altes chinesisches Wörterbuch las den oberen Teil anders, nämlich als „etwas durchbohrt das Herz“. Heute gilt 串 als Klangteil."},
"湾":{"t":"laut","x":"Die alte Form 灣 war ein Lautzeichen: 氵 (Wasser) für den Sinn, 彎 (ワン, „biegen, krümmen“) für den Klang. Gemeint ist ein großer, gekrümmter Meereseinschnitt. In 湾 wurde 彎 zu 弯 verkürzt.","s":2,"p":[["氵","Wasser","b"],["弯","gebogen","l"]],"a":"灣"},
"爆":{"t":"laut","x":"火 (Feuer) gibt den Sinn: etwas platzt oder birst im Feuer. 暴 gibt den Klang (暴 バク → 爆 バク).","s":2,"p":[["火","Feuer","b"],["暴","Gewalt","l"]],"n":"Der Klangteil 暴 bedeutet „gewaltsam“ und passt deshalb auch inhaltlich gut. Eine echte Sinn-Verbindung ist das aber nicht.","i":"s"},
"跡":{"t":"laut","x":"𧾷 (Fuß) steht für den Sinn: Spuren, die Füße hinterlassen. 亦 liefert den Klang. Das Zeichen ist eine Nebenform von 迹, bei der das Gehen-Zeichen durch „Fuß“ ersetzt wurde.","s":1,"p":[["𧾷","Fuß","b"],["亦","auch","l"]]},
"香":{"t":"kombi","x":"Auf den Orakelknochen steht oben Hirse (黍), unten ein Mund 口: Duft von Getreide, vermutlich als Opfer oder als Rohstoff für Gegorenes. Aus der Hirse wurde später 禾, aus dem unteren Teil das heutige 日.","s":2,"p":[["禾","Hirse","b"],["日","(früher Mund 口)","f"]],"n":"Das untere 日 hat nichts mit der Sonne zu tun, es ist aus 口 (später 甘, „süß“) umgeformt. Die oft gelesene Deutung „Getreide + süß“ passt nicht zu den ältesten Formen.","i":"obs"},
"兆":{"t":"unklar","x":"Wie das Zeichen entstand, ist nicht sicher geklärt. Eine Deutung sieht zwei Menschen, die vor einer Flut davonlaufen. Eine andere sieht zwei Füße, die durch eine Grenzlinie getrennt sind; „Grenze“ wäre dann die ursprüngliche Bedeutung, später für „Vorzeichen“ ausgeliehen.","s":0,"n":"Oft liest man „Risse im Orakelpanzer“. Die Forschung sieht das heute anders: Die Orakelknochen zeigen keine solche Form.","i":"os"},
"齢":{"t":"laut","x":"Die alte Form 齡 hat 齒 (Zahn) als Sinnteil, denn an den Zähnen ließ sich das Alter ablesen. 令 gibt den Klang (令 レイ → 齢 レイ). In 齢 wurde 齒 zu 歯 vereinfacht.","s":2,"p":[["歯","Zahn","b"],["令","Befehl","l"]],"n":"Manchmal liest man, 令 bedeute „gleichmäßig aufgereiht“ und beschreibe die Zahnreihe. Das ist nicht belegt.","a":"齡","i":"s"},
"刊":{"t":"laut","x":"刂 (Messer) steht für das Schneiden, Schnitzen, Einritzen. 干 gibt den Klang (干 カン → 刊 カン). Später meint das Zeichen auch „drucken, veröffentlichen“.","s":2,"p":[["干","trocken / Schild","l"],["刂","Messer","b"]]},
"傾":{"t":"laut","x":"亻 (Mensch) gibt den Sinn: Ein Mensch neigt sich zur Seite. 頃 liefert den Klang (頃 ケイ → 傾 ケイ).","s":2,"p":[["亻","Mensch","b"],["頃","Weile","l"]],"n":"Der rechte Teil ist nicht 化 + 頁, auch wenn er so aussieht: Er ist das eigene Zeichen 頃.","i":"s"},
"奥":{"t":"kombi","x":"Die alte Form 奧 zeigt oben 匊, einen Bauch voll Getreide, also etwas Eingelagertes, und darunter zwei Hände. Gemeint ist: Man verwahrt etwas tief drinnen, daher „das Innere, das Hinterste“. In 奥 steht oben 米 an der Stelle des alten Teils.","s":1,"p":[["匊","Getreide lagern","b"],["廾","zwei Hände","b"]],"n":"Oft liest man „Dach + Reis + Mensch: im dunklen Haus tastet jemand mit gespreizten Händen“. Das ist nicht gesichert.","a":"奧"},
"贈":{"t":"laut","x":"貝 (Muschel, früher Geld) steht für Wertvolles, das man schenkt. 曽 gibt den Klang (曽 ソウ → 贈 ゾウ/ソウ).","s":2,"p":[["貝","Muschelgeld","b"],["曽","(früher 曾) Schicht","l"]],"i":"s"},
"超":{"t":"laut","x":"走 (laufen) gibt den Sinn: Man rennt über etwas hinweg, „überschreiten“. 召 steuert den Klang bei.","s":2,"p":[["走","laufen","b"],["召","rufen","l"]]},
"雇":{"t":"laut","x":"Ursprünglich schrieb das Zeichen das Wort für „Wachtel“: 隹 (Vogel) für den Sinn, 戸 für den Klang (戸 コ → 雇 コ). Später wurde es für ein gleich klingendes Wort ausgeliehen, nämlich „anstellen, mieten“.","s":2,"p":[["戸","Tür","l"],["隹","Vogel","b"]],"i":"s"},
"片":{"t":"bild","x":"Eine Seite eines Ganzen. Ein Deutungsansatz sieht in 片 einen halbierten Baumstamm, also ein abgespaltenes Stück Holz. Eine andere Sicht: Es ist die Spiegelung von 爿, dem Bild eines Bettes oder Gestells.","s":0,"n":"Die klassische Deutung „halbes 木 zum Zerschneiden“ lässt sich an alten Schriftformen nicht belegen.","i":"s"},
"群":{"t":"laut","x":"羊 (Schaf) gibt den Sinn: eine Herde, die zusammenhält. 君 gibt den Klang (君 クン → 群 グン).","s":2,"p":[["君","Herrscher","l"],["羊","Schaf","b"]],"n":"Früher wurde manchmal erklärt, ein „Herr“ führe die Schafe. Das gilt als unbelegte Vermutung; 君 liefert nur den Klang."},
"埋":{"t":"laut","x":"土 (Erde) zeigt, dass man etwas mit Erde zudeckt. 里 war der Klangteil. Älter schrieb man das Wort mit Gras oben (薶), erst später setzte sich die Form mit 土 durch.","s":2,"p":[["土","Erde","b"],["里","Dorf","l"]]},
"駐":{"t":"laut","x":"馬 (Pferd) gibt den Sinn: Ein Pferd hält an und bleibt stehen. 主 gibt den Klang (主 シュ → 駐 チュウ). Dasselbe 主 steckt in 住.","s":2,"p":[["馬","Pferd","b"],["主","Herr","l"]]},
"柱":{"t":"laut","x":"木 (Holz) zeigt das Material: ein Pfosten aus Holz. 主 gibt den Klang (主 シュ → 柱 チュウ).","s":2,"p":[["木","Holz","b"],["主","Herr","l"]]},
"鋭":{"t":"laut","x":"金 (Metall) steht für Klinge und Spitze: etwas ist scharf und spitz. 兑 (alte Schreibung 兌) gibt den Klang. Die alte Form 銳 sieht fast gleich aus, nur die Schreibung des rechten Teils ist leicht anders.","s":2,"p":[["金","Metall","b"],["兑","tauschen","l"]]},
"殿":{"t":"laut","x":"殳 (Hand mit Schlaggerät) ist der Sinnteil, 𡱂 liefert den Klang. Das Wort meinte ursprünglich die Nachhut, die hinten das Heer sichert. Daraus entwickelten sich später „Palast, Halle“ als Bedeutungen.","s":1,"p":[["𡱂","Gesäß","l"],["殳","Schlagen","b"]],"i":"s"},
"薄":{"t":"laut","x":"艹 (Gras) gibt den Sinn: Es geht um Dünnes, Zartes wie Pflanzen. 溥 gibt den Klang (ハク).","s":2,"p":[["艹","Gras","b"],["溥","weit","l"]],"i":"s"},
"伺":{"t":"laut","x":"亻 (Mensch) gibt den Sinn: Ein Mensch steht dienend neben jemandem. 司 liefert den Klang (司 シ → 伺 シ).","s":2,"p":[["亻","Mensch","b"],["司","verwalten","l"]]},
"炭":{"t":"laut","x":"火 (Feuer) gibt den Sinn: Es geht um etwas, das im Feuer entsteht und brennt. Der Klangteil war 屵; er ist im heutigen Zeichen zu einer 山-ähnlichen Form geworden.","s":2,"p":[["山","(aus 屵 verformt)","l"],["火","Feuer","b"]]},
"包":{"t":"leih","x":"Das Zeichen zeigte ursprünglich einen Menschen, der ein Kind im Arm hält; das ist das Wort für „umarmen“ (抱). Später wurde es für ein gleich klingendes Wort ausgeliehen: „einwickeln, einhüllen“.","s":1,"p":[["勹","umfassen","b"],["己","Kind","b"]],"n":"Oft liest man „ein Embryo im Mutterleib“. Das passt nicht zu den alten Schriftformen.","i":"s"},
"衣":{"t":"bild","x":"Das Zeichen zeigt die Umrisse eines Oberteils, dessen Kragen vor der Brust zusammengelegt ist: ein Kleidungsstück.","s":2,"n":"Als Bauteil wird 衣 oft in zwei Teile zerlegt, zwischen die ein anderes Zeichen gesetzt wird.","i":"obs"},
"鉱":{"t":"laut","x":"Die alte Form 鑛 hatte 金 (Metall) für den Sinn und 廣 für den Klang (コウ). In Japan wurde 廣 zu 広 verkürzt, spätestens Ende des 19. Jahrhunderts, nach dem Vorbild von gleich klingenden Zeichen wie 弘 und 宏.","s":2,"p":[["金","Metall","b"],["広","weit","l"]],"a":"鑛"},
"双":{"t":"kurz","x":"Das Zeichen ist eine Kurzform von 雙 („Paar“). Es besteht aus zweimal 又 (Hand). Diese Schreibung gibt es in China schon seit der Ming-Zeit und wurde in Japan übernommen.","s":1,"p":[["又","Hand","f"],["又","Hand","f"]],"a":"雙","i":"s"},
"床":{"t":"kombi","x":"Ein Gebilde aus Holz in einem Haus: ein Bett oder Gestell. Ursprünglich eine Nebenform von 牀, in dem links das Bild eines Bettes (爿) stand.","s":1,"p":[["广","Haus","b"],["木","Holz","b"]],"a":"牀","i":"os"},
"掘":{"t":"laut","x":"扌 (Hand) gibt den Sinn: Man gräbt mit den Händen. 屈 gibt den Klang (屈 クツ → 掘 クツ).","s":2,"p":[["扌","Hand","b"],["屈","krümmen","l"]],"i":"s"},
"泊":{"t":"laut","x":"氵 (Wasser) steht für den Ort: ein Schiff legt am Wasser an und bleibt dort liegen. 白 gibt den Klang (白 ハク → 泊 ハク). Daraus wurde „übernachten“.","s":2,"p":[["氵","Wasser","b"],["白","weiß","l"]]},
"荒":{"t":"laut","x":"艹 (Gras) zeigt Land, auf dem Pflanzen wild wuchern, ohne Pflege. 巟 liefert den Klang (コウ).","s":2,"p":[["艹","Gras","b"],["巟","verwildern","l"]],"i":"s"},
"袋":{"t":"laut","x":"衣 (Stoff) zeigt das Material: ein Beutel aus Stoff. 代 liefert den Klang (代 ダイ → 袋 タイ).","s":2,"p":[["代","ersetzen","l"],["衣","Kleidung","b"]]},
"珍":{"t":"laut","x":"玉 (Edelstein) steht für etwas Kostbares. 㐱 liefert den Klang. Ursprünglich war ein prächtiger Edelstein gemeint, später auch „selten“.","s":2,"p":[["玉","Edelstein","b"],["㐱","dicht","l"]]},
"籍":{"t":"laut","x":"𥫗 (Bambus) steht für beschriebene Bambusstreifen, also Bücher und Verzeichnisse. 耤 gibt den Klang (耤 セキ → 籍 セキ). Gemeint sind Register, in die Personen eingetragen werden.","s":2,"p":[["𥫗","Bambus","b"],["耤","Feld bestellen","l"]],"i":"s"},
"刷":{"t":"laut","x":"刂 (Messer) deutet auf kratzende, schabende Bewegung hin. 㕞 liefert den Klang (サツ). Das Wort bedeutete ursprünglich „abschaben, säubern“.","s":2,"p":[["㕞","reinigen","l"],["刂","Messer","b"]],"i":"s"},
"封":{"t":"kombi","x":"Ursprünglich zeigte das Zeichen eine Pflanze, die in aufgeschüttete Erde gesetzt wird. Später kam eine Hand (寸) dazu: Man häuft Erde an und bepflanzt sie. Daraus entwickelten sich Bedeutungen wie „abgrenzen, versiegeln“.","s":1,"p":[["圭","Setzling auf Erdhügel","f"],["寸","Hand","b"]],"n":"Das linke 圭 sieht aus wie das eigenständige Zeichen 圭, hat aber einen anderen Ursprung.","i":"obs"},
"筒":{"t":"laut","x":"𥫗 (Bambus) gibt den Sinn: ein hohles Rohr wie ein Bambushalm. 同 gibt den Klang (同 ドウ → 筒 トウ). Anfangs stand 同 allein für das Wort „Röhre“, später wurde der Bambus ergänzt.","s":2,"p":[["𥫗","Bambus","b"],["同","gleich","l"]]},
"柔":{"t":"bild","x":"Die ältere Form zeigt einen Baum mit biegsamen, weichen Zweigen. Der obere Teil wurde später dem Zeichen 矛 angeglichen, so entstand die heutige Form. Das Zeichen steht für „weich, nachgiebig“.","s":2,"p":[["矛","(früher Zweige)","f"],["木","Baum","b"]],"n":"Ein altes Wörterbuch las das Zeichen als 矛 + 木. Die älteren Schriftformen zeigen aber, dass 矛 nichts damit zu tun hat.","i":"bs"},
"沈":{"t":"laut","x":"氵 (Wasser) zeigt, dass es um Untergehen im Wasser geht. 冘 gibt den Klang (チン/ジン).","s":2,"p":[["氵","Wasser","b"],["冘","zögern","l"]],"n":"Auf Orakelknochen steht statt 冘 ein Schaf (羊): Ein Opfertier wurde im Fluss versenkt. Später ersetzte man das Tier durch den Klangteil.","i":"obs"},
"辛":{"t":"leih","x":"Ursprünglich zeigte das Zeichen frisch gewachsene Triebe an einem Baum; es ist die Urform von 新 („neu“). Später wurde es für ein gleich klingendes Wort ausgeliehen, zum Beispiel für ein Zeichen der Himmelsstämme.","s":2,"n":"Oft liest man, es sei ein Werkzeug zum Tätowieren oder Bestrafen. Das beruht auf einer Verwechslung mit einem anderen Zeichen, 䇂.","i":"obs"},
"匹":{"t":"unklar","x":"Die Herkunft ist nicht geklärt. Es gibt mehrere Vermutungen, etwa Falten eines Stoffes, einen Lautteil mit Stein oder die Hälfte von zwei Pferden. Keine davon ist anerkannt.","s":0,"n":"Die alte Deutung „八 + 匸, ein Stoffmaß“ gilt als unwahrscheinlich, da die älteren Formen diese Teile nicht zeigen.","i":"bs"},
"叫":{"t":"laut","x":"口 (Mund) zeigt, dass es um Stimme geht. 丩 gibt den Klang (丩 キュウ → 叫 キョウ). Das Wort heißt „schreien, rufen“.","s":2,"p":[["口","Mund","b"],["丩","verflechten","l"]],"i":"s"},
"涙":{"t":"laut","x":"Die alte Form 淚 hat 氵 (Wasser) für den Sinn und 戾 für den Klang (レイ). In 涙 ist 戾 zu 戻 verkürzt. Früher stand 泣 für „Tränen“, erst später wurde 淚 geschaffen.","s":2,"p":[["氵","Wasser","b"],["戻","zurück","l"]],"a":"淚"},
"缶":{"t":"laut","x":"Die alte Form 罐 bestand aus 缶 (Tongefäß) und 雚 für den Klang (カン). In Japan benutzte man sie in der Meiji-Zeit für Konservendosen („can“), später ließ man den Klangteil weg. Das Zeichen 缶 allein zeigt ursprünglich einen Tonkrug mit Deckel.","s":2,"p":[["缶","Tongefäß","b"],["雚","Klang カン","l"]],"a":"罐"},
"粒":{"t":"laut","x":"米 (Reis) gibt den Sinn: ein einzelnes Korn. 立 gibt den Klang (立 リツ → 粒 リュウ).","s":2,"p":[["米","Reis","b"],["立","stehen","l"]],"i":"s"},
"塔":{"t":"laut","x":"土 (Erde) deutet auf einen aufgeschichteten Bau. 荅 gibt den Klang (トウ).","s":2,"p":[["土","Erde","b"],["荅","antworten","l"]]},
"肌":{"t":"laut","x":"⺼ (Fleisch, Körper) zeigt, dass es um den Körper geht, genauer um die Haut. 几 liefert den Klang (几 キ → 肌 キ).","s":2,"p":[["⺼","Fleisch","b"],["几","Tischchen","l"]]},
"舟":{"t":"bild","x":"Ein Bild eines hölzernen Bootes. In Bauteilen wird 舟 manchmal als 月, 肉 oder 凡 geschrieben.","s":2,"i":"obs"},
"曇":{"t":"kombi","x":"Sonne (日) über oder hinter Wolken (雲): Der Himmel ist bedeckt, die Sonne scheint nicht durch. Gemeint sind dicke, tief hängende Wolken.","s":2,"p":[["日","Sonne","b"],["雲","Wolke","b"]]},
"磨":{"t":"laut","x":"石 (Stein) steht für den Schleifstein. 麻 gibt den Klang (麻 マ → 磨 マ). Zuerst schrieb 麻 allein das Wort; der Stein wurde später ergänzt. Dann wurde das Zeichen für „schleifen, polieren“ ausgeliehen.","s":1,"p":[["麻","Hanf","l"],["石","Stein","b"]]},
"湿":{"t":"laut","x":"Die alte Form 濕 hat 氵 (Wasser) für den Sinn, rechts den Klangteil 㬎. In 湿 ist dieser Teil stark verkürzt zu 显. Beide Formen bedeuten „feucht, nass“.","s":1,"p":[["氵","Wasser","b"],["㬎","(verformt zu 显)","l"]],"a":"濕"},
"硬":{"t":"laut","x":"石 (Stein) gibt den Sinn: hart wie Stein. 更 gibt den Klang (更 コウ → 硬 コウ).","s":2,"p":[["石","Stein","b"],["更","ändern","l"]]},
"鈍":{"t":"laut","x":"金 (Metall) zeigt: Es geht um eine Klinge, die nicht schneidet, sie ist stumpf. 屯 gibt den Klang (屯 トン → 鈍 ドン).","s":2,"p":[["金","Metall","b"],["屯","sammeln","l"]],"i":"s"},
"涼":{"t":"laut","x":"氵 (Wasser) gibt den Sinn: kühl wie Wasser. 京 gibt den Klang (京 キョウ → 涼 リョウ). Ursprünglich schrieb das Zeichen das Wort für „kalt“.","s":2,"p":[["氵","Wasser","b"],["京","Hauptstadt","l"]],"i":"s"},
"零":{"t":"laut","x":"雨 (Regen) gibt den Sinn: Es geht um Tropfen, die herabfallen. 令 liefert den Klang (令 レイ → 零 レイ).","s":2,"p":[["雨","Regen","b"],["令","Befehl","l"]],"i":"s"},
"綿":{"t":"kombi","x":"Ein Faden (糸) und Seidenstoff (帛). Ursprünglich schrieb man das Wort mit 緜, wo der Fadenteil rechts neben dem Stoff stand; später rückte er nach links und wurde zu 糸 vereinfacht, so entstand 綿.","s":1,"p":[["糹","Faden","b"],["帛","Seidenstoff","b"]],"i":"s"},
"帽":{"t":"laut","x":"巾 (Tuch) gibt den Sinn: etwas aus Stoff, das man trägt. 冒 (ボウ) gibt den Klang und die Grundbedeutung „bedecken“. Zuerst schrieb 冒 (bzw. 冃) allein das Wort „Mütze“, 巾 wurde später ergänzt.","s":2,"p":[["巾","Tuch","b"],["冒","bedecken","l"]]},
"憎":{"t":"laut","x":"忄 (Herz) zeigt, dass es um ein Gefühl geht. 曽 (früher 曾) gibt den Klang (ソウ → ゾウ).","s":2,"p":[["忄","Herz","b"],["曽","Schicht","l"]],"i":"s"},
"滴":{"t":"laut","x":"氵 (Wasser) gibt den Sinn: ein Tropfen Wasser. 啇 gibt den Klang (テキ).","s":2,"p":[["氵","Wasser","b"],["啇","Wurzel","l"]],"i":"s"},
"畳":{"t":"unklar","x":"Die alte Form 疊 hatte oben 畾, drei Felder (田), als Bild für „aufeinander gestapelt“, darunter 宜. Daraus wurde das heutige 畳 mit nur einem 田. Das Wort steht für „stapeln, falten“.","s":0,"p":[["田","Feld","f"],["冝","(früher 宜)","f"]],"n":"Früher stand oben 晶 (drei Sonnen). Ein altes Wörterbuch berichtet, ein Kaiser habe das geändert, weil drei Sonnen dem Herrscher zu mächtig wirkten.","a":"疊","i":"b"},
"畜":{"t":"unklar","x":"Die Herkunft ist umstritten. Eine Deutung sieht einen Futtersack, der an einer Schnur hängt: Vieh, das gefüttert wird. Eine andere sieht Tiere, die in einem Pferch festgebunden werden. Beides bedeutet „Vieh halten“.","s":0,"p":[["玄","Schnur","f"],["田","Feld","f"]],"n":"Eine weitere Sicht hält das Zeichen für ein Lautzeichen: oben ein Teil mit Klang, unten die Urform von „Magen“ als Sinnteil.","i":"obs"},
"溶":{"t":"laut","x":"氵 (Wasser) gibt den Sinn. 容 gibt den Klang (容 ヨウ → 溶 ヨウ). Das Zeichen schrieb zuerst ein Wort für das Fließen des Wassers. Später wurde es für „schmelzen, auflösen“ verwendet.","s":2,"p":[["氵","Wasser","b"],["容","fassen","l"]]},
"踊":{"t":"laut","x":"𧾷 (Fuß) gibt den Sinn: Bewegung mit den Füßen, springen. 甬 gibt den Klang (甬 ヨウ → 踊 ヨウ).","s":2,"p":[["𧾷","Fuß","b"],["甬","Röhre","l"]]},
"賢":{"t":"laut","x":"貝 (Muschel, früher Geld) steht für Wert: ein wertvoller, tüchtiger Mensch. 臤 gibt den Klang (臤 ケン → 賢 ケン).","s":2,"p":[["臤","fest, tüchtig","l"],["貝","Muschelgeld","b"]],"i":"s"},
"灯":{"t":"laut","x":"火 (Feuer) für den Sinn, 丁 für den Klang. Die alte Form 燈 hatte 登 als Klangteil; in 灯 steht dafür das einfachere 丁. Gemeint ist eine Lampe oder ein Licht.","s":2,"p":[["火","Feuer","b"],["丁","Block","l"]],"a":"燈"},
"咲":{"t":"laut","x":"Ursprünglich eine Nebenform von 笑 („lachen“): 口 (Mund) für den Sinn, 关 für den Klang. In Japan wird das Zeichen für „aufblühen“ benutzt, also in anderer Bedeutung als im Chinesischen.","s":1,"p":[["口","Mund","b"],["关","lachen","l"]]},
"塗":{"t":"laut","x":"土 (Erde) gibt den Sinnbereich: Schlamm, Erde, die man aufträgt. 涂 liefert den Klang (ト). Daraus wurde „streichen, anstreichen“.","s":2,"p":[["涂","Schlamm","l"],["土","Erde","b"]]},
"召":{"t":"laut","x":"Ein Mund (口), der jemanden herbeiruft; 刀 liefert den Klang. Das Zeichen steht für „herbeirufen, vorladen“.","s":2,"p":[["口","Mund","b"],["刀","Messer","l"]],"n":"Auf manchen Orakelknochen sah das Zeichen ganz anders aus (Hände über einem Weingefäß). Die Deutung „Mund + Löffel/Mensch“ gilt als Fehlanalyse.","i":"obs"},
"挟":{"t":"laut","x":"Alte Form 挾: eine Hand (扌) als Sinnteil – etwas greifen, einklemmen – und 夾 als Klangteil (キョウ). In der heutigen Form ist 夾 zu 夹 verkürzt.","s":2,"p":[["扌","Hand","b"],["夹","einklemmen","l"]],"a":"挾"},
"枯":{"t":"laut","x":"木 (Baum) zeigt den Sinnbereich: Pflanzen, die vertrocknen. 古 liefert den Klang (コ). Gemeint ist „verdorren, welken“.","s":2,"p":[["木","Baum","b"],["古","alt","l"]],"i":"s"},
"沸":{"t":"laut","x":"氵 (Wasser) gibt den Sinn: Wasser, das aufwallt. 弗 liefert den Klang (フツ). Das Zeichen steht für „kochen, sieden“.","s":2,"p":[["氵","Wasser","b"],["弗","nicht","l"]]},
"濯":{"t":"laut","x":"氵 (Wasser) gibt den Sinn: mit Wasser waschen, spülen. 翟 steht für den Klang (テキ, hier タク).","s":2,"p":[["氵","Wasser","b"],["翟","Fasan","l"]],"i":"bs"},
"燥":{"t":"laut","x":"火 (Feuer) zeigt den Sinn: durch Hitze trocknen. 喿 liefert den Klang (ソウ). Das Zeichen steht für „trocken, dürr“.","s":2,"p":[["火","Feuer","b"],["喿","Klangteil","l"]],"i":"s"},
"瓶":{"t":"laut","x":"瓦 (Ton, Töpferware) gibt den Sinn: ein Gefäß aus gebranntem Ton. 并 liefert den Klang (ヘイ → ビン).","s":2,"p":[["并","zusammen","l"],["瓦","Tongefäß","b"]],"n":"Ursprünglich ein Tongefäß mit langem, schmalem Hals, kein Glas. Heute meint das Zeichen Flaschen aller Art."},
"耕":{"t":"laut","x":"耒 (ein Pflug-Werkzeug) gibt den Sinn: den Boden bearbeiten. 井 liefert den Klang (コウ). Das Zeichen steht für „pflügen, bestellen“.","s":2,"p":[["耒","Pflug","b"],["井","Klangteil","l"]],"n":"井 sieht aus wie „Brunnen“, ist hier aber ein anderes Zeichen: die Urform von 型, die nur als Klangteil dient.","i":"s"},
"肯":{"t":"leih","x":"Das Zeichen bedeutete ursprünglich „Kinn“ und bestand aus Fleisch (肉) und einem Klangteil. Später wurde es für das gleich klingende Wort „zustimmen, einwilligen“ ausgeliehen.","s":1,"p":[["月","Fleisch","b"]],"n":"Oft liest man „Fleisch an einem Knochen“ (so deutete es schon das alte Wörterbuch). Die alten Bronzeformen zeigen aber keinen Bezug zum Knochenzeichen. Das obere 止 ist eine spätere Verformung.","i":"b"},
"脂":{"t":"laut","x":"月 steht hier für Fleisch (肉) und zeigt den Sinn: tierisches Gewebe, Fett. 旨 liefert den Klang (シ). Das Zeichen steht für „Fett, Talg“.","s":2,"p":[["月","Fleisch","b"],["旨","wohlschmeckend","l"]],"i":"s"},
"膚":{"t":"laut","x":"Fleisch (肉) gibt den Sinn: der Körper bzw. seine Haut. Der Klangteil ist eine verkürzte Form von 盧 (heute als 虍 + 胃-Teil sichtbar). Gemeint ist „Haut“.","s":2,"p":[["月","Fleisch","b"],["虍","Klangteil","l"]],"i":"b"},
"軒":{"t":"laut","x":"車 (Wagen) gibt den Sinn: Das Zeichen bezeichnete ursprünglich einen Wagen mit Verdeck. 干 liefert den Klang (カン → ケン).","s":2,"p":[["車","Wagen","b"],["干","Schild, trocknen","l"]]},
"軟":{"t":"laut","x":"Ursprünglich 輭: 車 (Wagen) als Sinnteil und 耎 als Klangteil (ナン). Mit der Zeit wurde 耎 zu 欠 verändert. Gemeint ist „weich“.","s":2,"p":[["車","Wagen","b"],["欠","Gähnen, fehlen","l"]],"n":"Warum gerade ein Wagen „weich“ anzeigt, ist nicht ganz klar. Vielleicht Erschöpfung nach dem Ziehen, vielleicht der Bezug zu weichem Holz."},
"郊":{"t":"laut","x":"阝 (hier 邑, Siedlung) gibt den Sinn: ein Ort. 交 liefert den Klang (コウ). Das Zeichen steht für das Gebiet vor der Stadt, die Vorstadt.","s":2,"p":[["交","kreuzen","l"],["阝","Stadt","b"]]},
"隅":{"t":"laut","x":"阝 (hier 阜, Hügel, Erdwall) gibt den Sinn. 禺 liefert den Klang (グウ). Das Zeichen steht für „Ecke, Winkel“.","s":2,"p":[["阝","Hügel","b"],["禺","Klangteil","l"]]},
"隻":{"t":"kombi","x":"Ein Vogel (隹) in der Hand (又): ein einzelnes Stück. Das verwandte Zeichen 雙 zeigt zwei Vögel in der Hand, also „ein Paar“. 隻 zählt daher Einzelnes, z. B. Schiffe.","s":1,"p":[["隹","Vogel","b"],["又","Hand","b"]],"n":"In sehr alten Texten zeigte 隻 einen gefangenen Vogel („erbeuten“). Dass es dafür ausgeliehen wurde, ist umstritten."},
"刀":{"t":"bild","x":"Ein Messer oder Schwert mit einer Schneide. Das Zeichen bildet die einseitige Klinge ab.","s":2,"i":"obs"},
"丁":{"t":"unklar","x":"Das Zeichen war ursprünglich ein einfaches Bild, was es zeigte, ist umstritten. Nach neuerer Forschung vielleicht der Scheitel des Kopfes. Später wurde es für den vierten Himmelsstamm ausgeliehen.","s":0,"n":"Weitere Vorschläge: Nagelkopf oder Stadtmauer. Beide gelten nach neuerer Forschung als Fehldeutung.","i":"obs"},
"又":{"t":"leih","x":"Das Zeichen zeigt eine rechte Hand und war die Urform von 右 „rechts“. Später wurde es für das Wort „wieder, außerdem“ ausgeliehen.","s":2,"n":"In vielen Zeichen erscheint 又 verkürzt als ⺕, z. B. in 事, 雪, 急.","i":"obs"},
"矢":{"t":"bild","x":"Ein Pfeil. Das Zeichen bildet einen Pfeil mit Spitze, Schaft und Federn ab; in alten Formen ist das gut zu erkennen.","s":2,"i":"obs"},
"羊":{"t":"bild","x":"Ein Schaf, von vorn gesehen. Das Zeichen bildet vor allem den Kopf mit den Hörnern ab.","s":2,"i":"obs"},
"氏":{"t":"unklar","x":"Ein altes Bildzeichen, dessen Vorbild unbekannt ist. Später wurde es für das Wort „Sippe, Familienname“ ausgeliehen.","s":0,"n":"Vorgeschlagen wurden u. a. eine Wurzel, ein Löffel, ein Mensch beim Säen oder ein Stab mit Zeichen. Keine Deutung ist gesichert.","i":"obs"},
"仮":{"t":"laut","x":"Alte Form 假: 亻 (Mensch) als Sinnteil und 叚 als Klangteil (カ). Die heutige Form mit 反 stammt aus Schreibschriftformen von 假. Gemeint ist „vorläufig, geliehen“.","s":2,"p":[["亻","Mensch","b"],["叚","Klangteil der Altform","l"],["反","Schreibkurzform","f"]],"a":"假","i":"s"},
"級":{"t":"laut","x":"糸 (Faden, Seide) gibt den Sinn, 及 den Klang (キュウ). Gemeint ist „Rang, Stufe“. Der Faden steht für die Bänder, an denen man Ränge erkannte.","s":2,"p":[["糸","Faden","b"],["及","erreichen","l"]],"i":"s"},
"功":{"t":"laut","x":"力 (Kraft) gibt den Sinn: Anstrengung und Verdienst. 工 liefert den Klang (コウ). Gemeint ist „Verdienst, Leistung“.","s":2,"p":[["工","Arbeit","l"],["力","Kraft","b"]]},
"第":{"t":"laut","x":"Entstand aus 弟 als abgespaltenes Zeichen. Der obere Teil wurde zu 竹 verformt. Das Zeichen wurde für „Reihenfolge, Nummer“ ausgeliehen; 弟 liefert den Klang (ダイ, テイ).","s":1,"p":[["竹","Bambus","b"],["弟","jüngerer Bruder","l"]],"n":"Eine andere Erklärung: 竹 steht für Bambusstreifen, auf denen man früher Listen und Ordnungen schrieb."},
"暑":{"t":"laut","x":"日 (Sonne) gibt den Sinn: Hitze. 者 liefert den Klang (ショ). Das Zeichen steht für „heiß“, besonders vom Sommer.","s":2,"p":[["日","Sonne","b"],["者","Person","l"]]},
"整":{"t":"laut","x":"Der obere Teil 敕 gibt den Sinnbereich an, 正 den Klang (セイ). Gemeint ist „in Ordnung bringen, ordnen“.","s":2,"p":[["敕","Befehl","b"],["正","richtig","l"]]},
"詩":{"t":"laut","x":"言 (Sprache) zeigt den Sinn: Dichtung ist Sprache in besonderer Form. 寺 liefert den Klang (ジ → シ). Gemeint ist „Gedicht“.","s":2,"p":[["言","Sprache","b"],["寺","Tempel","l"]],"i":"s"},
"器":{"t":"unklar","x":"Vier 口 um ein 犬 (Hund). Wie das Zeichen zu verstehen ist, ist nicht geklärt. Es wurde wohl für das Wort „Gefäß, Gerät“ ausgeliehen.","s":0,"p":[["口","Mund, Gefäß","f"],["犬","Hund","f"]],"n":"Oft liest man „ein Hund bewacht vier Gefäße“. Dass 口 hier Gefäße zeigt, ist nicht belegt. Eine andere Deutung: ein Opferhund umgeben von Behältern mit Gebeten.","i":"bs"},
"士":{"t":"bild","x":"Eine Streitaxt (Beil). Das Zeichen sah ursprünglich wie 王 aus. Später stand es für „Krieger, Beamter“ und dann „Gelehrter, Mann von Stand“.","s":2,"n":"Die alte Deutung „ein Strich über einer Zehn“ oder gar ein Körperteil ist ein Irrtum; frühe Formen zeigen die Axt.","i":"obs"},
"標":{"t":"laut","x":"木 (Baum) gibt den Sinn, 票 den Klang (ヒョウ). Ursprünglich meinte das Zeichen die Baumspitze, den Wipfel. Heute bedeutet es „Zeichen, Marke“.","s":2,"p":[["木","Baum","b"],["票","Zettel","l"]],"i":"s"},
"鏡":{"t":"laut","x":"釒 (Metall) gibt den Sinn: Spiegel aus Bronze. 竟 liefert den Klang (キョウ, ケイ). Gemeint ist „Spiegel“.","s":2,"p":[["釒","Metall","b"],["竟","Ende","l"]],"i":"s"},
"養":{"t":"laut","x":"食 (Essen) gibt den Sinn: ernähren, aufziehen. 羊 liefert den Klang (ヨウ). Das Zeichen steht für „ernähren, aufziehen“.","s":2,"p":[["羊","Schaf","l"],["食","Essen","b"]],"n":"Gelegentlich liest man „Schaf + Essen“ als Sinnverbindung. Die gleiche Lesung ヨウ stützt aber die Klangdeutung.","i":"s"},
"謝":{"t":"laut","x":"言 (Wort, Sprache) zeigt den Sinn: Worte sagen. 射 liefert den Klang (シャ). Das Zeichen steht für „danken, sich entschuldigen“.","s":2,"p":[["言","Sprache","b"],["射","schießen","l"]]},
"松":{"t":"laut","x":"木 (Baum) gibt den Sinn, 公 den Klang (コウ). Das Zeichen steht für die Kiefer.","s":2,"p":[["木","Baum","b"],["公","öffentlich","l"]]},
"基":{"t":"laut","x":"土 (Erde) gibt den Sinn: der Boden als Fundament. 其 liefert den Klang (キ). Gemeint ist „Grundlage, Fundament“.","s":2,"p":[["其","dieser","l"],["土","Erde","b"]],"i":"obs"},
"妥":{"t":"leih","x":"Eine Hand (爪) von oben auf einer Frau (女): beruhigen, besänftigen. Das war die Urbedeutung (heute 綏). Später für „angemessen, passend“ ausgeliehen.","s":2,"p":[["爫","Hand","b"],["女","Frau","b"]],"i":"ob"},
"雰":{"t":"laut","x":"雨 (Regen) gibt den Sinn: Dunst, Nebel in der Luft. 分 liefert den Klang (ブン → フン). Heute steht es für „Stimmung, Atmosphäre“.","s":2,"p":[["雨","Regen","b"],["分","teilen","l"]],"i":"s"},
"頑":{"t":"laut","x":"頁 (Kopf) gibt den Sinn: ein sturer Kopf. 元 liefert den Klang (ゲン → ガン). Gemeint ist „hartnäckig, stur“.","s":2,"p":[["元","Kopf, Ursprung","l"],["頁","Kopf","b"]],"n":"Nach einer Erklärung bedeutete 元 ursprünglich selbst „Kopf“. Dann wäre das Zeichen eine Verdopplung: ein „Kopf“ mit der Bedeutung „unbeweglicher Kopf“.","i":"s"},
"司":{"t":"unklar","x":"Wie das Zeichen entstand, ist nicht geklärt. Es steht für „leiten, verwalten“.","s":0,"n":"Eine Deutung sieht einen Mund (口), der Befehle gibt, plus ein Zeichen der Macht. „Mensch + Mund“ gilt als Fehldeutung.","i":"obs"},
"泣":{"t":"laut","x":"氵 (Wasser) gibt den Sinn: Tränen. 立 liefert den Klang. Ursprünglich „Tränen“, daraus „weinen“.","s":2,"p":[["氵","Wasser","b"],["立","stehen","l"]],"i":"s"},
"紀":{"t":"laut","x":"糸 (Faden) gibt den Sinn: Schnur, Seil. 己 liefert den Klang (キ). Ursprünglich „Schnur, Seil“.","s":2,"p":[["糸","Faden","b"],["己","selbst","l"]]},
"典":{"t":"bild","x":"Ein Buch aus Bambusstreifen (冊), das auf eine Unterlage gelegt wird. Daraus entstand die Bedeutung „Schriftwerk, Vorschrift“.","s":1,"p":[["冊","Buch","b"],["丌","Unterlage","b"]],"n":"Oft liest man „ein Buch auf einem Tisch“. Ob die Unterlage ein Tisch ist, ist nicht gesichert.","i":"obs"},
"保":{"t":"kombi","x":"Ein Mensch, der ein Kind auf dem Rücken trägt. Daraus wurde „tragen, beschützen“. In der heutigen Form hat sich das Kind zu 呆 verformt.","s":2,"p":[["亻","Mensch","b"],["子","Kind (heute 呆)","b"]],"n":"Die alte Deutung „亻 + 呆“ ist falsch: 呆 ist nur eine verkürzte Form von 保.","i":"obs"},
"弁":{"t":"kurz","x":"Heute steht 弁 für mehrere alte Zeichen, z. B. 辯 (reden, verteidigen: 言 mit zwei 辛 als Klangteil 辡). Das Zeichen 弁 selbst ist alt und enthält zwei Hände (廾).","s":0,"p":[["廾","zwei Hände","b"]],"n":"Für das ursprüngliche 弁 gibt es drei Deutungen: zwei Hände setzen einer Person eine Kappe auf; zwei Hände klatschen; zwei Hände halten einen Korb.","a":"辯","i":"s"},
"証":{"t":"laut","x":"言 (Wort) als Sinnteil und 正 als Klangteil (セイ → ショウ). Ursprünglich „ermahnen“, später „beweisen, Beweis“. Heute auch Kurzform von 證 (Klangteil 登).","s":2,"p":[["言","Sprache","b"],["正","richtig","l"]],"a":"證"},
"冒":{"t":"leih","x":"Ursprünglich 冃 (Mütze); später kam 目 dazu. Das Zeichen bedeutete „Kopfbedeckung“ (heute 帽) und wurde dann für „wagen, sich aussetzen“ ausgeliehen.","s":1,"p":[["冃","Mütze","b"],["目","Auge","l"]],"n":"Ob 目 Klang- oder Sinnteil ist, sehen Fachleute unterschiedlich.","i":"bs"},
"冗":{"t":"kombi","x":"Ein Dach (宀) über einem Menschen (儿): jemand zu Hause ohne Arbeit. Daraus wurde „überflüssig, Muße“.","s":2,"p":[["宀","Dach","b"],["儿","Mensch","b"]],"n":"Eine alte Orakelknochenform, die früher als 冗 galt, ist in Wirklichkeit 六妣.","i":"os"},
"梅":{"t":"laut","x":"木 (Baum) gibt den Sinn, 毎 den Klang (マイ → バイ). Das Zeichen steht für den Pflaumenbaum.","s":2,"p":[["木","Baum","b"],["毎","jeder","l"]],"i":"s"},
"結":{"t":"laut","x":"糸 (Faden) gibt den Sinn: Fäden verknoten. 吉 liefert den Klang (キツ → ケツ). Gemeint ist „binden, knüpfen“.","s":2,"p":[["糸","Faden","b"],["吉","Glück","l"]]},
"是":{"t":"leih","x":"Die Urform bestand aus 止 (Fuß) und einem Klangteil (Kind + Buch). Sie stand für „Lederschuh“. Später wurde sie für „dies, das“ ausgeliehen, die Teile verschliffen.","s":1,"p":[["止","Fuß","b"]],"n":"Oft liest man „日 + 正“. Das ist ein Fehler des alten Wörterbuchs.","i":"obs"},
"渉":{"t":"kombi","x":"Wasser (氵) und Füße (歩): durch einen Fluss waten. Die alten Formen zeigen Wasser mit je einem Fuß auf beiden Seiten.","s":2,"p":[["氵","Wasser","b"],["歩","gehen","b"]]},
"虚":{"t":"laut","x":"Alte Form 虛: 丘 (Hügel) als Sinnteil und 虍 als Klangteil (キョ). Ursprünglich ein großer Hügel. Später „leer“. Im heutigen Zeichen ist 丘 zu 业 verkürzt.","s":2,"p":[["虍","Tiger","l"],["业","Hügel (verkürzt)","b"]],"a":"虛","i":"s"},
"幻":{"t":"unklar","x":"Die Herkunft ist nicht geklärt. Man sieht darin eine Abwandlung von 玄 oder eine Kurzform von 縣.","s":0,"n":"Oft liest man, es sei ein auf den Kopf gestelltes 予 (Weberschiffchen). Das gilt als Irrtum.","i":"s"},
"弓":{"t":"bild","x":"Ein Bogen. Das Zeichen bildet den Holzbogen ab.","s":2,"n":"Die Bogensehne wurde in der heutigen Form weggelassen.","i":"obs"},
"汽":{"t":"laut","x":"氵 (Wasser) gibt den Sinn: Dampf von Wasser. 气 liefert den Klang (キ). Gemeint ist „Dampf, Wasserdampf“.","s":2,"p":[["氵","Wasser","b"],["气","Dampf","l"]],"i":"s"},
"僧":{"t":"laut","x":"亻 (Mensch) gibt den Sinn: eine bestimmte Art Mensch, der Mönch. 曽 (alt 曾) liefert den Klang (ソウ).","s":2,"p":[["亻","Mensch","b"],["曽","Klangteil","l"]],"i":"s"},
"禅":{"t":"laut","x":"Alte Form 禪: 示 (礻, Altar, Ritual) als Sinnteil, 單 als Klangteil. Heute 単 statt 單. Das Zeichen steht für Zen.","s":2,"p":[["礻","Altar","b"],["単","einzeln","l"]],"a":"禪","i":"s"},
"句":{"t":"laut","x":"Zwei Teile: 丩 (verschlungene Stränge, Klang ク) und 口 (Mund). Das Zeichen steht für einen Satzabschnitt, „Satz, Phrase“.","s":1,"p":[["丩","Verschlungenes","l"],["口","Mund","f"]],"n":"Ob 口 Klangteil oder nur Zusatz ist, ist offen. 丩 sieht heute wie 勹 aus, ist aber ein anderes Zeichen.","i":"obs"},
"節":{"t":"laut","x":"竹 (Bambus) gibt den Sinn: der Knoten am Bambus. 即 liefert den Klang (ソク → セツ). Gemeint ist „Knoten, Abschnitt“.","s":2,"p":[["竹","Bambus","b"],["即","sofort","l"]],"i":"s"},
"昆":{"t":"unklar","x":"Die Herkunft ist umstritten. Einige sehen darin den Körper eines Insekts mit Beinen, andere ein Reh ohne Geweih. Später für ein anderes Wort ausgeliehen.","s":0,"i":"obs"},
"閥":{"t":"laut","x":"門 (Tor) gibt den Sinn: Haus, Familie von Rang. 伐 liefert den Klang (バツ). Gemeint ist „Familie, Clique“.","s":2,"p":[["門","Tor","b"],["伐","schlagen","l"]],"i":"s"},
"舌":{"t":"bild","x":"Eine Zunge, die aus einem Mund (口) herausragt. In alten Formen ist die Zunge gespalten, wie eine Schlangenzunge.","s":2,"p":[["口","Mund","b"]],"n":"Das alte Wörterbuch zerlegt das Zeichen in 干 + 口. Das ist falsch.","i":"os"},
"宙":{"t":"laut","x":"宀 (Dach) gibt den Sinn: etwas, das überspannt. 由 liefert den Klang (ユウ → チュウ). Gemeint ist „Raum, Weltall“.","s":2,"p":[["宀","Dach","b"],["由","Ursprung","l"]]},
"履":{"t":"laut","x":"In alten Formen sieht man eine Person, die einen Schritt macht, dazu 眉 als Klangteil. So wurde es zum Zeichen für „treten, gehen“. Die heutige Form ist durch Umformung entstanden.","s":1,"p":[["尸","Körper","b"],["復","zurück","f"]],"n":"Das alte Wörterbuch zerlegt es in 尸 + 彳 + 夊 + 舟. Das ist falsch.","i":"obs"},
"善":{"t":"kombi","x":"Ein Schaf (羊), das für etwas Gutes, Schönes steht, über zwei 言 (Reden). Die Altform 譱 hatte beide 言. Das Zeichen steht für „gut“.","s":1,"p":[["羊","Schaf","b"],["言","Rede","b"]],"n":"Eine Deutung: Man lobt gemeinsam gutes Essen. Eine andere: 言 liefert den Klang.","i":"bs"},
"災":{"t":"laut","x":"火 (Feuer) gibt den Sinn: Unglück. 巛 (Flut, ursprünglich als Wassernot) liefert den Klang. Gemeint ist „Katastrophe“.","s":2,"p":[["巛","Flut","l"],["火","Feuer","b"]]},
"率":{"t":"leih","x":"Ursprünglich ein dickes Seil, mit Zierstrichen oben und unten. Das Zeichen wurde für „führen“ und „Verhältnis“ ausgeliehen.","s":2,"n":"Das alte Wörterbuch deutet es als Vogelfangnetz. Das gilt nicht mehr.","i":"obs"},
"妨":{"t":"laut","x":"Links 女 (Frau) als Sinnteil, rechts 方 als Klangteil (ホウ → ボウ). Gemeint ist „behindern, stören“.","s":2,"p":[["女","Frau","b"],["方","Seite, Richtung","l"]],"n":"Eine Vermutung: 方 stand früher auch für „Raum einnehmen“, das Zeichen hieße dann wörtlich „jemandem den Weg zu einer Frau versperren“. Sicher ist das nicht."},
"裕":{"t":"laut","x":"Links 衤 (Kleidung) als Sinnteil, rechts 谷 als Klangteil. Das Zeichen bedeutet „reichlich, großzügig, geräumig“; die Bedeutung hat sich also von der Kleidung weg verschoben.","s":2,"p":[["衤","Kleidung","b"],["谷","Tal","l"]],"n":"Oft liest man „zwischen Körper und Kleid ist Platz wie in einem Tal“. Das gilt als nachträgliche Erfindung: 谷 liefert hier nur den Klang, keine Bedeutung.","i":"bs"},
"尾":{"t":"kombi","x":"Ein Mensch (尸) mit angesetztem Haarbüschel (毛): ein Mensch mit Schwanz. Daraus wurde „Schwanz, Ende“.","s":2,"p":[["尸","Mensch","b"],["毛","Haar, Fell","b"]],"n":"Auch in älteren Formen von 僕 steckt so ein Schwanz; man vermutet, dass er ein Zeichen niedriger Stellung war.","i":"s"},
"嫌":{"t":"laut","x":"Links 女 (Frau) als Sinnteil, rechts 兼 als Klangteil (ケン). Das Zeichen steht für „verabscheuen, nicht mögen“.","s":2,"p":[["女","Frau","b"],["兼","zugleich","l"]],"i":"s"},
"臭":{"t":"kombi","x":"自 ist das alte Bild einer Nase, 犬 ein Hund, der für seinen Geruchssinn bekannt ist: ursprünglich „riechen, schnuppern“. Später wurde das Zeichen für „Geruch, Gestank“ ausgeliehen.","s":2,"p":[["自","Nase","b"],["犬","Hund","b"]],"n":"Für „riechen“ entstand später das neue Zeichen 嗅 (mit 口 Mund).","i":"os"},
"穴":{"t":"bild","x":"Das Bild einer Höhle oder einer Erdwohnung, vielleicht auch eines Eingangs. Daraus wurde „Loch, Höhle“.","s":1,"i":"s"},
"笛":{"t":"laut","x":"Oben 竹 (Bambus) als Sinnteil, denn Flöten wurden aus Bambus gemacht. Unten 由 als Klangteil. Zusammen: „Flöte“.","s":2,"p":[["竹","Bambus","b"],["由","Ursprung","l"]]},
"敵":{"t":"laut","x":"Rechts 攵 (Hand mit Stock, „schlagen“) als Sinnteil, links 啇 als Klangteil (テキ). Gemeint ist „Feind, Gegner“.","s":2,"p":[["攵","schlagen","b"],["啇","Klangteil","l"]]},
"挙":{"t":"laut","x":"Die alte Form 擧 hat unten 手 (Hand) als Sinnteil und oben 與 als Klangteil (ヨ → キョ). Gemeint ist „(hoch)heben“. In der heutigen Form wurde 與 stark verkürzt.","s":2,"p":[["手","Hand","b"],["與","geben","l"]],"a":"擧"},
"派":{"t":"laut","x":"Links 氵 (Wasser), rechts der Klangteil 𠂢 (ハ). 𠂢 war das ursprüngliche Zeichen; 氵 kam später dazu, um es deutlicher zu machen. Gemeint ist ein abzweigender Nebenarm eines Flusses, daher „Zweig, Richtung, Gruppe“.","s":2,"p":[["氵","Wasser","b"],["𠂢","Klangteil","l"]],"i":"s"},
"素":{"t":"leih","x":"素 war zunächst eine Nebenform von 索 (Hände flechten einen Faden). Das Zeichen wurde dann für das gleich klingende Wort für „Grundstoff, schlicht, unbearbeitet“ ausgeliehen.","s":1,"p":[["糸","Faden","b"],["龶","Formrest","f"]],"n":"Der obere Teil sieht heute aus wie 生 ohne den schrägen Strich, hat damit aber nichts zu tun.","i":"bs"},
"評":{"t":"laut","x":"Links 訁 (Sprache) als Sinnteil, rechts 平 als Klangteil (ヘイ → ヒョウ). Man „spricht“ über etwas und bewertet es.","s":2,"p":[["訁","Sprache","b"],["平","eben","l"]]},
"批":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 比 als Klangteil (ヒ). Ursprünglich „schlagen“; später für „beurteilen, kritisieren“ ausgeliehen.","s":2,"p":[["扌","Hand","b"],["比","vergleichen","l"]]},
"検":{"t":"laut","x":"Die alte Form 檢 hat links 木 (Holz) als Sinnteil und rechts 僉 als Klangteil (セン → ケン). Gemeint ist „prüfen, untersuchen“. Heute ist 僉 zu 㑒 verkürzt.","s":2,"p":[["木","Holz","b"],["僉","alle","l"]],"a":"檢","i":"s"},
"審":{"t":"unklar","x":"Oben 宀 (Dach), darunter ein Teil, dessen Bedeutung nicht geklärt ist. Wie das Zeichen ursprünglich aufgebaut war, weiß man nicht genau. Heute bedeutet es „prüfen, beurteilen“.","s":0,"p":[["宀","Dach","b"]],"n":"Das alte Wörterbuch 説文解字 zerlegt es in 宀, 釆 und 田. Alte Inschriften zeigen aber, dass das nicht stimmt.","i":"s"},
"条":{"t":"laut","x":"Die alte Form 條 hat oben 攸 als Klangteil und unten 木 (Baum) als Sinnteil. Ursprünglich war ein kleiner Zweig gemeint, später „Streifen, Absatz, Paragraf“. Heute ist der obere Teil zu 夂 verkürzt.","s":2,"p":[["攸","Klangteil","l"],["木","Baum","b"]],"a":"條"},
"企":{"t":"kombi","x":"Ein Mensch (人) über einem Fuß (止): jemand steht auf Zehenspitzen. Daraus wurde „sich recken, anstreben, planen“.","s":2,"p":[["人","Mensch","b"],["止","Fuß","b"]],"i":"os"},
"義":{"t":"laut","x":"Oben 羊 als Sinnteil, unten 我 als Klangteil (ガ → ギ). 羊 steht hier für „gut, glückbringend“, nicht für das Schaf. Gemeint ist rechtes, richtiges Handeln.","s":2,"p":[["羊","gut (Glück)","b"],["我","ich","l"]],"i":"obs"},
"罰":{"t":"unklar","x":"Das Zeichen besteht aus 罒, 言 und 刂 (Messer) und bedeutet „Strafe“. Wie es genau entstand, ist ungeklärt.","s":0,"p":[["罒","Netz","f"],["言","Sprache","b"],["刂","Messer","b"]],"n":"Einige sehen darin Beschimpfung (言) plus Messer (刂) als Zeichen für ein Vergehen. Das ist eine Deutung, kein gesicherter Befund.","i":"bs"},
"誕":{"t":"laut","x":"Links 言 (Sprache) als Sinnteil, rechts 延 als Klangteil (エン → タン). Ursprünglich „übertreiben, flunkern“; später für „geboren werden“ ausgeliehen.","s":2,"p":[["言","Sprache","b"],["延","dehnen","l"]],"n":"Oft liest man „weit ausgedehntes Reden, daher Übertreibung“. Das gilt als nachträgliche Deutung: 延 liefert nur den Klang."},
"脱":{"t":"laut","x":"Die alte Form 脫 hat links 月 (hier „Fleisch, Körper“) als Sinnteil und rechts 兌 als Klangteil (タイ → ダツ). Gemeint ist „abstreifen, ausziehen“.","s":2,"p":[["月","Fleisch","b"],["兑","tauschen","l"]],"n":"Früher las man darin eine Sinnverbindung. Das gilt als unbelegt.","a":"脫"},
"宮":{"t":"kombi","x":"宀 ist ein Haus. Darunter steht 呂, ursprünglich das Bild aneinandergereihter Räume. Zusammen: ein Gebäude mit vielen Räumen, „Palast“.","s":2,"p":[["宀","Haus","b"],["呂","Räume","b"]],"n":"Das alte Wörterbuch 説文解字 deutet den unteren Teil als Körper-Zeichen. Das gilt als falsch.","i":"obs"},
"案":{"t":"laut","x":"Unten 木 (Holz) als Sinnteil, oben 安 als Klangteil (アン). Ursprünglich „Tisch“; später für das gleich klingende Wort „Gedanke, Plan, Entwurf“ ausgeliehen.","s":2,"p":[["木","Holz","b"],["安","ruhig","l"]],"n":"Früher las man 安 auch als Bedeutungsteil. Das gilt als unbelegt."},
"価":{"t":"laut","x":"Die alte Form 價 hat links 亻 (Mensch) und rechts 賈 (Handel treiben) als Klangteil (コ → カ). Heute ist 賈 auf 覀 verkürzt. Gemeint ist „Preis, Wert“.","s":2,"p":[["亻","Mensch","b"],["賈","handeln","l"]],"n":"Früher las man 賈 auch als Bedeutungsteil. Das gilt als Irrtum.","a":"價"},
"統":{"t":"laut","x":"Links 糸 (Faden) als Sinnteil, rechts 充 als Klangteil (ジュウ → トウ). Gemeint ist das Zusammenfassen von Fäden: „vereinen, regieren“.","s":2,"p":[["糸","Faden","b"],["充","füllen","l"]],"i":"s"},
"策":{"t":"laut","x":"Oben 竹 (Bambus) als Sinnteil, unten 朿 als Klangteil (サク). Ursprünglich „Bambustafel, Schriftstück“; später für „Plan, Maßnahme“ ausgeliehen.","s":2,"p":[["竹","Bambus","b"],["朿","Dorn","l"]]},
"藤":{"t":"laut","x":"Oben 艹 (Pflanze) als Sinnteil, unten 滕 als Klangteil (トウ). So steht es für die Glyzine, eine Kletterpflanze.","s":2,"p":[["艹","Pflanze","b"],["滕","Klangteil","l"]]},
"姿":{"t":"laut","x":"Oben 次 als Klangteil (ジ → シ), unten 女 (Frau) als Sinnteil. Gemeint ist „Gestalt, Haltung“.","s":2,"p":[["次","nächster","l"],["女","Frau","b"]],"i":"s"},
"応":{"t":"laut","x":"Die alte Form 應 hat unten 心 (Herz) als Sinnteil und oben 䧹 als Klangteil (オウ). Gemeint ist „antworten“. Heute ist der obere Teil auf 广 verkürzt.","s":2,"p":[["心","Herz","b"],["广","Formrest","f"]],"a":"應"},
"提":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 是 als Klangteil (ゼ → テイ). Ursprünglich „in der Hand tragen“, daher „vorlegen, vorschlagen“.","s":2,"p":[["扌","Hand","b"],["是","dies, richtig","l"]]},
"援":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 爰 als Klangteil (エン). Gemeint ist „helfen, unterstützen“.","s":2,"p":[["扌","Hand","b"],["爰","ziehen","l"]]},
"態":{"t":"laut","x":"Oben 能 als Klangteil (ノウ → タイ), unten 心 (Herz) als Sinnteil. Gemeint ist die innere Haltung, daraus „Zustand, Verhalten“.","s":2,"p":[["能","können","l"],["心","Herz","b"]],"i":"s"},
"賀":{"t":"laut","x":"Oben 加 als Klangteil (カ → ガ), unten 貝 (Muschel, früher Geld) als Sinnteil. Gemeint ist ein Geschenk zum Glückwunsch: „gratulieren“.","s":1,"p":[["加","hinzufügen","l"],["貝","Muschel, Geld","b"]],"i":"s"},
"鬼":{"t":"bild","x":"Das Bild eines knienden Menschen mit hässlichem Gesicht (oben 甶), vielleicht einer Maske: ein Geist oder Dämon. Der Punkt unten rechts kam später als Schwanz-Rest dazu.","s":2,"n":"In alten Inschriften gab es stehende und sitzende Formen. Heute weiß man: die sitzende gehört zu 異, nur die stehende zu 鬼.","i":"obs"},
"護":{"t":"laut","x":"Links 言 (Sprache) als Sinnteil, rechts 蒦 als Klangteil (カク → ゴ). Gemeint ist „schützen, in Schutz nehmen“.","s":2,"p":[["言","Sprache","b"],["蒦","Klangteil","l"]],"i":"s"},
"裁":{"t":"laut","x":"Unten 衣 (Kleidung) als Sinnteil, oben 𢦏 als Klangteil (サイ). Ursprünglich Stoff zuschneiden, daher „schneiden, entscheiden, richten“.","s":2,"p":[["衣","Kleidung","b"],["𢦏","Klangteil","l"]],"n":"Im Klangteil steckt bereits die Vorstellung des Schneidens.","i":"s"},
"崎":{"t":"laut","x":"Links 山 (Berg) als Sinnteil, rechts 奇 als Klangteil (キ). Ursprünglich „steil, schroff“; im Japanischen auch „Kap, Landspitze“.","s":2,"p":[["山","Berg","b"],["奇","seltsam","l"]]},
"看":{"t":"laut","x":"Unten 目 (Auge) als Sinnteil, oben ein Klangteil (カン), der aus 㫃 entstand. Gemeint ist „(hin)sehen, beobachten“.","s":1,"p":[["目","Auge","b"],["㫃","Klangteil","l"]],"n":"Oft liest man „Hand über den Augen, um in die Ferne zu schauen“. Der obere Teil ist aber keine Hand.","i":"s"},
"幹":{"t":"laut","x":"Beide Teile liefern den Klang (カン). Ursprünglich schrieb man 榦 mit 木 (Baum) als Sinnteil; dieses wurde durch 干 ersetzt. Gemeint ist der Baumstamm, übertragen „Hauptsache, Rückgrat“.","s":2,"p":[["倝","Klangteil","l"],["干","trocken","l"]]},
"張":{"t":"laut","x":"Links 弓 (Bogen) als Sinnteil, rechts 長 als Klangteil (チョウ). Gemeint ist „spannen“, ursprünglich die Bogensehne; daraus „ausspannen, dehnen“.","s":2,"p":[["弓","Bogen","b"],["長","lang","l"]],"n":"Früher las man 長 auch als Bedeutungsteil (lang). Laut neuer Forschung ist das ein Irrtum."},
"沢":{"t":"laut","x":"Die alte Form 澤 hat 氵 (Wasser) und 睪 als Klangteil. In der heutigen Form wurde 睪 durch das einfache 尺 ersetzt, wie schon bei 釈 (alt 釋). Gemeint ist „Sumpf, Feuchtgebiet“.","s":1,"p":[["氵","Wasser","b"],["尺","Elle","l"]],"a":"澤"},
"施":{"t":"laut","x":"Links 㫃 als Sinnteil, rechts 也 als Klangteil (シ). Gemeint ist „anwenden, ausführen, gewähren“.","s":1,"p":[["㫃","Fahne","b"],["也","auch","l"]]},
"俳":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 非 als Klangteil (ヒ → ハイ). Gemeint ist ein Mensch, der auftritt, ein Schauspieler.","s":1,"p":[["亻","Mensch","b"],["非","nicht","l"]]},
"秀":{"t":"unklar","x":"Oben 禾 (Getreide), unten ein Teil, dessen Herkunft unklar ist. Eine Deutung sieht das Blühen einer Reispflanze, eine andere eine herabhängende Ähre. Heute: „hervorragend, ausgezeichnet“.","s":0,"p":[["禾","Getreide","b"],["乃","Formrest","f"]],"n":"Der untere Teil 乃 geht vielleicht auf 引 zurück. Ältere Schreibungen zeigen unten 弓 bzw. 引.","i":"s"},
"製":{"t":"laut","x":"Unten 衣 (Kleidung) als Sinnteil, oben 制 als Klangteil (セイ). Ursprünglich „Kleidung schneidern“; später allgemein „herstellen“.","s":2,"p":[["衣","Kleidung","b"],["制","regeln","l"]]},
"狭":{"t":"laut","x":"Die alte Form 狹 hat links 犭 (Hund) als Sinnteil und rechts 夾 als Klangteil (キョウ). Gemeint ist „eng, schmal“. In der heutigen Form ist 夾 zu 夹 verkürzt.","s":2,"p":[["犭","Hund","b"],["夾","einklemmen","l"]],"a":"狹"},
"載":{"t":"laut","x":"Unten 車 (Wagen) als Sinnteil, oben 𢦏 als Klangteil (サイ). Gemeint ist „auf den Wagen laden“, daraus „aufladen, mitnehmen, veröffentlichen“.","s":2,"p":[["車","Wagen","b"],["𢦏","Klangteil","l"]]},
"視":{"t":"kombi","x":"Das Zeichen geht auf eine stehende Person mit betontem Auge zurück („sehen“). Später kam links 礻 hinzu, dann sah es aus wie heute: „betrachten, ansehen“.","s":1,"p":[["礻","zeigen","b"],["見","sehen","b"]],"n":"Oft liest man 示 als Klangteil. Das passt lautlich nicht, sagt die neuere Forschung.","i":"obs"},
"環":{"t":"laut","x":"Links 玉 (Jade) als Sinnteil, rechts 睘 als Klangteil (ケイ → カン). Gemeint ist ein runder Jadering: „Ring, Kreis“.","s":2,"p":[["玉","Jade","b"],["睘","Klangteil","l"]],"i":"bs"},
"展":{"t":"laut","x":"Oben 尸 als Sinnteil, darunter der Klangteil 𧝑 (テン), der heute stark verformt ist. Gemeint ist „ausbreiten, entfalten“.","s":1,"p":[["尸","Körper","b"],["𧝑","Klangteil","l"]],"i":"s"},
"株":{"t":"laut","x":"Links 木 (Baum) als Sinnteil, rechts 朱 als Klangteil (シュ). Gemeint ist der Baumstumpf, daraus „Stamm, Stück, Aktie“.","s":2,"p":[["木","Baum","b"],["朱","rot","l"]]},
"影":{"t":"laut","x":"Links 景 als Klangteil (ケイ → エイ), rechts 彡 (Farbstriche) als Sinnteil. Gemeint ist der Schatten, das Bild.","s":2,"p":[["景","Licht","l"],["彡","Striche","b"]],"n":"Der Klangteil 景 trägt wohl auch die Idee „Bild“ mit."},
"響":{"t":"laut","x":"Unten 音 (Ton) als Sinnteil, oben 鄉 als Klangteil (キョウ). Gemeint ist „widerhallen, klingen“.","s":2,"p":[["郷","Dorf","l"],["音","Ton","b"]],"i":"s"},
"票":{"t":"leih","x":"Das Zeichen zeigte zuerst eine Baumspitze, den Wipfel. Es wurde dann für das gleich klingende Wort „Zettel, Marke“ ausgeliehen. Die Teile 覀 und 示 sind durch spätere Formänderungen entstanden.","s":0,"p":[["覀","Formrest","f"],["示","Formrest","f"]],"n":"Eine andere Deutung: zwei Paare Hände heben etwas hoch, ursprünglich aufsteigende Funken. Welche stimmt, ist offen.","i":"s"},
"訴":{"t":"laut","x":"Links 訁 (Sprache) als Sinnteil, rechts ein Klangteil, der ursprünglich 㡿 war und sich zu 斥 verformt hat. Gemeint ist „klagen, vorbringen“.","s":1,"p":[["訁","Sprache","b"],["斥","Klangteil","l"]]},
"訟":{"t":"laut","x":"Links 訁 (Sprache) als Sinnteil, rechts 公 als Klangteil (コウ → ショウ). Gemeint ist „sich streiten, streiten vor Gericht“.","s":2,"p":[["訁","Sprache","b"],["公","öffentlich","l"]]},
"逮":{"t":"laut","x":"辶 (gehen) als Sinnteil, 隶 als Klangteil (タイ). Ursprünglich „erreichen“; daraus „einholen, festnehmen“.","s":2,"p":[["辶","gehen","b"],["隶","erreichen","l"]]},
"模":{"t":"laut","x":"Links 木 (Holz) als Sinnteil, rechts 莫 als Klangteil (バク → ボ, モ). Gemeint ist die Form, die Vorlage; das Holz erinnert an Formen aus Holz.","s":2,"p":[["木","Holz","b"],["莫","Klangteil","l"]],"i":"s"},
"鮮":{"t":"kombi","x":"Ein Fisch (魚) neben einem Schaf (羊): beides köstlich und frisch. Daraus wurde „frisch, lebendig, klar“.","s":1,"p":[["魚","Fisch","b"],["羊","Schaf","b"]],"n":"Eine andere Deutung: 魚 als Sinnteil und 羊 (oder 羴) nur als Klangteil. Beides wird vertreten.","i":"s"},
"属":{"t":"laut","x":"Die alte Form 屬 hat oben 尾 (Schwanz) als Sinnteil und unten 蜀 als Klangteil (ショク → ゾク). Gemeint ist „folgen, dazugehören“. Heute ist der Aufbau stark verkürzt.","s":2,"p":[["尸","Schwanz","b"],["蜀","Klangteil","l"]],"a":"屬","i":"s"},
"肥":{"t":"laut","x":"Links 月 (Fleisch) als Sinnteil, rechts ein Klangteil (ヒ), wohl ein verkürztes 妃. Gemeint ist „fett, fruchtbar, düngen“.","s":1,"p":[["月","Fleisch","b"],["巴","Klangteil","l"]],"n":"Das alte Wörterbuch 説文解字 liest 肉 plus kniende Person. Mit 巴 oder 己 hat der Teil nichts zu tun."},
"絞":{"t":"laut","x":"Links 糸 (Faden) als Sinnteil, rechts 交 als Klangteil (コウ). Gemeint ist „zusammendrehen, abschnüren, auswringen“.","s":2,"p":[["糸","Faden","b"],["交","kreuzen","l"]],"n":"Das alte Wörterbuch 説文解字 sieht darin eine Sinnverbindung."},
"輩":{"t":"laut","x":"Unten 車 (Wagen) als Sinnteil, oben 非 als Klangteil (ヒ → ハイ). Gemeint ist eine Reihe von Wagen, daraus „Reihe, Genossen“.","s":2,"p":[["車","Wagen","b"],["非","nicht","l"]]},
"隠":{"t":"laut","x":"Die alte Form 隱 hat links 阝 (Hügel, Berg) als Sinnteil und rechts 㥯 als Klangteil (イン). Gemeint ist „verbergen, verstecken“. Heute ist der rechte Teil vereinfacht.","s":2,"p":[["阝","Hügel","b"],["㥯","Klangteil","l"]],"a":"隱","i":"s"},
"授":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 受 als Klangteil (ジュ). Gemeint ist „aushändigen, erteilen, lehren“.","s":2,"p":[["扌","Hand","b"],["受","empfangen","l"]]},
"創":{"t":"laut","x":"Rechts 刂 (Messer) als Sinnteil, links 倉 als Klangteil (ソウ). Ursprünglich „verletzen, Wunde“; später für „anfangen, schaffen“ ausgeliehen.","s":2,"p":[["刂","Messer","b"],["倉","Lager","l"]],"i":"s"},
"往":{"t":"laut","x":"Der rechte Teil war zuerst ein Fuß (止) plus 王 als Klangteil (オウ). Später kam 彳 (gehen) dazu, und aus 王 wurde das heutige 主. Gemeint ist „gehen, hin“.","s":2,"p":[["彳","gehen","b"],["主","Formrest","f"]],"n":"Das 主 hat heute nichts mit „Herr“ zu tun.","i":"obs"},
"較":{"t":"laut","x":"Links 車 (Wagen) als Sinnteil, rechts 交 als Klangteil (コウ). Ursprünglich ein Querholz am Wagen; später für „vergleichen“ ausgeliehen.","s":2,"p":[["車","Wagen","b"],["交","kreuzen","l"]],"n":"Als Klangteil stand ursprünglich 爻, später wurde es zu 交."},
"鉛":{"t":"laut","x":"Links 釒 (Metall) als Sinnteil, rechts 㕣 als Klangteil (エン). So steht es für das Metall Blei.","s":2,"p":[["釒","Metall","b"],["㕣","Klangteil","l"]],"n":"Oft liest man „fließendes, schmelzendes Metall“. Das gilt als nachträgliche Erfindung: 㕣 liefert nur den Klang."},
"故":{"t":"laut","x":"Links 古 als Klangteil (コ), rechts 攵 (Hand mit Stock, „schlagen“) als Sinnteil. Gemeint ist „Grund, Ursache“; daraus „deshalb, alt“.","s":2,"p":[["古","alt","l"],["攵","schlagen","b"]],"i":"bs"},
"障":{"t":"laut","x":"Links 阝 (die Hügel-/Wall-Form von 阜) als Sinnteil, rechts 章 als Klangteil (ショウ → 障 ショウ). Das Wort bezeichnete zuerst einen Damm oder Deich; daraus wurde „hindern, im Weg stehen“.","s":2,"p":[["阝","Hügel, Wall","b"],["章","Abschnitt","l"]],"i":"s"},
"従":{"t":"laut","x":"Die alte Form 從 bestand aus 辵 (gehen) und 从 (zwei Menschen hintereinander), das zuerst selbst „folgen“ schrieb; die Gehen-Form kam später dazu. 従 ist die in der Tang-Zeit belegte Kurzform, die Japan 1946 übernahm.","s":2,"p":[["彳","gehen","b"],["从","folgen","l"]],"a":"從","i":"bs"},
"我":{"t":"leih","x":"Ursprünglich das Bild einer Waffe oder eines Geräts mit mehreren gezackten Klingen, ähnlich dem Zeichen 戈 (Hellebarde). Schon auf Orakelknochen wurde es wegen des Klangs für das Wort „ich“ ausgeliehen.","s":2,"n":"Oft liest man „eine Hand hält eine Waffe, um sich selbst zu schützen“. Das ist eine spätere Volksdeutung; ursprünglich zeigt das Zeichen nur die Waffe.","i":"obs"},
"激":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 敫 als Klangteil. Gemeint war zuerst Wasser, das heftig aufspritzt; daraus wurde allgemein „heftig, stark“.","s":2,"p":[["氵","Wasser","b"],["敫","Klangteil","l"]]},
"励":{"t":"laut","x":"Die alte Form 勵 besteht aus 力 (Kraft) als Sinnteil und 厲 als Klangteil (レイ → 励 レイ). Das Wort bedeutete „anspornen, sich anstrengen“. Heute ist 厲 zu 厉 verkürzt.","s":2,"p":[["力","Kraft","b"],["厉","streng (Kurzform von 厲)","l"]],"a":"勵"},
"討":{"t":"laut","x":"Links 言 (sprechen) als Sinnteil, rechts 寸, das hier für den Klangteil 肘 steht. Gemeint ist „mit Worten oder Waffen gegen etwas vorgehen“.","s":2,"p":[["言","sprechen","b"],["寸","Kurzform von 肘 (Ellbogen)","l"]],"n":"Das alte Wörterbuch Shuowen deutet 寸 als Hand und das Ganze als „mit Worten zurechtrücken“. Heute sieht man in 寸 eher den Klangteil."},
"徴":{"t":"laut","x":"Die alte Form 徵 geht auf ein Zeichen für ein Messer mit zahnartigen Zacken zurück. Später kamen 彳 und 攵 dazu. Das Wort bedeutete zuerst „herbeirufen, einberufen“. Die heutige Form 徴 ist eine Variante davon.","s":1,"p":[["彳","Gehen","b"],["攵","schlagen","b"],["𭖒","gezacktes Messer","l"]],"n":"Das alte Wörterbuch Shuowen zerlegt das Zeichen anders (aus 微 und 𡈼); die heutige Forschung hält das für falsch.","a":"徵"},
"怪":{"t":"laut","x":"Links 忄 (Herz, Gefühl) als Sinnteil, rechts 圣 als Klangteil. Das Wort steht für „seltsam, unheimlich“. 圣 geht auf eine Variante von 右 zurück, deren unterer Teil sich zu 土 verändert hat.","s":2,"p":[["忄","Herz","b"],["圣","Klangteil","l"]]},
"獣":{"t":"kombi","x":"Die alte Form 獸 zeigt eine Jagdwaffe (單) und einen Hund (犬): Jagd. Das Zeichen für „jagen“ wurde dann für das Wort „wildes Tier“ ausgeliehen. In 獣 ist der linke Teil verkürzt.","s":2,"p":[["單","Jagdwaffe","b"],["犬","Hund","b"]],"a":"獸","i":"obs"},
"振":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 辰 als Klangteil (シン → 振 シン). Gemeint ist eine Handbewegung: schwingen, schütteln.","s":2,"p":[["扌","Hand","b"],["辰","Klangteil","l"]]},
"豚":{"t":"kombi","x":"Fleisch (月) plus Schwein (豕). Das Zeichen stand ursprünglich für ein fettes, wohlgenährtes Schwein und wurde dann für das Wort „Ferkel, Schwein“ ausgeliehen.","s":2,"p":[["月","Fleisch","b"],["豕","Schwein","b"]],"i":"obs"},
"独":{"t":"laut","x":"Die alte Form 獨 hat 犭 (Hund) als Sinnteil und 蜀 als Klangteil (ドク). Das Wort bedeutete „allein, einzeln“. In 独 ist 蜀 zu 虫 verkürzt.","s":2,"p":[["犭","Hund","b"],["虫","Kurzform von 蜀","l"]],"a":"獨","i":"s"},
"屈":{"t":"laut","x":"Ursprünglich eine Schreibung mit 尾 (Schwanz) und 出 als Klangteil; 尾 wurde in der Kanzleischrift zu 尸. Das Wort hieß zuerst „kurz“ und wurde dann für „sich krümmen, beugen“ ausgeliehen.","s":2,"p":[["尸","Schwanz (尾)","b"],["出","hinausgehen","l"]],"i":"bs"},
"暇":{"t":"laut","x":"Links 日 (Sonne, Zeit) als Sinnteil, rechts 叚 als Klangteil (カ → 暇 カ). Gemeint ist freie Zeit, eine Lücke im Tag: Muße, Freizeit.","s":2,"p":[["日","Sonne, Tag","b"],["叚","Klangteil","l"]],"i":"s"},
"織":{"t":"laut","x":"Links 糹 (Faden) als Sinnteil, rechts 戠 als Klangteil. Gemeint ist das Weben von Fäden zu Stoff.","s":2,"p":[["糹","Seide, Faden","b"],["戠","Klangteil","l"]],"i":"os"},
"惑":{"t":"laut","x":"Oben 或 als Klangteil (ワク → 惑 ワク), unten 心 (Herz) als Sinnteil. Gemeint ist ein verwirrtes Herz: sich verirren, schwanken.","s":2,"p":[["或","Klangteil","l"],["心","Herz","b"]]},
"誘":{"t":"laut","x":"Links 言 (sprechen) als Sinnteil, rechts 秀 als Klangteil. Gemeint ist „mit Worten locken, einladen“.","s":2,"p":[["言","sprechen","b"],["秀","hervorragend","l"]],"i":"s"},
"就":{"t":"kombi","x":"Auf Orakelknochen und Bronzen steht ein Ahnentempel (亯) über einem hohen Gebäude (京): „hoch“. Später kam 尤 hinzu, warum, ist unklar. Heute bedeutet das Zeichen „herangehen, antreten, sich einer Sache zuwenden“.","s":1,"p":[["京","hohes Gebäude","b"],["尤","besonders","f"]],"n":"Das alte Wörterbuch Shuowen erklärt das Zeichen als 京 + 尤. Das beschreibt nur die späte Form; die frühen Schriftformen zeigen den Tempelteil.","i":"obs"},
"睡":{"t":"laut","x":"Links 目 (Auge) als Sinnteil, rechts 垂 als Klangteil. Gemeint ist „schlafen“: die Augen schließen sich.","s":2,"p":[["目","Auge","b"],["垂","herabhängen","l"]],"i":"s"},
"症":{"t":"laut","x":"Innen 疒 (Krankheit) als Sinnteil, 正 als Klangteil (ショウ → 症 ショウ). Das Zeichen steht für Krankheitszeichen und Symptome.","s":2,"p":[["疒","Krankheit","b"],["正","richtig","l"]]},
"締":{"t":"laut","x":"Links 糹 (Faden) als Sinnteil, rechts 帝 als Klangteil (テイ → 締 テイ). Gemeint ist „mit Fäden fest verknoten, zuschnüren“.","s":2,"p":[["糹","Faden","b"],["帝","Kaiser","l"]]},
"迫":{"t":"laut","x":"Links 辶 (gehen) als Sinnteil, rechts 白 als Klangteil (ハク → 迫 ハク). Das Wort heißt „bedrängen, näherrücken, sich nähern“.","s":2,"p":[["辶","gehen","b"],["白","weiß","l"]]},
"端":{"t":"laut","x":"Links 立 (aufrecht stehen) als Sinnteil, rechts 耑 als Klangteil. Das Wort bedeutete „gerade, richtig“ und wurde dann für „Ende, Rand“ gebraucht.","s":1,"p":[["立","stehen","b"],["耑","Klangteil","l"]],"i":"s"},
"健":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 建 als Klangteil (ケン → 健 ケン). Gemeint ist ein Mensch, der kräftig und gesund ist.","s":2,"p":[["亻","Mensch","b"],["建","bauen","l"]],"i":"s"},
"康":{"t":"leih","x":"Das Zeichen ist eine Variante von 庚, einem Gerät oder Instrument, mit kleinen Punkten. Es wurde später für das Wort „ruhig, friedlich“ ausgeliehen; daraus kommt „gesund“ in 健康.","s":0,"p":[["庚","Gerät","b"]],"n":"Oft liest man, dass unten 米 (Reis) steht. Eine Quelle sieht tatsächlich Reis und Spreu, eine andere nennt das ein Missverständnis. Sicher ist nur: Das Zeichen ist keine Bildung für „friedlich“.","i":"bs"},
"郎":{"t":"laut","x":"Links 良 als Klangteil, rechts 阝 (die Form von 邑, Stadt) als Sinnteil. Mehr ist über den Aufbau nicht bekannt. Heute steht das Zeichen für „junger Mann“, zum Beispiel in Männernamen.","s":1,"p":[["良","gut","l"],["阝","Stadt","b"]],"i":"s"},
"稚":{"t":"laut","x":"Die Urform ist 穉 mit 禾 (Getreide) als Sinnteil und 屖 als Klangteil. Schon in der Han-Zeit wurde 屖 meist durch 隹 ersetzt. Gemeint sind junge, zarte Pflanzen; daraus „kindlich, unreif“.","s":1,"p":[["禾","Getreide","b"],["隹","Vogel (steht für 屖)","f"]]},
"博":{"t":"laut","x":"Links 十, die frühe Form von 盾 (Schild), rechts 尃 als Klangteil. Das Zeichen schrieb zuerst „schlagen“ und wurde dann für „weit, ausgebreitet“ ausgeliehen, wie in 博士.","s":2,"p":[["十","Schild (alte Form)","b"],["尃","Klangteil","l"]],"n":"Das alte Wörterbuch Shuowen sieht darin die Zahl 十 („zehn“). Die Bronzeschrift zeigt, dass das nicht stimmt.","i":"s"},
"潔":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 絜 als Klangteil (ケツ → 潔 ケツ). Gemeint ist sauberes, klares Wasser; daraus „rein, rechtschaffen“.","s":2,"p":[["氵","Wasser","b"],["絜","Klangteil","l"]],"n":"Oft liest man, 絜 zeige einen Faden, der mit einem Messer eingeritzt wird, um sich zu reinigen. Das gilt als widerlegt."},
"隊":{"t":"laut","x":"Links 阝 (Hügel) als Sinnteil, rechts 㒸 als Klangteil. Ursprünglich schrieb das Zeichen das Wort „fallen, abstürzen“. Es wurde dann für „Truppe, Gruppe“ ausgeliehen; für „fallen“ entstand 墜.","s":2,"p":[["阝","Hügel","b"],["㒸","Klangteil","l"]]},
"修":{"t":"laut","x":"Rechts oben 彡 (Striche für Verzierung, Muster) als Sinnteil, 攸 als Klangteil. Das Wort bedeutete „schmücken, herrichten“. Daraus wurde „in Ordnung bringen, sich bilden“, wie in 修理 und 修行.","s":2,"p":[["攸","Klangteil","l"],["彡","Verzierung, Muster","b"]],"i":"s"},
"奇":{"t":"laut","x":"Oben 大 (ein stehender Mensch) als Sinnteil, unten 可 als Klangteil. Das Zeichen schrieb zuerst das Wort „stehen, sich stützen“ und wurde dann für „seltsam, ungewöhnlich“ ausgeliehen.","s":2,"p":[["大","stehender Mensch","b"],["可","möglich","l"]]},
"妙":{"t":"laut","x":"Links 女 (Frau) als Sinnteil, rechts 少 als Klangteil. Das Wort bedeutete „schön, anmutig“; daraus wurde „fein, wunderbar“.","s":2,"p":[["女","Frau","b"],["少","wenig","l"]]},
"麗":{"t":"bild","x":"Ein Hirsch mit betont großem Geweih. Das Bild stand für das Wort „prächtig, schön“. Oben sind die Geweihstangen, unten der Hirsch (鹿).","s":2,"i":"obs"},
"微":{"t":"laut","x":"Links 彳 (Gehen, Handlung). Rechts steht ein Zeichen, das auf Orakelknochen einen Menschen mit langen Haaren und eine Hand mit Werkzeug zeigt, wohl „Haare entwirren“. So entstand die Vorstellung „winzig, fein“.","s":1,"p":[["彳","Gehen","b"],["𢼸","Klangteil","l"]],"n":"Eine Quelle sieht in 𢼸 nur den Klangteil, die andere eine Bedeutungsbildung (Haare teilen, daher fein).","i":"s"},
"益":{"t":"kombi","x":"Wasser (oben, liegend geschrieben) über einem Gefäß (皿): das Wasser steigt und läuft über. Das ist die Urform von 溢 („überfließen“). Daraus wurde „zunehmen“ und „Nutzen, Gewinn“.","s":2,"p":[["氺","Wasser","b"],["皿","Gefäß","b"]],"i":"ob"},
"憲":{"t":"laut","x":"Oben 𡩜 als Klangteil, unten 心 (Herz) als Sinnteil. Das Zeichen bedeutet „Gesetz, Regel“, wie in 憲法 (Verfassung).","s":1,"p":[["𡩜","Klangteil","l"],["心","Herz","b"]],"n":"Frühere Wörterbücher sahen in 𡩜 zugleich einen Bedeutungsträger. Diese Deutung gilt als überholt."},
"衆":{"t":"kombi","x":"Auf Orakelknochen steht eine Menschengruppe (㐺) unter der Sonne (日): viele Menschen bei der Arbeit oder im Freien. Daraus entstand „Menge, Volk“.","s":1,"p":[["日","Sonne","b"],["㐺","mehrere Menschen","b"]],"n":"Oft liest man, oben stehe ein Auge (目) oder Blut (血). Laut den frühen Schriftformen stimmt das nicht."},
"傘":{"t":"bild","x":"Das Bild eines Schirms mit Dach und Gestell. Es stand von Anfang an für den Regen- oder Sonnenschirm.","s":2},
"浜":{"t":"laut","x":"Die alte Form 濱 hat 氵 (Wasser) und 賓 als Klangteil. In 浜 ist 賓 durch das einfachere 兵 ersetzt. Gemeint ist das Ufer am Wasser: Strand, Küste.","s":1,"p":[["氵","Wasser","b"],["兵","Soldat","l"]],"n":"Ein anderes Wort 浜 mit Klangteil 兵 bezeichnete früher einen kleinen Kanal. Beide Zeichen fielen später zusammen.","a":"濱"},
"撃":{"t":"laut","x":"Die alte Form 擊 hat 手 (Hand) als Sinnteil und 毄 als Klangteil, der auch „anstoßen, schlagen“ bedeutet. Gemeint ist „schlagen, angreifen“. In 撃 ist der obere Teil verkürzt.","s":2,"p":[["手","Hand","b"],["毄","schlagen","l"]],"a":"擊","i":"s"},
"攻":{"t":"laut","x":"Rechts 攵 (eine Hand mit Werkzeug oder Waffe) als Sinnteil, links 工 als Klangteil (コウ → 攻 コウ). Gemeint ist „angreifen, bearbeiten“.","s":2,"p":[["工","Arbeit","l"],["攵","Hand mit Werkzeug","b"]]},
"監":{"t":"kombi","x":"Ein Mensch mit betontem Auge beugt sich über ein Gefäß voll Wasser und sieht hinein, wie in einen Spiegel. Das Zeichen schrieb zuerst „sich im Wasser betrachten“ (heute 鑑). Daraus wurde „beaufsichtigen“.","s":2,"p":[["臣","betontes Auge","b"],["皿","Gefäß","b"]],"i":"obs"},
"催":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 崔 als Klangteil (サイ → 催 サイ). Das Zeichen bedeutet „antreiben, veranlassen“, so auch in 開催 „abhalten“.","s":1,"p":[["亻","Mensch","b"],["崔","Klangteil","l"]]},
"促":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 足 als Klangteil (ソク → 促 ソク). Das Wort heißt „bedrängen, antreiben, zur Eile drängen“.","s":2,"p":[["亻","Mensch","b"],["足","Fuß","l"]]},
"江":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 工 als Klangteil (コウ → 江 コウ). Das Zeichen war der Name des großen Flusses, besonders des Jangtse, und steht heute für „Bucht, Flussarm“.","s":2,"p":[["氵","Wasser","b"],["工","Arbeit","l"]]},
"請":{"t":"laut","x":"Links 言 (sprechen) als Sinnteil, rechts 青 als Klangteil (セイ → 請 セイ). Gemeint ist „mit Worten um etwas bitten“.","s":2,"p":[["言","sprechen","b"],["青","blau, grün","l"]],"i":"s"},
"雄":{"t":"laut","x":"Rechts 隹 (Vogel) als Sinnteil, links 厷 als Klangteil. Das Wort bezeichnete das männliche Tier und wurde dann auch für „Held, kraftvoll“ gebraucht.","s":2,"p":[["厷","Klangteil","l"],["隹","Vogel","b"]]},
"壊":{"t":"laut","x":"Die alte Form 壞 hat 土 (Erde) als Sinnteil und 褱 als Klangteil (カイ → 壊 カイ). Gemeint ist „zerfallen, einstürzen“: Verfallenes wird wieder zu Erde. In 壊 ist der Klangteil vereinfacht.","s":2,"p":[["土","Erde","b"],["褱","Klangteil","l"]],"a":"壞","i":"s"},
"診":{"t":"laut","x":"Links 言 (sprechen, fragen) als Sinnteil, rechts 㐱 als Klangteil (シン → 診 シン). Heute bedeutet das Zeichen „untersuchen, Patienten diagnostizieren“.","s":1,"p":[["言","sprechen","b"],["㐱","Klangteil","l"]]},
"閣":{"t":"laut","x":"Außen 門 (Tor) als Sinnteil, innen 各 als Klangteil (カク → 閣 カク). Das Zeichen bezeichnet ein hohes Gebäude, einen Turm; später auch „Kabinett“.","s":2,"p":[["門","Tor","b"],["各","jeder","l"]],"i":"s"},
"僚":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 尞 als Klangteil (リョウ → 僚 リョウ). Das Wort bezeichnete den Beamten; heute: „Kollege, Gefährte“.","s":2,"p":[["亻","Mensch","b"],["尞","Klangteil","l"]]},
"督":{"t":"laut","x":"Unten 目 (Auge) als Sinnteil, oben 叔 als Klangteil. Gemeint ist „mit den Augen überwachen, beaufsichtigen“.","s":2,"p":[["叔","Klangteil","l"],["目","Auge","b"]],"i":"os"},
"街":{"t":"laut","x":"Außen 行, ein Bild für eine Kreuzung, innen 圭 als Klangteil. Das Wort bedeutete „große Straße“; daraus „Straße, Stadtviertel, Stadt“.","s":2,"p":[["行","Kreuzung","b"],["圭","Klangteil","l"]],"n":"Das 圭 sieht aus wie zwei 土 (Erde). Ursprünglich zeigt es aber zeremonielle Beile und hat mit Erde nichts zu tun."},
"宗":{"t":"kombi","x":"Ein Haus (宀) mit einer Ahnentafel oder einem Altar (示) darin: der Ahnentempel. Daraus wurde „Ahnen, Stammlinie“ und schließlich „Religion, Glaubensrichtung“.","s":2,"p":[["宀","Dach, Haus","b"],["示","Ahnentafel, Altar","b"]],"i":"obs"},
"緊":{"t":"laut","x":"Oben 臤 als Klangteil, unten 糸 (Faden) als Sinnteil. Gemeint ist ein straff gespannter Faden: fest, eng, gespannt.","s":2,"p":[["臤","Klangteil","l"],["糸","Faden","b"]],"i":"s"},
"宴":{"t":"laut","x":"Oben 宀 (Haus) als Sinnteil, unten 妟 als Klangteil (エン → 宴 エン). Gemeint ist ein Fest im Haus: Bankett, Gelage.","s":2,"p":[["宀","Dach, Haus","b"],["妟","Klangteil","l"]]},
"添":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 忝 als Klangteil (テン → 添 テン). Gemeint ist „Wasser dazugießen, hinzufügen“; daraus „beilegen, begleiten“.","s":2,"p":[["氵","Wasser","b"],["忝","Klangteil","l"]]},
"猛":{"t":"laut","x":"Links 犭 (Tier) als Sinnteil, rechts 孟 als Klangteil (モウ → 猛 モウ). Gemeint ist ein wildes, heftiges Tier; daraus „grimmig, stark“.","s":2,"p":[["犭","Hund, Tier","b"],["孟","Klangteil","l"]]},
"烈":{"t":"laut","x":"Unten 灬 (Feuer) als Sinnteil, links oben 列 als Klangteil (レツ → 烈 レツ). Gemeint ist lodernde Hitze; daraus „heftig, leidenschaftlich“.","s":2,"p":[["列","Reihe","l"],["灬","Feuer","b"]],"i":"s"},
"索":{"t":"kombi","x":"Das Zeichen hat mit Fasern und Seilen zu tun: Es zeigt, wie Fäden zu einem Seil gedreht werden. Das Wort hieß zuerst „drehen, Seil“ und wurde dann für „suchen“ ausgeliehen.","s":1,"p":[["糸","Faden","b"]],"n":"Eine Quelle deutet den oberen Teil als abgestreifte Hanffasern, die andere als verdrehte Fadenbündel. Beide sehen Fasern und Seil.","i":"s"},
"詳":{"t":"laut","x":"Links 言 (sprechen) als Sinnteil, rechts 羊 als Klangteil. Gemeint ist „genau erzählen, ausführlich erklären“.","s":2,"p":[["言","sprechen","b"],["羊","Schaf","l"]]},
"魅":{"t":"laut","x":"Links 鬼 (Geist, Dämon) als Sinnteil, rechts 未 als Klangteil (ミ → 魅 ミ). Das Zeichen steht für einen Geist, der Menschen verzaubert; daraus „bezaubern, Reiz“.","s":2,"p":[["鬼","Geist","b"],["未","noch nicht","l"]],"i":"s"},
"渇":{"t":"laut","x":"Die alte Form 渴 hat 氵 (Wasser) als Sinnteil und 曷 als Klangteil (カツ → 渇 カツ). Gemeint ist: kein Wasser mehr, trocken, durstig. In 渇 ist der Klangteil verkürzt.","s":2,"p":[["氵","Wasser","b"],["曷","Klangteil","l"]],"a":"渴","i":"s"},
"系":{"t":"kurz","x":"Kurzform von 係. Dessen Urform zeigt eine Person mit gefesseltem Oberkörper; später wurde Person und Faden getrennt geschrieben. 系 behielt nur den Fadenteil. Der Faden verbindet: Linie, Zusammenhang.","s":1,"p":[["糸","Faden","b"]],"n":"Eine andere Deutung liest 系 als Hand (手) mit einem Faden (糸).","i":"obs"},
"旗":{"t":"laut","x":"Links 㫃 (eine wehende Fahne) als Sinnteil, rechts 其 als Klangteil (キ → 旗 キ). Das Zeichen bedeutet „Fahne, Banner“.","s":2,"p":[["㫃","Fahne","b"],["其","Klangteil","l"]],"i":"s"},
"乏":{"t":"zeichen","x":"Das Zeichen scheint aus 正 abgewandelt zu sein, indem der obere Teil schräg gestellt wurde. Es steht für „Mangel, knapp sein“.","s":1,"p":[["正","richtig (verändert)","f"]],"n":"Das alte Wörterbuch Shuowen erklärt es als gespiegeltes 正; das gilt als falsch. Eine andere Deutung führt es auf ein Zeichen mit zwei 止 zurück."},
"覧":{"t":"laut","x":"Die alte Form 覽 hat 見 (sehen) als Sinnteil und 監 als Klangteil. Gemeint ist „anschauen, überblicken“. In 覧 ist der Klangteil oben verkürzt.","s":2,"p":[["監","betrachten","l"],["見","sehen","b"]],"a":"覽","i":"s"},
"懐":{"t":"laut","x":"Die alte Form 懷 hat 忄 (Herz) als Sinnteil und 褱 als Klangteil (カイ → 懐 カイ). Gemeint ist „im Herzen tragen, sich sehnen, vermissen“. In 懐 ist der Klangteil verkürzt.","s":2,"p":[["忄","Herz","b"],["褱","Klangteil","l"]],"a":"懷","i":"bs"},
"漏":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 屚 als Klangteil, das selbst schon „lecken“ bedeutet. Gemeint ist „durchsickern, entweichen“.","s":2,"p":[["氵","Wasser","b"],["屚","lecken","l"]],"i":"s"},
"購":{"t":"laut","x":"Das Muschelzeichen 貝 (früher Geld) gibt den Sinnbereich „Kauf, Geld“, 冓 liefert den Klang: コウ → 購 コウ. Das Wort bedeutete ursprünglich „etwas einlösen, abgelten“ (あがなう) und wurde zu „kaufen“.","s":2,"p":[["貝","Muschel, Geld","b"],["冓","Klang コウ","l"]]},
"飾":{"t":"laut","x":"Das Tuch 巾 steht für Stoff und Schmuck, der Klangteil 飤 (heute oft als 飠 geschrieben) liefert den Klang ショク. Gemeint ist „schmücken, verzieren“ (かざる).","s":2,"p":[["飠","Speise","l"],["巾","Tuch","b"]],"n":"Früher las man das Zeichen als Sinnverbindung oder als „Besen fegt Gegenstände vom Sockel“. Die Forschung hält beides für falsch."},
"騒":{"t":"laut","x":"Alte Form 騷: Pferd 馬 als Sinnteil, 蚤 als Klangteil (ソウ). Ursprünglich „ein Pferd streicheln“; „lärmen, Aufruhr“ ist später ausgeliehen. Die heutige Form 騒 vereinfacht den Klangteil.","s":2,"p":[["馬","Pferd","b"],["蚤","Klang ソウ","l"]],"n":"Eine ältere Deutung als Sinnverbindung gilt als haltlos.","a":"騷","i":"s"},
"撮":{"t":"laut","x":"Die Hand 扌 zeigt eine Tätigkeit mit den Fingern, 最 gibt den Klang (サイ → サツ). Ursprünglich „mit den Fingern greifen, zupfen“ (つまむ); heute auch „(ein Foto) machen“.","s":2,"p":[["扌","Hand","b"],["最","Klang サイ","l"]],"i":"s"},
"離":{"t":"laut","x":"Der Vogel 隹 steht für den Sinnbereich, 离 für den Klang (リ). Ursprünglich ein Vogel, wohl der Schwarznacken-Pirol. „Sich trennen, entfernen“ ist eine Ausleihe des gleich klingenden Wortes.","s":2,"p":[["隹","Vogel","b"],["离","Klang リ","l"]],"n":"Oft wird das Zeichen als Sinnverbindung erklärt. Der Lautbefund spricht dagegen: Es ist ein Laut-Zeichen.","i":"s"},
"融":{"t":"laut","x":"Der Klangteil ist 虫 (alt: 蟲), daneben steht 鬲, das sonst „Kessel“ bedeutet. Die ursprüngliche Bedeutung des Zeichens ist unbekannt; „schmelzen, verschmelzen“ ist eine Ausleihe.","s":1,"p":[["鬲","Kessel","b"],["虫","Insekt, Schlange","l"]],"n":"Ob 鬲 hier wirklich einen Kessel meint, ist umstritten: Es kann auch ein anderes, ähnliches Bauteil sein, das mit Kessel nichts zu tun hat.","i":"s"},
"華":{"t":"bild","x":"Ältere Formen zeigen oben die Blüten einer Pflanze und unten Stängel und Blätter: eine blühende Pflanze. Das ist die ursprüngliche Schreibung von 花 „Blume“. Später kam das Pflanzenzeichen 艹 dazu; „prächtig, glanzvoll“ ist eine Erweiterung.","s":1,"p":[["艹","Pflanze","b"]],"n":"Einige Quellen sehen das Zeichen als Laut-Zeichen, bei dem 于 den Klang angibt und die Pflanze der Sinnteil ist.","i":"bs"},
"既":{"t":"kombi","x":"Links die Schale mit gekochtem Reis (皀), rechts ein Mensch, der den Kopf abwendet (旡): Er hat aufgegessen. Das Zeichen bedeutete „aufessen“ und wurde zu „schon, bereits“ ausgeliehen.","s":1,"p":[["皀","Reisschale","b"],["旡","sich abwendender Mensch","b"]],"n":"Eine Quelle sieht 旡 stattdessen als Klangteil.","i":"ob"},
"豪":{"t":"laut","x":"Das Schwein 豕 gibt den Sinnbereich, 高 (コウ → 豪 ゴウ) den Klang; oben ist 高 verkürzt. Ursprünglich das Wort für das Stachelschwein, später zu „stark, großartig“ ausgeliehen.","s":2,"p":[["高","hoch","l"],["豕","Schwein","b"]],"i":"s"},
"鑑":{"t":"laut","x":"Metall 金 als Sinnteil, 監 als Klangteil (カン). Das Wort „kritisch betrachten, sich an einem Vorbild messen“ (かんがみる) wurde zuerst nur mit 監 geschrieben; 金 kam später dazu.","s":2,"p":[["金","Metall","b"],["監","Klang カン","l"]]},
"尋":{"t":"kombi","x":"Die frühe Form zeigt zwei ausgestreckte Arme, die etwas ausmessen: die Armspanne als Längenmaß. Später kam eine weitere Hand 寸 dazu. Daraus „messen“ und weiter „suchen, nachfragen“.","s":2,"p":[["彐","Hand","b"],["寸","Hand","b"],["工","Rest","f"],["口","Rest","f"]],"n":"Oft liest man 工 und 口 als „links“ und „rechts“ (左, 右). Das ist falsch: Sie sind verformte Reste von Hand und Boot.","i":"os"},
"廊":{"t":"laut","x":"Das Dach 广 steht für ein Gebäude, 郎 gibt den Klang (ロウ → 廊 ロウ). Gemeint ist ein Gang oder eine Halle am Gebäude.","s":1,"p":[["广","Gebäude","b"],["郎","Klang ロウ","l"]],"i":"s"},
"驚":{"t":"laut","x":"Das Pferd 馬 gibt den Sinnbereich: Pferde erschrecken leicht. 敬 liefert den Klang (ケイ → 驚 キョウ). Daraus „erschrecken, staunen“.","s":2,"p":[["敬","Klang ケイ","l"],["馬","Pferd","b"]],"i":"s"},
"嘆":{"t":"laut","x":"Der Mund 口 steht für das Seufzen und Klagen, 歎 gibt den Klang (タン). Das Zeichen drückt das Aufseufzen vor Kummer aus; die heutige Form ist eine leicht abgewandelte Schreibung des Klangteils.","s":2,"p":[["口","Mund","b"],["歎","Klang タン","l"]],"i":"s"},
"倉":{"t":"bild","x":"Frühe Formen zeigen einen Getreidespeicher: oben das Dach, darunter eine Tür und eine Grube zum Lagern von Getreide. Daraus „Lager, Speicher“.","s":1,"p":[["亼","Dach","b"],["戸","Tür","b"],["口","Grube","b"]],"n":"Die Tür veränderte sich später zu einer anderen Form; dadurch wurde das Zeichen in der Antike mit 食 verwechselt.","i":"obs"},
"巣":{"t":"bild","x":"Die alte Form 巢 zeigt ein Vogelnest auf einem Baum: oben der Jungvogel, darunter das Nest und der Baum. Heute sind Nest und Baum im Teil 果 zusammengeflossen.","s":2,"p":[["巛","Jungvogel","b"],["田","Nest","b"],["木","Baum","b"]],"a":"巢","i":"s"},
"径":{"t":"laut","x":"Alte Form 徑: der Weg 彳 als Sinnteil, 巠 als Klangteil (ケイ). Gemeint ist ein Pfad. Heute ist 巠 zu 圣 verkürzt.","s":2,"p":[["彳","Weg","b"],["圣","Klang ケイ","l"]],"a":"徑"},
"救":{"t":"laut","x":"Der Teil 攵 steht für eine Handlung, 求 gibt den Klang (キュウ). Daraus „retten, helfen“.","s":2,"p":[["求","Klang キュウ","l"],["攵","Handlung","b"]],"i":"s"},
"脈":{"t":"laut","x":"月 steht hier für „Fleisch, Körper“, der Rest 𠂢 für den Klang. Ursprünglich „Ader, Faser“, daraus „Puls, Zusammenhang“.","s":2,"p":[["月","Fleisch","b"],["𠂢","Klangteil","l"]],"n":"Eine Deutung als Sinnverbindung aus Fleisch und 永 gilt als falsch."},
"墓":{"t":"laut","x":"Die Erde 土 gibt den Sinnbereich, 莫 den Klang (ボ). Gemeint ist ein Grab.","s":2,"p":[["莫","Klang ボ","l"],["土","Erde","b"]],"i":"s"},
"徳":{"t":"laut","x":"Alte Form 德: 彳 (gehen) und 心 (Herz) als Sinnteile, 直 als Klangteil. Zuerst die Tugend der frühen Könige, die man sich zum Vorbild nahm. Heute fehlt in 徳 der Querstrich unter 十.","s":2,"p":[["彳","Gehen","b"],["直","gerade","l"],["心","Herz","b"]],"a":"德","i":"obs"},
"偵":{"t":"laut","x":"Der Mensch 亻 als Sinnteil, 貞 (テイ) gibt den Klang; es bedeutet „befragen, erkunden“. Ein Mensch, der etwas auskundschaftet.","s":2,"p":[["亻","Mensch","b"],["貞","Klang テイ","l"]],"i":"s"},
"綺":{"t":"laut","x":"Die Seide 糹 gibt den Sinnbereich Stoff, 奇 liefert den Klang (キ). Gemeint ist ein gemustertes Gewebe, daraus „schön, kunstvoll“.","s":1,"p":[["糹","Seide","b"],["奇","Klang キ","l"]]},
"序":{"t":"laut","x":"Das Gebäude 广 gibt den Sinnbereich, 予 den Klang (ヨ → ジョ). Ursprünglich ein Schulgebäude (まなびや); die Bedeutung „Reihenfolge, Vorwort“ ist ausgeliehen.","s":2,"p":[["广","Gebäude","b"],["予","Klang ヨ","l"]],"i":"s"},
"志":{"t":"laut","x":"Das Herz 心 als Sinnteil, 之 (シ) als Klangteil. Daraus „das, was das Herz anstrebt“: Wille, Vorsatz.","s":2,"p":[["士","verformtes 之","l"],["心","Herz","b"]],"n":"Der obere Teil sieht heute wie 士 aus, geht aber auf 之 zurück."},
"恩":{"t":"laut","x":"Das Herz 心 als Sinnteil, 因 (イン → オン) als Klangteil. Gemeint ist die Zuwendung und Güte eines anderen: Wohltat, Dank.","s":2,"p":[["因","Klang イン","l"],["心","Herz","b"]]},
"桜":{"t":"laut","x":"Alte Form 櫻: Baum 木 als Sinnteil, 嬰 als Klangteil (エイ → オウ). Ursprünglich ein chinesischer Kirschbaum. Heute ist 嬰 zu einem kleineren Teil verkürzt.","s":2,"p":[["木","Baum","b"],["嬰","Klang エイ","l"]],"a":"櫻"},
"眼":{"t":"laut","x":"Das Auge 目 als Sinnteil, 艮 (ゴン) als Klangteil (→ ガン). Gemeint ist das Auge, der Augapfel.","s":2,"p":[["目","Auge","b"],["艮","Klang ゴン","l"]]},
"興":{"t":"kombi","x":"Vier Hände heben gemeinsam einen Gegenstand hoch. In frühen Formen war es eine Trage oder ein Tablett, später wurde daraus 同. Daraus „aufheben, in Gang bringen, aufleben“.","s":2,"p":[["舁","vier Hände","b"],["同","Gegenstand","f"]],"n":"Das Zeichen 口 wurde später ergänzt und bringt keine eigene Bedeutung.","i":"obs"},
"衛":{"t":"kombi","x":"Alte Formen zeigen Füße, die an einem Weg um ein Gebiet herumgehen: eine Streife, die das Gelände bewacht. Daraus „schützen, bewachen“. Die Form 衞 hatte noch den Teil 帀, der heute weggefallen ist.","s":1,"p":[["行","Straße","b"],["韋","Füße um ein Gebiet","b"]],"a":"衞"},
"酸":{"t":"laut","x":"Das Gefäß 酉 gibt den Sinnbereich, 夋 den Klang (シュン → サン). Gemeint ist „sauer“.","s":2,"p":[["酉","Gefäß","b"],["夋","Klang シュン","l"]]},
"銭":{"t":"laut","x":"Alte Form 錢: Metall 金 als Sinnteil, 戔 als Klangteil (セン). Ursprünglich ein Ackerwerkzeug, später „Münze, Geld“. Heute ist 戔 vereinfacht.","s":2,"p":[["金","Metall","b"],["戔","Klang セン","l"]],"a":"錢"},
"飼":{"t":"laut","x":"Das Essen-Zeichen 飠 als Sinnteil, 司 (シ) als Klangteil. Das Wort „füttern“ wurde zuerst nur mit 食 geschrieben; 司 kam später als Klanghilfe dazu.","s":2,"p":[["飠","essen","b"],["司","Klang シ","l"]]},
"傷":{"t":"laut","x":"Der Mensch 亻 steht für den Sinnbereich, der rechte Teil gibt den Klang (ショウ). Gemeint ist „Wunde, verletzen“.","s":2,"p":[["亻","Mensch","b"],["𬀷","Klangteil","l"]]},
"厳":{"t":"laut","x":"Alte Form 嚴: 喦 als Sinnteil, 敢 als Klangteil (カン → ゲン). Zuerst „übertreiben“; „streng, würdevoll“ ist ausgeliehen. In der heutigen Form ist der obere Teil verkürzt.","s":2,"p":[["喦","laut reden","b"],["敢","Klang カン","l"]],"a":"嚴","i":"bs"},
"密":{"t":"laut","x":"Der Berg 山 gibt den Sinnbereich, 宓 den Klang (ミツ). Ursprünglich ein Berg, der wie ein Gebäude wirkt. „Dicht, heimlich“ ist ausgeliehen.","s":1,"p":[["宓","Klangteil","l"],["山","Berg","b"]]},
"暖":{"t":"laut","x":"Die Sonne 日 als Sinnteil, 爰 als Klangteil (エン → ダン). Gemeint ist „sonnig warm“, aus dem Wort 暄.","s":2,"p":[["日","Sonne","b"],["爰","Klang エン","l"]]},
"秘":{"t":"laut","x":"Alte Form 祕: 示 (Altar, Ritual) und 必 als Klangteil. Es geht um geheime Rituale, daraus „geheim“. In 秘 wurde 示 zu 禾.","s":2,"p":[["禾","aus 示","f"],["必","Klang ヒツ","l"]],"a":"祕"},
"訳":{"t":"laut","x":"Alte Form 譯: Sprache 言 als Sinnteil, 睪 als Klangteil (エキ → ヤク). Gemeint ist „erklären, übersetzen“. In 訳 steht das einfache 尺 an Stelle von 睪 (wie bei 釈).","s":2,"p":[["訁","Sprache","b"],["尺","Ersatz","f"]],"a":"譯"},
"染":{"t":"unklar","x":"Das Zeichen enthält Wasser 氵 und Baum 木 (dazu 九). Eine Deutung: Etwas hängt von einem Baum ins Wasser, um gefärbt zu werden. Die genaue Erklärung ist ungewiss.","s":0,"p":[["氵","Wasser","b"],["木","Baum","b"]],"n":"Nach einer anderen Auffassung ist es ein Laut-Zeichen mit Wasser als Sinnteil und einem Klangteil (朵).","i":"s"},
"筋":{"t":"unklar","x":"Oben Bambus, unten Fleisch 月 und ein Teil, der ursprünglich 刀 (Messer) war. Gemeint ist „Sehne, Muskel, Faser“. Ob es eine Sinnverbindung (faseriger Bambus) oder ein Laut-Zeichen ist, ist offen.","s":0,"p":[["⺮","Bambus","b"],["月","Fleisch","b"],["力","aus 刀","f"]],"i":"s"},
"垂":{"t":"laut","x":"Die Erde 土 steht für den Sinnbereich, der obere Teil zeigt herabhängende Blüten und Blätter. Das Wort bedeutete ursprünglich „Grenzland“; „herabhängen, fallen lassen“ ist ausgeliehen.","s":1,"p":[["𠂹","hängende Blüten","l"],["土","Erde","b"]],"i":"s"},
"宣":{"t":"laut","x":"Das Dach 宀 steht für ein Gebäude, 亘 gibt den Klang (セン). Ursprünglich eine große Halle des Palastes; daraus „offenbar, verkünden“.","s":2,"p":[["宀","Dach","b"],["亘","Klang セン","l"]],"i":"obs"},
"忠":{"t":"laut","x":"Das Herz 心 gibt den Sinnbereich, 中 den Klang (チュウ). Gemeint ist die Treue eines aufrichtigen Herzens.","s":2,"p":[["中","Mitte","l"],["心","Herz","b"]],"n":"Oft liest man „das Herz in der Mitte“. 中 gilt aber nur als Klangteil.","i":"s"},
"拡":{"t":"laut","x":"Alte Form 擴: Hand 扌 als Sinnteil, 廣 als Klangteil (コウ → カク). Gemeint ist „ausstrecken, erweitern“. Heute steht die Kurzform 広 darin, wie schon bei 広 selbst.","s":2,"p":[["扌","Hand","b"],["広","Klang コウ","l"]],"a":"擴"},
"操":{"t":"laut","x":"Die Hand 扌 gibt den Sinnbereich, 喿 den Klang (ソウ). Gemeint ist „in der Hand halten“, daraus „bedienen, führen“.","s":2,"p":[["扌","Hand","b"],["喿","Klang ソウ","l"]],"i":"s"},
"熟":{"t":"laut","x":"Das Feuer 灬 steht für das Garen, 孰 gibt den Klang (ジュク). Gemeint ist „gar kochen“, daraus „reif, vertraut“.","s":2,"p":[["孰","Klang ジュク","l"],["灬","Feuer","b"]]},
"異":{"t":"bild","x":"Das Zeichen zeigt eine Gestalt mit einer Maske vor dem Gesicht (oben, heute 田). Etwas Unheimliches, Fremdes, daher „anders, ungewöhnlich“.","s":2,"p":[["田","Maske","b"]],"n":"Manchmal wird es als Mensch mit Last auf dem Kopf gedeutet (戴). Das beruht auf einer Verwechslung mit einem ähnlichen Zeichen.","i":"obs"},
"皇":{"t":"laut","x":"Oben ein Federschmuck bzw. eine Krone mit Federn (heute wie 白), später kam 王 als Klangteil dazu. „Kaiser“ ist eine Ausleihe.","s":1,"p":[["白","Federkrone","b"],["王","König","l"]],"n":"Eine zweite Deutung sieht einen Kerzenständer mit Kerze: das Zeichen stünde dann für „leuchten“.","i":"obs"},
"盛":{"t":"laut","x":"Die Schale 皿 gibt den Sinnbereich, 成 den Klang (セイ). Ursprünglich „in eine Schale füllen, anrichten“ (もる), später „blühend, reich“.","s":2,"p":[["成","Klang セイ","l"],["皿","Schale","b"]],"i":"bs"},
"漠":{"t":"laut","x":"Das Wasser 氵 gibt den Sinnbereich, 莫 den Klang (バク). Das Zeichen steht für „weit, vage“, auch für die Wüste.","s":1,"p":[["氵","Wasser","b"],["莫","Klang バク","l"]],"i":"s"},
"糖":{"t":"laut","x":"Das Reiszeichen 米 gibt den Sinnbereich, 唐 den Klang (トウ). Gemeint ist „Zucker“.","s":1,"p":[["米","Reis","b"],["唐","Klang トウ","l"]],"i":"s"},
"納":{"t":"laut","x":"Die Seide 糹 gibt den Sinnbereich, 内 den Klang (ナイ → ノウ). Ursprünglich der Zügel eines Gespanns; „einziehen, abliefern“ ist ausgeliehen.","s":2,"p":[["糹","Seide","b"],["内","Klang ナイ","l"]]},
"肺":{"t":"laut","x":"月 steht hier für Fleisch und Körperorgane, der rechte Teil gibt den Klang (ハイ). Gemeint ist die Lunge.","s":2,"p":[["月","Fleisch","b"],["巿","Klangteil","l"]],"n":"In der japanischen Form sieht der Klangteil wie 市 aus, ist aber 巿."},
"賃":{"t":"laut","x":"Das Geldzeichen 貝 gibt den Sinnbereich, 任 den Klang (ニン → チン). Gemeint ist Lohn bzw. Miete: Geld für eine Arbeit.","s":2,"p":[["任","Klang ニン","l"],["貝","Muschel, Geld","b"]]},
"貴":{"t":"laut","x":"Das Geldzeichen 貝 steht für Wert, oben der Klangteil (キ), ein altes Zeichen für „Korb“. Gemeint ist „kostbar, teuer“.","s":2,"p":[["臾","Klangteil","l"],["貝","Muschel, Geld","b"]],"n":"Die klassische Deutung 貝 + 臾 als Sinnteile gilt nach den frühen Bronzeformen als falsch.","i":"s"},
"吐":{"t":"laut","x":"Der Mund 口 gibt den Sinnbereich, 土 den Klang (ト). Gemeint ist „ausspucken, erbrechen“.","s":2,"p":[["口","Mund","b"],["土","Klang ト","l"]]},
"奴":{"t":"kombi","x":"Eine Hand 又 greift nach einer Frau 女: jemand wird festgehalten. Daraus „Sklave, Diener“. Ursprünglich hieß es „greifen, packen“, später wurde das Zeichen für „Diener“ ausgeliehen.","s":1,"p":[["女","Frau","b"],["又","Hand","b"]],"n":"Nach einer anderen Sicht ist 女 zugleich der Klangteil, und das Ganze ein Laut-Zeichen.","i":"obs"},
"隷":{"t":"unklar","x":"Die alte Form 隸 besteht aus 柰 und 隶. „Untergeben, Diener“ ist wohl eine Ausleihe. Wie das Zeichen genau aufgebaut ist, ist umstritten.","s":0,"p":[["隶","ergreifen","b"]],"n":"Eine alte Erklärung (隶 plus 柰 als Klangteil) passt lautlich nicht.","a":"隸","i":"s"},
"芋":{"t":"laut","x":"Die Pflanze 艹 gibt den Sinnbereich, 于 den Klang (ウ). Gemeint ist Taro, die Knollenpflanze.","s":2,"p":[["艹","Pflanze","b"],["于","Klang ウ","l"]]},
"縮":{"t":"laut","x":"Der Faden 糹 gibt den Sinnbereich, 宿 den Klang (シュク). Gemeint ist „zusammenziehen, schrumpfen“.","s":1,"p":[["糹","Faden","b"],["宿","Klang シュク","l"]]},
"縦":{"t":"laut","x":"Alte Form 縱: Faden 糹 als Sinnteil, 從 als Klangteil (ジュウ). Zuerst „loslassen, laufen lassen“, später „Länge, senkrecht“. Der Klangteil ist heute zu 従 verkürzt.","s":2,"p":[["糹","Faden","b"],["従","Klang ジュウ","l"]],"a":"縱"},
"粋":{"t":"laut","x":"Alte Form 粹: Reis 米 als Sinnteil, 卒 als Klangteil (ソツ → スイ). Heute steht die Kurzform 卆. Gemeint ist „rein, erlesen“.","s":1,"p":[["米","Reis","b"],["卆","Klang ソツ","l"]],"a":"粹","i":"s"},
"聖":{"t":"kombi","x":"Ein Mensch mit großem Ohr und einem Mund: jemand, der gut hört. Ursprünglich das Wort für „hören“; „weise Person, Heiliger“ ist ausgeliehen.","s":1,"p":[["耳","Ohr","b"],["𡈼","Mensch","b"],["口","Mund","b"]],"n":"Oft wird 呈 als Klangteil genannt. Das gilt als falsch.","i":"s"},
"磁":{"t":"laut","x":"Der Stein 石 gibt den Sinnbereich, 茲 den Klang (ジ). Gemeint ist der Magnetstein, dann „Magnet, Porzellan“.","s":2,"p":[["石","Stein","b"],["茲","Klang ジ","l"]]},
"射":{"t":"bild","x":"Frühe Formen zeigen Bogen und Pfeil, später kam eine Hand dazu, die die Sehne spannt. Daraus „schießen“. Aus Bogen und Pfeil wurde später 身, die Hand wurde 寸.","s":2,"p":[["寸","Hand","b"]],"n":"Oft liest man „Körper 身 plus Hand 寸“. Die frühen Formen zeigen, dass 身 hier nichts mit Körper zu tun hat.","i":"ob"},
"幕":{"t":"laut","x":"Das Tuch 巾 gibt den Sinnbereich, 莫 den Klang (マク). Gemeint ist ein Vorhang, ein Tuch zum Verdecken; daraus „Akt, Vorhang“.","s":2,"p":[["莫","Klang マク","l"],["巾","Tuch","b"]],"i":"s"},
"薦":{"t":"laut","x":"Das Gras 艹 gibt den Sinnbereich, 廌 ein Fabeltier. Ursprünglich eine Matte (むしろ). „Empfehlen“ ist später ausgeliehen.","s":1,"p":[["艹","Gras","b"],["廌","Fabeltier","l"]],"n":"Manche lesen es als Sinnverbindung: Tier auf der Weide.","i":"bs"},
"推":{"t":"laut","x":"Die Hand 扌 gibt den Sinnbereich, 隹 den Klang (スイ). Gemeint ist „mit der Hand schieben“, daraus „ableiten, empfehlen“.","s":2,"p":[["扌","Hand","b"],["隹","Klang スイ","l"]]},
"揮":{"t":"laut","x":"Die Hand 扌 gibt den Sinnbereich, 軍 den Klang. Gemeint ist „schwingen, schwenken“.","s":1,"p":[["扌","Hand","b"],["軍","Klang","l"]],"i":"s"},
"沿":{"t":"laut","x":"Links steht 氵 (Wasser), rechts 㕣 als Klangteil (エン → 沿 エン). Das Zeichen meinte ursprünglich den Rand eines Flusses; daraus wurde „entlang, an etwas entlang folgen“.","s":2,"p":[["氵","Wasser","b"],["㕣","Lautteil","l"]]},
"源":{"t":"laut","x":"原 stand zuerst allein für „Quelle, Ursprung“ (ゲン). Später kam 氵 (Wasser) dazu, um das Wort „Quelle eines Gewässers“ deutlicher zu machen. 原 gibt den Klang (ゲン → 源 ゲン) und die Grundbedeutung.","s":2,"p":[["氵","Wasser","b"],["原","Ursprung","l"]]},
"歓":{"t":"laut","x":"Die alte Form 歡 besteht aus 欠 als Sinnteil und 雚 als Klangteil (カン). In der heutigen Form 歓 wurde 雚 zu einem kürzeren Zeichen vereinfacht, das nur noch den Klang trägt (カン → 歓 カン).","s":2,"p":[["欠","Sinnteil","b"],["雚","Klangteil","l"]],"a":"歡"},
"豆":{"t":"leih","x":"Ursprünglich ein Bild einer Hochfußschale (たかつき), eines Gefäßes auf hohem Fuß. Später wurde das Zeichen wegen des gleichen Klangs für das Wort „Bohne“ ausgeliehen; die Schale ist die ursprüngliche Bedeutung.","s":2,"i":"obs"},
"腐":{"t":"laut","x":"肉 (Fleisch) gibt den Sinn „verderben, faulen“, 府 liefert den Klang (フ → 腐 フ).","s":2,"p":[["肉","Fleisch","b"],["府","Lager, Amt","l"]],"n":"Manchmal wird 府 auch als zusätzlicher Bedeutungsträger gedeutet; diese Analyse gilt heute als falsch, 府 ist nur der Klangteil."},
"彫":{"t":"laut","x":"彡 steht für Muster und Verzierung und gibt den Sinn: Muster in etwas einarbeiten, also schnitzen oder gravieren. 周 ist der Klangteil.","s":2,"p":[["周","Umkreis","l"],["彡","Muster","b"]]},
"舎":{"t":"laut","x":"Die alte Form 舍 war zuerst ein Zeichen für das Wort „ich“ (余); 口 kam später als bloßer Zusatz dazu. Das Zeichen wurde dann für das gleich klingende Wort „Haus, Unterkunft“ ausgeliehen. Die heutige Form 舎 ist verkürzt.","s":2,"p":[["余","ich","l"],["口","Mund","f"]],"a":"舍","i":"bs"},
"滞":{"t":"laut","x":"In der alten Form 滯 steht 氵 (Wasser) für den Sinn, 帶 für den Klang (タイ → 滯 タイ). Die heutige Form 滞 ist eine verkürzte Schreibweise des alten Zeichens.","s":2,"p":[["氵","Wasser","b"],["帯","Gürtel","l"]],"a":"滯","i":"s"},
"己":{"t":"bild","x":"Ein Bildzeichen, dessen genaue Vorlage nicht geklärt ist. Vorgeschlagen werden ein Seil zum Binden von Dingen, ein Fangseil oder ein Markierungszeichen auf Töpfen. Bedeutung „selbst“ kam später.","s":0,"n":"Verwechsle es nicht mit 已 und 巳, die ähnlich aussehen, aber andere Zeichen sind.","i":"obs"},
"厄":{"t":"leih","x":"Nach der neueren Deutung zeigt das Zeichen ein Joch, das einem Zugtier oder Wagen aufgelegt wird. Später wurde es für das gleich klingende Wort „Unglück, Unheil“ ausgeliehen.","s":1,"n":"Eine andere Deutung sieht einen knienden Menschen (卩) mit einem Strich am Knie und ein Gelenk oder einen Knoten; die Joch-Deutung gilt als besser belegt.","i":"s"},
"亀":{"t":"bild","x":"Die alte Form 龜 zeigt eine Schildkröte, abgebildet von der Seite und von oben. Die heutige Form 亀 ist eine stark vereinfachte Schreibweise davon.","s":2,"a":"龜","i":"obs"},
"剣":{"t":"laut","x":"Die alte Form 劍 besteht aus 刂 (Messer, Klinge) als Sinnteil und 僉 als Klangteil. In der heutigen Form 剣 wurde der Klangteil zu einem kürzeren Zeichen vereinfacht.","s":2,"p":[["刂","Messer","b"],["僉","alle","l"]],"a":"劍","i":"s"},
"杉":{"t":"laut","x":"木 (Baum) gibt den Sinn, 彡 den Klang (サン → 杉 サン). Das Zeichen bezeichnete einen Nadelbaum.","s":1,"p":[["木","Baum","b"],["彡","Strichmuster","l"]],"n":"Oft wird 彡 als Bild der Zweige oder Nadeln gedeutet; in der Forschung gilt es als Klangteil."},
"汁":{"t":"laut","x":"氵 (Wasser) zeigt den Sinnbereich „Flüssigkeit“. 十 ist der Klangteil (ジュウ → 汁 ジュウ), nicht die Zahl.","s":2,"p":[["氵","Wasser","b"],["十","zehn","l"]],"i":"s"},
"炎":{"t":"kombi","x":"Zweimal 火 (Feuer) übereinander: das Feuer brennt hoch und lodert. So entsteht „Flamme, Entzündung“.","s":2,"p":[["火","Feuer","b"],["火","Feuer","b"]],"i":"os"},
"為":{"t":"kombi","x":"Die alte Form 爲 zeigt eine Hand und einen Elefanten, also jemanden, der mit einem Elefanten arbeitet und ihn lenkt. Daraus wurde allgemein „tun, machen“. Die heutige Form 為 ist stark verkürzt.","s":2,"p":[["爪","Hand","b"],["象","Elefant","b"]],"n":"Das Shuowen deutete das Zeichen als Affen. Das gilt heute als überholt.","a":"爲"},
"熊":{"t":"leih","x":"Ursprünglich schrieb das Zeichen das Wort für lodernde Flammen, deshalb steht 火 (灬) unten. Der obere Teil 能 war das Tier, das später „Bär“ hieß; das Wort „Bär“ wurde dann auf dieses Zeichen übertragen.","s":1,"p":[["能","Bär","b"],["灬","Feuer","b"]],"i":"s"},
"獄":{"t":"kombi","x":"Zwei Hunde (犭 und 犬) stehen links und rechts von 言 (Wort, Rede): zwei Seiten, die sich anbellen. Das Wort bedeutete ursprünglich „Rechtsstreit, Klage“; heute ist es „Gefängnis“.","s":1,"p":[["犭","Hund","b"],["言","Wort","b"],["犬","Hund","b"]],"n":"Manchmal liest man das Bild von bellenden Wachhunden im Gefängnis. Belegt ist vor allem die Bedeutung „Klage“.","i":"bs"},
"酔":{"t":"laut","x":"In der alten Form 醉 gibt 酉 (Weingefäß, Alkohol) den Sinn. 卒 ist der Klangteil. In der heutigen Form 酔 steht dafür die Kurzform 卆.","s":2,"p":[["酉","Weingefäß","b"],["卒","Ende","l"]],"a":"醉","i":"s"},
"酢":{"t":"laut","x":"酉 (Weingefäß, Gegorenes) zeigt den Sinnbereich, 乍 liefert den Klang (サ → 酢 サク). Gemeint ist Essig, also etwas Gegorenes.","s":2,"p":[["酉","Weingefäß","b"],["乍","plötzlich","l"]],"i":"bs"},
"盟":{"t":"laut","x":"皿 (Schale) steht für die Schwurhandlung, 明 liefert den Klang (メイ → 盟 メイ). Das Zeichen hat sich in Stufen verändert: Das Teil über der Schale war früher ein anderes, wurde später durch 朙 und dann durch 明 ersetzt.","s":2,"p":[["明","hell","l"],["皿","Schale","b"]],"n":"Nach japanischer Deutung tragen 明 und 皿 beide zum Klang bei.","i":"obs"},
"遺":{"t":"laut","x":"辶 (Gehen, Bewegung) zeigt den Sinn „zurücklassen, fallen lassen“. Das rechte Teil war ursprünglich ein Bild von Sand in beiden Händen und liefert den Klang.","s":1,"p":[["辶","gehen","b"],["貴","Klangteil","l"]],"n":"Das rechte Teil ist nicht das 貴 aus 貴重 („wertvoll“), sondern ein anderes, gleich aussehendes Zeichen."},
"債":{"t":"laut","x":"亻 (Mensch) gibt den Sinn, denn es geht um Menschen, die jemandem etwas schulden. 責 liefert den Klang (セキ → 債 サイ) und passt zugleich zum Sinn.","s":2,"p":[["亻","Mensch","b"],["責","Schuld","l"]]},
"及":{"t":"kombi","x":"Eine Hand (又) greift nach einem Menschen (人) und holt ihn ein. Daraus wurde „erreichen, heranreichen“.","s":2,"p":[["人","Mensch","b"],["又","Hand","b"]],"i":"obs"},
"奈":{"t":"leih","x":"Ursprünglich ein Baum (木) über einem Altar (示), vermutlich für eine Zeremonie. 奈 und 祟 sind beide aus dieser Form entstanden. Dann wurde 奈 für das Wort „was tun?“ ausgeliehen; heute steht oben 大.","s":1,"p":[["大","Baum (Form)","f"],["示","Altar","b"]]},
"廃":{"t":"laut","x":"In der alten Form 廢 steht 广 (Haus, Dach) für den Sinn, 發 liefert den Klang (ハツ → ハイ). Die heutige Form 廃 benutzt statt 發 die vereinfachte Form 発.","s":2,"p":[["广","Haus","b"],["発","Klangteil","l"]],"n":"Früher wurde das Wort „aufgeben“ mit anderen Zeichen (灋, 法) geschrieben.","a":"廢"},
"摘":{"t":"laut","x":"扌 (Hand) gibt den Sinn „pflücken, abzupfen“, 啇 den Klang (テキ → 摘 テキ).","s":2,"p":[["扌","Hand","b"],["啇","Klangteil","l"]]},
"核":{"t":"laut","x":"木 (Baum) zeigt den Sinnbereich, 亥 den Klang. Das Zeichen bezeichnete den Kern einer Frucht; die heutigen Bedeutungen wie „Kern, Atomkern“ sind davon abgeleitet.","s":1,"p":[["木","Baum","b"],["亥","Klangteil","l"]],"n":"Eine Quelle nennt als ursprüngliche Bedeutung eine bestimmte Baumart.","i":"s"},
"沖":{"t":"laut","x":"氵 (Wasser) gibt den Sinn, 中 den Klang (チュウ → 沖 チュウ). Das Wort bedeutete ursprünglich „Wasser sprudelt hoch“; die Bedeutung „offenes Meer“ ist japanisch.","s":2,"p":[["氵","Wasser","b"],["中","Mitte","l"]],"n":"Oft liest man „die Mitte des Wassers, daher das offene Meer“. Die Forschung sieht in 中 nur den Klangteil.","i":"obs"},
"縄":{"t":"laut","x":"In der alten Form 繩 steht 糸 (Faden) für den Sinn „Seil“ und 黽 für den Klang. Die heutige Form 縄 hat den Klangteil stark vereinfacht.","s":2,"p":[["糸","Faden","b"],["黽","Klangteil","l"]],"a":"繩","i":"s"},
"津":{"t":"laut","x":"氵 (Wasser) gibt den Sinn, der rechte Teil den Klang. Dieser Teil ist laut neuer Forschung eine verkürzte Form von 盡, die sich in der Schreibschrift zu 聿 verformt hat.","s":2,"p":[["氵","Wasser","b"],["聿","Klangteil","l"]]},
"献":{"t":"laut","x":"In der alten Form 獻 bedeutet 犬 (Hund) den Sinn: Ein Hund wurde als Opfergabe dargebracht. 鬳 liefert den Klang (ゲン → 献 ケン). In der heutigen Form 献 steht dafür verkürzt 南.","s":2,"p":[["南","Klangteil","l"],["犬","Hund","b"]],"a":"獻","i":"obs"},
"継":{"t":"laut","x":"糸 (Faden) gibt den Sinn „verbinden, fortführen“. Der Klangteil ging auf ein Zeichen für zusammenhängende Fäden zurück. In der heutigen Form 継 wurde er verkürzt.","s":2,"p":[["糸","Faden","b"],["㡭","Klangteil","l"]],"n":"Der Klangteil sieht ähnlich aus wie in 断, hat aber einen ganz anderen Ursprung.","a":"繼","i":"s"},
"維":{"t":"laut","x":"糸 (Faden) gibt den Sinn „Seil, Band“, 隹 den Klang. Dass 隹 ursprünglich anders klang, sieht man noch an Verwandten wie 唯 und 惟 (beide イ).","s":2,"p":[["糸","Faden","b"],["隹","Vogel","l"]],"i":"bs"},
"伎":{"t":"laut","x":"亻 (Mensch) zeigt den Sinn: das Können einer Person, ihre Kunst. 支 liefert den Klang (シ → 伎 ギ).","s":2,"p":[["亻","Mensch","b"],["支","stützen","l"]],"i":"s"},
"踏":{"t":"laut","x":"⻊ (Fuß) gibt den Sinn „treten“, 沓 den Klang (トウ → 踏 トウ).","s":2,"p":[["⻊","Fuß","b"],["沓","Klangteil","l"]]},
"鹿":{"t":"bild","x":"Ein Bildzeichen für einen Hirsch. Die heutige Form ist stark abstrahiert: Kopf, Geweih und Beine sind zu Teilen wie 广 und 比 geworden.","s":2,"i":"obs"},
"諾":{"t":"laut","x":"言 (Wort, sprechen) gibt den Sinn: mit „ja“ antworten, zusagen. 若 liefert den Klang.","s":2,"p":[["言","Wort","b"],["若","wie","l"]],"n":"Manchmal wird 若 („so, wie“) als zusätzlicher Bedeutungsteil gedeutet. Das gilt heute als falsch.","i":"obs"},
"跳":{"t":"laut","x":"⻊ (Fuß) gibt den Sinn „springen“, 兆 den Klang (チョウ → 跳 チョウ).","s":2,"p":[["⻊","Fuß","b"],["兆","Zeichen","l"]],"i":"s"},
"昭":{"t":"laut","x":"日 (Sonne) steht für Licht und Helligkeit, 召 für den Klang (ショウ → 昭 ショウ). Das Zeichen meint „hell, leuchtend“.","s":2,"p":[["日","Sonne","b"],["召","rufen","l"]]},
"償":{"t":"laut","x":"亻 (Mensch) zeigt, dass es um Menschen geht, die etwas zurückgeben oder ausgleichen. 賞 liefert den Klang (ショウ → 償 ショウ).","s":2,"p":[["亻","Mensch","b"],["賞","Preis","l"]]},
"刑":{"t":"laut","x":"刂 (Messer) steht für die Strafe, das Zeichen hat den Sinn „bestrafen“. Der linke Teil gibt den Klang (ケイ → 刑 ケイ).","s":2,"p":[["开","Form","l"],["刂","Messer","b"]],"n":"Der Klangteil sieht aus wie 井 (Brunnen), ist aber ein anderes Zeichen, das für „Form, Modell“ (型) stand."},
"執":{"t":"bild","x":"Das Zeichen zeigt einen Menschen mit Handschellen, also jemanden, der festgenommen ist. Daraus wurde „ergreifen, festhalten“.","s":2,"p":[["幸","Handschellen","f"],["丸","Mensch","f"]],"n":"Das heutige 幸 (Glück) ist hier keine Bedeutung, sondern der Rest der Form für Handschellen.","i":"obs"},
"塁":{"t":"laut","x":"In der alten Form 壘 steht 土 (Erde) für Wälle aus Erde, 畾 liefert den Klang (ライ → 塁 ルイ). Gemeint ist eine Festung oder ein Erdwall. In der heutigen Form 塁 ist 畾 verkürzt.","s":2,"p":[["土","Erde","b"],["畾","Klangteil","l"]],"a":"壘","i":"s"},
"崩":{"t":"laut","x":"山 (Berg) gibt den Sinn: etwas Großes stürzt ein, einen Berg, der zusammenbricht. 朋 liefert den Klang (ホウ → 崩 ホウ).","s":2,"p":[["山","Berg","b"],["朋","Freund","l"]]},
"抗":{"t":"laut","x":"扌 (Hand) gibt den Sinn „sich widersetzen“, 亢 den Klang (コウ → 抗 コウ).","s":2,"p":[["扌","Hand","b"],["亢","Klangteil","l"]]},
"抵":{"t":"laut","x":"扌 (Hand) gibt den Sinn „stoßen, berühren, widerstehen“, 氐 den Klang (テイ → 抵 テイ).","s":2,"p":[["扌","Hand","b"],["氐","Klangteil","l"]]},
"旬":{"t":"laut","x":"日 (Tag) zeigt den Sinn: ein Zeitraum von zehn Tagen. Der andere Teil gibt den Klang (ジュン → 旬 ジュン). Er war ursprünglich ein anderes Zeichen und ist erst später zu 勹 geworden.","s":1,"p":[["勹","Klangteil","l"],["日","Sonne, Tag","b"]],"n":"Das Shuowen sah darin 勹 („einwickeln“) plus 日. Diese Analyse gilt heute als falsch.","i":"obs"},
"弾":{"t":"laut","x":"In der alten Form 彈 steht 弓 (Bogen) für den Sinn „schnellen, abschießen“, 單 für den Klang (タン → 彈 ダン/タン). Die heutige Form 弾 verwendet dafür 単.","s":2,"p":[["弓","Bogen","b"],["単","einfach","l"]],"a":"彈","i":"os"},
"聴":{"t":"laut","x":"Das Ohr 耳 zeigt den Sinn „hören“. Die alte Form 聽 enthielt weitere Teile, die aus einem älteren Zeichen für „hören“ stammen; heute sind sie stark verkürzt.","s":0,"p":[["耳","Ohr","b"]],"n":"Der Rest der alten Form wird unterschiedlich gedeutet: als Mund und Ohr oder als Klangteil. Die Deutung des alten Wörterbuchs Shuowen gilt hier als falsch.","a":"聽","i":"obs"},
"遣":{"t":"kombi","x":"Ursprünglich zeigte das Zeichen zwei Hände, die ein Heer (𠂤) losschicken, also „aussenden“. Später kam 辶 (Gehen) dazu, was heute noch in der Form steckt.","s":2,"p":[["辶","gehen","b"],["𠂤","Heer","b"]],"i":"s"},
"闘":{"t":"laut","x":"In der alten Form 鬪 steht 鬥 für zwei Kämpfer, die sich gegenüberstehen, und der Rest für den Klang. In der heutigen Form 闘 wurde 鬥 zu 門 vereinfacht.","s":1,"p":[["門","Tor (Form)","f"],["𭔰","Klangteil","l"]],"n":"Das Tor 門 hat hier nichts mit einem Tor zu tun, es ist nur eine verkürzte Form.","a":"鬪"},
"陣":{"t":"leih","x":"陣 entstand als Abspaltung von 陳 und wurde für das Wort „Schlachtordnung, Heerlager“ ausgeliehen. Links wurde 阜 (Hügel, heute 阝) hinzugefügt.","s":1,"p":[["阝","Hügel","f"],["車","Wagen","f"]]},
"臨":{"t":"kombi","x":"Ein Mensch blickt mit offenen Augen nach unten auf mehrere Dinge (品). Das Zeichen war zunächst ein Bild für einen Menschen, der hinabschaut. 品 kam später als Klangteil dazu. Daraus wurde „herantreten, vor sich haben“.","s":1,"p":[["臣","Auge","b"],["人","Mensch","b"],["品","Gegenstände","l"]],"n":"Eine andere Analyse sieht 臥 (sich hinlegen) plus 品 als Klangteil.","i":"s"},
"削":{"t":"laut","x":"刂 (Messer) gibt den Sinn „schneiden, schaben“, 肖 den Klang.","s":2,"p":[["肖","ähneln","l"],["刂","Messer","b"]],"i":"s"},
"契":{"t":"laut","x":"Der Klangteil 㓞 bedeutet „einkerben, einschneiden“, darunter steht 大 (Mensch). Gemeint ist ein Mensch, der etwas einkerbt oder festhält, also eine Abmachung. Daraus wurde „Vertrag, Versprechen“.","s":1,"p":[["㓞","einritzen","l"],["大","Mensch","b"]],"n":"Beide Quellen sind sich über die Rolle von 大 nicht ganz einig.","i":"obs"},
"恵":{"t":"laut","x":"In der alten Form 惠 gibt 心 (Herz) den Sinn „Güte, Rücksicht“. 叀 liefert den Klang. In der heutigen Form 恵 wurde der obere Teil verkürzt.","s":2,"p":[["心","Herz","b"],["叀","Klangteil","l"]],"a":"惠","i":"s"},
"掲":{"t":"laut","x":"In der alten Form 揭 steht 扌 (Hand) für den Sinn „hochhalten, aufhängen“, 曷 für den Klang. In der heutigen Form 掲 ist der rechte Teil durch ein anderes Zeichen ersetzt.","s":2,"p":[["扌","Hand","b"],["曷","Klangteil","l"]],"a":"揭","i":"s"},
"葬":{"t":"kombi","x":"Ein Toter (死) liegt zwischen Pflanzen (艹): Man bedeckt ihn mit Gras oder Reisig. So entsteht „begraben, bestatten“. Die zwei Hände 廾 stehen heute unten.","s":2,"p":[["艹","Gras","b"],["死","Toter","b"],["廾","Hände","f"]],"n":"Die frühesten Formen zeigen einen Menschen in einer Grube.","i":"obs"},
"需":{"t":"leih","x":"Ursprünglich ein Mensch, der im Regen nass wird (雨 über einem Menschen); das war das Wort für „nass werden“. Später wurde das Zeichen für das Wort „fordern, brauchen“ ausgeliehen. Die Menschenfigur wurde in der Han-Zeit zu 而.","s":2,"p":[["雨","Regen","b"],["而","Mensch (Form)","f"]],"n":"Manche sehen den unteren Teil als Klangteil.","i":"bs"},
"宜":{"t":"leih","x":"Ursprünglich ein Bild: Fleischstücke für ein Opfer liegen auf einer Bank oder einem Opfertisch. Später wurde das Zeichen für das gleich klingende Wort „passend, gut“ ausgeliehen.","s":2,"i":"obs"},
"繰":{"t":"laut","x":"糸 (Faden) gibt den Sinn „Garn aufspulen, abwickeln“. 喿 liefert den Klang (ソウ → 繰 ソウ).","s":2,"p":[["糸","Faden","b"],["喿","Klangteil","l"]],"i":"s"},
"避":{"t":"laut","x":"辶 (Gehen, Bewegung) gibt den Sinn „ausweichen, meiden“, 辟 den Klang.","s":2,"p":[["辶","gehen","b"],["辟","Klangteil","l"]],"i":"s"},
"妊":{"t":"laut","x":"女 (Frau) zeigt den Sinn „schwanger“, 壬 liefert den Klang (ジン → 妊 ニン/ジン).","s":2,"p":[["女","Frau","b"],["壬","Klangteil","l"]]},
"娠":{"t":"laut","x":"女 (Frau) zeigt den Sinn „schwanger sein“, 辰 liefert den Klang (シン → 娠 シン).","s":2,"p":[["女","Frau","b"],["辰","Klangteil","l"]]},
"致":{"t":"laut","x":"至 liefert den Klang und die Grundidee „ankommen, hingelangen“. Später kam ein Zusatzteil dazu, der keine eigene Bedeutung hat. Das Zeichen heißt „hinführen, bewirken“.","s":1,"p":[["至","gelangen","l"],["攵","Zusatz","f"]],"n":"Das Shuowen sah darin 至 plus 夊 („gehen“). Das gilt heute als falsch.","i":"obs"},
"奏":{"t":"kombi","x":"Zwei Hände halten einen Gegenstand, vermutlich ein Gerät für Musik oder Tanz bei einer Opferzeremonie. Daraus wurde „aufführen, musizieren“.","s":0,"p":[["廾","zwei Hände","b"]],"n":"Eine andere Deutung sieht zwei Hände, die Harz von einem angeschnittenen Baum auffangen.","i":"s"},
"伴":{"t":"laut","x":"亻 (Mensch) gibt den Sinn: jemand, der einen anderen begleitet. 半 liefert den Klang (ハン → 伴 ハン).","s":2,"p":[["亻","Mensch","b"],["半","halb","l"]],"n":"Früher wurde 半 auch als Bedeutungsteil gedeutet; das gilt als falsch."},
"併":{"t":"laut","x":"亻 (Mensch) wurde zu 并 (nebeneinanderstellen) hinzugefügt. Das Zeichen bedeutet „nebeneinander stehen, sich vereinen“. 并 liefert den Klang (ヘイ → 併 ヘイ).","s":2,"p":[["亻","Mensch","b"],["并","nebeneinander","l"]]},
"却":{"t":"laut","x":"In der alten Form 卻 gibt 卩 (kniender Mensch) den Sinn „zurückweichen“, der Rest den Klang (キャク). Die heutige Form 却 ist eine Variante, bei der das linke Teil wie 去 aussieht.","s":2,"p":[["去","Klangteil (Form)","f"],["卩","kniender Mensch","b"]],"n":"Das 去 in 却 hat nichts mit „weggehen“ (去) zu tun.","a":"卻","i":"s"},
"慮":{"t":"laut","x":"Unten das Herz als Sinnteil: Es geht um Denken und Bedenken. Oben steht ein Klangteil (Lesung リョ). Gemeint ist „sorgfältig abwägen, bedenken“.","s":2,"p":[["心","Herz","b"],["𧆨","Klangteil","l"]],"n":"Alte Wörterbücher zerlegen das Zeichen in 思 („denken“) und 虍. Die Bronzeschrift zeigt aber, dass 思 hier nicht drinsteckt."},
"懸":{"t":"laut","x":"縣 (ケン) steht für den Klang und stand zuerst selbst für das Wort „aufhängen“. Später kam 心 dazu, um dieses Wort deutlicher abzugrenzen. Heute heißt 懸 „hängen, aufhängen“ und im übertragenen Sinn „abhängen von“.","s":2,"p":[["縣","Klang","l"],["心","Herz","b"]]},
"房":{"t":"laut","x":"Eine Tür (戸) zeigt: Es geht um einen Raum. 方 gibt den Klang (ホウ → ボウ). Gemeint ist zuerst ein Zimmer; „Quaste, Büschel“ ist eine spätere Bedeutung.","s":2,"p":[["戸","Tür","b"],["方","Seite","l"]],"n":"Möglich ist, dass 方 „Seite“ auch den Sinn mitbestimmt, falls das Zeichen ursprünglich ein Nebenzimmer neben dem Hauptraum meinte.","i":"s"},
"扱":{"t":"laut","x":"Die Hand (扌) steht für das Tun mit den Händen, 及 (キュウ) für den Klang. Gemeint ist etwas mit der Hand greifen und damit umgehen. Im Japanischen: „behandeln, handhaben“.","s":2,"p":[["扌","Hand","b"],["及","erreichen","l"]]},
"抑":{"t":"kombi","x":"Die frühe Form zeigt eine Hand, die einen knienden Menschen niederdrückt: „unterdrücken, zurückhalten“. Später wurde 手 (扌) noch einmal ergänzt, um dieses Wort von 印 („Siegel“) zu trennen.","s":1,"p":[["扌","Hand","b"],["卬","Kniender","b"]],"n":"Man kann das Zeichen auch als Laut-Zeichen mit 印 als Klangteil einordnen; 印 selbst geht auf dasselbe Bild zurück.","i":"obs"},
"択":{"t":"laut","x":"Das alte Zeichen 擇 hatte die Hand (扌) als Sinnteil („auswählen“) und 睪 als Klangteil. In der heutigen Kurzform ist 睪 durch das einfache 尺 ersetzt worden.","s":1,"p":[["扌","Hand","b"],["睪","Klang","l"]],"a":"擇"},
"描":{"t":"laut","x":"Die Hand (扌) steht für das Tun mit der Hand, 苗 (ビョウ) für den Klang, der bis heute fast gleich geblieben ist. Gemeint ist „zeichnen, malen“.","s":2,"p":[["扌","Hand","b"],["苗","Setzling","l"]]},
"盤":{"t":"laut","x":"Unten die Schale (皿) als Sinnteil: eine große flache Schale. Oben 般 als Klangteil (ハン → バン). Früher stand eine andere Form für den Klang; sie wurde später verändert.","s":2,"p":[["般","Klang","l"],["皿","Schale","b"]]},
"称":{"t":"kurz","x":"Kurzform des alten Zeichens 稱. Sie entstand aus der verschliffenen Schreibweise (Kursive) von 稱 und wurde in Japan als Standardform übernommen. Das Zeichen bedeutet „nennen, bezeichnen“.","s":1,"a":"稱","i":"s"},
"緩":{"t":"laut","x":"Der Faden (糸) gibt den Sinnbereich: etwas Gespanntes, das locker wird. 爰 liefert den Klang (エン → カン). Gemeint ist „locker, schlaff, langsam“.","s":2,"p":[["糸","Faden","b"],["爰","Klang","l"]]},
"託":{"t":"laut","x":"Das Sprechen (言) gibt den Sinnbereich: etwas mündlich anvertrauen. 乇 liefert den Klang (タク), der bis heute gleich blieb. Gemeint ist „anvertrauen, übertragen“.","s":2,"p":[["言","Sprechen","b"],["乇","Klang","l"]]},
"賄":{"t":"laut","x":"Die Muschel (貝) war altes Geld, steht also für Besitz und Vermögen. 有 liefert den Klang; heute klingt 賄 (ワイ) anders als 有 (ユウ). Gemeint ist ursprünglich „Vermögen, Güter“.","s":2,"p":[["貝","Muschel/Geld","b"],["有","Klang","l"]]},
"還":{"t":"laut","x":"Das Wegzeichen (辶) steht für Gehen und Zurückkehren. 睘 liefert den Klang (カン). Gemeint ist „zurückkehren, zurückgeben“.","s":2,"p":[["辶","Weg","b"],["睘","Klang","l"]],"i":"bs"},
"邦":{"t":"laut","x":"阝 steht hier für 邑, eine Siedlung oder ein Gebiet. 丰 ist der Klangteil (ホウ). Gemeint ist „Land, Staat“.","s":2,"p":[["丰","Klang","l"],["阝","Ort/Stadt","b"]],"n":"Früher deutete man das Zeichen auch als Sinnverbindung, in der 丰 mitbedeutet. Heute gilt das als überholt.","i":"s"},
"鈴":{"t":"laut","x":"Das Metall (金) zeigt: Eine Glocke aus Metall. 令 liefert den Klang (レイ). Ein früheres Zeichen bildete die Glocke direkt ab; später kam 令 hinzu, und das Bildteil wurde durch 金 ersetzt.","s":2,"p":[["金","Metall","b"],["令","Befehl","l"]],"i":"bs"},
"岐":{"t":"laut","x":"Der Berg (山) zeigt: Es war zuerst der Name eines Berges. 支 liefert den Klang (シ ↔ キ). Später wurde das Zeichen für „Weggabelung, Verzweigung“ ausgeliehen.","s":2,"p":[["山","Berg","b"],["支","Zweig","l"]],"i":"s"},
"隆":{"t":"laut","x":"Das Zeichen bedeutet „hoch aufragen, üppig“. 降 steht für den Klang. Als Sinnteil gilt entweder 生 („wachsen“) oder 土 („Erde“); sicher ist nur der Klangteil.","s":1,"p":[["降","Klang","l"],["生","wachsen","b"]],"n":"Alte Wörterbücher erklären das Zeichen als 生 plus 降 als Sinnverbindung. Ob 生 oder 土 mitbedeutet, ist unter Fachleuten nicht eindeutig."},
"控":{"t":"laut","x":"Die Hand (扌) gibt den Sinnbereich: mit der Hand ziehen oder zurückhalten. 空 liefert den Klang (クウ → コウ). Gemeint ist „zurückhalten, abziehen, sich zurückhalten“.","s":2,"p":[["扌","Hand","b"],["空","Klang","l"]]},
"壁":{"t":"laut","x":"Die Erde (土) zeigt: Eine Wand aus Erde oder Lehm. 辟 gibt den Klang (ヘキ), der bis heute gleich ist. Gemeint ist „Wand, Mauer“.","s":2,"p":[["辟","Klang","l"],["土","Erde","b"]]},
"棋":{"t":"laut","x":"Das Holz (木) steht für den Stoff, aus dem Spielsteine und Brett sind. 其 liefert den Klang (キ). Gemeint sind Brettspiele wie Shōgi.","s":2,"p":[["木","Holz","b"],["其","Klang","l"]],"i":"os"},
"渋":{"t":"kurz","x":"Kurzform von 澁. Das Wasserzeichen (氵) blieb stehen. Ein Bauteil des alten Zeichens wurde in Japan durch vier Punkte ersetzt. Das Zeichen bedeutet „herb, stockend, zögerlich“.","s":1,"p":[["氵","Wasser","b"]],"a":"澁"},
"仙":{"t":"laut","x":"Das Zeichen ist eine Abwandlung von 僊. Der Mensch (亻) bleibt als Sinnteil. 山 (サン → セン) wurde als Klangteil gewählt. Gemeint ist ein Unsterblicher oder Einsiedler.","s":1,"p":[["亻","Mensch","b"],["山","Berg","l"]],"n":"Gängig ist die Eselsbrücke „ein Mensch im Gebirge“. Die Forschung sieht 山 aber als Klangteil, nicht als Sinnverbindung."},
"充":{"t":"unklar","x":"Der Aufbau ist nicht sicher geklärt. Es steht ein Mensch (儿) unten; das obere Teil wird unterschiedlich gedeutet. Das Zeichen bedeutet „füllen, aufladen, zuweisen“.","s":0,"n":"Oft liest man, oben stehe 育 in Kurzform als Klangteil. Das passt lautlich nicht und wird heute abgelehnt."},
"免":{"t":"leih","x":"Ursprünglich ein Mensch mit einer Kopfbedeckung bzw. einem um den Kopf gewickelten Tuch. Dieses Bild stand für ein eigenes Wort und wurde später für „entkommen, erlassen“ ausgeliehen.","s":1,"n":"Früher hieß es oft, das Zeichen sei eine Krone plus Mensch. Die Form der Krone passt aber nicht, die Deutung gilt als überholt.","i":"ob"},
"勧":{"t":"laut","x":"Im alten Zeichen 勸 gibt 力 (Kraft) den Sinn: jemanden antreiben. 雚 liefert den Klang (カン). In der Kurzform ist 雚 zu 又 verkürzt. Gemeint ist „zureden, empfehlen“.","s":1,"p":[["雚","Klang","l"],["力","Kraft","b"]],"a":"勸","i":"s"},
"圏":{"t":"laut","x":"Die Umrandung (囗) zeigt: ein begrenzter Bereich. 巻 liefert den Klang (ケン). Im alten Zeichen 圈 stand unten ein anderes Teilzeichen; in 圏 wurde es zu 己 geändert. Gemeint ist „Bereich, Kreis“.","s":1,"p":[["囗","Umgrenzung","b"],["巻","Klang","l"]],"a":"圈","i":"s"},
"奪":{"t":"kombi","x":"Eine Hand (寸, früher 又) greift nach einem Vogel (隹), der in einem Gewand steckt. So entsteht der Sinn „wegnehmen, rauben“.","s":1,"p":[["大","Gewand","f"],["隹","Vogel","b"],["寸","Hand","b"]],"n":"Eine zweite Deutung sieht ein Laut-Zeichen: ein Gewand mit 隻 als Klangteil, ursprünglich für „Kleidung ausziehen, wegnehmen“.","i":"bs"},
"慎":{"t":"laut","x":"Das Herz (忄) steht für die innere Haltung. 真 liefert den Klang (シン), der bis heute gleich ist. Gemeint ist „vorsichtig, besonnen sein“.","s":2,"p":[["忄","Herz","b"],["真","Klang","l"]],"i":"s"},
"拒":{"t":"laut","x":"Die Hand (扌) steht für das Zurückweisen mit der Hand. 巨 liefert den Klang (キョ), der bis heute gleich ist. Gemeint ist „abwehren, ablehnen“.","s":2,"p":[["扌","Hand","b"],["巨","Klang","l"]],"n":"Gelegentlich liest man, 巨 bedeute „groß, entfernt“ und die Hand halte so Abstand. Das ist eine nachträgliche Deutung; 巨 trägt hier nur den Klang."},
"枠":{"t":"unklar","x":"Ein in Japan geschaffenes Zeichen (Kokuji). Das Holz (木) steht für den Stoff. Die Herkunft ist nicht sicher; es könnte eine verschliffene Form von 椊 („Zapfen“) sein. Es bedeutet „Rahmen“.","s":1,"p":[["木","Holz","b"]],"n":"Die Lesung わく stammt wohl von einem anderen Zeichen für Garnspulen und wurde in der Bauwelt auf 枠 übertragen."},
"甲":{"t":"unklar","x":"Die Herkunft ist nicht gesichert. Die Orakelknochenform ist ein Kreuz, was zu manchen Erklärungen nicht passt.","s":0,"n":"Oft liest man, es zeige einen Panzer (Schildkrötenpanzer oder Rüstung). Die frühe Kreuzform spricht aber gegen die Schildkrötendeutung.","i":"obs"},
"斐":{"t":"laut","x":"文 („Muster, Schrift“) zeigt: etwas Gemustertes, Schönes. 非 liefert den Klang (ヒ), der bis heute gleich ist. Gemeint ist „schön gemustert“; im Japanischen kommt es vor allem in Namen vor.","s":1,"p":[["非","Klang","l"],["文","Muster","b"]]},
"祉":{"t":"laut","x":"Der Altar (礻) steht für Opfer und Glück. 止 liefert den Klang (シ). Gemeint ist „Glück, Segen“; bekannt aus 福祉 („Wohlfahrt“).","s":2,"p":[["礻","Altar","b"],["止","Klang","l"]],"i":"s"},
"稲":{"t":"laut","x":"Das Getreide (禾) gibt den Sinnbereich: Reispflanze. Im alten Zeichen 稻 steht rechts 舀 als Klangteil. Die Kurzform entstand aus der Schreibschrift, wobei 臼 zu 旧 verschliffen wurde.","s":1,"p":[["禾","Getreide","b"],["舀","Klang","l"]],"a":"稻"},
"譲":{"t":"laut","x":"Das Sprechen (訁) gibt den Sinnbereich: „nachgeben, abtreten“ geschieht mit Worten. 襄 liefert den Klang (ジョウ). In der Kurzform wurde der Klangteil zu 㐮 vereinfacht.","s":1,"p":[["訁","Sprechen","b"],["襄","Klang","l"]],"a":"讓"},
"謙":{"t":"laut","x":"Das Sprechen (言) steht für die Art, wie man auftritt. 兼 liefert den Klang (ケン), der bis heute gleich ist. Gemeint ist „bescheiden sein, sich zurücknehmen“.","s":2,"p":[["言","Sprechen","b"],["兼","Klang","l"]],"i":"s"},
"躍":{"t":"laut","x":"Der Fuß (⻊) zeigt, dass es um eine Bewegung der Beine geht. 翟 liefert den Klang (テキ → ヤク). Gemeint ist „springen, hüpfen“.","s":2,"p":[["⻊","Fuß","b"],["翟","Klang","l"]],"i":"s"},
"銃":{"t":"laut","x":"Das Metall (金) zeigt: ein Rohr oder eine Waffe aus Metall. 充 liefert den Klang (ジュウ), der bis heute gleich ist. Gemeint ist „Feuerwaffe, Gewehr“.","s":2,"p":[["金","Metall","b"],["充","Klang","l"]]},
"項":{"t":"laut","x":"Der Kopf (頁) zeigt eine Körperstelle am Kopf. 工 liefert den Klang (コウ). Ursprünglich ist das der Nacken; später auch ein Punkt oder Abschnitt in Listen.","s":2,"p":[["工","Klang","l"],["頁","Kopf","b"]]},
"鋼":{"t":"laut","x":"Das Metall (金) gibt den Sinnbereich: Stahl. 岡 liefert den Klang (コウ), der bis heute gleich ist.","s":2,"p":[["金","Metall","b"],["岡","Klang","l"]],"n":"Früher deutete man 岡 als Teil der Bedeutung („harter Hügel“). Das gilt heute als überholt."},
"顧":{"t":"laut","x":"Der Kopf (頁) zeigt: Es geht um eine Kopfbewegung, also um einen Blick zurück. 雇 liefert den Klang (コ), der bis heute gleich ist. Gemeint ist „zurückblicken, bedenken“.","s":2,"p":[["雇","Klang","l"],["頁","Kopf","b"]],"i":"bs"},
"駆":{"t":"laut","x":"Das Pferd (馬) zeigt: antreiben, galoppieren. 区 liefert den Klang (ク). Im alten Zeichen 驅 stand dafür die längere Form 區; sie wurde zu 区 verkürzt.","s":2,"p":[["馬","Pferd","b"],["区","Klang","l"]],"a":"驅","i":"s"},
"唱":{"t":"laut","x":"Der Mund (口) steht für Sprechen und Singen. 昌 liefert den Klang (ショウ), der bis heute gleich ist. Gemeint ist „singen, vortragen, ausrufen“.","s":2,"p":[["口","Mund","b"],["昌","Klang","l"]],"i":"s"},
"俊":{"t":"laut","x":"Der Mensch (亻) zeigt: Es geht um eine Person. 夋 liefert den Klang (シュン). Gemeint ist „hervorragend, begabt“.","s":2,"p":[["亻","Mensch","b"],["夋","Klang","l"]]},
"兼":{"t":"kombi","x":"Eine Hand hält zwei Getreidehalme zugleich. So entsteht der Sinn „zugleich haben, verbinden“. In der heutigen Form sind die beiden Halme nicht mehr gut zu erkennen.","s":2,"p":[["禾","Getreide","b"],["又","Hand","b"]],"i":"s"},
"剤":{"t":"laut","x":"Das Messer (刂) steht für Teilen und Zuschneiden. 斉 liefert den Klang (セイ → ザイ). Im alten Zeichen 劑 stand dafür die längere Form 齊. Gemeint ist „Arznei, Mittel“.","s":1,"p":[["斉","Klang","l"],["刂","Messer","b"]],"a":"劑"},
"堀":{"t":"laut","x":"Die Erde (土) zeigt: Es wird Erde ausgehoben. 屈 liefert den Klang (クツ). Gemeint ist „graben, Graben, Wallgraben“.","s":2,"p":[["土","Erde","b"],["屈","Klang","l"]],"i":"s"},
"巡":{"t":"laut","x":"Das Wegzeichen (辶) steht für Gehen. 川 (jetzt als 巛) liefert den Klang, der früher ähnlich war; heute lesen sie sich anders (ジュン / セン). Gemeint ist „umhergehen, Runde machen“.","s":2,"p":[["辶","Weg","b"],["巛","Klang","l"]],"i":"s"},
"戒":{"t":"kombi","x":"Zwei Hände (廾) halten eine Waffe (戈). So entsteht der Sinn „bereithalten, auf der Hut sein“. Daraus entwickelte sich „warnen, ermahnen, Gebot“.","s":2,"p":[["戈","Hellebarde","b"],["廾","zwei Hände","b"]],"i":"obs"},
"排":{"t":"laut","x":"Die Hand (扌) steht für ein Tun mit den Händen: beiseiteschieben oder aufreihen. 非 liefert den Klang (ヒ → ハイ). Gemeint ist „ausschließen, anordnen“.","s":2,"p":[["扌","Hand","b"],["非","Klang","l"]]},
"携":{"t":"laut","x":"Die Hand (扌) steht für das Tragen: etwas hängt an der Hand. 巂 liefert den Klang (ケイ). Im alten Zeichen 攜 stand der Klangteil noch voll da; er wurde zu 隽 verkürzt.","s":2,"p":[["扌","Hand","b"],["巂","Klang","l"]],"a":"攜"},
"敏":{"t":"laut","x":"Das Zeichen 攵 (Hand mit Stock) steht für Tätigkeit und Eifer. 毎 liefert den Klang (マイ → ビン). Gemeint ist „flink, wach, scharfsinnig“.","s":2,"p":[["毎","Klang","l"],["攵","Handlung","b"]],"i":"b"},
"敷":{"t":"laut","x":"Die Handlung (攵) zeigt: etwas ausbreiten. 尃 liefert den Klang (フ), der bis heute gleich ist. In der heutigen Form ist dessen Unterteil 寸 zu 方 verändert worden. Gemeint ist „ausbreiten, legen“.","s":2,"p":[["尃","Klang","l"],["攵","Handlung","b"]]},
"犠":{"t":"laut","x":"Das Rind (牜) zeigt: ein Opfertier. 義 liefert den Klang (ギ). Im alten Zeichen 犧 stand ein anderer Klangteil, 羲; in der Kurzform wurde er durch das gleich klingende 義 ersetzt.","s":1,"p":[["牜","Rind","b"],["義","Klang","l"]],"a":"犧","i":"s"},
"獲":{"t":"laut","x":"Der Hund (犭) zeigt: Jagd und Beute. 蒦 liefert den Klang (カク), der bis heute gleich ist. Gemeint ist „erbeuten, bekommen“.","s":2,"p":[["犭","Hund","b"],["蒦","Klang","l"]]},
"茂":{"t":"laut","x":"Das Gras (艹) zeigt: Pflanzen, die dicht wachsen. 戊 liefert den Klang (ボ → モ). Gemeint ist „üppig wachsen, dicht“.","s":2,"p":[["艹","Gras","b"],["戊","Klang","l"]],"i":"s"},
"繁":{"t":"laut","x":"Die Handlung (攵) ist der Sinnteil, 緐 (Faden 糸 mit 毎) der Klangteil (ハン). In der heutigen Form sind beide verschmolzen, sodass man 敏 über 糸 sieht. Gemeint ist „dicht, zahlreich“.","s":1,"p":[["緐","Klang","l"],["攵","Handlung","b"]],"n":"Früher las man das Zeichen als Sinnverbindung, in der 敏 mitbedeutet. Das gilt heute als überholt."},
"頻":{"t":"leih","x":"Das alte Zeichen 瀕 zeigte einen Menschen (頁) mit den Füßen (步) am Wasser: „am Rand stehen“. Beim Verkürzen fiel das Wasser weg. Dann wurde es für „häufig, immer wieder“ ausgeliehen.","s":2,"p":[["頁","Kopf/Mensch","b"],["步","gehen","b"]]},
"殖":{"t":"laut","x":"歹 (Knochen, Tod) zeigt: Verfall. 直 liefert den Klang (チョク → ショク). Das Wort hieß zuerst „verfaulen“. Später wurde dasselbe Zeichen für „sich vermehren“ ausgeliehen.","s":2,"p":[["歹","Tod","b"],["直","Klang","l"]]},
"衝":{"t":"laut","x":"Die Straße (行) zeigt: eine breite Verkehrsstraße. Als Klangteil stand ursprünglich 童, später verkürzt zu 重. Später wurde das Zeichen für „stoßen, zusammenprallen“ ausgeliehen.","s":2,"p":[["行","Straße","b"],["重","Klang","l"]],"i":"s"},
"誉":{"t":"laut","x":"Das Sprechen (言) steht für Lob. Das alte Zeichen 譽 hatte 與 als Klangteil (ヨ); in der Kurzform ist es zu 兴 verkürzt. Gemeint ist „Ruhm, Lob“.","s":1,"p":[["言","Sprechen","b"],["与","Klang","l"]],"a":"譽","i":"s"},
"褒":{"t":"laut","x":"Das Kleid (衣) zeigt: Es ging zuerst um ein weites Gewand. Klangteil ist 孚. Später wurde das Zeichen für „loben“ ausgeliehen.","s":1,"p":[["衣","Kleid","b"],["孚","Klang","l"]],"n":"Heute sieht man 保 im Zeichen, und man deutet es oft als 衣 plus 保. Die alte Schrift zeigt aber, dass das ein Fehlschluss aus der heutigen Form ist.","a":"襃"},
"透":{"t":"laut","x":"Das Wegzeichen (辶) steht für Gehen und Hindurchgehen. 秀 liefert den Klang (シュウ → トウ). Gemeint ist „durchgehen, durchsichtig sein“.","s":2,"p":[["辶","Weg","b"],["秀","Klang","l"]],"i":"s"},
"隣":{"t":"laut","x":"Das alte Zeichen 鄰 hatte links 邑 (Siedlung) als Sinnteil und 粦 als Klangteil (リン). In 隣 wurde die Siedlung durch 阜 ersetzt (⻖, „Hügel“). Gemeint ist „Nachbar“.","s":2,"p":[["阝","Hügel","b"],["粦","Klang","l"]],"a":"鄰","i":"s"},
"雅":{"t":"laut","x":"Der Vogel (隹) zeigt: ursprünglich ein Vogel, nämlich die Krähe. 牙 liefert den Klang (ガ), der bis heute gleich ist. Später wurde das Zeichen für „fein, elegant“ ausgeliehen.","s":2,"p":[["隹","Vogel","b"],["牙","Klang","l"]]},
"徹":{"t":"kombi","x":"Die frühe Form zeigt eine Hand und einen Topf: Geschirr wird nach dem Essen abgeräumt. Später kamen 攵 (Tätigkeit) und 彳 (Gehen) dazu. Der Topf verschliff dabei zu etwas, das wie 育 aussieht.","s":1,"p":[["彳","gehen","f"],["育","Topf","f"],["攵","Hand","b"]],"n":"Das 育 im Zeichen hat nichts mit „aufziehen“ zu tun. Ein Quellenteil sieht eher ein Laut-Zeichen mit abgeleitetem Klangteil."},
"瀬":{"t":"laut","x":"Das Wasser (氵) zeigt: eine Stelle im Fluss. 頼 liefert den Klang (ライ), der bis heute gleich ist. Gemeint ist „Stromschnelle, flache Stelle im Fluss“. Die heutige Form ist eine Variante von 瀨.","s":1,"p":[["氵","Wasser","b"],["頼","Klang","l"]],"a":"瀨","i":"s"},
"撤":{"t":"laut","x":"Die Hand (扌) zeigt: etwas mit den Händen wegnehmen. 徹 liefert den Klang (テツ), nur in verkürzter Form (ohne 彳). Gemeint ist „entfernen, zurückziehen“.","s":2,"p":[["扌","Hand","b"],["徹","Klang","l"]]},
"措":{"t":"laut","x":"Die Hand (扌) steht für ein Tun mit den Händen. 昔 liefert den Klang (セキ → ソ). Gemeint ist „hinlegen, setzen“, im übertragenen Sinn „Maßnahme“.","s":2,"p":[["扌","Hand","b"],["昔","Klang","l"]],"i":"s"},
"拠":{"t":"laut","x":"Die Hand (扌) steht für „sich auf etwas stützen“. Das alte Zeichen 據 hatte 豦 als Klangteil; in der Kurzform wurde es durch 処 ersetzt. Gemeint ist „Grundlage, sich stützen auf“.","s":1,"p":[["扌","Hand","b"],["処","Klang","l"]],"a":"據"},
"儀":{"t":"laut","x":"Links steht 亻 (Mensch) als Sinnteil, rechts 義 als Klangteil (ギ → 儀 ギ). Gemeint ist die Regel, die Ordnung, nach der man sich richtet; daraus „Zeremonie, Umgangsform“.","s":2,"p":[["亻","Mensch","b"],["義","Rechtlichkeit, Regel","l"]],"i":"bs"},
"樹":{"t":"laut","x":"Das Zeichen 尌 zeigte ursprünglich, wie man einen Baum pflanzt, und wurde für „pflanzen“ benutzt. Später kam 木 (Baum) dazu, damit das Zeichen für den Baum selbst eindeutig ist: 木 + 尌.","s":2,"p":[["木","Baum","b"],["尌","pflanzen","l"]],"n":"Oft liest man, in 尌 stecke eine Trommel (壴). Das gilt heute als falsch: 尌 hat mit Trommeln nichts zu tun, anders als 鼓.","i":"s"},
"棄":{"t":"kombi","x":"Ein auf den Kopf gestelltes Kind (子), ein Korb und zwei Hände: Ein Kind wird im Korb weggeworfen. Daraus wurde „wegwerfen, aufgeben“. Die Form spiegelt eine alte Gesellschaft wider, in der Neugeborene manchmal ausgesetzt wurden.","s":2,"p":[["𠫓","Kind (auf dem Kopf)","b"],["𠀠","Korb","b"],["廾","zwei Hände","b"]],"i":"obs"},
"虎":{"t":"bild","x":"Bildzeichen für den Tiger. Oben 虍 ist der Kopf des Tigers. Der Körper ist weggefallen, Beine und Schwanz wurden zum unteren Teil (früher 人, heute 儿 oder 几 geschrieben).","s":2,"i":"obs"},
"蛍":{"t":"laut","x":"In der alten Form 螢 steht 虫 (Insekt) als Sinnteil und 𤇾 als Klangteil; gemeint ist das Glühwürmchen. In 蛍 ist der obere Teil 𤇾 stark verkürzt.","s":2,"p":[["虫","Insekt","b"],["𤇾","Klangteil","l"]],"a":"螢"},
"艦":{"t":"laut","x":"舟 (Boot) gibt den Sinnbereich an, 監 den Klang (カン → 艦 カン). Gemeint ist ursprünglich das Kriegsschiff.","s":2,"p":[["舟","Boot","b"],["監","beaufsichtigen","l"]]},
"潜":{"t":"laut","x":"In der alten Form 潛 gibt 氵 (Wasser) den Sinnbereich an, 朁 den Klang; gemeint ist „untertauchen“. In der heutigen Form 潜 steht stattdessen 替 als Bauteil.","s":2,"p":[["氵","Wasser","b"],["朁","Klangteil","l"]],"a":"潛","i":"s"},
"拳":{"t":"laut","x":"手 (Hand) zeigt den Sinnbereich: Die Faust ist eine Form der Hand. Der obere Teil gibt den Klang an (ケン). Der obere Teil sieht heute anders aus als der ursprüngliche Klangteil.","s":2,"p":[["龹","Klangteil","l"],["手","Hand","b"]],"i":"s"},
"仁":{"t":"unklar","x":"Nach heutiger Sicht ist 仁 aus 人 (Mensch) abgeleitet: Ein zusätzlicher waagerechter Strich unterscheidet das Zeichen von 人. Die „zwei“ in 二 haben hier keine eigene Bedeutung.","s":0,"p":[["亻","Mensch","b"],["二","zwei","f"]],"n":"Oft liest man „zwei Menschen“ (menschliches Miteinander). Das ist eine spätere Deutung, kein gesicherter Ursprung.","i":"s"},
"至":{"t":"bild","x":"Ein Pfeil, der sein Ziel erreicht und am Boden steckt. Daraus wurde „ankommen, erreichen“.","s":2,"n":"Manchmal wird das Zeichen als Vogel gedeutet, der Beute fängt. Das ist eine Volksdeutung ohne Belege.","i":"obs"},
"誠":{"t":"laut","x":"言 (Sprache, Worte) gibt den Sinnbereich an, 成 den Klang (セイ → 誠 セイ). Gemeint ist das, was man aufrichtig sagt: „Wahrheit, Aufrichtigkeit“.","s":2,"p":[["言","Sprache","b"],["成","werden, vollenden","l"]],"i":"s"},
"郷":{"t":"laut","x":"In der alten Form 鄕 stehen zwei 邑 (Siedlung) links und rechts, in der Mitte ein verkürztes 卿 als Klangteil (キョウ → 郷 キョウ). Gemeint ist das Dorf, die Heimat. Die Kurzform 郷 vereinfacht die Mitte.","s":2,"p":[["邑","Siedlung (zweimal)","b"],["卿","Klangteil","l"]],"n":"Oft liest man, in der Mitte säßen zwei Menschen mit einem Festmahl einander gegenüber. Das gilt heute als Konstruktion: Der mittlere Teil trägt keinen Sinn.","a":"鄕"},
"侵":{"t":"laut","x":"亻 (Mensch) als Sinnteil, daneben ein Klangteil (シン). Gemeint ist „eindringen, angreifen“.","s":1,"p":[["亻","Mensch","b"],["𠬶","Klangteil","l"]],"n":"Eine alte Wörterbuchdeutung sieht darin einen Menschen mit Besen in der Hand. Heute wird das Zeichen als Laut-Sinn-Zeichen erklärt.","i":"obs"},
"偽":{"t":"laut","x":"In der alten Form 僞 steht 亻 (Mensch) als Sinnteil und 爲 als Klangteil. Gemeint ist etwas „Gemachtes, Unechtes“, daher „falsch, Lüge“. 偽 ist die Kurzform mit vereinfachtem rechtem Teil.","s":2,"p":[["亻","Mensch","b"],["爲","tun, machen","l"]],"n":"Oft liest man das Zeichen als Sinnverbindung „was ein Mensch macht“. Das gilt als Fehldeutung.","a":"僞","i":"s"},
"克":{"t":"unklar","x":"Der Ursprung ist nicht geklärt. Auf Orakelknochen und Bronzen steht oben 由 (oder einfach 口) über einem seitlich liegenden Becken. Daraus entwickelte sich die heutige Form.","s":0,"n":"Es gibt mehrere Theorien, aber keine gilt als gesichert.","i":"obs"},
"哲":{"t":"laut","x":"口 (Mund) steht für Sprechen, 折 gibt den Klang an (セツ → 哲 テツ). In frühen Bronzeinschriften wird das Wort anders geschrieben (悊); die heutige Form gibt es erst später.","s":2,"p":[["口","Mund","b"],["折","brechen","l"]],"n":"Oft liest man „mit Worten die Dinge zerlegen, also Weisheit“. Das ist nachträglich hineingedeutet; 折 gibt nur den Klang an.","i":"s"},
"喪":{"t":"laut","x":"Ursprünglich 桑 (Maulbeerbaum) als Klangteil (ソウ → 喪 ソウ) plus 口 als Unterscheidungszeichen; manchmal standen mehrere Münder. Das Wort bedeutet „verlieren“. Die heutige Form sieht aus wie 哭 + 亡, entstand aber erst später.","s":2,"p":[["桑","Maulbeerbaum","l"],["口","Mund","f"]],"n":"Oft liest man „weinen (哭) um einen Toten (亡)“. Die alten Formen zeigen, dass das nicht der Ursprung ist.","i":"obs"},
"堅":{"t":"laut","x":"土 (Erde) als Sinnteil: festes, hartes Erdreich. 臤 gibt den Klang an (ケン). Daraus „hart, fest“.","s":2,"p":[["土","Erde","b"],["臤","Klangteil","l"]]},
"括":{"t":"laut","x":"扌 (Hand) als Sinnteil: zusammenfassen, bündeln. Der rechte Teil ist ein Klangteil (カツ), der ursprünglich etwas anders aussah und heute wie 舌 geschrieben wird.","s":1,"p":[["扌","Hand","b"],["舌","Zunge (Klangteil)","l"]]},
"弧":{"t":"laut","x":"弓 (Bogen) gibt den Sinn an, 瓜 den Klang. Gemeint ist ein Bogen aus Holz; daraus entwickelte sich der Sinn „gebogene Linie, Bogenform“.","s":2,"p":[["弓","Bogen","b"],["瓜","Kürbis","l"]]},
"挑":{"t":"laut","x":"扌 (Hand) als Sinnteil, 兆 gibt den Klang an (チョウ → 挑 チョウ). Gemeint ist „herausfordern“.","s":2,"p":[["扌","Hand","b"],["兆","Zeichen","l"]],"i":"s"},
"揚":{"t":"laut","x":"扌 (Hand) als Sinnteil: mit der Hand hochheben. 昜 gibt den Klang an (ヨウ → 揚 ヨウ). Daraus „erheben, hochziehen“.","s":2,"p":[["扌","Hand","b"],["昜","Klangteil","l"]]},
"握":{"t":"laut","x":"扌 (Hand) als Sinnteil, 屋 als Klangteil (オク → 握 アク). Gemeint ist „fassen, greifen, ballen“. Die Bedeutung von 屋 spielt hier keine Rolle.","s":2,"p":[["扌","Hand","b"],["屋","Haus","l"]]},
"揺":{"t":"laut","x":"In der alten Form 搖 steht 扌 (Hand) als Sinnteil und ein Klangteil, der von 繇 abgeleitet ist (ヨウ). Gemeint ist „schwingen, schütteln“. In 揺 ist der rechte Teil vereinfacht.","s":2,"p":[["扌","Hand","b"],["䍃","Klangteil","l"]],"a":"搖"},
"斎":{"t":"laut","x":"In der alten Form 齋 gibt 示 (Altar, Gottheit) den Sinnbereich an, 齊 den Klang (セイ → 齋 サイ). Gemeint ist die rituelle Reinigung. In 斎 ist 齊 zu 斉 verkürzt und 示 zu 小 geworden.","s":2,"p":[["示","Gottheit, Altar","b"],["齊","gleichmäßig","l"]],"n":"Früher las man 齊 auch als Sinnteil („Gleichheit der Gedanken“). Das gilt als unbegründet.","a":"齋","i":"bs"},
"暫":{"t":"laut","x":"日 (Sonne, Zeit) als Sinnteil, 斬 als Klangteil (ザン). Gemeint ist eine kurze Zeitspanne: „vorübergehend, eine Weile“.","s":2,"p":[["日","Sonne, Tag","b"],["斬","abhauen","l"]],"n":"Teils wird 斬 auch als Sinnteil gedeutet. Das gilt heute als falsch.","i":"s"},
"析":{"t":"kombi","x":"Eine Axt (斤) und Holz (木): Holz wird gespalten. Daraus „aufspalten, zerlegen“.","s":2,"p":[["木","Baum, Holz","b"],["斤","Axt","b"]],"i":"obs"},
"枢":{"t":"laut","x":"In der alten Form 樞 steht 木 (Holz) als Sinnteil und 區 als Klangteil. Gemeint ist ein Angelpunkt, ein Dreh- und Mittelpunkt. In 枢 wird 區 zu 区 verkürzt, so wie in 区.","s":2,"p":[["木","Holz","b"],["區","Klangteil","l"]],"a":"樞","i":"s"},
"軸":{"t":"laut","x":"車 (Wagen) als Sinnteil, 由 als Klangteil. Gemeint ist die Achse, die durch das Rad hindurchgeht; daraus „Achse, Rolle“.","s":1,"p":[["車","Wagen","b"],["由","hindurch","l"]]},
"柄":{"t":"laut","x":"木 (Holz) als Sinnteil, 丙 als Klangteil (ヘイ → 柄 ヘイ). Gemeint ist der hölzerne Griff oder Stiel; daraus später „Muster“.","s":2,"p":[["木","Holz","b"],["丙","Klangteil","l"]],"i":"s"},
"滑":{"t":"laut","x":"氵 (Wasser) als Sinnteil, 骨 als Klangteil (コツ → 滑 コツ). Gemeint ist „gleiten, rutschen“.","s":2,"p":[["氵","Wasser","b"],["骨","Knochen","l"]]},
"潟":{"t":"laut","x":"氵 (Wasser) als Sinnteil, 舄 als Klangteil (セキ). Das alte Wort meint salzhaltigen Boden; daraus „Lagune, Watt“.","s":2,"p":[["氵","Wasser","b"],["舄","Klangteil","l"]]},
"焦":{"t":"laut","x":"Ursprünglich 隹 (Vogel) und 小 als Klangteil: der Name einer Vogelart. In der Zeit der Streitenden Reiche wurde 小 zu 火 (灬) umgeformt. Danach wurde das Zeichen für „verbrennen, versengen“ ausgeliehen.","s":2,"p":[["隹","Vogel","b"],["小","klein","l"]],"n":"Oft liest man „Vogel über Feuer“. Das ist nur der Eindruck der späteren Form, nicht der Ursprung.","i":"bs"},
"範":{"t":"laut","x":"車 (Wagen) als Sinnteil und ein Klangteil (ハン) – daraus „Muster, Vorbild“. Der Klangteil sieht heute stark verändert aus.","s":1,"p":[["車","Wagen","b"],["𦫾","Klangteil","l"]],"n":"Ein altes Wörterbuch erklärt den oberen Teil als 笵. Die Bronzeformen zeigen, dass das nicht stimmt."},
"紛":{"t":"laut","x":"糸 (Faden) als Sinnteil, 分 als Klangteil (フン). Daraus „durcheinandergeraten, sich verwirren“.","s":2,"p":[["糸","Faden","b"],["分","teilen","l"]],"i":"s"},
"糾":{"t":"laut","x":"丩 stand ursprünglich selbst für „verflechten, verdrehen“. Später kam 糸 (Faden) dazu, um das Wort deutlicher zu machen. Daraus „verflechten“ und später „klären, tadeln“.","s":2,"p":[["糸","Faden","b"],["丩","verflechten","l"]],"i":"obs"},
"綱":{"t":"laut","x":"糸 (Faden, Seil) als Sinnteil, 岡 als Klangteil (コウ → 綱 コウ). Gemeint ist das dicke Seil, das Tau; daraus „Hauptlinie, Grundsatz“.","s":2,"p":[["糸","Faden","b"],["岡","Hügel","l"]]},
"網":{"t":"laut","x":"Ursprünglich genügte das Bildzeichen 网 für das Netz. Dann kam 亡 als Klangteil dazu (罔), schließlich 糸 (Faden): 網. Klang: モウ.","s":2,"p":[["糸","Faden","b"],["罔","Netz","l"]],"i":"obs"},
"肝":{"t":"laut","x":"⺼ (Fleisch, Körperteil) als Sinnteil, 干 als Klangteil (カン → 肝 カン). Gemeint ist die Leber; daraus „Kern, Wesentliches“.","s":2,"p":[["⺼","Fleisch, Körperteil","b"],["干","trocknen","l"]]},
"芝":{"t":"laut","x":"艹 (Pflanze) als Sinnteil, 之 als Klangteil (シ → 芝 シ). Das Zeichen meint eine Pflanzenart; heute steht es für Rasen.","s":2,"p":[["艹","Gras, Pflanze","b"],["之","gehen","l"]],"i":"s"},
"裂":{"t":"laut","x":"衣 (Kleidung) als Sinnteil: Stoff zerreißen. 列 gibt den Klang an (レツ → 裂 レツ) und zeigt zerlegte Knochen in einer Reihe.","s":2,"p":[["列","Reihe","l"],["衣","Kleidung","b"]],"i":"s"},
"襲":{"t":"laut","x":"衣 (Kleidung) als Sinnteil. Als Klangteil stand früher 龖, das später zu 龍 verkürzt wurde. Daraus „überziehen, angreifen, übernehmen“.","s":1,"p":[["龍","Drache","l"],["衣","Kleidung","b"]],"i":"s"},
"貢":{"t":"laut","x":"貝 (Muschel, Wertgegenstand) als Sinnteil, 工 als Klangteil (コウ → 貢 コウ). Gemeint ist Tribut, den man abgibt.","s":2,"p":[["工","Arbeit","l"],["貝","Muschel, Geld","b"]]},
"趣":{"t":"laut","x":"走 (laufen) als Sinnteil, 取 als Klangteil (シュ → 趣 シュ). Gemeint ist „sich beeilen, auf ein Ziel zugehen“; daraus „Richtung, Sinn, Reiz“.","s":2,"p":[["走","laufen","b"],["取","nehmen","l"]],"i":"s"},
"距":{"t":"laut","x":"足 (Fuß) als Sinnteil, 巨 als Klangteil (キョ → 距 キョ). Gemeint ist der Abstand zwischen zwei Schritten; daraus „Entfernung“.","s":2,"p":[["足","Fuß","b"],["巨","groß","l"]],"n":"Früher las man 巨 auch als Sinnteil. Das gilt als falsch."},
"露":{"t":"laut","x":"雨 (Regen) als Sinnteil, 路 als Klangteil (ロ → 露 ロ). Gemeint ist der Tau; daraus „offenlegen, entblößen“.","s":2,"p":[["雨","Regen","b"],["路","Weg","l"]],"i":"s"},
"牧":{"t":"kombi","x":"Ein Rind (牛) und eine Hand mit Gerte (攵, ursprünglich 攴): Man treibt Vieh. Daraus „Vieh hüten, Weide“.","s":2,"p":[["牜","Rind","b"],["攵","Gerte","b"]],"i":"obs"},
"朗":{"t":"laut","x":"月 (Mond) als Sinnteil, 良 als Klangteil (リョウ → 朗 ロウ). Gemeint ist Helligkeit; daraus „klar, heiter“.","s":2,"p":[["良","gut","l"],["月","Mond","b"]],"i":"s"},
"潮":{"t":"laut","x":"Ursprünglich schrieb man das Wort für Gezeiten nur 朝. Dann kam 氵 (Wasser) als Sinnteil dazu. 朝 gibt weiter den Klang an (チョウ → 潮 チョウ).","s":2,"p":[["氵","Wasser","b"],["朝","Morgen","l"]]},
"即":{"t":"kombi","x":"Ein Speisegefäß (皀) und ein knieender Mensch (卩): Man setzt sich zum Essen. Daraus „herantreten“ und „sofort“. 即 ist die Kurzform von 卽.","s":2,"p":[["皀","Speisegefäß","b"],["卩","knieender Mensch","b"]],"a":"卽"},
"垣":{"t":"laut","x":"土 (Erde) als Sinnteil, 亘 als Klangteil (エン → 垣 エン). Gemeint ist die Mauer oder der Zaun.","s":2,"p":[["土","Erde","b"],["亘","Klangteil","l"]],"i":"s"},
"威":{"t":"kombi","x":"Eine Waffe (戌) und eine Frau (女). Das Zeichen wird für „drohen, einschüchtern“ gebraucht; daraus „Würde, Macht“.","s":1,"p":[["戌","Waffe","b"],["女","Frau","b"]],"i":"bs"},
"岳":{"t":"unklar","x":"Unten steht 山 (Berg). Der obere Teil ist ein ursprünglich schafähnliches Zeichen, das wohl als Klangzeichen geliehen wurde. Mit 丘 (Hügel) hat er nichts zu tun.","s":0,"p":[["山","Berg","b"]],"i":"os"},
"慰":{"t":"laut","x":"心 (Herz) als Sinnteil, 尉 als Klangteil (イ → 慰 イ). Gemeint ist „trösten, beruhigen“.","s":2,"p":[["心","Herz","b"],["尉","Klangteil","l"]]},
"懇":{"t":"laut","x":"心 (Herz) als Sinnteil, 貇 als Klangteil (コン). Gemeint ist, sich mit ganzem Herzen zuzuwenden; daraus „freundlich, aufrichtig“.","s":2,"p":[["心","Herz","b"],["貇","Klangteil","l"]],"n":"Ältere Wörterbücher deuten den oberen Teil als Sinnbringer. Das gilt als falsch."},
"懲":{"t":"laut","x":"心 (Herz) als Sinnteil, 徵 als Klangteil (チョウ → 懲 チョウ). Gemeint ist „sich zurechtweisen lassen, bestrafen“.","s":2,"p":[["心","Herz","b"],["徵","Zeichen","l"]]},
"摩":{"t":"laut","x":"手 (Hand) als Sinnteil, 麻 als Klangteil (マ → 摩 マ). Gemeint ist „reiben“.","s":2,"p":[["手","Hand","b"],["麻","Hanf","l"]]},
"擦":{"t":"laut","x":"扌 (Hand) als Sinnteil: mit der Hand abwischen, reiben. 察 gibt den Klang an (サツ → 擦 サツ).","s":2,"p":[["扌","Hand","b"],["察","Klangteil","l"]]},
"撲":{"t":"laut","x":"扌 (Hand) als Sinnteil, 菐 als Klangteil (ボク). Gemeint ist „schlagen, hauen“.","s":2,"p":[["扌","Hand","b"],["菐","Klangteil","l"]]},
"斉":{"t":"leih","x":"Die alte Form 齊 zeigt wohl die Frucht einer Pflanze (Ankerdorn) und diente zunächst für diese Pflanze. Später wurde das Zeichen für das Wort „gleich, einheitlich“ ausgeliehen. 斉 ist die Kurzform.","s":1,"n":"Oft liest man „Ähren in einer Reihe“. Das passt nicht zu den alten Formen.","a":"齊","i":"obs"},
"旨":{"t":"kombi","x":"Ein Löffel (匕) bringt Essen zum Mund (口): etwas Gutes, Leckeres. In der späteren Schrift bekam 口 einen Strich (甘) und dann die Form 日. Daraus „Geschmack, Sinn“.","s":2,"p":[["匕","Löffel","b"],["口","Mund","b"]],"n":"Alte Wörterbücher sehen 匕 als Klangteil. Das stimmt nicht.","i":"obs"},
"沼":{"t":"laut","x":"氵 (Wasser) als Sinnteil, 召 als Klangteil (ショウ → 沼 ショウ). Gemeint ist ein Teich oder Sumpf.","s":2,"p":[["氵","Wasser","b"],["召","rufen","l"]]},
"泰":{"t":"unklar","x":"Das Zeichen entstand wohl als Abwandlung von 大 mit zusätzlichen Bauteilen 廾 (zwei Hände) und 水 (Wasser). Der ursprüngliche Sinn („rutschen“) ist unsicher; die heutige Bedeutung „ruhig, groß“ kam später.","s":0,"p":[["大","groß","b"],["水","Wasser","b"]],"n":"Eine Deutung sieht den Ursprung in der Schriftreform der Qin-Zeit: 水 und 廾 seien später angefügt worden.","i":"s"},
"滅":{"t":"laut","x":"氵 (Wasser) als Sinnteil, 烕 als Klangteil (メツ → 滅 メツ). Gemeint ist „auslöschen, vernichten“.","s":2,"p":[["氵","Wasser","b"],["烕","Klangteil","l"]],"n":"Ältere Wörterbücher deuten 烕 auch als Sinnteil. Das ist unbegründet.","i":"obs"},
"滋":{"t":"laut","x":"氵 (Wasser) als Sinnteil, 茲 als Klangteil (ジ). Gemeint ist, wie Wasser Pflanzen nährt: „nähren, gedeihen“.","s":2,"p":[["氵","Wasser","b"],["茲","Klangteil","l"]]},
"炉":{"t":"laut","x":"In der alten Form 爐 steht 火 (Feuer) als Sinnteil und 盧 als Klangteil (ロ → 爐 ロ). Gemeint ist der Herd oder Ofen. In 炉 ist 盧 zu 戸 verkürzt.","s":2,"p":[["火","Feuer","b"],["盧","Klangteil","l"]],"a":"爐"},
"琴":{"t":"laut","x":"Oben steht 珡, die Zither (zwei Stege-Zeichen), unten 今 als Klangteil. Gemeint ist ein Saiteninstrument.","s":1,"p":[["珡","Zither","b"],["今","jetzt","l"]],"i":"s"},
"寸":{"t":"leih","x":"Ursprünglich war 寸 eine Kurzform von 尊. Später wurde das Zeichen für das Wort „Zoll“ (ein Längenmaß) ausgeliehen.","s":1,"n":"Oft liest man „Hand mit Strich am Handgelenk, der misst“. Das gilt als falsch. In 肘 oder 寺 hat 寸 einen anderen Ursprung.","i":"bs"},
"竜":{"t":"bild","x":"Die alte Form 龍 ist ein Bildzeichen für den Drachen, ein Fabelwesen. Seit der Han-Zeit gibt es 竜 als vereinfachte Kurzschrift davon.","s":2,"n":"Manche leiten 竜 von älteren Schriftformen ab. Das ist nicht gesichert.","a":"龍","i":"obs"},
"縁":{"t":"laut","x":"In der alten Form 緣 steht 糸 (Faden) als Sinnteil und 彖 als Klangteil. In 縁 ist der rechte Teil vereinfacht. Die heutige Bedeutung „Verbindung, Beziehung“ ist eine Weiterentwicklung.","s":2,"p":[["糸","Faden","b"],["彖","Klangteil","l"]],"a":"緣","i":"s"},
"翼":{"t":"laut","x":"Oben 羽 (Federn) als Sinnteil, unten 異 als Klangteil. Ursprünglich schrieb man das Wort „Flügel“ allein mit 羽; später wurde 異 zur Verdeutlichung des Klangs ergänzt.","s":2,"p":[["羽","Feder, Flügel","b"],["異","anders","l"]]},
"吉":{"t":"leih","x":"Das Zeichen schrieb zuerst das Wort „hart, fest“: oben die Form einer Waffenklinge als Sinnbild für Hartes, dazu ein 口-Zeichen. Später wurde es für ein gleich klingendes Wort „gut, Glück“ ausgeliehen. Die Klinge wurde mit der Zeit zu 士.","s":1,"p":[["士","Klingenform","f"],["口","Mundzeichen","f"]],"i":"obs"},
"刃":{"t":"zeichen","x":"Ein Messer 刀, bei dem ein zusätzlicher Strich genau die scharfe Schneide markiert. So steht das Zeichen für „Klinge, Schneide“.","s":2,"p":[["刀","Messer","b"]],"i":"os"},
"忍":{"t":"laut","x":"Das Herz 心 gibt den Sinnbereich (innere Haltung, Aushalten), 刃 den Klang (ニン bzw. ジン). Gemeint ist „ertragen, aushalten“.","s":2,"p":[["心","Herz","b"],["刃","Klinge","l"]],"i":"s"},
"桃":{"t":"laut","x":"Der Baum 木 zeigt, dass es um eine Pflanze geht, 兆 liefert den Klang. Gemeint ist der Pfirsichbaum.","s":2,"p":[["木","Baum","b"],["兆","Vorzeichen","l"]],"i":"s"},
"侍":{"t":"laut","x":"亻 (Mensch) gibt den Sinnbereich, 寺 den Klang: 寺 ジ → 侍 ジ. Das Zeichen betrifft eine Person, die jemandem dient.","s":2,"p":[["亻","Mensch","b"],["寺","Tempel","l"]]},
"娯":{"t":"laut","x":"Die alte Form 娛 besteht aus 女 (Frau) und 吳 als Klangteil: 呉 ゴ → 娯 ゴ. In der heutigen Form ist 吳 zu 呉 vereinfacht.","s":1,"p":[["女","Frau","b"],["呉","Wu","l"]],"a":"娛"},
"斗":{"t":"bild","x":"Abgebildet ist eine Schöpfkelle mit Stiel, mit der man Getreide oder Flüssigkeit abmisst. Daher ist 斗 ein altes Hohlmaß, später auch der Name des Sternbilds „Großer Wagen“.","s":2,"i":"os"},
"朱":{"t":"leih","x":"Ein Baum 木 mit einem Punkt mitten im Stamm, der den Stamm hervorhebt. So schrieb man ursprünglich das Wort „Baumstamm“. Später wurde das Zeichen für das gleich klingende Wort „Zinnoberrot“ ausgeliehen.","s":1,"p":[["木","Baum","b"],["丶","Punkt","f"]],"n":"Eine weitere Deutung sieht 朱 als ausgeliehene Abspaltung von 束.","i":"obs"},
"丘":{"t":"bild","x":"Das Zeichen zeigt einen Hügel, ähnlich wie 山. Die heutige Form wirkt zusammengesetzt, geht aber auf dieses Bild zurück.","s":2,"n":"Das Shuowen deutete 丘 als 北 plus 一; das gilt heute als falsche Analyse.","i":"os"},
"梨":{"t":"laut","x":"木 (Baum) gibt den Sinnbereich, 利 den Klang (リ → リ). Gemeint ist der Birnbaum.","s":2,"p":[["木","Baum","b"],["利","nützlich","l"]],"i":"s"},
"僕":{"t":"bild","x":"Die frühe Form zeigte einen Sklaven oder Gefangenen mit Strafwerkzeug auf dem Kopf, Händen mit Korb und einem Schwanz als Zeichen niederen Standes. Später wurde der Körper zur Mensch-Seite 亻, der Rest zum Klangteil 菐.","s":2,"p":[["亻","Mensch","b"],["菐","Lautteil","l"]]},
"釣":{"t":"laut","x":"Metall 金 als Sinnteil (der Angelhaken), 勺 als Klangteil. Gemeint ist „angeln“.","s":2,"p":[["釒","Metall","b"],["勺","Schöpfkelle","l"]],"n":"Eine ältere Deutung sah im Klangteil zugleich Bedeutung; das gilt als Fehlanalyse.","i":"s"},
"嵐":{"t":"laut","x":"Der Berg 山 steht für den Sinnbereich, 風 für den Klang (nach der Quelle in verkürzter Form). Ursprünglich war damit die Luft in den Bergen gemeint, heute „Sturm“.","s":2,"p":[["山","Berg","b"],["風","Wind","l"]]},
"姫":{"t":"laut","x":"Ursprünglich 女 (Frau) plus Klangteil 臣. Das japanische 姫 für „Prinzessin“ gilt aber als Variante des Zeichens 姬 (Lesung キ), das eine eigene Herkunft hat.","s":1,"p":[["女","Frau","b"],["臣","Diener","l"]]},
"棚":{"t":"laut","x":"木 (Holz) gibt den Sinnbereich, 朋 den Klang (ホウ → ホウ). Ein Regal oder Gestell wird aus Holz gebaut.","s":2,"p":[["木","Baum","b"],["朋","Freund","l"]]},
"砲":{"t":"laut","x":"石 (Stein) als Sinnteil, 包 als Klangteil (ホウ → ホウ). Ursprünglich war es die Wurfmaschine, die Steine weit schleuderte, daraus wurde „Kanone“.","s":2,"p":[["石","Stein","b"],["包","einwickeln","l"]]},
"雷":{"t":"laut","x":"Die ältere Form 靁 bestand aus 雨 (Regen) und Klangteil 畾. In 雷 ist 畾 zu einem einzelnen 田 verkürzt. Gemeint ist der Donner.","s":2,"p":[["⻗","Regen","b"],["田","Feld","f"]],"n":"Eine alte Deutung nahm auch Bedeutung im Klangteil an; das gilt als falsch."},
"芽":{"t":"laut","x":"艹 (Pflanze) als Sinnteil, 牙 als Klangteil (ガ → ガ). Gemeint ist der Pflanzenspross, die Knospe.","s":2,"p":[["艹","Gras, Pflanze","b"],["牙","Zahn","l"]],"n":"Die Deutung „Zahn der Pflanze“ als Sinnverbindung gilt als haltlos."},
"澄":{"t":"laut","x":"Wasser 氵 gibt den Sinnbereich: klares Wasser. 登 ist der Klangteil; heute klingen beide nicht mehr gleich (登 トウ, 澄 チョウ).","s":2,"p":[["氵","Wasser","b"],["登","aufsteigen","l"]]},
"矛":{"t":"bild","x":"Abgebildet ist ein Speer mit Ring in der Mitte des Schafts, eine Waffe, die sich von der Hellebarde 戈 unterscheidet.","s":2,"n":"Hat nichts mit 予 zu tun, obwohl es heute ähnlich aussieht.","i":"bs"},
"鐘":{"t":"laut","x":"金 (Metall) als Sinnteil, denn die Glocke ist aus Bronze. 童 liefert den Klang; heute klingen beide nicht mehr gleich (童 ドウ, 鐘 ショウ).","s":2,"p":[["金","Metall","b"],["童","Kind","l"]],"i":"bs"},
"凶":{"t":"bild","x":"Nach neuerer Forschung eine Kurzform von 兇, bei dem ein Kopf hervorgehoben ist; gemeint ist „unheilvoll“.","s":0,"n":"Traditionell: eine Grube mit einem Kreuz, in die man hineinfällt, oder ein Erdspalt. Verwandtschaft mit 匈 und 胸 gilt als nicht belegt.","i":"s"},
"塊":{"t":"laut","x":"土 (Erde) als Sinnteil, 鬼 als Klangteil. Gemeint ist ein Klumpen Erde, daraus „Klumpen, Brocken“.","s":2,"p":[["土","Erde","b"],["鬼","Geist","l"]],"i":"s"},
"狩":{"t":"laut","x":"犭 (Hund, Tier) als Sinnteil, 守 als Klangteil (シュ → シュ). Gemeint ist „jagen“.","s":2,"p":[["犭","Hund","b"],["守","bewachen","l"]]},
"魂":{"t":"laut","x":"鬼 (Geist) gibt den Sinnbereich, 云 den Klang. Gemeint ist die Seele.","s":2,"p":[["鬼","Geist","b"],["云","sagen","l"]],"i":"s"},
"脚":{"t":"laut","x":"月 steht hier für Fleisch, Körper; 却 (alt 卻) ist der Klangteil (却 キャク → 脚 キャク). Gemeint ist das Bein bzw. der Fuß.","s":2,"p":[["月","Körper","b"],["却","zurück","l"]]},
"也":{"t":"unklar","x":"Die Herkunft ist ungeklärt. Eine neuere Deutung sieht ein weinendes Kind mit offenem Mund, das Zeichen für „weinen“; eine andere sieht eine Abspaltung von 侃. Später wurde 也 als Hilfswort der klassischen Sprache gebraucht.","s":0,"n":"Auch die Deutungen als Frauenkörper (Shuowen), Skorpion oder Schlange sind schwach begründet.","i":"s"},
"井":{"t":"bild","x":"Abgebildet ist ein Brunnen mit quadratischem Rahmen. In alten Formen steht oft ein Punkt in der Mitte (heute 丼), der den Brunnen oder einen Stein darin zeigt.","s":2,"n":"Daneben gab es ein zweites, gleich aussehendes Zeichen für „Rahmen, Form“; es steckt in 形, 刑 und 型.","i":"obs"},
"嬢":{"t":"laut","x":"Die alte Form 孃 besteht aus 女 (Frau) und Klangteil 襄 (ジョウ). Sie bezeichnete ursprünglich die Mutter. In der heutigen Form wurde der Klangteil zu 㐮 verkürzt.","s":2,"p":[["女","Frau","b"],["襄","helfen","l"]],"a":"孃"},
"暦":{"t":"laut","x":"Die alte Form 曆 hat 日 (Tag) als Sinnteil und 厤 als Klangteil (レキ). Gemeint ist der Kalender. In der heutigen Form wurde der Oberteil verkürzt.","s":2,"p":[["日","Sonne, Tag","b"],["厤","Lautteil","l"]],"a":"曆","i":"s"},
"眺":{"t":"laut","x":"目 (Auge) als Sinnteil, 兆 als Klangteil (チョウ → チョウ). Gemeint ist „in die Ferne blicken“.","s":2,"p":[["目","Auge","b"],["兆","Vorzeichen","l"]],"i":"s"},
"裸":{"t":"laut","x":"衤 (Kleidung) als Sinnteil: ohne Kleidung, nackt. 果 liefert den Klang, der früher ähnlicher war (果 カ, 裸 ラ).","s":2,"p":[["衤","Kleidung","b"],["果","Frucht","l"]]},
"塾":{"t":"laut","x":"Ursprünglich schrieb man das Wort für den Raum neben dem Tor allein mit 孰; später kam 土 als Sinnteil hinzu, 孰 blieb Klangteil (ジュク). Daraus wurde „Privatschule“.","s":2,"p":[["孰","wer","l"],["土","Erde","b"]],"i":"s"},
"卓":{"t":"unklar","x":"Die Herkunft ist ungeklärt. Man deutet den oberen Teil als Mensch oder Zeichen und den unteren als 早 oder 昜, doch keine Deutung ist gesichert.","s":0,"n":"Eine Deutung sieht einen Menschen, der auf einem sonnenbeschienenen Altar höher steht.","i":"bs"},
"菌":{"t":"laut","x":"艹 (Pflanze) als Sinnteil, 囷 als Klangteil (キン → キン). Gemeint sind Pilze und daraus Bakterien.","s":2,"p":[["艹","Pflanze","b"],["囷","Kornspeicher","l"]]},
"陰":{"t":"laut","x":"阝 steht für einen Hügel, die dem Licht abgewandte Seite. 侌 liefert den Klang (イン). Es besteht selbst aus 云 (Wolke) und Klangteil 今. Gemeint ist „Schatten“.","s":2,"p":[["阝","Hügel","b"],["侌","beschatten","l"]],"i":"s"},
"霊":{"t":"laut","x":"Die alte Form 靈 enthält 巫 (Schamane, Medium) als Sinnteil und 霝 als Klangteil (レイ). Gemeint ist die Seele. Heute ist 霝 stark verkürzt.","s":2,"p":[["巫","Schamane","b"],["霝","Lautteil","l"]],"n":"In frühen Formen stand statt 巫 auch 玉, 心 oder 示.","a":"靈","i":"s"},
"稼":{"t":"laut","x":"禾 (Getreide) als Sinnteil, 家 als Klangteil (カ → カ). Ursprünglich „Getreide anbauen“, heute „arbeiten, Geld verdienen“.","s":2,"p":[["禾","Getreide","b"],["家","Haus","l"]]},
"嫁":{"t":"laut","x":"女 (Frau) als Sinnteil, 家 als Klangteil (カ → カ). Gemeint ist „einheiraten, Braut“.","s":2,"p":[["女","Frau","b"],["家","Haus","l"]]},
"溝":{"t":"laut","x":"氵 (Wasser) als Sinnteil, 冓 als Klangteil (コウ → コウ). Gemeint ist ein Graben oder Wasserlauf.","s":2,"p":[["氵","Wasser","b"],["冓","Gerüst","l"]]},
"滝":{"t":"laut","x":"Die alte Form 瀧 hat 氵 (Wasser) und 龍 als Klangteil. Zuerst schrieb man damit „Nieselregen“, später wurde sie für „Wasserfall“ ausgeliehen. In 滝 ist 龍 zu 竜 vereinfacht.","s":2,"p":[["氵","Wasser","b"],["竜","Drache","l"]],"a":"瀧"},
"狂":{"t":"laut","x":"犭 (Hund, Tier) als Sinnteil, daneben ein Klangteil. Dieser sieht heute wie 王 aus, ist aber die alte Form von 往.","s":2,"p":[["犭","Hund","b"],["王","König","l"]],"i":"os"},
"翔":{"t":"laut","x":"羽 (Federn) als Sinnteil: Flügel, fliegen. 羊 ist der Klangteil; früher klangen beide ähnlicher (羊 ヨウ, 翔 ショウ).","s":2,"p":[["羽","Feder","b"],["羊","Schaf","l"]]},
"墨":{"t":"laut","x":"Ursprünglich schrieb man „Tusche“ allein mit 黑, dem Klangteil. Später kam 土 als Sinnteil hinzu. Der Aufbau ist heute 黒 über 土.","s":2,"p":[["黒","schwarz","l"],["土","Erde","b"]]},
"鳩":{"t":"laut","x":"鳥 (Vogel) als Sinnteil, 九 als Klangteil (キュウ → キュウ). Gemeint ist die Taube.","s":2,"p":[["九","neun","l"],["鳥","Vogel","b"]],"n":"Oft liest man, 九 gebe den Ruf der Taube wieder. Das gilt als Volksetymologie ohne Beleg.","i":"s"},
"穏":{"t":"laut","x":"Die alte Form 穩 besteht aus 禾 und dem Klangteil 㥯 (オン). Gemeint ist „ruhig, friedlich“. In der heutigen Form ist der Klangteil verkürzt.","s":1,"p":[["禾","Getreide","b"],["㥯","Lautteil","l"]],"a":"穩","i":"s"},
"魔":{"t":"laut","x":"鬼 (Geist) als Sinnteil, 麻 als Klangteil (マ). Das Zeichen entstand erst später, um den buddhistischen Dämon Māra in 魔羅 zu schreiben.","s":2,"p":[["麻","Hanf","l"],["鬼","Geist","b"]],"n":"Die Deutung „Hanf betäubt den Geist“ ist ein Kunstgriff: 麻 gibt hier nur den Klang."},
"寮":{"t":"laut","x":"宀 (Dach, Haus) als Sinnteil, 尞 als Klangteil (リョウ → リョウ). Gemeint ist ein Haus für mehrere Bewohner, das Wohnheim.","s":2,"p":[["宀","Dach","b"],["尞","Lautteil","l"]],"n":"Eine ältere Sinn-und-Klang-Deutung des 尞 gilt als falsch.","i":"obs"},
"盆":{"t":"laut","x":"皿 (Schale) als Sinnteil, 分 als Klangteil. Gemeint ist ein Becken oder Tablett.","s":2,"p":[["分","teilen","l"],["皿","Schale","b"]],"i":"bs"},
"棟":{"t":"laut","x":"木 (Holz) als Sinnteil, 東 als Klangteil (トウ → トウ). Gemeint ist der Dachfirst, der Firstbalken; daraus „Gebäude“.","s":2,"p":[["木","Holz","b"],["東","Osten","l"]]},
"寧":{"t":"kombi","x":"Eine frühe Form zeigt Dach, Schale und ein Gefäß als Bild für „zufrieden“; später kam das Herz 心 dazu. Eine andere Sicht sieht ein Gemisch aus zwei Zeichen: Gebet mit Opferschale (Ruhe) und „Herz in Ruhe“ unter dem Dach.","s":0,"p":[["宀","Dach","b"],["心","Herz","b"],["皿","Schale","b"]],"n":"Der Aufbau wird unterschiedlich erklärt; gesichert ist nur das Thema „Ruhe, Frieden“.","i":"obs"},
"猿":{"t":"laut","x":"犭 (Tier) als Sinnteil, 袁 als Klangteil (エン → エン). Gemeint ist der Affe.","s":2,"p":[["犭","Tier","b"],["袁","Lautteil","l"]],"n":"Das Zeichen ist eine Variante von 猨 mit ausgetauschtem Klangteil."},
"瞳":{"t":"laut","x":"目 (Auge) als Sinnteil, 童 als Klangteil (ドウ → ドウ). Gemeint ist die Pupille.","s":2,"p":[["目","Auge","b"],["童","Kind","l"]]},
"碁":{"t":"laut","x":"石 (Stein) als Sinnteil, 其 als Klangteil. Das Zeichen ist eine Variante von 棊, bei der 木 durch 石 ersetzt wurde, passend zu den Go-Steinen.","s":2,"p":[["其","Lautteil","l"],["石","Stein","b"]]},
"租":{"t":"laut","x":"禾 (Getreide) als Sinnteil, 且 als Klangteil. Grundrente wurde in Getreide gezahlt, daher „Abgabe, Pacht“.","s":2,"p":[["禾","Getreide","b"],["且","Lautteil","l"]],"i":"s"},
"幽":{"t":"laut","x":"Der Berg 山 gibt den Sinnbereich, zweimal 幺 den Klang (ユウ). Gemeint ist „tief, verborgen“.","s":1,"p":[["山","Berg","b"],["幺","fein","l"]],"n":"Früher las man die Mitte als Feuer; neuere Befunde sprechen für einen Berg. Die Deutung als Sinnverbindung gilt als falsch.","i":"s"},
"泡":{"t":"laut","x":"氵 (Wasser) als Sinnteil, 包 als Klangteil (ホウ → ホウ). Gemeint ist die Blase, der Schaum.","s":2,"p":[["氵","Wasser","b"],["包","einwickeln","l"]],"i":"s"},
"癖":{"t":"laut","x":"疒 (Krankheit) als Sinnteil, 辟 als Klangteil (ヘキ → ヘキ). Zuerst war eine bestimmte Magenkrankheit gemeint, später „Angewohnheit, Eigenart“.","s":2,"p":[["疒","Krankheit","b"],["辟","Lautteil","l"]]},
"鍛":{"t":"laut","x":"金 (Metall) als Sinnteil, 段 als Klangteil. Gemeint ist „schmieden, hämmern“; daraus „trainieren, stählen“.","s":2,"p":[["釒","Metall","b"],["段","Stufe","l"]]},
"錬":{"t":"laut","x":"Die alte Form 鍊 hat 金 (Metall) als Sinnteil und 柬 als Klangteil. In der heutigen Form wurde 柬 durch das ähnliche 東 ersetzt.","s":2,"p":[["釒","Metall","b"],["柬","Lautteil","l"]],"n":"Eine Deutung mit Sinn im Klangteil gilt als haltlos.","a":"鍊","i":"s"},
"穂":{"t":"laut","x":"Die alte Form 穗 hat 禾 (Getreide) und den Klangteil 惠. Gemeint ist die Ähre. In der heutigen Form wurde 惠 wie bei 恵 verkürzt.","s":2,"p":[["禾","Getreide","b"],["恵","Gnade","l"]],"a":"穗","i":"s"},
"帝":{"t":"leih","x":"Der Ursprung ist nicht eindeutig. Frühe Formen zeigen wohl eine Blüte mit Kelch (蒂); andere deuten Holz für das Opfer 禘. Später wurde das Zeichen für das höchste Wesen, dann den Herrscher verwendet.","s":1,"i":"obs"},
"瞬":{"t":"laut","x":"目 (Auge) als Sinnteil, 舜 als Klangteil (シュン → シュン). Gemeint ist „blinzeln“, daraus „Augenblick“.","s":2,"p":[["目","Auge","b"],["舜","Lautteil","l"]]},
"菊":{"t":"laut","x":"艹 (Pflanze) als Sinnteil, 匊 als Klangteil (キク). Gemeint ist die Chrysantheme.","s":2,"p":[["艹","Pflanze","b"],["匊","Lautteil","l"]],"n":"Eine Deutung als Sinnverbindung gilt als falsch.","i":"s"},
"誇":{"t":"laut","x":"訁 (Sprache) als Sinnteil, 夸 als Klangteil. Gemeint ist „prahlen, stolz sein“.","s":2,"p":[["訁","Wort","b"],["夸","prahlen","l"]]},
"庄":{"t":"laut","x":"Die alte Form 莊 hat 艹 als Sinnteil und 壯 als Klangteil. Gemeint ist ein Landgut. Die heutige Form 庄 stammt aus der Schreibschrift und wirkt anders aufgebaut.","s":1,"p":[["艹","Pflanze","b"],["壯","kräftig","l"]],"a":"莊"},
"阻":{"t":"laut","x":"阝 (Hügel) als Sinnteil, 且 als Klangteil (ソ → ソ). Gemeint ist „steil, im Weg sein“, daraus „verhindern“.","s":2,"p":[["阝","Hügel","b"],["且","Lautteil","l"]],"i":"s"},
"黙":{"t":"laut","x":"Die alte Form 默 hat 犬 als Sinnteil und 黑 als Klangteil. In der heutigen Form ist 黑 zu 黒 vereinfacht. Gemeint ist „schweigen“.","s":1,"p":[["黒","schwarz","l"],["犬","Hund","b"]],"a":"默","i":"s"},
"俵":{"t":"laut","x":"亻 (Mensch) als Sinnteil, 表 als Klangteil (ヒョウ → ヒョウ). Ursprünglich „verteilen“; heute der Strohsack.","s":2,"p":[["亻","Mensch","b"],["表","außen","l"]]},
"架":{"t":"laut","x":"Links Holz als Sinnteil, 加 (カ) als Klangteil. Gemeint ist ursprünglich ein hölzernes Gestell oder eine Stütze; daraus wurde „Gerüst, aufstellen, Regal“.","s":1,"p":[["木","Holz","b"],["加","hinzufügen","l"]]},
"砕":{"t":"laut","x":"Die alte Form 碎 hatte 石 (Stein) als Sinnteil und 卒 (ソツ) als Klangteil: Stein, der zerspringt. Heute ist 卒 zu 卆 verkürzt, der Aufbau ist sonst gleich.","s":2,"p":[["石","Stein","b"],["卆","Soldat (Kurzform von 卒)","l"]],"a":"碎","i":"s"},
"粘":{"t":"laut","x":"Reis als Sinnteil, 占 (セン) als Klangteil. Gemeint ist klebriger Reis, daraus „klebrig, zäh sein“. Die Form entstand, indem bei der älteren Variante 黏 der linke Teil durch 米 ersetzt wurde.","s":2,"p":[["米","Reis","b"],["占","einnehmen","l"]]},
"欺":{"t":"laut","x":"欠 steht als Sinnteil für einen Menschen mit offenem Mund (Atem, Sprechen), 其 (キ, ギ) liefert den Klang. Die Bedeutung ist „betrügen, täuschen“.","s":2,"p":[["欠","Atem, offener Mund","b"],["其","Klangteil","l"]],"i":"s"},
"詐":{"t":"laut","x":"言 (Wort, Sprechen) gibt den Sinnbereich, 乍 liefert den Klang (heute サ wie in 詐欺). Es meint „mit Worten täuschen, lügen“.","s":2,"p":[["言","Wort","b"],["乍","Klangteil","l"]],"i":"s"},
"霧":{"t":"laut","x":"雨 (Regen, Wetter) zeigt den Sinnbereich, 務 (ム) den Klang, der in der On-Lesung ム noch erhalten ist. Es steht für „Nebel“.","s":2,"p":[["雨","Regen","b"],["務","Aufgabe","l"]],"i":"s"},
"柳":{"t":"laut","x":"木 (Baum) als Sinnteil, 卯 als Klangteil: die Weide. Schon in Orakelknochen- und Bronzeschrift war es so aufgebaut; in der Siegelschrift gab es kurz eine Variante mit anderem Klangteil, später kehrte man zu 卯 zurück.","s":2,"p":[["木","Baum","b"],["卯","Klangteil","l"]],"i":"bs"},
"伊":{"t":"unklar","x":"Das Zeichen besteht aus 亻 (Mensch) und 尹. Wie es genau entstand, ist nicht gesichert. Als Lautzeichen wird es oft für fremde Namen benutzt, z. B. 伊太利 (Italien).","s":0,"p":[["亻","Mensch","b"],["尹","Vorsteher","l"]],"n":"Eine Deutung sieht 尹 als Klangteil. Neuere Forschung hält das für unpassend: in den frühen Schriftformen steht unter dem Zeichen eher ein hockender Mensch (尸), dessen Klangteil anders lautet.","i":"obs"},
"佐":{"t":"laut","x":"亻 (Mensch) als Sinnteil, 左 (サ) als Klangteil. Gemeint ist „jemandem helfen“; daraus „Gehilfe, Assistent“. Die Lesung サ stammt direkt vom Klangteil.","s":2,"p":[["亻","Mensch","b"],["左","links","l"]]},
"尺":{"t":"unklar","x":"Der Ursprung dieses Zeichens für die Längeneinheit „Shaku“ ist nicht geklärt. Es gilt als vereinfachte Variante älterer Formen und ist wohl aus ihnen verkürzt worden.","s":0,"n":"Oft liest man, es zeige eine Hand, die mit gespreiztem Daumen und Mittelfinger eine Länge abmisst. Das passt laut neuerer Forschung nicht zu den frühen Schriftformen.","i":"s"},
"哀":{"t":"laut","x":"口 (Mund, Klage) als Sinnteil, 衣 (イ) als Klangteil. Das Zeichen steht für „bemitleiden, Trauer“.","s":2,"p":[["口","Mund","b"],["衣","Kleidung","l"]],"n":"Oft liest man, in 衣 stecke ein Tuch, in das man beim Weinen den Mund verbirgt. In den Quellen ist 衣 nur der Klangteil."},
"唇":{"t":"laut","x":"口 (Mund) als Sinnteil, 辰 (シン) als Klangteil: die Lippe. Die Lesung シン kommt vom Klangteil.","s":2,"p":[["口","Mund","b"],["辰","Klangteil","l"]]},
"塀":{"t":"laut","x":"Ein in Japan gebildetes Zeichen: 土 (Erde) als Sinnteil, 屏 (ヘイ) als Klangteil. Es meint eine Mauer oder einen Zaun aus Erde und Stein.","s":1,"p":[["土","Erde","b"],["屏","Schirm, Wand","l"]]},
"墜":{"t":"laut","x":"Ursprünglich schrieb man „fallen“ nur mit 隊 (ツイ). Später kam 土 (Erde, Boden) als Sinnteil dazu: etwas stürzt zu Boden. Die Lesung ツイ steckt noch im Klangteil.","s":2,"p":[["隊","Gruppe","l"],["土","Erde","b"]]},
"如":{"t":"leih","x":"Zuerst wurde 女 nur wegen des ähnlichen Klangs für das Wort „wie, gleich“ ausgeliehen. Später fügte man 口 als Unterscheidungszeichen hinzu, damit man das Wort vom Zeichen für „Frau“ trennen kann.","s":1,"p":[["女","Frau","l"],["口","Mund","f"]],"i":"obs"},
"婆":{"t":"laut","x":"女 (Frau) als Sinnteil, 波 (ハ) als Klangteil. Gemeint ist die ältere Frau, „Großmutter, alte Frau“; so auch in 産婆.","s":2,"p":[["女","Frau","b"],["波","Welle","l"]]},
"幣":{"t":"laut","x":"巾 (Tuch) als Sinnteil, 敝 (ヘイ) als Klangteil. Gemeint war Stoff, der bei Zeremonien als Gabe oder Opfer diente; daraus wurde „Gabe“ und später „Geld“.","s":2,"p":[["敝","Klangteil","l"],["巾","Tuch","b"]]},
"恨":{"t":"laut","x":"忄 (Herz, Gefühl) als Sinnteil, 艮 (コン) als Klangteil. Das Zeichen steht für „grollen, bereuen“.","s":2,"p":[["忄","Herz","b"],["艮","Klangteil","l"]]},
"憩":{"t":"laut","x":"息 (Atem, Ruhe) als Sinnteil, dazu ein Klangteil 𠯑 (links oben, heute wie 舌 geschrieben). Gemeint ist „rasten, ausruhen“.","s":0,"p":[["息","Atem, Ruhe","b"],["𠯑","Klangteil","l"]],"n":"Eine zweite Deutung sieht eine Abkürzung aus 恬 („ruhig“) und 息 („ausruhen“): ein Sinnverbindungszeichen."},
"扇":{"t":"kombi","x":"Der obere Teil sieht aus wie 戸 (Tür), ist aber ursprünglich ein Bild eines Fächers und hat mit „Tür“ nichts zu tun. Später kam 羽 (Feder, Flügel) als Sinnteil dazu: der Fächer.","s":1,"p":[["戸","Fächerform","f"],["羽","Feder","b"]],"n":"Oft liest man „Tür + Federn = Fächer“. Die Tür steckt aber nicht im Zeichen."},
"扉":{"t":"laut","x":"戸 (Tür) als Sinnteil, 非 (ヒ) als Klangteil: die Flügeltür. Die On-Lesung ヒ stammt vom Klangteil.","s":2,"p":[["戸","Tür","b"],["非","nicht","l"]],"n":"Manchmal liest man, 非 deute zugleich auf zwei auseinandergehende Türflügel. Das gilt als falsche Analyse."},
"挿":{"t":"laut","x":"Die alte Form 插 hatte 扌 (Hand) als Sinnteil und 臿 (ソウ) als Klangteil: etwas hineinstecken. 臿 zeigt selbst, wie ein Pfeil im Köcher steckt. In 挿 ist der rechte Teil vereinfacht.","s":2,"p":[["扌","Hand","b"],["臿","Stößel, Pfeil im Köcher","l"]],"a":"插"},
"掌":{"t":"laut","x":"手 (Hand) als Sinnteil, 尚 (ショウ) als Klangteil: die Handfläche. Daraus entstand auch „in der Hand haben, verwalten“.","s":2,"p":[["尚","noch, hochschätzen","l"],["手","Hand","b"]],"i":"s"},
"炊":{"t":"kombi","x":"Eine Person mit offenem Mund beugt sich zum Feuer, etwa um es anzublasen. Daraus wurde „kochen, Reis garen“.","s":1,"p":[["火","Feuer","b"],["欠","Mensch mit offenem Mund","b"]],"n":"Eine ältere Erklärung deutet das Zeichen als 火 plus Klangteil 吹. Neuere Forschung sieht es umgekehrt: 吹 ist später aus 炊 entstanden."},
"爽":{"t":"unklar","x":"Der ursprüngliche Aufbau ist nicht geklärt. Die frühen Formen zeigen wohl einen Menschen mit etwas unter den Armen. Das Zeichen stand zuerst für ein anderes Wort („helfen“) und wurde später für „frisch, erfrischend“ ausgeliehen.","s":0,"n":"Oft liest man, die Doppel-X-Zeichen stünden für Tätowierungen auf der Brust. Dafür gibt es keinen Beleg.","i":"obs"},
"瞭":{"t":"laut","x":"目 (Auge) als Sinnteil, 尞 (リョウ) als Klangteil. Mit den Augen klar sehen, daraus „deutlich, klar“.","s":2,"p":[["目","Auge","b"],["尞","Klangteil","l"]]},
"胴":{"t":"laut","x":"月 (hier für Fleisch, Körper) als Sinnteil, 同 (ドウ) als Klangteil. Ursprünglich war „Dickdarm“ gemeint; später nahm das Wort die Bedeutung „Rumpf“ an.","s":2,"p":[["月","Fleisch","b"],["同","gleich","l"]]},
"虹":{"t":"laut","x":"虫 (Tier, Kriechtier) als Sinnteil, 工 (コウ) als Klangteil: der Regenbogen. Die Alten sahen ihn als Lebewesen. In der Orakelknochenschrift war das Zeichen noch ein Bild eines zweiköpfigen Drachen.","s":2,"p":[["虫","Tier","b"],["工","Arbeit","l"]],"i":"os"},
"帳":{"t":"laut","x":"巾 (Tuch) als Sinnteil, 長 (チョウ) als Klangteil. Ursprünglich ein Vorhang oder Zeltstoff; später wurde daraus die gebundene „Heftform“, daher „Notizbuch“.","s":2,"p":[["巾","Tuch","b"],["長","lang","l"]],"i":"s"},
"蚊":{"t":"laut","x":"虫 (Insekt) als Sinnteil, 文 (ブン) als Klangteil: die Stechmücke.","s":2,"p":[["虫","Insekt","b"],["文","Schrift","l"]],"n":"Oft heißt es, 文 (ブン) ahme das Summen der Mücke nach. Das ist eine Volksdeutung: 文 gibt nur den Klang des Wortes."},
"蛇":{"t":"laut","x":"Ursprünglich genügte 它 für „Schlange“, es war ein Bild davon. Später kam 虫 (Kriechtier) als Sinnteil dazu, weil 它 auch für anderes verwendet wurde. 它 liefert zugleich den Klang.","s":2,"p":[["虫","Kriechtier","b"],["它","Schlange","l"]],"i":"s"},
"辱":{"t":"leih","x":"Eine Hand hält ein Steinwerkzeug: Unkraut jäten, den Acker bearbeiten. Das Zeichen wurde später für den gleich klingenden Begriff „beschämen, demütigen“ ausgeliehen.","s":2,"p":[["辰","Steinhacke","b"],["寸","Hand","b"]]},
"鉢":{"t":"laut","x":"Die alte Form 缽 setzte 缶 (Tongefäß) und 本 zusammen. Die heutige Form hat 金 (Metall) als Sinnteil, daher „Schale, Becken“. Beide Formen haben 本 als Klangteil, doch gilt das nicht als ganz sicher.","s":1,"p":[["金","Metall","b"],["本","Klangteil","l"]],"n":"Ein Teil der Forschung sieht in 本 eine Verschreibung eines anderen Zeichens (犮), das den Klang besser erklärt.","a":"缽"},
"霜":{"t":"laut","x":"雨 (Regen, Wetter) als Sinnteil, 相 (ソウ) als Klangteil: der Reif oder Frost.","s":2,"p":[["雨","Regen, Wetter","b"],["相","gegenseitig","l"]]},
"飢":{"t":"laut","x":"飠 (Essen) als Sinnteil, 几 (キ) als Klangteil: Hunger leiden. Die Lesung キ stammt vom Klangteil.","s":2,"p":[["飠","Essen","b"],["几","Tisch","l"]]},
"餓":{"t":"laut","x":"飠 (Essen) als Sinnteil, 我 (ガ) als Klangteil: verhungern, hungern. Die Lesung ガ stammt vom Klangteil.","s":2,"p":[["飠","Essen","b"],["我","ich","l"]],"i":"s"},
"迅":{"t":"laut","x":"辶 (Weg, Bewegung) als Sinnteil, 卂 (シン) als Klangteil. Gemeint ist schnelle Bewegung, daher „schnell, flink“.","s":2,"p":[["辶","gehen","b"],["卂","Klangteil","l"]],"i":"s"},
"騎":{"t":"laut","x":"馬 (Pferd) als Sinnteil, 奇 (キ) als Klangteil: auf einem Pferd reiten. Die Lesung キ stammt vom Klangteil.","s":2,"p":[["馬","Pferd","b"],["奇","seltsam","l"]]},
"蓄":{"t":"laut","x":"艹 (Pflanze) als Sinnteil, 畜 (チク) als Klangteil. Gemeint ist, Vorräte wie Getreide aufzuheben; daraus „sparen, anhäufen“.","s":2,"p":[["艹","Pflanze","b"],["畜","Vieh","l"]]},
"尽":{"t":"kombi","x":"Die alte Form 盡 zeigt eine Hand mit Bürste, die eine Schale auswäscht, bis sie leer ist. Daraus „leer werden, aufgebraucht sein“. In 尽 ist das Zeichen stark verkürzt.","s":2,"p":[["聿","Hand mit Pinsel","b"],["皿","Schale","b"]],"n":"Manchmal liest man „Pinsel + Feuer + Schale“. Die frühen Schriftformen bestätigen das nicht.","a":"盡","i":"obs"},
"彩":{"t":"laut","x":"彡 steht für Schmuck oder Farbmuster und gibt den Sinnbereich, 采 (サイ) den Klang. Es meint „Farbe, Glanz“.","s":2,"p":[["采","pflücken","l"],["彡","Farbstreifen","b"]],"i":"s"},
"憶":{"t":"laut","x":"忄 (Herz, Denken) als Sinnteil, 意 (イ) als Klangteil. Gemeint ist „sich erinnern, im Gedächtnis behalten“.","s":2,"p":[["忄","Herz","b"],["意","Sinn","l"]]},
"耐":{"t":"laut","x":"寸 (Hand, Maß) als Sinnteil, 而 als Klangteil. Das Zeichen steht für „aushalten, durchstehen“.","s":1,"p":[["而","Klangteil","l"],["寸","Hand","b"]]},
"輝":{"t":"laut","x":"光 (Licht) als Sinnteil, 軍 als Klangteil: „glänzen, strahlen“. Das Zeichen ist eine Variante von 煇, bei der man den Teil links ausgetauscht hat.","s":2,"p":[["光","Licht","b"],["軍","Heer","l"]]},
"脅":{"t":"laut","x":"月 (Fleisch, Körper) als Sinnteil, 劦 als Klangteil. Ursprünglich war die Seite des Körpers unter den Armen gemeint (Flanke). Später wurde das Zeichen für das gleich klingende „drohen, einschüchtern“ ausgeliehen.","s":2,"p":[["劦","Klangteil","l"],["月","Fleisch","b"]],"n":"Eine ältere Deutung sieht 劦 („zusammenarbeiten“) auch als Sinnteil. Neuere Forschung hält das für falsch.","i":"s"},
"麻":{"t":"unklar","x":"Zusammengesetzt aus 厂 (Fels, Stein) und 𣏟. Nach einer Deutung war ursprünglich „Schleifstein, schleifen“ gemeint; später wurde das Zeichen für das gleich klingende Wort „Hanf“ ausgeliehen.","s":0,"p":[["厂","Fels, Schleifstein","b"],["𣏟","Klangteil","l"]],"n":"Oft liest man, das Zeichen zeige Hanf, der unter einem Dach trocknet (广). Neuere Forschung sieht darin kein Dach; eine andere Deutung liest die Blätter der Hanfpflanze heraus.","i":"bs"},
"培":{"t":"laut","x":"土 (Erde) als Sinnteil, 咅 als Klangteil. Gemeint ist, Erde anzuhäufen, um Pflanzen zu pflegen; daraus „anbauen, heranziehen“.","s":1,"p":[["土","Erde","b"],["咅","Klangteil","l"]]},
"悔":{"t":"laut","x":"忄 (Herz, Gefühl) als Sinnteil, 毎 als Klangteil: etwas bereuen. Die Lesung カイ ähnelt dem älteren Klang des Klangteils.","s":1,"p":[["忄","Herz","b"],["毎","jedes","l"]]},
"遂":{"t":"laut","x":"辶 (Weg, gehen) als Sinnteil, 㒸 als Klangteil. Es bedeutet „zu Ende führen, vollbringen“. Im Klangteil steckt kein Schwein, auch wenn es so aussieht.","s":2,"p":[["辶","gehen","b"],["㒸","Klangteil","l"]],"i":"bs"},
"班":{"t":"kombi","x":"Zwei Jadestücke (玨), in der Mitte teilt ein Messer 刂 sie auseinander. Daraus wurde „aufteilen“, und später „Gruppe, Abteilung“, die entsteht, wenn man etwas aufteilt.","s":2,"p":[["王","Jadestücke","b"],["刂","Messer","b"]],"i":"bs"},
"斜":{"t":"laut","x":"斗 (Schöpfkelle) als Sinnteil, 余 als Klangteil: ursprünglich „mit der Kelle schöpfen“. Das gleich klingende Wort „schräg“ benutzte später dasselbe Zeichen.","s":1,"p":[["余","übrig","l"],["斗","Schöpfkelle","b"]],"i":"s"},
"殴":{"t":"laut","x":"Die alte Form 毆 hatte 殳 (Waffe, Schlagen) als Sinnteil und 區 (ク) als Klangteil: schlagen. In 殴 wurde 區 zu 区 verkürzt.","s":2,"p":[["区","Bezirk","l"],["殳","Schlagstock","b"]],"a":"毆","i":"s"},
"盾":{"t":"bild","x":"Das Zeichen bildete in der Orakelknochenschrift einen Schild ab. Die Form der späteren Zeit ist nicht mehr sicher erklärbar.","s":1,"n":"Eine Deutung sieht in der späteren Form 允 als Klangteil.","i":"obs"},
"穫":{"t":"laut","x":"禾 (Getreide) als Sinnteil, 蒦 (カク) als Klangteil: Getreide einbringen, ernten.","s":2,"p":[["禾","Getreide","b"],["蒦","Klangteil","l"]]},
"駒":{"t":"laut","x":"馬 (Pferd) als Sinnteil, 句 (ク) als Klangteil: ein junges Pferd, ein Fohlen. Der Klang ク steckt in der On-Lesung. Als „Spielstein“ beim Shōgi ist es später übertragen.","s":2,"p":[["馬","Pferd","b"],["句","Satz","l"]],"i":"bs"},
"紫":{"t":"laut","x":"糸 (Faden, Stoff) als Sinnteil, 此 (シ) als Klangteil: eine Farbe von Stoffen, das Violett. Die Lesung シ stammt vom Klangteil.","s":2,"p":[["此","dies","l"],["糸","Faden","b"]],"n":"Manchmal heißt es, 此 gebe zugleich einen Sinn dazu. Das gilt als falsch.","i":"s"},
"抽":{"t":"laut","x":"扌 (Hand) als Sinnteil, 由 als Klangteil: etwas herausziehen. Daraus „herausnehmen, ziehen“.","s":1,"p":[["扌","Hand","b"],["由","Ursprung","l"]]},
"誓":{"t":"laut","x":"言 (Wort, Sprechen) als Sinnteil, 折 (セツ) als Klangteil: etwas feierlich versprechen, schwören.","s":1,"p":[["言","Wort","b"],["折","brechen","l"]],"i":"bs"},
"悟":{"t":"laut","x":"忄 (Herz, Geist) als Sinnteil, 吾 (ゴ) als Klangteil. Gemeint ist „erkennen, begreifen“. Die Lesung ゴ stammt vom Klangteil.","s":2,"p":[["忄","Herz","b"],["吾","ich","l"]]},
"拓":{"t":"laut","x":"扌 (Hand) als Sinnteil, 石 als Klangteil: mit den Händen Steine wegräumen, Land öffnen. Der Klang タク stimmt mit dem alten Klang von 石 überein, der heutigen Lesung セキ nach nicht mehr.","s":1,"p":[["扌","Hand","b"],["石","Stein","l"]],"i":"s"},
"拘":{"t":"laut","x":"扌 (Hand) als Sinnteil, 句 als Klangteil. Es bedeutet „festhalten, ergreifen“; daraus „verhaften“ und „an etwas haften“.","s":2,"p":[["扌","Hand","b"],["句","Satz","l"]],"i":"bs"},
"礎":{"t":"laut","x":"石 (Stein) als Sinnteil, 楚 (ソ) als Klangteil: ein Stein als Unterlage für Säulen. Daraus „Grundstein, Fundament“.","s":2,"p":[["石","Stein","b"],["楚","Klangteil","l"]]},
"鶴":{"t":"laut","x":"Zuerst schrieb man „Kranich“ allein mit 隺, einem Vogel (隹) mit hervorgehobenem Hals. Später kam 鳥 (Vogel) als Sinnteil dazu. 隺 liefert zugleich den Klang (カク).","s":2,"p":[["隺","Klangteil","l"],["鳥","Vogel","b"]]},
"刈":{"t":"laut","x":"Ursprünglich genügte 乂 für „mähen“. Später kam 刂 (Messer) dazu, um das Wort vom anderen Wort 乂 zu trennen. 乂 gibt den Klang (ガイ), 刂 den Sinn.","s":2,"p":[["乂","Sichel","l"],["刂","Messer","b"]],"i":"s"},
"剛":{"t":"laut","x":"Ursprünglich schrieb man mit diesem Zeichen „Hügel“: 山 (Berg) als Sinnteil, der Rest als Klangteil. Später wurde es für das gleich klingende Wort „hart, stark“ ausgeliehen; 岡 ist eine Kurzform davon.","s":1,"p":[["山","Berg","b"],["网","Netz","l"],["刀","Messer","l"]],"n":"Das Shuowen wertet 岡 als Klangteil und 刀 als Sinn. Das gilt heute als falsch."},
"唯":{"t":"laut","x":"口 (Mund, Laut) als Sinnteil, 隹 (イ, ユイ) als Klangteil. Ursprünglich ein Wort für den Ruf eines Vogels oder die Antwort „ja“. Später für „nur, allein“ ausgeliehen.","s":1,"p":[["口","Mund","b"],["隹","Vogel","l"]],"i":"s"},
"壇":{"t":"laut","x":"土 (Erde) als Sinnteil, 亶 (タン, ダン) als Klangteil. Gemeint ist ein erhöhter Platz aus Erde, ein Podium oder Altar.","s":2,"p":[["土","Erde","b"],["亶","Klangteil","l"]]},
"尼":{"t":"kombi","x":"Ein Mensch (尸) sitzt auf dem Rücken eines anderen (匕): sehr eng beieinander, „nahe“. Später wurde das Zeichen für das gleich klingende Wort „Nonne“ ausgeliehen.","s":2,"p":[["尸","Mensch","b"],["匕","Mensch","b"]],"n":"Das Shuowen sah im Zeichen einen Klangteil. Spätere Forscher halten das für widerlegt.","i":"s"},
"概":{"t":"laut","x":"木 (Holz) als Sinnteil, 既 (キ) als Klangteil. Ursprünglich ein Holzstab zum Abstreichen von Getreide im Maß. Daraus wurde „Maß“ und „Überblick“.","s":1,"p":[["木","Holz","b"],["既","bereits","l"]]},
"浸":{"t":"laut","x":"氵 (Wasser) als Sinnteil, 𠬶 (シン) als Klangteil: in Wasser tauchen, einweichen, daraus „durchdringen“.","s":2,"p":[["氵","Wasser","b"],["𠬶","Klangteil","l"]]},
"淡":{"t":"laut","x":"Links das Wasser-Zeichen als Sinnteil, rechts 炎 als Klangteil (エン → タン). Gemeint ist ursprünglich Flüssigkeit, die „dünn“ und blass ist; daraus „schwach, hell, dezent“.","s":2,"p":[["氵","Wasser","b"],["炎","Flamme","l"]]},
"煮":{"t":"laut","x":"Unten das Feuer-Zeichen (灬) als Sinnteil, oben 者 als Klangteil (シャ). Es steht für „kochen, sieden“ über dem Feuer.","s":2,"p":[["灬","Feuer","b"],["者","Person","l"]],"n":"Manchmal wird 者 auch als bedeutungstragend gedeutet. Das gilt heute als falsche Analyse; 者 liefert nur den Klang."},
"覆":{"t":"laut","x":"Oben 襾 („bedecken“) als Sinnteil, darunter 復 als Klangteil (フク). Das Zeichen steht für „umstülpen, umkippen“ und „bedecken“.","s":1,"p":[["襾","Deckel","b"],["復","zurückkehren","l"]],"n":"Die Form 襾 sieht in 賈 gleich aus, hat aber einen anderen Ursprung. Woher 襾 selbst stammt, ist nicht sicher geklärt.","i":"s"},
"謀":{"t":"laut","x":"Links 言 („Wort, sprechen“) als Sinnteil, rechts 某 als Klangteil (ボウ). Gemeint ist „planen, beraten“, auch heimlich: „Plan, Verschwörung“.","s":2,"p":[["言","Sprechen","b"],["某","gewisser","l"]],"i":"s"},
"陶":{"t":"laut","x":"Links das Hügel-Zeichen (阝), rechts 匋 als Klangteil (トウ). Das Zeichen stand zuerst für einen Ortsnamen und wurde dann für „Keramik, Töpferware“ ausgeliehen.","s":1,"p":[["阝","Hügel","b"],["匋","Töpferware","l"]],"n":"Auf Orakelknochen sieht man eher Hügel, Menschen und Erde (graben). Der heutige Aufbau mit 匋 kam später.","i":"bs"},
"隔":{"t":"laut","x":"Links das Hügel-/Mauer-Zeichen (阝) als Sinnteil, rechts 鬲 als Klangteil (カク). Gemeint ist „durch eine Wand trennen“, also „abtrennen, Abstand“.","s":2,"p":[["阝","Mauer","b"],["鬲","Dreifußtopf","l"]],"i":"s"},
"征":{"t":"laut","x":"Links 彳 („gehen, marschieren“) als Sinnteil, rechts 正 als Klangteil (セイ). Ursprünglich schrieb man das Wort „Feldzug, erobern“ schon mit 正 allein; 彳 wurde ergänzt.","s":2,"p":[["彳","gehen","b"],["正","richtig","l"]]},
"陛":{"t":"laut","x":"Links das Hügel-/Stufen-Zeichen (阝) als Sinnteil, rechts 坒 als Klangteil (ヘイ). Gemeint sind die Stufen zum Thron; später als Titel „Eure Majestät“ (陛下).","s":1,"p":[["阝","Hügel","b"],["坒","Klangteil","l"]]},
"俗":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 谷 als Klangteil (コク → ゾク). Gemeint sind die Bräuche und Gewohnheiten der Menschen; daraus „gewöhnlich, weltlich“.","s":2,"p":[["亻","Mensch","b"],["谷","Tal","l"]],"i":"bs"},
"桑":{"t":"bild","x":"Ein Bildzeichen: ein Maulbeerbaum. Das Laub oben ist heute zu 叒 geworden, darunter steht 木 für Stamm und Wurzeln.","s":2,"n":"Die alte Erklärung, es sei aus 叒 und 木 zusammengesetzt, stimmt laut den Orakelknochen-Formen nicht.","i":"os"},
"潤":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 閏 als Klangteil (ジュン). Gemeint ist reichlich Feuchtigkeit: „feucht, befeuchten“; daraus auch „Gewinn“.","s":2,"p":[["氵","Wasser","b"],["閏","Schaltmonat","l"]]},
"珠":{"t":"laut","x":"Links das Jade-Zeichen (王, ursprünglich 玉) als Sinnteil, rechts 朱 als Klangteil (シュ). Es steht für Perlen und Edelsteinkugeln.","s":2,"p":[["王","Jade","b"],["朱","Zinnoberrot","l"]]},
"衰":{"t":"leih","x":"Ursprünglich ein Bildzeichen für einen Regenumhang aus Gras oder Palmfasern; später kam 衣 dazu (heute 蓑). Das Zeichen wurde dann für das gleich klingende Wort „schwach werden, verfallen“ ausgeliehen.","s":2,"p":[["衣","Kleid","b"]],"i":"obs"},
"奨":{"t":"laut","x":"Die alte Form 獎 hatte 將 als Klangteil (ショウ) und 犬 darunter; wozu 犬 diente, ist unklar. Heute steht 将 über 大, denn 犬 wurde zu 大 vereinfacht. Das Zeichen bedeutet „ermuntern, fördern“.","s":1,"p":[["将","Anführer","l"],["大","groß","f"]],"a":"獎"},
"劣":{"t":"kombi","x":"„Wenig“ (少) und „Kraft“ (力) zusammen: zu wenig Kraft, also unterlegen. Daraus „schlechter, minderwertig“.","s":2,"p":[["少","wenig","b"],["力","Kraft","b"]],"i":"s"},
"勘":{"t":"laut","x":"Rechts 力 („Kraft“) als Sinnteil, links 甚 als Klangteil (ジン, alt ähnlich カン). Gemeint ist „genau, kräftig hinsehen“; daraus „prüfen, Gespür“.","s":1,"p":[["力","Kraft","b"],["甚","sehr","l"]],"i":"s"},
"妃":{"t":"kombi","x":"Eine Frau neben einer knienden Gestalt: ein Paar, das nebeneinander kniet. Das Zeichen schrieb zuerst „Partner, zusammenpassen“ (配) und wurde dann für „Kaiserin, Gemahlin“ ausgeliehen.","s":2,"p":[["女","Frau","b"],["己","Kniender","b"]],"n":"Das rechte Bauteil sieht heute wie 己 aus, ist aber ursprünglich ein kniender Mensch (卩). Die alte Erklärung „Frau + Klangteil 己“ stimmt nicht."},
"峰":{"t":"laut","x":"Links 山 (Berg) als Sinnteil, rechts 夆 als Klangteil (ホウ). Es steht für den „Gipfel“.","s":2,"p":[["山","Berg","b"],["夆","Klangteil","l"]],"n":"Oft liest man „dort, wo sich die Berggrate treffen“. Das ist eine nachträgliche Deutung; 夆 liefert nur den Klang."},
"巧":{"t":"laut","x":"Links 工 (Handwerk, Arbeit) als Sinnteil, rechts 丂 als Klangteil (コウ). Gemeint ist handwerkliches Geschick: „geschickt, kunstvoll“.","s":1,"p":[["工","Handwerk","b"],["丂","Klangteil","l"]]},
"邪":{"t":"laut","x":"Rechts das Stadt-Zeichen (阝) als Sinnteil, links 牙 als Klangteil. Es war zuerst ein Ortsname und wurde dann für „falsch, böse“ ausgeliehen (ジャ).","s":2,"p":[["牙","Zahn","l"],["阝","Stadt","b"]],"i":"s"},
"駄":{"t":"laut","x":"Links 馬 (Pferd) als Sinnteil, rechts 太 als Klangteil (タイ → ダ/タ). Gemeint ist „Lasten auf einem Pferd tragen“; daraus „Packlast, wertlos“.","s":2,"p":[["馬","Pferd","b"],["太","dick","l"]]},
"廷":{"t":"kombi","x":"Nach heutiger Forschung steckt ein Mensch (人) auf Boden (土) in einer Ecke eines Geländes. Gemeint ist der Hof, wo man vor dem Herrscher steht: „Hof, Gericht“.","s":0,"p":[["土","Erde","b"],["人","Mensch","b"]],"n":"Die Erklärung „廴 + Klangteil 𡈼“ aus dem alten Wörterbuch stimmt nach den Bronzeformen nicht. Eine Minderheitsmeinung sieht Klangteil 㐱.","i":"bs"},
"簿":{"t":"laut","x":"Oben 竹 (Bambus) als Sinnteil, darunter 溥 als Klangteil (フ → ボ). Das Zeichen steht für „Register, Buch“.","s":1,"p":[["竹","Bambus","b"],["溥","weit","l"]],"i":"s"},
"彰":{"t":"laut","x":"Rechts 彡 (farbige Muster) als Sinnteil, links 章 als Klangteil (ショウ). Gemeint ist „auffällig, glänzend“, daraus „würdigen, ehren“.","s":2,"p":[["章","Abzeichen","l"],["彡","Muster","b"]],"i":"s"},
"漫":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 曼 als Klangteil (マン). Das Bild: Wasser, das sich weit ausbreitet und überläuft. Daraus „planlos, ausufernd“.","s":2,"p":[["氵","Wasser","b"],["曼","weit","l"]]},
"訂":{"t":"laut","x":"Links 言 (Wort, sprechen) als Sinnteil, rechts 丁 als Klangteil (テイ). Das Zeichen schrieb „absprechen, festlegen“; daraus „berichtigen, bestellen“.","s":2,"p":[["言","Sprechen","b"],["丁","Nagel","l"]],"i":"s"},
"諮":{"t":"laut","x":"Links 言 (sprechen) als Sinnteil, rechts 咨 als Klangteil (シ). Gemeint ist, jemanden um Rat zu fragen: „befragen, konsultieren“.","s":2,"p":[["言","Sprechen","b"],["咨","beraten","l"]]},
"銘":{"t":"laut","x":"Links das Metall-Zeichen (釒) als Sinnteil, rechts 名 als Klangteil (メイ). Gemeint ist, einen Namen in Metall einzugravieren: „Inschrift“.","s":2,"p":[["釒","Metall","b"],["名","Name","l"]],"n":"Man kann 名 („Name“) auch als Bedeutungsteil lesen: ein Name in Metall.","i":"bs"},
"堤":{"t":"laut","x":"Links 土 (Erde) als Sinnteil, rechts 是 als Klangteil (テイ). Gemeint ist ein Erddamm: „Deich, Damm“.","s":2,"p":[["土","Erde","b"],["是","dies","l"]]},
"漂":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 票 als Klangteil (ヒョウ). Gemeint ist „auf dem Wasser treiben“.","s":2,"p":[["氵","Wasser","b"],["票","Zettel","l"]],"i":"s"},
"翻":{"t":"laut","x":"Rechts 羽 (Flügel) als Sinnteil, links 番 als Klangteil (バン → ホン). Flattern, sich umdrehen: „wenden, umschlagen“. In der alten Form 飜 stand statt 羽 das Zeichen 飛 („fliegen“).","s":2,"p":[["番","Reihenfolge","l"],["羽","Flügel","b"]],"a":"飜"},
"軌":{"t":"laut","x":"Links 車 (Wagen) als Sinnteil, rechts 九 als Klangteil (キュウ → キ). Gemeint ist die Spur der Wagenräder: „Spur, Gleis“.","s":2,"p":[["車","Wagen","b"],["九","neun","l"]],"i":"bs"},
"后":{"t":"unklar","x":"Die Herkunft ist nicht sicher geklärt. Es gibt mehrere Theorien: Eine sieht das Zeichen als Spiegelform von 句, eine andere als Kurzform von 厚; beide klingen ähnlich. Es steht für „Herrscher(in), Kaiserin“.","s":0,"n":"Oft liest man „Spiegelbild von 司“. Die Forschung hält das für fraglich, weil sich Klang und Bedeutung unterscheiden.","i":"os"},
"奮":{"t":"unklar","x":"Das Zeichen besteht aus 衣, 隹 (kurzschwänziger Vogel) und 田 (Feld). Wie die Teile zusammenpassen, ist nicht gesichert. Es schreibt das Wort „sich erheben, ermuntern“.","s":0,"p":[["衣","Kleid","f"],["隹","Vogel","f"],["田","Feld","f"]],"n":"Oft liest man „ein Vogel breitet auf dem Feld die Flügel“. Die Forschung hält die Zerlegung in 奞 + 田 für falsch.","i":"bs"},
"亭":{"t":"laut","x":"Das Zeichen sah ursprünglich aus wie 京, ein hohes Gebäude (Turm, Pavillon). Der untere Teil wurde später zu 丁 umgeformt, das den Klang (テイ) angibt. Es steht für „Pavillon“ und, in Namen, für „Gasthaus“.","s":2,"p":[["京","Turm","b"],["丁","Nagel","l"]],"i":"s"},
"仰":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 卬 als Klangteil (ギョウ). Gemeint ist, dass man den Blick nach oben richtet: „aufblicken, verehren“.","s":2,"p":[["亻","Mensch","b"],["卬","aufschauen","l"]],"i":"s"},
"伯":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 白 als Klangteil (ハク). Es bezeichnet den Ältesten, das Oberhaupt: „Graf; ältester Bruder“.","s":2,"p":[["亻","Mensch","b"],["白","weiß","l"]],"i":"os"},
"墳":{"t":"laut","x":"Links 土 (Erde) als Sinnteil, rechts 賁 als Klangteil (フン). Gemeint ist ein Erdhügel über einem Grab: „Grabhügel“.","s":2,"p":[["土","Erde","b"],["賁","Klangteil","l"]],"i":"s"},
"壮":{"t":"laut","x":"Die alte Form 壯 hatte 士 (Mann) als Sinnteil und 爿 als Klangteil (ソウ). Gemeint ist „kräftig, stattlich“. In der heutigen Schreibung wurde 爿 zu 丬 verkürzt.","s":2,"p":[["士","Mann","b"],["爿","Klangteil","l"]],"a":"壯"},
"把":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 巴 als Klangteil (ハ). Gemeint ist „mit der Hand greifen, packen“.","s":2,"p":[["扌","Hand","b"],["巴","Klangteil","l"]],"i":"s"},
"搬":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 般 als Klangteil (ハン). Gemeint ist „tragen, befördern“.","s":2,"p":[["扌","Hand","b"],["般","Klangteil","l"]]},
"晶":{"t":"leih","x":"Drei Mal 日: ursprünglich ein Bildzeichen für mehrere Sterne und für das Wort „Stern“ (星). Später wurde es für das ähnlich klingende „hell, klar“ ausgeliehen; daher „Kristall, glänzend“.","s":1,"p":[["日","Sonne","b"]],"n":"Mancher liest drei Sonnen als „sehr hell“ (Sinnverbindung). Nach der japanischen Quelle war es aber zuerst ein Sternbild.","i":"s"},
"洞":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 同 als Klangteil (ドウ). Zuerst stand das Zeichen für „schnell fließen“; später für „Höhle, hohler Raum“.","s":2,"p":[["氵","Wasser","b"],["同","gleich","l"]],"i":"s"},
"涯":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 厓 als Klangteil (ガイ). Gemeint ist eine Klippe am Wasser, also „Ufer, Rand, Grenze“.","s":2,"p":[["氵","Wasser","b"],["厓","Klippe","l"]],"i":"s"},
"疫":{"t":"laut","x":"Außen 疒 (Krankheit) als Sinnteil, innen 殳 als verkürzter Klangteil. Er kürzt 役 ab (エキ/ヤク). Gemeint ist eine ansteckende Krankheit: „Seuche“.","s":2,"p":[["疒","Krankheit","b"],["殳","Stock","l"]],"i":"s"},
"孔":{"t":"kombi","x":"Ein Kind (子) mit einer Markierung am Kopf. Nach einer Deutung zeigt sie die Fontanelle, die offene Stelle am Schädel eines Neugeborenen. Daraus „Öffnung, Loch“.","s":0,"p":[["子","Kind","b"]],"n":"Eine andere Deutung sieht ein stillendes Kind. Das Zeichen schrieb dann „stillen“ und wurde für „Loch“ ausgeliehen.","i":"bs"},
"邸":{"t":"laut","x":"Rechts das Stadt-Zeichen (阝) als Sinnteil, links 氐 als Klangteil (テイ). Es bezeichnete das Haus, in dem Lehnsherren in der Hauptstadt wohnten; daraus „Villa, Residenz“.","s":1,"p":[["阝","Stadt","b"],["氐","Klangteil","l"]],"i":"s"},
"郡":{"t":"laut","x":"Rechts das Stadt-Zeichen (阝) als Sinnteil, links 君 als Klangteil (クン → グン). Es war eine alte Verwaltungseinheit: „Landkreis“.","s":2,"p":[["君","Herrscher","l"],["阝","Stadt","b"]]},
"釈":{"t":"laut","x":"Die alte Form 釋 hatte 釆 („unterscheiden“) als Sinnteil und 睪 als Klangteil. Heute ersetzt 尺 den Teil 睪, wie auch bei 訳 und 駅. Das Zeichen bedeutet „erklären, auslösen“.","s":2,"p":[["釆","unterscheiden","b"],["尺","Maß","l"]],"a":"釋"},
"肪":{"t":"laut","x":"Links ⺼ (Fleisch) als Sinnteil, rechts 方 als Klangteil (ホウ → ボウ). Es steht für „Fett“ im Körper.","s":2,"p":[["⺼","Fleisch","b"],["方","Seite","l"]]},
"喚":{"t":"laut","x":"Links 口 (Mund) als Sinnteil, rechts 奐 als Klangteil (カン). Gemeint ist „rufen, herbeirufen“.","s":2,"p":[["口","Mund","b"],["奐","Klangteil","l"]],"i":"s"},
"媛":{"t":"laut","x":"Links 女 (Frau) als Sinnteil, rechts 爰 als Klangteil (エン). Gemeint ist eine schöne Frau, später auch „Prinzessin“.","s":2,"p":[["女","Frau","b"],["爰","Klangteil","l"]]},
"貞":{"t":"laut","x":"Das Zeichen zeigte ursprünglich einen Opferdreifuß (鼎) und wurde für das gleich klingende „wahrsagen“ ausgeliehen. Dann kam 卜 („Orakel“) dazu. Unten sieht es heute wie 貝 aus; das ist ein Zufall der Form.","s":2,"p":[["卜","Orakel","b"],["鼎","Dreifuß","l"]],"n":"Die alte Erklärung „卜 + 貝“ stimmt laut den Orakelknochen- und Bronzeformen nicht.","i":"obs"},
"玄":{"t":"leih","x":"Ursprünglich ein gebündelter, aufgehängter Faden (幺 mit Markierung oben). Das Zeichen wurde für das gleich klingende Wort „dunkel, tief, geheimnisvoll“ ausgeliehen.","s":1,"p":[["幺","Faden","b"],["亠","Markierung","f"]],"n":"Eine Quelle zählt es als Hinweiszeichen: zwei verschlungene Fäden plus Markierung.","i":"bs"},
"苗":{"t":"kombi","x":"Eine Pflanze (艹) auf einem Feld (田): Setzlinge im Feld. Daraus „Sämling, Setzling“.","s":2,"p":[["艹","Pflanze","b"],["田","Feld","b"]],"i":"bs"},
"渦":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 咼 als Klangteil (カ). Gemeint ist ein Strudel im Wasser: „Wirbel“.","s":2,"p":[["氵","Wasser","b"],["咼","Klangteil","l"]]},
"慈":{"t":"laut","x":"Unten 心 (Herz) als Sinnteil, oben 茲 als Klangteil (ジ). Gemeint ist ein liebevolles Herz: „Güte, Barmherzigkeit“.","s":2,"p":[["茲","dieses","l"],["心","Herz","b"]]},
"襟":{"t":"laut","x":"Links das Kleidungs-Zeichen (衤) als Sinnteil, rechts 禁 als Klangteil (キン). Gemeint ist der Kragen: „Revers, Kragen, Brust“.","s":2,"p":[["衤","Kleidung","b"],["禁","verbieten","l"]]},
"蓮":{"t":"laut","x":"Oben 艹 (Pflanze) als Sinnteil, darunter 連 als Klangteil (レン). Es steht für die Lotosblume.","s":2,"p":[["艹","Pflanze","b"],["連","verbinden","l"]],"i":"s"},
"亮":{"t":"laut","x":"Unten 儿 (Mensch) als Sinnteil, oben 京 als Klangteil (リョウ). Gemeint ist „hell, klar“.","s":1,"p":[["儿","Mensch","b"],["京","Turm","l"]]},
"聡":{"t":"laut","x":"Die alte Form 聰 hatte 耳 (Ohr) als Sinnteil und 悤 als Klangteil (ソウ). Das Ohr steht für gutes Zuhören und schnelles Lernen: „klug, aufgeweckt“. Heute ist der Klangteil verkürzt.","s":2,"p":[["耳","Ohr","b"],["悤","Herz-Klang","l"]],"a":"聰"},
"浦":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 甫 als Klangteil (ホ). Gemeint ist eine Bucht oder ein Küstenstrich: „Bucht, Ufer“.","s":2,"p":[["氵","Wasser","b"],["甫","Klangteil","l"]],"i":"s"},
"塚":{"t":"laut","x":"Links 土 (Erde) als Sinnteil, rechts 冢 als Klangteil (チョウ). Gemeint ist ein Erdhügel, auch Grabhügel: „Hügel, Grabhügel“.","s":2,"p":[["土","Erde","b"],["冢","Hügel","l"]]},
"陥":{"t":"laut","x":"Die alte Form 陷 bestand aus dem Hügel-Zeichen (阝) und 臽, einem Bild für „in eine Grube fallen“; 臽 liefert auch den Klang (カン). Heute ist 臽 zu ⺈旧 vereinfacht. Daraus „hineinfallen, einstürzen“.","s":2,"p":[["阝","Hügel","b"],["臽","Falle","l"]],"a":"陷","i":"s"},
"貫":{"t":"bild","x":"Ein Bildzeichen: zwei Kaurimuscheln (貝), durch einen senkrechten Stab oder eine Schnur aufgefädelt. Daraus „durchbohren, hindurchgehen“.","s":2,"p":[["貝","Muschel","b"]],"n":"Das alte Wörterbuch nimmt eine Zusammensetzung aus 毌 + 貝 an. Diese Deutung passt laut den Bronzeinschriften nicht."},
"覇":{"t":"unklar","x":"Das Zeichen gilt als Variante von 霸. Über seinen Aufbau gibt es keine verlässliche Angabe. Es steht für „Vorherrschaft, Hegemonie“.","s":0},
"呂":{"t":"leih","x":"Ursprünglich ein Bildzeichen für zwei übereinandergelegte Metallbarren. Dann wurde es für das gleich klingende Wort „Tonlage, Musikton“ ausgeliehen. Heute steht es in Namen und im Wort 風呂.","s":2,"n":"Oft liest man „zwei Wirbel einer Wirbelsäule“. Das ist die Deutung aus dem alten Wörterbuch; sie ist ein Irrtum.","i":"b"},
"擁":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 雍 als Klangteil (ヨウ). Gemeint ist „umarmen, umschließen“.","s":2,"p":[["扌","Hand","b"],["雍","Klangteil","l"]],"i":"bs"},
"孤":{"t":"laut","x":"Links 子 (Kind) als Sinnteil, rechts 瓜 als Klangteil (カ → コ). Gemeint ist ein Waisenkind: „Waise, allein“.","s":2,"p":[["子","Kind","b"],["瓜","Melone","l"]],"i":"s"},
"賠":{"t":"laut","x":"Links 貝 (Muschel, früher Geld) als Sinnteil, rechts 咅 als Klangteil (バイ). Gemeint ist, einen Schaden mit Geld auszugleichen: „entschädigen“.","s":2,"p":[["貝","Muschel","b"],["咅","Klangteil","l"]]},
"鎖":{"t":"laut","x":"Links 金 (Metall) als Sinnteil, rechts ein Klangteil 𧴪, der die Aussprache angibt. Das Zeichen schrieb ursprünglich das Wort für „Schloss, Riegel“; daraus wurde später „Kette“ und „absperren“.","s":2,"p":[["金","Metall","b"],["𧴪","Klangteil","l"]]},
"噴":{"t":"laut","x":"口 (Mund) gibt den Sinnbereich an: etwas aus dem Mund hervorstoßen, ausspeien. 賁 liefert den Klang (賁 ホン/フン → 噴 フン). Daraus entstand die Bedeutung „hervorsprudeln, ausstoßen“.","s":2,"p":[["口","Mund","b"],["賁","Klangteil","l"]],"i":"s"},
"祥":{"t":"laut","x":"示 (Altar, Religiöses) ist der Sinnteil, 羊 der Klangteil (羊 ヨウ → 祥 ショウ). Es geht um Glück und gutes Vorzeichen. Ursprünglich genügte 羊 allein; 示 wurde später ergänzt, um das Wort klar abzugrenzen.","s":2,"p":[["示","Altar","b"],["羊","Schaf","l"]]},
"牲":{"t":"laut","x":"牛 (Rind) zeigt: ein Tier, hier das Opfertier. 生 gibt den Klang (生 セイ → 牲 セイ).","s":2,"p":[["牛","Rind","b"],["生","Leben","l"]]},
"秩":{"t":"laut","x":"禾 (Getreide) ist der Sinnteil, 失 der Klangteil (シツ → チツ, ähnlich). Das Wort bezeichnete zunächst Unterhalt bzw. Gehalt in Getreide; später kam die Bedeutung „Ordnung, Reihenfolge“ dazu.","s":1,"p":[["禾","Getreide","b"],["失","verlieren","l"]],"n":"Eine Erklärung sagt, das Zeichen habe ursprünglich geordnet aufgeschichtete Getreidepflanzen gezeigt, woraus „Ordnung“ wurde. Das ist nur eine Deutung unter mehreren."},
"唆":{"t":"laut","x":"口 (Mund) steht für Reden: jemanden mit Worten anstiften, verleiten. 夋 ist der Klangteil. Das Zeichen schreibt das Wort für „jemanden aufhetzen, verleiten“.","s":2,"p":[["口","Mund","b"],["夋","Klangteil","l"]]},
"膨":{"t":"laut","x":"Links steht 月 in der Rolle von „Fleisch, Körper“ (nicht Mond), es gibt den Sinnbereich an. Rechts 彭 als Klangteil (ホウ → ボウ). Gemeint ist das Anschwellen, Aufquellen.","s":2,"p":[["月","Fleisch","b"],["彭","Klangteil","l"]]},
"芳":{"t":"laut","x":"艹 (Pflanze) zeigt den Sinnbereich: Duft von Pflanzen. 方 liefert den Klang (ホウ → ホウ). Das Zeichen schreibt das Wort für „Duft“, später auch allgemein „vortrefflich“.","s":2,"p":[["艹","Pflanze","b"],["方","Richtung","l"]]},
"恒":{"t":"laut","x":"Die alte Form 恆 besteht aus 忄 (Herz, Gemüt) und dem Klangteil 亙 (コウ). Gemeint ist ein beständiges Gemüt, daraus „dauerhaft, immer“. In 恒 wurde 亙 zu 亘 verkürzt.","s":2,"p":[["忄","Herz","b"],["亘","Klangteil","l"]],"a":"恆","i":"s"},
"倫":{"t":"laut","x":"亻 (Mensch) gibt den Sinnbereich an, 侖 den Klang (リン). Es geht um Menschen und ihre Ordnung untereinander: Gefährte, Moral.","s":2,"p":[["亻","Mensch","b"],["侖","Klangteil","l"]]},
"陳":{"t":"laut","x":"阝 (Hügel, Erdwall) plus ein Klangteil, der heute wie 東 aussieht. Ursprünglich schrieb das Zeichen einen Ortsnamen. Später wurde es ausgeliehen für „ausbreiten, aufreihen, darlegen“.","s":1,"p":[["阝","Hügel","b"],["東","Klangteil","l"]],"i":"bs"},
"須":{"t":"leih","x":"Ursprünglich ein Bild: ein Kopf (頁) mit Haaren (彡) am Kinn, also ein Bart. Das Zeichen schrieb das Wort „Bart“. Später wurde es für ein gleich klingendes Wort ausgeliehen: „müssen, unbedingt“.","s":2,"p":[["彡","Haar","b"],["頁","Kopf","b"]],"i":"obs"},
"偏":{"t":"laut","x":"亻 (Mensch) steht für den Sinnbereich, 扁 liefert den Klang (ヘン). Gemeint ist „zur Seite geneigt, einseitig, ungleich“.","s":2,"p":[["亻","Mensch","b"],["扁","flach","l"]]},
"遇":{"t":"laut","x":"辶 (Gehen, Weg) als Sinnteil: man trifft sich unterwegs. 禺 ist der Klangteil (グウ). Bedeutung „begegnen, antreffen“.","s":2,"p":[["辶","Gehen","b"],["禺","Klangteil","l"]]},
"糧":{"t":"laut","x":"米 (Reis, Getreide) gibt den Sinnbereich an: Proviant, Nahrung für unterwegs. 量 liefert den Klang (リョウ → リョウ).","s":2,"p":[["米","Reis","b"],["量","Menge","l"]],"i":"s"},
"殊":{"t":"laut","x":"歹 (Kurzform von 死, „Tod“) ist der Sinnteil, 朱 der Klangteil (シュ). Das Zeichen schrieb zunächst das Wort „sterben“. „Besonders, außergewöhnlich“ ist eine spätere Verwendung.","s":2,"p":[["歹","Tod","b"],["朱","rot","l"]],"n":"Oft liest man „wie ein Baumstumpf abgehackt: ungewöhnlich“. Die Forschung sieht das heute anders: 朱 liefert nur den Klang, keine Bedeutung."},
"慢":{"t":"laut","x":"忄 (Herz, Gemüt) zeigt, dass es um eine Haltung geht. 曼 liefert den Klang (マン). Das Zeichen schreibt „nachlässig, träge, respektlos“.","s":2,"p":[["忄","Herz","b"],["曼","Klangteil","l"]]},
"没":{"t":"laut","x":"Die alte Form 沒 hat 氵 (Wasser) als Sinnteil und einen Klangteil (ボツ/モツ): etwas versinkt im Wasser. In 没 wurde der Klangteil zu 殳 vereinfacht.","s":2,"p":[["氵","Wasser","b"],["殳","Klangteil","l"]],"a":"沒","i":"s"},
"怠":{"t":"laut","x":"心 (Herz) unten gibt den Sinnbereich an: eine Haltung, nämlich nachlässig sein. 台 oben liefert den Klang (台 ダイ → 怠 タイ). Bedeutung „faul sein, vernachlässigen“.","s":2,"p":[["台","Klangteil","l"],["心","Herz","b"]]},
"遭":{"t":"laut","x":"辶 (Gehen) als Sinnteil: man begegnet jemandem oder etwas unterwegs. 曹 liefert den Klang (ソウ → ソウ). Heute meist für unangenehme Begegnungen: „geraten in, erleiden“.","s":2,"p":[["辶","Gehen","b"],["曹","Klangteil","l"]],"n":"Auf Orakelknochen stand statt 辶 ein umgedrehter Fuß, dazu ein anderer Klangteil.","i":"s"},
"惰":{"t":"laut","x":"忄 (Herz, Gemüt) ist der Sinnteil: Trägheit, Nachlässigkeit. Rechts steht der Klangteil 隋 in verkürzter Form (Lesung ダ). Bedeutung „faul, träge“.","s":2,"p":[["忄","Herz","b"],["隋","Klangteil, verkürzt","l"]]},
"猟":{"t":"laut","x":"Die alte Form 獵 hat 犭 (Hund, Tier) als Sinnteil, denn Hunde helfen bei der Jagd, und 巤 als Klangteil (リョウ). In 猟 wurde 巤 zu 鼡 verkürzt.","s":2,"p":[["犭","Hund","b"],["巤","Klangteil","l"]],"a":"獵","i":"bs"},
"乃":{"t":"unklar","x":"Woher das Zeichen kommt, ist nicht geklärt. Man deutet es als Seil, als Brust, oder als etwas, das gezogen wird. Das Zeichen wurde schon früh für ein gleich klingendes Wort ausgeliehen: „du“ und „dann, also“.","s":0,"n":"Die alte Erklärung, es zeige schwer herauskommenden Atem, gilt nicht als verlässlich.","i":"obs"},
"綾":{"t":"laut","x":"糸 (Faden, Seide) zeigt den Stoffbereich, 夌 ist der Klangteil. Gemeint ist ein Stoff mit eingewebtem Muster, Köper.","s":1,"p":[["糸","Faden","b"],["夌","Klangteil","l"]],"i":"s"},
"颯":{"t":"laut","x":"風 (Wind) ist der Sinnteil, 立 liefert den Klang (リツ → サツ, ähnlich). Das Zeichen schreibt ein Lautwort für das Rauschen des Windes; daraus „flott, schneidig“.","s":1,"p":[["立","stehen","l"],["風","Wind","b"]],"i":"s"},
"隼":{"t":"unklar","x":"Der obere Teil ist 隹, das Bild eines kurzschwänzigen Vogels. 隼 wurde aus 隹 abgespalten, um den Falken zu bezeichnen. Wozu der untere Teil 十 gehört, ist nicht klar.","s":1,"p":[["隹","kurzschwänziger Vogel","b"]]},
"輔":{"t":"laut","x":"車 (Wagen) ist der Sinnteil, 甫 der Klangteil (ホ). Das Zeichen schreibt das Wort „helfen, unterstützen“; wie sich das aus dem Wagen ergibt, ist nicht überliefert.","s":1,"p":[["車","Wagen","b"],["甫","Klangteil","l"]]},
"寛":{"t":"laut","x":"Die alte Form 寬 hat 宀 (Dach, Haus) als Sinnteil und einen Klangteil (カン). Ein geräumiges Haus steht für „weit, großzügig“. In 寛 wurde ein Strich weggelassen und ein Teil zu 艹 umgeformt.","s":2,"p":[["宀","Haus","b"],["莧","Klangteil","l"]],"a":"寬"},
"胞":{"t":"laut","x":"月 steht hier für Fleisch, Körper. 包 liefert den Klang (ホウ). 包 zeigt außerdem eine Gestalt mit einem Kind im Leib. So bezeichnet das Zeichen die Hülle des Fötus, später „Zelle“ oder „Landsleute“.","s":2,"p":[["月","Fleisch","b"],["包","einwickeln","l"]],"i":"s"},
"浄":{"t":"laut","x":"Die alte Form 淨 besteht aus 氵 (Wasser) und dem Klangteil 爭. Mit Wasser wird etwas gereinigt: „sauber, rein“. In 浄 ist 爭 zu 争 verkürzt.","s":2,"p":[["氵","Wasser","b"],["争","Klangteil","l"]],"a":"淨"},
"随":{"t":"laut","x":"Die alte Form 隨 hat 辶 (Gehen) als Sinnteil und 隋 als Klangteil (ズイ). Wer geht, folgt: „folgen“. In 随 wurde der Klangteil verkürzt.","s":2,"p":[["辶","Gehen","b"],["隋","Klangteil","l"]],"a":"隨","i":"s"},
"稿":{"t":"laut","x":"禾 (Getreide) ist der Sinnteil, 高 der Klangteil (コウ → コウ). Heute bedeutet das Zeichen „Entwurf, Manuskript“.","s":1,"p":[["禾","Getreide","b"],["高","hoch","l"]],"n":"Nach der japanischen Quelle geht es auf ein anderes Zeichen, 稾 (Stroh), zurück, das hier weiterverwendet wurde.","i":"s"},
"丹":{"t":"bild","x":"Oft als Bild einer Grube oder eines Schachts gedeutet, in dem rote Zinnobererde liegt. Das Zeichen steht für „Zinnoberrot, rote Farbe“.","s":0,"n":"Der genaue Aufbau ist nicht gesichert.","i":"obs"},
"壌":{"t":"laut","x":"Die alte Form 壤 hat 土 (Erde) als Sinnteil und 襄 als Klangteil (ジョウ). Gemeint ist weiche, fruchtbare Erde. In 壌 ist der Klangteil verkürzt.","s":2,"p":[["土","Erde","b"],["㐮","Klangteil","l"]],"a":"壤"},
"舗":{"t":"laut","x":"Ursprünglich schrieb man 鋪 mit 金 (Metall) für einen Türbeschlag, geliehen für „ausbreiten“ und dann „Laden“. In 舖/舗 ersetzte man 金 durch 舎 (Haus), 甫 bleibt Klangteil (ホ).","s":1,"p":[["舎","Haus","b"],["甫","Klangteil","l"]],"a":"舖"},
"騰":{"t":"laut","x":"馬 (Pferd) ist der Sinnteil: ein Pferd springt, galoppiert. 朕 ist der Klangteil. Daraus „hochspringen, steigen“.","s":2,"p":[["馬","Pferd","b"],["朕","Klangteil","l"]],"i":"s"},
"緯":{"t":"laut","x":"糸 (Faden) gibt den Sinnbereich an: der quer verlaufende Schussfaden beim Weben. 韋 liefert den Klang (イ → イ). Von dort „quer, waagerecht“, etwa bei Breitengraden.","s":2,"p":[["糸","Faden","b"],["韋","Klangteil","l"]]},
"艇":{"t":"laut","x":"舟 (Boot) ist der Sinnteil, 廷 der Klangteil (廷 テイ → 艇 テイ). Das Zeichen bedeutet „kleines Boot“.","s":2,"p":[["舟","Boot","b"],["廷","Klangteil","l"]]},
"披":{"t":"laut","x":"扌 (Hand) zeigt eine Tätigkeit: aufmachen, aufschlagen. 皮 liefert den Klang (ヒ → ヒ). Daraus „öffnen, enthüllen“.","s":2,"p":[["扌","Hand","b"],["皮","Haut","l"]]},
"錦":{"t":"laut","x":"帛 (Seidenstoff) ist der Sinnteil, 金 liefert den Klang (キン → キン). Gemeint ist ein kostbarer, gemusterter Seidenbrokat.","s":2,"p":[["帛","Seide","b"],["金","Gold","l"]]},
"准":{"t":"laut","x":"Das Zeichen ist die Kurzform von 準. Dort steht 氵 (Wasser) für den Sinnbereich und 隹 als Klangteil. Das Wort bedeutete ursprünglich „Wasserwaage, Wasserstand“; später verschob sich die Bedeutung. In 准 ist 氵 zu 冫 verkürzt.","s":2,"p":[["冫","Wasser, verkürzt","b"],["隹","Vogel","l"]],"n":"In 準 sieht der Teil wie 隼 (Falke) aus, ist aber ursprünglich 隹. Er liefert nur den Klang.","a":"準"},
"剰":{"t":"laut","x":"Die alte Form 剩 hat 刂 (Messer) und den Klangteil 乘 (ジョウ). In 剰 ist 乘 zu 乗 vereinfacht. Das Zeichen bedeutet „Überschuss, Rest“.","s":2,"p":[["乗","Klangteil","l"],["刂","Messer","b"]],"a":"剩"},
"繊":{"t":"laut","x":"Die alte Form 纖 hat 糸 (Faden) als Sinnteil und 韱 als Klangteil (セン). Gemeint ist „fein, dünn“ wie ein Faden. In 繊 wurde 韱 stark vereinfacht.","s":2,"p":[["糸","Faden","b"],["韱","Klangteil","l"]],"a":"纖"},
"諭":{"t":"laut","x":"言 (Sprechen) ist der Sinnteil, 兪 der Klangteil (ユ → ユ). Man belehrt jemanden mit Worten: „ermahnen, jemandem etwas klarmachen“.","s":2,"p":[["言","Sprechen","b"],["兪","Klangteil","l"]]},
"惨":{"t":"laut","x":"Die alte Form 慘 hat 忄 (Herz, Gefühl) als Sinnteil und 參 als Klangteil (サン). Es geht um ein schmerzliches Gefühl: „grausam, elend“. In 惨 wurde 參 zu 参 vereinfacht.","s":2,"p":[["忄","Herz","b"],["参","Klangteil","l"]],"a":"慘","i":"s"},
"虐":{"t":"kombi","x":"Auf Orakelknochen zeigt das Zeichen einen Tiger (虎), der eine Person mit den Krallen packt und fressen will. Daraus wurde „grausam, quälen, misshandeln“.","s":2,"p":[["虍","Tiger","b"],["人","Mensch","b"]],"i":"os"},
"据":{"t":"laut","x":"Die alte Form 據 hat 扌 (Hand) und den Klangteil 豦; in 据 steht dafür 居 (キョ). Ursprünglich „sich auf etwas stützen“. Die Lesung すえる, „hinstellen“, ist eine japanische Zusatzbedeutung.","s":2,"p":[["扌","Hand","b"],["居","wohnen","l"]],"n":"Früher schrieb man dafür oft 居; seit der Meiji-Zeit ist 据 üblich.","a":"據"},
"徐":{"t":"laut","x":"彳 (Schritt, Gehen) ist der Sinnteil: langsam gehen. 余 liefert den Klang (ヨ → ジョ). Daraus „langsam, allmählich“.","s":2,"p":[["彳","Gehen","b"],["余","Klangteil","l"]],"i":"bs"},
"搭":{"t":"laut","x":"扌 (Hand) steht für eine Tätigkeit, 荅 liefert den Klang (トウ → トウ). Das Zeichen bedeutet „aufladen, einsteigen, anbringen“.","s":1,"p":[["扌","Hand","b"],["荅","Klangteil","l"]]},
"鯉":{"t":"laut","x":"魚 (Fisch) gibt den Sinnbereich an, 里 den Klang (リ → リ). Das Zeichen schreibt den Fisch „Karpfen“.","s":2,"p":[["魚","Fisch","b"],["里","Dorf","l"]]},
"緋":{"t":"laut","x":"糸 (Seidenfaden, Stoff) zeigt, dass es um Gewebtes oder Gefärbtes geht, 非 liefert den Klang (ヒ → ヒ). Das Zeichen bedeutet „scharlachrot“.","s":2,"p":[["糸","Faden","b"],["非","nicht","l"]],"i":"s"},
"曙":{"t":"laut","x":"日 (Sonne, Tag) gibt den Sinnbereich an: der Moment, wenn es hell wird. 署 liefert den Klang (ショ → ショ). Das Zeichen bedeutet „Morgendämmerung“.","s":2,"p":[["日","Sonne","b"],["署","Klangteil","l"]]},
"胡":{"t":"laut","x":"月 steht hier für Fleisch, 古 ist der Klangteil (コ). Das Zeichen schrieb zunächst das Wort für das herabhängende Fleisch am Kinn. Später wurde es für ein gleich klingendes Wort („wie, warum“) ausgeliehen.","s":2,"p":[["古","alt","l"],["月","Fleisch","b"]],"i":"s"},
"帥":{"t":"kombi","x":"Ursprünglich zeigte das Zeichen zwei Hände, die ein Tuch halten. Später kam 巾 (Tuch) dazu, daraus entstand die heutige Form. Das Wort schrieb ein Handtuch. Die Bedeutung „Befehlshaber“ kam erst später dazu.","s":1,"p":[["巾","Tuch","b"]],"n":"Alte Wörterbücher sahen links das Zeichen 𠂤 (Hügel/Truppe). Die Orakelknochen- und Bronzeformen zeigen, dass das nicht stimmt.","i":"bs"},
"啓":{"t":"unklar","x":"Das Zeichen besteht aus 戸 (Tür), 攵 (Hand mit Stock) und 口 (Mund). Es gilt als Kurzform des älteren 啟 mit der Bedeutung „öffnen, aufschließen, mitteilen“. Ein gesicherter Aufbau lässt sich aus den Quellen nicht ablesen.","s":0,"p":[["戸","Tür","b"],["攵","schlagen","b"],["口","Mund","b"]]},
"葵":{"t":"laut","x":"艹 (Pflanze) zeigt, dass es eine Pflanze ist, 癸 liefert den Klang (キ). Das Zeichen schreibt den Namen der Malvengewächse, etwa Stockrose.","s":2,"p":[["艹","Pflanze","b"],["癸","Klangteil","l"]]},
"駿":{"t":"laut","x":"馬 (Pferd) ist der Sinnteil, 夋 der Klangteil (シュン → シュン). Das Zeichen bedeutet „ausgezeichnetes, schnelles Pferd“.","s":2,"p":[["馬","Pferd","b"],["夋","Klangteil","l"]],"n":"Oft liest man, 夋 zeige eine stattliche Gestalt und bringe so die Bedeutung ein. Die Forschung sieht das heute anders: 夋 liefert nur den Klang."},
"諒":{"t":"laut","x":"言 (Sprechen) ist der Sinnteil, 京 der Klangteil (京 キョウ → 諒 リョウ, Klang hat sich etwas verschoben). Heute: „verstehen, einsehen“.","s":1,"p":[["言","Sprechen","b"],["京","Hauptstadt","l"]],"i":"s"},
"莉":{"t":"laut","x":"艹 (Pflanze) gibt den Sinnbereich an, 利 den Klang (リ → リ). Das Zeichen kommt vor allem im Wort für Jasmin vor.","s":2,"p":[["艹","Pflanze","b"],["利","Vorteil","l"]]},
"鯨":{"t":"laut","x":"魚 (Fisch) gibt den Sinnbereich an, 京 den Klang (京 ケイ → 鯨 ゲイ). Das Zeichen schreibt das Wort für „Wal“.","s":2,"p":[["魚","Fisch","b"],["京","Klangteil","l"]],"n":"Oft liest man, 京 bedeute „groß“ und mache so einen großen Fisch. Die Forschung sieht das heute anders: 京 liefert nur den Klang.","i":"s"},
"荘":{"t":"laut","x":"Die alte Form 莊 hat 艹 (Pflanze) als Sinnteil und 壯 als Klangteil (ソウ). Das Wort bezeichnete ein Landgut. In 荘 wurde 壯 zu 壮 vereinfacht.","s":2,"p":[["艹","Pflanze","b"],["壮","Klangteil","l"]],"a":"莊"},
"栽":{"t":"laut","x":"木 (Baum) ist der Sinnteil: Pflanzen setzen. 𢦏 liefert den Klang (サイ). Das Zeichen bedeutet „pflanzen, anbauen“.","s":2,"p":[["木","Baum","b"],["𢦏","Klangteil","l"]]},
"拐":{"t":"laut","x":"扌 (Hand) steht für eine Tätigkeit, 叧 liefert den Klang. Das Zeichen bedeutet „entführen, verschleppen“.","s":1,"p":[["扌","Hand","b"],["叧","Klangteil","l"]]},
"冠":{"t":"laut","x":"冖 ist eine Kopfbedeckung, 元 der Klangteil (ゲン/ガン → カン). Später kam 寸 (Hand) dazu: eine Hand setzt die Mütze auf den Kopf. Das Zeichen bedeutet „Krone, Hut“.","s":2,"p":[["冖","Mütze","b"],["元","Kopf","l"],["寸","Hand","f"]],"i":"s"},
"勲":{"t":"laut","x":"力 (Kraft) steht für Leistung, Verdienst. 熏 liefert den Klang (クン). Das Zeichen bedeutet „Verdienst, Ehrung“. Die heutige Form ist die Kurzform von 勳.","s":1,"p":[["熏","Klangteil","l"],["力","Kraft","b"]],"a":"勳"},
"酬":{"t":"laut","x":"酉 (Weinkrug, Alkohol) ist der Sinnteil, 州 der Klangteil (シュウ). Das Zeichen bedeutet „vergelten, erwidern“.","s":2,"p":[["酉","Weingefäß","b"],["州","Klangteil","l"]],"i":"s"},
"紋":{"t":"laut","x":"糸 (Faden) als Sinnteil: eine Linie im Gewebe, ein Muster. 文 liefert den Klang (モン → モン). Das Zeichen ist eine Spezialform für „Muster“ gegenüber dem allgemeineren 文.","s":2,"p":[["糸","Faden","b"],["文","Muster","l"]]},
"卸":{"t":"laut","x":"Das Zeichen ist eine verkürzte Form von 御, bei der 彳 weggelassen wurde. 午 liefert den Klang. Es schreibt das Wort für „abladen, abnehmen“, im Japanischen auch „Großhandel“.","s":1,"p":[["午","Mittag","l"],["止","Fuß","b"],["卩","kniende Gestalt","f"]]},
"欄":{"t":"laut","x":"木 (Holz) ist der Sinnteil: ein Geländer aus Holz. 闌 liefert den Klang (ラン → ラン). Daraus entstand auch „Spalte, Feld“.","s":2,"p":[["木","Holz","b"],["闌","Klangteil","l"]]},
"逸":{"t":"kombi","x":"Auf Orakelknochen steht ein Fuß mit einem Tier; später 辶 (Gehen) mit 兔 (Hase). Das Bild: etwas entwischt, entkommt. Daraus „entgehen, abweichen, herausragen“.","s":0,"p":[["辶","Gehen","b"],["兔","Hase","b"]],"n":"Eine andere Lesart sieht im rechten Teil nur einen verkürzten Klangteil."},
"尚":{"t":"leih","x":"Ursprünglich ein Bildzeichen für ein Gebäude, nämlich eine hohe Halle (heute 堂). Später wurde das Zeichen für das gleich klingende Wort „außerdem, noch dazu“ ausgeliehen.","s":1,"n":"Oft liest man „八 + 向“. Die alten Schriftformen zeigen, dass diese Zerlegung nicht stimmt.","i":"bs"},
"顕":{"t":"kombi","x":"Die alte Form 顯 zeigt Sonne, Seidenfäden und einen Kopf (頁): Man betrachtet Fäden im Sonnenlicht, also etwas deutlich Sichtbares. Heute ist der linke Teil zu 显 verkürzt.","s":1,"p":[["日","Sonne","b"],["糸","Seide","b"],["頁","Kopf, Mensch","b"]],"n":"Ein altes Zeichenlexikon zerlegt anders (㬎 + 頁), das gilt heute als Fehlanalyse.","a":"顯","i":"bs"},
"粛":{"t":"unklar","x":"Die Herkunft der alten Form 肅 ist unklar. Sie besteht aus zwei Teilen (聿 und 𣶒); die heutige Form ist eine Verkürzung davon.","s":0,"n":"Eine Vermutung sieht im oberen Teil ein Stickwerkzeug in der Hand und das Zeichen als Lautzeichen für „Stickerei“. Das ist reine Spekulation.","a":"肅","i":"s"},
"愚":{"t":"laut","x":"Unten das Herz (心) als Sinnteil: Es geht um den Geist. Oben 禺 gibt den Klang (グウ → グ). So steht das Zeichen für „dumm, töricht“.","s":2,"p":[["禺","Klangteil","l"],["心","Herz","b"]],"n":"Oft liest man „禺 = Affe, ein Herz wie ein Affe“. Das ist eine Deutung, die nachträglich passend gemacht wurde; 禺 trägt hier nur den Klang."},
"庶":{"t":"laut","x":"Unten das Feuer (灬) als Sinnteil: Das Wort bedeutete ursprünglich „kochen, sieden“. 石 gab den Klang; es ist in der Schrift zur heutigen Form verformt. Später wurde das Zeichen für „viele, allerlei“ ausgeliehen.","s":2,"p":[["火","Feuer","b"],["石","Stein","l"]],"n":"Ein altes Zeichenlexikon deutet es als 广 + 炗; die frühen Schriftformen widerlegen das."},
"践":{"t":"laut","x":"Links der Fuß (⻊) als Sinnteil: treten, betreten. Rechts gibt 戔 den Klang (セン). Die alte Form 踐 hat 戔; im heutigen Zeichen ist dieser Teil vereinfacht.","s":2,"p":[["⻊","Fuß","b"],["戔","Klangteil","l"]],"n":"Eine zweite Lesart nimmt für 戔 auch die Bedeutung „klein“ an, dann wären es „kleine Schritte“.","a":"踐","i":"s"},
"呈":{"t":"unklar","x":"Der Ursprung ist nicht sicher geklärt. Das Zeichen hat oben einen Mund (口); der untere Teil ist nicht dasselbe wie 王 oder 壬. Es bedeutet „zeigen, darbieten“.","s":0,"n":"Genannt werden auch „口 + 十“ oder „口 + 士“, gesichert ist nichts davon.","i":"s"},
"疎":{"t":"kurz","x":"Eine Schreibvariante von 疏. Der Teil 㐬 wurde zu einer Form mit 束 umgeformt.","s":1},
"疾":{"t":"laut","x":"Ursprünglich standen zwei Zeichen für zwei Wörter: ein Pfeil, der auf einen Menschen zufliegt („schnell“), und ein Mensch im Bett („krank“). Beide klangen fast gleich und wurden zu 疾 verschmolzen; es bedeutet beides.","s":1,"p":[["矢","Pfeil","b"],["疒","Krankenbett","l"]],"n":"Ein altes Zeichenlexikon sieht 矢 als Klangteil; das passt lautlich nicht.","i":"obs"},
"謡":{"t":"laut","x":"Links 言 (sprechen) als Sinnteil, rechts 䍃 als Klangteil (ヨウ). Gemeint ist „singen, vortragen“. In der alten Form 謠 ist der Klangteil etwas anders geschrieben.","s":2,"p":[["言","Sprechen","b"],["䍃","Klangteil","l"]],"a":"謠"},
"鎌":{"t":"laut","x":"Links Metall (釒), denn die Sichel ist aus Metall. Rechts gibt 兼 den Klang (ケン; heute auch レン).","s":2,"p":[["金","Metall","b"],["兼","Klangteil","l"]],"i":"s"},
"酷":{"t":"laut","x":"Links das Gefäß für Alkohol (酉) als Sinnteil: Zuerst ging es um einen sehr starken Geschmack des Weins. Rechts gibt 告 den Klang (コク). Daraus wurde „streng, grausam“.","s":2,"p":[["酉","Weingefäß","b"],["告","Klangteil","l"]]},
"叙":{"t":"laut","x":"In der alten Form 敘 gab 余 den Klang; 攴 (Hand mit Stock) war der Sinnteil. Heute steht dort verkürzt 又. Das Wort bedeutete ursprünglich „der Reihe nach ordnen“.","s":2,"p":[["余","Klangteil","l"],["又","Hand","f"]],"a":"敘","i":"os"},
"且":{"t":"leih","x":"Ursprünglich ein Bildzeichen für ein kleines Gestell, auf dem Opferfleisch oder zum Schneiden gelegt wird (Hackblock). Später wurde es für das Bindewort „außerdem, und zwar“ ausgeliehen.","s":1,"n":"Andere Deutungen sehen einen Steinaltar oder ein Symbol für den männlichen Vorfahren. In alten Inschriften stand das Zeichen oft für „Ahn“.","i":"obs"},
"痴":{"t":"laut","x":"Die alte Form 癡 hat 疒 (Krankheit) als Sinnteil und 疑 als Klangteil. Im heutigen Zeichen wurde 疑 durch 知 ersetzt, das ebenfalls チ klingt. Gemeint ist „töricht, geistig stumpf“.","s":2,"p":[["疒","Krankheit","b"],["知","wissen","l"]],"a":"癡"},
"茎":{"t":"laut","x":"Oben das Pflanzenzeichen (艹), denn es geht um den Stängel. Der Klangteil ist in der alten Form 莖 ein 巠 (ケイ); im heutigen Zeichen ist er zu 圣 vereinfacht.","s":1,"p":[["艹","Pflanze","b"],["圣","Klangteil","l"]],"a":"莖"},
"阿":{"t":"laut","x":"Links der Hügel (阝) als Sinnteil, rechts 可 als Klangteil. Ursprünglich bedeutete das Zeichen einen großen Erdhügel.","s":1,"p":[["阝","Hügel","b"],["可","Klangteil","l"]]},
"悠":{"t":"laut","x":"Unten das Herz (心): Es geht um Gedanken und Gefühle. Oben gibt 攸 den Klang (ユウ). Ursprünglich bedeutete es „sorgenvoll nachdenken“.","s":2,"p":[["攸","Klangteil","l"],["心","Herz","b"]]},
"杏":{"t":"kombi","x":"Ein Baum (木) über einem Mund (口). Das Zeichen steht für den Aprikosenbaum; vielleicht verweist der Mund auf den guten Geschmack der Frucht.","s":1,"p":[["木","Baum","b"],["口","Mund","b"]],"n":"Ein altes Zeichenlexikon sieht 可 als Klangteil, das gilt als unwahrscheinlich.","i":"os"},
"茜":{"t":"laut","x":"Oben das Pflanzenzeichen (艹) für die Krapppflanze, unten 西 als Klangteil.","s":2,"p":[["艹","Pflanze","b"],["西","Klangteil","l"]],"i":"s"},
"栞":{"t":"laut","x":"Unten das Holz (木) als Sinnteil, oben 幵 aus zwei 干 als Klangteil (カン). Das Wort bedeutete „schneiden, abschaben“ (wie heute 刊).","s":1,"p":[["木","Holz","b"],["幵","Klangteil","l"]]},
"伏":{"t":"kombi","x":"Ein Mensch (亻) neben einem Hund (犬). Gemeint ist „sich niederwerfen, sich ducken“, also wie ein Hund auf dem Boden liegen.","s":1,"p":[["亻","Mensch","b"],["犬","Hund","b"]],"n":"Auf den frühesten Inschriften ist es nur ein am Boden liegender Mensch. Eine andere Lesart: ein Hund duckt sich neben dem Menschen und will springen.","i":"bs"},
"鎮":{"t":"laut","x":"Links Metall (釒): Ursprünglich ein Gewicht, das etwas niederdrückt. Rechts gibt 真 den Klang. Daraus wurde „niederhalten, beruhigen“.","s":2,"p":[["金","Metall","b"],["真","Klangteil","l"]],"i":"s"},
"奉":{"t":"laut","x":"Ursprünglich zwei Hände (廾), die etwas darreichen, mit 丰 als Klangteil (ホウ). Später kam unten 手 hinzu, der obere Teil wurde zur heutigen Form verformt. Es bedeutet „darbieten, verehren“.","s":2,"p":[["丰","Klangteil","l"],["廾","zwei Hände","b"],["手","Hand","f"]],"i":"bs"},
"憂":{"t":"laut","x":"Mit dem Herz (心) als Sinnteil: Es geht um Sorgen und Kummer. Welcher Teil genau den Klang trägt, ist in der Forschung unklar.","s":0,"p":[["心","Herz","b"]],"n":"Oft liest man „Kopf + Herz + Fuß: jemand geht grübelnd umher“. Dafür gibt es keine sicheren Belege.","i":"s"},
"朴":{"t":"laut","x":"Links der Baum (木) als Sinnteil, rechts 卜 als Klangteil (ボク). Das Zeichen steht heute für Schlichtheit.","s":2,"p":[["木","Baum","b"],["卜","Klangteil","l"]],"i":"s"},
"惜":{"t":"laut","x":"Links das Herz (忄) als Sinnteil: ein Gefühl. Rechts gibt 昔 den Klang (セキ). Gemeint ist „bedauern, schade finden, sparsam mit etwas umgehen“.","s":2,"p":[["忄","Herz","b"],["昔","Klangteil","l"]],"n":"Manche sehen in 昔 („früher“) auch einen Sinnklang: Gefühle für Vergangenes. Gesichert ist nur der Klang.","i":"s"},
"佳":{"t":"laut","x":"Links der Mensch (亻) als Sinnteil, rechts 圭 als Klangteil. Das Zeichen steht für „schön, vortrefflich“.","s":2,"p":[["亻","Mensch","b"],["圭","Klangteil","l"]],"n":"Früher las man 圭 auch als Sinnteil; das gilt heute als falsch."},
"悼":{"t":"laut","x":"Links das Herz (忄), denn es geht um Trauer. Rechts gibt 卓 den Klang. Es bedeutet „betrauern, beklagen“.","s":2,"p":[["忄","Herz","b"],["卓","Klangteil","l"]]},
"該":{"t":"laut","x":"Links 言 (sprechen) als Sinnteil, rechts 亥 als Klangteil (ガイ). Ursprünglich „tadeln“; später wurde das Zeichen für „alles, entsprechend“ ausgeliehen.","s":2,"p":[["言","Sprechen","b"],["亥","Klangteil","l"]]},
"赴":{"t":"laut","x":"Links und unten 走 (laufen) als Sinnteil, innen 卜 als Klangteil. Es bedeutet „sich begeben, hingehen“.","s":2,"p":[["走","laufen","b"],["卜","Klangteil","l"]],"i":"s"},
"髄":{"t":"laut","x":"Links 骨 (Knochen) als Sinnteil, rechts ein Klangteil (ズイ). Gemeint ist das weiche Mark im Knochen. Die alte Form 髓 ist rechts etwas anders gebaut; heute ist der Teil vereinfacht.","s":1,"p":[["骨","Knochen","b"],["遀","Klangteil","l"]],"a":"髓"},
"傍":{"t":"laut","x":"Links der Mensch (亻) als Sinnteil, rechts 旁 als Klangteil (ボウ). Das Zeichen steht für „Seite, neben“.","s":2,"p":[["亻","Mensch","b"],["旁","Klangteil","l"]]},
"累":{"t":"laut","x":"Die alte Form 纍 hatte 畾 als Klangteil (ライ → ルイ) und 糸 (Faden) als Sinnteil: „binden, Seil“. Später für „aufhäufen“ ausgeliehen. Heute ist 畾 zu 田 verkürzt.","s":2,"p":[["糸","Faden","b"],["田","Klangteil","l"]],"n":"Oft liest man „Feldarbeit (田) und Nähen (糸) machen müde“. Das ist eine spätere Volksdeutung.","a":"纍"},
"癒":{"t":"laut","x":"Außen 疒 (Krankheit) als Sinnteil, innen 愈 als Klangteil (ユ). Gemeint ist „gesund werden, heilen“.","s":1,"p":[["疒","Krankheit","b"],["愈","Klangteil","l"]]},
"郭":{"t":"laut","x":"Ursprünglich das Bild eines hohen Turms an der Stadtmauer. Später kam 邑 (Stadt, links als 阝) dazu. Es steht für „Stadtmauer, Viertel“.","s":1,"p":[["阝","Stadt","b"],["享","Turm","l"]],"n":"Das heutige 享 ist nur zufällig gleich geschrieben und hat mit 享 „genießen“ nichts zu tun.","i":"s"},
"尿":{"t":"bild","x":"Ursprünglich das Bild eines Menschen, der Wasser lässt. In der Siegelschrift wurde daraus „Schwanz (尾) + Wasser (水)“; heute steht oben das verkürzte 尸.","s":2,"p":[["尸","Körper","b"],["水","Wasser","b"]],"i":"os"},
"賓":{"t":"laut","x":"Unten die Muschel (貝) als Sinnteil, oben ein Klangteil (ヒン). Das Zeichen steht für „Gast“.","s":1,"p":[["貝","Muschel","b"],["𡧍","Klangteil","l"]],"i":"obs"},
"虜":{"t":"laut","x":"Das Zeichen steht für „gefangen nehmen“ oder „Gefangener“. Ursprünglich war 力 (Kraft) der Sinnteil und 𧆨 der Klangteil; die heutige Form ist eine verbreitete Variante.","s":1,"p":[["力","Kraft","b"],["𧆨","Klangteil","l"]]},
"憾":{"t":"laut","x":"Links das Herz (忄), denn es geht um ein Gefühl. Rechts gibt 感 den Klang (カン). Es steht für „Bedauern“.","s":2,"p":[["忄","Herz","b"],["感","Klangteil","l"]]},
"弥":{"t":"laut","x":"Links der Bogen (弓) als Sinnteil, rechts ein Klangteil. In der alten Form 彌 ist es 爾; heute ist der Teil verkürzt. Gemeint ist „erfüllen, immer mehr“.","s":2,"p":[["弓","Bogen","b"],["尓","Klangteil","l"]],"n":"Ein altes Zeichenlexikon erklärt es als „den Bogen entspannen“. Diese Bedeutung ist in alten Texten nicht belegt.","a":"彌","i":"s"},
"粗":{"t":"laut","x":"Links der Reis (米) als Sinnteil, rechts 且 als Klangteil (ソ). Gemeint ist „grob“.","s":2,"p":[["米","Reis","b"],["且","Klangteil","l"]],"i":"s"},
"循":{"t":"laut","x":"Links 彳 (Bewegung, gehen) als Sinnteil, rechts 盾 als Klangteil (ジュン). Gemeint ist „entlanggehen, folgen“.","s":2,"p":[["彳","gehen","b"],["盾","Klangteil","l"]]},
"凝":{"t":"laut","x":"Links das Eis (冫) als Sinnteil: etwas wird fest. Rechts gibt 疑 den Klang (ギ → ギョウ). Gemeint ist „gefrieren, sich verfestigen“.","s":2,"p":[["冫","Eis","b"],["疑","Klangteil","l"]],"i":"s"},
"昌":{"t":"kombi","x":"Die Sonne (日) mit einem Zusatzzeichen 口. Das Wort bedeutete „Sonnenlicht“; daraus wurde „hell, blühend“.","s":1,"p":[["日","Sonne","b"],["口","Zusatzzeichen","f"]],"n":"Eine andere Deutung liest 口 als Mund: Rufen oder Singen beim Morgengrauen.","i":"os"},
"旦":{"t":"kombi","x":"Oben die Sonne (日). Das Zeichen steht für den Morgen, wenn die Sonne aufgeht. Was der untere Teil darstellt, ist umstritten.","s":0,"p":[["日","Sonne","b"]],"n":"Oft liest man „Sonne über dem Horizont (一)“. Die alten Schriftformen zeigen, dass der Strich keine Horizontlinie ist; neuere Forschung sieht darin einen Kopf (丁).","i":"obs"},
"愉":{"t":"laut","x":"Links das Herz (忄), denn es geht um Freude. Rechts gibt 兪 den Klang (ユ). Gemeint ist „Freude, Vergnügen“.","s":2,"p":[["忄","Herz","b"],["兪","Klangteil","l"]]},
"抹":{"t":"laut","x":"Links die Hand (扌) als Sinnteil, rechts 末 als Klangteil (マツ). Gemeint ist „reiben, überstreichen, auslöschen“.","s":2,"p":[["扌","Hand","b"],["末","Klangteil","l"]]},
"栓":{"t":"laut","x":"Links das Holz (木) als Sinnteil, rechts 全 als Klangteil. Ursprünglich ein Holzpflock oder Stöpsel.","s":2,"p":[["木","Holz","b"],["全","Klangteil","l"]]},
"之":{"t":"leih","x":"Ein Fuß (止) steht auf einer Startlinie (一): „gehen“. Später wurde das Zeichen für das Wörtchen „von, dieses“ ausgeliehen. Der Fuß ist heute zu einem Punkt geworden.","s":1,"p":[["止","Fuß","b"],["一","Ausgangspunkt","b"]],"n":"Eine andere Analyse sieht 止 als Klangteil.","i":"obs"},
"遼":{"t":"laut","x":"Links unten 辶 (gehen, Weg) als Sinnteil, innen 尞 als Klangteil (リョウ). Gemeint ist „weit entfernt“.","s":2,"p":[["辶","gehen","b"],["尞","Klangteil","l"]]},
"瑛":{"t":"laut","x":"Links die Jade (玉, hier als 王) als Sinnteil, rechts 英 als Klangteil (エイ). Es steht für den Glanz von Edelsteinen.","s":1,"p":[["王","Jade","b"],["英","Klangteil","l"]]},
"那":{"t":"laut","x":"Rechts 阝 (Stadt) als Sinnteil, links ein Klangteil. Ursprünglich der Name eines kleinen Staats; später für „jenes“ ausgeliehen.","s":1,"p":[["冄","Klangteil","l"],["阝","Stadt","b"]],"n":"Die Lautteile stimmen nur teilweise überein; das ist noch nicht geklärt.","i":"s"},
"拍":{"t":"laut","x":"Links die Hand (扌) als Sinnteil, rechts 白 als Klangteil (ハク). Gemeint ist „schlagen, klatschen“; daraus der Takt.","s":2,"p":[["扌","Hand","b"],["白","Klangteil","l"]]},
"猶":{"t":"laut","x":"Links das Tierzeichen (犭), rechts 酋 als Klangteil (ユウ). Ursprünglich ein Name für eine Affenart; später für „noch, immer noch“ ausgeliehen.","s":2,"p":[["犭","Hund, Tier","b"],["酋","Klangteil","l"]],"i":"obs"},
"宰":{"t":"kombi","x":"Ein Haus (宀) mit einem Zeichen für „verwalten“. Gemeint ist ein Verwalter, ein Amtsträger.","s":1,"p":[["宀","Dach, Haus","b"],["辛","(Form)","f"]],"n":"Die untere Form sieht aus wie 辛 („scharf“), gehört aber nicht dazu."},
"寂":{"t":"laut","x":"Oben das Dach (宀) als Sinnteil: still im Haus. Unten 叔 als Klangteil. Gemeint ist „still, einsam“.","s":2,"p":[["宀","Haus","b"],["叔","Klangteil","l"]]},
"縫":{"t":"laut","x":"Links der Faden (糹) als Sinnteil, rechts 逢 als Klangteil (ホウ). Gemeint ist „nähen“.","s":2,"p":[["糸","Faden","b"],["逢","Klangteil","l"]],"i":"s"},
"呉":{"t":"kombi","x":"Die alte Form 吳 zeigt einen Mund (口) und einen Menschen mit schief gelegtem Kopf (夨): laut sprechen. Das heutige 呉 ist oben vereinfacht.","s":2,"p":[["口","Mund","b"],["夨","schiefer Kopf","b"]],"a":"吳","i":"obs"},
"凡":{"t":"unklar","x":"Die Herkunft ist nicht sicher geklärt. Das Zeichen besteht aus zwei senkrechten Strichen ungleicher Länge. Auf Orakelknochen kommt es vor allem als Klangteil vor.","s":0,"n":"Möglicherweise ist es aus 戌 entstanden.","i":"obs"},
"恭":{"t":"laut","x":"Unten das Herz (㣺), denn es geht um die innere Haltung. Oben gibt 共 den Klang (キョウ). Gemeint ist „ehrerbietig“.","s":2,"p":[["共","Klangteil","l"],["㣺","Herz","b"]],"i":"s"},
"錯":{"t":"laut","x":"Links Metall (釒), rechts 昔 als Klangteil. Ursprünglich ging es um Metallüberzug; später ausgeliehen für „mischen“ und „sich irren“.","s":1,"p":[["金","Metall","b"],["昔","Klangteil","l"]],"n":"Oft liest man „aufgeschichtetes Metall → mischen“. Der Klangteil trägt hier keinen Sinn."},
"穀":{"t":"laut","x":"Links das Getreide (禾) als Sinnteil, rechts ein Klangteil (殼, コク). Gemeint ist „Getreide“.","s":2,"p":[["禾","Getreide","b"],["殻","Klangteil","l"]]},
"陵":{"t":"laut","x":"Links der Hügel (阝) als Sinnteil, rechts 夌 als Klangteil (リョウ). Gemeint ist „Hügel, Grabhügel“.","s":2,"p":[["阝","Hügel","b"],["夌","Klangteil","l"]],"n":"Früher las man 夌 auch als Sinnteil; das gilt heute als falsch."},
"弊":{"t":"laut","x":"Oben 敝 als Klangteil (ヘイ), unten zwei Hände (廾). Gemeint ist etwas Kaputtes, Schädliches.","s":2,"p":[["敝","Klangteil","l"],["廾","zwei Hände","b"]]},
"舶":{"t":"laut","x":"Links das Boot (舟) als Sinnteil, rechts 白 als Klangteil (ハク). Gemeint ist „großes Schiff“.","s":2,"p":[["舟","Boot","b"],["白","Klangteil","l"]]},
"窮":{"t":"laut","x":"Oben die Höhle (穴) als Sinnteil, unten 躬 als Klangteil (キュウ). Gemeint ist „am Ende sein, bedrängt sein“.","s":2,"p":[["穴","Höhle","b"],["躬","Klangteil","l"]]},
"悦":{"t":"laut","x":"Links das Herz (忄) als Sinnteil, rechts 兌 als Klangteil. Ursprünglich stand 兌 allein für „sich freuen“; 心 kam später dazu.","s":2,"p":[["忄","Herz","b"],["兌","Klangteil","l"]]},
"縛":{"t":"laut","x":"Links der Faden (糹) als Sinnteil, rechts 尃 als Klangteil (バク). Gemeint ist „binden, fesseln“.","s":2,"p":[["糸","Faden","b"],["尃","Klangteil","l"]]},
"轄":{"t":"laut","x":"Links der Wagen (車) als Sinnteil, rechts 害 als Klangteil. Gemeint ist ein Keil, der das Rad festhält.","s":2,"p":[["車","Wagen","b"],["害","Klangteil","l"]]},
"弦":{"t":"zeichen","x":"Ursprünglich ein Bogen 弓 mit einem Markierungsstrich an der Sehne: Das Zeichen zeigte auf die Bogensehne. Später löste sich der Sehnenteil ab und wurde zum separaten Bauteil 玄.","s":1,"p":[["弓","Bogen","b"],["玄","(Lautform)","f"]],"n":"Oft liest man 弦 als „Bogen + Klangteil 玄“. Die Lautlage im Altchinesischen passt dafür aber nicht, daher gilt es heute eher als Hinweiszeichen."},
"窒":{"t":"laut","x":"Die Höhle 穴 gibt den Sinnbereich vor (etwas verstopfen, zumachen), 至 liefert den Klang. Bedeutung: „verstopfen, ersticken“ (チツ).","s":2,"p":[["穴","Höhle","b"],["至","ankommen","l"]]},
"洪":{"t":"laut","x":"Wasser 氵 zeigt den Sinn „große Wassermassen, Flut“, 共 liefert den Klang. Daher steht 洪 für Flut und allgemein für „riesig“.","s":2,"p":[["氵","Wasser","b"],["共","gemeinsam","l"]],"i":"s"},
"摂":{"t":"laut","x":"Die alte Form 攝 besteht aus Hand 扌 (Sinnteil) und 聶 (Klangteil). Im heutigen 摂 wurde das komplizierte 聶 stark vereinfacht. Gemeint ist „ergreifen, in sich aufnehmen“.","s":2,"p":[["扌","Hand","b"],["聶","(Lautteil)","l"]],"a":"攝","i":"s"},
"飽":{"t":"laut","x":"Essen 飠 gibt den Sinnbereich (satt sein), 包 den Klang: 包 ホウ → 飽 ホウ. Gemeint ist „satt, übersatt“.","s":2,"p":[["飠","Essen","b"],["包","einwickeln","l"]],"i":"s"},
"紳":{"t":"laut","x":"Seide 糸 zeigt den Sinn: Gemeint war ein breiter Gürtel (Schärpe) für festliche Kleidung. 申 liefert den Klang: 申 シン → 紳 シン. Später heißt 紳 allgemein „Herr, Gentleman“.","s":2,"p":[["糸","Seide","b"],["申","sich erstrecken","l"]]},
"庸":{"t":"laut","x":"Ursprünglich das Zeichen für eine große Glocke (鏞): 庚 als Sinnteil, 用 als Klangteil (ヨウ). Später wurde das Zeichen für ein gleich klingendes Wort geliehen: „beschäftigen, brauchen“.","s":1,"p":[["庚","(Sinnteil)","b"],["用","gebrauchen","l"]],"n":"Die alte Erklärung, 庸 sei eine Sinnverbindung, gilt als Fehlanalyse.","i":"o"},
"靖":{"t":"laut","x":"立 (stehen, aufstellen) gibt den Sinn, 青 den Klang: 青 セイ → 靖 セイ. Gemeint ist „zur Ruhe kommen, befrieden“.","s":2,"p":[["立","stehen","b"],["青","blau, grün","l"]]},
"嘉":{"t":"laut","x":"Ein Sinnteil oben (kein „Mund“) und 加 als Klangteil (カ). Gemeint ist „gut, lobenswert“.","s":1,"p":[["𪲓","(Sinnteil)","b"],["加","hinzufügen","l"]],"n":"Oft liest man 壴 (Trommel) als oberen Teil. Die alten Schriftformen zeigen aber, dass der Teil nichts mit 壴 zu tun hat."},
"搾":{"t":"laut","x":"Hand 扌 zeigt das Tun (mit der Hand), 窄 liefert den Klang (サク). Gemeint ist „auspressen, auswringen“.","s":1,"p":[["扌","Hand","b"],["窄","eng","l"]],"n":"Manchmal wird 搾 für ein in Japan erfundenes Zeichen gehalten. Es entstand aber schon in China (etwa zur Song-Zeit) als Variante von 榨."},
"蝶":{"t":"laut","x":"Insekt 虫 gibt den Sinnbereich, 枼 den Klang. 蝶 steht für den Schmetterling.","s":2,"p":[["虫","Insekt","b"],["枼","(Lautteil)","l"]]},
"碑":{"t":"laut","x":"Stein 石 zeigt das Material, 卑 liefert den Klang: 卑 ヒ → 碑 ヒ. Gemeint ist ein Stein mit Inschrift, ein Denkmal.","s":2,"p":[["石","Stein","b"],["卑","niedrig","l"]]},
"尉":{"t":"unklar","x":"Die Herkunft ist nicht geklärt. Möglicherweise hängt das Zeichen mit 𡰥 zusammen und enthält Hand (寸) und Feuer. Es wird als Rangbezeichnung („Offizier“) benutzt.","s":0,"i":"s"},
"匠":{"t":"laut","x":"Das Beil 斤 steht für das Handwerkszeug, 匚 ist der Klangteil. 匠 bedeutet „Handwerker, Meister“.","s":2,"p":[["斤","Beil","b"],["匚","Behälter","l"]],"n":"Traditionell liest man es als „Kiste + Beil“ (Sinnverbindung). Neuere Forschung sieht 匚 als Lautteil.","i":"s"},
"遥":{"t":"laut","x":"Weg 辶 gibt den Sinnbereich (weit gehen), 䍃 den Klang (ヨウ). Gemeint ist „fern, weit entfernt“.","s":1,"p":[["辶","Weg","b"],["䍃","(Lautteil)","l"]]},
"智":{"t":"kombi","x":"Ursprünglich ein Erwachsener, ein Kind und ein Mund: Wissen wird weitergegeben. Die Teile verschliffen. Heute: 知 plus 日 als verformter Mund. Gemeint ist „Weisheit“.","s":2,"p":[["知","wissen","b"],["日","(Mund)","f"]],"n":"Oft liest man 矢 als Klangteil in 知/智. Die Forschung sieht 矢 aber als verformtes 大, nicht als Klang.","i":"obs"},
"賊":{"t":"kombi","x":"Ursprünglich ein Schatz (貝) wird mit einer Waffe zerstört: Das Zeichen steht für „schädigen, zerstören“. Daraus wurde „Räuber, Rebell“.","s":1,"p":[["貝","Muschelgeld","b"],["戎","Waffe","b"]],"n":"Eine andere Analyse sieht 則 als Klangteil und 戈 (Waffe) als Sinnteil. Die heutige Form wurde später als 貝 + 戎 gelesen.","i":"bs"},
"鼓":{"t":"kombi","x":"Eine Trommel 壴 und eine Hand mit Schlägel 支. Das Zeichen zeigt, wie eine Trommel geschlagen wird. Es steht für „Trommel, Trommeln“.","s":2,"p":[["壴","Trommel","b"],["支","Hand mit Schlägel","b"]],"i":"obs"},
"旋":{"t":"laut","x":"Zuerst eine Fahne und ein Fuß (sich bewegen). Dann kam ein Kreis 〇 als Klangteil hinzu; der Kreis verschmolz mit dem Fuß zum heutigen 疋. Gemeint ist „kreisen, sich drehen“.","s":2,"p":[["方","Fahne","b"],["疋","Fuß + Kreis","l"]]},
"腸":{"t":"laut","x":"月 steht hier für Fleisch/Körper und zeigt den Sinnbereich. 昜 liefert den Klang. 腸 ist der Darm.","s":2,"p":[["月","Fleisch","b"],["昜","(Lautteil)","l"]]},
"槽":{"t":"laut","x":"Holz 木 zeigt das Material: ein hölzerner Trog oder Bottich. 曹 liefert den Klang: 曹 ソウ → 槽 ソウ.","s":2,"p":[["木","Holz","b"],["曹","Gruppe","l"]],"i":"s"},
"伐":{"t":"kombi","x":"Ein Mensch 亻 und eine Waffe 戈: Man schlägt mit der Waffe auf den Hals eines Menschen. Daraus wurde „(ab)hauen, fällen, angreifen“.","s":2,"p":[["亻","Mensch","b"],["戈","Speer","b"]],"i":"obs"},
"漬":{"t":"laut","x":"Wasser 氵 zeigt den Sinn: etwas in Flüssigkeit tauchen. 責 liefert den Klang. Gemeint ist „einweichen, einlegen“.","s":2,"p":[["氵","Wasser","b"],["責","Schuld","l"]],"n":"Der Klangteil 責 hat selbst einen Klangteil (朿)."},
"坪":{"t":"laut","x":"Erde 土 gibt den Sinn (Boden, Grundfläche), 平 den Klang: 平 ヘイ → 坪 ヘイ. 坪 ist ein Flächenmaß.","s":2,"p":[["土","Erde","b"],["平","eben","l"]]},
"紺":{"t":"laut","x":"Seide 糸 verweist auf gefärbten Stoff, 甘 liefert den Klang. Gemeint ist die Farbe Dunkelblau.","s":2,"p":[["糸","Seide","b"],["甘","süß","l"]],"i":"s"},
"羅":{"t":"kombi","x":"Ursprünglich ein Netz zum Vogelfang: Das Netzzeichen bekam einen Vogel, dann einen Faden. So entstand „Netz“, später „aufreihen, dicht gestreut“.","s":1,"p":[["罒","Netz","b"],["隹","Vogel","b"],["糸","Faden","b"]],"n":"Die Erklärung „Netz + 維“ (Shuowen) gilt als falsch.","i":"os"},
"峡":{"t":"laut","x":"Die alte Form 峽 hat Berg 山 als Sinnteil und 夾 (einklemmen) als Klangteil. Die Schlucht liegt zwischen Bergen. Im heutigen 峡 wurde 夾 vereinfacht.","s":2,"p":[["山","Berg","b"],["夹","einklemmen","l"]],"a":"峽"},
"俸":{"t":"laut","x":"Der Mensch 亻 gibt den Sinnbereich, 奉 den Klang: 奉 ホウ → 俸 ホウ. 俸 steht für Gehalt, Besoldung.","s":2,"p":[["亻","Mensch","b"],["奉","darbringen","l"]]},
"醸":{"t":"laut","x":"Der Weinkrug 酉 steht für Alkohol, 襄 liefert den Klang (ジョウ). Gemeint ist „brauen, vergären lassen“. In der heutigen Form ist 襄 vereinfacht zu 㐮.","s":2,"p":[["酉","Weinkrug","b"],["襄","(Lautteil)","l"]],"a":"釀"},
"弔":{"t":"leih","x":"Ursprünglich ein Mensch, um den ein Pfeil mit Schnur gewickelt ist (Jagdwaffe mit Fangschnur). Später wurde das Zeichen für das gleich klingende Wort „kondolieren, betrauern“ ausgeliehen.","s":1,"n":"Neuere Forschung deutet es als Mensch, den eine Schlange umwindet. Die alte Erklärung „Mensch + Bogen“ gilt als falsch.","i":"bs"},
"乙":{"t":"unklar","x":"Die Herkunft ist unklar. Das Zeichen dient als zweites der zehn Himmelsstämme und wird für „zweiter, andere Seite, seltsam“ gebraucht.","s":0,"n":"Vorgeschlagen wurden eine sprießende Pflanze, ein Fischdarm, ein Wasserlauf oder ein Knochenspatel. Keine Deutung ist belegt.","i":"obs"},
"遍":{"t":"laut","x":"Der Weg 辶 gibt den Sinn (sich ausbreiten, überall hingehen), 扁 den Klang: 扁 ヘン → 遍 ヘン. Gemeint ist „überall, allgemein“.","s":2,"p":[["辶","Weg","b"],["扁","flach","l"]]},
"衡":{"t":"laut","x":"行 liefert den Klang (コウ). Die Mitte 角 + 大 trägt den Sinn, ihre genaue Herkunft ist unklar. Gemeint ist „Waage, Gleichgewicht“.","s":1,"p":[["行","gehen","l"],["角","Horn","b"],["大","groß","b"]],"i":"s"},
"款":{"t":"kombi","x":"Aus 柰 und 欠. Ursprünglich 歀 mit 木 statt 士; die Form wurde im Lauf der Zeit verändert. Gemeint ist „Aufrichtigkeit“, dann „Artikel, Abschnitt“.","s":1,"p":[["柰","(Bauteil)","b"],["欠","Mangel, Lücke","b"]],"n":"Eine Lesart sieht 柰 als Klangteil und 欠 als Sinnteil; die Forschung ist uneinig."},
"閲":{"t":"laut","x":"Tor 門 und 兌 als Klangteil (エツ/タイ-Gruppe). Gemeint ist „durchsehen, prüfen“.","s":1,"p":[["門","Tor","b"],["兑","(Lautteil)","l"]]},
"喝":{"t":"laut","x":"Der Mund 口 steht für die Stimme, 曷 liefert den Klang (カツ). Gemeint ist „anschreien, laut rufen“.","s":2,"p":[["口","Mund","b"],["曷","(Lautteil)","l"]],"i":"s"},
"敢":{"t":"leih","x":"Eine Hand mit Fanggerät jagt ein Wildschwein: ursprünglich „fangen, überfallen“. Später wurde das Zeichen für ein gleich klingendes Wort geliehen: „wagen, sich trauen“.","s":2,"n":"Die Bestandteile veränderten sich stark; ein später hinzugefügter Mund oder 甘 war nur Zusatz.","i":"obs"},
"膜":{"t":"laut","x":"月 steht für Fleisch/Körper: eine Haut im Körper. 莫 liefert den Klang: 莫 バク → 膜 マク. Gemeint ist „Haut, Membran“.","s":2,"p":[["月","Fleisch","b"],["莫","(Lautteil)","l"]],"i":"s"},
"盲":{"t":"laut","x":"Das Auge 目 zeigt den Sinn (Sehen), 亡 den Klang (ボウ/モウ). Gemeint ist „blind“.","s":2,"p":[["目","Auge","b"],["亡","verlieren","l"]],"i":"s"},
"胎":{"t":"laut","x":"月 für Körper(fleisch) und 台 als Klangteil: 台 タイ → 胎 タイ. Gemeint ist „Mutterleib, Embryo“.","s":2,"p":[["月","Fleisch","b"],["台","(Lautteil)","l"]],"i":"s"},
"酵":{"t":"laut","x":"Der Weinkrug 酉 zeigt den Sinn: Gären und Alkohol. 孝 liefert den Klang: 孝 コウ → 酵 コウ. Gemeint ist „Gärung, Hefe“.","s":2,"p":[["酉","Weinkrug","b"],["孝","Kindespflicht","l"]]},
"堕":{"t":"laut","x":"Die alte Form 墮 hat Erde 土 als Sinnteil und 隋 als Klangteil (ダ). Man fällt auf den Boden. Im heutigen 堕 ist 隋 verkürzt. Gemeint ist „herabfallen, sinken“.","s":2,"p":[["陏","(Lautteil)","l"],["土","Erde","b"]],"a":"墮"},
"遮":{"t":"laut","x":"Der Weg 辶 gibt den Sinn (sich in den Weg stellen), 庶 den Klang (ショ → シャ). Gemeint ist „versperren, abschirmen“.","s":2,"p":[["辶","Weg","b"],["庶","viele","l"]]},
"凸":{"t":"bild","x":"Ein Bildzeichen: Die Form zeigt etwas, das nach oben hervorragt. Gemeint ist „hervorstehend, konvex“.","s":1,"n":"Es gibt Hinweise, dass das Zeichen zwei verschiedene Ursprünge hat (als Variante von 突 und als Variante anderer Zeichen)."},
"凹":{"t":"bild","x":"Ein Bildzeichen: Die Form zeigt etwas, das eingedrückt ist. Gemeint ist „eingedellt, konkav“.","s":1},
"楓":{"t":"laut","x":"Der Baum 木 zeigt den Sinn, 風 liefert den Klang: 風 フウ → 楓 フウ. Gemeint ist der Ahorn.","s":2,"p":[["木","Baum","b"],["風","Wind","l"]]},
"哉":{"t":"laut","x":"Der Mund 口 zeigt: Es ist ein gesprochener Ausruf. 𢦏 liefert den Klang (サイ). 哉 steht für „wie …!“ oder „ach!“.","s":2,"p":[["口","Mund","b"],["𢦏","(Lautteil)","l"]]},
"蒼":{"t":"laut","x":"Pflanze 艹 zeigt den Sinn (Grün), 倉 liefert den Klang: 倉 ソウ → 蒼 ソウ. Gemeint ist „tiefgrün, blassblau“.","s":2,"p":[["艹","Pflanze","b"],["倉","Lager","l"]],"i":"s"},
"瑠":{"t":"laut","x":"王 steht hier für Jade (玉) als Sinnteil, 留 liefert den Klang (リュウ). 瑠 steht im Wort 瑠璃 für Lapislazuli.","s":2,"p":[["王","Edelstein","b"],["留","bleiben","l"]]},
"萌":{"t":"laut","x":"Pflanze 艹 und 明 als Klangteil. Das Zeichen bedeutet „sprießen, ausschlagen“.","s":1,"p":[["艹","Pflanze","b"],["明","hell","l"]],"n":"Nach einer zweiten Erklärung entstand das Zeichen durch Verformung eines anderen Zeichens und wurde nur für „sprießen“ ausgeliehen."},
"硫":{"t":"laut","x":"Stein 石 für den Stoff, 㐬 (aus 流) für den Klang: 流 リュウ → 硫 リュウ. 硫 steht für Schwefel.","s":2,"p":[["石","Stein","b"],["㐬","(Lautteil)","l"]]},
"赦":{"t":"laut","x":"Ursprünglich ein Stock in der Hand (攵) mit 亦 als Klangteil. In späteren Schriften wurde 亦 durch ähnliches 赤 ersetzt. Gemeint ist „vergeben, begnadigen“.","s":2,"p":[["亦","auch","l"],["攵","schlagen","b"]],"n":"Oft liest man 赤 (rot) als Klangteil. Die Bronzeschrift zeigt aber, dass es ursprünglich 亦 war."},
"窃":{"t":"laut","x":"Die Höhle 穴 ist der Sinnteil, 切 liefert den Klang (セツ). 窃 ist die vereinfachte Form von 竊 mit anderem Klangteil. Gemeint ist „stehlen, heimlich“.","s":1,"p":[["穴","Höhle","b"],["切","schneiden","l"]],"a":"竊","i":"s"},
"慨":{"t":"laut","x":"Das Herz 忄 zeigt Gefühl, 既 liefert den Klang. Gemeint ist „seufzen, bedauern“.","s":2,"p":[["忄","Herz","b"],["既","schon","l"]]},
"扶":{"t":"laut","x":"Die Hand 扌 zeigt das Tun, 夫 den Klang: 夫 フ → 扶 フ. Gemeint ist „stützen, helfen“.","s":2,"p":[["扌","Hand","b"],["夫","Mann","l"]]},
"戯":{"t":"laut","x":"Die alte Form 戲 hat die Waffe 戈 als Sinnteil und 䖒 als Klangteil (ギ). Heute steht 虚 für 䖒. Gemeint ist „spielen, Scherz“.","s":2,"p":[["虚","(ersetzt 䖒)","l"],["戈","Hellebarde","b"]],"a":"戲","i":"s"},
"忌":{"t":"laut","x":"Das Herz 心 zeigt das Gefühl, 己 liefert den Klang (キ). Gemeint ist „meiden, verabscheuen“, daher „Trauerzeit“.","s":2,"p":[["己","selbst","l"],["心","Herz","b"]]},
"濁":{"t":"laut","x":"Wasser 氵 zeigt den Sinn: trübes, schmutziges Wasser. 蜀 liefert den Klang. Gemeint ist „trüb“, auch „stimmhaft“.","s":2,"p":[["氵","Wasser","b"],["蜀","(Lautteil)","l"]],"i":"s"},
"奔":{"t":"kombi","x":"Ein laufender Mensch (alte Form von 走) und drei Füße 止: schnelles Rennen. Gemeint ist „rennen, davonstürmen“. Die Teile sind zu 大 + 卉 verschliffen.","s":2,"p":[["大","laufender Mensch","b"],["卉","drei Füße 止","f"]],"n":"Die Deutung „夭 + Klangteil 卉“ gilt als falsch.","i":"bs"},
"肖":{"t":"laut","x":"Ursprünglich ein Zeichen für „Nacht“ (宵): Mond 月 als Sinnteil, 小 als Klangteil. Später wurde es für ein gleich klingendes Wort geliehen: „ähneln“.","s":2,"p":[["小","klein","l"],["月","Mond","b"]],"n":"Die Erklärung „Fleisch + 小“ (Shuowen) gilt als falsch: 月 ist hier der Mond.","i":"s"},
"朽":{"t":"laut","x":"Holz 木 zeigt den Sinn (faules Holz), 丂 liefert den Klang. Gemeint ist „verfaulen, vermodern“.","s":2,"p":[["木","Holz","b"],["丂","(Kurzform 考)","l"]]},
"殻":{"t":"laut","x":"Ursprünglich „schlagen, klopfen“: 殳 trägt den Sinn, 壳 den Klang (カク). Später wurde das Zeichen für ein gleich klingendes Wort geliehen: „Schale, Hülle“.","s":1,"p":[["壳","(Lautteil)","l"],["殳","schlagen","b"]]},
"享":{"t":"bild","x":"Ein Bildzeichen für ein Gebäude, vermutlich ein Ahnenschrein. Ursprünglich „darbringen, opfern“, heute „genießen, empfangen“.","s":1,"n":"Das 享 in 郭 sieht ähnlich aus, hat aber einen anderen Ursprung (Stadtmauer).","i":"obs"},
"藩":{"t":"laut","x":"Pflanze 艹 zeigt den Sinn (Hecke, Umzäunung), 潘 liefert den Klang: 潘 ハン → 藩 ハン. Gemeint ist „Einfriedung“, dann „Lehen, Domäne“.","s":2,"p":[["艹","Pflanze","b"],["潘","(Lautteil)","l"]]},
"媒":{"t":"laut","x":"Die Frau 女 zeigt den Sinn, 某 den Klang. 媒 steht für den Heiratsvermittler und allgemein für „vermitteln“.","s":2,"p":[["女","Frau","b"],["某","irgendein","l"]],"i":"s"},
"鶏":{"t":"laut","x":"Der Vogel 鳥 trägt den Sinn, 奚 den Klang (ケイ). Das heutige 鶏 ist eine verkürzte Schreibform der alten 鷄. Gemeint ist das Huhn.","s":2,"p":[["奚","(Lautteil)","l"],["鳥","Vogel","b"]],"a":"鷄"},
"嘱":{"t":"laut","x":"Der Mund 口 zeigt: etwas sagen. 屬 liefert den Klang (ショク). Im heutigen Zeichen steht die Kurzform 属. Gemeint ist „auftragen, anvertrauen“.","s":2,"p":[["口","Mund","b"],["属","gehören","l"]],"a":"囑"},
"迭":{"t":"laut","x":"Der Weg 辶 zeigt die Bewegung, 失 den Klang (失 シツ → 迭 テツ). Gemeint ist „abwechseln, ablösen“.","s":2,"p":[["辶","Weg","b"],["失","verlieren","l"]]},
"椎":{"t":"laut","x":"Holz 木 für das Material, 隹 für den Klang. Gemeint ist ursprünglich ein Holzhammer. Daraus ergibt sich „Hammer, Schlägel“.","s":2,"p":[["木","Holz","b"],["隹","Vogel","l"]]},
"絹":{"t":"laut","x":"Seide 糸 zeigt den Sinn, 肙 liefert den Klang (ケン). 絹 steht für Seide(nstoff).","s":2,"p":[["糸","Seide","b"],["肙","(Lautteil)","l"]]},
"陪":{"t":"laut","x":"Links 阝 (Hügel, Erdhaufen), rechts der Klangteil 咅. Das Zeichen stand zuerst für „Erde aufhäufen“; später wurde es für das gleich klingende Wort „begleiten, zur Seite stehen“ ausgeliehen.","s":2,"p":[["阝","Hügel","b"],["咅","(Klangteil)","l"]]},
"剖":{"t":"laut","x":"Das Messer 刂 gibt den Sinn: etwas mit einem Messer in zwei Teile schneiden. 咅 liefert den Klang. Daraus wurde „aufschneiden, teilen“.","s":2,"p":[["刂","Messer","b"],["咅","(Klangteil)","l"]]},
"譜":{"t":"laut","x":"訁 (Sprache, Worte) gibt den Sinnbereich, 普 den Klang (フ → 譜 フ). Gemeint ist etwas Aufgeschriebenes, eine Aufzeichnung – daher Stammbaum und Notenschrift.","s":2,"p":[["訁","Sprache","b"],["普","allgemein","l"]]},
"淑":{"t":"laut","x":"氵 steht für Wasser (Sinnteil), 叔 liefert den Klang (叔 シュク → 淑 シュク). Das Zeichen bedeutet „sanft, rein, anmutig“.","s":2,"p":[["氵","Wasser","b"],["叔","Onkel","l"]],"i":"s"},
"帆":{"t":"laut","x":"巾 (Tuch) ist der Sinnteil: ein Segel besteht aus Stoff. 凡 liefert den Klang (ハン).","s":2,"p":[["巾","Tuch","b"],["凡","gewöhnlich","l"]]},
"憤":{"t":"laut","x":"忄 (Herz, Gefühl) zeigt, dass es um eine Gemütsregung geht, 賁 liefert den Klang. Gemeint ist „sich empören, zornig sein“.","s":2,"p":[["忄","Herz","b"],["賁","(Klangteil)","l"]],"i":"s"},
"酌":{"t":"laut","x":"酉 (Krug mit Wein) gibt den Sinn, 勺 den Klang (勺 シャク → 酌 シャク). Gemeint ist das Einschenken und Trinken von Wein; das Zeichen steht für „schöpfen, einschenken“.","s":2,"p":[["酉","Weinkrug","b"],["勺","Schöpflöffel","l"]],"i":"obs"},
"暁":{"t":"laut","x":"Die alte Form 曉 hatte links 日 (Sonne, Tag) und rechts den Klangteil 堯 (ギョウ). Gemeint ist die Morgendämmerung. Heute ist der Klangteil zu 尭 verkürzt.","s":2,"p":[["日","Sonne","b"],["尭","(Klangteil)","l"]],"a":"曉","i":"s"},
"傑":{"t":"laut","x":"亻 steht für einen Menschen, 桀 liefert den Klang (ケツ). Gemeint ist ein herausragender, überragender Mensch.","s":2,"p":[["亻","Mensch","b"],["桀","(Klangteil)","l"]]},
"錠":{"t":"laut","x":"釒 (Metall) ist der Sinnteil, 定 liefert den Klang (定 ジョウ → 錠 ジョウ). Das Zeichen bezeichnete ursprünglich ein Gefäß aus Metall; später wurde es für Schloss und Tablette gebraucht.","s":1,"p":[["釒","Metall","b"],["定","festlegen","l"]]},
"凌":{"t":"laut","x":"冫 (Eis) ist der Sinnteil, 夌 liefert den Klang (リョウ). Das Zeichen bedeutet „überwinden, bezwingen, ertragen“.","s":1,"p":[["冫","Eis","b"],["夌","(Klangteil)","l"]]},
"瑞":{"t":"laut","x":"𤣩 (Jade, Edelstein) ist der Sinnteil, 耑 liefert den Klang. Das Zeichen bedeutet „glückverheißend“.","s":1,"p":[["𤣩","Jade","b"],["耑","(Klangteil)","l"]],"i":"s"},
"璃":{"t":"laut","x":"𤣩 (Jade, Edelstein) zeigt den Sinnbereich, 离 liefert den Klang (リ). Das Zeichen kommt in den Wörtern für zwei der „sieben Kostbarkeiten“ vor: 瑠璃 (Lapislazuli) und 玻璃 (Glas).","s":2,"p":[["𤣩","Jade","b"],["离","(Klangteil)","l"]]},
"遷":{"t":"laut","x":"辶 (Bewegung, Weg) gibt den Sinn: sich von einem Ort zum anderen bewegen. 䙴 liefert den Klang (セン). Daraus wurde „umziehen, verlegen, sich wandeln“.","s":2,"p":[["辶","gehen","b"],["䙴","(Klangteil)","l"]],"i":"s"},
"拙":{"t":"laut","x":"扌 (Hand) zeigt: Es geht um Handwerk und Geschick. 出 gibt den Klang. Die Bedeutung ist „ungeschickt, unbeholfen, schlecht“.","s":2,"p":[["扌","Hand","b"],["出","hinaus","l"]]},
"峠":{"t":"kombi","x":"Ein in Japan geschaffenes Zeichen: Auf dem Berg 山 geht es erst hinauf 上 und dann hinunter 下. Das ist der Bergpass, die höchste Stelle des Weges.","s":2,"p":[["山","Berg","b"],["上","hinauf","b"],["下","hinunter","b"]]},
"篤":{"t":"laut","x":"Nach dem alten Wörterbuch bedeutete das Zeichen „ein Pferd, das langsam geht“, mit 馬 als Sinnteil und 竹 als Klangteil. Belege dafür fehlen jedoch; später wurde es für „aufrichtig, eifrig“ ausgeliehen.","s":1,"p":[["竹","Bambus","l"],["馬","Pferd","b"]],"i":"s"},
"叔":{"t":"leih","x":"Eine Hand 又 hält einen Pfahl 尗 und gräbt damit die Erde auf. So entstand das Zeichen für „graben“. Später wurde es für das gleich klingende Wort „jüngerer Bruder des Vaters, Onkel“ ausgeliehen.","s":2,"p":[["尗","Pfahl","b"],["又","Hand","b"]],"n":"Das 叔 in 寂 und 椒 ist ein anderes Bauteil und hat mit diesem Zeichen nichts zu tun.","i":"bs"},
"雌":{"t":"laut","x":"隹 (kurzschwänziger Vogel) zeigt, dass es um Tiere geht, 此 liefert den Klang. Das Zeichen bedeutet „weiblich, Weibchen“.","s":2,"p":[["此","dies","l"],["隹","Vogel","b"]],"i":"s"},
"堪":{"t":"laut","x":"土 (Erde) ist der Sinnteil, 甚 liefert den Klang. Das Zeichen bedeutet „aushalten, ertragen“.","s":2,"p":[["土","Erde","b"],["甚","sehr","l"]],"i":"s"},
"吟":{"t":"laut","x":"口 (Mund) zeigt, dass es um Sprechen und Singen geht, 今 liefert den Klang. Gemeint ist „(ein Gedicht) vortragen, summen“.","s":2,"p":[["口","Mund","b"],["今","jetzt","l"]],"i":"s"},
"甚":{"t":"unklar","x":"Wie das Zeichen aufgebaut ist, weiß man nicht sicher. Es bedeutet „sehr, außerordentlich“.","s":0,"n":"Oft liest man „süß 甘 + Paar 匹“. Die alten Bronzeformen zeigen aber, dass das nicht stimmt.","i":"bs"},
"崇":{"t":"laut","x":"山 (Berg) gibt den Sinn: hoch wie ein Berg. 宗 liefert den Klang. Aus „hoch“ wurde „erhaben“ und dann „verehren“.","s":2,"p":[["山","Berg","b"],["宗","Ahnen","l"]]},
"漆":{"t":"laut","x":"Die Lackmasse (Urushi) hieß ursprünglich 桼. Später kam 氵 (Wasser, Flüssigkeit) dazu, weil der Lack flüssig ist. 桼 gibt auch den Klang (シツ).","s":2,"p":[["氵","Wasser","b"],["桼","Lackbaum-Harz","l"]]},
"岬":{"t":"laut","x":"山 (Berg) zeigt den Sinnbereich, 甲 liefert den Klang (コウ). Das Zeichen bezeichnete ursprünglich etwas zwischen Bergen; in Japan benutzt man es für „Kap, Landspitze“.","s":2,"p":[["山","Berg","b"],["甲","Panzer","l"]]},
"紡":{"t":"laut","x":"糹 (Seidenfaden) zeigt: Es geht um Garn. 方 liefert den Klang. Das Zeichen bedeutet „spinnen“.","s":2,"p":[["糹","Faden","b"],["方","Richtung","l"]]},
"礁":{"t":"laut","x":"石 (Stein) zeigt den Sinn, 焦 liefert den Klang (ショウ). Gemeint ist ein verborgener Felsen im Wasser, ein Riff.","s":1,"p":[["石","Stein","b"],["焦","verbrennen","l"]]},
"屯":{"t":"bild","x":"Das Zeichen bildet einen jungen Spross ab, der gerade aus der Erde kommt. So steht es für das Aufkeimen.","s":2,"i":"obs"},
"姻":{"t":"laut","x":"女 (Frau) gibt den Sinn: Heirat betrifft eine Frau. 因 liefert den Klang (イン). Das Zeichen bedeutet „Heirat, angeheiratete Verwandtschaft“.","s":2,"p":[["女","Frau","b"],["因","Grund","l"]],"n":"Früher deutete man 因 auch als Sinnteil. Das gilt heute als Fehlanalyse."},
"擬":{"t":"laut","x":"扌 (Hand) steht für eine Tätigkeit, 疑 liefert den Klang (ギ). Das Zeichen bedeutet „nachahmen, nachbilden, etwas nachahmend vorhaben“.","s":2,"p":[["扌","Hand","b"],["疑","zweifeln","l"]]},
"睦":{"t":"laut","x":"目 (Auge) ist der Sinnteil, 坴 liefert den Klang. Das Zeichen bedeutet „einander freundlich ansehen“, also „freundschaftlich, eng verbunden sein“.","s":1,"p":[["目","Auge","b"],["坴","(Klangteil)","l"]],"i":"s"},
"閑":{"t":"leih","x":"Ein Querbalken 木 vor dem Tor 門: der Riegel. Das Zeichen stand ursprünglich für „Riegel, Sperre“. Später wurde es für das gleich klingende Wort „Muße, freie Zeit“ ausgeliehen.","s":2,"p":[["門","Tor","b"],["木","Holz","b"]],"i":"bs"},
"曹":{"t":"kombi","x":"Ursprünglich zwei nebeneinanderstehende Bündel 東. Es bedeutete „Paar, Gruppe, Gleichgestellte“. Später kam ein Zusatzzeichen (口) dazu, das sich zu 曰 wandelte.","s":2,"p":[["東","Bündel","b"],["曰","(Zusatz)","f"]],"n":"Das Zeichen hat nichts mit 曲 zu tun, obwohl der obere Teil heute so aussieht.","i":"obs"},
"詠":{"t":"laut","x":"訁 (Sprache, Worte) ist der Sinnteil, 永 liefert den Klang (永 エイ → 詠 エイ). Gemeint ist das Vortragen eines Gedichts, „singen, rezitieren“.","s":2,"p":[["訁","Sprache","b"],["永","lang","l"]]},
"卑":{"t":"unklar","x":"Was das Zeichen ursprünglich abbildet, ist unklar. Es wurde für das gleich klingende Wort „niedrig“ benutzt.","s":0,"n":"Oft liest man „eine Hand mit einem Fächer: ein Diener“. Es gibt viele andere Vorschläge (Becher, Hammer, Korb); keiner ist gesichert.","i":"bs"},
"侮":{"t":"laut","x":"亻 (Mensch) zeigt, dass es um das Verhalten gegenüber Menschen geht, 毎 liefert den Klang. Das Zeichen bedeutet „verachten, geringschätzen“.","s":2,"p":[["亻","Mensch","b"],["毎","jeder","l"]]},
"鋳":{"t":"laut","x":"Die alte Form 鑄 hatte 金 (Metall) als Sinnteil und 壽 als Klangteil. Es geht um „Metall gießen“. Heute ist 壽 zu 寿 verkürzt, und 鋳 selbst stammt aus einer Schreibschrift-Form.","s":2,"p":[["釒","Metall","b"],["寿","langes Leben","l"]],"a":"鑄","i":"b"},
"胆":{"t":"laut","x":"⺼ (Fleisch, Körperteil) gibt den Sinn, 旦 den Klang (旦 タン → 胆 タン). Die alte Form 膽 hatte den Klangteil 詹; 胆 ist eine Variante mit anderem Klangteil. Es bedeutet „Galle“ und „Mut“.","s":2,"p":[["⺼","Fleisch","b"],["旦","Morgen","l"]],"a":"膽","i":"s"},
"浪":{"t":"laut","x":"氵 (Wasser) ist der Sinnteil, 良 liefert den Klang. Das Zeichen bedeutet „Welle“.","s":2,"p":[["氵","Wasser","b"],["良","gut","l"]],"i":"s"},
"禍":{"t":"laut","x":"礻 (Altar, Opfer, Ritual) zeigt den Sinnbereich, 咼 liefert den Klang (カ). Gemeint ist das Unglück, das von höheren Mächten kommt: „Unheil, Katastrophe“.","s":2,"p":[["礻","Altar, Opfer","b"],["咼","(Klangteil)","l"]],"i":"s"},
"酪":{"t":"laut","x":"酉 (Krug, vergorenes Getränk) gibt den Sinn, 各 den Klang. Gemeint ist ein vergorenes Milchprodukt wie Sauermilch, daher „Milchprodukte“.","s":1,"p":[["酉","Gärgetränk","b"],["各","jeder","l"]],"i":"s"},
"憧":{"t":"laut","x":"忄 (Herz, Gefühl) zeigt: Es geht um eine Gemütsregung. 童 liefert den Klang. Das Zeichen bedeutet „sich sehnen, schwärmen“.","s":1,"p":[["忄","Herz","b"],["童","Kind","l"]],"i":"s"},
"慶":{"t":"kombi","x":"In den ältesten Formen steht ein hirschartiges Tier 廌 über dem Herz 心. Ein schönes, seltenes Tier gilt als Glückszeichen. So steht das Zeichen für „feiern, Glückwunsch“.","s":2,"p":[["廌","Fabeltier","b"],["心","Herz","b"]],"n":"Das alte Wörterbuch sah darin 鹿 (Hirsch) + 心 + 夊 (Fuß). Das ist falsch; der Teil unten ist der Schwanz des Tieres.","i":"bs"},
"亜":{"t":"leih","x":"Die alte Form 亞 zeigt vermutlich einen Grundriss, wohl eine Grabanlage in der Aufsicht. Später wurde sie für das gleich klingende Wort „zweiter, nachfolgend“ ausgeliehen. 亜 ist die Kurzform.","s":1,"a":"亞","i":"obs"},
"汰":{"t":"laut","x":"氵 (Wasser) ist der Sinnteil: im Wasser auswaschen und sieben. 太 liefert den Klang (太 タイ → 汰 タイ).","s":2,"p":[["氵","Wasser","b"],["太","dick","l"]]},
"梓":{"t":"laut","x":"木 (Baum) zeigt, dass es ein Baum ist: der Trompetenbaum (Catalpa). Der rechte Teil liefert den Klang; er ist eine Kurzform von 宰.","s":1,"p":[["木","Baum","b"],["辛","(Klangteil)","l"]]},
"沙":{"t":"kombi","x":"Wasser 氵 und kleine Pünktchen 少: Sand am Ufer. Schon auf den Orakelknochen zeigt das Zeichen Wasser mit Körnchen daneben.","s":2,"p":[["氵","Wasser","b"],["少","kleine Punkte","b"]],"i":"bs"},
"逝":{"t":"laut","x":"辶 (Weg, Bewegung) gibt den Sinn: weggehen. 折 liefert den Klang. Daraus wurde „entschwinden, sterben“.","s":2,"p":[["辶","gehen","b"],["折","brechen","l"]],"i":"s"},
"匿":{"t":"laut","x":"匸 (Versteck, verbergen) ist der Sinnteil, 若 liefert den Klang. Das Zeichen bedeutet „sich verstecken, verbergen“.","s":2,"p":[["匸","verbergen","b"],["若","jung","l"]],"i":"bs"},
"寡":{"t":"kombi","x":"Unter dem Dach 宀 steht nur ein Mensch (Kopf 頁): jemand ist allein im Haus. Daraus wurde „allein, Witwe“ und „wenig“.","s":0,"p":[["宀","Dach","b"],["頁","Kopf, Person","b"]],"n":"Das alte Wörterbuch sah 宀 + 頒 („verteilen“). Das ist falsch.","i":"bs"},
"痢":{"t":"laut","x":"疒 (Krankheit) gibt den Sinn, 利 den Klang (利 リ → 痢 リ). Das Zeichen steht für „Durchfall, Ruhr“.","s":2,"p":[["疒","Krankheit","b"],["利","Nutzen","l"]]},
"坑":{"t":"laut","x":"土 (Erde) ist der Sinnteil: ein Loch in der Erde. 亢 liefert den Klang (コウ). Das Zeichen bedeutet „Grube, Schacht“.","s":2,"p":[["土","Erde","b"],["亢","(Klangteil)","l"]],"i":"s"},
"藍":{"t":"laut","x":"艹 (Pflanze) zeigt den Sinn: Es ist eine Pflanze, die Indigo liefert. 監 liefert den Klang (ラン).","s":2,"p":[["艹","Pflanze","b"],["監","überwachen","l"]]},
"畔":{"t":"laut","x":"田 (Feld) ist der Sinnteil, 半 liefert den Klang (半 ハン → 畔 ハン). Gemeint ist der Damm zwischen Feldern, der Rain.","s":2,"p":[["田","Feld","b"],["半","halb","l"]],"i":"s"},
"唄":{"t":"laut","x":"口 (Mund) zeigt: Es geht ums Singen. 貝 liefert den Klang (貝 バイ → 唄 バイ). Das Zeichen kürzt ein Wort ab, das ein Sanskrit-Wort für „Hymne, Gesang“ lautlich wiedergibt.","s":1,"p":[["口","Mund","b"],["貝","Muschel","l"]]},
"拷":{"t":"laut","x":"扌 (Hand) zeigt, dass geschlagen wird, 考 liefert den Klang. Es ersetzte die ältere Schreibung mit 考 allein, die „verhören“ bedeutete. Daher „foltern, schlagen“.","s":2,"p":[["扌","Hand","b"],["考","bedenken","l"]]},
"渓":{"t":"laut","x":"Die alte Form 溪 hatte 氵 (Wasser) als Sinnteil und 奚 als Klangteil (ケイ). Es bedeutet „Bergbach, Tal“. In 渓 ist der Klangteil stark verkürzt.","s":2,"p":[["氵","Wasser","b"],["奚","(Klangteil)","l"]],"a":"溪"},
"廉":{"t":"leih","x":"Ursprünglich ein Zeichen für den Wetzstein: ein Stein (厂, in 广 enthalten) als Sinnteil und 兼 als Klangteil. Später wurde es für das gleich klingende Wort „billig, redlich“ ausgeliehen.","s":2,"p":[["广","Fels, Dach","b"],["兼","zugleich","l"]],"i":"s"},
"謹":{"t":"laut","x":"訁 (Sprache) zeigt: Es geht um Reden. 堇 liefert den Klang (キン). Das Zeichen bedeutet „vorsichtig, ehrerbietig“.","s":2,"p":[["訁","Sprache","b"],["堇","(Klangteil)","l"]],"i":"s"},
"湧":{"t":"laut","x":"氵 (Wasser) ist der Sinnteil: Wasser sprudelt hervor. 勇 liefert den Klang (勇 ユウ → 湧 ユウ).","s":2,"p":[["氵","Wasser","b"],["勇","mutig","l"]]},
"醜":{"t":"laut","x":"Das Zeichen bedeutet „hässlich, schlecht“. Es ist ein Lautzeichen: 酉 liefert den Klang, der Sinnteil ist ein anderes Bauteil, das sich zu 鬼 (Dämon) gewandelt hat.","s":1,"p":[["酉","Weinkrug","l"],["鬼","Dämon","f"]],"n":"Oft liest man „Wein + Dämon: Dämonen sind hässlich“. Das wird heute als falsch eingestuft."},
"升":{"t":"bild","x":"Das Zeichen bildet einen Schöpflöffel oder ein Messgefäß mit Griff ab, ein Hohlmaß. Der Zusatzstrich unterscheidet es von 斗.","s":2,"i":"obs"},
"殉":{"t":"laut","x":"歹 (Tod, Gebein) gibt den Sinn, 旬 den Klang (旬 ジュン → 殉 ジュン). Gemeint ist, einem Verstorbenen in den Tod zu folgen.","s":2,"p":[["歹","Tod","b"],["旬","zehn Tage","l"]]},
"煩":{"t":"kombi","x":"Feuer 火 und Kopf 頁: Etwas brennt im Kopf. Gemeint ist die Plage, die Sorge, „lästig“.","s":1,"p":[["火","Feuer","b"],["頁","Kopf","b"]],"n":"Eine andere Deutung sieht 焚 (ハン/フン, verbrennen) als Klangteil; dann wäre es ein Lautzeichen.","i":"s"},
"劾":{"t":"laut","x":"力 (Kraft) ist der Sinnteil, 亥 liefert den Klang (亥 ガイ → 劾 ガイ). Das Zeichen bedeutet „anklagen, zur Rechenschaft ziehen“.","s":2,"p":[["力","Kraft","b"],["亥","(Klangteil)","l"]]},
"桟":{"t":"laut","x":"Die alte Form 棧 hatte 木 (Holz) als Sinnteil und 戔 als Klangteil (サン). Es bezeichnet ein Holzgerüst, einen Steg. In 桟 ist der Klangteil zu einer Kurzform geworden.","s":2,"p":[["木","Holz","b"],["戔","(Klangteil)","l"]],"a":"棧","i":"s"},
"婿":{"t":"laut","x":"Die ältere Form 壻 hatte 士 (Mann) als Sinnteil und einen Klangteil, der später zu 胥 verwechselt wurde. In 婿 ist 士 durch 女 ersetzt. Gemeint ist der Schwiegersohn, Bräutigam.","s":2,"p":[["女","Frau","b"],["胥","(Klangteil)","l"]],"a":"壻"},
"慕":{"t":"laut","x":"㣺 (Herz) zeigt den Sinn: Es ist eine Herzensregung. 莫 liefert den Klang (ボ). Das Zeichen bedeutet „sich sehnen, verehren“.","s":2,"p":[["莫","(Klangteil)","l"],["㣺","Herz","b"]],"i":"bs"},
"罷":{"t":"leih","x":"Ein Netz 罒 über 能 (hier „Bär“): ein Bär im Netz. Das Zeichen stand ursprünglich für eine Bärenart (羆). Später wurde es für das gleich klingende Wort „aufhören, entlassen“ ausgeliehen.","s":1,"p":[["罒","Netz","b"],["能","Bär","b"]],"i":"s"},
"矯":{"t":"laut","x":"矢 (Pfeil) gibt den Sinn: einen Pfeilschaft gerade richten. 喬 liefert den Klang (キョウ). Daraus wurde „zurechtbiegen, korrigieren“.","s":2,"p":[["矢","Pfeil","b"],["喬","hoch","l"]],"i":"s"},
"某":{"t":"leih","x":"Das Zeichen wird für „jemand, ein gewisser“ gebraucht – das ist ausgeliehen, weil das Wort gleich oder ähnlich klang. Wie das Zeichen ursprünglich aufgebaut war, ist nicht gesichert.","s":0,"p":[["木","Baum","b"]],"n":"Oft liest man „etwas Süßes (甘) am Baum (木)“ und denkt an die Pflaume (梅). Das ist eine alte Deutung aus dem Shuowen und gilt als schwach begründet; eine andere Erklärung sieht 某 als verkürzte Form von 無.","i":"bs"},
"囚":{"t":"kombi","x":"Ein Mensch (人) in einer Umzäunung (囗): ein Eingesperrter, ein Gefangener. Das Zeichen steht für „einsperren“ und „Häftling“.","s":2,"p":[["囗","Umzäunung","b"],["人","Mensch","b"]],"n":"Nicht verwandt mit 因.","i":"s"},
"泌":{"t":"laut","x":"氵 (Wasser) zeigt den Sinnbereich: etwas Flüssiges sickert oder fließt heraus. 必 liefert den Klang: 必 ヒツ → 泌 ヒツ.","s":2,"p":[["氵","Wasser","b"],["必","unbedingt","l"]]},
"漸":{"t":"laut","x":"氵 (Wasser) gibt den Sinnbereich an, 斬 den Klang (ザン; die heutige Lesung ゼン klingt noch ähnlich). Die Bedeutung „allmählich“ ist daraus nicht ablesbar.","s":2,"p":[["氵","Wasser","b"],["斬","abhauen","l"]],"i":"s"},
"藻":{"t":"laut","x":"艹 (Pflanze) gibt den Sinnbereich: eine Wasserpflanze, Alge. Der Klangteil 澡 (mit 氵 Wasser und 喿) liefert den Laut: 澡 ソウ → 藻 ソウ.","s":2,"p":[["艹","Pflanze","b"],["澡","waschen","l"]],"i":"s"},
"妄":{"t":"laut","x":"Der Klang kommt von 亡 (ボウ; heute noch in 妄 ボウ/モウ hörbar), 女 (Frau) ist der Sinnteil. Wie 女 zur Bedeutung „Wahn, unbegründet“ passt, ist nicht geklärt.","s":2,"p":[["亡","verlieren","l"],["女","Frau","b"]],"i":"bs"},
"蛮":{"t":"laut","x":"Die alte Form 蠻 hat 虫 (Wurm, Getier) als Sinnteil und 䜌 als Klangteil. Das heutige 蛮 kürzt den oberen Teil zu 亦 ab, nach demselben Muster wie 変 aus 變.","s":2,"p":[["虫","Wurm","b"],["䜌","verknüpfen","l"]],"a":"蠻"},
"倹":{"t":"laut","x":"Die alte Form 儉 besteht aus 亻 (Mensch) als Sinnteil und 僉 als Klangteil. Im heutigen 倹 ist der Klangteil zu 㑒 verkürzt. Gemeint ist „sparsam sein“.","s":2,"p":[["亻","Mensch","b"],["㑒","alle","l"]],"a":"儉","i":"s"},
"渥":{"t":"laut","x":"氵 (Wasser) steht für den Sinnbereich „benetzen, durchfeuchten“, 屋 für den Klang: 屋 オク → 渥 アク.","s":2,"p":[["氵","Wasser","b"],["屋","Haus","l"]]},
"旭":{"t":"laut","x":"日 (Sonne) gibt den Sinnbereich an: die aufgehende Sonne. 九 liefert den Klang (ク/キュウ), der in 旭 キョク ähnlich nachklingt.","s":2,"p":[["九","neun","l"],["日","Sonne","b"]],"i":"s"},
"絢":{"t":"laut","x":"糸 (Faden, Seide) ist der Sinnteil: ein schön gemustertes Gewebe. 旬 liefert den Klang; die Lesung hat sich seither verschoben (旬 ジュン, 絢 ケン).","s":1,"p":[["糸","Faden","b"],["旬","zehn Tage","l"]],"i":"s"},
"鮎":{"t":"laut","x":"魚 (Fisch) ist der Sinnteil, 占 der Klangteil (センの Reihe: 占 セン, 鮎 デン/ネン). Im alten China meinte 鮎 einen Wels; in Japan ist es der Ayu (Süßwasserfisch).","s":2,"p":[["魚","Fisch","b"],["占","wahrsagen","l"]],"n":"In Japan erzählt man, 神功皇后 habe mit dem Fischen ein Orakel (占) befragt und einen Ayu gefangen. Das ist eine Überlieferung, keine Zeichenherkunft.","i":"s"},
"惟":{"t":"laut","x":"忄 (Herz) zeigt, dass es um Denken und Überlegen geht. 隹 (kleiner Vogel) liefert den Klang: 隹 スイ, 惟 イ.","s":1,"p":[["忄","Herz","b"],["隹","Vogel","l"]]},
"亥":{"t":"unklar","x":"Wie das Zeichen entstanden ist, weiß man nicht. Es wurde ausgeliehen für das zwölfte Tierkreiszeichen. Vorgeschlagen werden etwa Wurzeln einer Pflanze oder ein Tier.","s":0,"n":"Oft liest man „Wildschwein“, weil das Zeichen in der Tierreihe dem Schwein entspricht. Das stützt sich auf spätere Formen und gilt als falsche Herleitung.","i":"obs"},
"郁":{"t":"laut","x":"阝 (hier die Stadt-/Ortsform von 邑) ist der Sinnteil, 有 der Klangteil: 有 ユウ → 郁 イク (ähnlich).","s":2,"p":[["有","haben","l"],["阝","Stadt","b"]],"i":"s"},
"磯":{"t":"laut","x":"石 (Stein) gibt den Sinnbereich an: ein felsiges Ufer. 幾 liefert den Klang: 幾 キ → 磯 キ.","s":2,"p":[["石","Stein","b"],["幾","wie viele","l"]]},
"壱":{"t":"laut","x":"Das heutige 壱 ist eine Kurzform von 壹. Dieses Zeichen hat 吉 (キツ) als Klangteil, im Shuowen mit 壺 (Krug) als Sinnteil. Es wurde für die Zahl „eins“ ausgeliehen; bei 壱 ist 豆 zu 匕 verkürzt.","s":1,"p":[["壺","Krug","b"],["吉","Glück","l"]],"n":"Über den Aufbau ist man sich nicht ganz einig: Eine Ansicht sieht 壹 als Ableitung eines Teils von 㱅, zu dem 吉 als Klang kam.","a":"壹","i":"s"},
"允":{"t":"leih","x":"Das Zeichen zeigt wohl einen stehenden Menschen mit hinter dem Rücken verschränkten Händen. Was es ursprünglich bedeutete, ist unbekannt; später wurde es für „aufrichtig, erlauben“ ausgeliehen.","s":1,"i":"bs"},
"胤":{"t":"kombi","x":"Nach einer Deutung steht 肉 (Fleisch) für die Blutlinie, 幺 (Faden) für ihre Fortsetzung und 八 (teilen) für die Verzweigung. So entsteht „Nachkommenschaft“.","s":1,"p":[["八","teilen","b"],["幺","Faden","b"],["肉","Fleisch","b"]]},
"韻":{"t":"laut","x":"音 (Klang) ist der Sinnteil: Nachklang, Reim. 員 liefert den Laut: 員 イン → 韻 イン.","s":2,"p":[["音","Klang","b"],["員","Mitglied","l"]]},
"卯":{"t":"unklar","x":"Der Ursprung ist nicht geklärt. Auf Orakelknochen steht das Zeichen für ein Opfer, bei dem etwas in zwei Hälften geteilt wird. Später wurde es für das vierte Tierkreiszeichen ausgeliehen.","s":0,"i":"obs"},
"丑":{"t":"leih","x":"Ursprünglich eine Hand mit hervorgehobenen Fingernägeln oder Krallen; es stand für „Kralle, Nagel“. Später wurde es für das zweite Tierkreiszeichen ausgeliehen.","s":2,"i":"obs"},
"叡":{"t":"laut","x":"目 (Auge) ist der Sinnteil für scharfes Sehen und Einsicht, 㕡 dient als Klangteil (エイ).","s":1,"p":[["目","Auge","b"],["㕡","Rinne","l"]],"n":"Eine Quelle versteht das Zeichen als Sinnverbindung: Auge plus tiefe Rinne, also „tiefer Einblick“.","i":"bs"},
"謁":{"t":"laut","x":"言 (sprechen) ist der Sinnteil: vor einen Höheren treten und sprechen. 曷 liefert den Klang: 曷 カツ, 謁 エツ.","s":2,"p":[["言","Sprache","b"],["曷","wie","l"]],"n":"Früher deutete man das Zeichen zusätzlich als Sinnverbindung; das gilt als falsch.","i":"s"},
"艶":{"t":"laut","x":"Die alte Form 豔 hat 豐 (üppig) als Sinnteil und 盍 als Klangteil; gemeint ist Glanz, Pracht. Daneben entstand die Schreibung 艷 mit 色 (Farbe), aus der das heutige 艶 verkürzt ist.","s":1,"p":[["豊","reich","b"],["色","Farbe","b"]],"a":"艷"},
"苑":{"t":"laut","x":"艹 (Pflanze) gibt den Sinnbereich an: ein bewachsenes Gelände, Garten. 夗 liefert den Klang: 夗 エン → 苑 エン.","s":2,"p":[["艹","Pflanze","b"],["夗","sich krümmen","l"]]},
"於":{"t":"leih","x":"Das Zeichen ist eine verkürzte Form eines alten Zeichens für „Krähe“ (烏) und wurde für das Wort „in, an, bei“ ausgeliehen.","s":2,"n":"Es hat nichts mit 方 zu tun, obwohl es heute so aussieht.","i":"b"},
"旺":{"t":"laut","x":"日 (Sonne) ist der Sinnteil: strahlend, blühend. 王 liefert den Klang: 王 オウ → 旺 オウ.","s":2,"p":[["日","Sonne","b"],["王","König","l"]],"n":"Das Zeichen ging von 暀 (日 + 往) aus und wurde später als 日 + 王 verstanden."},
"翁":{"t":"laut","x":"Ursprünglich: Halsfedern eines Vogels. 羽 (Feder) ist der Sinnteil, 公 der Klangteil (コウ, später オウ). Dann wurde das Wort für „alter Mann“ ausgeliehen.","s":2,"p":[["公","öffentlich","l"],["羽","Feder","b"]],"i":"s"},
"伽":{"t":"laut","x":"亻 (Mensch) ist der Sinnteil, 加 liefert den Klang: 加 カ → 伽 カ.","s":2,"p":[["亻","Mensch","b"],["加","hinzufügen","l"]]},
"箇":{"t":"laut","x":"竹 (Bambus) ist der Sinnteil, ursprünglich ein einzelner Bambusstängel; daher das Zählwort. 固 liefert den Klang: 固 コ → 箇 コ.","s":2,"p":[["竹","Bambus","b"],["固","fest","l"]],"i":"s"},
"茄":{"t":"laut","x":"艹 (Pflanze) gibt den Sinnbereich an, 加 den Klang: 加 カ → 茄 カ.","s":2,"p":[["艹","Pflanze","b"],["加","hinzufügen","l"]],"i":"s"},
"霞":{"t":"laut","x":"雨 (Regen) zeigt den Sinnbereich Wetter und Dunst. 叚 liefert den Klang: 叚 カ → 霞 カ.","s":2,"p":[["雨","Regen","b"],["叚","leihen","l"]],"i":"s"},
"魁":{"t":"laut","x":"斗 (Schöpfkelle) ist der Sinnteil: ursprünglich ein Löffel. 鬼 liefert den Klang (キ, 魁 カイ). Später wurde das Zeichen für „Anführer“ ausgeliehen.","s":2,"p":[["鬼","Dämon","l"],["斗","Schöpfkelle","b"]],"i":"s"},
"凱":{"t":"laut","x":"Das Zeichen bedeutete Siegesmusik. 豈 liefert den Klang (ガイ/カイ), 几 wird je nach Deutung als zweiter Klangteil oder als Sinnteil gelesen.","s":1,"p":[["豈","wie denn","l"],["几","Tisch","b"]],"n":"Eine Deutung sieht in 豈 eine Trommel als Sinnteil und in 几 den Klang."},
"馨":{"t":"laut","x":"香 (Duft) ist der Sinnteil: wohlriechend, duften. 殸 liefert den Klang: 殸 ケイ → 馨 ケイ.","s":2,"p":[["香","Duft","b"],["殸","Klingstein","l"]],"n":"Früher las man 殸 auch als Bedeutungsteil; das gilt als unbegründet.","i":"s"},
"嚇":{"t":"laut","x":"口 (Mund) ist der Sinnteil: mit dem Mund drohen, einschüchtern. 赫 liefert den Klang: 赫 カク → 嚇 カク.","s":2,"p":[["口","Mund","b"],["赫","rot leuchten","l"]]},
"褐":{"t":"laut","x":"衤 (Kleidung) ist der Sinnteil: ein Gewand aus grobem Stoff, daher „braun, grob“. 曷 liefert den Klang: 曷 カツ → 褐 カツ.","s":2,"p":[["衤","Kleidung","b"],["曷","wie","l"]],"i":"s"},
"叶":{"t":"laut","x":"Das Zeichen ist eine alte Variante von 協 („zusammenwirken“). 口 (Mund) gilt als Sinnteil, 十 als Klangteil; im alten Chinesisch klangen beide ähnlich.","s":1,"p":[["口","Mund","b"],["十","zehn","l"]],"n":"Eine Deutung als Sinnverbindung gilt als falsch."},
"樺":{"t":"laut","x":"木 (Baum) ist der Sinnteil: die Birke. Der Klangteil ist 華 (altes Bauteil 𠌶): 華 カ → 樺 カ.","s":1,"p":[["木","Baum","b"],["華","Blüte","l"]]},
"茅":{"t":"laut","x":"艹 (Pflanze) zeigt, dass es ein Gras ist. 矛 liefert den Klang: 矛 ボウ → 茅 ボウ.","s":1,"p":[["艹","Pflanze","b"],["矛","Speer","l"]]},
"侃":{"t":"unklar","x":"Der Aufbau ist umstritten. Eine Deutung leitet das Zeichen aus 衍 ab: Dabei fiel 彳 weg und 口 kam hinzu. Das Wort bedeutete ursprünglich „fröhlich, vergnügt“.","s":0,"i":"bs"},
"棺":{"t":"laut","x":"木 (Holz) ist der Sinnteil: ein Sarg aus Holz. 官 liefert den Klang: 官 カン → 棺 カン.","s":2,"p":[["木","Baum","b"],["官","Beamter","l"]]},
"莞":{"t":"laut","x":"艹 (Pflanze) gibt den Sinnbereich an: eine Binsenart. 完 liefert den Klang: 完 カン → 莞 カン.","s":2,"p":[["艹","Pflanze","b"],["完","vollständig","l"]]},
"巌":{"t":"laut","x":"Die alte Form 巖 hat 山 (Berg) als Sinnteil und 嚴 als Klangteil: 嚴 ゲン → ガン. Im heutigen 巌 ist der Klangteil zur Kurzform 厳 verkürzt. Gemeint ist ein schroffer Fels.","s":2,"p":[["山","Berg","b"],["厳","streng","l"]],"a":"巖","i":"s"},
"嬉":{"t":"laut","x":"喜 (Freude) liefert den Klang (キ) und zugleich den Sinn; 女 (Frau) steht daneben als Sinnteil.","s":2,"p":[["女","Frau","b"],["喜","Freude","l"]],"n":"Der Teil 喜 trägt hier auch selbst die Bedeutung „Freude“."},
"毅":{"t":"laut","x":"Nach einer Quelle ist 豙 der Klangteil und 殳 (eine alte Waffe, Stab) der Sinnteil. Das Zeichen steht für „standhaft, stark“.","s":1,"p":[["豙","Klangteil","l"],["殳","Stab","b"]],"i":"s"},
"稀":{"t":"laut","x":"Ursprünglich stand 希 allein für „selten, spärlich“. Mit 禾 (Getreide) wurde 稀 daraus gemacht; 希 behielt den Klang: 希 キ → 稀 キ.","s":2,"p":[["禾","Getreide","b"],["希","hoffen","l"]]},
"誼":{"t":"laut","x":"言 (Sprache) ist der Sinnteil, 宜 liefert den Klang: 宜 ギ → 誼 ギ.","s":1,"p":[["言","Sprache","b"],["宜","passend","l"]]},
"鞠":{"t":"laut","x":"Das Zeichen bedeutete zuerst „Hefe, Koji“ und wurde später für den Lederball (Kemari) ausgeliehen. Der Klang kommt von 匊 (キク); das 革 darin ist ein Rest eines Handschellen-Bildes, nicht „Leder“.","s":1,"p":[["革","Leder","f"],["匊","Handvoll","l"]],"i":"s"},
"橘":{"t":"laut","x":"木 (Baum) ist der Sinnteil: ein Fruchtbaum, die Mandarine. 矞 liefert den Klang: 矞 イツ → 橘 キツ.","s":1,"p":[["木","Baum","b"],["矞","Klangteil","l"]],"i":"s"},
"亨":{"t":"leih","x":"Das Zeichen zeigt wohl ein Gebäude, vermutlich einen Ahnenschrein. Später wurde es für „reibungslos verlaufen“ ausgeliehen.","s":2,"n":"Ähnliche Zeichen wie 享 und 亯 haben dieselbe Herkunft.","i":"s"},
"匡":{"t":"laut","x":"Ursprünglich ein viereckiger Korb. 匚 (Kasten) ist der Sinnteil, der Klangteil war 㞷, von dem heute nur 王 übrig ist: 王 オウ, 匡 キョウ/オウ.","s":2,"p":[["匚","Kasten","b"],["王","König","l"]],"i":"s"},
"喬":{"t":"zeichen","x":"Das Zeichen wurde aus 高 (hoch) abgeleitet, indem ein Zusatzstrich zur Unterscheidung angefügt wurde. Es bedeutet auch „hoch“.","s":2,"p":[["高","hoch","b"]],"n":"Der Shuowen liest den oberen Teil als 夭 („biegen“) und sieht ein Lautzeichen. Das ist ein Irrtum, wie die Bronzeformen zeigen.","i":"s"},
"尭":{"t":"kombi","x":"Die alte Form 堯 zeigt aufgehäufte Erde (土) über einer knienden Person: „hoch aufragend“. Im heutigen 尭 ist der Erdenteil zu 卉 verkürzt.","s":1,"p":[["卉","(verkürzt)","f"],["兀","kniender Mensch","b"]],"a":"堯","i":"obs"},
"桐":{"t":"laut","x":"木 (Baum) ist der Sinnteil, 同 der Klangteil: 同 ドウ → 桐 ドウ.","s":2,"p":[["木","Baum","b"],["同","gleich","l"]]},
"斤":{"t":"bild","x":"Ein Bildzeichen: eine Axt mit Stiel und Klinge. Später wurde es auch zur Gewichtseinheit.","s":2,"i":"obs"},
"欣":{"t":"laut","x":"欠 (ein Mensch mit offenem Mund) ist der Sinnteil: Freude äußern. 斤 liefert den Klang: 斤 キン → 欣 キン.","s":2,"p":[["斤","Axt","l"],["欠","gähnen","b"]]},
"欽":{"t":"laut","x":"Das Zeichen zeigt einen gähnenden Menschen (欠) und meinte zuerst „gähnen“. 金 liefert den Klang: 金 キン → 欽 キン. „Verehren“ ist eine spätere, ausgeliehene Bedeutung.","s":2,"p":[["金","Gold","l"],["欠","gähnen","b"]]},
"芹":{"t":"laut","x":"艹 (Pflanze) gibt den Sinnbereich an, 斤 den Klang: 斤 キン → 芹 キン.","s":2,"p":[["艹","Pflanze","b"],["斤","Axt","l"]]},
"衿":{"t":"laut","x":"衤 (Kleidung) ist der Sinnteil: der Kragen. 今 liefert den Klang: 今 コン/キン → 衿 キン.","s":2,"p":[["衤","Kleidung","b"],["今","jetzt","l"]],"n":"Oft wird dasselbe Wort auch als 襟 geschrieben."},
"玖":{"t":"laut","x":"玉 (Edelstein) ist der Sinnteil: ein schwarzer Schmuckstein. 久 liefert den Klang: 久 キュウ → 玖 キュウ.","s":1,"p":[["玉","Edelstein","b"],["久","lange","l"]],"i":"s"},
"虞":{"t":"laut","x":"Ursprünglich ein tigerähnliches Fabeltier: 虍 (Tiger) als Sinnteil, 呉 als Klangteil. Später wurde das Zeichen für „Besorgnis, Furcht“ ausgeliehen.","s":2,"p":[["虍","Tiger","b"],["呉","Wu","l"]],"i":"b"},
"栗":{"t":"bild","x":"Ein Bildzeichen: ein Baum mit stacheligen Fruchtkapseln – die Kastanie.","s":2,"n":"Nicht verwandt mit 要 oder 票.","i":"os"},
"薫":{"t":"laut","x":"Die alte Form 薰 hat 艹 (Pflanze) als Sinnteil, 熏 als Klangteil: 熏 クン → 薰 クン. Gemeint ist ein Duftkraut. 薫 ist eine Variante davon.","s":2,"p":[["艹","Pflanze","b"],["熏","räuchern","l"]],"a":"薰","i":"s"},
"袈":{"t":"laut","x":"衣 (Kleidung) ist der Sinnteil, 加 der Klangteil: 加 カ → 袈 ケ/カ.","s":1,"p":[["加","hinzufügen","l"],["衣","Kleidung","b"]]},
"圭":{"t":"bild","x":"Ein Bildzeichen: Es zeigt eine Klinge und ein Stück Jade in Form dieser Klinge. 圭 bedeutet eine Jade-Zeremonialtafel.","s":2,"n":"Oft liest man „zweimal 土“. Das ist falsch: Auf Orakelknochen und Bronzen hat das Zeichen mit 土 nichts zu tun.","i":"obs"},
"慧":{"t":"laut","x":"心 (Herz) ist der Sinnteil: Geist, Verstand. 彗 liefert den Klang: 彗 スイ → 慧 ケイ/エ. Gemeint ist „klug, scharfsinnig“.","s":2,"p":[["彗","Besen","l"],["心","Herz","b"]],"i":"s"},
"桂":{"t":"laut","x":"木 (Baum) ist der Sinnteil, 圭 der Klangteil: 圭 ケイ → 桂 ケイ.","s":2,"p":[["木","Baum","b"],["圭","Jadetafel","l"]]},
"絃":{"t":"laut","x":"糸 (Faden) ist der Sinnteil, 玄 der Klangteil: 玄 ゲン → 絃 ゲン. Das Zeichen steht für Seil und Saite.","s":1,"p":[["糸","Faden","b"],["玄","dunkel","l"]],"n":"Nach einer Deutung ist 絃 teils eine verkürzte Form von 弦 („Bogensehne“); beide Wörter klangen ähnlich."},
"伍":{"t":"laut","x":"Links der Mensch 亻 als Sinnteil, rechts 五 als Klangteil (ゴ → 伍 ゴ). Gemeint ist eine kleine Gruppe von Leuten, ursprünglich eine Truppeneinheit („Fünfergruppe“).","s":2,"p":[["亻","Mensch","b"],["五","fünf","l"]],"n":"Früher wurde das Zeichen teils als Sinnverbindung gedeutet („fünf Menschen“). Das gilt heute als falsch: 五 liefert nur den Klang."},
"梧":{"t":"laut","x":"Ein Baumname: 木 (Baum) gibt den Sinnbereich an, 吾 den Klang (ゴ → 梧 ゴ). Gemeint ist der Blauglockenbaum / Paulownia-ähnliche Zierbaum.","s":1,"p":[["木","Baum","b"],["吾","ich","l"]]},
"瑚":{"t":"laut","x":"Links 玉 (Edelstein) als Sinnbereich, rechts 胡 als Klangteil (コ → 瑚 コ). Das Zeichen steht heute für Koralle.","s":1,"p":[["玉","Edelstein","b"],["胡","Barbar/Ausland","l"]]},
"侯":{"t":"leih","x":"Ursprünglich ein Bild: ein Pfeil, der eine Zielscheibe trifft („Pfeilziel“). Später kamen dekorative Striche dazu, daraus die heutige Form. Das Zeichen wurde dann für ein gleich klingendes Wort „Fürst, Adliger“ ausgeliehen.","s":2,"p":[["亻","Zierstrich","f"],["矢","Pfeil","b"]],"i":"obs"},
"倖":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 幸 als Klangteil (コウ → 倖 コウ). Das Zeichen steht für Glück, glücklichen Zufall.","s":1,"p":[["亻","Mensch","b"],["幸","Glück","l"]]},
"宏":{"t":"laut","x":"Oben das Dach 宀, das für Raum und Haus steht, darunter 厷 als Klangteil (コウ → 宏 コウ). Daraus entwickelte sich der Sinn „weit, geräumig“.","s":1,"p":[["宀","Dach","b"],["厷","(nur Klang)","l"]],"i":"s"},
"弘":{"t":"zeichen","x":"Ein Bogen 弓 mit einer Markierung am Bogenarm. Das Zeichen schrieb zuerst das Wort für den Arm des Bogens (verwandt mit 肱). Später wird es für „weit, groß“ benutzt.","s":0,"p":[["弓","Bogen","b"],["厶","Markierung","f"]],"n":"Oft liest man: 弓 + 口, also der Klang eines Bogens, wobei 口 später zu 厶 verdorben sei. Die japanische Forschungsdarstellung hält diese Analyse für falsch.","i":"s"},
"昂":{"t":"laut","x":"Oben 日 (Sonne) als Sinnteil, darunter 卬 als Klangteil, die beide fast gleich klangen. Gemeint ist „sich erheben, aufsteigen“.","s":2,"p":[["日","Sonne","b"],["卬","aufblickender Mensch","l"]],"i":"s"},
"晃":{"t":"laut","x":"Oben 日 (Sonne), darunter 光 (Licht). Die Forschung sieht 光 als Klangteil (コウ → 晃 コウ), zugleich passt es zum Sinn „hell, strahlend“.","s":1,"p":[["日","Sonne","b"],["光","Licht","l"]],"n":"Die traditionelle Einordnung nennt das Zeichen eine Sinnverbindung aus Sonne und Licht. Als Lautzeichen wird es heute eingeordnet.","i":"s"},
"浩":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 告 als Klangteil. Im Altchinesischen klangen beide ähnlich, heute eher nicht mehr (告 コク, 浩 コウ). Gemeint ist „weit, riesig wie Wasser“.","s":2,"p":[["氵","Wasser","b"],["告","verkünden","l"]],"i":"s"},
"紘":{"t":"laut","x":"Links 糸 (Faden, Schnur), rechts 厷 als Klangteil (コウ → 紘 コウ). Das Zeichen stand zuerst für die Kinnbänder einer Kappe; heute vor allem im Sinn von „groß, weit“.","s":2,"p":[["糸","Faden","b"],["厷","(nur Klang)","l"]],"i":"s"},
"鴻":{"t":"laut","x":"Ein Vogelname: 鳥 (Vogel) gibt den Sinnbereich an, 江 den Klang (コウ → 鴻 コウ). Gemeint ist ein großer Wildvogel, die Wildgans.","s":1,"p":[["江","Fluss","l"],["鳥","Vogel","b"]]},
"墾":{"t":"laut","x":"Unten 土 (Erde) als Sinnteil, oben 貇 als Klangteil (コン → 墾 コン). Gemeint ist, die Erde umzubrechen und Land urbar zu machen.","s":2,"p":[["土","Erde","b"],["貇","(nur Klang)","l"]]},
"嵯":{"t":"laut","x":"Unten 山 (Berg), oben 差 als Klangteil (サ → 嵯 サ). Das Zeichen beschreibt etwas Steiles, Zerklüftetes, wie Berge.","s":2,"p":[["山","Berg","b"],["差","Unterschied","l"]]},
"瑳":{"t":"laut","x":"Links 玉 (Edelstein), rechts 差 als Klangteil (サ → 瑳 サ). Das Zeichen steht für glänzend, poliert, schimmernd wie ein Stein.","s":1,"p":[["玉","Edelstein","b"],["差","Unterschied","l"]]},
"裟":{"t":"laut","x":"Unten 衣 (Kleidung) als Sinnteil, oben 沙 als Klangteil (サ, シャ). Das Zeichen kommt vor allem in 袈裟 vor, dem Gewand buddhistischer Mönche.","s":2,"p":[["衣","Kleid","b"],["沙","Sand","l"]]},
"采":{"t":"kombi","x":"Oben eine Hand 爫, unten ein Baum 木: Eine Hand pflückt etwas vom Baum. Das Zeichen stand zuerst für „pflücken, sammeln“ (heute 採). Später kam der Sinn „Aussehen, Würfel“ hinzu.","s":2,"p":[["爫","Hand","b"],["木","Baum","b"]],"i":"obs"},
"冴":{"t":"unklar","x":"Links steht 冫 (Eis, Kälte), rechts 牙. Für dieses Zeichen liegt keine gesicherte Herleitung seines Aufbaus vor.","s":0},
"朔":{"t":"laut","x":"Rechts 月 (Mond) als Sinnteil, links 屰 als Klangteil (ギャク → 朔 サク; im Altchinesischen klangen sie ähnlicher). Gemeint ist der Neumond, damit der Monatsbeginn.","s":2,"p":[["屰","verkehrt/entgegen","l"],["月","Mond","b"]],"i":"bs"},
"笹":{"t":"kombi","x":"Unter dem Bambus 竹 steht 世. Wahrscheinlich ist 世 ein Rest des Zeichens 葉 (Blatt): Bambusblatt, daher Bambusgras. Möglich ist auch ein Wortspiel mit den Bambusknoten.","s":1,"p":[["竹","Bambus","b"],["世","Welt/Generation","f"]],"n":"Ältere Wörterbücher erklären 世 als „über Generationen“ oder als Blattform. Das gilt als falsch."},
"皐":{"t":"unklar","x":"Das Zeichen gilt als verderbte Schreibform von 皋. Für den Aufbau gibt es hier keine eigene gesicherte Herleitung.","s":0},
"燦":{"t":"laut","x":"Links 火 (Feuer) als Sinnteil, rechts 粲 als Klangteil (サン → 燦 サン). Gemeint ist „hell leuchten, glänzen“.","s":2,"p":[["火","Feuer","b"],["粲","(nur Klang)","l"]],"i":"s"},
"蚕":{"t":"kurz","x":"Kurzform der alten Form 蠶 (Seidenraupe), die aus doppelten Teilen bestand. In 蚕 sind die doppelten Teile zu 天 und 虫 verschmolzen. Mit 虫 (Insekt) als Sinnteil.","s":1,"p":[["天","Himmel","f"],["虫","Insekt","b"]],"n":"Ein anderes, älteres Zeichen 蚕 (テン) bezeichnete einen Regenwurm: Insektenteil 虫 plus Klangteil 天.","a":"蠶","i":"s"},
"嗣":{"t":"laut","x":"Mund 口 und Urkunde 冊 stehen für das Einsetzen eines Nachfolgers durch Wort und Schrift; 司 liefert den Klang (シ → 嗣 シ). Daraus „Erbe sein, nachfolgen“.","s":2,"p":[["口","Mund","b"],["冊","Urkunde","b"],["司","verwalten","l"]]},
"肢":{"t":"laut","x":"Links 月 (hier Fleisch, Körper) als Sinnteil, rechts 支 als Klangteil (シ → 肢 シ). Gemeint sind die Gliedmaßen.","s":2,"p":[["月","Fleisch","b"],["支","Zweig/stützen","l"]],"i":"s"},
"賜":{"t":"laut","x":"Links 貝 (Muschel, früher Geld), rechts 易 als Klangteil. Zuerst schrieb 易 selbst das Wort „schenken“; 貝 kam später dazu und verdeutlicht den Sinn „Geschenk, Gabe“.","s":2,"p":[["貝","Muschel/Geld","b"],["易","(nur Klang)","l"]],"i":"bs"},
"爾":{"t":"leih","x":"Der ursprüngliche Aufbau ist nicht sicher. Als Deutung gilt ein Web- bzw. Fadengerät mit gekreuzten Fäden. Das Zeichen wurde früh für das Wort „du“ ausgeliehen.","s":1,"i":"obs"},
"蒔":{"t":"laut","x":"Oben 艹 (Pflanze, Gras) als Sinnteil, darunter 時 als Klangteil (ジ → 蒔 ジ, シ). Gemeint ist „Samen säen, pflanzen“.","s":2,"p":[["艹","Pflanze","b"],["時","Zeit","l"]]},
"汐":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 夕 als Klangteil (セキ → 汐 セキ). Das Zeichen steht für Gezeiten, Meerwasser.","s":1,"p":[["氵","Wasser","b"],["夕","Abend","l"]]},
"偲":{"t":"laut","x":"Links 亻 (Mensch), rechts 思 als Klangteil (シ → 偲 シ). Das Zeichen steht für ein Erinnern, an jemanden denken.","s":1,"p":[["亻","Mensch","b"],["思","denken","l"]]},
"紗":{"t":"laut","x":"Links 糸 (Faden, Seide) als Sinnteil, rechts 少 (verwandt mit 沙) als Klangteil (サ, シャ). Gemeint ist dünner, feiner Gaze-Stoff.","s":2,"p":[["糸","Faden","b"],["少","wenig","l"]],"n":"Eine Deutung als Sinnverbindung („feine Fäden“) gilt als falsch."},
"勺":{"t":"bild","x":"Das Zeichen zeigt eine Schöpfkelle, einen Schöpflöffel. Der Punkt 丶 steht für den Inhalt, der darin liegt, etwa Flüssigkeit.","s":1,"p":[["勹","Löffel","b"],["丶","Inhalt","f"]],"i":"bs"},
"爵":{"t":"bild","x":"Abbild eines antiken Trinkgefäßes für Wein in Form eines Vogels. In älteren Formen hält eine Hand (heute 寸) das Gefäß. Aus den Gefäßteilen wurden oben 爫 und 罒.","s":2,"p":[["爫","Gefäß oben","f"],["罒","Gefäß Mitte","f"],["寸","Hand","b"]],"i":"obs"},
"儒":{"t":"laut","x":"Links 亻 (Mensch) als Sinnteil, rechts 需 als Klangteil (ジュ → 儒 ジュ). Gemeint ist ein gelehrter Mensch, Gelehrter.","s":2,"p":[["亻","Mensch","b"],["需","brauchen","l"]],"i":"s"},
"愁":{"t":"laut","x":"Unten 心 (Herz) als Sinnteil, oben 秋 als Klangteil (シュウ → 愁 シュウ). Gemeint ist ein bekümmertes Herz, Kummer.","s":2,"p":[["心","Herz","b"],["秋","Herbst","l"]]},
"洲":{"t":"laut","x":"Links 氵 (Wasser), rechts 州 (Klangteil, シュウ → 洲 シュウ). 州 schrieb zuerst selbst das Wort „Sandbank, Insel“; das Wasser kam später dazu, um die vom Wasser umgebene Insel zu zeigen.","s":2,"p":[["氵","Wasser","b"],["州","Insel/Land","l"]]},
"峻":{"t":"laut","x":"Links 山 (Berg) als Sinnteil, rechts 夋 als Klangteil (シュン → 峻 シュン). Gemeint ist hoch und steil, wie ein Berg.","s":2,"p":[["山","Berg","b"],["夋","(nur Klang)","l"]]},
"竣":{"t":"laut","x":"Links 立 (stehen) als Sinnteil, rechts 夋 als Klangteil (シュン → 竣 シュン). Das Zeichen steht für „beenden, fertigstellen“.","s":1,"p":[["立","stehen","b"],["夋","(nur Klang)","l"]]},
"舜":{"t":"unklar","x":"Das Zeichen ist aus einer älteren Siegelschriftform abgewandelt. Eine gesicherte Herleitung des Aufbaus gibt es nicht.","s":0},
"淳":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 享 (alt als 𦎧) als Klangteil. Gemeint ist „rein, lauter“, wie klares Wasser. Heute klingt 淳 (ジュン) nicht mehr so ähnlich wie der Klangteil (キョウ).","s":1,"p":[["氵","Wasser","b"],["享","genießen","l"]]},
"遵":{"t":"laut","x":"Links unten 辶 (gehen, Weg) als Sinnteil, 尊 als Klangteil. 尊 bedeutet zugleich Ehrerbietung, was zu „befolgen, sich richten nach“ passt.","s":2,"p":[["辶","gehen","b"],["尊","ehren","l"]]},
"渚":{"t":"laut","x":"Links 氵 (Wasser) als Sinnteil, rechts 者 als Klangteil (シャ → 渚 ショ). Gemeint ist das Ufer, ursprünglich ein kleines Eiland im Wasser.","s":2,"p":[["氵","Wasser","b"],["者","Person/Sache","l"]]},
"恕":{"t":"laut","x":"Unten 心 (Herz) als Sinnteil, oben 如 als Klangteil (ジョ → 恕 ジョ). Gemeint ist ein nachsichtiges Herz: verzeihen, Nachsicht.","s":2,"p":[["心","Herz","b"],["如","wie","l"]]},
"宵":{"t":"laut","x":"Oben 宀 (Dach) als Sinnteil, darunter 肖 als Klangteil (ショウ → 宵 ショウ). Gemeint ist die Nacht, der frühe Abend.","s":2,"p":[["宀","Dach","b"],["肖","ähneln","l"]],"i":"bs"},
"抄":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 少 als Klangteil (ショウ → 抄 ショウ). Das Zeichen steht für „herausnehmen, auszugsweise abschreiben“.","s":2,"p":[["扌","Hand","b"],["少","wenig","l"]]},
"捷":{"t":"laut","x":"Links 扌 (Hand) als Sinnteil, rechts 疌 als Klangteil. Das Zeichen steht für „schnell, flink“ und „Sieg“.","s":1,"p":[["扌","Hand","b"],["疌","(nur Klang)","l"]],"i":"s"},
"梢":{"t":"laut","x":"Links 木 (Baum) als Sinnteil, rechts 肖 als Klangteil (ショウ → 梢 ショウ). Gemeint ist das Ende eines Zweigs, die Baumspitze.","s":2,"p":[["木","Baum","b"],["肖","ähneln","l"]],"i":"s"},
"硝":{"t":"laut","x":"Links 石 (Stein, Mineral) als Sinnteil, rechts 肖 als Klangteil (ショウ → 硝 ショウ). Das Zeichen steht für Salpeter.","s":2,"p":[["石","Stein","b"],["肖","ähneln","l"]]},
"菖":{"t":"laut","x":"Oben 艹 (Pflanze) als Sinnteil, darunter 昌 als Klangteil (ショウ → 菖 ショウ). Gemeint ist eine Pflanze, die Iris.","s":1,"p":[["艹","Pflanze","b"],["昌","blühen","l"]]},
"蕉":{"t":"laut","x":"Oben 艹 (Pflanze) als Sinnteil, darunter 焦 als Klangteil (ショウ → 蕉 ショウ). Das Zeichen steht für die Banane (Bananenstaude).","s":2,"p":[["艹","Pflanze","b"],["焦","anbrennen","l"]],"i":"s"},
"詔":{"t":"laut","x":"Links 訁 (Wort, sprechen) als Sinnteil, rechts 召 als Klangteil (ショウ → 詔 ショウ). Gemeint ist ein Befehl, ein kaiserlicher Erlass.","s":2,"p":[["訁","Wort","b"],["召","rufen","l"]]},
"丞":{"t":"kombi","x":"In der alten Form: ein knieender Mensch, zwei Hände und eine Grube. Man zieht jemanden aus der Grube heraus, daher „helfen, retten“. Vergleiche 承.","s":1,"p":[["卩","knieender Mensch","b"],["廾","zwei Hände","b"],["凵","Grube","b"]],"i":"os"},
"穣":{"t":"laut","x":"Links 禾 (Getreide) als Sinnteil, rechts ein Klangteil (ジョウ → 穣 ジョウ). In der alten Form 穰 stand dort 襄; im heutigen 穣 ist er zu 㐮 verkürzt. Gemeint ist reiche Ernte.","s":1,"p":[["禾","Getreide","b"],["㐮","(nur Klang)","l"]],"a":"穰","i":"s"},
"晋":{"t":"unklar","x":"Die alte Form 晉 besteht aus zwei Pfeilen 矢 über 日 (Sonne). Eine gesicherte Herleitung gibt es nicht. Das heutige 晋 ist die Kurzform davon.","s":0,"p":[["日","Sonne","b"]],"n":"Oft liest man „zwei Pfeile treffen die Sonne“ oder die Deutung über 臸 („ankommen“). Beides gilt heute als nicht haltbar.","a":"晉","i":"ob"},
"榛":{"t":"laut","x":"Links 木 (Baum) als Sinnteil, rechts 秦 als Klangteil (シン → 榛 シン). Das Zeichen steht für die Haselnuss, den Haselstrauch.","s":2,"p":[["木","Baum","b"],["秦","Qin","l"]]},
"秦":{"t":"kombi","x":"In der Orakelknochenschrift: ein Stößel, zwei Hände und zwei Getreidepflanzen. Es ging wohl um Getreide oder Landwirtschaft, Genaueres ist unklar. Das Zeichen wurde früh nur noch als Name verwendet (Qin).","s":1,"p":[["廾","zwei Hände","b"],["午","Stößel","b"],["禾","Getreide","b"]],"i":"obs"},
"薪":{"t":"laut","x":"Oben 艹 (Pflanze, Gras), darunter 新 (Klangteil, シン → 薪 シン). 新 schrieb zuerst selbst das Wort „Brennholz“; 艹 kam später dazu. Daher Brennholz, Reisig.","s":2,"p":[["艹","Pflanze","b"],["新","neu","l"]],"i":"s"},
"翠":{"t":"laut","x":"Links 羽 (Feder) als Sinnteil, 卒 als Klangteil. Im Altchinesischen klangen sie ähnlich, heute eher nicht (卒 ソツ, 翠 スイ). Gemeint ist der Eisvogel, danach die Farbe grün.","s":2,"p":[["羽","Feder","b"],["卒","Soldat","l"]],"i":"bs"},
"錘":{"t":"laut","x":"Links 釒 (Metall) als Sinnteil, rechts 垂 als Klangteil (スイ → 錘 スイ). Gemeint ist ein Gewicht aus Metall: Senkblei, Gewicht.","s":2,"p":[["釒","Metall","b"],["垂","hängen","l"]],"i":"s"},
"嵩":{"t":"kombi","x":"Oben 山 (Berg), darunter 高 (hoch): ein hoher, aufragender Berg. Die Teile geben gemeinsam den Sinn „hoch, aufragend“.","s":1,"p":[["山","Berg","b"],["高","hoch","b"]],"i":"s"},
"雛":{"t":"laut","x":"Rechts 隹 (Vogel) als Sinnteil, links 芻 als Klangteil (スウ → 雛 スウ). Das Zeichen steht für ein Küken, ein junges Vögelchen.","s":2,"p":[["隹","Vogel","b"],["芻","(nur Klang)","l"]],"i":"os"},
"畝":{"t":"laut","x":"Ursprünglich 畮: 田 (Feld) als Sinnteil, 每 als Klangteil. Später wurde der Klangteil durch 又 ersetzt, heute als 久; oben kam 十 dazu, das zu 亠 verschliffen wurde. Gemeint ist die Ackerfurche, Beet.","s":2,"p":[["田","Feld","b"],["久","lange","l"]],"i":"s"},
"斥":{"t":"unklar","x":"Zwei ältere Zeichen sind in 斥 zusammengefallen. Für セキ wird 厇 genannt (厂 + 乇, beides Klangteile); eine andere Herleitung nennt 㡿 (广 + 屰). Der Ursprung ist nicht eindeutig.","s":0,"i":"bs"},
"碩":{"t":"laut","x":"Rechts 頁 (Kopf) als Sinnteil, links 石 als Klangteil (セキ → 碩 セキ). Ursprünglich „großer Kopf“, daraus „groß, mächtig“.","s":2,"p":[["頁","Kopf","b"],["石","Stein","l"]],"i":"s"},
"銑":{"t":"laut","x":"Links 釒 (Metall) als Sinnteil, rechts 先 als Klangteil (セン → 銑 セン). Das Zeichen steht für Roheisen.","s":2,"p":[["釒","Metall","b"],["先","voran","l"]]},
"繕":{"t":"laut","x":"Links 糸 (Faden) als Sinnteil, rechts 善 als Klangteil (ゼン → 繕 ゼン). Der Klangteil passt auch zum Sinn: etwas wieder „gut machen“, ausbessern.","s":2,"p":[["糸","Faden","b"],["善","gut","l"]],"i":"s"},
"塑":{"t":"laut","x":"Unten 土 (Erde, Lehm) als Sinnteil, oben 朔 als Klangteil (サク → 塑 ソ). Gemeint ist das Formen aus weichem Material, Modellieren.","s":2,"p":[["土","Erde","b"],["朔","Neumond","l"]]},
"惣":{"t":"unklar","x":"Das Zeichen gilt als Schreibfehler für 揔. Eine eigene gesicherte Herleitung aus 物 und 心 gibt es nicht.","s":1},
"綜":{"t":"laut","x":"Links 糸 (Faden) als Sinnteil, rechts 宗 als Klangteil (ソウ → 綜 ソウ). Gemeint ist „zusammenfassen, ordnen“.","s":2,"p":[["糸","Faden","b"],["宗","Ahnen/Linie","l"]]},
"黛":{"t":"laut","x":"Unten 黑 (schwarz) als Sinnteil, oben 代 als Klangteil (ダイ → 黛 タイ). Gemeint ist schwarze Farbe für die Augenbrauen.","s":2,"p":[["代","ersetzen","l"],["黑","schwarz","b"]]},
"鯛":{"t":"laut","x":"Links 魚 (Fisch) zeigt den Sinnbereich: ein Fisch, die Meerbrasse. Rechts 周 liefert den Klang; die Lesung チョウ ist hier noch gut zu erkennen.","s":1,"p":[["魚","Fisch","b"],["周","ringsum","l"]]},
"鷹":{"t":"laut","x":"Unten 鳥 (Vogel) gibt den Sinnbereich an: ein Greifvogel, der Habicht. Der obere Teil 䧹 ist der Klangteil und steht für die alte Aussprache.","s":2,"p":[["鳥","Vogel","b"],["䧹","Lautteil","l"]]},
"啄":{"t":"laut","x":"口 (Mund) steht für das Picken und Beißen, 豖 liefert den Klang: 豖 → 啄 タク. Das Zeichen schreibt das Wort für „picken“ und „nagen“.","s":2,"p":[["口","Mund","b"],["豖","Lautteil","l"]],"i":"s"},
"琢":{"t":"laut","x":"Links steht 玉 (Jade, hier in der Kurzform 王): Edelstein wird bearbeitet. Rechts 豖 liefert den Klang: 豖 → 琢 タク. Gemeint ist „schleifen, polieren“.","s":2,"p":[["玉","Jade","b"],["豖","Lautteil","l"]]},
"只":{"t":"leih","x":"Das Zeichen entstand als Kurzform von 枳; sein 口 hat mit „Mund“ nichts zu tun. Es wurde dann für das Wort „nur, bloß“ ausgeliehen und dafür benutzt.","s":1,"p":[["口","Mund","f"],["八","acht","f"]],"n":"Oft liest man „Atem, der aus dem Mund strömt“ (口 plus abziehende Striche). Die japanische Fachquelle sieht 口 dagegen als bedeutungslos.","i":"s"},
"但":{"t":"laut","x":"亻 (Mensch) steht für den Sinnbereich, 旦 für den Klang: 旦 タン → 但 タン. In alten Bronzeinschriften ist das Zeichen ein Personenname. Später wurde es für „nur, aber“ ausgeliehen.","s":2,"p":[["亻","Mensch","b"],["旦","Morgenröte","l"]]},
"辰":{"t":"leih","x":"Ursprünglich ein Bild eines Ackergeräts, mit dem man den Boden lockerte und Unkraut entfernte; es wurde wohl aus einer großen Muschel gefertigt. Später wurde das Zeichen für das fünfte Tierkreiszeichen ausgeliehen.","s":1,"n":"Eine zweite Deutung sieht darin einen Menschen, der sich an eine Felswand klammert, den Vorläufer von 振.","i":"obs"},
"巽":{"t":"leih","x":"Die ältere Form 巺 zeigt zwei kniende Menschen an einem Tisch: Speise wird angerichtet. In diesem Sinn wurde das Zeichen später für das Wort „gehorsam, bescheiden“ ausgeliehen. Heute steht es auch für Südost.","s":0,"p":[["共","gemeinsam","f"],["巳","Form","f"]],"n":"Eine andere Deutung sieht es als Lautzeichen: 丌 (Tisch) plus der Lautteil 𠨎. Die Forschung ist uneins.","i":"s"},
"檀":{"t":"laut","x":"木 (Baum) gibt den Sinnbereich an, 亶 den Klang: 亶 ダン → 檀 ダン. Das Zeichen bezeichnet eine Baumart (Sandelholz, Spindelbaum).","s":2,"p":[["木","Baum","b"],["亶","Lautteil","l"]],"i":"s"},
"逐":{"t":"kombi","x":"Ein Tier (豕, Schwein) und ein Fuß, der hinterherläuft: jemand jagt ein Tier. Später wurde der Fuß durch 辶 (Gehen) ersetzt. Daraus wurde „verfolgen, nachjagen“.","s":2,"p":[["辶","Gehen","b"],["豕","Schwein","b"]],"i":"obs"},
"嫡":{"t":"laut","x":"女 (Frau) gibt den Sinnbereich an, 啇 den Klang (啇 テキ → 嫡 テキ). Gemeint ist die rechtmäßige Hauptlinie der Familie, die „direkte Abstammung“.","s":2,"p":[["女","Frau","b"],["啇","Lautteil","l"]]},
"衷":{"t":"laut","x":"衣 (Kleidung) wird um 中 (Mitte) ergänzt: Das Zeichen meint das Innere eines Kleidungsstücks. 中 liefert den Klang (チュウ). Von dort kam man zu „das Innerste, das Herz“.","s":2,"p":[["衣","Kleidung","b"],["中","Mitte","l"]],"n":"Oft liest man, 中 trage auch Bedeutung bei. Die japanische Fachquelle hält das für nicht belegt: 中 gibt nur den Klang.","i":"s"},
"猪":{"t":"laut","x":"犭 (Tier, aus 犬) zeigt den Sinnbereich: ein Tier. 者 liefert den Klang. Das Zeichen schreibt das Wort für „Wildschwein“.","s":2,"p":[["犭","Tier (Hund)","b"],["者","Lautteil","l"]]},
"暢":{"t":"laut","x":"Links steht ein Teil von 伸 („sich strecken“) als Sinnbereich, rechts 昜 für den Klang. Das Zeichen schreibt das Wort „sich ausdehnen, sich entfalten“.","s":1,"p":[["申","strecken (von 伸)","b"],["昜","Lautteil","l"]]},
"脹":{"t":"laut","x":"⺼ (Fleisch, Körper) gibt den Sinnbereich an: der Körper schwillt. 長 liefert den Klang (チョウ). Daraus wurde „anschwellen, sich aufblähen“.","s":2,"p":[["⺼","Fleisch","b"],["長","lang","l"]],"n":"Früher las man 長 auch als Bedeutungsträger („wachsen“). Die japanische Fachquelle hält das für eine falsche Analyse."},
"勅":{"t":"unklar","x":"Das Zeichen ist eine verbreitete Variante von 敕, das „ermahnen, in Ordnung bringen“ bedeutet. Rechts war ursprünglich 攴 (Hand mit Stock, Zeichen der Autorität); daraus wurde 力. Daher kommt der Sinn „kaiserlicher Befehl“.","s":0,"p":[["束","Bündel","l"],["力","Kraft","f"]],"n":"Die linke Hälfte wird verschieden gedeutet: als Lautteil 束 oder 柬, oder als Teil eines Zeichens für „warnen“. Sicher ist die Aufbauform nicht.","a":"敕","i":"bs"},
"朕":{"t":"leih","x":"Die alte Form 𦩎 zeigt ein Boot (舟) und zwei Hände mit einer Stange: jemand staakt ein Boot voran. Später wurde das Zeichen für das ehrfurchtsvolle „ich“ ausgeliehen, das nur Herrscher verwenden.","s":1,"p":[["月","Fleisch/Mond (aus 舟)","f"],["关","Hände mit Stange","b"]],"n":"Heute sieht das Boot wie 月 aus; die Hände wurden zu 关.","i":"obs"},
"槻":{"t":"laut","x":"木 (Baum) zeigt, dass es um einen Baum geht (die Zelkove). 規 liefert den Klang: 規 キ → 槻 キ.","s":1,"p":[["木","Baum","b"],["規","Maß","l"]]},
"蔦":{"t":"unklar","x":"Oben steht 艹 (Pflanze), unten 鳥 (Vogel). Das Zeichen bezeichnet Efeu und Kletterpflanzen. Wie die beiden Teile zusammenhängen, ist aus den Quellen nicht gesichert.","s":0,"p":[["艹","Pflanze","b"],["鳥","Vogel","b"]]},
"椿":{"t":"unklar","x":"Links 木 (Baum), rechts 春 (Frühling). Das Zeichen bezeichnet die Kamelie. Wie 春 hier wirkt, ob als Klang oder Sinn, ist aus den Quellen nicht gesichert.","s":0,"p":[["木","Baum","b"],["春","Frühling","f"]]},
"紬":{"t":"laut","x":"糸 (Seide, Faden) gibt den Sinnbereich an: ein Gewebe aus Seide. 由 liefert den Klang. Gemeint ist ein Stoff aus gröberer Seide mit Knötchen.","s":2,"p":[["糸","Seide","b"],["由","Ursprung","l"]]},
"悌":{"t":"laut","x":"忄 (Herz) zeigt, dass es um eine Haltung geht. 弟 liefert den Klang (テイ) und steht für den jüngeren Bruder. Das Zeichen meint den Respekt gegenüber Älteren.","s":2,"p":[["忄","Herz","b"],["弟","jüngerer Bruder","l"]],"n":"In alten Klassikern wird dafür oft einfach 弟 geschrieben."},
"禎":{"t":"laut","x":"礻 (Altar, Gottheit) steht für Segen und Glück. 貞 liefert den Klang: 貞 テイ → 禎 テイ. Daraus wurde „Glück, gutes Vorzeichen“.","s":1,"p":[["礻","Altar/Gott","b"],["貞","Standhaftigkeit","l"]],"i":"s"},
"逓":{"t":"laut","x":"In der alten Form 遞 gibt 辶 (Gehen) den Sinnbereich an, 虒 den Klang. Das Zeichen steht für „abwechseln, weitergeben“. Heute ist 虒 zu 乕 verkürzt.","s":2,"p":[["辶","Gehen","b"],["虒","Lautteil","l"]],"a":"遞"},
"杜":{"t":"laut","x":"木 (Baum) gibt den Sinnbereich an, 土 den Klang: 土 ト → 杜 ト. Ursprünglich eine bestimmte Baumart. Heute steht das Zeichen auch für „Wäldchen“.","s":2,"p":[["木","Baum","b"],["土","Erde","l"]],"i":"bs"},
"痘":{"t":"laut","x":"疒 (Krankheit) zeigt den Sinnbereich: eine Hautkrankheit, die Pocken. 豆 liefert den Klang: 豆 トウ → 痘 トウ.","s":2,"p":[["疒","Krankheit","b"],["豆","Bohne","l"]],"n":"Oft liest man, 豆 zeige auch die bohnenförmigen Pusteln. Das ist nicht sicher: nach der Fachquelle gibt 豆 nur den Klang."},
"謄":{"t":"laut","x":"言 (Wort, Rede) gibt den Sinnbereich an: etwas Geschriebenes wird übertragen. 朕 liefert den Klang. Das Zeichen schreibt das Wort für „abschreiben, kopieren“.","s":2,"p":[["言","Wort","b"],["朕","Lautteil","l"]],"n":"Die Aussprache von 朕 (チン) weicht heute von トウ ab; sie wandelte sich seit alter Zeit."},
"寅":{"t":"leih","x":"Ursprünglich ein Pfeil (矢) mit einer Markierung zur Unterscheidung. Dieses Zeichen wurde dann für das dritte Tierkreiszeichen (Tiger) ausgeliehen. Die Pfeilspitze wurde zu 宀.","s":2,"p":[["宀","Dach (aus Pfeilspitze)","f"],["矢","Pfeil","b"]],"n":"Oft liest man „Pfeil plus zwei Hände“. Nach heutiger Forschung stimmt das nicht; die Orakelknochenform enthält keine Hände.","i":"obs"},
"酉":{"t":"leih","x":"Ein Bild eines Weinkrugs mit spitzem Boden: das ursprüngliche Zeichen für „Alkohol, Wein“. Später wurde es für das zehnte Tierkreiszeichen (Hahn) ausgeliehen.","s":2,"n":"Es sieht fast wie 西 aus, hat aber mit „Westen“ nichts zu tun.","i":"obs"},
"惇":{"t":"laut","x":"忄 (Herz) zeigt, dass es um eine Haltung geht: aufrichtig, warmherzig. 享 liefert vermutlich den Klang. Quellen zu diesem Zeichen sind knapp.","s":1,"p":[["忄","Herz","b"],["享","genießen","l"]]},
"敦":{"t":"laut","x":"Die ältere Form 𦎫 zeigt einen Opferschrein und ein Schaf: ein gekochtes Opfertier. Später kam 攴 (Hand mit Stock) dazu, so entstand das heutige Zeichen mit dem Lautteil 𦎫.","s":1,"p":[["享","Opfer kochen","l"],["攵","Hand mit Stock","b"]],"n":"Später wurde das Zeichen für „drängen, zwingen“ benutzt; 燉 gehört zur alten Bedeutung „kochen“.","i":"bs"},
"凪":{"t":"kombi","x":"In Japan geschaffenes Zeichen: der Außenteil von 風 (Wind) plus 止 (anhalten). Wenn der Wind aufhört, herrscht Flaute, das Meer ist glatt.","s":2,"p":[["几","Außenteil von 風 (Wind)","b"],["止","stehen bleiben","b"]]},
"捺":{"t":"laut","x":"扌 (Hand) zeigt das Tun: mit der Hand drücken, stempeln. 奈 liefert den Klang (ナ, in der Lesung ナツ ähnlich).","s":1,"p":[["扌","Hand","b"],["奈","Lautteil","l"]]},
"楠":{"t":"laut","x":"木 (Baum) gibt den Sinnbereich an, 南 den Klang: 南 ナン → 楠 ナン. Das Zeichen bezeichnet den Kampferbaum und ist aus der Variante 枏 entstanden.","s":1,"p":[["木","Baum","b"],["南","Süden","l"]]},
"弐":{"t":"laut","x":"Die alte Form 貳 hat 貝 (Muschel, Geld) als Sinnteil und 弍 (zwei) als Klangteil; sie wurde für „zwei“ ausgeliehen. Heute ist 貝 zu 一 verkürzt.","s":1,"p":[["貝","Muschel/Geld","b"],["弍","zwei","l"]],"n":"Die ursprüngliche Bedeutung von 貳 ist unklar.","a":"貳","i":"bs"},
"巴":{"t":"bild","x":"Ursprünglich das Bild eines Menschen, der etwas in der Hand hält. Das Zeichen stand für „greifen, halten“. Später wurde der Handteil als eigener Teil missverstanden.","s":1,"n":"Oft wird 巴 als Schlange erklärt. Das ist nicht gesichert.","i":"os"},
"萩":{"t":"laut","x":"艹 (Pflanze) zeigt, dass es um eine Pflanze geht. 秋 (Herbst) liefert den Klang: 秋 シュウ → 萩 シュウ. Das Zeichen steht für den Buschklee.","s":1,"p":[["艹","Pflanze","b"],["秋","Herbst","l"]]},
"肇":{"t":"laut","x":"Die frühe Form zeigt, wie man gegen eine Tür schlägt. Später kam 聿 dazu. Das Zeichen schrieb das Wort „schlagen“ und wurde dann für „beginnen“ ausgeliehen.","s":1,"p":[["𢼄","Lautteil (Tür schlagen)","l"],["聿","Hand mit Pinsel","b"]]},
"頒":{"t":"laut","x":"頁 (Kopf) ist hier ein Zeichen für Gesicht und Person. 分 (teilen) liefert den Klang; es trägt wohl auch den Sinn „verteilen“. Das Zeichen bedeutet „austeilen, verbreiten“.","s":1,"p":[["分","teilen","l"],["頁","Kopf","b"]],"i":"s"},
"眉":{"t":"bild","x":"Ein Auge (目) mit Haaren darüber: die Augenbraue. Die Haare haben sich im Lauf der Zeit zu einem Strich über dem Auge verändert.","s":2,"p":[["𠃜","Haare","b"],["目","Auge","b"]],"i":"obs"},
"柊":{"t":"laut","x":"木 (Baum) gibt den Sinnbereich an, 冬 (Winter) den Klang. Das Zeichen schreibt den Namen des Baums „Stechpalme“.","s":1,"p":[["木","Baum","b"],["冬","Winter","l"]]},
"彦":{"t":"laut","x":"Die alte Form 彥 gehört zu einem Wort für „begabter Mann“. Ursprünglich 文 (Zierde) plus ein Lautteil 言; später wurde 言 durch 彡 (Muster) ersetzt. Heute ist die Form verkürzt.","s":1,"p":[["产","verkürzter Teil","f"],["彡","Muster","b"]],"a":"彥","i":"s"},
"彪":{"t":"kombi","x":"虎 (Tiger) und 彡 (Muster, Striche): die Streifen und Flecken des Tigers. Daraus wurde „gestreift, gefleckt, prächtig“.","s":1,"p":[["虎","Tiger","b"],["彡","Muster","b"]],"i":"s"},
"彬":{"t":"laut","x":"彡 (Muster, Zierde) steht für Schönheit. 林 ist wohl die verkürzte Form eines Lautteils (焚 oder 棼). Das Zeichen meint „fein, gebildet“.","s":0,"p":[["林","Wald","l"],["彡","Muster","b"]],"i":"s"},
"芙":{"t":"laut","x":"艹 (Pflanze) zeigt den Sinnbereich, 夫 liefert den Klang: 夫 フ → 芙 フ. Das Zeichen bezeichnet die Lotosblume.","s":2,"p":[["艹","Pflanze","b"],["夫","Mann","l"]]},
"賦":{"t":"laut","x":"貝 (Muschel, Geld) zeigt den Sinnbereich: Abgaben. 武 liefert den Klang. Das Zeichen bedeutet „Steuer erheben“ und später „Gedicht, Aufsatz“.","s":2,"p":[["貝","Muschel/Geld","b"],["武","Krieg","l"]],"n":"Oft liest man, 武 trage auch Bedeutung bei. Nach der Fachquelle ist das nicht belegt.","i":"bs"},
"附":{"t":"laut","x":"阝 (Hügel, aus 阜) gibt den Sinnbereich an, 付 den Klang: 付 フ → 附 フ. Daraus wurde „anhängen, hinzufügen“.","s":2,"p":[["阝","Hügel","b"],["付","anfügen","l"]]},
"蕗":{"t":"laut","x":"艹 (Pflanze) zeigt den Sinnbereich. 路 liefert den Klang: 路 ロ → 蕗 ロ. Das Zeichen steht für den Pestwurz (Fuki).","s":1,"p":[["艹","Pflanze","b"],["路","Weg","l"]]},
"丙":{"t":"leih","x":"Ursprünglich wohl das Bild eines Sockels oder einer kleinen Ablage. Dieses Zeichen wurde früh für den dritten Himmelsstamm ausgeliehen. Heute steht es auch für „der Dritte“.","s":1,"n":"Es gibt mehrere Deutungen: Schultern, Fischschwanz oder ein Teil eines Wagens. Die ursprüngliche Bedeutung ist verloren.","i":"obs"},
"碧":{"t":"laut","x":"石 (Stein) zeigt den Sinnbereich: ein blaugrüner Edelstein. Der obere Teil 珀 trägt den Klang. Daraus wurde die Farbe „blaugrün“.","s":1,"p":[["珀","Bernstein","l"],["石","Stein","b"]]},
"甫":{"t":"unklar","x":"Die Herkunft ist umstritten. Ein Teil der Forschung sieht eine Hand mit Seil, die etwas fängt; ein anderer sieht zwei Pflanzen auf einem Feld, also einen Garten. Später dient das Zeichen für „eben erst“.","s":0,"n":"Die ältere Deutung „Pflanze über Feld“ gehört nach der japanischen Fachquelle zu einem anderen Zeichen, 圃.","i":"obs"},
"倣":{"t":"laut","x":"亻 (Mensch) gibt den Sinnbereich an: Menschen tun etwas nach. 放 liefert den Klang: 放 ホウ → 倣 ホウ. Gemeint ist „nachahmen“.","s":2,"p":[["亻","Mensch","b"],["放","loslassen","l"]]},
"朋":{"t":"bild","x":"Zwei Schnüre mit aufgereihten Kaurimuscheln: eine alte Geld-Einheit. Daraus wurde die Bedeutung „Gefährte, Freund“. Die beiden Schnüre haben sich später zu zwei 月 verändert.","s":1,"n":"Eine zweite Deutung sieht 朋 als Lautzeichen: 人 plus 玨, einer Muschelschnur. Einigkeit herrscht nicht.","i":"obs"},
"鳳":{"t":"laut","x":"Das Zeichen zeigte zuerst einen Vogel mit Federschopf und langen Schwanzfedern. Später kam 凡 als Lautteil dazu. Gemeint ist der Fenghuang, der mythische Vogel; wohl nach dem Pfau.","s":2,"p":[["几","Lautteil (凡)","l"],["鳥","Vogel","b"]],"n":"In alter Zeit wurde das Zeichen auch für „Wind“ (風) ausgeliehen.","i":"obs"},
"鵬":{"t":"laut","x":"鳥 (Vogel) gibt den Sinnbereich an, 朋 den Klang: 朋 ホウ → 鵬 ホウ. Das Zeichen steht für den Riesenvogel der Sage.","s":2,"p":[["朋","Freund","l"],["鳥","Vogel","b"]],"n":"Möglicherweise ist es eine alte Form von 鳳."},
"槙":{"t":"laut","x":"木 (Baum) zeigt den Sinnbereich, 真 den Klang. Das Zeichen bezeichnet eine immergrüne Baumart (Steineibe). Die Form 槇 ist die Variante mit alter Schreibung von 眞.","s":1,"p":[["木","Baum","b"],["真","wahr","l"]]},
"柾":{"t":"kombi","x":"木 (Holz) und 正 (gerade, richtig): Holz mit geradem Verlauf der Maserung. Das Zeichen wurde in Japan geschaffen.","s":1,"p":[["木","Baum","b"],["正","gerade","b"]]},
"亦":{"t":"zeichen","x":"Ein stehender Mensch (大) mit zwei Punkten unter den Armen, die die Achselhöhlen markieren: das ursprüngliche Zeichen für „Achsel“. Später wurde es für „auch, ebenfalls“ ausgeliehen.","s":2,"p":[["大","Mensch","b"]],"i":"obs"},
"繭":{"t":"kombi","x":"Ein Zeichen für den Kokon. Das frühere Bild zeigte eine Seidenraupe, die sich wie ein Vorhang in Fäden hüllt. Später wurden Seide (糸) und Insekt (虫) kombiniert.","s":1,"p":[["糸","Seide","b"],["虫","Raupe","b"],["黹","Stickerei (verkürzt)","f"]],"i":"s"},
"麿":{"t":"kurz","x":"Ein in Japan geschaffenes Zeichen: eine Zusammenziehung von 麻 und 呂, den beiden Silben des Namens Maro. Es wird vor allem in Namen verwendet.","s":2,"p":[["麻","Hanf (ま)","l"],["呂","ろ","l"]]},
"巳":{"t":"leih","x":"Das Zeichen hat sich vom Zeichen für „Kind“ (子) abgespalten. Es wurde für das sechste Tierkreiszeichen (Schlange) ausgeliehen. Was es ursprünglich zeigte, ist nicht gesichert.","s":1,"n":"Verbreitet ist die Deutung „Schlange“ oder „Fötus“.","i":"obs"},
"稔":{"t":"laut","x":"禾 (Getreide) gibt den Sinnbereich an, 念 den Klang: 念 ネン → 稔 ネン. Gemeint ist das Reifen des Getreides, die Ernte.","s":1,"p":[["禾","Getreide","b"],["念","Gedanke","l"]]},
"椋":{"t":"laut","x":"木 (Baum) gibt den Sinnbereich an: eine Baumart. 京 liefert den Klang. Das Zeichen steht heute für eine bestimmte Baumart und für den Star.","s":1,"p":[["木","Baum","b"],["京","Hauptstadt","l"]],"i":"s"},
"孟":{"t":"laut","x":"子 (Kind) steht für den Sinnbereich, 皿 (Schale) liefert den Klang. Gemeint ist das älteste Kind, daher „Anfang, erster“.","s":2,"p":[["子","Kind","b"],["皿","Schale","l"]],"i":"s"},
"耗":{"t":"laut","x":"耒 (Pflug) bezieht sich auf Feldarbeit. 毛 liefert den Klang: 毛 モウ → 耗 モウ. Daraus wurde „abnehmen, verbrauchen“.","s":2,"p":[["耒","Pflug","b"],["毛","Haar","l"]],"n":"Früher wurde 毛 auch als Bedeutungsträger gedeutet. Die Fachquelle hält das für falsch."},
"匁":{"t":"kurz","x":"Das Zeichen ist eine Kurzform von 錢 (Geld), das in Japan zur Gewichtseinheit Monme wurde. Aus dem Teil 戔 entstand die heutige Form. Mit 文 und メ hat es nichts zu tun.","s":2,"n":"Oft liest man, es sei eine Verbindung aus 文 und メ. Die Fachquelle hält das für falsch."},
"冶":{"t":"kombi","x":"Ursprünglich Metallbarren, ein Löffel (刀) und eine Dekoration (口): Metall wird geschmolzen und gegossen. Die Barren wurden zu 冫; 刀 und 口 verschmolzen zu 台, das auch als Klang dient.","s":2,"p":[["冫","Barren","b"],["台","Gießform (Lautteil)","l"]],"i":"bs"},
"耶":{"t":"kurz","x":"Das Zeichen ist eine Nebenform von 邪. Es wird in Namen und als Fragepartikel verwendet. Ein erklärbarer Aufbau fehlt.","s":1,"p":[["耳","Ohr","f"],["阝","Hügel/Ort","f"]]},
"佑":{"t":"laut","x":"亻 (Mensch) zeigt den Sinnbereich: jemand hilft. 右 liefert den Klang (ウ/ユウ). Gemeint ist „helfen, beistehen“.","s":2,"p":[["亻","Mensch","b"],["右","rechts","l"]]},
"宥":{"t":"laut","x":"宀 (Dach, Haus) gibt den Sinnbereich an, 有 den Klang: 有 ユウ → 宥 ユウ. Daraus wurde „besänftigen, nachsichtig sein“.","s":1,"p":[["宀","Dach","b"],["有","haben","l"]],"i":"s"},
"柚":{"t":"laut","x":"木 (Baum) zeigt, dass es um ein Gewächs geht; 由 (ユ, ユウ) liefert den Klang. Gemeint ist ein Zitrusbaum, die Zitrone bzw. Yuzu.","s":1,"p":[["木","Baum","b"],["由","Ursprung","l"]],"i":"o"},
"祐":{"t":"laut","x":"礻 steht für Geistwesen und Opfer, der Sinnteil für Beistand von höherer Seite. 右 (ウ, ユウ) gibt den Klang. Die Bedeutung ist „helfen, beistehen“.","s":2,"p":[["礻","Geist, Kult","b"],["右","rechts","l"]],"n":"Eine ältere Lesart sah in 右 (rechte Hand) auch einen Bedeutungsteil. Das gilt heute als falsch: 右 ist nur der Klangteil.","i":"obs"},
"邑":{"t":"kombi","x":"Oben ein umgrenztes Gebiet, darunter ein kniender Mensch: ein Ort, an dem Menschen siedeln. Daraus wurde „Stadt, Dorf“. Im Japanischen steht das Zeichen als Bauteil rechts oft als 阝.","s":2,"p":[["囗","Mauer, Gebiet","b"],["卩","Kniender","b"]],"n":"Der untere Teil hat nichts mit 巴 zu tun, auch wenn er heute so aussieht.","i":"obs"},
"楊":{"t":"laut","x":"木 (Baum) zeigt die Pflanzengruppe, 昜 (ヨウ) den Klang. Gemeint ist die Weide, eine Baumart.","s":2,"p":[["木","Baum","b"],["昜","Sonne, Aufstieg","l"]],"i":"bs"},
"窯":{"t":"laut","x":"穴 (Loch, Höhlung) deutet den Brennraum an, in dem Keramik gebrannt wird: der Brennofen. 羔 gibt den Klang.","s":2,"p":[["穴","Höhle, Loch","b"],["羔","Lamm","l"]]},
"耀":{"t":"laut","x":"光 (Licht) gibt den Sinn „strahlen, glänzen“, 翟 (ヨウ im Klang ähnlich) den Klang. Dasselbe Klangteil steckt in 燿.","s":2,"p":[["光","Licht","b"],["翟","Fasan","l"]]},
"蓉":{"t":"laut","x":"艹 (Pflanze) zeigt, dass es um ein Gewächs geht, 容 (ヨウ) liefert den Klang. Gemeint ist die Lotosblume.","s":2,"p":[["艹","Pflanze","b"],["容","Aussehen","l"]]},
"濫":{"t":"laut","x":"氵 (Wasser) bezieht sich auf Wasser, das über die Ufer tritt. 監 gibt den Klang (heute カン, früher dem ラン nahe). Daraus: „überfließen, maßlos“.","s":2,"p":[["氵","Wasser","b"],["監","überwachen","l"]]},
"蘭":{"t":"laut","x":"艹 (Pflanze) zeigt das Gewächs, 闌 (ラン) den Klang. Gemeint ist die Orchidee.","s":1,"p":[["艹","Pflanze","b"],["闌","Schranke","l"]],"i":"s"},
"吏":{"t":"unklar","x":"Ursprünglich war das Zeichen eine Nebenform von 史 und 事; in den frühesten Schriftzeugnissen werden sie nicht immer unterschieden. Vermutlich zeigt es eine Hand, die ein Zeichen hält: ein Beauftragter, daher „Beamter“.","s":0,"i":"bs"},
"李":{"t":"laut","x":"In den alten Formen gehört zu 子 ein Klangteil 來 (ein Getreidename, Klang ライ), der später zu 木 verformt wurde. Die ursprüngliche Bedeutung ist unsicher; das Wort wurde für die Pflaume genutzt.","s":1,"p":[["木","Baum","f"],["子","Kind","b"]],"n":"Oft liest man „Baum + Kind“. Die alten Formen sprechen dagegen: Das 木 ist ein verformter Klangteil.","i":"bs"},
"琉":{"t":"laut","x":"𤣩 ist 玉 (Jade) in Bauteilform und steht für Edelstein. 㐬 gibt den Klang (wie in 流 リュウ). Gemeint ist ein Edelstein, etwa Lapislazuli.","s":1,"p":[["𤣩","Jade","b"],["㐬","Klangteil","l"]]},
"稜":{"t":"laut","x":"夌 gibt den Klang (リョウ, wie in 陵), 禾 steht als Sinnteil. Die Bedeutung hat sich zu „Kante, Ecke“ entwickelt; wie genau, ist aus den Quellen nicht klar.","s":1,"p":[["禾","Getreide","b"],["夌","Hügel","l"]]},
"厘":{"t":"laut","x":"Kurzform von 釐, bei der der obere Teil weggelassen wurde. Die alte Form besteht aus zwei Klangteilen (𠩺 und 里, beide ähnlich lautend) und hieß „ordnen“. In Japan wird das Zeichen für eine kleine Maßeinheit verwendet.","s":1,"p":[["厂","Rest von 釐","f"],["里","Dorf","l"]],"a":"釐","i":"obs"},
"琳":{"t":"laut","x":"𤣩 ist 玉 (Jade) in Bauteilform und steht für Edelstein. 林 (リン) gibt den Klang. Gemeint ist ein schöner Edelstein.","s":1,"p":[["𤣩","Jade","b"],["林","Wald","l"]],"i":"s"},
"麟":{"t":"laut","x":"鹿 (Hirsch) zeigt das Tier an, 粦 (リン) den Klang. Gemeint ist das Qilin, ein Fabeltier mit Hirschgestalt.","s":2,"p":[["鹿","Hirsch","b"],["粦","Klangteil","l"]],"i":"os"},
"伶":{"t":"laut","x":"亻 (Mensch) für eine Person, 令 (レイ) für den Klang. Gemeint ist ein Schauspieler oder Musiker.","s":2,"p":[["亻","Mensch","b"],["令","Befehl","l"]],"i":"s"},
"嶺":{"t":"laut","x":"山 (Berg) zeigt den Sinn, 領 (リョウ) gibt den Klang. Das Zeichen bedeutet „Bergkamm, Gipfel“.","s":2,"p":[["山","Berg","b"],["領","Gebiet","l"]]},
"怜":{"t":"laut","x":"忄 steht für Herz und Verstand, 令 (レイ) gibt den Klang. Gemeint ist ein klarer, kluger Geist.","s":2,"p":[["忄","Herz, Geist","b"],["令","Befehl","l"]],"n":"Früher las man 令 auch als Bedeutungsteil. Das gilt als falsch: 令 ist nur Klangteil."},
"玲":{"t":"laut","x":"𤣩 ist 玉 (Jade) in Bauteilform, 令 (レイ) gibt den Klang. Das Zeichen bezeichnet das Klingen von Jade, einen hellen Ton.","s":2,"p":[["𤣩","Jade","b"],["令","Befehl","l"]],"i":"s"},
"楼":{"t":"laut","x":"Die alte Form 樓 hat 木 (Holz, Baum) als Sinnteil und 婁 (ロウ) als Klangteil. Das heutige 娄 ist eine Kurzform von 婁 aus der Schreibschrift. Gemeint ist ein hohes Holzgebäude.","s":2,"p":[["木","Holz, Baum","b"],["娄","Klangteil","l"]],"a":"樓"},
"禄":{"t":"laut","x":"Die alte Form 祿 besteht aus 示 (Geist, Kult) als Sinnteil und 彔 (ロク) als Klangteil. Heute steht 礻 für 示 und 录 für 彔. Die Bedeutung ist „Segen, Gehalt“.","s":2,"p":[["礻","Geist, Kult","b"],["录","Klangteil","l"]],"a":"祿"},
"倭":{"t":"laut","x":"亻 steht für Mensch, 委 gibt den Klang (イ, ワ). Das Zeichen bezeichnete in alter Zeit das Volk von Japan und wurde zum Namen für das Land.","s":2,"p":[["亻","Mensch","b"],["委","anvertrauen","l"]]},
"亘":{"t":"bild","x":"Das Zeichen zeigte ursprünglich ein Wirbel- oder Spiralmuster, ähnlich der alten Form 囘. Später wurde es für „sich erstrecken, quer hinüberreichen“ verwendet. Im Japanischen ist es auch eine Kurzform von 亙.","s":1,"i":"obs"},
"侑":{"t":"laut","x":"亻 (Mensch) steht für eine Person, 有 (ユウ) gibt den Klang. Die Bedeutung ist „jemanden zum Essen oder Trinken nötigen, ermuntern“.","s":2,"p":[["亻","Mensch","b"],["有","haben","l"]]},
"勁":{"t":"laut","x":"力 (Kraft) gibt den Sinn „stark“, 巠 (ケイ) den Klang.","s":2,"p":[["巠","Klangteil","l"],["力","Kraft","b"]],"i":"s"},
"奎":{"t":"laut","x":"大 steht für groß und stattlich, 圭 (ケイ) gibt den Klang. Das Zeichen bezeichnet ein Sternbild.","s":2,"p":[["大","groß","b"],["圭","Jadetafel","l"]],"n":"Das 土 in 圭 wirkt wie „Erde“, war ursprünglich aber nur die Form zweier Zeremonialbeile; die Erde-Deutung ist später entstanden."},
"崚":{"t":"laut","x":"山 (Berg) zeigt den Sinn, 夌 (リョウ) den Klang. Gemeint sind steil aufragende, aneinandergereihte Berge.","s":1,"p":[["山","Berg","b"],["夌","Hügel","l"]]},
"彗":{"t":"kombi","x":"Ursprünglich ein Bild eines Besens, dem später 又 (rechte Hand) hinzugefügt wurde: eine Hand, die einen Besen hält. Das Zeichen bedeutet Besen.","s":2,"p":[["丰丰","Besen","b"],["⺕","Hand","b"]],"i":"os"},
"昴":{"t":"laut","x":"日 (Sonne, Gestirn) zeigt den Sinn, 卯 (ボウ) gibt den Klang. Das Zeichen benennt die Plejaden, ein Sternhaufen.","s":1,"p":[["日","Sonne, Gestirn","b"],["卯","Hase","l"]]},
"晏":{"t":"laut","x":"日 (Sonne) bezieht sich auf die Tageszeit, 安 (アン) gibt den Klang. Gemeint ist die späte, ruhige Zeit des Tages.","s":2,"p":[["日","Sonne","b"],["安","ruhig","l"]]},
"晨":{"t":"laut","x":"日 (Sonne) nennt den Tageszeitbezug, 辰 (シン) den Klang. Das Zeichen bedeutet „Morgen“.","s":2,"p":[["日","Sonne","b"],["辰","Zeit","l"]],"n":"辰 stand ursprünglich allein für dieses Wort und wird heute vor allem für das Tierkreiszeichen verwendet."},
"晟":{"t":"laut","x":"日 (Sonne) für Helligkeit, 成 (セイ) für den Klang. Gemeint ist: hell, klar.","s":1,"p":[["日","Sonne","b"],["成","werden","l"]],"i":"s"},
"暉":{"t":"laut","x":"日 (Sonne) zeigt den Sinn „Sonnenlicht, Glanz“, 軍 gibt den Klang (heute グン, in alter Zeit dem Wort näher).","s":2,"p":[["日","Sonne","b"],["軍","Heer","l"]],"i":"s"},
"椰":{"t":"laut","x":"木 (Baum) zeigt eine Baumart, 耶 (ヤ) den Klang. Gemeint ist die Kokospalme.","s":1,"p":[["木","Baum","b"],["耶","Klangteil","l"]]},
"毬":{"t":"laut","x":"毛 (Haar, Fell) bezieht sich auf einen Ball aus Fell oder Haar, 求 (キュウ) gibt den Klang. Das Zeichen bedeutet Ball.","s":1,"p":[["毛","Haar, Fell","b"],["求","suchen","l"]],"i":"s"},
"洸":{"t":"laut","x":"氵 (Wasser) für Wasser, 光 (コウ) gibt den Klang. Das Zeichen beschreibt glitzerndes Wasser.","s":2,"p":[["氵","Wasser","b"],["光","Licht","l"]],"i":"s"},
"洵":{"t":"laut","x":"氵 (Wasser) und 旬 (ジュン) als Klangteil. Das Zeichen war ursprünglich ein Gewässername; die heutige Bedeutung „wahrhaftig“ kam später.","s":1,"p":[["氵","Wasser","b"],["旬","zehn Tage","l"]],"i":"s"},
"滉":{"t":"laut","x":"氵 (Wasser) zeigt den Sinn, 晃 (コウ) den Klang. Gemeint ist weites, tiefes Wasser.","s":2,"p":[["氵","Wasser","b"],["晃","glänzen","l"]]},
"漱":{"t":"laut","x":"氵 (Wasser) für das Spülen, 欶 (ソウ) für den Klang. Das Zeichen bedeutet „den Mund ausspülen“.","s":1,"p":[["氵","Wasser","b"],["欶","Klangteil","l"]]},
"澪":{"t":"laut","x":"氵 (Wasser) steht für Wasserweg, 零 (レイ) gibt den Klang. In China ist das Zeichen fast nur ein Flussname; in Japan wurde es für die Fahrrinne genutzt.","s":1,"p":[["氵","Wasser","b"],["零","Null, Tropfen","l"]]},
"燎":{"t":"laut","x":"火 (Feuer) für das Brennen, 尞 (リョウ) für den Klang. Ursprünglich schrieb 尞 allein dieses Wort; 火 wurde später links zur Verdeutlichung ergänzt.","s":2,"p":[["火","Feuer","b"],["尞","Klangteil","l"]]},
"燿":{"t":"laut","x":"火 (Feuer) für Licht und Glanz, 翟 (ヨウ im Klang ähnlich) für den Klang. Das Zeichen bedeutet „leuchten, glänzen“.","s":2,"p":[["火","Feuer","b"],["翟","Fasan","l"]],"i":"s"},
"瑶":{"t":"laut","x":"𤣩 ist 玉 (Jade) in Bauteilform und zeigt Edelstein, 䍃 gibt den Klang (ヨウ). Gemeint ist ein schöner Stein.","s":1,"p":[["𤣩","Jade","b"],["䍃","Klangteil","l"]]},
"皓":{"t":"laut","x":"白 (weiß) gibt den Sinn, 告 (コク; im Klang ähnlich コウ) den Klang. Das Zeichen bedeutet „weiß, hell“.","s":2,"p":[["白","weiß","b"],["告","mitteilen","l"]]},
"眸":{"t":"laut","x":"目 (Auge) zeigt den Sinn, 牟 (ボウ, ム) gibt den Klang. Das Zeichen bezeichnet die Pupille.","s":2,"p":[["目","Auge","b"],["牟","Klangteil","l"]]},
"笙":{"t":"laut","x":"竹 (Bambus) zeigt das Material des Instruments, 生 (ショウ) den Klang. Gemeint ist die Mundorgel, ein Blasinstrument aus Bambusrohren.","s":2,"p":[["竹","Bambus","b"],["生","Leben","l"]]},
"綸":{"t":"laut","x":"糹 (Seidenfaden) steht für Faden und Stoff, 侖 (リン) gibt den Klang. Das Zeichen bezeichnet einen Seidenfaden.","s":2,"p":[["糹","Seide","b"],["侖","Klangteil","l"]]},
"脩":{"t":"laut","x":"月 steht hier für Fleisch (肉), 攸 gibt den Klang (ユウ → シュウ, ähnlich). Gemeint ist Trockenfleisch.","s":2,"p":[["攸","Klangteil","l"],["月","Fleisch","b"]]},
"茉":{"t":"laut","x":"艹 (Pflanze) für ein Gewächs, 末 (マツ) für den Klang. Gemeint ist der Jasmin.","s":2,"p":[["艹","Pflanze","b"],["末","Ende","l"]]},
"菫":{"t":"kurz","x":"Das Zeichen ist aus 堇 entstanden, dessen oberer Teil durch den Einfluss von 艹 (Pflanze) verändert wurde. Die ursprüngliche Form war 蓳. Das Zeichen bezeichnet das Veilchen.","s":1},
"詢":{"t":"laut","x":"訁 (Sprache) für Rede und Frage, 旬 (ジュン) für den Klang. Das Zeichen bedeutet „befragen, um Rat bitten“.","s":2,"p":[["訁","Wort, Sprache","b"],["旬","zehn Tage","l"]],"i":"s"},
"諄":{"t":"laut","x":"訁 (Sprache) für Rede, ein Klangteil (hier als 享 geschrieben, alt 𦎧) für den Klang (シュン). Gemeint ist eindringliches, ausführliches Reden.","s":1,"p":[["訁","Wort, Sprache","b"],["享","Klangteil","l"]]},
"赳":{"t":"laut","x":"走 (laufen) steht für Bewegung, 丩 (キュウ) gibt den Klang. Das Zeichen bedeutet „kräftig, tapfer“.","s":1,"p":[["走","laufen","b"],["丩","Klangteil","l"]],"i":"s"},
"迪":{"t":"laut","x":"辶 (gehen, Weg) gibt den Sinn „Weg“, 由 den Klang. Die heutige Lesung テキ klingt dem Klangteil nicht mehr ähnlich. Das Wort bedeutet „Weg“, übertragen „anleiten“.","s":1,"p":[["辶","Weg, gehen","b"],["由","Ursprung","l"]]},
"頌":{"t":"laut","x":"頁 (Kopf, Gesicht) als Sinnteil, 公 als Klangteil. Ursprünglich war das Wort „Aussehen“ (heute 容 geschrieben); das Zeichen wurde dann für „Lobgesang“ ausgeliehen.","s":2,"p":[["公","öffentlich","l"],["頁","Kopf, Gesicht","b"]]},
"黎":{"t":"laut","x":"黍 (Hirse) ist der Sinnteil, in der heutigen Form verkürzt, 利 (リ) gibt den Klang. Die heutigen Bedeutungen wie „dunkel“ und „viele“ sind aus dieser Grundlage ausgeliehen.","s":1,"p":[["黍","Hirse","b"],["利","Vorteil","l"]]},
"凜":{"t":"laut","x":"冫 (Eis) steht für Kälte, 稟 (リン) gibt den Klang. Das Zeichen bedeutet „kalt, streng“.","s":2,"p":[["冫","Eis","b"],["稟","Klangteil","l"]],"n":"Oft liest man „Eis berührt, man strafft sich“ oder „Vorrat sammeln“. Das ist zurechtgelegt: 稟 liefert nur den Klang.","i":"s"},
"熙":{"t":"laut","x":"灬 (Feuer) steht für Wärme und Licht, 巸 gibt den Klang. Das Zeichen bedeutet „hell, strahlend“.","s":1,"p":[["巸","Klangteil","l"],["灬","Feuer","b"]],"i":"bs"}
};
